['Here's a C implementation that fulfills your requirements using a linked list with thread safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

typedef struct {
    Record* head;
    pthread_mutex_t lock;
} RecordList;

// Initialize the record list with thread safety
void initRecordList(RecordList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Insert a new record into the list
int insertRecord(RecordList* list, int key, long offset) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return -1; // Allocation failed

    new_record->key = key;
    new_record->offset = offset;

    pthread_mutex_lock(&list->lock);

    new_record->next = list->head;
    list->head = new_record;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Delete a record by key
int deleteRecord(RecordList* list, int key) {
    Record *prev = NULL, *current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Record not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Query a record by key
long queryRecord(RecordList* list, int key) {
    Record* current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current != NULL && current->key != key) {
        current = current->next;
    }

    long offset = (current != NULL) ? current->offset : -1;

    pthread_mutex_unlock(&list->lock);
    return offset;
}

// Free all records in the list
void freeRecordList(RecordList* list) {
    Record *current, *next;

    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Function to handle external data sources and updates
void updateFromExternalSource(RecordList* list, const char* data) {
    // Parse and validate incoming data format
    // For simplicity, assume data is in the format "key:offset;"
    char* token = strtok((char*)data, ";");
    while (token != NULL) {
        int key;
        long offset;

        if (sscanf(token, "%d:%ld", &key, &offset) == 2) {
            deleteRecord(list, key); // Ensure no duplicate keys
            insertRecord(list, key, offset);
        }

        token = strtok(NULL, ";");
    }
}

// Example usage
int main() {
    RecordList list;
    initRecordList(&list);

    updateFromExternalSource(&list, "1:100;2:200;3:300;");

    printf("Offset for key 2: %ld\n", queryRecord(&list, 2));

    deleteRecord(&list, 2);
    freeRecordList(&list);

    return 0;
}
```

This code defines a `Record` structure and a `RecordList` to manage the list with thread safety using a mutex. It includes functions for initialization, insertion, deletion, querying, freeing resources, and updating from an external data source. The example usage demonstrates how to use these functions.']

