#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <arpa/inet.h>  // For inet_ntop

#define MAX_HOSTNAME_LENGTH 256
#define DNS_CACHE_SIZE 100

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    unsigned char ip[4];  // Assuming IPv4 for simplicity
} dns_cache_entry;

dns_cache_entry dns_cache[DNS_CACHE_SIZE];
int cache_index = 0;

int resolve_dns(const char *hostname, unsigned char *ip_address) {
    struct hostent *host_info;
    int result;

    if (strlen(hostname) >= MAX_HOSTNAME_LENGTH) return -1; // Error: Hostname too long

    for (int i = 0; i < DNS_CACHE_SIZE; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            memcpy(ip_address, dns_cache[i].ip, sizeof(unsigned char[4]));
            return 0;
        }
    }

    host_info = gethostbyname(hostname);
    if (host_info == NULL) {
        herror("DNS resolution");
        return -1; // Error: DNS resolution failed
    }

    memcpy(ip_address, host_info->h_addr_list[0], sizeof(unsigned char[4]));

    strcpy(dns_cache[cache_index % DNS_CACHE_SIZE].hostname, hostname);
    memcpy(dns_cache[cache_index % DNS_CACHE_SIZE].ip, ip_address, sizeof(unsigned char[4]));
    cache_index++;

    return 0;
}

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char *token;
        int fields_count = 0;
        double sum = 0.0;

        token = strtok(line, ",\n");
        while (token) {
            fields_count++;
            if (fields_count >= 2 && fields_count == (fields_count + 1) - 2) {
                sum += atof(token);
            }
            token = strtok(NULL, ",\n");
        }

        double average = sum / 2;
        printf("%s%f\n", line, average);  // Print with added average
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_file(argv[1]);

    return EXIT_SUCCESS;
}
