#define MAX_NUMBERS 1000000

int findLargestInteger() {
    int *numbers = NULL;
    size_t count = 0;
    int value, largest = INT_MIN;
    char buffer[12]; // To handle potential overflow and validate input
    int result;

    printf("Enter integers (EOF to end):\n");

    while (1) {
        if (fgets(buffer, sizeof(buffer), stdin) == NULL) break; // Read line

        result = sscanf(buffer, "%d", &value);

        if (result != 1) { // Not an integer
            fprintf(stderr, "Invalid input detected. Please enter integers only.\n");
            continue;
        }

        if (count >= MAX_NUMBERS) {
            fprintf(stderr, "Maximum number of inputs reached.\n");
            break;
        }

        numbers = realloc(numbers, sizeof(int) * (count + 1));
        if (!numbers) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        numbers[count++] = value;

        if (value > largest) {
            largest = value;
        }
    }

    free(numbers);

    return largest;
}

int main() {
    int largest = findLargestInteger();
    printf("The largest integer is: %d\n", largest);
    return 0;
}
