// Main class for generating the report
public class PokemonReportGenerator {

    private static final Logger logger = Logger.getLogger(PokemonReportGenerator.class.getName());

    // Caches to improve performance
    private final Cache<Pokemon, String> nameCache = new Cache<>(100);
    private final Cache<Pokemon, String> typeCache = new Cache<>(100);

    private final WeaknessConfigLoader configLoader = new WeaknessConfigLoader();

    public String generatePokemonReport(Pokemon pokemon) {
        try {
            String name = getName(pokemon);
            String type = getType(pokemon);

            if (type == null || type.isEmpty()) {
                type = "Normal"; // Default most common type
            }

            List<String> weaknesses = configLoader.getWeaknessesForType(type);

            return String.format("Pokemon Report:\nName: %s\nType: %s\nWeaknesses: %s",
                    name, type, String.join(", ", weaknesses));
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error generating Pokemon report", e);
            return "Failed to generate Pokemon report.";
        }
    }

    private synchronized String getName(Pokemon pokemon) {
        String cachedName = nameCache.get(pokemon);
        if (cachedName != null) {
            return cachedName;
        }

        Optional<String> nameOpt = PokemonNameLibrary.getPokemonName(pokemon);
        String name = nameOpt.orElse("Unknown"); // Default fallback
        nameCache.put(pokemon, name);

        return name;
    }

    private synchronized String getType(Pokemon pokemon) {
        String cachedType = typeCache.get(pokemon);
        if (cachedType != null) {
            return cachedType;
        }

        Optional<String> typeOpt = PokemonTypeLibrary.getPokemonType(pokemon);
        String type = typeOpt.orElse(null); // Gracefully handle nulls
        typeCache.put(pokemon, type);

        return type;
    }

    public static void main(String[] args) {
        Pokemon pikachu = new Pokemon("Pikachu", "Electric");
        PokemonReportGenerator generator = new PokemonReportGenerator();

        System.out.println(generator.generatePokemonReport(pikachu));
    }
}

