#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <curl/curl.h>

#define MAX_CONCURRENT_OPERATIONS 5
#define CACHE_EXPIRATION_TIME (24 * 60 * 60) // 24 hours in seconds

typedef struct {
    char **data;
    size_t length;
} Cache;

typedef enum { SYNC, ASYNC } ExecutionMode;

typedef void (*Callback)(const char *result);

static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;
static int active_requests = 0;
static Cache hash_caches = {.data = NULL, .length = 0};
static Cache cipher_caches = {.data = NULL, .length = 0};

typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *) userp;

    char *ptr = realloc(mem->memory, mem->size + real_size + 1);
    if (!ptr) {
        // Handle memory allocation error
        printf("Not enough memory\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, real_size);
    mem->size += real_size;
    mem->memory[mem->size] = '\0';

    return real_size;
}

static int is_cache_valid(const char *cache_timestamp) {
    time_t current_time = time(NULL);
    struct tm tm;
    strptime(cache_timestamp, "%Y-%m-%dT%H:%M:%SZ", &tm);
    time_t cache_time = mktime(&tm);

    return difftime(current_time, cache_time) < CACHE_EXPIRATION_TIME;
}

static void fetch_algorithms(const char *url, MemoryStruct *chunk, ExecutionMode mode, Callback callback) {
    CURL *curl_handle;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_ALL);
    curl_handle = curl_easy_init();

    if (curl_handle) {
        curl_easy_setopt(curl_handle, CURLOPT_URL, url);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)chunk);

        pthread_mutex_lock(&cache_lock);
        active_requests++;
        while (active_requests > MAX_CONCURRENT_OPERATIONS) {
            pthread_cond_wait(&cond_var, &cache_lock);
        }
        pthread_mutex_unlock(&cache_lock);

        res = curl_easy_perform(curl_handle);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        pthread_mutex_lock(&cache_lock);
        active_requests--;
        pthread_cond_signal(&cond_var);
        pthread_mutex_unlock(&cache_lock);

        curl_easy_cleanup(curl_handle);
    }
    curl_global_cleanup();

    if (mode == ASYNC && callback) {
        char *result = chunk->memory;
        callback(result);
    } else if (mode == SYNC) {
        return chunk->memory;
    }

    free(chunk->memory);
}

void update_cache(const char *url, Cache *cache, const char **key, ExecutionMode mode, Callback callback) {
    static pthread_mutex_t update_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&update_lock);

    MemoryStruct chunk = { .memory = malloc(1), .size = 0 };

    if (!chunk.memory) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }

    fetch_algorithms(url, &chunk, mode, [callback](const char *result) {
        pthread_mutex_lock(&update_lock);

        // Simulate parsing and caching logic
        const char *cache_timestamp = "2023-10-01T00:00:00Z";  // Placeholder timestamp

        if (!is_cache_valid(cache_timestamp)) {
            if (callback) callback(result);
            // Update cache with new data
            cache->length = 0; // Reset length
            free(cache->data[0]); // Free old data
            cache->data[0] = strdup(result); // Store new result
            cache->length = 1;
        }

        pthread_mutex_unlock(&update_lock);
    });

    pthread_mutex_unlock(&update_lock);

    if (mode == SYNC) {
        free(chunk.memory);
    }
}

void get_algorithms(ExecutionMode mode, Callback callback) {
