fn load_config(config_path: &Path) -> Result<HashSet<PathBuf>, String> {
    // Simulating reading a config file to get included files.
    let content = fs::read_to_string(config_path).map_err(|e| e.to_string())?;
    Ok(HashSet::from([PathBuf::from("file1.rs"), PathBuf::from("file2.rs")])) // Dummy content
}

fn is_valid_source_file(file: &Path) -> bool {
    file.extension().map_or(false, |ext| ext == "rs")
}

fn process_file(
    cache: Arc<Mutex<HashMap<PathBuf, String>>>,
    config_files: Arc<HashSet<PathBuf>>,
    file_path: PathBuf,
) -> Result<String, String> {
    let mut cache = cache.lock().unwrap();

    if let Some(ir) = cache.get(&file_path) {
        println!("Cache hit for {:?}", file_path);
        return Ok(ir.clone());
    }

    if !config_files.contains(&file_path) {
        println!("File {:?} is not in config, skipping.", file_path);
        return Err(format!("Config exclusion: {:?}", file_path));
    }

    let source = fs::read_to_string(&file_path).map_err(|e| e.to_string())?;
    let lexer = Lexer::new(&source);

    match lexer.tokenize() {
        Ok(tokens) => {
            let parsed_nodes = Parser::parse(tokens)?;
            println!("Parsed nodes for {:?}: {:?}", file_path, parsed_nodes);

            match LLVMAPI::generate_ir(&parsed_nodes) {
                Ok(ir_code) => {
                    cache.insert(file_path.clone(), ir_code.clone());
                    println!("Generated LLVM IR for {:?}:", file_path);
                    println!("{}", ir_code);
                    Ok(ir_code)
                },
                Err(e) => Err(format!("LLVM generation failed for {:?}: {}", file_path, e)),
            }
        },
        Err(e) => Err(format!("Tokenization failed for {:?}: {}", file_path, e)),
    }
}

fn generate_llvm_ir_for_directory(dir: &Path) -> Result<(), String> {
    let config = load_config(Path::new("config.txt"))?;
    let cache = Arc::new(Mutex::new(HashMap::new()));
    let config_files = Arc::new(config);

    let paths: Vec<PathBuf> = fs::read_dir(dir)?
        .filter_map(Result::ok)
        .filter(|entry| is_valid_source_file(entry.path()))
        .map(|entry| entry.path())
        .collect();

    let mut handles = vec![];

    for path in paths {
        let cache_clone = Arc::clone(&cache);
        let config_files_clone = Arc::clone(&config_files);

        handles.push(thread::spawn(move || {
            match process_file(cache_clone, config_files_clone, path) {
                Ok(_) => println!("Successfully processed {:?}", path),
                Err(e) => eprintln!("Error processing {:?}: {}", path, e),
            }
        }));
    }

    for handle in handles {
        let _ = handle.join();
    }

    Ok(())
}

fn main() -> Result<(), String> {
    generate_llvm_ir_for_directory(Path::new("src"))
}
