#include <iostream>
#include <vector>
#include <mutex>

class CustomContainer {
public:
    std::vector<int> data;
    mutable std::mutex mtx;

    CustomContainer(size_t initial_size = 0) : data(initial_size, 0) {}

    void process(int target, int replacement);
};

void CustomContainer::process(int target, int replacement) {
    std::lock_guard<std::mutex> lock(mtx);

    // Locate the first occurrence of the target
    auto it = std::find(data.begin(), data.end(), target);

    if (it != data.end()) {
        // Replace the target with the replacement value
        *it = replacement;
    } else {
        // Append the replacement value at the end, check for overflow
        try {
            data.push_back(replacement);
        } catch (const std::bad_alloc&) {
            std::cerr << "Memory allocation failed while appending to container." << std::endl;
            // Handle memory allocation failure gracefully if needed
        }
    }
}

// Example usage
int main() {
    CustomContainer metrics(10000000);  // Initialize with a large size

    // Simulate processing with target and replacement values
    metrics.process(42, -1);

    return 0;
}
```

