        allocations_.insert(ptr);
        return ptr;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (allocations_.find(ptr) != allocations_.end()) {
            std::free(ptr);
            allocations_.erase(ptr);
        }
    }

private:
    std::mutex mutex_;
    std::set<void*> allocations_;
};

MemoryManager g_memory_manager;

// Retry mechanism with exponential backoff
bool sendRequestWithRetry(const std::string& url, int maxRetries = 5) {
    CURL* curl;
    CURLcode res;
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (!curl) return false;

    for (int attempt = 0; attempt < maxRetries; ++attempt) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());

        // Execute request
        res = curl_easy_perform(curl);

        if (res == CURLE_OK) {
            std::cout << "Request successful" << std::endl;
            curl_easy_cleanup(curl);
            return true;
        } else {
            std::this_thread::sleep_for(std::chrono::milliseconds(100 * (1 << attempt))); // Exponential backoff
            std::cerr << "Attempt " << attempt + 1 << " failed: " << curl_easy_strerror(res) << std::endl;
        }
    }

    curl_easy_cleanup(curl);
    return false;
}

// Thread-safe cache mechanism
class Cache {
public:
    void set(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = value;
    }

    bool get(const std::string& key, std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            value = it->second;
            return true;
        }
        return false;
    }

private:
    std::map<std::string, std::string> cache_;
    std::mutex mutex_;
};

// Main program logic
class MonitoringClient {
public:
    void start() {
        running_ = true;
        workerThread_ = std::thread(&MonitoringClient::workerLoop, this);
    }

    void stop() {
        running_.store(false);
        if (workerThread_.joinable()) {
            workerThread_.join();
        }
    }

private:
    void workerLoop() {
        while (running_) {
            std::string metrics = fetchMetrics();

            // Process and log the fetched metrics
            logMetrics(metrics);

            std::this_thread::sleep_for(std::chrono::seconds(10)); // Fetch every 10 seconds
        }
    }

    std::string fetchMetrics() {
        static const std::string url = "https://example.com/api/metrics";

        if (cache_.get(url, metrics_)) {
            return metrics_;
        } else {
            if (sendRequestWithRetry(url)) {
                cache_.set(url, metrics_);
                return metrics_;
            }
            return "Failed to fetch metrics.";
        }
    }

    void logMetrics(const std::string& metrics) {
        // Log metrics for diagnostics
        std::cout << "Logged Metrics: " << metrics << std::endl;
    }

    std::atomic<bool> running_{false};
    std::thread workerThread_;
    Cache cache_;
    std::string metrics_;
};

int main() {
    MonitoringClient client;
    client.start();

    // Simulate application runtime
    std::this_thread::sleep_for(std::chrono::minutes(1));

    client.stop();
    return 0;
}
