#include <memory>

namespace LoggingSystem {

enum class LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR
};

class Logger {
public:
    static Logger& getInstance() {
        static Logger instance;
        return instance;
    }

    Logger(const Logger&) = delete;
    void operator=(const Logger&) = delete;

    ~Logger();

    void log(LogLevel level, const std::string& message);
    void adjustThreadPoolSize(int new_size);

private:
    Logger();
    void workerThread();
    void compressAndSendLogs(std::vector<std::pair<LogLevel, std::string>> logs);

    static std::mutex instanceMutex;
    static std::condition_variable cv;
    static std::atomic<bool> running;

    int minThreads = 2;
    int maxThreads = 16;
    int currentThreads = 4;

    std::vector<std::thread> workers;
    std::queue<std::pair<LogLevel, std::string>> logQueue;
    std::mutex queueMutex;

    std::atomic<int> pendingLogs{0};
    std::map<LogLevel, std::function<void(const std::string&)>> handlers;

    void setupHandlers();
};

std::mutex Logger::instanceMutex;
std::condition_variable Logger::cv;
std::atomic<bool> Logger::running{true};

Logger::Logger() {
    for (int i = 0; i < currentThreads; ++i) {
        workers.emplace_back(&Logger::workerThread, this);
    }
    setupHandlers();
}

Logger::~Logger() {
    running = false;
    cv.notify_all();

    for (auto& worker : workers) {
        if (worker.joinable()) {
            worker.join();
        }
    }
}

void Logger::log(LogLevel level, const std::string& message) {
    auto logEntry = std::make_pair(level, message);
    {
        std::lock_guard<std::mutex> lock(queueMutex);
        logQueue.push(logEntry);
    }
    pendingLogs++;
    cv.notify_one();
}

void Logger::adjustThreadPoolSize(int new_size) {
    if (new_size < minThreads || new_size > maxThreads)
        return;

    currentThreads = new_size;

    // Adjust the size of the worker pool
    std::unique_lock<std::mutex> lock(instanceMutex);
    cv.notify_all();
}

void Logger::workerThread() {
    while (running) {
        std::pair<LogLevel, std::string> logEntry;

        {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !logQueue.empty() || !running; });

            if (!running && logQueue.empty())
                break;

            logEntry = logQueue.front();
            logQueue.pop();
        }

        pendingLogs--;

        // Compress and send logs
        compressAndSendLogs({logEntry});
    }
}

void Logger::compressAndSendLogs(std::vector<std::pair<LogLevel, std::string>> logs) {
    // Placeholder for compression logic
    // Placeholder for sending to external service
}

void Logger::setupHandlers() {
    handlers[LogLevel::DEBUG] = [](const std::string& msg) { /* Handle DEBUG */ };
    handlers[LogLevel::INFO]  = [](const std::string& msg) { /* Handle INFO */ };
    handlers[LogLevel::WARN]  = [](const std::string& msg) { /* Handle WARN */ };
    handlers[LogLevel::ERROR] = [](const std::string& msg) { /* Handle ERROR */ };
}

} // namespace LoggingSystem

int main() {
    auto& logger = LoggingSystem::Logger::getInstance();

    // Example usage
    logger.log(LoggingSystem::LogLevel::INFO, "Server started successfully.");

    // Simulate dynamic adjustment of thread pool size based on load
    std::this_thread::sleep_for(std::chrono::seconds(2));
    logger.adjustThreadPoolSize(8);

    return 0;
}
