using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class DataProcessor
{
    private readonly string _connectionString;

    public DataProcessor(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async IAsyncEnumerable<IDataReader> ProcessData(
        List<Func<Dictionary<string, object>, bool>> filterCriteria,
        string baseQuery,
        Func<Task<Dictionary<string, object>>> fetchExternalData)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            var queryBuilder = new QueryStringBuilder(baseQuery);

            foreach (var criterion in filterCriteria)
            {
                queryBuilder.AddFilter(criterion);
            }

            string finalQuery = queryBuilder.ToString();

            using (var command = new SqlCommand(finalQuery, connection))
            {
                await using (var reader = await command.ExecuteReaderAsync())
                {
                    while (await reader.ReadAsync())
                    {
                        var dataRow = new Dictionary<string, object>();
                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            dataRow[reader.GetName(i)] = reader.GetValue(i);
                        }

                        try
                        {
                            var externalData = await fetchExternalData();
                            foreach (var kvp in externalData)
                            {
                                dataRow[kvp.Key] = kvp.Value;
                            }
                        }
                        catch (Exception ex)
                        {
                            // Log the error and continue processing
                            Console.WriteLine($"Error fetching external data: {ex.Message}");
                        }

                        yield return new DataReaderWrapper(reader, dataRow);
                    }
                }
            }
        }
    }
}

public class QueryStringBuilder
{
    private readonly string _baseQuery;
    private List<string> _filters = new();

    public QueryStringBuilder(string baseQuery)
    {
        _baseQuery = baseQuery.TrimEnd(' ', ';');
