    {
        // Simplified example; in practice, you'd need to safely parameterize SQL
        _filters.Add(" AND SomeColumn = @SomeValue"); // Replace with dynamic condition
    }

    public override string ToString()
    {
        return $"{_baseQuery} WHERE 1=1" + string.Join("", _filters);
    }
}

public class DataReaderWrapper : IDataReader
