    private readonly SqlDataReader _reader;
    private readonly Dictionary<string, object> _dataRow;

    public DataReaderWrapper(SqlDataReader reader, Dictionary<string, object> dataRow)
    {
        _reader = reader;
        _dataRow = dataRow;
    }

    // Implement all required methods from IDataReader interface
    // Forward calls to the underlying _reader where applicable

