    public bool Read()
    {
        return _reader.Read();
    }

    public int Depth => _reader.Depth;

    public string GetName(int i)
    {
        return _reader.GetName(i);
    }

    public object GetValue(string name)
    {
        if (_dataRow.TryGetValue(name, out var value))
        {
            return value;
        }
        return null;
    }

    // Other IDataReader members would be similarly wrapped or forwarded
