public class XmlParser
{
    public static XmlNode FindElementByName(string xmlContent, string elementName)
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            doc.LoadXml(xmlContent);

            XPathNavigator navigator = doc.CreateNavigator();
            XPathExpression expr = navigator.Compile($"//{elementName}");
            XPathNodeIterator nodes = navigator.Select(expr);

            if (nodes.Count == 0)
            {
                LogSearch("No element found with the specified name.");
                throw new Exception("Element not found");
            }

            if (nodes.MoveNext())
            {
                if (!nodes.MoveNext()) // Check for a second node
                {
                    LogSearch($"Element '{elementName}' found successfully.");
                    return nodes.Current as XmlNode;
                }
                else
                {
                    LogSearch("Multiple elements found with the specified name.");
                    throw new Exception("Multiple elements found");
                }
            }

            return null; // Should not reach here
        }
        catch (Exception ex)
        {
            LogSearch($"An error occurred: {ex.Message}");
            throw;
        }
    }

    private static void LogSearch(string message)
    {
        try
        {
            // Assuming a centralized logging service with a method called LogMessage
