use std::fs;
use std::path::{Path, PathBuf};
use std::env;
use std::io;

fn create_directory_with_env_var(template: &str) -> io::Result<()> {
    let dir_path = construct_directory_path(template)?;

    if !dir_path.exists() {
        ensure_parent_directories(&dir_path)?;

        fs::create_dir_all(&dir_path).map_err(|e| e.into())?;

        let permissions = fs::Permissions::from_mode(0o755);
        fs::set_permissions(&dir_path, permissions).map_err(|_| io::Error::new(io::ErrorKind::PermissionDenied, "Failed to set directory permissions"))?;
    }

    Ok(())
}

fn construct_directory_path(template: &str) -> io::Result<PathBuf> {
    let mut path_buf = PathBuf::from(env::var("BASE_PATH").unwrap_or_else(|_| ".".into()));

    for part in template.split("{") {
        if let Some((key, rest)) = part.split_once('}') {
            let value = env::var(key).unwrap_or_else(|_| ".".into());
            path_buf.push(value);
            path_buf.extend_from_slice(rest);
        } else {
            path_buf.push(part);
        }
    }

    Ok(path_buf)
}

fn ensure_parent_directories(dir_path: &Path) -> io::Result<()> {
    let parent = dir_path.parent().ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "Parent directory not found"))?;

    fs::create_dir_all(parent).map_err(|e| e.into())
}
