            string elementId = requestBody["elementId"]?.ToString();
            string htmlContent = requestBody["htmlContent"]?.ToString();

            if (string.IsNullOrWhiteSpace(sectionId) || string.IsNullOrWhiteSpace(elementId) || string.IsNullOrWhiteSpace(htmlContent))
