["```javascript
const fs = require('fs').promises;
const path = require('path');
const { createInterface } = require('readline');

async function readDirectoryAndProcessFiles(directory) {
    const maxConcurrency = 10;
    let activeReads = 0;
    let summary = {};
    let totalCharacters = 0;

    async function processFile(filePath) {
        try {
            activeReads++;
            const fileStream = fs.createReadStream(filePath);
            const rl = createInterface({
                input: fileStream,
                crlfDelay: Infinity
            });

            let lineCount = 0;
            let charCount = 0;

            for await (const line of rl) {
                lineCount++;
                charCount += line.length;
            }

            summary[filePath] = { lines: lineCount, characters: charCount };
            totalCharacters += charCount;
        } catch (error) {
            console.error(`Error processing file ${filePath}:`, error);
        } finally {
            activeReads--;
            if (activeReads < maxConcurrency && pendingFiles.length > 0) {
                const nextFile = pendingFiles.shift();
                processFile(nextFile).catch(console.error);
            }
        }
    }

    try {
        const files = await fs.readdir(directory);
        let pendingFiles = files.map(file => path.join(directory, file));

        for (let i = 0; i < Math.min(pendingFiles.length, maxConcurrency); i++) {
            processFile(pendingFiles.shift()).catch(console.error);
        }

        while (activeReads > 0) {
            await new Promise(resolve => setTimeout(resolve, 100));
        }
    } catch (error) {
        console.error(`Error reading directory ${directory}:`, error);
    }

    return { summary, totalCharacters };
}

module.exports = readDirectoryAndProcessFiles;
```"]

