const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

let testCache = new Map();

function loadModule(modulePath) {
    return require(path.resolve(process.cwd(), modulePath));
}

async function runTests(module, options = {}) {
    const moduleName = module.name || 'Unknown Module';
    const { enableTests, parallel, maxMemoryUsage } = options;

    console.log(`Starting tests for ${moduleName}`);

    let testSuite = loadModule(`${module.path}/tests`);
    let testList = Object.keys(testSuite);

    // Apply selective enabling/disabling of tests based on environment
    if (enableTests) {
        testList = testList.filter(testName => enableTests.includes(testName));
    }

    console.log(`Running ${testList.length} tests for ${moduleName}`);

    const results = [];
    const executionTimes = {};

    for (const testName of testList) {
        const isCached = testCache.has(testName);

        if (!isCached || options.refreshCache) {
            console.log(`Executing test: ${testName}`);
            let startTime = performance.now();

            // Reset the mocking library
            require('blueslip').reset();

            try {
                // Execute each test, handle async operations gracefully
                await Promise.resolve(testSuite[testName]());

                const endTime = performance.now();
                executionTimes[testName] = endTime - startTime;

                console.log(`Test ${testName} passed in ${executionTimes[testName].toFixed(2)}ms`);
                results.push({ testName, status: 'passed', time: executionTimes[testName] });

                // Cache the result
                testCache.set(testName, { status: 'passed', time: executionTimes[testName] });
            } catch (error) {
                console.error(`Test ${testName} failed in ${(performance.now() - startTime).toFixed(2)}ms`);
                results.push({ testName, status: 'failed', error: error.message });

                // Handle failure without caching
                testCache.delete(testName);
            }
        } else {
            const cachedResult = testCache.get(testName);

            console.log(`Using cached result for ${testName}`);
            executionTimes[testName] = cachedResult.time;
            results.push({ testName, status: cachedResult.status, time: cachedResult.time });
        }

        // Optimize resource usage
        if (process.memoryUsage().heapUsed > maxMemoryUsage) {
            console.warn(`Warning: Memory usage exceeded ${maxMemoryUsage}. Freeing resources.`);
            global.gc(); // If available, to trigger garbage collection
        }
    }

    return { results, executionTimes };
}

function resetCache() {
    testCache.clear();
}

module.exports = { runTests, resetCache };

// Usage example:
// const myModule = { name: 'MyModule', path: './my-module' };
// (async () => {
//     const options = {
