    this.cache = new Map();
  }

  get(key) {
    return this.cache.get(key);
  }

  set(key, value) {
    this.cache.set(key, value);
  }

  has(key) {
    return this.cache.has(key);
  }
}

const sessionScriptCache = new ScriptCache();

function generateFooterScripts(scripts) {
  const validScripts = [];
  let errorLog = [];

  // Validate and filter scripts
  for (let script of scripts) {
    if (!script || typeof script !== 'object') {
      console.error('Invalid script object:', script);
      continue;
    }

    const { type, version, isActive, dependencies } = script;

    if (
      typeof type !== 'string' ||
      typeof version !== 'string' ||
      typeof isActive !== 'boolean' ||
      !Array.isArray(dependencies)
    ) {
      console.error('Malformed script object:', script);
      errorLog.push(script);
      continue;
    }

    validScripts.push({ ...script, isValid: true });
  }

  // Sort scripts by dependencies
  const sortedScripts = topologicalSort(validScripts);

  let renderedHtml = '';
  for (let script of sortedScripts) {
    if (!script.isValid || !script.isActive) continue;

    const cacheKey = `${script.type}:${script.version}`;
    if (sessionScriptCache.has(cacheKey)) {
      continue;
    }

    renderedHtml += `<script src="${script.src}" type="${script.type}"></script>\n`;
    sessionScriptCache.set(cacheKey, script);
  }

  return renderedHtml.trim();
}

function topologicalSort(scripts) {
  const graph = scripts.reduce((acc, { dependencies, ...rest }) => {
    acc[rest] = new Set(dependencies);
    return acc;
  }, {});

  const visited = new Set();
  const stack = [];

  function visit(node) {
    if (visited.has(node)) return;
    visited.add(node);

    const edges = graph[node];
    if (edges) {
      for (let edge of edges) {
        const depNode = scripts.find(s => s.type === edge && s.version);
        if (!depNode) continue;
        visit(depNode);
      }
    }

    stack.push(node);
  }

  scripts.forEach(script => {
    visit(script);
  });

  return stack.reverse();
}

// Usage example
const scriptArray = [
  { type: 'js', version: '1.0', isActive: true, dependencies: [], src: '/path/to/script1.js' },
  // Add more scripts as needed...
];

document.querySelector('footer').innerHTML += generateFooterScripts(scriptArray);
```

