public class DataStreamingUtility {

    private static final Logger LOGGER = Logger.getLogger(DataStreamingUtility.class.getName());
    private final ExecutorService executorService;
    private final List<ServiceInstance> serviceInstances = new ArrayList<>();

    public DataStreamingUtility(int numberOfServices) {
        this.executorService = Executors.newFixedThreadPool(numberOfServices);
    }

    public void start() {
        for (int i = 0; i < serviceInstances.size(); i++) {
            ServiceInstance instance = serviceInstances.get(i);
            executorService.submit(() -> {
