                } catch (InterruptedException e) {
                    LOGGER.log(Level.INFO, "ServiceInstance " + instance.getId() + " interrupted.");
                } finally {
                    LOGGER.log(Level.INFO, "ServiceInstance " + instance.getId() + " stopped.");
                }
            });
        }
    }

    public void stopAllServices() {
        for (ServiceInstance instance : serviceInstances) {
            instance.pause();
            executorService.shutdownNow();
        }
    }

    private void processStreamData(ServiceInstance instance) {
        // Simulate data retrieval and processing
        LOGGER.log(Level.INFO, "Processing data in ServiceInstance " + instance.getId());
        // Example: Retrieve data from an external source and store it in the array
    }

    private int getRandomInterval() {
        Random random = new Random();
        return 500 + random.nextInt(1500); // Random interval between 500ms and 2000ms
    }

    public void addServiceInstance(ServiceInstance instance) {
        serviceInstances.add(instance);
    }

    public static void main(String[] args) throws InterruptedException {
        DataStreamingUtility utility = new DataStreamingUtility(5);

        for (int i = 0; i < 10; i++) {
            ServiceInstance instance = new ServiceInstance(i);
            utility.addServiceInstance(instance);
        }

        utility.start();

