const EventEmitter = require('events');
const { pipeline } = require('stream');

// Helper function to validate data blocks
function isValidDataBlock(data) {
    return !/(^|[^0])0{10,}/.test(data);
}

// Abstract class for external binary sources
class BinarySource extends EventEmitter {
    constructor() {
        super();
    }

    async connect() { /* Implement connection logic */ }
    async fetchData() { /* Implement fetch data logic */ }
}

// Example implementation of a Binary Source
class HTTPBinarySource extends BinarySource {
    constructor(url) {
        super();
        this.url = url;
    }

    async connect() {
        // Simulate network connection
        console.log(`Connecting to ${this.url}`);
    }

    async fetchData() {
        // Simulate fetching data from an HTTP source
        return new Promise((resolve) => setTimeout(() => resolve(Buffer.from([1, 2, 3])), 100));
    }
}

// Data Processor Class
class DataProcessor extends EventEmitter {
    constructor(sources) {
        super();
        this.sources = sources;
        this.activeSources = [];
    }

    async initialize() {
        for (const source of this.sources) {
            await source.connect();
            this.activeSources.push(source);
        }
        this.startProcessing();
    }

    startProcessing() {
        const streamProcessors = this.activeSources.map((source) => this.createStreamProcessor(source));
        return Promise.all(streamProcessors);
    }

    createStreamProcessor(source) {
        return async () => {
            try {
                while (true) {
                    const data = await source.fetchData();
                    if (!isValidDataBlock(data.toString('binary'))) {
                        console.log('Invalid block detected, skipping...');
                        continue;
                    }
                    this.emit('data', data);
                }
            } catch (error) {
                this.emit('error', error);
            }
        };
    }

    process(callback) {
        this.on('data', callback);
        this.on('error', (err) => console.error(`Error: ${err.message}`));
    }
}

// Main Pipeline
(async () => {
    const sources = [
        new HTTPBinarySource('http://example.com/source1'),
        new HTTPBinarySource('http://example.com/source2')
    ];

    const processor = new DataProcessor(sources);

    processor.process((data) => {
        console.log(`Valid data received: ${data}`);
    });

    await processor.initialize();
})();
```

