import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class TransactionProcessor {

    private static final Logger logger = Logger.getLogger(TransactionProcessor.class.getName());
    private Set<String> uniqueCustomers = ConcurrentHashMap.newKeySet();
    private Map<String, Set<String>> customerTransactions = new ConcurrentHashMap<>();

    public void processCSV(String filePath) {
        long startTime = System.currentTimeMillis();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                processLine(line);
            }
        } catch (IOException e) {
            logger.severe("Error reading file: " + e.getMessage());
        }

        long endTime = System.currentTimeMillis();
        logger.info("Processing time: " + (endTime - startTime) + " ms");

        calculateUniquePairs();
    }

    private void processLine(String line) {
        String[] fields = line.split(",");

        if (fields.length < 2) return;

        String customerA = sanitize(fields[0]);
        String customerB = sanitize(fields[1]);

        if (customerA == null || customerB == null || customerA.equals(customerB)) return;

        uniqueCustomers.add(customerA);
        uniqueCustomers.add(customerB);

        customerTransactions.computeIfAbsent(customerA, k -> ConcurrentHashMap.newKeySet()).add(customerB);
        customerTransactions.computeIfAbsent(customerB, k -> ConcurrentHashMap.newKeySet()).add(customerA);

        validateTransactionWithAPI(customerA, customerB);
    }

    private String sanitize(String field) {
        return field != null && !field.trim().isEmpty() ? field.trim() : null;
    }

    private void calculateUniquePairs() {
        long startTime = System.currentTimeMillis();

        int uniquePairs = 0;

        for (String customerA : uniqueCustomers) {
            for (String customerB : uniqueCustomers) {
                if (!customerA.equals(customerB) && !hasTransactedWithEachOther(customerA, customerB)) {
                    uniquePairs++;
                }
            }
        }

        uniquePairs /= 2; // Each pair is counted twice

        long endTime = System.currentTimeMillis();
        logger.info("Unique pairs calculation time: " + (endTime - startTime) + " ms");
        logger.info("Number of unique customer pairs who have never transacted with each other: " + uniquePairs);
    }

    private boolean hasTransactedWithEachOther(String customerA, String customerB) {
        return customerTransactions.getOrDefault(customerA, Collections.emptySet())
                .contains(customerB);
    }

    private void validateTransactionWithAPI(String customerA, String customerB) {
        int retries = 3;
        while (retries > 0) {
            try {
                if (externalPaymentAPICall(customerA, customerB)) {
                    logger.info("Transaction between " + customerA + " and " + customerB + " validated.");
                    return;
                }
            } catch (IOException e) {
                logger.warning("API call failed: " + e.getMessage());
            }
            retries--;
        }
        logger.severe("Failed to validate transaction after retries: " + customerA + ", " + customerB);
    }

    private boolean externalPaymentAPICall(String customerA, String customerB) throws IOException {
        // Simulate API call
        return true; // Assume success for simulation purposes
    }

    public static void main(String[] args) {
        TransactionProcessor processor = new TransactionProcessor();
        processor.processCSV("path/to/your/largefile.csv");
    }
}
