        Yaml yaml = new Yaml();
        Map<String, Object> data = yaml.load(inputStream);
        serviceConfigs.putAll(data);
        logger.info("Loaded configurations: {}", serviceConfigs.keySet());
    }

    @PostMapping("/add-service")
    public String addService(@RequestBody ServiceConfig config) {
        if (serviceConfigs.size() < 20) {
            serviceConfigs.put(config.getName(), config);
            manageServiceLifecycle(config, true);
            return "Service added successfully";
        }
        return "Cannot exceed 20 services";
    }

    @DeleteMapping("/remove-service/{name}")
    public String removeService(@PathVariable String name) {
        ServiceConfig config = serviceConfigs.remove(name);
        if (config != null) {
            manageServiceLifecycle(config, false);
            return "Service removed successfully";
        }
        return "Service not found";
    }

    private void manageServiceLifecycle(ServiceConfig config, boolean start) {
        threadPool.submit(() -> {
            try {
                if (start) {
                    initializeService(config);
                } else {
                    shutdownService(config);
                }
            } catch (Exception e) {
                logger.error("Error managing service lifecycle: ", e);
            }
        });
    }

    private void initializeService(ServiceConfig config) throws InterruptedException {
        // Simulate initialization with delay and retry
        int attempts = 0;
        while (attempts < config.getRetryAttempts()) {
            try {
                Thread.sleep(config.getStartupDelay());
                logger.info("Service {} started", config.getName());
                publishStatusUpdate(config, "started");
                break;
            } catch (InterruptedException e) {
                attempts++;
                if (attempts >= config.getRetryAttempts()) {
                    publishAlert(config, "Failed to start service after retries.");
                }
            }
        }
    }

    private void shutdownService(ServiceConfig config) {
        logger.info("Service {} stopped", config.getName());
        publishStatusUpdate(config, "stopped");
    }

