class ConfigManager {
    private $config;
    private static $instance = null;

    // Private constructor to prevent direct instantiation.
    private function __construct($environment) {
        $this->loadConfig($environment);
        $this->monitorChanges();
    }

    public static function getInstance($environment = 'production') {
        if (self::$instance === null) {
            self::$instance = new ConfigManager($environment);
        }
        return self::$instance;
    }

    private function loadConfig($environment) {
        $configPath = __DIR__ . "/config/{$environment}.php";

        if (!file_exists($configPath)) {
            throw new Exception("Configuration file for {$environment} not found.");
        }

        $this->config = require $configPath;
        $this->setupDependencies();
    }

    private function setupDependencies() {
        // Database connection
        $dbConfig = $this->config['database'] ?? [];
        try {
            $dsn = "mysql:host={$dbConfig['host']};dbname={$dbConfig['name']}";
            new PDO($dsn, $dbConfig['user'], $dbConfig['password']);
        } catch (PDOException $e) {
            error_log("Database connection failed: " . $e->getMessage());
            // Graceful fallback or retry logic
        }

        // Caching system initialization
        if (isset($this->config['cache'])) {
            $cacheConfig = $this->config['cache'];
            // Assuming a caching class exists, e.g., CacheManager::init()
            CacheManager::init($cacheConfig);
        }

        // Third-party API setup
        foreach ($this->config['apis'] ?? [] as $api) {
            $apiKey = $api['key'] ?? '';
            if (!$apiKey) {
                error_log("API key not provided for {$api['name']}.");
            }
            // Initialize the API client with the given key, e.g., ApiClient::init($apiKey);
        }

        // Monitor resource usage
        register_shutdown_function(function () {
            $memoryUsage = memory_get_peak_usage(true) / 1024 / 1024;
            error_log("Peak memory usage: {$memoryUsage} MB");
        });
    }

    public function getConfig() {
        return $this->config;
    }

    private function monitorChanges() {
        $lastModified = filemtime(__DIR__ . "/config/{$environment}.php");

        if ($this->config['file_last_checked'] !== $lastModified) {
            $this->loadConfig($GLOBALS['env']);
            $this->logChange("Configuration reloaded due to changes.");
        }

        // Update the last checked timestamp
        $this->config['file_last_checked'] = $lastModified;
    }

    private function logChange($message) {
        error_log("[{$GLOBALS['env']} - " . date('Y-m-d H:i:s') . "] {$message}");
        // Additional logging mechanisms can be added here (e.g., to a file or external service)
    }
}

// Usage
