    }

    // Customize headers
    pub fn with_headers(mut self, headers: HeaderMap) -> Self {
        self.headers = Some(headers);
        self
    }

    // Set a custom timeout
    pub fn with_timeout(mut self, timeout_secs: u64) -> Self {
        self.timeout = Duration::from_secs(timeout_secs);
        self
    }

    // Set maximum retries for failed requests
    pub fn with_max_retries(mut self, max_retries: u32) -> Self {
        self.max_retries = max_retries;
        self
    }

    // Create a synchronous HTTP client
    pub async fn sync_client(&self) -> SyncClient {
        let mut builder = ClientBuilder::new();

        if self.disable_cert_validation {
            builder.danger_accept_invalid_certs(true);
        }

        builder.timeout(self.timeout).build().unwrap()
    }

    // Create an asynchronous HTTP client with connection pooling
    pub async fn async_client(&self) -> AsyncClient {
        let mut builder = reqwest_async::ClientBuilder::new();

        if self.disable_cert_validation {
            builder.danger_accept_invalid_certs(true);
        }

        builder.timeout(self.timeout).build().unwrap()
    }

    // Perform a request with retry logic
    pub async fn perform_request(&self, client: &AsyncClient, method: reqwest_async::Method, path: &str) -> Result<String, Box<dyn std::error::Error>> {
        let full_url = format!("{}{}", self.base_url, path);

        for attempt in 0..=self.max_retries {
            match client.request(method, &full_url)
                .timeout(self.timeout)
                .headers(self.headers.clone().unwrap_or_default())
                .send()
                .await
            {
                Ok(response) => {
                    return response.text().await.map_err(Into::into);
                },
                Err(e) if attempt < self.max_retries => {
                    log::warn!("Attempt {} failed: {:?}", attempt + 1, e); // Integrate logging here
                    time::sleep(Duration::from_secs(2)).await;
                }
                Err(e) => return Err(Box::new(e)),
            }
        }

        Err("Max retries exceeded".into())
    }
}

#[tokio::main]
async fn main() {
    let client = HttpClient::new("https://api.example.com", false)
        .with_timeout(10)
        .with_max_retries(5);

    match client.async_client().await.perform_request(reqwest_async::Method::GET, "/endpoint").await {
        Ok(response) => println!("Response: {}", response),
        Err(e) => eprintln!("Request failed: {:?}", e),
    }
}
```

In this code:
- `HttpClient` struct is defined to hold configuration.
- Synchronous and asynchronous clients are implemented using the `reqwest` crate and its asynchronous counterpart.
- The `perform_request` method includes retry logic with logging on failure.
- Connection pooling and timeout handling are configured in client builders.
- This design provides a flexible, modular HTTP client capable of both sync and async operations.']

['```rust
use std::env;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};
use sysinfo::{System, SystemExt};

// Define a simple logging system with different log levels.
#[derive(Debug, PartialEq)]
enum LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
}

struct Logger {
    level: LogLevel,
    file_output: bool,
}

impl Logger {
    fn new(level: LogLevel) -> Self {
        let file_output = env::var("LOG_TO_FILE").unwrap_or_default() == "true";
        Logger { level, file_output }
    }

    fn log(&self, level: LogLevel, message: &str) {
        if self.level as i32 <= level as i32 {
            println!("[{}]: {}", level.to_string(), message);
            if self.file_output {
                // Append to a log file.
                let mut file = std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .open("build.log")
                    .unwrap();
                writeln!(file, "[{}]: {}", level.to_string(), message).unwrap();
            }
        }
    }

    fn to_string(&self) -> String {
        match self.level {
            LogLevel::DEBUG => "debug".to_string(),
            LogLevel::INFO => "info".to_string(),
            LogLevel::WARNING => "warning".to_string(),
            LogLevel::ERROR => "error".to_string(),
        }
    }
}

fn build_system_monitor(options: Vec<&str>) -> (i32, String) {
    let logger = Logger::new(LogLevel::from_env());

    // Detect the host operating system.
    let target_os = env::var("CARGO_TARGET").unwrap_or_else(|_| "unknown".to_string());

    let start_time = Instant::now();
    let system = System::new_all();

    // Run the build command
    let mut cmd = Command::new("cargo");
    cmd.arg("build")
        .args(&options)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());

    if let Ok(output) = cmd.output() {
        let duration = start_time.elapsed();

        system.refresh_all();

        // Collect metrics
        let memory_info = format!(
            "Memory Usage: {} KB",
            system.used_memory()
        );

        let exit_code = output.status.code().unwrap_or(1);
        let warnings_errors = String::from_utf8_lossy(&output.stderr)
            .lines()
            .filter_map(|line| {
                if line.contains("warning") {
                    Some(("WARNING".to_string(), line.to_string()))
                } else if line.contains("error") {
                    Some(("ERROR".to_string(), line.to_string()))
                } else {
                    None
                }
            })
            .collect::<Vec<_>>()
            .join("\n");

        let report = format!(
            "Build completed in: {:.2?}\n{}{}\nWarnings and Errors:\n{}",
            duration,
            memory_info,
            if target_os.contains("windows") { "\nTarget OS: Windows" } else {
                if target_os.contains("linux") { "\nTarget OS: Linux" } else { "" }
            },
            warnings_errors
        );

        logger.log(LogLevel::INFO, &report);

        return (exit_code.unwrap_or(1), report);
    } else {
        let error_message = "Failed to run the build command.".to_string();
        logger.log(LogLevel::ERROR, &error_message);
        return (1, error_message);
    }
}

impl From<&str> for LogLevel {
    fn from(s: &str) -> Self {
        match s.to_lowercase().as_str() {
            "debug" => LogLevel::DEBUG,
            "info" => LogLevel::INFO,
            "warning" => LogLevel::WARNING,
            "error" => LogLevel::ERROR,
            _ => LogLevel::INFO, // Default log level
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_build_system_monitor() {
        let options = vec!["--release"];
        let (exit_code, report) = build_system_monitor(options);
        assert!(exit_code >= 0);
        assert!(!report.is_empty());
        println!("Test Report: {}", report);
    }
}
```

This Rust code defines a `build_system_monitor` function that processes command-line arguments to configure and execute a Rust project build using the Cargo tool. It includes a modular logging system, builds on system metrics collection, and handles environmental differences such as OS type. The provided unit test verifies the basic functionality of the monitoring system.']

