import requests
from cachetools import TTLCache, cached
from datetime import timedelta
import logging
import time

# Configure logging
logging.basicConfig(level=logging.INFO)

class WeatherDataRetriever:
    def __init__(self, api_key, cache_ttl_seconds=300):
        self.api_key = api_key
        self.cache = TTLCache(maxsize=1000, ttl=cache_ttl_seconds)
        self.base_url = "https://api.weather.com/v3/"
        self.rate_limit_reset_time = None

    @cached(cache=lambda self: self.cache)
    def get_weather_data(self, city):
        if self.rate_limit_reset_time and time.time() < self.rate_limit_reset_time:
            sleep_duration = self.rate_limit_reset_time - time.time()
            logging.info(f"Rate limit hit. Sleeping for {sleep_duration:.2f} seconds.")
            time.sleep(sleep_duration)

        try:
            response = requests.get(
                f"{self.base_url}weather",
                params={"q": city, "apiKey": self.api_key}
            )

            if response.status_code == 429:  # Rate limit exceeded
                self.rate_limit_reset_time = int(response.headers.get("Retry-After", time.time() + 60))
                return None

            response.raise_for_status()
            data = response.json()

            # Handle potential changes in data format or structure
            weather_data = {
                "city": city,
                "temperature": data.get("temperature"),
                "description": data.get("weather_description")
            }

            logging.info(f"Successfully retrieved weather data for {city}.")
            return weather_data

        except requests.exceptions.HTTPError as http_err:
            logging.error(f"HTTP error occurred: {http_err}")
        except requests.exceptions.RequestException as req_err:
            logging.error(f"Request exception: {req_err}")
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")

        return None

    def fetch_weather_for_cities(self, cities):
        results = []
        for city in cities:
            weather_data = self.get_weather_data(city)
            if weather_data:
                results.append(weather_data)
        return results

# Sample invocation
def main():
    api_key = "your_api_key_here"
    cities = ["New York", "Los Angeles", "Chicago"]
    retriever = WeatherDataRetriever(api_key)

    try:
        weather_data = retriever.fetch_weather_for_cities(cities)
        if weather_data:
            for data in weather_data:
                print(data)
        else:
            logging.info("No weather data retrieved.")

    except Exception as e:
        logging.error(f"Failed to fetch weather data: {e}")

if __name__ == "__main__":
    main()
```

This code sets up a robust function that interacts with a third-party weather API. It uses caching and handles rate limiting gracefully, manages errors effectively, logs critical information for monitoring, and is designed to be scalable and resilient to changes in the data format or API structure.']

