<?php

function generateAndHash($length, $charset, $password, $config) {
    // Validate config settings
    if (!isset($config['hash_algorithm'])) {
        $config['hash_algorithm'] = PASSWORD_DEFAULT;
    }

    // Generate random string
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset[random_int(0, strlen($charset) - 1)];
    }

    // Hash the password
    try {
        $hashedPassword = password_hash($password, $config['hash_algorithm']);
        if ($hashedPassword === false) {
            throw new Exception("Password hashing failed.");
        }
    } catch (Exception $e) {
        return ['error' => $e->getMessage()];
    }

    return [
        'generated_string' => $randomString,
        'hashed_password'  => $hashedPassword
    ];
}

function readFileSync($directoryPath, $filename) {
    // Define whitelist of allowed directories
    $whitelist = ['/path/to/allowed/dir1', '/path/to/allowed/dir2'];

    if (!in_array(realpath($directoryPath), $whitelist)) {
        throw new Exception("Directory not in whitelist.");
    }

    $filePath = realpath($directoryPath) . DIRECTORY_SEPARATOR . $filename;

    // Read and parse the configuration file
    try {
        if (!file_exists($filePath) || !is_readable($filePath)) {
            throw new Exception("File cannot be read.");
        }

        $configData = file_get_contents($filePath);
        if ($configData === false) {
            throw new Exception("Failed to read from file.");
        }

        return parse_ini_string($configData, true);

    } catch (Exception $e) {
        return ['error' => $e->getMessage()];
    }
}

