const { Readable } = require('stream');
const https = require('https');

async function fetchFile(url) {
  return new Promise((resolve, reject) => {
    let data = '';
    https.get(url, (res) => {
      if (res.statusCode !== 200) {
        return reject(new Error(`Failed to get ${url}: ${res.statusCode}`));
      }

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => resolve(data));

      res.on('error', (err) => reject(err));
    }).on('timeout', () => {
      https.get(url, (res) => { // Retry once on timeout
        if (res.statusCode !== 200) {
          return reject(new Error(`Failed to get ${url}: ${res.statusCode}`));
        }

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => resolve(data));

        res.on('error', (err) => reject(err));
      }).setTimeout(5000);
    });
  });
}

async function processOAuthAndStream(oauthRequest, readableStream) {
  const { privateKeyUrl, certUrl } = oauthRequest;
  let bufferData = Buffer.alloc(0);

  try {
    console.log('Fetching private key and certificate...');

    const [privateKeyResponse, certResponse] = await Promise.all([
      fetchFile(privateKeyUrl),
      fetchFile(certUrl)
    ]);

    console.log('Files fetched successfully.');

    const pemFileContent = `${certResponse}\n${privateKeyResponse}`;

    readableStream.on('data', (chunk) => {
      bufferData = Buffer.concat([bufferData, chunk]);

      // Pause if buffer size exceeds 10MB
      if (bufferData.length > 10 * 1024 * 1024) {
        console.log('Buffer overflow risk detected. Pausing stream.');
        readableStream.pause();

        setTimeout(() => {
          // Process and clear the buffer before resuming
          processBufferData(bufferData);
          bufferData = Buffer.alloc(0);
          console.log('Resuming stream after processing data.');
          readableStream.resume();
        }, 100); // Adjust time as necessary for processing
      }
    });

    readableStream.on('end', () => {
      if (bufferData.length > 0) {
        processBufferData(bufferData);
      }

      console.log('Stream ended. All data processed.');

      // Here you would typically save the PEM file or pass it to another function
      console.log('PEM File Created:', pemFileContent);
    });

    readableStream.on('error', (err) => {
      console.error('Stream encountered an error:', err.message);
    });

  } catch (error) {
    console.error('Error processing OAuth and stream:', error.message);
  }
}

