<?php
// auth.php
session_start();
require 'vendor/autoload.php';

use League\OAuth2\Client\Provider\GenericProvider;

$provider = new GenericProvider([
    'clientId'                => 'your-client-id',
    'clientSecret'            => 'your-client-secret',
    'redirectUri'             => 'https://your-redirect-uri.com/callback',
    'urlAuthorize'            => 'https://authorization-server.com/authorize',
    'urlAccessToken'          => 'https://authorization-server.com/token',
    'urlResourceOwnerDetails' => 'https://resource-owner.com/resource'
]);

if (!isset($_SESSION['access_token'])) {
    if (isset($_GET['code'])) {
        $accessToken = $provider->getAccessToken('authorization_code', [
            'code' => $_GET['code']
        ]);

        $_SESSION['access_token'] = $accessToken->getToken();
    } else {
        $authUrl = $provider->getAuthorizationUrl();
        header('Location: ' . $authUrl);
        exit;
    }
}

function getUserData() {
    global $provider;
    try {
        $accessToken = $provider->getAccessToken('refresh_token', [
            'refresh_token' => $_SESSION['access_token']
        ]);
        $_SESSION['access_token'] = $accessToken->getToken();

        $apiResponse = $provider->getAuthenticatedRequest(
            'GET',
            'https://external-api.com/user-data',
            $accessToken
        );

        return json_decode(file_get_contents($apiResponse->getBody()), true);
    } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
        error_log('Error: ' . $e->getMessage());
        header($_SERVER["SERVER_PROTOCOL"] . " 401 Unauthorized");
        exit;
    }
}

// rate-limiting middleware
function rateLimitMiddleware() {
    if (!isset($_SESSION['request_count'])) {
        $_SESSION['request_count'] = 0;
    }

    $_SESSION['request_count']++;

    $maxRequests = 100; // limit per hour
    $resetTime = time() + (60 * 60);

    if ($_SESSION['request_count'] > $maxRequests) {
        header($_SERVER["SERVER_PROTOCOL"] . " 429 Too Many Requests");
        exit;
    }

    if (!isset($_SESSION['rate_limit_reset']) || $_SESSION['rate_limit_reset'] < time()) {
        $_SESSION['request_count'] = 0;
        $_SESSION['rate_limit_reset'] = $resetTime;
    }
}

// dns_resolver.php
function resolveDNS($hostname) {
    // Use REST API to communicate with C-based DNS resolver
    $url = "http://localhost:8080/dns?hostname=$hostname";
    $response = file_get_contents($url);

    if ($response === FALSE) {
        error_log("Failed to resolve DNS for hostname: $hostname");
        header($_SERVER["SERVER_PROTOCOL"] . " 502 Bad Gateway");
        exit;
    }

    return json_decode($response, true)['ip'];
}

// api.php
rateLimitMiddleware();

header('Content-Type: application/json');

$method = $_SERVER['REQUEST_METHOD'];

switch ($method) {
    case 'GET':
        $userData = getUserData();
        echo json_encode(['user_data' => $userData]);
        break;

    default:
        header($_SERVER["SERVER_PROTOCOL"] . " 405 Method Not Allowed");
}

