### C Component

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

#define CACHE_SIZE 100
typedef struct {
    char hostname[256];
    uint8_t ip_address[4];
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
int cache_index = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void init_cache() {
    pthread_mutex_init(&cache_lock, NULL);
}

void add_to_cache(const char* hostname, const uint8_t* ip) {
    pthread_mutex_lock(&cache_lock);
    strncpy(cache[cache_index].hostname, hostname, sizeof(cache[cache_index].hostname));
    memcpy(cache[cache_index].ip_address, ip, 4);
    cache_index = (cache_index + 1) % CACHE_SIZE;
    pthread_mutex_unlock(&cache_lock);
}

int get_from_cache(const char* hostname, uint8_t* ip) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            memcpy(ip, cache[i].ip_address, 4);
            pthread_mutex_unlock(&cache_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

void* handle_request(void* arg) {
    char* req = (char*)arg;
    char hostname[256];
    sscanf(req, "GET /dns?hostname=%255s HTTP/1.1", hostname);

    uint8_t ip_address[4] = {0};

    if (!get_from_cache(hostname, ip_address)) {
        struct addrinfo hints, *res, *p;
        int status;

        memset(&hints, 0, sizeof hints);
        hints.ai_family = AF_INET; // IPv4
        hints.ai_socktype = SOCK_STREAM;

        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
            return NULL;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            if (p->ai_family == AF_INET) {
                struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
                ip_address[0] = ((uint8_t*)&ipv4->sin_addr)[0];
                ip_address[1] = ((uint8_t*)&ipv4->sin_addr)[1];
                ip_address[2] = ((uint8_t*)&ipv4->sin_addr)[2];
                ip_address[3] = ((uint8_t*)&ipv4->sin_addr)[3];

                break;
            }
        }

        freeaddrinfo(res);
    }

    add_to_cache(hostname, ip_address);

    char response[256];
    snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{\"ip\": \"%d.%d.%d.%d\"}",
             ip_address[0], ip_address[1], ip_address[2], ip_address[3]);

    write(STDOUT_FILENO, response, strlen(response));
    return NULL;
}

int main() {
    init_cache();

    const char* port = "8080";
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(atoi(port));

    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 10) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    while(1) {
        if ((new_socket = accept(server_fd, (struct sockaddr*)&address, (socklen_t*)&addrlen))<0) {
            perror("accept");
            continue;
        }

        pthread_t thread_id;
        char buffer[1024] = {0};
        read(new_socket, buffer, 1024);

        pthread_create(&thread_id, NULL, handle_request, strdup(buffer));
        pthread_detach(thread_id);
    }

    return 0;
}
```

