<?php

class PasswordUpdateException extends Exception {}

interface AuthenticatorServiceInterface {
    public function validatePasswordStrength($password): bool;
    public function logPasswordChange($userId, $status): void;
}

class PasswordUpdaterDAO {

    private $dbConnection;
    private $authenticatorService;
    private $cache;

    public function __construct($dbConnection, AuthenticatorServiceInterface $authenticatorService, $cache) {
        $this->dbConnection = $dbConnection;
        $this->authenticatorService = $authenticatorService;
        $this->cache = $cache;
    }

    public function updateUserPassword(int $userId, string $newPassword): bool {
        try {
            // Check if user data is cached
            $userData = $this->getOrCacheUserData($userId);

            if (!$userData) {
                throw new PasswordUpdateException("User not found.");
            }

            // Validate password strength through external service
            if (!$this->authenticatorService->validatePasswordStrength($newPassword)) {
                throw new PasswordUpdateException("Invalid password strength.");
            }

            $this->startTransaction();

            // Update the user's password in the database securely
            $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT);
            if (!$this->updateUserPasswordInDB($userId, $hashedPassword)) {
                throw new PasswordUpdateException("Failed to update password.");
            }

            // Commit transaction and clear cache on success
            $this->commitTransaction();
            $this->cache->deleteItem("user_data_{$userId}");

            // Log the successful change through external service
            $this->authenticatorService->logPasswordChange($userId, "success");

            return true;
        } catch (Exception $e) {
            $this->rollbackTransaction();
            $this->authenticatorService->logPasswordChange($userId, "failure");
            error_log("Password update failed for user {$userId}: " . $e->getMessage());
            return false;
        }
    }

    private function getOrCacheUserData(int $userId): ?array {
        $cacheKey = "user_data_{$userId}";
        if ($this->cache->hasItem($cacheKey)) {
            return $this->cache->getItem($cacheKey);
        } else {
            $userData = $this->fetchUserFromDB($userId);
            if ($userData) {
                $this->cache->setItem($cacheKey, $userData);
            }
            return $userData;
        }
    }

    private function fetchUserFromDB(int $userId): ?array {
        $stmt = $this->dbConnection->prepare("SELECT * FROM users WHERE id = ?");
        $stmt->bind_param('i', $userId);
        $stmt->execute();
        $result = $stmt->get_result();
        return $result->fetch_assoc();
    }

    private function updateUserPasswordInDB(int $userId, string $hashedPassword): bool {
        $stmt = $this->dbConnection->prepare("UPDATE users SET password = ? WHERE id = ?");
        $stmt->bind_param('si', $hashedPassword, $userId);
        return $stmt->execute();
    }

    private function startTransaction() {
        $this->dbConnection->begin_transaction(MYSQLI_TRANS_START_READ_WRITE | MYSQLI_TRANS_START_WITH_CONSISTENT_SNAPSHOT);
    }

    private function commitTransaction() {
        $this->dbConnection->commit();
    }

    private function rollbackTransaction() {
        $this->dbConnection->rollback();
    }
}

