};

// Custom allocator interface
class CustomAllocator {
public:
    virtual ~CustomAllocator() = default;

    virtual void* allocate(size_t size, bool aligned = false) = 0;
    virtual void deallocate(void* ptr) = 0;
};

// A simple custom allocator for demonstration purposes
class SimpleAllocator : public CustomAllocator {
private:
    std::mutex allocMutex; // Mutex to ensure thread safety

public:
    void* allocate(size_t size, bool aligned = false) override {
        std::lock_guard<std::mutex> lock(allocMutex);
        if (aligned) {
            return _mm_malloc(size, 64); // Aligned allocation
        } else {
            return malloc(size); // Unaligned allocation
        }
    }

    void deallocate(void* ptr) override {
        std::lock_guard<std::mutex> lock(allocMutex);
        if (ptr == nullptr) return;
        if (reinterpret_cast<uintptr_t>(ptr) % 64 == 0) {
            _mm_free(ptr); // Aligned deallocation
        } else {
            free(ptr); // Unaligned deallocation
        }
    }
};

// Octree class
