#define MAX_IP_CONNECTIONS 100
#define MAX_REQUESTS_PER_MINUTE 60
#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    char ip[16];
    int request_count;
    time_t last_request_time;
} IPMetrics;

typedef struct {
    char id[32];
    size_t payload_size;
} Request;

IPMetrics ip_metrics[MAX_IP_CONNECTIONS];
int highest_payload_size = 0;
char highest_payload_id[32] = {0};

void initialize_ip_metrics() {
    for (int i = 0; i < MAX_IP_CONNECTIONS; i++) {
        strcpy(ip_metrics[i].ip, "0.0.0.0");
        ip_metrics[i].request_count = 0;
        ip_metrics[i].last_request_time = time(NULL);
    }
}

int get_ip_index(const char *ip) {
    for (int i = 0; i < MAX_IP_CONNECTIONS; i++) {
        if (strcmp(ip_metrics[i].ip, ip) == 0) {
            return i;
        }
    }
    return -1;
}

void update_request_count(const char *ip) {
    int index = get_ip_index(ip);
    time_t now = time(NULL);

    if (index != -1) {
        if ((now - ip_metrics[index].last_request_time) > 60) {
            ip_metrics[index].request_count = 0;
            ip_metrics[index].last_request_time = now;
        }
        ip_metrics[index].request_count++;
        ip_metrics[index].last_request_time = now;
    } else {
        for (int i = 0; i < MAX_IP_CONNECTIONS; i++) {
            if (ip_metrics[i].request_count == 0) {
                strcpy(ip_metrics[i].ip, ip);
                ip_metrics[i].request_count = 1;
                ip_metrics[i].last_request_time = now;
                break;
            }
        }
    }
}

int is_rate_limited(const char *ip) {
    int index = get_ip_index(ip);
    if (index != -1 && ip_metrics[index].request_count > MAX_REQUESTS_PER_MINUTE) {
        return 1;
    }
    return 0;
}

void process_request(Request request, const char *ip) {
    // Simulate latency check and payload size filtering
    if (request.payload_size > MAX_PAYLOAD_SIZE) {
        printf("Request %s exceeds maximum payload size.\n", request.id);
        return;
    }

    update_request_count(ip);

    if (is_rate_limited(ip)) {
        printf("Rate limit exceeded for IP: %s\n", ip);
        return;
    }

    // Update highest payload
    if (request.payload_size > highest_payload_size) {
        highest_payload_size = request.payload_size;
        strcpy(highest_payload_id, request.id);
    }

    // Simulate database operations and logging
    printf("Processing request ID: %s from IP: %s\n", request.id, ip);

    // Add more logic for handling the request...
}

int main() {
    initialize_ip_metrics();

    // Simulating incoming requests
    Request req1 = {.id = "req123", .payload_size = 512};
    process_request(req1, "192.168.0.1");

    Request req2 = {.id = "req124", .payload_size = 2048}; // Exceeds payload size
    process_request(req2, "192.168.0.1");

    Request req3 = {.id = "req125", .payload_size = 1024};
    for (int i = 0; i < MAX_REQUESTS_PER_MINUTE + 10; i++) {
        process_request(req3, "192.168.0.2");
    }

    printf("Highest Payload ID: %s with size %d\n", highest_payload_id, highest_payload_size);

    return 0;
}
