#include <iostream>
#include <mutex>
#include <thread>
#include <chrono>
#include <random>

class Character {
public:
    Character(int attackPoints)
        : maxAttackPoints(attackPoints), currentAttackPoints(attackPoints),
          cooldowns{0, 0, 0, 0}, lastAttack(-1) {}

    void regenerateAttackPoints() {
        std::lock_guard<std::mutex> lock(regenMutex);

        // Simulate dynamic regeneration based on activity and server load
        int regenRate = determineRegenerationRate();
        currentAttackPoints = std::min(maxAttackPoints, currentAttackPoints + regenRate);

        // Regenerate points over time (e.g., every second)
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    int chooseAttack() {
        std::lock_guard<std::mutex> lock(attackMutex);

        int availableAttacks[4];
        int count = 0;

        // Check cooldowns and attack point costs
        for (int i = 0; i < 4; ++i) {
            if (cooldowns[i] == 0 && currentAttackPoints >= attackCosts[i]) {
                if (lastAttack != i || consecutiveUseLimitReached(i)) {
                    availableAttacks[count++] = i;
                }
            }
        }

        // Randomly select one of the available attacks
        if (count > 0) {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, count - 1);
            int selectedAttack = availableAttacks[dis(gen)];

            applyCooldown(selectedAttack);
            consumeAttackPoints(selectedAttack);
            lastAttack = selectedAttack;

            return selectedAttack;
        }

        // No valid attack can be made
        return -1;
    }

private:
    static constexpr int cooldownTime = 3;  // in seconds
    static constexpr int consecutiveUseLimit = 2;  // limit for consecutive use of same attack

    int maxAttackPoints;
    int currentAttackPoints;

    std::mutex regenMutex;
    std::mutex attackMutex;

    int cooldowns[4];
    int lastAttack;
    int attackCosts[4] = {10, 15, 20, 25};
    const int consecutiveUseCounts[4] = {0, 0, 0, 0};  // Initialize counters for consecutive uses

    void applyCooldown(int attackIndex) {
        cooldowns[attackIndex] = cooldownTime;
        ++consecutiveUseCounts[attackIndex];

        std::thread([this, attackIndex]() {
            std::this_thread::sleep_for(std::chrono::seconds(cooldownTime));
            {
                std::lock_guard<std::mutex> lock(attackMutex);
                if (cooldowns[attackIndex] > 0) cooldowns[attackIndex] = 0;
                --consecutiveUseCounts[attackIndex];
            }
        }).detach();
    }

    void consumeAttackPoints(int attackIndex) {
        currentAttackPoints -= attackCosts[attackIndex];
    }

    bool consecutiveUseLimitReached(int attackIndex) {
        return consecutiveUseCounts[attackIndex] < consecutiveUseLimit;
    }

    int determineRegenerationRate() {
        // Simulate dynamic regeneration rate (could depend on player activity and server load)
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 5);
        return dis(gen);  // Regenerate between 1 to 5 points
    }
};

int main() {
    Character hero(50);

    // Start attack point regeneration in a separate thread
    std::thread regenThread(&Character::regenerateAttackPoints, &hero);

    // Simulate choosing attacks over time
    for (int i = 0; i < 10; ++i) {
        int attack = hero.chooseAttack();
        if (attack != -1)
            std::cout << "Attack " << attack + 1 << " chosen.\n";
        else
            std::cout << "No valid attack available. Try again later.\n";

        std::this_thread::sleep_for(std::chrono::milliseconds(500));  // simulate time between actions
    }

    regenThread.join();

    return 0;
}
