using System.Threading;

public class RandomValueGenerator
{
    private readonly ConcurrentDictionary<Guid, (Random random, string log, int count)> _generators = new();
    private readonly object _lock = new();

    public Guid AddNewGenerator(long seed)
    {
        var id = Guid.NewGuid();
        var random = new Random(unchecked((int)seed));

        _generators[id] = (random, "", 0);
        return id;
    }

    public double GenerateRandomDouble(Guid generatorId, double min, double max, bool inclusiveMin, bool inclusiveMax)
    {
        EnsureExists(generatorId);

        var (random, log, count) = GetGenerator(generatorId);
        lock (_lock)
        {
            double value;
            if (inclusiveMin && inclusiveMax)
                value = random.NextDouble() * (max - min) + min;
            else
                value = random.NextDouble() * (max - min - 1e-10) + min + 1e-10;

            UpdateLog(generatorId, $"{value}", "double", count);
            _generators[generatorId] = (random, log, ++count);

            return value;
        }
    }

    public int GenerateRandomInt(Guid generatorId, int min, int max, bool inclusiveMin, bool inclusiveMax)
    {
        EnsureExists(generatorId);

        var (random, log, count) = GetGenerator(generatorId);
        lock (_lock)
        {
            int range = inclusiveMax ? max - min + 1 : max - min;
            int value = random.Next(inclusiveMin ? min : min + 1, inclusiveMax ? max + 1 : max);

            UpdateLog(generatorId, $"{value}", "int", count);
            _generators[generatorId] = (random, log, ++count);

            return value;
        }
    }

    public void ResetSeed(Guid generatorId, long newSeed)
    {
        EnsureExists(generatorId);

        lock (_lock)
        {
            var random = new Random(unchecked((int)newSeed));
            _generators[generatorId] = (random, "", 0);
        }
    }

    public string GenerateReport(Guid generatorId)
    {
        EnsureExists(generatorId);

        var (_, log, count) = GetGenerator(generatorId);
        return $"{count} values generated:\n{log}";
    }

    private void EnsureExists(Guid generatorId)
    {
        if (!_generators.ContainsKey(generatorId))
            throw new ArgumentException("Generator ID does not exist.", nameof(generatorId));
    }

    private (Random random, string log, int count) GetGenerator(Guid generatorId)
    {
        return _generators[generatorId];
    }

    private void UpdateLog(Guid generatorId, string value, string type, int count)
    {
        var (_, log, _) = GetGenerator(generatorId);
        _generators[generatorId] = (GetGenerator(generatorId).random, $"{log}\n{count}. {type}: {value}", count);
    }

    // External service integration and error handling would be implemented here
}
```

