typedef struct {
    char *data;
    int length;
} ThemeBitmap;

ThemeBitmap themeCache[100];
int cacheCount = 0;

void freeCache() {
    for (int i = 0; i < cacheCount; ++i) {
        if (themeCache[i].data != NULL) {
            free(themeCache[i].data);
            themeCache[i].data = NULL;
        }
    }
}

void parseLine(const char *line) {
    char *copy = strdup(line);
    char *token = strtok(copy, " ");
    while (token != NULL) {
        int length = strlen(token);
        ThemeBitmap bitmap;
        bitmap.data = malloc(length + 1);
        if (bitmap.data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free(copy);
            return;
        }
        strcpy(bitmap.data, token);
        bitmap.length = length;

        // Cache the bitmap
        if (cacheCount < sizeof(themeCache) / sizeof(ThemeBitmap)) {
            themeCache[cacheCount++] = bitmap;
        } else {
            // Recycle old cache entry
            free(themeCache[0].data);
            memmove(&themeCache[0], &themeCache[1], (cacheCount - 1) * sizeof(ThemeBitmap));
            themeCache[--cacheCount] = bitmap;
        }

        token = strtok(NULL, " ");
    }
    free(copy);
}

