#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tiffio.h"
#include "md5.h"

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int number_of_extra_samples;
    char *sample_info;
} ImageMetadata;

typedef struct {
    ImageMetadata metadata;
    char hash[33]; // MD5 hash is 32 characters + null terminator
} ProcessResult;

ProcessResult ProcessImageAndComputeHash(const char* imagePath, const char* stringToHash) {
    TIFF* tiff = TIFFOpen(imagePath, "r");
    ProcessResult result;

    if (!tiff) {
        fprintf(stderr, "Error: Unable to open TIFF image.\n");
        memset(&result, 0, sizeof(ProcessResult));
        return result;
    }

    ImageMetadata metadata = {0};
    metadata.sample_info = malloc(256); // Allocate memory for sample info description
    if (!metadata.sample_info) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        TIFFClose(tiff);
        memset(&result, 0, sizeof(ProcessResult));
        return result;
    }

    uint32 w, h;
    tsize_t s;
    uint16 bitspersample = 0, samplesperpixel = 0;

    if (TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesperpixel) &&
        TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bitspersample)) {
        metadata.samples_per_pixel = samplesperpixel;
        metadata.bits_per_sample = bitspersample;

        if (TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &metadata.number_of_extra_samples)) {
            sprintf(metadata.sample_info, "Sample Info: %d extra samples", metadata.number_of_extra_samples);
        } else {
            strcpy(metadata.sample_info, "No Extra Sample Information");
        }
    } else {
        fprintf(stderr, "Error: Missing necessary TIFF fields.\n");
        free(metadata.sample_info);
        TIFFClose(tiff);
        memset(&result, 0, sizeof(ProcessResult));
        return result;
    }

    TIFFGetImageWidth(tiff, &w);
    TIFFGetImageLength(tiff, &h);

    uint32 dircount = 0;
    if (TIFFNumberOfDirectories(tiff) > 1) {
        while (TIFFReadDirectory(tiff)) {
            ++dircount;
        }
    }

    printf("TIFF: width=%d, height=%d, samples_per_pixel=%d, bits_per_sample=%d\n", w, h, metadata.samples_per_pixel, metadata.bits_per_sample);

    MD5_CTX context;
    MD5Init(&context);
    MD5Update(&context, (unsigned char*)stringToHash, strlen(stringToHash));
    MD5Final((unsigned char*)&result.hash, &context);

    result.metadata = metadata;

    free(metadata.sample_info);
    TIFFClose(tiff);

    return result;
}

int main() {
    const char* imagePath = "example.tiff";
    const char* stringToHash = "Hello, World!";

    ProcessResult result = ProcessImageAndComputeHash(imagePath, stringToHash);

    if (result.metadata.bits_per_sample > 0) { // Check metadata validity
        printf("Metadata: bits per sample=%d\n", result.metadata.bits_per_sample);
        printf("Metadata: samples per pixel=%d\n", result.metadata.samples_per_pixel);
        printf("Metadata: %s\n", result.metadata.sample_info);
    } else {
        printf("Failed to process image.\n");
    }

    printf("MD5 Hash: %s\n", result.hash);

    return 0;
}
```

