#include <openssl/evp.h>
#include <openssl/sha.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#define AES_KEY_LENGTH 32 // AES-256 key length in bytes
#define IV_LENGTH 16      // AES block size

// Function to derive a key using SHA-256 from the given password
void derive_key(const char *password, unsigned char *key) {
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!mdctx) abort();

    if (1 != EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL)) abort();
    if (1 != EVP_DigestUpdate(mdctx, password, strlen(password))) abort();
    if (32 != EVP_DigestFinal_ex(mdctx, key, NULL)) abort(); // SHA-256 output length

    EVP_MD_CTX_free(mdctx);
}

// Function to initialize AES-256-CBC cipher
void init_aes_cipher(const char *password) {
    unsigned char key[AES_KEY_LENGTH];
    unsigned char iv[IV_LENGTH];

    derive_key(password, key);

    if (!RAND_bytes(iv, sizeof(iv))) abort(); // Generate random IV

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) abort();

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        abort();
    }

    // Store the cipher context and IV securely in your theme cache for reuse
    // For demonstration purposes, we'll just print them
    printf("Cipher initialized with key and IV.\n");

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
}

// Function to ensure default theme directory exists
