int processFiles(const std::string& inputFileName, const std::string& outputFileName,
                 const std::vector<uint8_t>& byteArray, Config config) {

    namespace fs = std::filesystem;
    int retryCount = 0;
    const int maxRetries = 3;

    // Ensure the output directory exists
    auto outputPath = fs::path(outputFileName).parent_path();
    if (!outputPath.empty() && !fs::exists(outputPath)) {
        try {
            fs::create_directories(outputPath);
        } catch (const std::exception& e) {
            std::cerr << "Error: Unable to create output directory. " << e.what() << '\n';
            return -1;
        }
    }

    while (retryCount < maxRetries) {
        try {
            // Convert JPEG to PDF
            JpegToPdfConverter converter(inputFileName, outputFileName);
            if (!converter.convert()) {
                std::cerr << "Error: JPEG conversion failed.\n";
                retryCount++;
                continue;
