#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define MAX_COMMANDS 5

static volatile sig_atomic_t terminate = 0;
static pid_t child_pids[MAX_COMMANDS] = {0};
static int active_children = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        terminate = 1;
        for (int i = 0; i < MAX_COMMANDS; ++i) {
            if (child_pids[i] > 0) {
                kill(child_pids[i], SIGTERM);
                waitpid(child_pids[i], NULL, WNOHANG);
            }
        }
    } else if (signum == SIGKILL) {
        for (int i = 0; i < MAX_COMMANDS; ++i) {
            if (child_pids[i] > 0) {
                kill(child_pids[i], SIGKILL);
            }
        }
    }
}

void execute_commands(const char* command_string) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigfillset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1 ||
        sigaction(SIGKILL, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    char* command = strdup(command_string);
    char* token = strtok(command, ";");
    int success = 1;

    while (token != NULL && !terminate) {
        while (active_children >= MAX_COMMANDS) {
            for (int i = 0; i < MAX_COMMANDS; ++i) {
                if (child_pids[i] > 0) {
                    int status;
                    pid_t result = waitpid(child_pids[i], &status, WNOHANG);
                    if (result == 0) continue;

                    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                        success = 0;
                    }

                    child_pids[i] = 0;
                    active_children--;
                }
            }
        }

        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            free(command);
            return 0;
        } else if (pid == 0) { // Child process
            execlp("sh", "sh", "-c", token, (char*)NULL);
            perror("execlp"); 
            exit(EXIT_FAILURE); 
        } else { // Parent process
            int i;
            for (i = 0; i < MAX_COMMANDS; ++i) {
                if (child_pids[i] == 0) {
                    child_pids[i] = pid;
                    break;
                }
            }

            if (i == MAX_COMMANDS) { 
                fprintf(stderr, "Error: No slot available for a new process.\n");
                free(command);
                return 0;
            }

            active_children++;
        }

        token = strtok(NULL, ";");
    }

    while (active_children > 0 && !terminate) {
        int status;
        pid_t result;

        do {
            result = waitpid(-1, &status, WNOHANG);
            if (result == -1) {
                perror("waitpid");
            }
            for (int i = 0; i < MAX_COMMANDS; ++i) {
                if (child_pids[i] == result) {
                    child_pids[i] = 0;
                    active_children--;
                    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                        success = 0;
                    }
                }
            }

        } while (result > 0);
    }

    free(command);
    return success ? 1 : 0;
}
