using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public class WebsiteManager
{
    private readonly ILogger _logger; // Assume an existing logger interface
    private static readonly ConcurrentDictionary<string, Process> RunningSites = new();

    public WebsiteManager(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<Process> StartWebsiteAsync(string directoryPath, string siteName, string[] args = null)
    {
        if (string.IsNullOrWhiteSpace(directoryPath) || string.IsNullOrWhiteSpace(siteName))
            return null;

        if (!ValidateDirectory(directoryPath))
            return null;

        if (!VerifyWebConfigExists(directoryPath))
            return null;

        ProcessStartInfo startInfo;
        try
        {
            startInfo = CreateProcessStartInfo(directoryPath, siteName, args);
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error creating process for {siteName}: {ex.Message}");
            return null;
        }

        var retryCount = 3;
        while (retryCount > 0)
        {
            try
            {
                Process process = await StartProcessAsync(startInfo);
                if (process != null)
                {
                    RunningSites.TryAdd(siteName, process);
                    _logger.LogInformation($"{siteName} started at {DateTime.UtcNow}");
                    return process;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Error starting {siteName}: {ex.Message}");
                retryCount--;
                await Task.Delay(1000); // Delay before retrying
            }
        }

        return null;
    }

    private bool ValidateDirectory(string directoryPath)
    {
        try
        {
            if (!Directory.Exists(directoryPath))
            {
                _logger.LogWarning($"Directory does not exist: {directoryPath}");
                return false;
            }

            var testFilePath = Path.Combine(directoryPath, "test.tmp");
            using (var fs = File.Create(testFilePath)) { }
            File.Delete(testFilePath);
            return true;
        }
        catch (UnauthorizedAccessException)
        {
            _logger.LogWarning($"Directory not accessible: {directoryPath}");
            return false;
        }
        catch (IOException ex)
        {
            _logger.LogError($"IO Exception during directory validation: {ex.Message}");
            return false;
        }
    }

    private bool VerifyWebConfigExists(string directoryPath)
    {
        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            _logger.LogWarning($"Missing web.config in directory: {directoryPath}");
            return false;
        }
        return true;
    }

    private ProcessStartInfo CreateProcessStartInfo(string directoryPath, string siteName, string[] args)
    {
        var startInfo = new ProcessStartInfo
        {
            FileName = "dotnet", // Assuming .NET Core application
            Arguments = $"{siteName} {string.Join(" ", args ?? Array.Empty<string>())}",
            WorkingDirectory = directoryPath,
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        };
        return startInfo;
    }

    private async Task<Process> StartProcessAsync(ProcessStartInfo startInfo)
    {
        var process = new Process { StartInfo = startInfo };

        try
        {
            process.Start();
            await EnsureReadiness(process, TimeSpan.FromSeconds(30)); // Customize timeout as needed
            return process;
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to ensure readiness: {ex.Message}");
            KillProcessAndChildren(process);
            throw;
        }
    }

    private async Task EnsureReadiness(Process process, TimeSpan timeout)
    {
        using var cts = new CancellationTokenSource(timeout);
        var tcs = new TaskCompletionSource<bool>();

        process.OutputDataReceived += (sender, args) =>
        {
            if (args.Data != null && args.Data.Contains("ready"))
                tcs.TrySetResult(true); // Adjust condition based on actual readiness signal
        };

        process.BeginOutputReadLine();
        await Task.WhenAny(tcs.Task, Task.Delay(Timeout.Infinite, cts.Token));
    }

    private void KillProcessAndChildren(Process process)
    {
        if (process != null && !process.HasExited)
            try { process.Kill(); } catch { }

        // Optionally iterate through child processes and terminate them
        // This example assumes no children for simplicity
    }

    public void StopWebsite(string siteName)
    {
        if (RunningSites.TryRemove(siteName, out var process) && !process.HasExited)
            KillProcessAndChildren(process);

        _logger.LogInformation($"{siteName} stopped at {DateTime.UtcNow}");
    }
}

public interface ILogger
{
    void LogInformation(string message);
    void LogWarning(string message);
    void LogError(string message);
}
