['```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class CommandExecutor {

    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final String LOG_DIR = "logs";

    public static void main(String[] args) {
        try {
            Path logDirPath = Paths.get(LOG_DIR);
            if (!Files.exists(logDirPath)) {
                Files.createDirectories(logDirPath);
            }

            executor.submit(() -> executeCommand("your_command_here"));

            // Add more commands as needed
        } catch (Exception e) {
            System.err.println("Error initializing application: " + e.getMessage());
        }
    }

    private static void executeCommand(String commandLine) {
        ProcessBuilder processBuilder = new ProcessBuilder(commandLine.split("\\s+"));
        Path stdoutLog = createTempFile("stdout", ".log");
        Path stderrLog = createTempFile("stderr", ".log");

        processBuilder.redirectOutput(stdoutLog.toFile());
        processBuilder.redirectError(stderrLog.toFile());

        try {
            Process process = processBuilder.start();
            int exitCode = process.waitFor();

            System.out.println("Command executed with exit code: " + exitCode);

        } catch (IOException | InterruptedException e) {
            System.err.println("Execution error: " + e.getMessage());
        } finally {
            deleteTempFile(stdoutLog);
            deleteTempFile(stderrLog);
        }
    }

    private static Path createTempFile(String prefix, String suffix) throws IOException {
        return Files.createTempFile(prefix, suffix, Paths.get(LOG_DIR));
    }

    private static void deleteTempFile(Path path) {
        try (Closeable ignore = new Closeable() {
            @Override
            public void close() throws IOException {
                if (Files.exists(path)) {
                    Files.delete(path);
                }
            }
        }) {}
    }
}
```

This code provides a framework for executing system commands based on user input, managing temporary files efficiently, and logging outputs. It uses `ProcessBuilder` to handle command execution and manages stdout/stderr redirection into separate log files. The application leverages an executor service to manage concurrency, allowing it to scale with multiple concurrent executions. Temporary files are handled using Java's `Files.createTempFile`, ensuring they reside in a specified directory and are deleted upon completion.']

