#define MAX_CONNECTIONS_LIMIT 10000

bool validateServerConfig(const char *configFilePath) {
    JSON_Value *rootValue = json_parse_file(configFilePath);
    if (!rootValue) {
        fprintf(stderr, "Error parsing configuration file\n");
        return false;
    }

    const JSON_Object *configObject = json_value_get_object(rootValue);
    bool isValid = true;

    // Validate `port`
    int port = (int)json_object_dotget_number(configObject, "port", 0);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "`port` must be a positive integer between 1 and 65535\n");
        isValid = false;
    }

    // Validate `host`
    const char *host = json_object_get_string(configObject, "host");
    if (!host || strlen(host) == 0) {
        fprintf(stderr, "`host` must be a non-empty string\n");
        isValid = false;
    }

    // Validate `max_connections`
    int maxConnections = (int)json_object_dotget_number(configObject, "max_connections", 0);
    if (maxConnections <= 0 || maxConnections > MAX_CONNECTIONS_LIMIT) {
        fprintf(stderr, "`max_connections` must be a positive integer not exceeding %d\n", MAX_CONNECTIONS_LIMIT);
        isValid = false;
    }

    // Validate `ssl_enabled`
    bool sslEnabled = json_object_dotget_boolean(configObject, "ssl_enabled", false);
    if (!json_value_is_bool(json_object_get_value(configObject, "ssl_enabled"))) {
        fprintf(stderr, "`ssl_enabled` must be a boolean value\n");
        isValid = false;
    }

    // Free JSON resources
    json_value_free(rootValue);

    return isValid;
}
