using System.Threading.Tasks;

public class ThemeCacheManager
{
    private readonly Dictionary<string, byte[]> _themeCache = new();
    private static readonly HttpClient httpClient = new();
    private const string EnvironmentVariableName = "THEME_FILE_PATH";
    private const string DefaultFilePath = "./default_theme_directory/config.txt";
    private const string RemoteServiceUrl = "https://remote-service.com/api/v1/upload";

    public async Task ProcessThemeBitmapsAsync()
    {
        string filePath = Environment.GetEnvironmentVariable(EnvironmentVariableName) ?? DefaultFilePath;

        try
        {
            await using var streamReader = new StreamReader(filePath);
            string line;

            while ((line = await streamReader.ReadLineAsync()) != null)
            {
                if (string.IsNullOrWhiteSpace(line)) continue; // Skip empty lines

                var fields = line.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

                try
                {
                    byte[] bitmapBytes = ParseBitmap(fields);
                    if (bitmapBytes != null)
                    {
                        await SendToRemoteServiceAsync(bitmapBytes);
                        CacheThemeBitmap(fields[0], bitmapBytes); // Assuming first field is an identifier
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing line: {line}. Exception: {ex.Message}");
                }
            }

            var pngFile = await ParsePngFromRootAsync();
            CacheThemeBitmap("root_parsing", pngFile);
        }
        catch (IOException ioEx)
        {
            Console.WriteLine($"IO error when reading file: {ioEx.Message}");
        }
    }

    private byte[] ParseBitmap(string[] fields)
    {
        if (fields.Length < 2) return null; // Ensure at least identifier and bitmap data

        try
        {
            var identifier = fields[0];
            var dataString = string.Join(",", fields, 1, fields.Length - 1);

            // Simulate parsing the bitmap
            return Convert.FromBase64String(dataString); 
        }
        catch (FormatException)
        {
            Console.WriteLine("Malformed base64 data.");
            return null;
        }
    }

    private void CacheThemeBitmap(string key, byte[] bitmapBytes)
    {
        if (_themeCache.ContainsKey(key))
        {
            _themeCache[key] = bitmapBytes; // Update existing cache entry
        }
        else if (_themeCache.Count < 100) // Arbitrary cache size limit for demonstration
        {
            _themeCache.Add(key, bitmapBytes); // Add new entry to cache
        }

        CleanupCache(); // Clean up unused entries periodically
    }

    private void CleanupCache()
    {
        if (_themeCache.Count <= 50) return; // Keep a certain number of items before cleanup

        var keysToRemove = new List<string>(_themeCache.Keys);

        while (keysToRemove.Count > 0 && _themeCache.Count > 50)
        {
            var keyToRemove = keysToRemove[0];
            _themeCache[keyToRemove] = null; // Remove reference to free memory
            _themeCache.Remove(keyToRemove); 
            keysToRemove.RemoveAt(0);
        }
    }

    private async Task<byte[]> ParsePngFromRootAsync()
    {
        try
        {
            var pngPath = Path.Combine(Directory.GetCurrentDirectory(), "image.png");
            return await File.ReadAllBytesAsync(pngPath);
        }
        catch (IOException ex)
        {
            Console.WriteLine($"Error reading PNG file: {ex.Message}");
            return null;
        }
    }

    private async Task SendToRemoteServiceAsync(byte[] bitmapData)
    {
        try
        {
            var content = new ByteArrayContent(bitmapData);

            var response = await RetryPolicy(async () => httpClient.PostAsync(RemoteServiceUrl, content));

            if (!response.IsSuccessStatusCode)
            {
                Console.WriteLine($"Failed to upload bitmap: {response.ReasonPhrase}");
            }
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Network error while sending data: {ex.Message}");
        }
    }

    private async Task<HttpResponseMessage> RetryPolicy(Func<Task<HttpResponseMessage>> action, int maxRetries = 3, int delayMs = 2000)
    {
        for (int attempt = 1; attempt <= maxRetries; attempt++)
        {
            try
            {
                return await action();
            }
            catch (Exception) when (attempt < maxRetries)
            {
                await Task.Delay(delayMs);
            }
        }

        throw new Exception("Max retry attempts exceeded");
    }
}
