using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DecryptionService
{
    private const int KeySizeTripleDES = 24; // Triple DES requires a key size of 192 bits (24 bytes)
    private const int IvSizeTripleDES = 8;   // Initialization Vector (IV) size is 64 bits (8 bytes)

    public static string DecryptMessage(string base64EncryptedMessage, byte[] decryptionKey, byte[] initializationVector)
    {
        if (!ValidateParameters(decryptionKey, initializationVector))
            return "Error: Invalid key or IV size";

        try
        {
            using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
            {
                // Set the encryption algorithm parameters
                tdes.Key = decryptionKey;
                tdes.IV = initializationVector;
                tdes.Mode = CipherMode.CBC;
                tdes.Padding = PaddingMode.PKCS7;

                byte[] cipherTextBytes = Convert.FromBase64String(base64EncryptedMessage);

                using (MemoryStream msDecrypt = new MemoryStream(cipherTextBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, tdes.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            string plaintext = srDecrypt.ReadToEnd();

                            ValidateAndLogSensitiveContent(plaintext);

                            return plaintext;
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Handle exception with logging framework, consider integrating a real logger
            Console.WriteLine($"Decryption error: {ex.Message}");
            return "Error during decryption";
        }
    }

    private static bool ValidateParameters(byte[] key, byte[] iv)
    {
        if (key.Length != KeySizeTripleDES)
            return false;

        if (iv.Length != IvSizeTripleDES)
            return false;

        return true;
    }

    private static void ValidateAndLogSensitiveContent(string message)
    {
        string[] sensitiveKeywords = { "confidential", "proprietary" };

        foreach (string keyword in sensitiveKeywords)
        {
            if (message.Contains(keyword, StringComparison.OrdinalIgnoreCase))
            {
                // Log warning with a logging framework, consider integrating a real logger
                Console.WriteLine($"Warning: Sensitive content detected - {keyword}");
            }
        }

        // Future extension point for additional checks can be added here
    }
}
