using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHashProcessor
{
    private readonly ConcurrentDictionary<string, string> _hashCache = new();
    private static readonly object _lockObject = new();

    public async Task<ConcurrentDictionary<string, string>> ProcessFilesAsync(IEnumerable<string> filePaths)
    {
        var fileHashes = new ConcurrentDictionary<string, string>();

        // Parallel processing of files
        await Task.WhenAll(filePaths.Select(filePath => ProcessFileAsync(filePath, fileHashes)));

        return fileHashes;
    }

    private async Task ProcessFileAsync(string filePath, ConcurrentDictionary<string, string> fileHashes)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("Invalid file path.", nameof(filePath));

        try
        {
            // Check cache first
            if (_hashCache.TryGetValue(filePath, out var cachedHash))
            {
                Log($"Using cached hash for {filePath}");
                fileHashes.TryAdd(filePath, cachedHash);
                return;
            }

            using (var sha256 = SHA256.Create())
            {
                using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 8192, true))
                {
                    var buffer = new byte[8192];
                    int bytesRead;

                    // Compute hash in chunks
                    while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                    {
                        sha256.TransformBlock(buffer, 0, bytesRead, null, 0);
                    }

                    sha256.TransformFinalBlock(buffer, 0, 0);

                    var hashBytes = sha256.Hash;
                    var fileHash = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

                    // Add to cache and main dictionary
                    lock (_lockObject)
                    {
                        _hashCache[filePath] = fileHash;
                    }
                    fileHashes.TryAdd(filePath, fileHash);
                }
            }

            Log($"Processed {filePath}");
        }
        catch (Exception ex)
        {
            LogError(ex, filePath);
        }
    }

    private void Log(string message)
    {
        // Integrate with external logging service
        Console.WriteLine(message); // Replace with actual logging call
    }

    private void LogError(Exception ex, string filePath)
    {
        // Integrate with external logging service
        Console.Error.WriteLine($"Error processing {filePath}: {ex.Message}"); // Replace with actual error logging call
    }
}
