public class CompressedFileLoader<T> : IDataLoader<T> where T : new()
{
    private readonly ILogger _logger;

    public CompressedFileLoader(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public T LoadData(string filePath)
    {
        try
        {
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            using (var compressionStream = GetCompressionStream(fileStream))
            using (var reader = new BinaryReader(compressionStream))
            {
                var data = Deserialize<T>(reader);

                if (!VerifyChecksum(fileStream, reader.BaseStream.Length))
                {
                    throw new DataIntegrityException("Checksum verification failed.");
                }

                return data;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error loading data from {filePath}: {ex.Message}");
            throw;
        }
    }

    private Stream GetCompressionStream(Stream fileStream)
    {
        if (IsGZipFile(fileStream))
        {
            fileStream.Seek(0, SeekOrigin.Begin);
            return new GZipStream(fileStream, CompressionMode.Decompress);
        }

        fileStream.Seek(0, SeekOrigin.Begin);
        return new DeflateStream(fileStream, CompressionMode.Decompress);
    }

