const ajv = new Ajv();
ajv.addSchema(schemas.logging, "logging");

function compileAndExecuteConfig(configFile) {
  const fs = require("fs");

  // Read the configuration file
  fs.readFile(configFile, 'utf8', (err, data) => {
    if (err) throw err;

    let config;
    try {
      config = JSON.parse(data);
    } catch (parseErr) {
      console.error("Invalid JSON format", parseErr);
      return;
    }

    // Validate the configuration
    const validate = ajv.getSchema("logging");
    if (!validate(config)) {
      console.error("Configuration validation failed:", validate.errors);
      return;
    }

    // Check memory limits and prevent exceeding them
    const currentMemoryUsageMB = process.memoryUsage().heapUsed / 1024 / 1024;
    if (currentMemoryUsageMB + config.maxMemoryUsageMB > process.env.MAX_MEMORY_LIMIT) {
      console.error("Configuration would exceed memory limits.");
      return;
    }

    // Simulate external data source integration with error recovery
    const fetchData = () => new Promise((resolve, reject) => {
      exec('curl -s http://external.data/source', (error, stdout, stderr) => {
        if (error || stderr) {
          console.warn("Network issue encountered. Retrying...");
          setTimeout(fetchData, 1000); // Retry after a delay
          return;
        }
        resolve(stdout);
      });
    });

    fetchData().then(data => {
      console.log("External data fetched successfully:", data);

      // Execute logging based on configuration level and output format
      executeLogging(config, data);

      // Example of efficient update/rollback support (simple version)
      const originalConfig = JSON.stringify(config);  // Backup current config

      try {
        // Simulate configuration change/update
        config.level = 'debug';  // Modify configuration for testing
        console.log("Updated logging level to debug.");

        executeLogging(config, data);

      } catch (updateError) {
        console.error("Update failed:", updateError);
        // Rollback to original configuration in case of an error
        JSON.parse(originalConfig);
        console.log("Rolled back to previous configuration.");
      }
    }).catch(finalErr => console.error("Failed to fetch external data:", finalErr));
  });
}

function executeLogging(config, data) {
  switch (config.level) {
    case 'debug':
      console.debug(data);
      break;
    case 'info':
      console.info(data);
      break;
    case 'warn':
      console.warn(data);
      break;
    case 'error':
      console.error(data);
      break;
    default:
      console.log("Logging data:", data);
  }
}

module.exports = { compileAndExecuteConfig };
