use tokio::runtime::Runtime;
use std::{env, path::PathBuf};
use log::{info, error, LevelFilter};
use simple_logger::SimpleLogger;

mod tasks;
mod logging;
mod ffi;

#[tokio::main]
async fn main() {
    // Initialize the logger
    let mut builder = SimpleLogger::new();
    builder.with_level(LevelFilter::Info).init().unwrap();

    info!("Starting application");

    // Load command-line arguments
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <task_module>", args[0]);
        std::process::exit(1);
    }

    let task_name = &args[1];
    info!("Executing task: {}", task_name);

    // Initialize task modules dynamically
    match tasks::initialize_task_module(task_name).await {
        Ok(module) => {
            if let Err(e) = module.execute().await {
                logging::log_critical_error(&format!("Task execution failed: {}", e));
            }
        },
        Err(err) => {
            error!("Failed to initialize task module '{}': {}", task_name, err);
            ffi::log_to_file("Error initializing task module", &err.to_string());
        }
    }

    info!("Application finished");
}

