use tokio::fs::File;
use tokio::io::{self, AsyncWriteExt};
use std::sync::Arc;
use simple_logger::SimpleLogger;
use log::LevelFilter;

pub fn init() {
    let mut builder = SimpleLogger::new();
    builder.with_level(LevelFilter::Info).init().unwrap();
}

pub async fn log_to_file(level: &str, message: &str) -> io::Result<()> {
    let file_path = PathBuf::from("critical_errors.log");
    let mut file = File::options()
        .append(true)
        .create(true)
        .open(file_path)
        .await?;

    writeln!(file, "[{}] {}", level, message).await
}

pub fn log_critical_error(message: &str) {
    let _ = tokio::spawn(async move {
        if let Err(e) = logging::log_to_file("CRITICAL", message).await {
            eprintln!("Failed to write critical error to file: {}", e);
        }
    });
}

// ffi.rs

extern "C" {
    fn log_error(format: *const i8, ...);
}

#[no_mangle]
pub extern "C" fn rust_log_to_file(file_path: &str, message: &str) {
    let c_file_path = std::ffi::CString::new(file_path).unwrap();
    let c_message = std::ffi::CString::new(message).unwrap();

    unsafe {
        log_error(c_file_path.as_ptr(), c_message.as_ptr());
    }
}

#[no_mangle]
pub extern "C" fn rust_log_to_file_internal(file_path: *const i8, message: *const i8) {
    let path = std::ffi::CStr::from_ptr(file_path).to_str().unwrap();
    let msg = std::ffi::CStr::from_ptr(message).to_str().unwrap();

    if let Err(e) = logging::log_to_file("CRITICAL", &msg).await {
        eprintln!("Failed to write critical error to file: {}", e);
    }
}

#[link(name = "c_logging")]
extern "C" {
    fn log_error(format: *const i8, ...) -> ();
}
