- **Logging**: Logs operations with timestamps and user info, using simple file-based logging.
- **Directory Size Limit**: Rejects creation attempts that would exceed a predefined size limit.
- **Retry Mechanism**: Implements retries for transient errors during directory creation.
- **External Service Integration**: Placeholder function to notify an external service on critical errors.
- **Error Handling**: Provides clear error messages and handles file system issues gracefully.

This implementation is modular, allowing easy extension and integration with additional services.']

['```python
import json
from collections import OrderedDict
from threading import RLock
from typing import Callable, Dict, Any

class LRUCache:
    def __init__(self, capacity: int):
        self.cache = OrderedDict()
        self.capacity = capacity
        self.lock = RLock()

    def get(self, key):
        with self.lock:
            if key not in self.cache:
                return None
            value = self.cache.pop(key)
            self.cache[key] = value
            return value

    def put(self, key, value):
        with self.lock:
            if key in self.cache:
                self.cache.pop(key)
            elif len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
            self.cache[key] = value


class JSONDataObjectFactory:
    _registry: Dict[str, Callable[[], Any]] = {}
    _cache = LRUCache(capacity=100)

    def __init__(self):
        self._lock = RLock()

    @classmethod
    def register(cls, name: str, factory_func: Callable[[], Any]):
        with cls._lock:
            if name in cls._registry:
                raise ValueError(f"Factory function for '{name}' already registered.")
            cls._registry[name] = factory_func

    @classmethod
    def unregister(cls, name: str):
        with cls._lock:
            if name in cls._registry:
                del cls._registry[name]

    @classmethod
    def from_json(cls, json_str: str) -> Any:
        cached_obj = cls._cache.get(json_str)
        if cached_obj is not None:
            return cached_obj

        data = json.loads(json_str)
        obj_type = data.pop('type', None)

        with cls._lock:
            factory_func = cls._registry.get(obj_type)

        if factory_func is None:
            raise ValueError(f"No registered factory for type '{obj_type}'.")

        obj = factory_func()(**data)
        cls._cache.put(json_str, obj)
        return obj

    @classmethod
    def to_json(cls, obj: Any) -> str:
        data = obj.to_dict()
        data['type'] = obj.__class__.__name__
        return json.dumps(data)


class BaseDataObject:
    _serialization_logic = {}

    def __init__(self, **kwargs):
        self.fields = kwargs

    @classmethod
    def register_serialization_logic(cls, field: str, logic_func: Callable[[Any], Any]):
        cls._serialization_logic[field] = logic_func

    def to_dict(self) -> Dict[str, Any]:
        result = {}
        for field, value in self.fields.items():
            if field in self._serialization_logic:
                result[field] = self._serialization_logic[field](value)
            else:
                result[field] = value
        return result


# Example subclass implementation
class UserDataObject(BaseDataObject):
    def __init__(self, name: str, age: int, **kwargs):
        super().__init__(name=name, age=age, **kwargs)

JSONDataObjectFactory.register('UserDataObject', UserDataObject)


# Unit tests (using pytest for demonstration)
def test_registering_and_using_factory():
    json_str = '{"type": "UserDataObject", "name": "John Doe", "age": 30}'

    obj = JSONDataObjectFactory.from_json(json_str)
    assert isinstance(obj, UserDataObject)
    assert obj.fields['name'] == 'John Doe'
    assert obj.fields['age'] == 30

def test_caching():
    json_str1 = '{"type": "UserDataObject", "name": "Jane Doe", "age": 25}'
    json_str2 = '{"type": "UserDataObject", "name": "Alice", "age": 22}'

    obj1 = JSONDataObjectFactory.from_json(json_str1)
    assert isinstance(obj1, UserDataObject)

    # Cache hit
    cached_obj1 = JSONDataObjectFactory._cache.get(json_str1)
    assert cached_obj1 is not None

    # Check cache size limit (LRU behavior)
    for i in range(101):
        _ = JSONDataObjectFactory.from_json(f'{{"type": "UserDataObject", "name": "Test{i}", "age": {i}}}')

    # Ensure first item was evicted
    assert JSONDataObjectFactory._cache.get(json_str1) is None

# Run tests (assuming pytest environment)
if __name__ == "__main__":
    import pytest
    pytest.main([__file__])
```']

