// Helper function to find the largest integer in an array.
int findLargestInteger(const int* arr, size_t size) {
    if (size == 0) return INT_MIN; // Handle empty array case

    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to process input and encrypt based on command line option.
EVP_CIPHER_CTX* processInputAndEncrypt(int filterEven, const char* operationOption) {
    // Mutex for thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Read integers from standard input
    size_t capacity = 1024;
    size_t size = 0;
    int* numbers = malloc(capacity * sizeof(int));
    if (!numbers) return NULL;

    while (scanf("%d", &numbers[size]) == 1 && size < 10000) {
        if (size >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) break; // Handle memory allocation failure
        }
        ++size;
    }

    // Filter for even numbers if required
    if (filterEven) {
        size_t newSize = 0;
        int* filteredNumbers = malloc(size * sizeof(int));
        if (!filteredNumbers) {
            free(numbers);
            return NULL;
        }

        for (size_t i = 0; i < size; ++i) {
            if (numbers[i] % 2 == 0) {
                filteredNumbers[newSize++] = numbers[i];
            }
        }

        free(numbers);
        numbers = filteredNumbers;
        size = newSize;
    }

    // Find the largest integer
    pthread_mutex_lock(&mutex);
    int largestInteger = findLargestInteger(numbers, size);
    pthread_mutex_unlock(&mutex);

    // Perform specific operation using OpenSSL
    EVP_CIPHER_CTX* cipherCtx = EVP_CIPHER_CTX_new();
    if (!cipherCtx) {
        free(numbers);
        return NULL;
    }

    // Example encryption setup (key and iv should be properly set)
    unsigned char key[32] = {0}; // Placeholder key
    unsigned char iv[16] = {0};  // Placeholder IV

    EVP_CIPHER_CTX_init(cipherCtx);

    if (!strcmp(operationOption, "encrypt")) {
        if (1 != EVP_EncryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(cipherCtx);
            free(numbers);
            return NULL;
        }
    } else if (!strcmp(operationOption, "decrypt")) {
        if (1 != EVP_DecryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(cipherCtx);
            free(numbers);
            return NULL;
        }
    }

    // Clean up
    free(numbers);

    pthread_mutex_destroy(&mutex);
    return cipherCtx;
}
