#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu_array(size_t count, uint16_t rx_ue_info_tag, uint16_t rnti) {
    if (count == 0) return NULL;

    pthread_mutex_lock(&allocation_lock);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);

    if (!array) {
        // Log error: Memory allocation failed
        fprintf(stderr, "Memory allocation failed for %zu CRC_INDICATION_PDU elements.\n", count);
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }

    // Initialize the array elements
    for (size_t i = 0; i < count; ++i) {
        array[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
        array[i].CRC_INDICATION_REL8_TAG.RNTI = rnti;

        // Randomly set CRCFLAG
        array[i].CRCFLAG = rand() % 2; // Generates a random 0 or 1
    }

    // Log success: Memory allocation succeeded for count elements.
    printf("Successfully allocated memory for %zu CRC_INDICATION_PDU elements.\n", count);

    pthread_mutex_unlock(&allocation_lock);

    return array;
}

void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (!array) return;

    free(array);
}

// Example usage
int main() {
    size_t num_pdus = 10; // Number of PDU structures to allocate
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = allocate_crc_indication_pdu_array(num_pdus, 12345, 67890);

    if (pdu_array) {
        // Use the allocated array
        free_crc_indication_pdu_array(pdu_array);
    }

    return 0;
}
