['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 1000

// Union-Find structure
typedef struct {
    int parent[MAX_RNTI];
    int rank[MAX_RNTI];
    pthread_mutex_t mutexes[MAX_RNTI];
} UnionFind;

void initializeUnionFind(UnionFind *uf) {
    for (int i = 0; i < MAX_RNTI; ++i) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
        pthread_mutex_init(&uf->mutexes[i], NULL);
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void unionSets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        pthread_mutex_lock(&uf->mutexes[rootX]);
        pthread_mutex_lock(&uf->mutexes[rootY]);

        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }

        pthread_mutex_unlock(&uf->mutexes[rootY]);
        pthread_mutex_unlock(&uf->mutexes[rootX]);
    }
}

void checkDisjointPairs(NFAPI_CRC_INDICATION_PDU_T *list, int size) {
    UnionFind uf;
    initializeUnionFind(&uf);

    for (int i = 0; i < size - 1; ++i) {
        for (int j = i + 1; j < size; ++j) {
            clock_t start_time = clock();
            if (find(&uf, list[i].RNTI) != find(&uf, list[j].RNTI)) {
                unionSets(&uf, list[i].RNTI, list[j].RNTI);
            }
            clock_t end_time = clock();
            double elapsed_time_ms = ((double)(end_time - start_time) * 1000.0) / CLOCKS_PER_SEC;
            printf("Disjoint check between RNTI %d and %d took %.2f ms\n", list[i].RNTI, list[j].RNTI, elapsed_time_ms);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* generateNfarcrcPduList(int num_pdus) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Failed to allocate memory");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_pdus; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 256;
        list[i].RNTI = rand() % MAX_RNTI;
        list[i].CRC_INDICATION_REL8_TAG = rand();
        list[i].CRCFLAG = rand() % 2;

        // Simulate potential error handling for RNTI retrieval
        if (list[i].RNTI == -1) {
            fprintf(stderr, "Error: Failed to retrieve valid RNTI value.\n");
            free(list);
            return NULL;
        }
    }

    checkDisjointPairs(list, num_pdus);

    return list;
}

void cleanupUnionFind(UnionFind *uf) {
    for (int i = 0; i < MAX_RNTI; ++i) {
        pthread_mutex_destroy(&uf->mutexes[i]);
    }
}
