#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    unsigned char L2_ADDRESS[6];
    unsigned char L3_ADDRESS[8];
} MAC_HEADER;

typedef struct {
    MAC_HEADER header;
    unsigned char *payload;
    size_t payload_size;
} MAC_PDU;

typedef struct {
    MAC_PDU *array;
    size_t count;
    size_t capacity;
} PDU_Manager;

// Mock functions for generating addresses
void generate_L2_ADDRESS(unsigned char *address) {
    // Simulate address generation (e.g., using network services)
    for (int i = 0; i < 6; ++i) {
        address[i] = rand() % 256;
    }
}

void generate_L3_ADDRESS(unsigned char *address) {
    // Simulate address generation
    for (int i = 0; i < 8; ++i) {
        address[i] = rand() % 256;
    }
}

// Function to initialize a MAC_PDU
MAC_PDU* init_mac_pdu(size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE) {
        return NULL;
    }

    MAC_PDU *pdu = malloc(sizeof(MAC_PDU));
    if (!pdu) {
        perror("Failed to allocate memory for MAC_PDU");
        return NULL;
    }

    generate_L2_ADDRESS(pdu->header.L2_ADDRESS);
    generate_L3_ADDRESS(pdu->header.L3_ADDRESS);

    pdu->payload = malloc(payload_size);
    if (!pdu->payload) {
        perror("Failed to allocate memory for payload");
        free(pdu);
        return NULL;
    }

    // Initialize the payload with random data
    for (size_t i = 0; i < payload_size; ++i) {
        pdu->payload[i] = rand() % 256;
    }

    pdu->payload_size = payload_size;

    return pdu;
}

// Function to initialize PDU_Manager
PDU_Manager* init_pdu_manager(size_t initial_capacity) {
    PDU_Manager *manager = malloc(sizeof(PDU_Manager));
    if (!manager) {
        perror("Failed to allocate memory for PDU_Manager");
        return NULL;
    }

    manager->array = calloc(initial_capacity, sizeof(MAC_PDU *));
    if (!manager->array) {
        perror("Failed to allocate memory for PDU array");
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;

    return manager;
}

// Function to append a new MAC_PDU to the manager
int append_pdu(PDU_Manager *manager, size_t payload_size) {
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity ? 2 * manager->capacity : 1;
        MAC_PDU **new_array = realloc(manager->array, new_capacity * sizeof(MAC_PDU *));
        if (!new_array) {
            perror("Failed to reallocate memory for PDU array");
            return -1;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    MAC_PDU *pdu = init_mac_pdu(payload_size);
    if (!pdu) {
        return -1;
    }

    manager->array[manager->count++] = pdu;

    return 0;
}

// Function to safely iterate over PDUs
void iterate_pdus(PDU_Manager *manager, void (*func)(MAC_PDU *)) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]) {
            func(manager->array[i]);
        }
    }
}

// Function to free the PDU_Manager
void free_pdu_manager(PDU_Manager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]) {
            free(manager->array[i]->payload);
            free(manager->array[i]);
        }
    }

    free(manager->array);
    free(manager);
}

// Example usage function
void print_pdu(MAC_PDU *pdu) {
    printf("MAC PDU:\n");
    printf("  L2_ADDRESS: ");
    for (int i = 0; i < 6; ++i) {
        printf("%02x ", pdu->header.L2_ADDRESS[i]);
    }
    printf("\n  L3_ADDRESS: ");
    for (int i = 0; i < 8; ++i) {
        printf("%02x ", pdu->header.L3_ADDRESS[i]);
    }
    printf("\n");
}

int main() {
    srand(time(NULL));

    PDU_Manager *manager = init_pdu_manager(2);
    if (!manager) return EXIT_FAILURE;

    append_pdu(manager, 10);
    append_pdu(manager, 20);

