#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/sysinfo.h>
#include <curl/curl.h>

#define MAX_CONCURRENT_REQUESTS 10

typedef struct {
    char *url;
    int priority;
} Request;

typedef struct {
    CURL *curl_handle;
    char url[256];
    int response_code;
    time_t start_time;
    time_t end_time;
    char error_msg[256];
} RequestData;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int current_concurrent_requests = 0;
CURLM *multi_handle;

void log_request(RequestData *data) {
    printf("Request to %s started at %ld, ended at %ld with response code %d\n",
           data->url,
           (long)data->start_time,
           (long)data->end_time,
           data->response_code);
}

size_t write_callback(void *buffer, size_t size, size_t nmemb, void *userp) {
    return size * nmemb; // We're only interested in the response code for logging
}

void *handle_request(void *arg) {
    RequestData *data = (RequestData *)arg;

    data->curl_handle = curl_easy_init();
    if (!data->curl_handle) {
        strcpy(data->error_msg, "Failed to initialize CURL");
        pthread_mutex_lock(&lock);
        current_concurrent_requests--;
        pthread_mutex_unlock(&lock);
        free(arg);
        return NULL;
    }

    curl_easy_setopt(data->curl_handle, CURLOPT_URL, data->url);
    curl_easy_setopt(data->curl_handle, CURLOPT_WRITEFUNCTION, write_callback);

    data->start_time = time(NULL);
    CURLcode res = curl_easy_perform(data->curl_handle);
    data->response_code = (int)curl_easy_getinfo(data->curl_handle, CURLINFO_RESPONSE_CODE);

    if (res != CURLE_OK) {
        snprintf(data->error_msg, sizeof(data->error_msg), "CURL error: %s", curl_easy_strerror(res));
    }

    data->end_time = time(NULL);

    log_request(data);

    curl_easy_cleanup(data->curl_handle);

    pthread_mutex_lock(&lock);
    current_concurrent_requests--;
    pthread_mutex_unlock(&lock);

    free(arg);
    return NULL;
}

void adjust_concurrency() {
    struct sysinfo info;
    sysinfo(&info);
    int available_memory = (int)(info.freeram / 1024);

    // Adjust based on memory usage, simple heuristic
    if (available_memory < 512 * 1024) { // less than 512MB free
        pthread_mutex_lock(&lock);
        current_concurrent_requests = MAX_CONCURRENT_REQUESTS / 2;
        pthread_mutex_unlock(&lock);
    } else {
        pthread_mutex_lock(&lock);
        current_concurrent_requests = MAX_CONCURRENT_REQUESTS;
        pthread_mutex_unlock(&lock);
    }
}

void execute_requests(Request *requests, int count) {
    pthread_t threads[count];
    multi_handle = curl_multi_init();

    for (int i = 0; i < count; ++i) {
        while (current_concurrent_requests >= MAX_CONCURRENT_REQUESTS) {
            usleep(100000); // Sleep for 100ms to prevent busy waiting
        }

        pthread_mutex_lock(&lock);
        current_concurrent_requests++;
        pthread_mutex_unlock(&lock);

        RequestData *data = malloc(sizeof(RequestData));
        strcpy(data->url, requests[i].url);

        pthread_create(&threads[i], NULL, handle_request, data);
    }

    for (int i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }

    curl_multi_cleanup(multi_handle);
}

void manage_requests(Request *requests, int count) {
    // Sort requests based on priority
    for (int i = 0; i < count - 1; i++) {
        for (int j = i + 1; j < count; j++) {
            if (requests[i].priority > requests[j].priority) {
                Request temp = requests[i];
                requests[i] = requests[j];
                requests[j] = temp;
            }
        }
    }

    while (count--) {
        adjust_concurrency();
        execute_requests(requests, count);
    }
}

int main() {
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Example list of URLs with priorities
    Request urls[] = {{"http://example.com", 1}, {"http://another.com", 2}};
    int url_count = sizeof(urls) / sizeof(Request);

    manage_requests(urls, url_count);

    curl_global_cleanup();
    return 0;
}
```

