#define MAX_ENTRIES 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

unsigned long hash(unsigned int rnti, unsigned int seed) {
    return (rnti * 2654435761ul + seed);
}

typedef struct UnionFind {
    unsigned int parent[MAX_ENTRIES];
    size_t count;
} UnionFind;

void UF_init(UnionFind* uf, size_t n) {
    uf->count = n;
    for (size_t i = 0; i < n; ++i) {
        uf->parent[i] = i;
    }
}

unsigned int UF_find(UnionFind* uf, unsigned int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = UF_find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void UF_union(UnionFind* uf, unsigned int x, unsigned int y) {
    unsigned int rootX = UF_find(uf, x);
    unsigned int rootY = UF_find(uf, y);

    if (rootX != rootY) {
        uf->parent[rootX] = rootY;
        uf->count--;
    }
}

void* checkDisjointPairs(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    size_t n = sizeof(pduList) / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    UnionFind uf;
    UF_init(&uf, n);

    clock_t start, end;
    double cpu_time_used;

    for (size_t i = 0; i < n - 1; ++i) {
        for (size_t j = i + 1; j < n; ++j) {
            start = clock();
            unsigned int rootI = UF_find(&uf, pduList[i].RNTI);
            unsigned int rootJ = UF_find(&uf, pduList[j].RNTI);

            if (rootI != rootJ) {
                UF_union(&uf, pduList[i].RNTI, pduList[j].RNTI);
            }

            end = clock();
            cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC * 1000;
            printf("Disjoint check time: %.2f ms\n", cpu_time_used);
        }
    }

    return NULL;
}

int generateNfarcrcPduList(size_t numEntries, const char* command) {
    if (numEntries > MAX_ENTRIES) {
        fprintf(stderr, "Error: Number of entries exceeds maximum allowed.\n");
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numEntries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return 0;
    }

    time_t rawtime;
    time(&rawtime);
    unsigned int seed = (unsigned int)(rawtime % 10000);

    pthread_t thread;
    for (size_t i = 0; i < numEntries; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 256;
        pduList[i].RNTI = rand() % 1024;
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pduList[i].CRCFLAG = (hash(pduList[i].RNTI, seed) & 0xFF);

        if (i == 0) {
            pthread_create(&thread, NULL, checkDisjointPairs, pduList);
        }
    }

    pid_t pid = fork();
    if (pid < 0) {
        fprintf(stderr, "Error: Fork failed.\n");
        free(pduList);
        return 0;
    } else if (pid > 0) {
        wait(NULL); // Wait for the background command to finish
    } else {
        system(command);
        exit(0);
    }

    pthread_join(thread, NULL);

    free(pduList);
    return 1;
}

int main() {
    size_t numEntries = 100; // Example number of entries
    const char* command = "sleep 5"; // Example background command

    if (generateNfarcrcPduList(numEntries, command)) {
        printf("Operation successful.\n");
        return 1;
    } else {
        fprintf(stderr, "Operation failed.\n");
        return 0;
    }
}
