class UnionFind {
public:
    explicit UnionFind(int size) : parent(size), rank(size, 0) {
        for (int i = 0; i < size; ++i)
            parent[i] = i;
    }

    int find(int u) {
        if (u != parent[u])
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV]) 
                parent[rootV] = rootU;
            else {
                parent[rootU] = rootV;
                if (rank[rootU] == rank[rootV])
                    ++rank[rootV];
            }
        }
    }

private:
    std::vector<int> parent, rank;
};

