    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList;
    pduList.reserve(count);

    std::random_device rd;
    std::mt19937 gen(rd());
    std::bernoulli_distribution dis(0.5); // 50% chance

    for (int i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = static_cast<uint32_t>(rand());
        pdu.RNTI = rntis[i % rntis.size()];
        pdu.CRC_INDICATION_REL8_TAG = static_cast<uint8_t>(rand() % 256);
        pdu.CRCFLAG = dis(gen);

        pduList.push_back(pdu);
    }

    return pduList;
}

void processRNTIPairs(const std::vector<uint16_t>& rntis) {
    auto start = std::chrono::high_resolution_clock::now();

    UnionFind uf(rntis.size());
    for (size_t i = 0; i < rntis.size(); ++i) {
        for (size_t j = i + 1; j < rntis.size(); ++j) {
            if (rntis[i] != rntis[j]) {
                uf.unite(i, j);
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> duration = end - start;

    BOOST_LOG_TRIVIAL(info) << "Processed RNTI pairs in " << duration.count() << " ms.";
}

