#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example limit, e.g., 1MB
#define LOG_FILE "nfa_pi_log.txt"

typedef struct {
    unsigned int rnti;
    char rx_ue_info_tag[128];
} RX_UE_INFORMATION_TAG;

typedef struct {
    int crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPIDynamicList;

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) return;

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int is_memory_limit_exceeded(size_t current_usage) {
    return current_usage > MAX_MEMORY_USAGE;
}

NFAPIDynamicList* create_nfa_dynamic_list() {
    NFAPIDynamicList *list = (NFAPIDynamicList*)malloc(sizeof(NFAPIDynamicList));
    if (!list) {
        log_message("Failed to allocate memory for list structure.");
        return NULL;
    }

    list->data = NULL;
    list->size = 0;
    list->capacity = 10; // Initial capacity
    pthread_mutex_init(&list->lock, NULL);

    size_t current_usage = sizeof(NFAPIDynamicList);
    NFAPI_CRC_INDICATION_PDU_T *elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!elements) {
        log_message("Failed to allocate initial memory for list elements.");
        free(list);
        return NULL;
    }

    current_usage += list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (is_memory_limit_exceeded(current_usage)) {
        free(elements);
        free(list);
        log_message("Memory limit exceeded during initialization.");
        return NULL;
    }

    list->data = elements;
    return list;
}

int add_pdu_to_list(NFAPIDynamicList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            log_message("Failed to resize memory for list elements.");
            return -1;
        }

        size_t current_usage = (list->capacity + new_capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (is_memory_limit_exceeded(current_usage)) {
            free(new_data);
            pthread_mutex_unlock(&list->lock);
            log_message("Memory limit exceeded during resizing.");
            return -1;
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &list->data[list->size];

    // Populate with example data, randomizing the CRCFLAG
    memset(new_pdu->ue_info_tag.rx_ue_info_tag, 'A', sizeof(new_pdu->ue_info_tag.rx_ue_info_tag) - 1);
    new_pdu->ue_info_tag.rx_ue_info_tag[sizeof(new_pdu->ue_info_tag.rx_ue_info_tag) - 1] = '\0';

    new_pdu->rnti = rand() % 100000; // Example random RNTI
    new_pdu->crc_indication_rel8_tag.crcflag = rand() & 1; // Randomly set CRCFLAG

    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_nfa_dynamic_list(NFAPIDynamicList *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);

        if (list->data) {
            free(list->data);
        }

        free(list);
    }
}

int main() {
    srand(time(NULL));
    NFAPIDynamicList *nfa_list = create_nfa_dynamic_list();

    if (!nfa_list) {
        log_message("Failed to create NFA dynamic list.");
        return -1;
    }

    const int num_elements = 100; // Example number of elements
    for (int i = 0; i < num_elements; ++i) {
        if (add_pdu_to_list(nfa_list) != 0) {
            log_message("Failed to add PDU to list.");
        }
    }

    free_nfa_dynamic_list(nfa_list);
    return 0;
}
