    UE_INFO_T RX_UE_INFORMATION_TAG;
    CRC_INDICATION_PDU_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global list for PDU instances
NFAPI_CRC_INDICATION_PDU_T* global_pdus = NULL;
size_t pdu_count = 0;
pthread_mutex_t pdu_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Memory pool structure (simplified)
typedef struct {
    size_t block_size;
    void** free_blocks;
    size_t num_free_blocks;
} MemoryPool;

MemoryPool mem_pool = { sizeof(NFAPI_CRC_INDICATION_PDU_T), NULL, 0 };

void initialize_memory_pool(size_t num_blocks) {
    mem_pool.free_blocks = malloc(num_blocks * sizeof(void*));
    for (size_t i = 0; i < num_blocks; ++i) {
        mem_pool.free_blocks[i] = malloc(mem_pool.block_size);
    }
    mem_pool.num_free_blocks = num_blocks;
}

void* pool_alloc() {
    if (mem_pool.num_free_blocks == 0) return NULL;

    void* block = mem_pool.free_blocks[--mem_pool.num_free_blocks];
    memset(block, 0, mem_pool.block_size); // Ensure zero-initialization
    return block;
}

void pool_free(void* block) {
    mem_pool.free_blocks[mem_pool.num_free_blocks++] = block;
}

// Logging function
void log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdus(size_t N, unsigned int seed, UE_INFO_T* ue_info_array) {
    srand(seed); // Seed the random number generator
    if (mem_pool.free_blocks == NULL || mem_pool.num_free_blocks < N) {
        log_message("Error: Insufficient memory pool blocks.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(*pdus));
    if (!pdus) {
        log_message("Error: Failed to allocate PDUs array.");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        void* block = pool_alloc();
        if (!block) {
            // Cleanup in case of allocation failure
            for (size_t j = 0; j < i; ++j) {
                free(pdus[j].CRC_INDICATION_REL8_TAG);
            }
            free(pdus);
            log_message("Error: Allocation failed during PDUs creation.");
            return NULL;
        }

        pdus[i] = *(NFAPI_CRC_INDICATION_PDU_T*)block;
        pdus[i].RX_UE_INFORMATION_TAG.RNTI = ue_info_array[i].RNTI;
        pdus[i].RX_UE_INFORMATION_TAG.RX_UE_INFORMATION_TAG = i; // Example tag
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        pthread_mutex_lock(&pdu_list_lock);
        if (global_pdus) {
            size_t old_count = pdu_count;
            global_pdus = realloc(global_pdus, (old_count + 1) * sizeof(*pdus));
            if (!global_pdus) {
                log_message("Error: Failed to append PDU to global list.");
                pthread_mutex_unlock(&pdu_list_lock);
                pool_free(block); // Rollback allocation
                free(pdus);
                return NULL;
            }
            global_pdus[old_count] = pdus[i];
            ++pdu_count;
        } else {
            global_pdus = malloc(sizeof(*pdus));
            *global_pdus = pdus[i];
            pdu_count = 1;
        }
        pthread_mutex_unlock(&pdu_list_lock);
    }

    log_message("PDUs successfully created and added to the global list.");
    return pdus;
}

// Unit Test Example
void test_create_pdus() {
    UE_INFO_T ue_info_array[] = { {123, 0}, {456, 1} };
    NFAPI_CRC_INDICATION_PDU_T* result = create_pdus(2, 42, ue_info_array);

    if (result) {
        printf("Test Passed: %zu PDUs created.\n", pdu_count);
    } else {
        printf("Test Failed: PDU creation unsuccessful.\n");
    }

    free(result); // Clean up
}

int main() {
    initialize_memory_pool(10); // Initialize memory pool with 10 blocks
    test_create_pdus();
    return 0;
}
```

### Notes:
1. **Memory Pool**: A simple memory pool is implemented to manage allocations and minimize fragmentation.
2. **Thread Safety**: A mutex lock (`pthread_mutex_t`) ensures safe access to the global list of PDUs across threads.
3. **Logging**: Uses `printf` for logging with timestamps, ensuring minimal performance impact during normal operation.
4. **Error Handling**: Allocates memory carefully and rolls back in case of failure, freeing allocated resources appropriately.
5. **Unit Test**: Basic test function verifies functionality under expected conditions.

This code is designed to balance efficiency with robustness, considering the trade-offs between validation, logging, and performance.']

