        selected_config.iv_length == 0) {
        log_error("Invalid or missing IV length.");
        EVP_CIPHER_CTX_free(ctx);
        CONF_free(conf);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_error("Failed to create cipher context.");
        EVP_CIPHER_CTX_free(ctx);
        CONF_free(conf);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Initialize the cipher context
    if (EVP_EncryptInit_ex(ctx, selected_config.cipher, NULL, NULL, NULL) != 1) {
        log_error("Failed to initialize encryption.");
        EVP_CIPHER_CTX_free(ctx);
        CONF_free(conf);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Log the configuration
    char cipher_name[256];
    if (EVP_CIPHER_get0_name(selected_config.cipher, cipher_name, sizeof(cipher_name)) > 0) {
        log_info("Selected Cipher: %s", cipher_name);
        log_info("Key Length: %u bits", selected_config.key_length * 8);
        log_info("IV Length: %u bytes", selected_config.iv_length);
    } else {
        log_error("Failed to get cipher name.");
        EVP_CIPHER_CTX_free(ctx);
        CONF_free(conf);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Clean up and unlock
    CONF_free(conf);
    pthread_mutex_unlock(&lock);

    return ctx; // Return the initialized context, or NULL if failed.
