typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned short CRCFLAG;
} CRC_INDICATION_REL8_TAG;

struct EfficientArray {
    int *data;
    size_t size;
};

int* read_and_validate_integers(size_t* count) {
    char input[1024];
    char* token = NULL;
    char* str = fgets(input, sizeof(input), stdin);
    if (!str) return NULL;

    size_t capacity = 10;
    int* array = malloc(capacity * sizeof(int));
    if (!array) exit(EXIT_FAILURE);

    *count = 0;
    while ((token = strtok(*count == 0 ? str : NULL, " \n")) != NULL) {
        char* endptr;
        long val = strtol(token, &endptr, 10);
        if (*endptr == '\0' && LONG_MIN <= val && val <= INT_MAX) {
            if (*count >= capacity) {
                capacity *= 2;
                array = realloc(array, capacity * sizeof(int));
                if (!array) exit(EXIT_FAILURE);
            }
            array[(*count)++] = (int)val;
        } else {
            fprintf(stderr, "Invalid integer: %s\n", token);
        }
    }

    return (*count > 0) ? array : NULL;
}

int get_largest_int(struct EfficientArray* arr) {
    if (arr->size == 0) return INT_MIN;

    int max = arr->data[0];
    for (size_t i = 1; i < arr->size; ++i) {
        if (arr->data[i] > max)
            max = arr->data[i];
    }
    return max;
}

bool validate_and_store_NFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T* pduArray, size_t* count) {
    // Assume valid RX_UE_INFORMATION_TAG and RNTI are non-zero
    *count = 0;
    size_t capacity = 10;
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return false;

    while (scanf("%hu %u", &pduArray[*count].RX_UE_INFORMATION_TAG, &pduArray[*count].RNTI) == 2) {
        if (pduArray[*count].RX_UE_INFORMATION_TAG == 0 || pduArray[*count].RNTI == 0) {
            fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG or RNTI: %hu %u\n", 
                    pduArray[*count].RX_UE_INFORMATION_TAG, pduArray[*count].RNTI);
        } else if (*count >= capacity) {
            capacity *= 2;
            array = realloc(array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!array) return false;
        }
        array[(*count)++] = pduArray[*count - 1];
    }

    free(pduArray);
    pduArray = array;
    return true;
}

void set_random_crcflag(CRC_INDICATION_REL8_TAG* tag) {
    // Use simple pseudo-random generator for demonstration
    static unsigned int seed = 12345; 
    srand(seed);
    tag->CRCFLAG = rand() % 2;
    ++seed; // Ensure different random number next time
}

void process_input_and_manage_structures() {
    size_t integerCount = 0;
    struct EfficientArray arr = { .data = read_and_validate_integers(&integerCount), .size = integerCount };
    if (arr.data) {
        printf("Largest Integer: %d\n", get_largest_int(&arr));
        free(arr.data);
    }

    size_t pduCount = 0;
    NFAPI_CRC_INDICATION_PDU_T* pduArray = malloc(10 * sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Initial allocation
    if (pduArray && validate_and_store_NFAPI_CRC_INDICATION_PDU(pduArray, &pduCount)) {
        for (size_t i = 0; i < pduCount; ++i) {
            CRC_INDICATION_REL8_TAG crcTag;
            set_random_crcflag(&crcTag);
            printf("PDU[%zu] RX_UE_INFORMATION_TAG: %hu RNTI: %u CRCFLAG: %d\n", 
                   i, pduArray[i].RX_UE_INFORMATION_TAG, pduArray[i].RNTI, crcTag.CRCFLAG);
        }
        free(pduArray);
    }
}

int main() {
    process_input_and_manage_structures();
    return 0;
}
