typedef enum {
    AES,
    CHACHA20
} CipherType;

typedef enum {
    CBC_MODE,
    GCM_MODE,
    CTR_MODE
} BlockCipherMode;

EVP_CIPHER_CTX* initialize_cipher(CipherType type, BlockCipherMode mode, const unsigned char *key, size_t key_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        LOG_ERROR("Failed to create cipher context.\n");
        return NULL;
    }

    int block_size;
    int iv_len;

    switch (type) {
        case AES: {
            switch (mode) {
                case CBC_MODE:
                    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
                        LOG_ERROR("Failed to initialize AES-CBC.\n");
                        return NULL;
                    }
                    block_size = 16; // AES block size
                    iv_len = block_size;
                    break;

                case GCM_MODE:
                    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, NULL)) {
                        LOG_ERROR("Failed to initialize AES-GCM.\n");
                        return NULL;
                    }
                    block_size = 16; // AES block size
                    iv_len = 12; // Recommended IV length for GCM
                    break;

                case CTR_MODE:
                    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_ctr(), NULL, key, NULL)) {
                        LOG_ERROR("Failed to initialize AES-CTR.\n");
                        return NULL;
                    }
                    block_size = 16; // AES block size
                    iv_len = block_size;
                    break;

                default:
                    LOG_ERROR("Unsupported mode for AES.\n");
                    EVP_CIPHER_CTX_free(ctx);
                    return NULL;
            }
        } break;

        case CHACHA20: {
            switch (mode) {
                case CTR_MODE:
                    if (!EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, key, NULL)) {
                        LOG_ERROR("Failed to initialize ChaCha20-Poly1305.\n");
                        return NULL;
                    }
                    block_size = 64; // ChaCha20 block size
                    iv_len = 12; // Recommended IV length for ChaCha20-Poly1305
                    break;

                default:
                    LOG_ERROR("Unsupported mode for ChaCha20.\n");
                    EVP_CIPHER_CTX_free(ctx);
                    return NULL;
            }
        } break;

        default:
            LOG_ERROR("Unsupported cipher type.\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
    }

    unsigned char iv[16];
    if (!RAND_bytes(iv, sizeof(iv) > iv_len ? iv_len : sizeof(iv))) {
        LOG_ERROR("Failed to generate IV.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv)) {
        LOG_ERROR("Failed to set key and IV.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Log success for debugging purposes
    printf("Cipher initialized successfully: %s\n", type == AES ? "AES" : "ChaCha20");

    return ctx;
}

void finalize_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
