NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t N) {
    if (N < 1 || N > 1000) {
        fprintf(stderr, "Error: Invalid input size %zu. Must be between 1 and 1000.\n", N);
        return NULL;
