    pthread_mutex_lock(&allocation_mutex);

    // Update total allocation count safely
    if (__sync_add_and_fetch(&total_allocations, N) > MAX_ALLOCATION_THRESHOLD) {
        fprintf(stderr, "Warning: Allocation threshold exceeded.\n");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
