    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = fetch_RX_UE_INFORMATION_TAG();
        array[i].RNTI = fetch_RNTI();
        array[i].CRC_INDICATION_REL8_TAG = rand(); // Unique tag
        array[i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    return array;
}

// Function to free the allocated memory
void free_nfaapi_crc_array(NFAPI_CRC_INDICATION_PDU_T* array) {
