        free(array);
    }
}

// Semaphore handling functions
int create_and_delete_semaphore(pthread_mutex_t *mutex, pthread_cond_t *cond, int initial_value) {
    // Initialize mutex and condition variable
    if (pthread_mutex_init(mutex, NULL) != 0 || pthread_cond_init(cond, NULL) != 0) {
        fprintf(stderr, "Error: Failed to initialize synchronization primitives.\n");
        return -1;
    }

    // Initial value setup for semaphore logic (not an actual semaphore)
    int count = initial_value;

    // Example usage scenario
    pthread_mutex_lock(mutex);
    while (count <= 0) {
        pthread_cond_wait(cond, mutex); // Wait if no resources available
    }
    --count; // Acquire resource
    pthread_mutex_unlock(mutex);

    // Cleanup
    pthread_mutex_destroy(mutex);
    pthread_cond_destroy(cond);

    return 0;
}

int main() {
