        free_nfaapi_crc_array(nfaapi_array);
    }

    pthread_mutex_t mutex;
    pthread_cond_t cond;

    // Create and delete semaphore logic
    create_and_delete_semaphore(&mutex, &cond, 5);

    return 0;
}
