#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_MEMORY_LIMIT 1048576 // Example limit in bytes

typedef struct {
    int RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    char RX_UE_INFORMATION_TAG[256];
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFALIST;

NFALIST* create_nfalist(size_t initial_capacity) {
    NFALIST* list = (NFALIST*)malloc(sizeof(NFALIST));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_nfalist(NFALIST* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}

int add_to_list(NFALIST* list, const NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity || 
        (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY_LIMIT) {
        pthread_mutex_unlock(&list->lock);
        log_warning("Memory limit reached or capacity exceeded");
        return -1;
    }

    memcpy(&list->data[list->size], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void log_warning(const char* message) {
    time_t now = time(NULL);
    FILE* log_file = fopen("nfa_list.log", "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

void filter_by_rnti(NFALIST* list, int rnti, NFAPI_CRC_INDICATION_PDU_T** filtered_data, size_t* count) {
    pthread_mutex_lock(&list->lock);

    *count = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].tag.RNTI == rnti) {
            (*count)++;
        }
    }

    *filtered_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    size_t j = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].tag.RNTI == rnti) {
            memcpy(&((*filtered_data)[j]), &list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            j++;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void update_entry(NFALIST* list, size_t index, const NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&list->lock);

    if (index < list->size) {
        memcpy(&list->data[index], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        log_warning("Update failed: index out of range");
    }

    pthread_mutex_unlock(&list->lock);
}

void performance_metrics(NFALIST* list) {
    pthread_mutex_lock(&list->lock);

    printf("Current size: %zu\n", list->size);
    printf("Capacity: %zu\n", list->capacity);

    pthread_mutex_unlock(&list->lock);
}

// Example usage:
int main() {
    NFALIST* nfalist = create_nfalist(10);

    NFAPI_CRC_INDICATION_PDU_T item;
    strcpy(item.RX_UE_INFORMATION_TAG, "ExampleTag");
    item.tag.RNTI = 1234;
    item.tag.CRCFLAG = rand() % 2;

    add_to_list(nfalist, &item);
    performance_metrics(nfalist);

    NFAPI_CRC_INDICATION_PDU_T* filtered_data;
    size_t count;
    filter_by_rnti(nfalist, 1234, &filtered_data, &count);

    for (size_t i = 0; i < count; ++i) {
        printf("Filtered RNTI: %d\n", filtered_data[i].tag.RNTI);
    }

    free(filtered_data);
    destroy_nfalist(nfalist);
    return 0;
}
