typedef struct {
    TX_FRAME_INFO *frames;
    size_t capacity;
    size_t count;
} DynamicFrameArray;

// Initialize the dynamic frame array
DynamicFrameArray* init_dynamic_frame_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicFrameArray *dfa = malloc(sizeof(DynamicFrameArray));
    if (!dfa) return NULL;

    dfa->frames = calloc(initial_capacity, sizeof(TX_FRAME_INFO));
    if (!dfa->frames) {
        free(dfa);
        return NULL;
    }

    dfa->capacity = initial_capacity;
    dfa->count = 0;
    return dfa;
}

// Resize the dynamic frame array
int resize_dynamic_frame_array(DynamicFrameArray *dfa, size_t new_capacity) {
    if (!dfa || !new_capacity) return -1;

    TX_FRAME_INFO *temp = realloc(dfa->frames, new_capacity * sizeof(TX_FRAME_INFO));
    if (!temp) return -1;

    dfa->frames = temp;
    dfa->capacity = new_capacity;
    return 0;
}

// Add a new frame or update an existing one
int add_or_update_frame(DynamicFrameArray *dfa, unsigned long frame_id, TX_RLC_PDU rlc_pdu, TX_PHY_PDU phy_pdu) {
    if (!dfa || !rlc_pdu || !phy_pdu) return -1;

    // Search for the frame by ID
    size_t i;
    for (i = 0; i < dfa->count; ++i) {
        if (dfa->frames[i].frame_id == frame_id) break;
    }

    // If not found, resize array if necessary and add new frame
    if (i == dfa->count) {
        if (dfa->count == dfa->capacity) {
            size_t new_capacity = dfa->capacity * 2;
            if (resize_dynamic_frame_array(dfa, new_capacity)) return -1; // Handle allocation failure gracefully
        }

        TX_FRAME_INFO *frame = &dfa->frames[dfa->count++];
        frame->frame_id = frame_id;
    } else {
        // Frame found, update existing one
        TX_FRAME_INFO *frame = &dfa->frames[i];
    }

    // Update or set the RLC and PHY PDU information
    TX_FRAME_INFO *frame = (i == dfa->count - 1) ? &dfa->frames[dfa->count - 1] : &dfa->frames[i];
    frame->rlc_pdu = rlc_pdu;
    frame->phy_pdu = phy_pdu;
    frame->timestamp = time(NULL);
    frame->transmission_status = 0; // Not transmitted

    return 0;
}

// Retrieve a frame by its unique identifier
TX_FRAME_INFO* get_frame(DynamicFrameArray *dfa, unsigned long frame_id) {
    if (!dfa) return NULL;

    for (size_t i = 0; i < dfa->count; ++i) {
        if (dfa->frames[i].frame_id == frame_id)
            return &dfa->frames[i];
    }

    return NULL;
}

// Free the dynamic frame array
void free_dynamic_frame_array(DynamicFrameArray *dfa) {
    if (!dfa) return;

    free(dfa->frames);
    free(dfa);
}

int main() {
    DynamicFrameArray *dfa = init_dynamic_frame_array(10);

    // Example usage
    TX_RLC_PDU rlc_pdu = {.rlc_pdu_id = 1};
    TX_PHY_PDU phy_pdu = {.phy_pdu_id = 1};

    add_or_update_frame(dfa, 1001, rlc_pdu, phy_pdu);

    TX_FRAME_INFO *frame = get_frame(dfa, 1001);
