['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>
#include <semaphore.h>

// Task structure definition
typedef struct Task {
    void (*function)(void*);
    void* argument;
    struct Task* next;
} Task;

// Thread pool structure definition
typedef struct ThreadPool {
    pthread_mutex_t lock;
    sem_t task_count;
    pthread_cond_t notify;
    pthread_t* threads;
    Task* tasks;
    int thread_count;
    int queue_size;
    int stop;
} ThreadPool;

// Function prototypes
ThreadPool* create_thread_pool(int thread_count, int queue_size);
void destroy_thread_pool(ThreadPool* pool);
int submit_task(ThreadPool* pool, void (*function)(void*), void* argument);
static void* worker(void* arg);

// Create a new thread pool
ThreadPool* create_thread_pool(int thread_count, int queue_size) {
    ThreadPool* pool = (ThreadPool*)malloc(sizeof(ThreadPool));
    if (!pool) return NULL;

    pool->thread_count = thread_count;
    pool->queue_size = queue_size;
    pool->stop = 0;

    pthread_mutex_init(&(pool->lock), NULL);
    sem_init(&(pool->task_count), 0, 0);
    pthread_cond_init(&(pool->notify), NULL);

    pool->threads = (pthread_t*)malloc(sizeof(pthread_t) * thread_count);
    pool->tasks = NULL;

    if (!pool->threads) {
        destroy_thread_pool(pool);
        return NULL;
    }

    for (int i = 0; i < thread_count; ++i) {
        if (pthread_create(&(pool->threads[i]), NULL, worker, (void*)pool)) {
            destroy_thread_pool(pool);
            return NULL;
        }
    }

    return pool;
}

// Destroy the thread pool
void destroy_thread_pool(ThreadPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&(pool->lock));
    pool->stop = 1;
    sem_post(&(pool->task_count)); // Wake up all worker threads.
    pthread_cond_broadcast(&(pool->notify));

    for (int i = 0; i < pool->thread_count; ++i) {
        pthread_join(pool->threads[i], NULL);
    }

    Task* task;
    while ((task = pool->tasks)) {
        pool->tasks = task->next;
        free(task);
    }

    pthread_mutex_unlock(&(pool->lock));
    pthread_mutex_destroy(&(pool->lock));
    sem_destroy(&(pool->task_count));
    pthread_cond_destroy(&(pool->notify));

    free(pool->threads);
    free(pool);
}

// Submit a new task to the thread pool
int submit_task(ThreadPool* pool, void (*function)(void*), void* argument) {
    if (!pool || !function) return -1;

    Task* new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) return -1;

    new_task->function = function;
    new_task->argument = argument;
    new_task->next = NULL;

    pthread_mutex_lock(&(pool->lock));

    // Enqueue task
    if (!pool->tasks) {
        pool->tasks = new_task;
    } else {
        Task* last = pool->tasks;
        while (last->next) last = last->next;
        last->next = new_task;
    }

    pthread_cond_signal(&(pool->notify));
    sem_post(&(pool->task_count));

    pthread_mutex_unlock(&(pool->lock));

    return 0;
}

// Worker thread function
static void* worker(void* arg) {
    ThreadPool* pool = (ThreadPool*)arg;

    while (1) {
        sem_wait(&(pool->task_count));

        pthread_mutex_lock(&(pool->lock));

        // Check if we are to stop
        while (!pool->tasks && !pool->stop) {
            pthread_cond_wait(&(pool->notify), &(pool->lock));
        }

        if (pool->stop && !(pool->tasks)) {
            pthread_mutex_unlock(&(pool->lock));
            break;
        }

        Task* task = pool->tasks;
        pool->tasks = task->next;

        pthread_mutex_unlock(&(pool->lock));

        (*(task->function))(task->argument);
        free(task);
    }

    return NULL;
}

// Example usage
