    int thread_count = 4; // Example value, should be configurable
    int queue_size = 10;  // Example value, should be configurable

    ThreadPool* pool = create_thread_pool(thread_count, queue_size);
    if (!pool) {
        fprintf(stderr, "Failed to create thread pool\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 20; ++i) {
