Graph* create_graph(size_t initial_size) {
    Graph *graph = (Graph *)malloc(sizeof(Graph));
    graph->vertices = (GraphNode **)calloc(initial_size, sizeof(GraphNode *));
    graph->num_vertices = 0;
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

void destroy_graph(Graph *graph) {
    for (size_t i = 0; i < graph->num_vertices; ++i) {
        GraphNode *node = graph->vertices[i];
        free(node->edges);
        pthread_rwlock_destroy(&node->rwlock);
        free(node->vertex_data); // Assume custom cleanup
        free(node);
    }
    free(graph->vertices);
    pthread_mutex_destroy(&graph->lock);
    free(graph);
}

GraphNode* add_vertex(Graph *graph, void *data) {
    pthread_mutex_lock(&graph->lock);

    GraphNode *node = (GraphNode *)malloc(sizeof(GraphNode));
    node->vertex_data = data;
    node->edges = NULL;
    node->num_edges = 0;
    pthread_rwlock_init(&node->rwlock, NULL);
    graph->vertices[graph->num_vertices++] = node;

    if (graph->num_vertices % 10 == 0) {
        graph->vertices = (GraphNode **)realloc(graph->vertices, graph->num_vertices * sizeof(GraphNode *));
    }

    pthread_mutex_unlock(&graph->lock);
    return node;
}

void add_edge(Graph *graph, GraphNode *from, GraphNode *to) {
    pthread_rwlock_wrlock(&from->rwlock);

    from->edges = (GraphNode **)realloc(from->edges, (from->num_edges + 1) * sizeof(GraphNode *));
    from->edges[from->num_edges++] = to;

    pthread_rwlock_unlock(&from->rwlock);
}

