#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>
#include <atomic>

// Mocking NetworkManager class using a test double
class TestNetworkManager {
public:
    bool GetRequestStatus() {
        static std::mt19937 rng(std::random_device{}());
        static std::uniform_real_distribution<double> dist(0.0, 1.0);
        // Simulate a 30% failure rate for requests
        return dist(rng) > 0.3;
    }

    void SendRequest(int requestId) {
        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 401 + 100)); // Random delay between 100ms and 500ms
        if (GetRequestStatus()) {
            std::cout << "Request " << requestId << " succeeded.\n";
        } else {
            std::cerr << "Request " << requestId << " failed.\n";
        }
    }
};

class ConnectionPool {
private:
    const size_t maxSimultaneousConnections = 20;
    const int retryLimit = 5;
    TestNetworkManager networkManager;
    std::queue<int> requestQueue;
    std::mutex mtx;
    std::condition_variable cv;
    bool stopFlag = false;
    std::atomic<size_t> activeConnections{0};
    size_t totalRequests = 0, successfulRequests = 0, failedRequests = 0, retryAttempts = 0;

public:
    ConnectionPool() {
        for (size_t i = 0; i < maxSimultaneousConnections; ++i) {
            std::thread(&ConnectionPool::Worker, this).detach();
        }
    }

    ~ConnectionPool() {
        stopFlag = true;
        cv.notify_all();
    }

    void AddRequest(int requestId) {
        std::unique_lock<std::mutex> lock(mtx);
        requestQueue.push(requestId);
        totalRequests++;
        cv.notify_one();
    }

    void Worker() {
        while (!stopFlag) {
            int requestId;
            {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !requestQueue.empty() || stopFlag; });

                if (stopFlag && requestQueue.empty()) break;

                requestId = requestQueue.front();
                requestQueue.pop();

                while (activeConnections >= maxSimultaneousConnections) {
                    cv.wait(lock);
                }
            }

            activeConnections++;
            ProcessRequest(requestId);

            std::unique_lock<std::mutex> lock(mtx);
            activeConnections--;
            cv.notify_all();
        }
    }

private:
    void ProcessRequest(int requestId, int attempt = 0) {
        if (attempt > retryLimit) {
            failedRequests++;
            return;
        }

        try {
            networkManager.SendRequest(requestId);

            if (networkManager.GetRequestStatus()) {
                successfulRequests++;
            } else {
                throw std::runtime_error("Simulated failure");
            }
        } catch (...) {
            retryAttempts++;
            int delay = std::pow(2, attempt) * 100; // Exponential backoff
            std::this_thread::sleep_for(std::chrono::milliseconds(delay));
            ProcessRequest(requestId, attempt + 1);
        }
    }

public:
    void PrintMetrics() const {
        double averageResponseTime = totalRequests > 0 ? (retryAttempts + successfulRequests) / static_cast<double>(totalRequests) * 100 : 0;
        std::cout << "Total Requests: " << totalRequests << "\n";
        std::cout << "Successful Requests: " << successfulRequests << "\n";
        std::cout << "Failed Requests: " << failedRequests << "\n";
        std::cout << "Retry Attempts: " << retryAttempts << "\n";
        std::cout << "Average Response Time (ms): " << averageResponseTime << "\n";
    }
};

int main() {
    ConnectionPool pool;

    // Simulate incoming requests
    for (int i = 0; i < 100; ++i) {
        pool.AddRequest(i);
    }

    std::this_thread::sleep_for(std::chrono::seconds(5)); // Allow some time for processing

    pool.PrintMetrics();

    return 0;
}
