    crcflag: bool

@dataclass
class NFAPI_CRC_INDICATION_PDU_T:
    rx_ue_information_tag: RX_UE_INFORMATION_TAG
    rnti: RNTI
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG

# Configuration and utility classes
class ConfigLoader:
    def __init__(self, config_files):
        self.config_files = config_files

    def load_config(self):
        # Load configuration from files (placeholder for actual implementation)
        return {"batch_size": 10, "logging_level": logging.INFO}

class MemoryManager:
    _lock = threading.Lock()

    @classmethod
    def allocate(cls, n):
        with cls._lock:
            try:
                return [NFAPI_CRC_INDICATION_PDU_T(
                    RX_UE_INFORMATION_TAG(random.randint(1, 100)),
                    RNTI(random.randint(101, 200)),
                    CRC_INDICATION_REL8_TAG(crcflag=random.choice([True, False]))
                ) for _ in range(n)]
            except MemoryError:
                logging.error("Memory allocation failed.")
                return None

    @classmethod
    def deallocate(cls, array):
        with cls._lock:
            # In Python, explicit deallocation isn't necessary due to garbage collection.
            del array

def process_config_file(config_file, batch_size, logger):
    # Simulating processing a configuration file
    allocated = MemoryManager.allocate(batch_size)
    if allocated is not None:
        logger.info(f"Successfully processed {len(allocated)} allocations for config: {config_file}")
    else:
        logger.error(f"Failed to process config file: {config_file}")

def worker(config_queue, batch_size, logger):
    while True:
        config_file = config_queue.get()
        if config_file is None:
            break
        process_config_file(config_file, batch_size, logger)
        config_queue.task_done()

def main():
    logging.basicConfig(level=logging.INFO)

    # Load configuration for the script itself
    loader = ConfigLoader(["config1.json", "config2.json"])
    config = loader.load_config()
    batch_size = config["batch_size"]

    num_worker_threads = 4
    logger = logging.getLogger()

    # Setup a queue and worker threads
    config_queue = queue.Queue()
    threads = []
    for i in range(num_worker_threads):
        t = threading.Thread(target=worker, args=(config_queue, batch_size, logger))
        t.start()
        threads.append(t)

    # Assume we have some list of configuration files to process
    config_files = ["file1", "file2", "file3"]

    for config_file in config_files:
        config_queue.put(config_file)

    # Block until all tasks are done
    config_queue.join()

    # Stop workers
    for i in range(num_worker_threads):
        config_queue.put(None)
    for t in threads:
        t.join()

if __name__ == "__main__":
    main()
