NFAPI_CRC_INDICATION_PDU_T* create_nfa_api_cri_list(const char *config_file, sqlite3 **db, const char *db_path, const char *query, int supervisor_id) {
    int num_structures = 0;
    if (fetch_config(config_file, &num_structures)) {
        fprintf(stderr, "Failed to read configuration file.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Memory allocation failed for PDU list");
        return NULL;
    }

    for (int i = 0; i < num_structures; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 256;
        pdu_list[i].RNTI = rand() % 65536;

        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.CRCFLAG = rand() % 2;
    }

    sqlite3 *db_conn;
    if (sqlite3_open(db_path, &db_conn)) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db_conn));
        free(pdu_list);
        return NULL;
    }

    *db = db_conn;

    sqlite3_stmt *stmt;
    char sql[512];
    snprintf(sql, sizeof(sql), "%s AND supervisor_id = ?", query);

    if (sqlite3_prepare_v2(*db, sql, -1, &stmt, 0) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(*db));
        sqlite3_close(*db);
        free(pdu_list);
        return NULL;
    }

    if (sqlite3_bind_int(stmt, 1, supervisor_id) != SQLITE_OK) {
        fprintf(stderr, "Binding error: %s\n", sqlite3_errmsg(*db));
        sqlite3_finalize(stmt);
        sqlite3_close(*db);
        free(pdu_list);
        return NULL;
    }

    printf("Employee Name\tCity\tAddress\n");
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        const unsigned char *name = sqlite3_column_text(stmt, 0);
        const unsigned char *city = sqlite3_column_text(stmt, 1);
        const unsigned char *address = sqlite3_column_text(stmt, 2);

        printf("%s\t%s\t%s\n", name, city, address);
    }

    sqlite3_finalize(stmt);

    return pdu_list;
}
