    int quality_index;
} RX_HISTORY_T;

typedef struct {
    RX_HISTORY_T rx_power_history[10];
    RX_HISTORY_T rx_quality_history[10];
    double frame_error_rate;
} NFAPI_L2_STATS_PDU_T;

struct string {
    char *ptr;
    size_t len;
};

static void init_string(struct string *s) {
    s->len = 0;
    s->ptr = malloc(s->len + 1);
    if (s->ptr == NULL)
        fprintf(stderr, "malloc() failed\n");
    s->ptr[0] = '\0';
}

static size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
    size_t new_len = s->len + size * nmemb;
    s->ptr = realloc(s->ptr, new_len + 1);
    if (s->ptr == NULL) {
        fprintf(stderr, "realloc() failed\n");
        return 0;
    }
    memcpy(s->ptr + s->len, ptr, size * nmemb);
    s->ptr[new_len] = '\0';
    s->len = new_len;

    return size * nmemb;
}

double calculate_fer(int received_symbols[], int total_symbols) {
    int errors = 0;
    for (int i = 0; i < total_symbols; i++) {
        if (received_symbols[i] == -1) { // Assuming -1 indicates an error
            errors++;
        }
    }
    return (double)errors / total_symbols;
}

void populate_nfa_stats(NFAPI_L2_STATS_PDU_T *nfa_stats, int n, int received_symbols[], int total_symbols) {
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 10; ++j) { // Assuming fixed history size
            nfa_stats[i].rx_power_history[j].power_level = rand() % 100;
            nfa_stats[i].rx_quality_history[j].quality_index = rand() % 50;
        }
        nfa_stats[i].frame_error_rate = calculate_fer(received_symbols, total_symbols);
    }
}

void send_nms_request(const char *api_key, const char *cell_id) {
    CURL *curl;
    CURLcode res;
    struct string s;

    init_string(&s);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(curl) {
        char url[256];
        snprintf(url, sizeof(url), "https://nms.api/performance?cell_id=%s&api_key=%s", cell_id, api_key);

        int retries = 0;
        while (retries < MAX_RETRY) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

            res = curl_easy_perform(curl);

            if (res == CURLE_OK) {
                printf("Received performance data: %s\n", s.ptr);
                break;
            } else {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                retries++;
                sleep((1 << retries)); // Exponential backoff
            }
        }

        if (retries == MAX_RETRY) {
            fprintf(stderr, "Failed to fetch data after %d retries.\n", MAX_RETRY);
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    free(s.ptr);
}

int main() {
    int received_symbols[] = {0, 1, -1, 3, -1, 5}; // Example symbols with errors
    int total_symbols = sizeof(received_symbols) / sizeof(received_symbols[0]);

    NFAPI_L2_STATS_PDU_T nfa_stats[5]; // Assuming 5 cells for example

    populate_nfa_stats(nfa_stats, 5, received_symbols, total_symbols);

    const char *api_key = "your_api_key";
    send_nms_request(api_key, "cell_123");

    return 0;
}
```

