}

// Function to remove an entry by RNTI
int remove_entry(NFAPI_CRC_INDICATION_PDU_T **head, unsigned long rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = *head, *prev = NULL;

    while (current != NULL && current->ue_info.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return 0; // RNTI not found

    if (prev == NULL) { // Remove head
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    return 1;
}

