#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define LOG_FILE "network_log.txt"

typedef struct {
    int CELL_ID;
    time_t MEASUREMENT_TIMESTAMP;
    float SINR_VALUE;
} NR_CELL_MEASUREMENT_REPORT;

typedef struct Node {
    NR_CELL_MEASUREMENT_REPORT data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CellMeasurementList;

CellMeasurementList* init_measurement_list(int M);
void free_measurement_list(CellMeasurementList* list);
int add_cell_measurement(CellMeasurementList* list, int cell_id, float snr);
float update_snr_value(NR_CELL_MEASUREMENT_REPORT* report, float new_snr);
float query_average_sinr(CellMeasurementList* list, int cell_id);
void log_message(const char* message);

CellMeasurementList* init_measurement_list(int M) {
    CellMeasurementList* list = (CellMeasurementList*)malloc(sizeof(CellMeasurementList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    // Preallocate nodes
    for (int i = 0; i < M; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            log_message("Failed to allocate memory for node.");
            free_measurement_list(list);
            return NULL;
        }
        list->head = new_node;
        list->head->next = NULL;
    }

    return list;
}

void free_measurement_list(CellMeasurementList* list) {
    if (list) {
        Node* current = list->head;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_cell_measurement(CellMeasurementList* list, int cell_id, float snr) {
    if (!list || snr < 0) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.CELL_ID == cell_id) {
            log_message("Duplicate CELL_ID encountered.");
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate ID
        }
        if (!current->next) break;
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Failed to allocate memory for new node.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data.CELL_ID = cell_id;
    new_node->data.MEASUREMENT_TIMESTAMP = time(NULL);
    new_node->data.SINR_VALUE = update_snr_value(&(new_node->data), snr);

    current->next = new_node;
    new_node->next = NULL;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully added
}

float update_snr_value(NR_CELL_MEASUREMENT_REPORT* report, float new_snr) {
    if (!report) return -1.0f;
    return 10 * log10(new_snr); // Convert SNR to SINR in dB
}

float query_average_sinr(CellMeasurementList* list, int cell_id) {
    if (!list) return -1.0f;

    pthread_mutex_lock(&list->lock);

    float sum = 0;
    int count = 0;
    Node* current = list->head;
    while (current) {
        if (current->data.CELL_ID == cell_id) {
            sum += current->data.SINR_VALUE;
            count++;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    return (count > 0) ? (sum / count) : -1.0f; // Return average or error code
}

void log_message(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}
```

### Design Choices Explanation

1. **Thread Safety**: A mutex lock is used to ensure thread safety when accessing the list. This prevents race conditions and data corruption in a concurrent environment.

2. **Dynamic Memory Management**: Nodes are dynamically allocated, allowing the system to handle varying numbers of cell measurements efficiently. The function preallocates nodes based on the input size `M`.

3. **Error Handling and Logging**: Errors such as memory allocation failures or duplicate `CELL_ID` entries are logged to a file. This logging mechanism is simple but ensures that errors can be tracked without significantly impacting performance.

4. **Scalability Considerations**: The list uses linked nodes, which allows for dynamic growth. However, operations on the list have O(n) complexity due to traversal, which could be optimized further with more advanced data structures if necessary.

5. **SINR Calculation**: SINR is calculated from SNR using a logarithmic conversion, reflecting real-world calculations in signal processing.

This design aims to balance memory usage, performance, and thread safety for managing large-scale 5G network measurements.']

