['Below is a C implementation for managing a dynamically allocated array of `NFAPI_RRC_MESSAGE_PDU_T` structures with thread-safe access:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    RRC_TYPE_1,
    RRC_TYPE_2,
    // Add other RRC message types as needed
} rrc_message_type_t;

typedef struct {
    rrc_message_type_t type;
    int sequence_number;
    void *payload;  // Optional payload data
    size_t payload_size;
} NFAPI_RRC_MESSAGE_PDU_T;

typedef struct {
    NFAPI_RRC_MESSAGE_PDU_T **messages;
    int capacity;
    int count;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock[1024];  // Array of read-write locks for fine-grained locking
} MessageManager;

MessageManager* create_manager(int initial_capacity) {
    MessageManager *manager = (MessageManager *)malloc(sizeof(MessageManager));
    if (!manager) return NULL;

    manager->messages = (NFAPI_RRC_MESSAGE_PDU_T **)calloc(initial_capacity, sizeof(NFAPI_RRC_MESSAGE_PDU_T *));
    if (!manager->messages) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);

    for (int i = 0; i < 1024; ++i) {
        pthread_rwlock_init(&manager->rwlock[i], NULL);
    }

    return manager;
}

void destroy_manager(MessageManager *manager) {
    if (!manager) return;

    for (int i = 0; i < manager->count; ++i) {
        free(manager->messages[i]->payload);
        free(manager->messages[i]);
    }
    free(manager->messages);

    pthread_mutex_destroy(&manager->lock);

    for (int i = 0; i < 1024; ++i) {
        pthread_rwlock_destroy(&manager->rwlock[i]);
    }

    free(manager);
}

static int expand_capacity(MessageManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        int new_capacity = manager->capacity * 2;
        NFAPI_RRC_MESSAGE_PDU_T **new_messages = (NFAPI_RRC_MESSAGE_PDU_T **)realloc(manager->messages, new_capacity * sizeof(NFAPI_RRC_MESSAGE_PDU_T *));
        if (!new_messages) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->messages = new_messages;
        manager->capacity = new_capacity;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_message(MessageManager *manager, NFAPI_RRC_MESSAGE_PDU_T *message) {
    if (!manager || !message) return -1;

    int index = message->sequence_number % 1024;
    pthread_rwlock_wrlock(&manager->rwlock[index]);

    if (expand_capacity(manager) != 0) {
        pthread_rwlock_unlock(&manager->rwlock[index]);
        return -1;
    }

    manager->messages[manager->count] = message;
    manager->count++;

    pthread_rwlock_unlock(&manager->rwlock[index]);
    return 0;
}

NFAPI_RRC_MESSAGE_PDU_T* get_message(MessageManager *manager, int sequence_number) {
    if (!manager) return NULL;

    int index = sequence_number % 1024;
    pthread_rwlock_rdlock(&manager->rwlock[index]);

    for (int i = 0; i < manager->count; ++i) {
        NFAPI_RRC_MESSAGE_PDU_T *msg = manager->messages[i];
        if (msg && msg->sequence_number == sequence_number) {
            pthread_rwlock_unlock(&manager->rwlock[index]);
            return msg;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock[index]);
    return NULL;
}

int update_message(MessageManager *manager, int sequence_number, void *new_payload, size_t payload_size) {
    NFAPI_RRC_MESSAGE_PDU_T *message = get_message(manager, sequence_number);
    if (!message) return -1;

    int index = sequence_number % 1024;
    pthread_rwlock_wrlock(&manager->rwlock[index]);

    free(message->payload);
    message->payload = malloc(payload_size);
    if (!message->payload) {
        pthread_rwlock_unlock(&manager->rwlock[index]);
        return -1;
    }
    memcpy(message->payload, new_payload, payload_size);
    message->payload_size = payload_size;

    pthread_rwlock_unlock(&manager->rwlock[index]);
    return 0;
}
```

### Key Points:
- **Memory Management**: The `expand_capacity` function ensures dynamic resizing of the array to handle more messages.
- **Concurrency Control**: Fine-grained locking is used with an array of read-write locks for each message, reducing contention compared to a single lock.
- **Scalability**: The design uses a hash-like mechanism (`sequence_number % 1024`) to distribute messages across locks, minimizing cache misses and improving scalability.
- **Usability**: Functions `add_message`, `get_message`, and `update_message` provide clear interfaces for managing messages.
- **Performance**: Locks are minimized by using read-write locks, allowing multiple concurrent reads.
- **Error Handling**: Checks for null pointers and allocation failures ensure robustness.']

