        // Do something with the hash, e.g., store or process it
    }

    return NULL;
}

void process_strings_batch(const char **strings, size_t count) {
    pthread_t thread;
    const char **batch = strings;
    size_t batch_count = count;

    if (count > 10000) {
        batch_count = 10000; // Limit to 10,000 for performance
    }

    void *arg[2] = { (void *)batch, &batch_count };

    clock_t start = clock();
    int retry_count = 0;
    while (retry_count < MAX_RETRY) {
        if (pthread_create(&thread, NULL, compute_md5_hash, arg)) {
            LOG_ERROR("Failed to create thread: %s", strerror(errno));
            retry_count++;
            continue;
        }

        pthread_join(thread, NULL);

        clock_t end = clock();
        double elapsed_time = ((double)end - start) / CLOCKS_PER_SEC;

        if (elapsed_time <= 5.0) {
            break; // Success
        } else {
            LOG_ERROR("Processing took longer than expected: %.2f seconds", elapsed_time);
            retry_count++;
        }
    }

    if (retry_count == MAX_RETRY) {
        LOG_ERROR("Max retries reached for processing batch");
    }
}

