["Here's a C implementation for managing a dynamically allocated array of `NFAPI_RRC_MESSAGE_PDU_T` structures, considering your outlined trade-offs:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int rrc_message_type;
    int sequence_number;
    void *payload; // Optional payload data
} NFAPI_RRC_MESSAGE_PDU_T;

typedef struct {
    NFAPI_RRC_MESSAGE_PDU_T* messages;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} MessageArray;

// Initialize the message array
MessageArray* init_message_array() {
    MessageArray* array = malloc(sizeof(MessageArray));
    if (!array) return NULL;

    array->messages = malloc(INITIAL_CAPACITY * sizeof(NFAPI_RRC_MESSAGE_PDU_T));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_rwlock_init(&array->lock, NULL);

    return array;
}

// Resize the internal message array
int resize_message_array(MessageArray* array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_RRC_MESSAGE_PDU_T* new_messages = realloc(array->messages, new_capacity * sizeof(NFAPI_RRC_MESSAGE_PDU_T));

    if (!new_messages) return -1;

    array->messages = new_messages;
    array->capacity = new_capacity;
    return 0;
}

// Add a new message
int add_message(MessageArray* array, NFAPI_RRC_MESSAGE_PDU_T message) {
    pthread_rwlock_wrlock(&array->lock);

    if (array->count == array->capacity) {
        int status = resize_message_array(array);
        if (status != 0) {
            pthread_rwlock_unlock(&array->lock);
            return -1;
        }
    }

    array->messages[array->count++] = message;

    pthread_rwlock_unlock(&array->lock);
    return 0;
}

// Update an existing message by sequence number
int update_message(MessageArray* array, int sequence_number, NFAPI_RRC_MESSAGE_PDU_T new_message) {
    pthread_rwlock_wrlock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].sequence_number == sequence_number) {
            array->messages[i] = new_message;
            pthread_rwlock_unlock(&array->lock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&array->lock);
    return -1;
}

// Retrieve a message by sequence number
NFAPI_RRC_MESSAGE_PDU_T* get_message(MessageArray* array, int sequence_number) {
    NFAPI_RRC_MESSAGE_PDU_T* result = NULL;

    pthread_rwlock_rdlock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].sequence_number == sequence_number) {
            result = &array->messages[i];
            break;
        }
    }

    pthread_rwlock_unlock(&array->lock);
    return result;
}

// Free resources
void free_message_array(MessageArray* array) {
    free(array->messages);
    pthread_rwlock_destroy(&array->lock);
    free(array);
}
```

### Key Points:
- **Concurrency Control**: Using `pthread_rwlock_t` for read-write locks to allow multiple readers or one writer at a time.
- **Memory Management**: Uses dynamic resizing to manage the array's capacity efficiently.
- **Scalability and Performance**: Double-buffer strategy for resizing minimizes reallocation overhead. Fine-grained locking allows concurrency without significant contention.
- **Error Handling**: Basic error handling with return codes for operations that may fail (e.g., memory allocation).
- **Usability**: Simple API functions (`init_message_array`, `add_message`, `update_message`, `get_message`, and `free_message_array`) make it easy to integrate into larger systems."]

