#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int valid; // Flag to indicate if the structure is in use.
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned long CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element(List* list, unsigned long rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Element not found
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (prev == NULL) { // Remove head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_crcflag(List* list, unsigned long rnti, int new_crcflag) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (!current) { // Element not found
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    current->data.CRCFLAG = new_crcflag;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void process_external_updates(List* list, NFAPI_CRC_INDICATION_PDU_T* updates, size_t count) {
    if (!list || !updates) return;

    for (size_t i = 0; i < count; ++i) {
        add_element(list, updates[i]);
    }
}
