```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Constants
#define MAX_CHANNELS 64 // Example maximum number of RF channels
#define M 1024           // Maximum number of symbols per frame

// Structures
typedef int RF_CHANNEL_ID;
typedef struct {
    RF_CHANNEL_ID channel_id;
    float *received_symbols; // Array of received symbols
    int flag_set_rx_frame_lock;
} LTE_PHY_RX_FRAME_INFO;

// Dynamic array structure
typedef struct {
    LTE_PHY_RX_FRAME_INFO **frames;
    size_t capacity;
    size_t count;
} LTE_PHY_RX_FRAME_MANAGER;

// Function to initialize the manager
void init_lte_phy_rx_frame_manager(LTE_PHY_RX_FRAME_MANAGER *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->frames = (LTE_PHY_RX_FRAME_INFO **)malloc(manager->capacity * sizeof(LTE_PHY_RX_FRAME_INFO *));
}

// Function to allocate a new frame
int add_rx_frame(LTE_PHY_RX_FRAME_MANAGER *manager, RF_CHANNEL_ID channel_id) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_PHY_RX_FRAME_INFO **new_frames = (LTE_PHY_RX_FRAME_INFO **)realloc(manager->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO *));
        if (!new_frames) {
            return -1; // Memory allocation failed
        }
        memset(new_frames + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(LTE_PHY_RX_FRAME_INFO *));
        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    LTE_PHY_RX_FRAME_INFO *frame = (LTE_PHY_RX_FRAME_INFO *)malloc(sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!frame) {
        return -1; // Memory allocation failed
    }
    frame->channel_id = channel_id;
    frame->received_symbols = (float *)calloc(M, sizeof(float)); // Initialize with zeroed symbols
    frame->flag_set_rx_frame_lock = 0;

    manager->frames[manager->count++] = frame;
    return 0; // Success
}

// Function to deallocate a specific frame
int remove_rx_frame(LTE_PHY_RX_FRAME_MANAGER *manager, RF_CHANNEL_ID channel_id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]->channel_id == channel_id) {
            free(manager->frames[i]->received_symbols);
            free(manager->frames[i]);
            manager->frames[i] = manager->frames[--manager->count]; // Overwrite and reduce count
            return 0; // Success
        }
    }
    return -1; // Frame not found
}

// Function to deallocate all frames
void clear_rx_frames(LTE_PHY_RX_FRAME_MANAGER *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]->received_symbols);
        free(manager->frames[i]);
    }
    free(manager->frames);
    manager->capacity = 0;
    manager->count = 0;
}

// Example usage
int main() {
    LTE_PHY_RX_FRAME_MANAGER manager;
    init_lte_phy_rx_frame_manager(&manager, 10);

    if (add_rx_frame(&manager, 1) == 0) {
        printf("Frame added successfully.\n");
    }

    remove_rx_frame(&manager, 1);
    clear_rx_frames(&manager);

    return 0;
}
```

### Key Points:
- **Dynamic Memory Management**: The code uses dynamic memory allocation to handle varying numbers of frames and symbols efficiently.
- **Scalability**: It doubles the capacity when needed, ensuring scalability.
- **Efficiency**: Memory is allocated for received symbols only when a frame is added, minimizing overhead.
- **Maintainability**: Functions are modular, making it easy to extend or modify.
- **Usability**: The design allows for easy addition of new fields or features.']

