DynamicArray* initialize_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for dynamic array");
        return NULL;
    }

    array->frames = (LTE_PHY_RX_FRAME_INFO *)calloc(initial_capacity, sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!array->frames) {
        free(array);
        perror("Failed to allocate memory for frames");
        return NULL;
    }

    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    if (pthread_mutex_lock(&array->lock) != 0) {
        perror("Mutex lock failed");
        return -1;
    }

    LTE_PHY_RX_FRAME_INFO *new_frames = (LTE_PHY_RX_FRAME_INFO *)realloc(array->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!new_frames) {
        pthread_mutex_unlock(&array->lock);
        perror("Failed to reallocate memory for frames");
        return -1;
    }

    array->frames = new_frames;
    array->capacity = new_capacity;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

