#define MAX_RF_CHANNELS 10
#define DEFAULT_SYMBOLS_PER_FRAME 256

typedef struct {
    int rf_channel_id;
    int* received_symbols;
    size_t num_symbols;
    int rx_frame_lock_status;
} LTE_PHY_RX_FRAME_INFO;

// Function to initialize the dynamic array of frames
LTE_PHY_RX_FRAME_INFO** init_dynamic_array(size_t frame_count, size_t symbols_per_frame) {
    if (frame_count == 0 || symbols_per_frame == 0) return NULL;

    LTE_PHY_RX_FRAME_INFO** dynamic_array = 
        (LTE_PHY_RX_FRAME_INFO**)calloc(frame_count, sizeof(LTE_PHY_RX_FRAME_INFO*));
    if (!dynamic_array) {
        perror("Failed to allocate memory for frame array");
        return NULL;
    }

    for (size_t i = 0; i < frame_count; ++i) {
        dynamic_array[i] = 
            (LTE_PHY_RX_FRAME_INFO*)calloc(1, sizeof(LTE_PHY_RX_FRAME_INFO));

        if (!dynamic_array[i]) {
            perror("Failed to allocate memory for LTE_PHY_RX_FRAME_INFO");

            // Free already allocated memory in case of failure
            for (size_t j = 0; j < i; ++j) {
                free(dynamic_array[j]->received_symbols);
                free(dynamic_array[j]);
            }
            free(dynamic_array);

            return NULL;
        }

        dynamic_array[i]->rf_channel_id = -1; // Initialize with invalid channel ID
        dynamic_array[i]->num_symbols = symbols_per_frame;
        dynamic_array[i]->received_symbols = 
            (int*)calloc(symbols_per_frame, sizeof(int));

        if (!dynamic_array[i]->received_symbols) {
            perror("Failed to allocate memory for received symbols array");

            // Free already allocated memory in case of failure
            free(dynamic_array[i]);
            for (size_t j = 0; j < i; ++j) {
                free(dynamic_array[j]->received_symbols);
                free(dynamic_array[j]);
            }
            free(dynamic_array);

            return NULL;
        }

        dynamic_array[i]->rx_frame_lock_status = 0; // Initialize with unlocked status
    }

    return dynamic_array;
}

// Function to deallocate the dynamic array of frames
void free_dynamic_array(LTE_PHY_RX_FRAME_INFO** dynamic_array, size_t frame_count) {
    if (!dynamic_array) return;

    for (size_t i = 0; i < frame_count; ++i) {
        if (dynamic_array[i]) {
            free(dynamic_array[i]->received_symbols);
            free(dynamic_array[i]);
        }
    }

    free(dynamic_array);
}

// Example usage
int main() {
    size_t frame_count = MAX_RF_CHANNELS;
    size_t symbols_per_frame = DEFAULT_SYMBOLS_PER_FRAME;

    LTE_PHY_RX_FRAME_INFO** dynamic_frames = init_dynamic_array(frame_count, symbols_per_frame);

    if (dynamic_frames) {
        // Use the initialized frames...

        free_dynamic_array(dynamic_frames, frame_count);
    }

    return 0;
}
