#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char *CRC_INDICATION_REL8_TAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG_T *crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST;

void init_list(NFAPI_CRC_LIST *list) {
    list->size = 0;
    list->capacity = 10; // Initial capacity
    list->elements = malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(NFAPI_CRC_LIST *list) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].crc_indication_rel8_tag != NULL) {
            free(list->elements[i].crc_indication_rel8_tag);
        }
    }
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}

int add_element(NFAPI_CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_LIST_SIZE) {
            fprintf(stderr, "Error: Maximum list capacity reached.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            fprintf(stderr, "Error: Memory reallocation failed.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->elements[list->size] = element;

    // Allocate and set CRC_INDICATION_REL8_TAG
    list->elements[list->size].crc_indication_rel8_tag = malloc(sizeof(CRC_INDICATION_REL8_TAG_T));
    if (!list->elements[list->size].crc_indication_rel8_tag) {
        fprintf(stderr, "Error: Memory allocation for CRC tag failed.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->elements[list->size].crc_indication_rel8_tag->RX_UE_INFORMATION_TAG = element.RX_UE_INFORMATION_TAG;
    list->elements[list->size].crc_indication_rel8_tag->RNTI = element.RNTI;
    list->elements[list->size].crc_indication_rel8_tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    ++list->size;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *get_element(NFAPI_CRC_LIST *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        return NULL;
    }

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[index];
    pthread_mutex_unlock(&list->lock);

    return element;
}

// Test cases
void test() {
    NFAPI_CRC_LIST list;
    init_list(&list);

    // Add elements to the list
    for (int i = 0; i < 5; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i, .RNTI = i * 10 };
        add_element(&list, pdu);
    }

    // Retrieve elements
    for (size_t i = 0; i < list.size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = get_element(&list, i);
        if (pdu) {
            printf("Element %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%u\n",
                   i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->crc_indication_rel8_tag->CRCFLAG);
        }
    }

    // Test edge case: retrieve out of bounds
    get_element(&list, 10);

    // Free list
    free_list(&list);
}

int main() {
    test();
    return 0;
}
```

This code includes memory management with dynamic resizing, thread safety using mutexes, and error handling for reallocation failures. The test function demonstrates adding elements, retrieving them, and handling an out-of-bounds index case.']

['Here's a complete implementation of the dynamic list management for TAI structures in C:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int cell_id;
    int tracking_area_code;
} tai;

typedef struct {
    int cell_id;
    int tracking_area_code;
    tai *neighbors; // Dynamically allocated list of neighboring TAIs
    size_t neighbor_count;
} tais_info;

typedef struct {
    tais_info *elements;
    size_t capacity;
    size_t size;
} tai_list;

void init_tai_list(tai_list *list) {
    list->capacity = 4; // Initial capacity
    list->size = 0;
    list->elements = malloc(list->capacity * sizeof(tais_info));
}

int add_tai(tai_list *list, int cell_id, int tac, tai neighbors[], size_t neighbor_count) {
    if (list == NULL || neighbors == NULL) return -1;

    // Reallocate memory if necessary
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        tais_info *new_elements = realloc(list->elements, new_capacity * sizeof(tais_info));
        if (!new_elements) return -1; // Memory allocation failed

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    tai_list *new_element = &list->elements[list->size];
    new_element->cell_id = cell_id;
    new_element->tracking_area_code = tac;

    new_element->neighbors = malloc(neighbor_count * sizeof(tai));
    if (!new_element->neighbors) return -1; // Memory allocation failed

    for (size_t i = 0; i < neighbor_count; ++i) {
        new_element->neighbors[i] = neighbors[i];
    }
    new_element->neighbor_count = neighbor_count;

    list->size++;
    return 0;
}

tais_info* get_tai(tai_list *list, size_t index) {
    if (list == NULL || index >= list->size) return NULL;
    return &list->elements[index];
}

void free_tai_list(tai_list *list) {
    if (!list) return;

    for (size_t i = 0; i < list->size; ++i) {
        free(list->elements[i].neighbors);
    }
    free(list->elements);

    list->capacity = 0;
    list->size = 0;
}

// Test cases
void test() {
    tai_list list;
    init_tai_list(&list);

    tai neighbors1[] = {{1, 100}, {2, 200}};
    add_tai(&list, 123, 456, neighbors1, 2);

    tai neighbors2[] = {{3, 300}};
    add_tai(&list, 789, 012, neighbors2, 1);

    tais_info *retrieved = get_tai(&list, 0);
    if (retrieved) {
        printf("Cell ID: %d, TAC: %d\n", retrieved->cell_id, retrieved->tracking_area_code);
        for (size_t i = 0; i < retrieved->neighbor_count; ++i) {
            printf("Neighbor Cell ID: %d, TAC: %d\n", retrieved->neighbors[i].cell_id, retrieved->neighbors[i].tracking_area_code);
        }
    }

    free_tai_list(&list);
}

int main() {
    test();
    return 0;
}
```

### Key Points:
- **Memory Management**: The function reallocates memory when the list grows beyond its current capacity.
- **Error Handling**: Checks for null pointers and failed allocations.
- **Freeing Memory**: Ensures all dynamically allocated memory is freed to prevent leaks.
- **Test Cases**: Demonstrates adding TAIs, retrieving them, and cleaning up.']

