#define MAX_RNTI 65535
#define INITIAL_POOL_SIZE 10

// Memory pool structure to manage allocations.
typedef struct MemoryPool {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *pool;
    struct MemoryPool *next; // Pointer for further growth if needed.
} MemoryPool;

// Global pointer to the head of memory pool list for reuse.
static MemoryPool *memory_pool_head = NULL;

// Initialize a new memory block in the pool.
MemoryPool* init_memory_block(size_t capacity) {
    MemoryPool *new_block = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!new_block) return NULL;

    new_block->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_block->pool) {
        free(new_block);
        return NULL;
    }

    new_block->capacity = capacity;
    new_block->size = 0;
    new_block->next = NULL;

    return new_block;
}

// Allocate memory from the pool or create a new block.
NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t n) {
    MemoryPool *current = memory_pool_head;

    // Try to reuse an existing block with enough capacity
    while (current != NULL && current->size + n > current->capacity) {
        current = current->next;
    }

    if (current == NULL || current->size + n > current->capacity) {
        // If no suitable block is found, create a new one or expand existing pool.
        size_t capacity = (n > INITIAL_POOL_SIZE) ? n : INITIAL_POOL_SIZE;

        MemoryPool *new_block = init_memory_block(capacity);
        if (!new_block) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL; // Handle memory allocation failure
        }

        new_block->next = memory_pool_head;
        memory_pool_head = new_block;

        current = new_block;
    }

    NFAPI_CRC_INDICATION_PDU_T *allocated_memory = &current->pool[current->size];
    current->size += n;

    return allocated_memory;
}

// Free all memory blocks when the module is unloaded or during cleanup.
void free_all_memory() {
    MemoryPool *current = memory_pool_head;
    while (current != NULL) {
        MemoryPool *next = current->next;
        free(current->pool);
        free(current);
        current = next;
    }
}

// Sample function to demonstrate use
NFAPI_CRC_INDICATION_PDU_T* manage_memory(size_t n) {
    if (n == 0 || n > MAX_RNTI) {
        fprintf(stderr, "Invalid N value\n");
        return NULL;
    }

    return allocate_memory(n);
}

int main() {
