    NFAPI_CRC_INDICATION_PDU_T *pdu_array = manage_memory(num_structs);

    if (pdu_array != NULL) {
        // Use pdu_array here

        // Remember to free the memory after use.
    }

    // Clean up when done
    free_all_memory();

    return 0;
}
