const axios = require('axios');
const { Readable } = require('stream');

let bufferQueue = [];
let isPaused = false;

async function updateResource(resourceId, data) {
  try {
    // Collecting data from a streaming source
    const stream = new Readable({
      read() {}
    });

    stream.on('data', (chunk) => {
      if (isPaused) {
        bufferQueue.push(chunk);
      } else {
        processChunk(chunk);
      }
    });

    stream.on('end', async () => {
      await axios.put(`https://api.example.com/resources/${resourceId}`, data);
    });

    stream.on('error', handleError);

    function pauseCollection() {
      isPaused = true;
    }

    function resumeCollection() {
      isPaused = false;
      while (bufferQueue.length > 0) {
        processChunk(bufferQueue.shift());
      }
    }

    function processChunk(chunk) {
      // Logic to process each chunk
    }

    function handleError(error) {
      console.error('Stream error:', error);
    }

    return { pauseCollection, resumeCollection };
  } catch (error) {
    console.error('Update resource error:', error);
  }
}

async function deleteResource(resourceId) {
  try {
    const response = await axios.delete(`https://api.example.com/resources/${resourceId}`);

    if (response.status === 200) {
      // Handle dependencies or associated resources
      handleDependencies();

      // Return new resource with default values
      return createDefaultResource();
    }
  } catch (error) {
    console.error('Delete resource error:', error);
  }

  async function handleDependencies() {
    // Logic to manage dependent resources
  }

  function createDefaultResource() {
    return { id: null, data: {} };
  }
}

function rateLimit(func) {
  let lastCall = 0;
  const limitTime = 100; // ms

  return (...args) => {
    const now = Date.now();
    if (now - lastCall >= limitTime) {
      lastCall = now;
      func(...args);
    }
  };
}

const throttledUpdateResource = rateLimit(updateResource);
const throttledDeleteResource = rateLimit(deleteResource);

module.exports = { updateResource: throttledUpdateResource, deleteResource: throttledDeleteResource };
