typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **elements;
    size_t count;
    size_t capacity;
} NFAPICRCList;

void initNFAPICRCList(NFAPICRCList *list) {
    list->capacity = 2; // Start with initial capacity
    list->count = 0;
    list->elements = malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!list->elements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

bool addNFAPICRCElement(NFAPICRCList *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (!new_elements) {
            fprintf(stderr, "Memory reallocation failed\n");
            return false; // Do not terminate application
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        fprintf(stderr, "Memory allocation failed\n");
        return false; // Do not terminate application
    }

    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG_p = malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!element->CRC_INDICATION_REL8_TAG_p) {
        free(element);
        fprintf(stderr, "Memory allocation failed\n");
        return false; // Do not terminate application
    }

    element->CRC_INDICATION_REL8_TAG_p->CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
    list->elements[list->count++] = element;
    return true;
}

NFAPI_CRC_INDICATION_PDU_T *getNFAPICRCElement(NFAPICRCList *list, size_t index) {
    if (index >= list->count) {
        return NULL; // Index out of bounds
    }
    return list->elements[index];
}

void freeNFAPICRCList(NFAPICRCList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->elements[i]) {
            free(list->elements[i]->CRC_INDICATION_REL8_TAG_p);
            free(list->elements[i]);
        }
