}

// Optimized array for largest integer retrieval
typedef struct {
    int *data;
    size_t count;
} LargestIntArray;

void initLargestIntArray(LargestIntArray *array) {
    array->count = 0;
    array->data = NULL;
}

bool addIntegerToLargestIntArray(LargestIntArray *array, int value) {
    if (array->count == 0 || value > array->data[array->count - 1]) {
        size_t new_capacity = array->count + 1;
        int *new_data = realloc(array->data, new_capacity * sizeof(int));
        if (!new_data) {
            fprintf(stderr, "Memory reallocation failed\n");
            return false; // Do not terminate application
        }
        array->data = new_data;
        array->data[array->count++] = value;
    } else if (value == array->data[array->count - 1]) {
        // If equal, do nothing
    } else {
        size_t i = 0;
        while (i < array->count && array->data[i] > value) {
            ++i;
        }
        if (i < array->count) {
            for (size_t j = array->count; j > i; --j) {
                array->data[j] = array->data[j - 1];
            }
            array->data[i] = value;
            ++array->count;
        } else {
            // Value is the smallest, do nothing
        }
    }
    return true;
}

int getLargestInteger(LargestIntArray *array) {
    if (array->count == 0) {
        fprintf(stderr, "No integers in array\n");
        exit(EXIT_FAILURE);
    }
    return array->data[array->count - 1];
}

void freeLargestIntArray(LargestIntArray *array) {
