        printf("Test element RX_UE_INFORMATION_TAG: %d\n", element->RX_UE_INFORMATION_TAG);
    }

    freeNFAPICRCList(&list);
}

void testLargestIntArray() {
    LargestIntArray array;
    initLargestIntArray(&array);

    addIntegerToLargestIntArray(&array, 5);
    addIntegerToLargestIntArray(&array, 3);
    addIntegerToLargestIntArray(&array, 9);
    addIntegerToLargestIntArray(&array, 7);

    printf("Largest integer: %d\n", getLargestInteger(&array));

    freeLargestIntArray(&array);
}

