#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MAX_LOG_MESSAGE_SIZE 256

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG crc_info;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for resource monitoring
size_t total_memory_allocated = 0;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    if (strlen(message) < MAX_LOG_MESSAGE_SIZE) {
        printf("%s\n", message);
    } else {
        printf("Log message exceeds maximum size and will be truncated.\n");
        strncpy(message, "Message too long, content truncated: ", MAX_LOG_MESSAGE_SIZE - 3);
        message[MAX_LOG_MESSAGE_SIZE - 1] = '\0';
        strncat(message, "...", 3);
        printf("%s\n", message);
    }
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (pthread_mutex_lock(&memory_lock)) return NULL;
    total_memory_allocated += size;
    pthread_mutex_unlock(&memory_lock);
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_list(int N, int max_reuse_limit) {
    srand(time(NULL));

    // Head of the linked list
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

    // Array to track used RNTIs for reuse limit enforcement
    bool *used_rntis = (bool*)safe_malloc(sizeof(bool) * 1024);
    if (!used_rntis) {
        log_message("Memory allocation failed for RNTI tracking.");
        return head;
    }
    memset(used_rntis, false, sizeof(bool) * 1024);

    int unique_rnti_count = 0;

    // Mutex for thread-safe operations
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; ++i) {
        unsigned long rnti;
        do {
            rnti = rand() % 1024;
        } while ((tail && tail->RNTI == rnti) || used_rntis[rnti]);

        if (!head) { // First element
            head = (NFAPI_CRC_INDICATION_PDU_T*)safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!head) {
                log_message("Memory allocation failed for the first node.");
                free(used_rntis);
                pthread_mutex_destroy(&list_lock);
                return head;
            }
            tail = head;
        } else { // Subsequent elements
            NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_node) {
                log_message("Memory allocation failed for a new node.");
                free(used_rntis);
                pthread_mutex_destroy(&list_lock);
                return head;
            }
            tail->next = new_node;
            tail = new_node;
        }

        pthread_mutex_lock(&list_lock);

        // Populate the structure
        tail->RX_UE_INFORMATION_TAG = rand();
        tail->RNTI = rnti;
        tail->crc_info.CRCFLAG = rand() % 2; // Random CRC flag

        char log_entry[MAX_LOG_MESSAGE_SIZE];
        snprintf(log_entry, sizeof(log_entry), "Created NFAPI_CRC_INDICATION_PDU_T: RX_UE_INFO=%lu, RNTI=%lu", 
                 tail->RX_UE_INFORMATION_TAG, tail->RNTI);
        log_message(log_entry);

        used_rntis[rnti] = true;
        if (++unique_rnti_count > max_reuse_limit) {
            char log_exit[MAX_LOG_MESSAGE_SIZE];
            snprintf(log_exit, sizeof(log_exit), "Exceeded RNTI reuse limit of %d. Aborting.", max_reuse_limit);
            log_message(log_exit);
            break; // Graceful exit
        }

        pthread_mutex_unlock(&list_lock);
    }

    free(used_rntis);
    pthread_mutex_destroy(&list_lock);

    return head;
}

// Optional function to monitor system resource usage
void report_resource_usage() {
    char message[MAX_LOG_MESSAGE_SIZE];
    snprintf(message, sizeof(message), "Total memory allocated: %zu bytes", total_memory_allocated);
    log_message(message);
}
