['Below is a C-based implementation of the message management system as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define EXPANSION_FACTOR 2

typedef enum {
    NFAPI_RESET_PDU,
    NFAPI_CONFIG_PDU,
    NFAPI_RX_PDU
} MessageType;

typedef struct {
    int session_id;
    MessageType type;
    union {
        // Define actual structures for each PDU type
    } pdu_data;
    time_t timestamp;
} MessageMetadata;

typedef struct {
    void *pdu;  // Union or specific structure depending on the message type
    MessageMetadata metadata;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageBuffer;

// Function prototypes
void init_message_buffer(MessageBuffer *buffer);
void destroy_message_buffer(MessageBuffer *buffer);
int add_message(MessageBuffer *buffer, NFAPI_MESSAGE_T message);
NFAPI_MESSAGE_T* get_message_by_session_id(const MessageBuffer *buffer, int session_id);
int remove_message_by_session_id(MessageBuffer *buffer, int session_id);
void resize_message_buffer(MessageBuffer *buffer);
void purge_expired_messages(MessageBuffer *buffer, time_t expiration_time);

// Initialize the message buffer
void init_message_buffer(MessageBuffer *buffer) {
    buffer->messages = malloc(INITIAL_CAPACITY * sizeof(NFAPI_MESSAGE_T));
    if (!buffer->messages) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    buffer->capacity = INITIAL_CAPACITY;
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);
}

// Destroy the message buffer
void destroy_message_buffer(MessageBuffer *buffer) {
    free(buffer->messages);
    pthread_mutex_destroy(&buffer->lock);
}

// Add a message to the buffer
int add_message(MessageBuffer *buffer, NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->count >= buffer->capacity) {
        resize_message_buffer(buffer);
    }

    buffer->messages[buffer->count++] = message;

    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

// Retrieve a message by session ID
NFAPI_MESSAGE_T* get_message_by_session_id(const MessageBuffer *buffer, int session_id) {
    for (size_t i = 0; i < buffer->count; ++i) {
        if (buffer->messages[i].metadata.session_id == session_id) {
            return &buffer->messages[i];
        }
    }
    return NULL;
}

// Remove a message by session ID
int remove_message_by_session_id(MessageBuffer *buffer, int session_id) {
    pthread_mutex_lock(&buffer->lock);

    for (size_t i = 0; i < buffer->count; ++i) {
        if (buffer->messages[i].metadata.session_id == session_id) {
            memmove(&buffer->messages[i], &buffer->messages[i + 1],
                    (--buffer->count - i) * sizeof(NFAPI_MESSAGE_T));
            break;
        }
    }

    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

// Resize the message buffer
void resize_message_buffer(MessageBuffer *buffer) {
    size_t new_capacity = buffer->capacity * EXPANSION_FACTOR;
    NFAPI_MESSAGE_T *new_messages = realloc(buffer->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
    if (!new_messages) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    buffer->messages = new_messages;
    buffer->capacity = new_capacity;
}

// Purge expired messages
void purge_expired_messages(MessageBuffer *buffer, time_t expiration_time) {
    pthread_mutex_lock(&buffer->lock);

    for (size_t i = 0; i < buffer->count;) {
        if (difftime(expiration_time, buffer->messages[i].metadata.timestamp) > 0) {
            memmove(&buffer->messages[i], &buffer->messages[i + 1],
                    (--buffer->count - i) * sizeof(NFAPI_MESSAGE_T));
        } else {
            ++i;
        }
