#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 100000

typedef struct {
    uint16_t member1;
    uint32_t member2;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint16_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
} List;

void init_list(List* list) {
    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);

    pthread_rwlock_wrlock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_rwlock_unlock(&list->lock);
}

int is_rnti_unique(List* list, uint16_t rnti) {
    Node* current = list->head;

    pthread_rwlock_rdlock(&list->lock);
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            pthread_rwlock_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);

    return 1;
}

void generate_random_data(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->rx_ue_info.member1 = rand() % UINT16_MAX + 1;
    pdu->rx_ue_info.member2 = rand() % UINT32_MAX + 1;

    do {
        pdu->rnti = rand() % (UINT16_MAX - 1) + 1;
    } while (!is_rnti_unique(list, pdu->rnti));

    pdu->crcflag = rand() % 2;
}

void free_list(List* list) {
    Node* current = list->head;
    Node* next_node;

    pthread_rwlock_wrlock(&list->lock);
    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }
    list->head = NULL;
    pthread_rwlock_unlock(&list->lock);

    pthread_rwlock_destroy(&list->lock);
}

void populate_list(List* list, int num_structs) {
    if (num_structs > MAX_STRUCTS || num_structs <= 0) {
        fprintf(stderr, "Invalid number of structures requested.\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < num_structs; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_data(&pdu);
        insert_node(list, pdu);
    }
}

void log_error(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

int main() {
    List list;
    init_list(&list);

    populate_list(&list, 100000);

    // For demonstration purposes: Free the allocated memory
    free_list(&list);

    return 0;
}
```

