        for (int i = 0; i < entries; ++i) {
            rxTags[i].TAG = rand() % 65536;
            rntis[i] = rand() % (RNTI_MAX_VALUE + 1);
        }
    } else {
        // Validate external data
        for (int i = 0; i < entries; ++i) {
            if (rntis[i] > RNTI_MAX_VALUE) {
                log_message("Invalid RNTI value in external data.");
                free(rxTags);
                free(rntis);
                return NULL;
            }
        }
    }

    // Check uniqueness and allocate the list
    uint16_t rnti_set[MAX_ENTRIES] = {0};
    int unique_count = 0;

    for (int i = 0; i < entries && unique_count < MAX_ENTRIES; ++i) {
        if (!rnti_set[rntis[i]]) {
            rnti_set[rntis[i]] = 1;
            unique_count++;
        }
    }

    if (unique_count > MAX_ENTRIES) {
        log_message("Too many unique RNTI values.");
        free(rxTags);
        free(rntis);
        return NULL;
    }

    list = malloc(unique_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("Memory allocation for the list failed.");
        free(rxTags);
        free(rntis);
        return NULL;
    }

    uint16_t cumulative_sum = 0;

    // Populate the list
    int index = 0;
    for (int i = 0; i < entries && index < unique_count; ++i) {
        if (!rnti_set[rntis[i]]) continue;

        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[index++];

        pdu->rxUeInformationTag = rxTags[i];
        pdu->rnti = rntis[i];

        cumulative_sum += pdu->rnti;
        pdu->crcIndicationRel8Tag.crcFlag = cumulative_sum % 256;

        // Mark as used
        rnti_set[rntis[i]] = 0;
    }

    free(rxTags);
    free(rntis);

    *num_entries = unique_count;
    return list;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}
