typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} IntArray;

void initIntArray(IntArray* array) {
    array->head = NULL;
    array->count = 0;
}

void insertSorted(IntArray* array, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Memory allocation failed
    newNode->value = value;

    if (array->head == NULL || array->head->value < value) {
        newNode->next = array->head;
        array->head = newNode;
    } else {
        Node* current = array->head;
        while (current->next != NULL && current->next->value >= value) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
    array->count++;
}

int getLargestInt(IntArray* array) {
    if (array->head == NULL) return INT_MIN; // No elements in the array
    return array->head->value;
}

void freeIntArray(IntArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    array->count = 0;
}

