#define MAX_ELEMENTS 1024

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t capacity;
} DynamicArray;

void init_array(DynamicArray *a) {
    a->array = NULL;
    a->used = 0;
    a->capacity = 0;
}

int resize_array(DynamicArray *a) {
    size_t new_capacity = (a->capacity == 0) ? 4 : (a->capacity * 2);
    if (new_capacity > MAX_ELEMENTS) {
        log_event("Reached maximum capacity limit.");
        return -1; // Indicate failure to expand
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(a->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_event("Memory allocation failed during resize.");
        return -1;
    }

    a->array = new_array;
    a->capacity = new_capacity;
    return 0; // Success
}

int add_crc_indication_pdu(DynamicArray *a, NFAPI_CRC_INDICATION_PDU_T item) {
    if (a->used == a->capacity) {
        int resize_result = resize_array(a);
        if (resize_result != 0) {
            log_event("Failed to resize array.");
            return -1;
        }
    }

    a->array[a->used++] = item;
    return 0; // Success
}

void free_array(DynamicArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->capacity = 0;
}

int main() {
    DynamicArray crc_array;
    init_array(&crc_array);

    srand(time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < MAX_ELEMENTS + 10; ++i) {  // Test beyond capacity
        NFAPI_CRC_INDICATION_PDU_T pdu;

