#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_THREADS 4

typedef struct {
    int sender_id;
    int recipient_id;
    char *message;
} Message;

typedef struct {
    Message **messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageQueue;

void initMessageQueue(MessageQueue *queue) {
    queue->messages = NULL;
    queue->count = 0;
    queue->capacity = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void freeMessageQueue(MessageQueue *queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        free(queue->messages[i]->message);
        free(queue->messages[i]);
    }
    free(queue->messages);
    pthread_mutex_destroy(&queue->lock);
}

void addMessageToQueue(MessageQueue *queue, Message *msg) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count == queue->capacity) {
        size_t new_capacity = queue->capacity ? queue->capacity * 2 : 16;
        queue->messages = realloc(queue->messages, new_capacity * sizeof(Message *));
    }
    queue->messages[queue->count++] = msg;
    pthread_mutex_unlock(&queue->lock);
}

size_t findLongestMessageLength(MessageQueue *queue) {
    size_t max_length = 0;
    pthread_mutex_lock(&queue->lock);
    for (size_t i = 0; i < queue->count; ++i) {
        if (strlen(queue->messages[i]->message) > max_length) {
            max_length = strlen(queue->messages[i]->message);
        }
    }
    pthread_mutex_unlock(&queue->lock);
    return max_length;
}

int shouldEncrypt(const char *opt, size_t length) {
    return (!strcmp(opt, "all") || (length % 2 == 0 && !strcmp(opt, "even")));
}

void encryptMessage(Message *msg) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char key[EVP_MAX_KEY_LENGTH] = {0};
    unsigned char iv[EVP_MAX_IV_LENGTH] = {0};

    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    int len;
    int ciphertext_len;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        exit(EXIT_FAILURE);
    }

    size_t input_length = strlen(msg->message);
    unsigned char *ciphertext = malloc(input_length + EVP_CIPHER_block_size(EVP_aes_256_cbc()));

    if (EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char *)msg->message, input_length) != 1) {
        exit(EXIT_FAILURE);
    }
    ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        exit(EXIT_FAILURE);
    }
    ciphertext_len += len;

    // Replace plaintext with encrypted message
    free(msg->message);
    msg->message = malloc(ciphertext_len);
    memcpy(msg->message, ciphertext, ciphertext_len);

    free(ciphertext);
    EVP_CIPHER_CTX_free(ctx);
}

void *processMessages(void *arg) {
    MessageQueue *queue = (MessageQueue *)arg;
    size_t longest_length = findLongestMessageLength(queue);

    pthread_mutex_lock(&queue->lock);
    for (size_t i = 0; i < queue->count; ++i) {
        Message *msg = queue->messages[i];
        if (shouldEncrypt("all", strlen(msg->message))) { // Replace "all" with actual option
            encryptMessage(msg);
        }
    }
    pthread_mutex_unlock(&queue->lock);

    return NULL;
}

void processAndEncryptMessages(int argc, char *argv[]) {
    MessageQueue queue;
    initMessageQueue(&queue);

    char line[1024];
    while (fgets(line, sizeof(line), stdin)) {
        int sender_id, recipient_id;
        char message[512];

        if (sscanf(line, "%d %d %[^\n]", &sender_id, &recipient_id, message) == 3) {
            Message *msg = malloc(sizeof(Message));
            msg->sender_id = sender_id;
            msg->recipient_id = recipient_id;
            msg->message = strdup(message);
            addMessageToQueue(&queue, msg);
        }
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, processMessages, &queue);
    }
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    freeMessageQueue(&queue);
}

int main(int argc, char *argv[]) {
    if (argc != 2 || (strcmp(argv[1], "all") != 0 && strcmp(argv[1], "even") != 0)) {
        fprintf(stderr, "Usage: %s <encrypt_option>\n", argv[0]);
        return EXIT_FAILURE;
    }

    processAndEncryptMessages(argc, argv);
    return EXIT_SUCCESS;
}
