#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdatomic.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Assuming RNTI is a unique identifier
    int CRC_INDICATION_REL8_TAG;
    _Atomic int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ENTRIES 1024

// Hash table structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries[MAX_ENTRIES];
    atomic_int size;
} NFAPI_CRC_TABLE;

// Initialize hash function
unsigned long hash(unsigned long RNTI) {
    return RNTI % MAX_ENTRIES;
}

// Function to initialize the NFAPI_CRC_TABLE
void init_crc_table(NFAPI_CRC_TABLE *table) {
    memset(table, 0, sizeof(*table));
    atomic_init(&table->size, 0);
}

// Add or update an entry based on RNTI
void add_or_update_entry(NFAPI_CRC_TABLE *table, NFAPI_CRC_INDICATION_PDU_T *entry) {
    unsigned long index = hash(entry->RNTI);
    NFAPI_CRC_INDICATION_PDU_T **slot = &table->entries[index];

    while (*slot != NULL && (*slot)->RNTI != entry->RNTI) {
        slot = (NFAPI_CRC_INDICATION_PDU_T**)((char*)slot + sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }

    if (*slot == NULL) {
        *slot = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        atomic_fetch_add_explicit(&table->size, 1, memory_order_relaxed);
    }

    **slot = *entry;
    (**slot).timestamp = time(NULL);
}

// Remove an entry by RNTI
void remove_entry(NFAPI_CRC_TABLE *table, unsigned long RNTI) {
    unsigned long index = hash(RNTI);
    NFAPI_CRC_INDICATION_PDU_T **slot = &table->entries[index];

    while (*slot != NULL && (*slot)->RNTI != RNTI) {
        slot = (NFAPI_CRC_INDICATION_PDU_T**)((char*)slot + sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }

    if (*slot != NULL) {
        free(*slot);
        *slot = NULL;
        atomic_fetch_sub_explicit(&table->size, 1, memory_order_relaxed);
    }
}

// Periodically clear entries older than a specified threshold
void clear_old_entries(NFAPI_CRC_TABLE *table, time_t threshold_ms) {
    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T **slot = &table->entries[i];

        while (*slot != NULL) {
