#include <sys/wait.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Union-Find structure and functions
typedef struct {
    int *parent, *rank;
    size_t size;
} UnionFind;

UnionFind* UF_create(size_t size) {
    UnionFind *uf = malloc(sizeof(UnionFind));
    uf->size = size;
    uf->parent = malloc(size * sizeof(int));
    uf->rank = malloc(size * sizeof(int));

    for (size_t i = 0; i < size; ++i) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
    return uf;
}

int UF_find(UnionFind *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = UF_find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void UF_union(UnionFind *uf, int x, int y) {
    int rootX = UF_find(uf, x);
    int rootY = UF_find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

void UF_destroy(UnionFind *uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

// Function to calculate a simple hash
unsigned int simple_hash(unsigned short rnti) {
    return (rnti ^ 0x5A5A5A5A) & 0xFFFFFFFF;
}

// Nested function for checking disjoint pairs using Union-Find
void* checkDisjointPairs(void *arg) {
    size_t num_entries = *((size_t*)arg);
    unsigned short rntis[num_entries];
    srand(time(NULL));

    // Initialize random RNTIs for example purposes
    for (size_t i = 0; i < num_entries; ++i) {
        rntis[i] = rand() % 10000;
    }

    UnionFind *uf = UF_create(num_entries);
    struct timespec start, end;

    clock_gettime(CLOCK_MONOTONIC, &start);

    for (size_t i = 0; i < num_entries - 1; ++i) {
        UF_union(uf, rntis[i], rntis[(i + 1) % num_entries]);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    long duration_us = (end.tv_sec - start.tv_sec) * 1000000L + (end.tv_nsec - start.tv_nsec) / 1000L;

    printf("Time taken for disjoint pairs check: %ld microseconds\n", duration_us);

    UF_destroy(uf);
    return NULL;
}

// Function to generate the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generateNfarcrcPduList(size_t num_entries) {
    pthread_t thread;
    size_t *num_entries_ptr = malloc(sizeof(size_t));
    *num_entries_ptr = num_entries;

    // Launch disjoint pairs check in a separate thread
    pthread_create(&thread, NULL, checkDisjointPairs, (void*)num_entries_ptr);
    pthread_detach(thread);

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) return NULL;

    for (size_t i = 0; i < num_entries; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i;
        pdu_list[i].RNTI = rand() % 10000;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 256;

        // Calculate CRCFLAG using a hash of RNTI and timestamp
        unsigned int hash = simple_hash(pdu_list[i].RNTI);
        time_t now = time(NULL);
        pdu_list[i].CRCFLAG = hash ^ ((unsigned int)now);
    }

    return pdu_list;
}

// Main function to run the command in background and check success of operations
int main(int argc, char *argv[]) {
    size_t num_entries = 1000; // Example number of entries
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = generateNfarcrcPduList(num_entries);

    if (!pdu_list) {
        printf("Failed to generate PDU list\n");
        return 0;
    }

    free(pdu_list);

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork failed");
        return 0;
    } else if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            printf("Command executed successfully\n");
            return 1;
        }
    } else { // Child process
        execlp(argv[1], argv[1], NULL); // Execute the specified command from arguments
        perror("execlp failed");
        exit(1);
    }

    return 0;
}
