    TX_RLC_PDU rlc_pdu;
    TX_PHY_PDU phy_pdu;
    time_t timestamp;
    int transmission_status;
} TX_FRAME_INFO;

typedef struct {
    TX_FRAME_INFO *frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned long checksum;
} FrameManager;

#define INITIAL_CAPACITY 10

void calculate_checksum(FrameManager *manager) {
    unsigned long cs = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        cs += manager->frames[i].id + /* Add other relevant fields */;
    }
    pthread_mutex_lock(&manager->lock);
    manager->checksum = cs;
    pthread_mutex_unlock(&manager->lock);
}

FrameManager* initialize_frame_manager() {
    FrameManager *manager = malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = malloc(INITIAL_CAPACITY * sizeof(TX_FRAME_INFO));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->checksum = 0;

    return manager;
}

int add_frame(FrameManager *manager, TX_FRAME_INFO frame) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TX_FRAME_INFO *new_frames = realloc(manager->frames, new_capacity * sizeof(TX_FRAME_INFO));
        if (!new_frames) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    manager->frames[manager->count++] = frame;
    calculate_checksum(manager);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_frame(FrameManager *manager, int id, TX_FRAME_INFO updated_frame) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i].id == id) {
            manager->frames[i] = updated_frame;
            calculate_checksum(manager);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Frame not found
}

TX_FRAME_INFO* get_frame(FrameManager *manager, int id) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i].id == id) {
            TX_FRAME_INFO *frame = malloc(sizeof(TX_FRAME_INFO));
            if (!frame) {
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }
            *frame = manager->frames[i];
            pthread_mutex_unlock(&manager->lock);
            return frame;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Frame not found
}

size_t get_frame_count(FrameManager *manager) {
    if (!manager) return (size_t)-1;

    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);

    return count;
}

void flush_outdated_frames(FrameManager *manager, time_t current_time, int max_age_seconds) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count;) {
        if (current_time - manager->frames[i].timestamp > max_age_seconds) {
            memmove(&manager->frames[i], &manager->frames[i + 1],
                    (--manager->count - i) * sizeof(TX_FRAME_INFO));
        } else {
            ++i;
        }
    }

    calculate_checksum(manager);
    pthread_mutex_unlock(&manager->lock);
}

void free_frame_manager(FrameManager *manager) {
    if (!manager) return;

    free(manager->frames);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` for thread safety.
- **Dynamic Array Management**: Handles dynamic resizing of the array when capacity is reached.
- **Checksum**: Maintains a checksum to verify integrity after modifications.
- **Error Handling**: Provides error handling for memory allocation failures.
- **Flushing Mechanism**: Supports flushing outdated frames based on timestamps."]

