// Add an entry ensuring the uniqueness of RNTI
int add_unique_entry(Node** head, unsigned short rnti, int seed) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 0; // Duplicate found
        }
        current = current->next;
    }

