    new_node->data.CRC_INDICATION_REL8_TAG = rand() % 256;   // Random value between 0-255
    new_node->data.CRCFLAG = rand() % 2;                     // Randomly set

    new_node->next = *head;
    *head = new_node;

    return 1;
}

// Serialize the list to a file
void serialize_list(const char* filename, Node* head) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

// Deserialize the list from a file
Node* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    Node* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory");
            break;
        }

        new_node->data = pdu;
        new_node->next = head;
        head = new_node;
    }

    fclose(file);
    return head;
}

// Simulate retrieving RNTI with retry logic
unsigned short retrieve_rnti_with_retry() {
    const int max_attempts = 5;
    unsigned short rnti = 0;

    for (int attempt = 1; attempt <= max_attempts; ++attempt) {
        // Simulating a network call that can fail
        if ((rand() % 10) < 7) { // 70% success rate
            rnti = rand() % 65536;
            return rnti;
        } else {
            fprintf(stderr, "Attempt %d failed to retrieve RNTI. Retrying...\n", attempt);
            sleep(1 << (attempt - 1)); // Exponential backoff
        }
    }

    if (!rnti) {
        perror("Failed to retrieve RNTI after multiple attempts");
        return 0;
    }

    return rnti;
}

// Free the list's memory
void free_list(Node* head) {
    Node* tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}
