    public:
        static std::mt19937 gen;

        explicit RandomCRCGenerator() {
            // Initialize random number generator with a seed based on the current time.
            std::random_device rd;
            gen.seed(rd());
        }

        ~RandomCRCGenerator() = default;

        static NFAPI_CRC_INDICATION_PDU_T create_pdu(unsigned int RNTI) {
