    class RNTPManager {
    private:
        unsigned int rnti;
        const size_t max_retries = 5;
        const size_t backoff_base_ms = 100;

        // Simulated external RNTI acquisition function.
        bool acquire_rnti() {
            return (rnti != 0); // Assume a non-zero RNTI indicates success
        }

    public:
        RNTPManager() : rnti(0) {}

        unsigned int get_rnti_with_retries() {
            size_t retries = 0;
            while (retries < max_retries && !acquire_rnti()) {
                std::this_thread::sleep_for(std::chrono::milliseconds(backoff_base_ms * (1 << retries)));
                retries++;
            }

            if (!acquire_rnti())
                throw std::runtime_error("Failed to acquire RNTI after maximum retries.");

            return rnti;
        }

        // Dummy function for acquiring an RNTI
