            // Simulated delay or failure condition.
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            rnti = 1234; // Example valid RNTI
        }
    };

    class CRCIndicationManager {
    private:
        static std::mutex mtx;
        static const size_t throttle_limit_per_sec = 10;
        static std::atomic<size_t> request_count;
        static std::chrono::steady_clock::time_point last_reset_time;

    public:
        static NFAPI_CRC_INDICATION_PDU_T generate_crc_pdu() {
            // Throttling mechanism
            {
                std::lock_guard<std::mutex> lock(mtx);
                auto now = std::chrono::steady_clock::now();

                if (now - last_reset_time > std::chrono::seconds(1)) {
                    request_count = 0;
                    last_reset_time = now;
                }

                if (request_count >= throttle_limit_per_sec) {
                    throw std::runtime_error("Exceeded rate limit of requests per second.");
                }
                request_count++;
            }

            RNTPManager rnti_manager;
            rnti_manager.simulate_external_source();

            auto rnti = rnti_manager.get_rnti_with_retries();

