typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t num_allocations;
    size_t total_memory_used;
} LinkedList;

void log_debug(const char* message) {
    printf("[DEBUG] %s\n", message);
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        log_debug("Failed to allocate memory for linked list.");
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->num_allocations = 0;
    list->total_memory_used = 0;

    return list;
}

void free_linked_list(LinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        list->num_allocations--;
        list->total_memory_used -= sizeof(Node);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return false;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_debug("Failed to allocate memory for a new node.");
        return false;
    }

    // Set random CRCFLAG value
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_lock(&list->lock);

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    list->num_allocations++;
    list->total_memory_used += sizeof(Node);

    log_debug("Added a new node to the linked list.");

    pthread_mutex_unlock(&list->lock);
    return true;
}

void get_list_stats(const LinkedList* list, size_t* num_allocations, size_t* total_memory_used) {
    if (!list || !num_allocations || !total_memory_used) return;

    pthread_mutex_lock(&list->lock);

    *num_allocations = list->num_allocations;
    *total_memory_used = list->total_memory_used;

    pthread_mutex_unlock(&list->lock);
}

// Example usage function
void example_usage() {
    LinkedList* list = create_linked_list();
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T data1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100 };
    add_node(list, data1);

    size_t num_allocations;
    size_t total_memory_used;
    get_list_stats(list, &num_allocations, &total_memory_used);

    printf("Allocations: %zu\n", num_allocations);
    printf("Total Memory Used: %zu bytes\n", total_memory_used);

    free_linked_list(list);
}

int main() {
    example_usage();
    return 0;
}
