#include <stdio.h>
#include <stdlib.h>
import threading

#define INITIAL_CAPACITY 10

typedef struct {
    long long timestamp;
    char* event_type; // String for flexibility and extensibility
    unsigned int id;
} NetworkEventLogEntry;

typedef struct {
    NetworkEventLogEntry* entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array();
void free_dynamic_array(DynamicArray* array);
int add_entry(DynamicArray* array, long long timestamp, const char* event_type, unsigned int id);
int remove_entry_by_id(DynamicArray* array, unsigned int id);
NetworkEventLogEntry** get_entries_by_timestamp_range(DynamicArray* array, long long start_time, long long end_time, size_t* result_count);
void resize_dynamic_array(DynamicArray* array);

// Helper function to find index by ID
static int find_index_by_id(const DynamicArray* array, unsigned int id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->entries[i].id == id) {
            return i;
        }
    }
    return -1;
}

// Helper function to copy string safely
static char* safe_strdup(const char* src) {
    char* dst = malloc(strlen(src) + 1);
    if (dst) strcpy(dst, src);
    return dst;
}

DynamicArray* create_dynamic_array() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->entries = calloc(array->capacity, sizeof(NetworkEventLogEntry));

    return array;
}

void free_dynamic_array(DynamicArray* array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        free(array->entries[i].event_type);
    }

    free(array->entries);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_entry(DynamicArray* array, long long timestamp, const char* event_type, unsigned int id) {
    if (!array || !event_type) return -1;

    pthread_mutex_lock(&array->lock);

    // Resize array if necessary
    if (array->size == array->capacity) {
        resize_dynamic_array(array);
    }

    // Check for duplicate ID
    if (find_index_by_id(array, id) != -1) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    NetworkEventLogEntry* entry = &array->entries[array->size++];
    entry->timestamp = timestamp;
    entry->event_type = safe_strdup(event_type);
    entry->id = id;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int remove_entry_by_id(DynamicArray* array, unsigned int id) {
    if (!array) return -1;

    pthread_mutex_lock(&array->lock);

    int index = find_index_by_id(array, id);
    if (index == -1) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    free(array->entries[index].event_type);

    // Shift elements to fill gap
    for (size_t i = index; i < array->size - 1; ++i) {
        array->entries[i] = array->entries[i + 1];
    }
    --array->size;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

NetworkEventLogEntry** get_entries_by_timestamp_range(DynamicArray* array, long long start_time, long long end_time, size_t* result_count) {
    if (!array || !result_count) return NULL;

    pthread_mutex_lock(&array->lock);

    *result_count = 0;
    NetworkEventLogEntry** results = malloc(array->size * sizeof(NetworkEventLogEntry*));
    if (!results) {
        pthread_mutex_unlock(&array->lock);
        return NULL;
    }

    for (size_t i = 0; i < array->size; ++i) {
        if (array->entries[i].timestamp >= start_time && array->entries[i].timestamp <= end_time) {
            results[(*result_count)++] = &array->entries[i];
        }
    }

    pthread_mutex_unlock(&array->lock);
    return results;
}

void resize_dynamic_array(DynamicArray* array) {
    size_t new_capacity = array->capacity * 2;
    NetworkEventLogEntry* new_entries = realloc(array->entries, new_capacity * sizeof(NetworkEventLogEntry));

    if (new_entries) {
        array->entries = new_entries;
        array->capacity = new_capacity;
    }
}

