}

int fetch_RNTI() {
    // Simulate a delay or failure scenario
    return rand() % MAX_TAG_VALUE + 1;
}

// Error logging function
void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(int N, int *allocated_count) {
    if (N <= 0) {
        log_error("Invalid number of elements requested.");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(INITIAL_ALLOCATION_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Initial memory allocation failed.");
        return NULL;
    }

    int current_size = INITIAL_ALLOCATION_SIZE;
    *allocated_count = 0;

    for (int i = 0; i < N; ) {
        if (*allocated_count >= current_size) {
            current_size *= 2; // Double the size
            NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(array, current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!temp_array) {
                log_error("Memory reallocation failed.");
                free(array);
                return NULL;
            }
            array = temp_array;
        }

        int RX_UE_INFORMATION_TAG = fetch_RX_UE_INFORMATION_TAG();
        int RNTI = fetch_RNTI();

        if (RX_UE_INFORMATION_TAG <= 0 || RX_UE_INFORMATION_TAG > MAX_TAG_VALUE ||
            RNTI <= 0 || RNTI > MAX_TAG_VALUE) {
            log_error("Invalid tag or RNTI value fetched.");
            continue; // Skip this iteration and try again
        }

        int CRCFLAG;
        if (i == 0) {
            CRCFLAG = rand() % 2; // Randomly set CRCFLAG for the first element
        } else {
            CRCFLAG = !array[*allocated_count - 1].CRCFLAG; // Ensure no adjacent elements have the same CRCFLAG
        }

        array[*allocated_count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        array[*allocated_count].RNTI = RNTI;
        array[*allocated_count].CRCFLAG = CRCFLAG;

        (*allocated_count)++;
        i++;
    }

    return realloc(array, *allocated_count * sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Resize to the exact number of allocated elements
}

int main() {
    int N = 100; // Example size
    int allocated_count;
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_crc_indications(N, &allocated_count);

    if (array) {
        printf("Successfully allocated %d elements.\n", allocated_count);
        free(array); // Clean up
    } else {
        printf("Failed to allocate memory.\n");
    }

    return 0;
}
