    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define error codes.
enum ErrorCode {
    ERROR_NONE,
    ERROR_INVALID_INPUT,
    ERROR_MEMORY_ALLOCATION,
    ERROR_MAX_LIMIT_REACHED
};

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes.
bool validate_inputs(uint8_t tag, uint16_t rnti);
void log_error(enum ErrorCode code);

// Initialize memory pool.
MemoryPool* init_memory_pool() {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->data = NULL;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Destroy memory pool.
void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        free(pool->data);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

// Allocate a new structure in the memory pool.
enum ErrorCode allocate_structure(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!validate_inputs(pdu->RX_UE_INFORMATION_TAG, pdu->RNTI)) {
        log_error(ERROR_INVALID_INPUT);
        return ERROR_INVALID_INPUT;
    }

    pthread_mutex_lock(&pool->lock);

    if (pool->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&pool->lock);
        log_error(ERROR_MAX_LIMIT_REACHED);
        return ERROR_MAX_LIMIT_REACHED;
    }

    pool->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->data, 
                                                      (pool->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        pthread_mutex_unlock(&pool->lock);
        log_error(ERROR_MEMORY_ALLOCATION);
        return ERROR_MEMORY_ALLOCATION;
    }

    // Set CRCFLAG randomly and ensure no two adjacent structures share the same value.
    pdu->CRCFLAG = (rand() % 2 == 0);

    if (pool->count > 0 && ((uintptr_t)pool->data + pool->count - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T) != (uintptr_t)pdu) {
        NFAPI_CRC_INDICATION_PDU_T *last_pdu = &pool->data[pool->count - 1];
        if (pdu->CRCFLAG == last_pdu->CRCFLAG) {
            pdu->CRCFLAG = !pdu->CRCFLAG;
        }
    }

    pool->data[pool->count++] = *pdu;

    pthread_mutex_unlock(&pool->lock);
    return ERROR_NONE;
}

// Validate inputs.
bool validate_inputs(uint8_t tag, uint16_t rnti) {
    return (tag >= MIN_RX_UE_INFORMATION_TAG && tag <= MAX_RX_UE_INFORMATION_TAG &&
            rnti >= MIN_RNTI && rnti <= MAX_RNTI);
}

// Log errors.
void log_error(enum ErrorCode code) {
    switch (code) {
        case ERROR_INVALID_INPUT:
            printf("Error: Invalid input values.\n");
            break;
        case ERROR_MEMORY_ALLOCATION:
            printf("Error: Memory allocation failed.\n");
            break;
        case ERROR_MAX_LIMIT_REACHED:
            printf("Error: Maximum limit of structures reached.\n");
            break;
        default:
            printf("Error: Unknown error occurred.\n");
    }
}
