    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node in the doubly linked list with reference counting and thread safety
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int ref_count;
    struct Node* prev;
    struct Node* next;
} Node;

// Doubly linked list structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} LinkedList;

// Function prototypes
LinkedList* init_list();
int populate_list(LinkedList* list, int count);
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu);
void free_node(Node* node);
int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
int remove_node(LinkedList* list, Node* node);
void update_rx_ue_info_tag(LinkedList* list, int rnti, int new_tag);

// Function implementations
LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int populate_list(LinkedList* list, int count) {
    if (count <= 0 || !list) return -1;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Simulate fetching data from an external source
        int status = rand() % 2; // Randomly simulate a failure or success
        if (status == 1) {
            fprintf(stderr, "Failed to fetch RX_UE_INFORMATION_TAG\n");
            continue;
        }

        pdu.RX_UE_INFORMATION_TAG = rand(); // Placeholder for fetched data
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2;

        add_node(list, pdu);
    }

    return 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = pdu;
    node->ref_count = 1;
    node->prev = NULL;
    node->next = NULL;

    return node;
}

void free_node(Node* node) {
    if (!node) return;
    free(node);
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = create_node(pdu);
    if (!new_node) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int remove_node(LinkedList* list, Node* node) {
    if (!node || !list || node->ref_count > 1) return -1;

    pthread_mutex_lock(&list->lock);

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (node == list->head) list->head = node->next;
    if (node == list->tail) list->tail = node->prev;

    pthread_mutex_unlock(&list->lock);

    free_node(node);

    return 0;
}

void update_rx_ue_info_tag(LinkedList* list, int rnti, int new_tag) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            current->data.RX_UE_INFORMATION_TAG = new_tag;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage and test
int main() {
    LinkedList* list = init_list();
    if (!list) return -1;

    populate_list(list, 10);

    // Example update operation
    update_rx_ue_info_tag(list, 1234, 5678); // Replace with actual RNTI

    // Clean up and destroy the list
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);

    return 0;
}
