#define MAX_ENTRIES 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    CRC_INDICATION_REL8_TAG_T crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->count = 0;
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        array->entries[i] = NULL;
    }
    pthread_mutex_init(&array->lock, NULL);
}

static int find_index_by_rnti(const DynamicArray *array, uint16_t rnti) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i]->crc_tag.RNTI == rnti) {
            return i;
        }
    }
    return -1;
}

int add_entry(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T entry, unsigned int seed) {
    pthread_mutex_lock(&array->lock);

    if (find_index_by_rnti(array, entry.crc_tag.RNTI) != -1 || array->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&array->lock);
        return 0; // Duplicate RNTI or no space
    }

    int index = array->count++;
    NFAPI_CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        pthread_mutex_unlock(&array->lock);
        return 0; // Memory allocation failed
    }
    *new_entry = entry;

    srand(seed + index); // Seed based on index for reproducibility
    new_entry->crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

    array->entries[index] = new_entry;

    pthread_mutex_unlock(&array->lock);
    return 1; // Success
}

size_t get_total_entries(const DynamicArray *array) {
    size_t count;
    pthread_mutex_lock(&array->lock);
    count = array->count;
    pthread_mutex_unlock(&array->lock);
    return count;
}

void free_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i]) {
            free(array->entries[i]);
        }
    }
    pthread_mutex_destroy(&array->lock);
}

// Example usage
int main() {
    DynamicArray array;
    init_dynamic_array(&array);

    NFAPI_CRC_INDICATION_PDU_T entry = { .crc_tag = { .RNTI = 123 } };

    if (add_entry(&array, entry, 42)) {
        printf("Entry added successfully.\n");
    }

    printf("Total entries: %zu\n", get_total_entries(&array));

    free_dynamic_array(&array);
    return 0;
}
