['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define PRIMARY_LIST_MAX_SIZE 100
#define SECONDARY_QUEUE_WATERMARK 75

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode* freeList;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* primary_list[PRIMARY_LIST_MAX_SIZE];
    int size;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* secondary_queue;
    int secondary_size;
} NFAPI_List;

// Initialize memory pool
MemoryPool* initialize_memory_pool(size_t block_count) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->freeList = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < block_count; ++i) {
        MemoryPoolNode* node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
        node->next = pool->freeList;
        pool->freeList = node;
    }
    return pool;
}

// Allocate a structure from the memory pool
NFAPI_CRC_INDICATION_PDU_T* allocate_structure(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (!pool->freeList) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool exhausted
    }
    MemoryPoolNode* node = pool->freeList;
    pool->freeList = node->next;
    NFAPI_CRC_INDICATION_PDU_T* data = &node->data;
    pthread_mutex_unlock(&pool->lock);
    return data;
}

// Return a structure to the memory pool
void deallocate_structure(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    MemoryPoolNode* node = (MemoryPoolNode*)data;
    pthread_mutex_lock(&pool->lock);
    node->next = pool->freeList;
    pool->freeList = node;
    pthread_mutex_unlock(&pool->lock);
}

// Initialize the NFAPI list
NFAPI_List* initialize_nfa_list() {
    NFAPI_List* nfa_list = (NFAPI_List*)malloc(sizeof(NFAPI_List));
    for (int i = 0; i < PRIMARY_LIST_MAX_SIZE; ++i) {
        nfa_list->primary_list[i] = NULL;
    }
    pthread_mutex_init(&nfa_list->lock, NULL);
    nfa_list->secondary_queue = NULL;
    nfa_list->secondary_size = 0;
    nfa_list->size = 0;
    return nfa_list;
}

// Add a structure to the NFAPI list
void add_structure(NFAPI_List* nfa_list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&nfa_list->lock);
    if (nfa_list->size < PRIMARY_LIST_MAX_SIZE) {
        nfa_list->primary_list[nfa_list->size++] = data;
    } else {
        // Add to secondary queue
        MemoryPoolNode* node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
        node->data = *data;
        node->next = nfa_list->secondary_queue;
        nfa_list->secondary_queue = node;
        nfa_list->secondary_size++;
    }
    pthread_mutex_unlock(&nfa_list->lock);

    // Process secondary queue if watermark is reached
    if (nfa_list->size >= SECONDARY_QUEUE_WATERMARK) {
        process_secondary_queue(nfa_list);
    }
}

// Process the secondary queue
void process_secondary_queue(NFAPI_List* nfa_list) {
    pthread_mutex_lock(&nfa_list->lock);
    while (nfa_list->secondary_size > 0 && nfa_list->size < PRIMARY_LIST_MAX_SIZE) {
        MemoryPoolNode* node = nfa_list->secondary_queue;
        nfa_list->secondary_queue = node->next;
        nfa_list->primary_list[nfa_list->size++] = &node->data;
        free(node);
        nfa_list->secondary_size--;
    }
    pthread_mutex_unlock(&nfa_list->lock);
}

// Simulate real-time updates and populate the list
void update_and_populate(NFAPI_List* nfa_list, MemoryPool* pool) {
    srand(time(NULL));
    for (int i = 0; i < 200; ++i) { // Simulate more entries than primary can hold
        NFAPI_CRC_INDICATION_PDU_T* data = allocate_structure(pool);
        if (!data) break;

        // Simulate external updates
        data->RX_UE_INFORMATION_TAG = rand() % 1000;
        data->RNTI = rand() % 500;
        data->CRC_INDICATION_REL8_TAG = rand() % 10;
        data->CRCFLAG = rand() % 2; // Random CRCFLAG

        add_structure(nfa_list, data);
    }
}

// Deallocate all structures
void deallocate_all(NFAPI_List* nfa_list, MemoryPool* pool) {
    pthread_mutex_lock(&nfa_list->lock);
    for (int i = 0; i < PRIMARY_LIST_MAX_SIZE; ++i) {
        if (nfa_list->primary_list[i]) {
            deallocate_structure(pool, nfa_list->primary_list[i]);
        }
    }

    MemoryPoolNode* node = nfa_list->secondary_queue;
    while (node) {
        MemoryPoolNode* temp = node;
        node = node->next;
        deallocate_structure(pool, &temp->data);
        free(temp);
    }
    pthread_mutex_unlock(&nfa_list->lock);

    // Clean up memory pool
    pthread_mutex_lock(&pool->lock);
    while (pool->freeList) {
        MemoryPoolNode* temp = pool->freeList;
        pool->freeList = temp->next;
        free(temp);
    }
    pthread_mutex_unlock(&pool->lock);
}

// Unit tests for the implementation
void test_nfa_list() {
    // Initialize memory pool and NFAPI list
    MemoryPool* pool = initialize_memory_pool(200);
    NFAPI_List* nfa_list = initialize_nfa_list();

    // Update and populate the list
    update_and_populate(nfa_list, pool);

    // Verify primary list size does not exceed max size
    pthread_mutex_lock(&nfa_list->lock);
    if (nfa_list->size > PRIMARY_LIST_MAX_SIZE) {
        printf("Test failed: Primary list exceeded max size.\n");
    } else {
        printf("Primary list size is within limits.\n");
    }
    pthread_mutex_unlock(&nfa_list->lock);

    // Verify secondary queue processing
    if (nfa_list->secondary_size > 0 && nfa_list->size >= PRIMARY_LIST_MAX_SIZE) {
        process_secondary_queue(nfa_list);
        pthread_mutex_lock(&nfa_list->lock);
        printf("Secondary queue processed. Remaining size: %d\n", nfa_list->secondary_size);
        pthread_mutex_unlock(&nfa_list->lock);
    }

    // Deallocate all structures
    deallocate_all(nfa_list, pool);

    // Clean up
    free(nfa_list);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int main() {
    test_nfa_list();
    return 0;
}
