#include <pthread.h>

#define DEFAULT_MAX_ENTRIES 1000

typedef struct {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct EntryNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct EntryNode* next;
} EntryNode;

typedef struct {
    EntryNode** table;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void log_warning(const char* message) {
    FILE* logFile = fopen("log.txt", "a");
    if (logFile) {
        fprintf(logFile, "WARNING: %s\n", message);
        fclose(logFile);
    }
}

void log_error(const char* message) {
    FILE* logFile = fopen("error_log.txt", "a");
    if (logFile) {
        fprintf(logFile, "ERROR: %s\n", message);
        fclose(logFile);
    }
}

unsigned int hash_function(uint16_t rnti, size_t capacity) {
    return rnti % capacity;
}

void initialize_random(unsigned int* seed) {
    if (*seed == 0) {
        *seed = (unsigned int)time(NULL);
    }
    srand(*seed);
}

uint32_t get_random_crcflag() {
    return rand() & 1; // Randomly set CRCFLAG to 0 or 1
}

DynamicArray* create_dynamic_array(size_t capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) {
        log_error("Memory allocation failed for dynamic array");
        return NULL;
    }

    array->table = calloc(capacity, sizeof(EntryNode*));
    if (!array->table) {
        free(array);
        log_error("Memory allocation failed for hash table");
        return NULL;
    }

    array->capacity = capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->capacity; ++i) {
        EntryNode* node = array->table[i];
        while (node) {
            EntryNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(array->table);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_entry(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!array || array->count >= array->capacity) return 0;

    pthread_mutex_lock(&array->lock);

    unsigned int index = hash_function(entry.RNTI, array->capacity);
    EntryNode* node = array->table[index];

    while (node) {
        if (node->data.RNTI == entry.RNTI) {
            log_warning("Duplicate RNTI encountered");
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        node = node->next;
    }

    EntryNode* newNode = malloc(sizeof(EntryNode));
    if (!newNode) {
        log_error("Memory allocation failed for new entry");
        pthread_mutex_unlock(&array->lock);
        return 0;
    }

    newNode->data = entry;
    newNode->next = array->table[index];
    array->table[index] = newNode;
    ++array->count;

    pthread_mutex_unlock(&array->lock);
    return 1;
}

size_t get_total_entries(const DynamicArray* array) {
    if (!array) return 0;

    size_t totalEntries = 0;
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->capacity; ++i) {
        EntryNode* node = array->table[i];
        while (node) {
            ++totalEntries;
            node = node->next;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return totalEntries;
}

void clear_array(DynamicArray* array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->capacity; ++i) {
        EntryNode* node = array->table[i];
        while (node) {
            EntryNode* temp = node;
            node = node->next;
            free(temp);
        }
        array->table[i] = NULL;
    }

    array->count = 0;

    pthread_mutex_unlock(&array->lock);
}

int main() {
    size_t maxEntries = DEFAULT_MAX_ENTRIES;
    unsigned int seed = 12345; // Example seed
    initialize_random(&seed);

    DynamicArray* array = create_dynamic_array(maxEntries);
    if (!array) return EXIT_FAILURE;

    NFAPI_CRC_INDICATION_PDU_T entry;
    entry.RX_UE_INFORMATION_TAG = 1;
    entry.RNTI = rand() % maxEntries; // Example RNTI
    entry.crcTag.CRCFLAG = get_random_crcflag();

    if (add_entry(array, entry)) {
        printf("Entry added. Total entries: %zu\n", get_total_entries(array));
    }

    clear_array(array);
    destroy_dynamic_array(array);

    return EXIT_SUCCESS;
}
