['Below is a C implementation for managing a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures as described in your requirements. The code uses pthreads for concurrency and a simple hash table for ensuring unique `RNTI` values.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_ENTRIES 10000

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Entry {
    uint32_t rnti;
    struct Entry *next;
    NFAPI_CRC_INDICATION_PDU_T data;
} HashEntry;

#define HASH_TABLE_SIZE 10007 // A prime number for better distribution

HashEntry *hashTable[HASH_TABLE_SIZE];
pthread_mutex_t hashMutex = PTHREAD_MUTEX_INITIALIZER;
size_t totalEntries = 0;
uint32_t seed = 12345; // Example seed

// Simple hash function
unsigned int hashRNTI(uint32_t rnti) {
    return rnti % HASH_TABLE_SIZE;
}

// Random number generator (Linear Congruential Generator)
int lcg_random() {
    static uint32_t state = seed;
    state = 1664525 * state + 1013904223;
    return state >> 16;
}

// Set CRCFLAG randomly
void setRandomCRCFlag(CRC_INDICATION_REL8_TAG_T *crcTag) {
    crcTag->CRCFLAG = lcg_random() & 0xFFFF; // Ensure it's a 16-bit value
}

// Add entry to the hash table
int addEntry(NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned int index = hashRNTI(pdu.RNTI);

    pthread_mutex_lock(&hashMutex);

    for (HashEntry *entry = hashTable[index]; entry != NULL; entry = entry->next) {
        if (entry->rnti == pdu.RNTI) {
            printf("Duplicate RNTI found: %u\n", pdu.RNTI);
            pthread_mutex_unlock(&hashMutex);
            return -1;
        }
    }

    if (totalEntries >= MAX_ENTRIES) {
        printf("Maximum entries reached.\n");
        pthread_mutex_unlock(&hashMutex);
        return -2;
    }

    HashEntry *newEntry = malloc(sizeof(HashEntry));
    if (!newEntry) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&hashMutex);
        return -3;
    }

    newEntry->rnti = pdu.RNTI;
    newEntry->data = pdu;
    newEntry->next = hashTable[index];
    hashTable[index] = newEntry;

    setRandomCRCFlag(&(newEntry->data.CRC_INDICATION_REL8_TAG));

    totalEntries++;
    pthread_mutex_unlock(&hashMutex);

    return 0;
}

// Get the number of entries
size_t getTotalEntries() {
    pthread_mutex_lock(&hashMutex);
    size_t count = totalEntries;
    pthread_mutex_unlock(&hashMutex);
    return count;
}

// Initialize hash table
void initHashTable() {
    memset(hashTable, 0, sizeof(hashTable));
}

// Clean up resources
void cleanupHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashEntry *entry = hashTable[i];
        while (entry != NULL) {
            HashEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
}

// Example usage
int main() {
    initHashTable();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100 };
    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 200 };

    if (addEntry(pdu1) == 0) {
        printf("Added entry with RNTI: %u\n", pdu1.RNTI);
    }

    if (addEntry(pdu2) == 0) {
        printf("Added entry with RNTI: %u\n", pdu2.RNTI);
    }

    printf("Total entries: %zu\n", getTotalEntries());

    cleanupHashTable();
    return 0;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex` to ensure thread safety.
- **Hash Table**: Utilized for efficient RNTI uniqueness check.
- **Randomization**: Linear Congruential Generator (LCG) for CRCFLAG setting.
- **Error Handling**: Returns error codes and uses `perror` for memory allocation failures.
- **Scalability**: The hash table can be expanded or replaced with more sophisticated structures as needed.

This implementation provides a basic framework that can be extended to meet additional requirements, such as integrating with data pipelines or using more advanced random number generators.']

