    unsigned long ip_long = inet_addr(ip);
    unsigned long mask_long = inet_addr(subnet_mask);
    unsigned long gw_long = inet_addr(gateway);

    return ((ip_long & mask_long) == (gw_long & mask_long));
}

unsigned long hash_network_config(const NetworkConfig* config) {
    // Simple hash function combining IP address, subnet mask, and gateway
    unsigned long hash = 5381;
    hash = ((hash << 5) + hash) + inet_addr(config->ip_address);
    hash = ((hash << 5) + hash) + inet_addr(config->subnet_mask);
    hash = ((hash << 5) + hash) + inet_addr(config->gateway);
    return hash;
}

// Core library function implementations
void init_collection(ConfigCollection* collection) {
    collection->head = NULL;
    collection->unique_count = 0;
    collection->duplicate_count = 0;
}

void free_collection(ConfigCollection* collection) {
    Node* current = collection->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    collection->head = NULL;
}

int add_config(ConfigCollection* collection, NetworkConfig new_config) {
    if (!is_valid_ip(new_config.ip_address) || !is_same_subnet(new_config.ip_address, 
                                                                new_config.subnet_mask, 
                                                                new_config.gateway)) {
        return -1; // Invalid configuration
    }

    unsigned long hash = hash_network_config(&new_config);
    Node* current = collection->head;

    while (current != NULL) {
        if (hash == hash_network_config(&(current->config))) {
            collection->duplicate_count++;
            return 0; // Duplicate found, not added
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->config = new_config;
    new_node->next = collection->head;
    collection->head = new_node;
    collection->unique_count++;

    return 1; // Successfully added
}

NetworkConfig* get_config_by_ip(ConfigCollection* collection, const char* ip) {
    Node* current = collection->head;
    while (current != NULL) {
        if (strcmp(current->config.ip_address, ip) == 0) {
            return &(current->config);
        }
        current = current->next;
    }
    return NULL; // Not found
}

size_t get_unique_count(ConfigCollection* collection) {
    return collection->unique_count;
}

size_t get_duplicate_count(ConfigCollection* collection) {
    return collection->duplicate_count;
}
