    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->pdus = malloc(max_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->config_count = 0;
    manager->max_configs = max_configs;
    manager->configs = malloc(max_configs * sizeof(NetInterfaceConfig));
    manager->pdu_count = 0;
    manager->max_pdus = max_pdus;

    manager->unique_entries = 0;
    manager->duplicate_entries = 0;

    return manager;
}

void destroy_network_manager(NetworkManager *manager) {
    if (!manager) return;
    pthread_mutex_destroy(&manager->lock);
    free(manager->pdus);
    for (size_t i = 0; i < manager->config_count; ++i) {
        for (int j = 0; j < manager->configs[i].active_interface_count; ++j) {
            free(manager->configs[i].active_interfaces[j]);
        }
    }
