    if (!is_valid_subnet_mask(new_config->subnet_mask)) return false;
    if (!is_valid_gateway(new_config->gateway)) return false;

    pthread_mutex_lock(&manager->lock);

    NetInterfaceConfig *duplicate = find_duplicate_config(manager, new_config);
    if (duplicate) {
        manager->duplicate_entries++;
        log_message("INFO", "Duplicate configuration detected.");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    if (manager->config_count >= manager->max_configs) {
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    manager->configs[manager->config_count++] = *new_config;
    manager->unique_entries++;

    pthread_mutex_unlock(&manager->lock);
    log_message("INFO", "Configuration added successfully.");
    return true;
}

