    struct in_addr addr;
    if (!inet_aton(mask, &addr)) return false;

    uint32_t mask_val = ntohl(addr.s_addr);
    // Check for valid subnet mask pattern
    return ((mask_val & (mask_val + 1)) == 0) && (mask_val != 0);
}

bool is_valid_gateway(const char *gateway) {
