#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_ENTRIES 100000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_rwlock_t lock;
} NFAPI_CRC_LIST_T;

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

NFAPI_CRC_LIST_T* create_crc_list() {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T *)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) {
        log_error("Memory allocation failed for list");
        return NULL;
    }
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

int resize_crc_list(NFAPI_CRC_LIST_T *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entries) {
        log_error("Memory reallocation failed");
        return -1;
    }
    list->entries = new_entries;
    list->capacity = new_capacity;
    return 0;
}

int add_crc_entry(NFAPI_CRC_LIST_T *list, uint16_t rx_tag, uint16_t rnti) {
    pthread_rwlock_wrlock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        if (new_capacity > MAX_ENTRIES) new_capacity = MAX_ENTRIES;
        if (resize_crc_list(list, new_capacity) != 0) {
            pthread_rwlock_unlock(&list->lock);
            return -1;
        }
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == rnti) {
            pthread_rwlock_unlock(&list->lock);
            log_error("Duplicate RNTI found");
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T entry = {rx_tag, rnti, rand() % 2};
    list->entries[list->count++] = entry;
    pthread_rwlock_unlock(&list->lock);
    return 0;
}

void free_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list) {
        pthread_rwlock_destroy(&list->lock);
        free(list->entries);
        free(list);
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_entry(const NFAPI_CRC_LIST_T *list, size_t index) {
    pthread_rwlock_rdlock(&list->lock);
    if (index < list->count) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[index];
        pthread_rwlock_unlock(&list->lock);
        return entry;
    }
    pthread_rwlock_unlock(&list->lock);
    return NULL;
}

void test_crc_list() {
    srand(time(NULL));
    NFAPI_CRC_LIST_T *crc_list = create_crc_list();
    if (!crc_list) return;

    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        uint16_t rx_tag = rand() % 100;
        uint16_t rnti = rand() % 65536;
        if (add_crc_entry(crc_list, rx_tag, rnti) != 0) break;
    }

    for (size_t i = 0; i < crc_list->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = get_crc_entry(crc_list, i);
        if (entry) {
            printf("Entry %zu: RX_TAG=%u, RNTI=%u, CRCFLAG=%u\n", i, entry->RX_UE_INFORMATION_TAG, entry->RNTI, entry->CRCFLAG);
        }
    }

    free_crc_list(crc_list);
}

int main() {
    test_crc_list();
    return 0;
}
```

