- Logging for error conditions.
- Unit tests to demonstrate typical usage.']

["```javascript
const fs = require('fs').promises;
const path = require('path');
const { createReadStream } = require('stream');
const readline = require('readline');

async function filterFiles(directory, ageThreshold) {
    const now = Date.now();
    let filePromises = [];

    // Asynchronously read directory contents
    try {
        const files = await fs.readdir(directory);

        for (let i = 0; i < files.length; i++) {
            const filePath = path.join(directory, files[i]);

            if ((now - ageThreshold) > now) continue; // skip future-dated files

            filePromises.push(async () => {
                try {
                    const stats = await fs.stat(filePath);

                    if (stats.size <= 10 * 1024 * 1024 && now - stats.mtimeMs < ageThreshold) {
                        console.log(`Processing file: ${filePath}`);
                        return filePath;
                    }
                } catch (err) {
                    console.error(`Error accessing file: ${filePath}`, err);
                }
            });
        }

        const results = await Promise.all(filePromises.map(p => p()));
        return results.filter(Boolean);

    } catch (error) {
        console.error('Error reading directory:', error);
        throw error;
    }
}

// Usage Example
const DIR_PATH = './your-directory-path';
const AGE_THRESHOLD_MS = 30 * 24 * 60 * 60 * 1000; // Files older than 30 days

filterFiles(DIR_PATH, AGE_THRESHOLD_MS)
    .then(filteredPaths => {
        console.log('Filtered file paths:', filteredPaths);
    })
    .catch(error => {
        console.error('An error occurred:', error);
    });
```

