#include <string.h>

#define MAX_THEME_LENGTH 20
#define MAX_RECENT_FEATURES 10

typedef struct {
    char theme[MAX_THEME_LENGTH + 1];
    int notificationSettings;
} UserPreferences;

typedef struct FeatureNode {
    char featureName[50];
    struct FeatureNode* next;
} FeatureNode;

typedef struct {
    FeatureNode* head;
    size_t count;
} RecentlyUsedFeatures;

int isValidTheme(const char *theme) {
    return theme && strlen(theme) <= MAX_THEME_LENGTH;
}

int areNotificationSettingsCompatible(int settings) {
    // Placeholder for actual device capability check
    return 1; // Assume always compatible for this example
}

FeatureNode* findFeature(RecentlyUsedFeatures* list, const char *featureName) {
    FeatureNode* current = list->head;
    while (current) {
        if (strcmp(current->featureName, featureName) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void addFeature(RecentlyUsedFeatures* list, const char *featureName) {
    FeatureNode* existing = findFeature(list, featureName);
    if (existing) {
        // Move to front for LRU-like behavior
        if (list->head != existing) {
            FeatureNode* prev = list->head;
            while (prev && prev->next != existing) {
                prev = prev->next;
            }
            if (prev) {
                prev->next = existing->next;
                existing->next = list->head;
                list->head = existing;
            }
        }
    } else {
        FeatureNode* newFeature = malloc(sizeof(FeatureNode));
        if (!newFeature) return; // Handle memory allocation failure
        strncpy(newFeature->featureName, featureName, sizeof(newFeature->featureName) - 1);
        newFeature->next = list->head;
        list->head = newFeature;
        list->count++;
        if (list->count > MAX_RECENT_FEATURES) {
            // Remove least recently used
            FeatureNode* toRemove = list->head;
            list->head = list->head->next;
            free(toRemove);
            list->count--;
        }
    }
}

int updatePreferences(UserPreferences *prefs, const char *theme, int notificationSettings, const char *recentFeature) {
    if (!isValidTheme(theme)) return -1; // Invalid theme
    if (!areNotificationSettingsCompatible(notificationSettings)) return -2; // Incompatible settings

    strncpy(prefs->theme, theme, MAX_THEME_LENGTH);
    prefs->notificationSettings = notificationSettings;

    addFeature(&(prefs->recentFeatures), recentFeature);

    return 0; // Success
}

void freePreferences(UserPreferences *prefs) {
    FeatureNode* current = prefs->recentFeatures.head;
    while (current) {
        FeatureNode* next = current->next;
        free(current);
        current = next;
    }
    prefs->recentFeatures.head = NULL;
    prefs->recentFeatures.count = 0;
}

int main() {
    UserPreferences userPrefs = { .theme = "", .notificationSettings = 0, .recentFeatures = {NULL, 0} };

    int result = updatePreferences(&userPrefs, "DarkMode", 1, "FeatureA");
    if (result == 0) {
        printf("Preferences updated successfully.\n");
    } else {
        printf("Failed to update preferences. Error code: %d\n", result);
    }

    freePreferences(&userPrefs);

    return 0;
}
