#define MAX_PDUS 10000
#define API_MAX_RETRIES 3

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} UE_DATA_PAIR;

pthread_mutex_t pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Mock function to simulate API call
int fetch_UE_data(UE_DATA_PAIR *data, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        data[i].RX_UE_INFORMATION_TAG = rand() % 100000;
        data[i].RNTI = rand() % 65535;
    }
    return 0; // Success
}

unsigned char calculate_checksum(unsigned int tag) {
    unsigned char checksum = 0;
    while (tag) {
        checksum ^= tag & 0xFF;
        tag >>= 8;
    }
    return checksum;
}

void log_verbose(const char *message, ...) {
    va_list args;
    va_start(args, message);
    vprintf(message, args);
    printf("\n");
    va_end(args);
}

void log_summary(const char *message) {
    printf("%s\n", message);
}

int generate_pdlus(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t max_pdus) {
    if (!pdus || max_pdus == 0) return -1;

    pthread_mutex_lock(&pdu_list_mutex);

    unsigned int rnti_set[65536] = {0};
    size_t pdu_count = 0;
    UE_DATA_PAIR ue_data_pairs[100]; // Buffer for fetched data
    int retries, api_status;

    while (pdu_count < max_pdus) {
        if ((api_status = fetch_UE_data(ue_data_pairs, sizeof(ue_data_pairs) / sizeof(ue_data_pairs[0]))) != 0) {
            for (retries = 0; retries < API_MAX_RETRIES && api_status != 0; ++retries) {
                log_verbose("API call failed, retrying (%d/%d)...", retries + 1, API_MAX_RETRIES);
                if ((api_status = fetch_UE_data(ue_data_pairs, sizeof(ue_data_pairs) / sizeof(ue_data_pairs[0]))) == 0)
                    break;
            }
        }

        if (api_status != 0) {
            log_summary("Failed to fetch UE data after retries.");
            pthread_mutex_unlock(&pdu_list_mutex);
            return -1; // Failure
        }

        for (size_t i = 0; i < sizeof(ue_data_pairs) / sizeof(ue_data_pairs[0]) && pdu_count < max_pdus; ++i) {
            unsigned int rnti = ue_data_pairs[i].RNTI;
            if (rnti_set[rnti] || pdu_count == UINT_MAX - 1) { // Handle overflow condition
                continue;
            }

            pdus[pdu_count].RX_UE_INFORMATION_TAG = ue_data_pairs[i].RX_UE_INFORMATION_TAG;
            pdus[pdu_count].RNTI = rnti;

            unsigned char calculated_crc = calculate_checksum(pdus[pdu_count].RX_UE_INFORMATION_TAG);
