    _Atomic int used;  // Indicates if this slot is currently in use
} NFAPI_CRC_INDICATION_PDU_T;

// Global pool size and mask for atomic operations
#define POOL_SIZE 1024

static unsigned int rnti_pool[POOL_SIZE];
static pthread_mutex_t recycle_lock = PTHREAD_MUTEX_INITIALIZER;
static _Atomic int next_rnti_index = 0;
static _Atomic int recycled_count = 0;

void initialize_rnti_pool(unsigned int start_value) {
    for (int i = 0; i < POOL_SIZE; ++i) {
        rnti_pool[i] = start_value + i;
    }
}

unsigned int get_next_unique_rnti() {
    unsigned int index, current_index, next_index;
    do {
        // Atomically fetch the index of the next RNTI to try
        current_index = atomic_fetch_add(&next_rnti_index, 1) % POOL_SIZE;

        for (int i = 0; i < 10; ++i) {  // Try up to 10 different indices
            unsigned int rnti_candidate = rnti_pool[(current_index + i) % POOL_SIZE];

            // Check if the RNTI is not currently used and assign it atomically
            index = atomic_fetch_and_explicit(&rnti_pool[current_index], 0, memory_order_acquire);
            if (index == 0 && __sync_bool_compare_and_swap(&rnti_pool[current_index], 0, rnti_candidate)) {
                return rnti_candidate;
            }
        }

        // If no valid RNTI found in this pass, try recycling
        pthread_mutex_lock(&recycle_lock);
        if (recycled_count > 0) {
            unsigned int recycled_rnti = rnti_pool[atomic_fetch_sub(&recycled_count, 1) % POOL_SIZE];
            return recycled_rnti;
        }
        pthread_mutex_unlock(&recycle_lock);

    } while (1); // Retry indefinitely
}

void recycle_rnti(unsigned int rnti) {
    unsigned int index = rnti - (rnti_pool[0] - 0);
    if (index < POOL_SIZE && atomic_fetch_add_explicit(&rnti_pool[index], 1, memory_order_release) == 0) {
        pthread_mutex_lock(&recycle_lock);
        rnti_pool[atomic_fetch_add(&recycled_count, 1) % POOL_SIZE] = rnti;
        pthread_mutex_unlock(&recycle_lock);
    }
}

void populate_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *list, size_t N) {
    srand(time(NULL)); // Seed random number generator for CRCFLAG

    if (!list || N == 0) return;

    for (size_t i = 0; i < N; ++i) {
        unsigned int rnti_value = get_next_unique_rnti();

        list[i].rx_ue_info = /* Initialize with actual values */;
        list[i].rnti = rnti_value;
        list[i].crc_ind_rel8_tag = (CRC_INDICATION_REL8_TAG){.crcflag = rand() % 2}; // Randomly set CRCFLAG

        if (i > 0) {
            while (list[i - 1].rnti == list[i].rnti) {
                recycle_rnti(list[i].rnti);  // Recycle the current RNTI and fetch a new one
                rnti_value = get_next_unique_rnti();
                list[i].rnti = rnti_value;
            }
        }

        // Mark this slot as used by setting the atomic flag
        atomic_store(&list[i].used, 1);
    }
}

void free_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *list, size_t N) {
    if (!list || N == 0) return;

    for (size_t i = 0; i < N; ++i) {
        // Recycle the RNTI value
        recycle_rnti(list[i].rnti);
        atomic_store(&list[i].used, 0); // Mark as unused
    }
}
