typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
int list_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// External RNTI source simulation
#define EXTERNAL_RNTI_SOURCE_AVAILABLE

#ifdef EXTERNAL_RNTI_SOURCE_AVAILABLE
#include <stdbool.h>
bool is_rnti_available(int rnti) {
    // Simulate external check with a delay
    struct timespec req = {0, 10000000}; // simulate latency of 10ms
    nanosleep(&req, (struct timespec*)NULL);

    // Assume RNTI values between 1 and 500 are available
    return rnti >= 1 && rnti <= 500;
}
#endif

void log_warning(const char* message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

int get_random_rnti() {
    // Random RNTI generation between 0 and 1023
    return rand() % 1024;
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    memset(&pdu, 0, sizeof(pdu));

    pdu.ue_info_tag.valid = 1; // Set valid
    pdu.crc_indication_rel8_tag.RNTI = rnti;
    pdu.timestamp_info.CRCFLAG = rand() % 2; // Random CRCFLAG
    pdu.timestamp_info.timestamp = time(NULL); // Current timestamp

    return pdu;
}

void add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&mutex);

    // Remove oldest element if list exceeds max size
    if (list_size >= MAX_LIST_SIZE) {
        Node* temp = head;
        head = head->next;
        free(temp);
        --list_size;
    }

    // Add the new node to the end of the list
    if (!head) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    ++list_size;

    pthread_mutex_unlock(&mutex);
}

void manage_nfa_list() {
    int rnti, attempts = 0;
    NFAPI_CRC_INDICATION_PDU_T pdu;

    srand(time(NULL)); // Seed random number generator

    while (1) {
        pthread_mutex_lock(&mutex);

        if (list_size > 0 && head->next == NULL) {
            tail = head; // Reset tail to allow proper removal
        }

        int previous_rnti = list_size > 0 ? head->data.crc_indication_rel8_tag.RNTI : -1;

        while (attempts < 10) {
            rnti = get_random_rnti();

#ifdef EXTERNAL_RNTI_SOURCE_AVAILABLE
            if (!is_rnti_available(rnti)) continue;
#endif

            if (rnti != previous_rnti) break;

            attempts++;
        }

        if (attempts == 10) {
            log_warning("No valid RNTI found after 10 attempts, using default.");
            rnti = 0; // Use a default RNTI
        }

        pdu = create_pdu(rnti);
        add_pdu_to_list(&pdu);

        pthread_mutex_unlock(&mutex);

        // Simulate periodic addition (e.g., every second)
        sleep(1); 
    }
}

int main() {
    manage_nfa_list();
    return 0;
}
