['Below is the implementation of a C function that manages TCP connections as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define MAX_CONNECTIONS 500

typedef enum {
    CONNECTION_IDLE,
    CONNECTION_ESTABLISHED,
    CONNECTION_CLOSED,
    CONNECTION_ERROR
} CONNECTION_STATUS;

typedef struct {
    int client_id;
    int server_port;
    CONNECTION_STATUS connection_status;
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T connections[MAX_CONNECTIONS];
    pthread_mutex_t lock;
    int verbosity_level; // 0: Minimal, 1: Summary, 2: Detailed
} ConnectionManager;

ConnectionManager manager;

void log_message(int level, const char *message) {
    if (manager.verbosity_level >= level) {
        printf("%s\n", message);
    }
}

int find_free_slot(ConnectionManager *manager) {
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[i].connection_status == CONNECTION_IDLE ||
            manager->connections[i].connection_status == CONNECTION_CLOSED) {
            return i;
        }
    }
    return -1;
}

int add_connection(ConnectionManager *manager, int client_id, int server_port) {
    pthread_mutex_lock(&manager->lock);

    int index = find_free_slot(manager);
    if (index == -1) {
        log_message(2, "No available slots for new connection.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->connections[index].client_id = client_id;
    manager->connections[index].server_port = server_port;
    manager->connections[index].connection_status = CONNECTION_ESTABLISHED;

    log_message(2, "Connection added successfully.");
    pthread_mutex_unlock(&manager->lock);
    return index;
}

void close_connection(ConnectionManager *manager, int client_id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[i].client_id == client_id &&
            manager->connections[i].connection_status != CONNECTION_IDLE) {
            manager->connections[i].connection_status = CONNECTION_CLOSED;
            log_message(1, "Connection closed.");
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void reconnect(ConnectionManager *manager, int client_id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[i].client_id == client_id &&
            manager->connections[i].connection_status == CONNECTION_ERROR) {
            // Simulate reconnection logic
            manager->connections[i].connection_status = CONNECTION_ESTABLISHED;
            log_message(2, "Reconnected successfully.");
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void handle_error(ConnectionManager *manager, int client_id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[i].client_id == client_id &&
            manager->connections[i].connection_status != CONNECTION_IDLE) {
            manager->connections[i].connection_status = CONNECTION_ERROR;
            log_message(2, "Connection error occurred.");
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void initialize_manager(ConnectionManager *manager) {
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        manager->connections[i].client_id = -1;
        manager->connections[i].server_port = 0;
        manager->connections[i].connection_status = CONNECTION_IDLE;
    }
    pthread_mutex_init(&manager->lock, NULL);
    manager->verbosity_level = 2; // Default to detailed logging
}

void destroy_manager(ConnectionManager *manager) {
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    initialize_manager(&manager);

    int client_id = 12345;
    int server_port = 8080;

    add_connection(&manager, client_id, server_port);
    handle_error(&manager, client_id);
    reconnect(&manager, client_id);
    close_connection(&manager, client_id);

    destroy_manager(&manager);
    return 0;
}
```

### Key Points:
- **Thread Safety:** Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Memory Management:** Efficiently manages a fixed-size array of connections.
- **Error Handling:** Provides mechanisms for handling connection errors and reconnections.
- **Logging:** Supports adjustable verbosity levels for logging messages.
- **Initialization and Cleanup:** Properly initializes and destroys the `ConnectionManager`.']

['Below is a C code implementation for the described DNS query resolution task. This code uses `resolv.h` and related libraries for handling DNS queries.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import time.h
#include <arpa/nameser.h>
#include <netdb.h>
#include <sys/time.h>

#define MAX_DNS_REQUESTS_PER_SECOND 10
#define TIMEOUT_SECONDS 2

typedef struct {
    char *hostname;
    u_char *ip_addresses;
    size_t ip_count;
} DNSResult;

// Global configurations
char **trusted_domains = NULL; // Dynamic list of trusted domains
size_t trusted_domain_count = 0;
time_t last_request_time[256] = {0}; // For rate limiting

// Function prototypes
int is_trusted_domain(const char *hostname);
void update_trusted_domains(char ***domains, size_t *count, const char **new_domains, size_t new_count);
DNSResult resolve_dns_query(const char *hostname);

// Check if a hostname is in the trusted domains list
int is_trusted_domain(const char *hostname) {
    for (size_t i = 0; i < trusted_domain_count; ++i) {
        if (strcmp(hostname, trusted_domains[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

// Update the list of trusted domains dynamically
void update_trusted_domains(char ***domains, size_t *count, const char **new_domains, size_t new_count) {
    // Free old memory if needed
    for (size_t i = 0; i < (*count); ++i) {
        free((*domains)[i]);
    }
    free(*domains);

    // Allocate new memory and copy domains
    *domains = malloc(new_count * sizeof(char *));
    for (size_t i = 0; i < new_count; ++i) {
        (*domains)[i] = strdup(new_domains[i]);
    }
    *count = new_count;
}

// Resolve DNS query function
DNSResult resolve_dns_query(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int ret;
    struct timeval timeout = {TIMEOUT_SECONDS, 0};
    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    DNSResult result = {NULL, NULL, 0};

    if (!is_trusted_domain(hostname)) {
        return (DNSResult){NULL, NULL, 0}; // Not trusted domain
    }

    // Rate limiting check
    struct sockaddr_in addr;
    inet_pton(AF_INET, hostname, &addr);
    u_int32_t client_ip = ntohl(addr.sin_addr.s_addr);

    if ((time(NULL) - last_request_time[client_ip]) < 1.0 / MAX_DNS_REQUESTS_PER_SECOND) {
        return (DNSResult){NULL, NULL, 0}; // Rate limit exceeded
    }
    last_request_time[client_ip] = time(NULL);

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((ret = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return (DNSResult){NULL, NULL, 0}; // Error occurred
    }

    size_t ip_count = 0;
    for (p = res; p != NULL; p = p->ai_next) {
        ip_count++;
    }

    result.ip_addresses = malloc(ip_count * sizeof(u_char *));
    result.hostname = strdup(hostname);
    result.ip_count = ip_count;

    size_t index = 0;
    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        result.ip_addresses[index++] = malloc(INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &(ipv4->sin_addr), result.ip_addresses[index - 1], INET_ADDRSTRLEN);
    }

    freeaddrinfo(res);

    // Calculate latency
    clock_gettime(CLOCK_MONOTONIC, &end_time);
    double latency = (end_time.tv_sec - start_time.tv_sec) + 
                     (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

    printf("Query for %s took %.3f seconds.\n", hostname, latency);

    return result;
}

// Example usage
int main() {
    const char *domains[] = {"example.com"};
    update_trusted_domains(&trusted_domains, &trusted_domain_count, domains, 1);

    DNSResult result = resolve_dns_query("example.com");
    if (result.ip_count > 0) {
        printf("Resolved IPs for %s:\n", result.hostname);
        for (size_t i = 0; i < result.ip_count; ++i) {
            printf("%s\n", result.ip_addresses[i]);
            free(result.ip_addresses[i]);
        }
    } else {
        printf("No IP addresses resolved or not a trusted domain.\n");
    }

    free(result.hostname);
    free(result.ip_addresses);

    // Cleanup
    for (size_t i = 0; i < trusted_domain_count; ++i) {
        free(trusted_domains[i]);
    }
    free(trusted_domains);

    return 0;
}
```

### Explanation:

- **DNS Resolution**: Uses `getaddrinfo()` to resolve hostnames into IP addresses.
- **Rate Limiting**: Implemented a basic rate limiter per client based on IP address, allowing only up to 10 requests per second.
- **Trusted Domains**: A dynamic list of trusted domains is maintained and updated via `update_trusted_domains()`.
- **Error Handling**: Gracefully handles errors by checking return values and using appropriate status codes.
- **Concurrency Management**: The code can be extended with threading or asynchronous calls for high concurrency.
- **Logging & Performance Metrics**: Prints query latency to standard output, which could be replaced with a logging system in production.

This implementation provides the basic structure needed for further enhancements like integrating performance metrics collection and more sophisticated error handling.']

