#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MESSAGES 1000

typedef enum {
    RRC_PDU_TYPE_1,
    RRC_PDU_TYPE_2,
    // Add other RRC_PDU types as needed
} RRC_PDU_TYPE;

typedef struct {
    RRC_PDU_TYPE pdu_type;
    char *payload;
    size_t length;
} NFAPI_RRC_MSG_T;

typedef struct {
    NFAPI_RRC_MSG_T *messages;
    size_t count;
    size_t capacity;
    int error_occurred;
} MessagePool;

MessagePool* create_message_pool(size_t initial_capacity) {
    MessagePool *pool = (MessagePool *)malloc(sizeof(MessagePool));
    if (!pool) return NULL;

    pool->messages = (NFAPI_RRC_MSG_T *)calloc(initial_capacity, sizeof(NFAPI_RRC_MSG_T));
    if (!pool->messages) {
        free(pool);
        return NULL;
    }

    pool->count = 0;
    pool->capacity = initial_capacity;
    pool->error_occurred = 0;
    return pool;
}

void resize_message_pool(MessagePool *pool, size_t new_capacity) {
    NFAPI_RRC_MSG_T *new_messages = (NFAPI_RRC_MSG_T *)realloc(pool->messages, new_capacity * sizeof(NFAPI_RRC_MSG_T));
    if (!new_messages) {
        pool->error_occurred = 1;
        return;
    }

    pool->messages = new_messages;
    pool->capacity = new_capacity;
}

void free_message_pool(MessagePool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->messages[i].payload) {
            free(pool->messages[i].payload);
        }
    }

    free(pool->messages);
    free(pool);
}

void log_error(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

int populateRRCMessages(MessagePool *pool, size_t num_messages, int available_memory, double latency_requirement) {
    if (!pool || !num_messages || available_memory <= 0 || latency_requirement <= 0.0) {
        log_error("Invalid parameters");
        return -1;
    }

    // Adjust capacity based on available memory
    size_t max_capacity = available_memory / (sizeof(NFAPI_RRC_MSG_T) + 256); // Assuming maximum payload size of 256 bytes
    if (max_capacity < num_messages) {
        log_error("Insufficient memory for requested messages");
        return -1;
    }

    resize_message_pool(pool, num_messages > pool->capacity ? num_messages : pool->capacity);

    pthread_t threads[MAX_MESSAGES];
    size_t chunk_size = num_messages / MAX_MESSAGES;
    int thread_count = (num_messages + chunk_size - 1) / chunk_size;

    for (int i = 0; i < thread_count && i < MAX_MESSAGES; ++i) {
        size_t start_idx = i * chunk_size;
        size_t end_idx = (i == thread_count - 1) ? num_messages : start_idx + chunk_size;

        if (pthread_create(&threads[i], NULL, [](void *arg) -> void* {
            MessageChunk *chunk = (MessageChunk *)arg;
            for (size_t j = chunk->start; j < chunk->end && !chunk->pool->error_occurred; ++j) {
                // Simulate message type and payload generation
                RRC_PDU_TYPE pdu_type = rand() % 2 ? RRC_PDU_TYPE_1 : RRC_PDU_TYPE_2;
                size_t length = (rand() % 256) + 1; // Random length between 1 and 256

                char *payload = (char *)malloc(length);
                if (!payload) {
                    chunk->pool->error_occurred = 1;
                    log_error("Memory allocation failed for payload");
                    continue;
                }

                memset(payload, rand() % 256, length); // Random content
                pthread_mutex_lock(&chunk->lock);
                chunk->pool->messages[j].pdu_type = pdu_type;
                chunk->pool->messages[j].payload = payload;
                chunk->pool->messages[j].length = length;
                pthread_mutex_unlock(&chunk->lock);
            }

            return NULL;
        }, &(MessageChunk){.start = start_idx, .end = end_idx, .pool = pool, .lock = PTHREAD_MUTEX_INITIALIZER}), 0) != 0) {
            log_error("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < thread_count && i < MAX_MESSAGES; ++i) {
        pthread_join(threads[i], NULL);
    }

    pool->count = num_messages;

    return 0;
}

int main() {
    MessagePool *pool = create_message_pool(100);
    if (!pool) {
        log_error("Failed to create message pool");
        return -1;
    }

    int available_memory = 1024 * 1024; // 1MB
    double latency_requirement = 0.01; // 10ms

    if (populateRRCMessages(pool, 500, available_memory, latency_requirement) != 0) {
        log_error("Failed to populate RRC messages");
        free_message_pool(pool);
        return -1;
    }

    for (size_t i = 0; i < pool->count; ++i) {
        printf("Message %zu: Type=%d, Length=%zu\n", i, pool->messages[i].pdu_type, pool->messages[i].length);
    }

    free_message_pool(pool);
    return 0;
}
