#define MAX_RNTI 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG; // part of CRC_INDICATION_REL8_TAG
} NFAPI_CRC_INDICATION_PDU_T;

// Define atomic variables for RNTI management and error handling
static _Atomic uint16_t current_rnti = 0;
static _Atomic uint32_t rnti_attempts = 0;
static pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to get a random number
uint8_t get_random_crcflag() {
    return rand() & 1; // Randomly returns 0 or 1
}

// Thread-safe function to allocate RNTI, ensuring no consecutive duplicates
int allocate_rnti(uint16_t *rnti) {
    uint16_t temp_rnti = atomic_fetch_add(&current_rnti, 1) % (MAX_RNTI + 1);
    int attempt_count = 0;
    while (temp_rnti == *rnti && attempt_count < 10) {
        temp_rnti = atomic_fetch_add(&current_rnti, 1) % (MAX_RNTI + 1);
        attempt_count++;
    }

    if (attempt_count >= 10) {
        // Fallback mechanism: recycle an RNTI
        pthread_mutex_lock(&rnti_mutex);
        temp_rnti = atomic_fetch_add(&current_rnti, 1) % (MAX_RNTI + 1); 
        pthread_mutex_unlock(&rnti_mutex);
    }

    *rnti = temp_rnti;
    return temp_rnti != 0xFFFF; // Return false if RNTI is invalid
}

// Function to initialize the list with N structures
void populate_nfa_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t N) {
    srand(time(NULL)); // Seed for random CRC flag generation

    for (size_t i = 0; i < N; ++i) {
        uint16_t rnti;
        if (!allocate_rnti(&rnti)) {
            fprintf(stderr, "Failed to allocate valid RNTI at index %zu\n", i);
            continue; // Skip this iteration if no valid RNTI is found
        }

        pdu_list[i].RX_UE_INFORMATION_TAG = rand() & 0xFFFF;
        pdu_list[i].RNTI = rnti;
        pdu_list[i].CRCFLAG = get_random_crcflag();
    }
}

// Logging function for performance metrics and bottlenecks
void log_performance(size_t N, double time_taken) {
    printf("Processed %zu structures in %.2f seconds\n", N, time_taken);
}

int main() {
    size_t N = 100000;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    clock_t start_time = clock();
    populate_nfa_indication_pdu_list(pdu_list, N);
    double time_taken = (double)(clock() - start_time) / CLOCKS_PER_SEC;

    log_performance(N, time_taken);

    free(pdu_list);
    return 0;
}
```

### Key Points:
- **Atomic Operations:** Used atomic operations for `current_rnti` to ensure thread-safe increments and avoid contention.
- **Mutex Lock:** Added a fallback mechanism with a mutex lock to recycle RNTI when stuck due to consecutive duplicates.
- **Randomness and Uniqueness:** Ensures no two consecutive structures have the same RNTI, maintaining uniqueness across calls.
- **Performance Logging:** Logs performance metrics for analysis.
- **Memory Management:** Dynamically allocates memory based on `N` while ensuring efficient deallocation.']

