// Function to generate a unique random integer within a given range
int generate_unique_random(int min, int max, int *used_set) {
    int num, is_unique;
    do {
        is_unique = 1;
        num = rand() % (max - min + 1) + min;
        for (int i = 0; i < max; ++i) {
            if (used_set[i] == num) {
                is_unique = 0;
                break;
            }
        }
    } while (!is_unique);
    return num;
}

// Function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_nfaapi_crc_list(size_t count, size_t *generated_count) {
