    NFAPI_CRC_INDICATION_PDU_T *list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int *used_rntis = calloc(1000000, sizeof(int));  // Adjust size as needed for unique RNTIs
    if (!used_rntis) {
        free(list);
        fprintf(stderr, "Memory allocation failed for used_rntis\n");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        list[i].RX_UE_INFORMATION_TAG = generate_unique_random(1, 1000000, NULL); // Unique tag
        list[i].RNTI = generate_unique_random(1, 1000000, used_rntis);
        used_rntis[list[i].RNTI - 1] = 1;  // Mark as used

        // Set CRC_INDICATION_REL8_TAG with a random CRCFLAG (assuming it's a byte value)
        list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
