// Function to add or update a UE context by IMEI
void addOrUpdate_UEContext(UEContextManager *manager, const char *imei, int qos_parameters, int status_flag) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (strcmp(manager->contexts[i].imei, imei) == 0 || manager->contexts[i].status_flag == 0) {
            strncpy(manager->contexts[i].imei, imei, sizeof(manager->contexts[i].imei));
            manager->contexts[i].qos_parameters = qos_parameters;
            manager->contexts[i].status_flag = status_flag;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // If no space is available
    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a UE context by IMEI
UEContext* get_UEContext(UEContextManager *manager, const char *imei) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (strcmp(manager->contexts[i].imei, imei) == 0) {
            UEContext *context = &manager->contexts[i];
            pthread_mutex_unlock(&manager->lock);
            return context;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

