#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG; // Assume it is an integer for simplicity
    unsigned long RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure to hold the dynamic array and its metadata
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread-safe access
} DynamicArray;

// Function declarations
DynamicArray* create_dynamic_array(size_t initial_capacity);
void free_dynamic_array(DynamicArray *dynamic_array);
int add_entry(DynamicArray *dynamic_array, int RX_UE_INFORMATION_TAG, unsigned long RNTI);
NFAPI_CRC_INDICATION_PDU_T* get_entry_by_RNTI(const DynamicArray *dynamic_array, unsigned long RNTI);
int update_CRCFLAG_by_RNTI(DynamicArray *dynamic_array, unsigned long RNTI, int new_CRCFLAG);

// Function implementations

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *dynamic_array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!dynamic_array) return NULL;

    dynamic_array->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_array->array) {
        free(dynamic_array);
        return NULL;
    }

    dynamic_array->size = 0;
    dynamic_array->capacity = initial_capacity;
    pthread_mutex_init(&dynamic_array->lock, NULL);
    return dynamic_array;
}

void free_dynamic_array(DynamicArray *dynamic_array) {
    if (dynamic_array) {
        pthread_mutex_destroy(&dynamic_array->lock);
        free(dynamic_array->array);
        free(dynamic_array);
    }
}

int add_entry(DynamicArray *dynamic_array, int RX_UE_INFORMATION_TAG, unsigned long RNTI) {
    pthread_mutex_lock(&dynamic_array->lock);

    if (dynamic_array->size == dynamic_array->capacity) {
        size_t new_capacity = dynamic_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(dynamic_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&dynamic_array->lock);
            return -1;
        }
        dynamic_array->array = new_array;
        dynamic_array->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &dynamic_array->array[dynamic_array->size++];
    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->RNTI = RNTI;
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&dynamic_array->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_RNTI(const DynamicArray *dynamic_array, unsigned long RNTI) {
    pthread_mutex_lock((pthread_mutex_t*)&dynamic_array->lock);

    for (size_t i = 0; i < dynamic_array->size; ++i) {
        if (dynamic_array->array[i].RNTI == RNTI) {
            pthread_mutex_unlock((pthread_mutex_t*)&dynamic_array->lock);
            return &dynamic_array->array[i];
        }
    }

    pthread_mutex_unlock((pthread_mutex_t*)&dynamic_array->lock);
    return NULL;
}

int update_CRCFLAG_by_RNTI(DynamicArray *dynamic_array, unsigned long RNTI, int new_CRCFLAG) {
    pthread_mutex_lock(&dynamic_array->lock);

    for (size_t i = 0; i < dynamic_array->size; ++i) {
        if (dynamic_array->array[i].RNTI == RNTI) {
            dynamic_array->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = new_CRCFLAG;
            pthread_mutex_unlock(&dynamic_array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&dynamic_array->lock);
    return -1; // Entry not found
}

// Example usage of the functions

int main() {
    DynamicArray *dynamic_array = create_dynamic_array(10);

    if (!dynamic_array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return 1;
    }

    add_entry(dynamic_array, 1, 1001);
    add_entry(dynamic_array, 2, 1002);

    NFAPI_CRC_INDICATION_PDU_T *entry = get_entry_by_RNTI(dynamic_array, 1001);
    if (entry) {
        printf("Entry found with RNTI: %lu, CRCFLAG: %d\n", entry->RNTI, entry->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    update_CRCFLAG_by_RNTI(dynamic_array, 1001, 1);

    entry = get_entry_by_RNTI(dynamic_array, 1001);
    if (entry) {
        printf("Updated CRCFLAG for RNTI: %lu, new CRCFLAG: %d\n", entry->RNTI, entry->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    free_dynamic_array(dynamic_array);

    return 0;
}
```

