} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ueInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcTag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
} NFAPICRCIndicationList;

// Function to create a new node
NFAPI_CRC_INDICATION_PDU_T* createNode(RX_UE_INFORMATION_TAG ueInfoTag, RNTI rnti, CRC_INDICATION_REL8_TAG crcTag) {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }
    newNode->ueInfoTag = ueInfoTag;
    newNode->rnti = rnti;
    newNode->crcTag = crcTag;
    newNode->next = NULL;
    return newNode;
}

// Function to add a node if RNTI is within range
int addNode(NFAPICRCIndicationList* list, RX_UE_INFORMATION_TAG ueInfoTag, RNTI rnti, CRC_INDICATION_REL8_TAG crcTag, RNTI minRNTI, RNTI maxRNTI) {
    if (rnti < minRNTI || rnti > maxRNTI) return 0;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* newNode = createNode(ueInfoTag, rnti, crcTag);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to set CRC flag based on conditions
void setCRCFlag(NFAPI_CRC_INDICATION_PDU_T* node, int ueState, float signalStrength) {
    if (ueState == 1 && signalStrength > -70.0) { // Example condition
        node->crcTag.crcFlag = 1;
    } else {
        node->crcTag.crcFlag = 0;
    }
}

// Function to filter and modify list based on RNTI range
void filterAndSetCRC(NFAPICRCIndicationList* list, RNTI minRNTI, RNTI maxRNTI, int ueState, float signalStrength) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T** curr = &list->head;
    while (*curr) {
        if ((*curr)->rnti >= minRNTI && (*curr)->rnti <= maxRNTI) {
            setCRCFlag(*curr, ueState, signalStrength);
        } else {
            NFAPI_CRC_INDICATION_PDU_T* toDelete = *curr;
            *curr = (*curr)->next;
            free(toDelete);
        }
        curr = &(*curr)->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to clear the list safely
void clearList(NFAPICRCIndicationList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

// Function to initialize the list
void initList(NFAPICRCIndicationList* list) {
    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        perror("Failed to initialize mutex");
        exit(EXIT_FAILURE);
    }
}

// Function to destroy the list and its lock
void destroyList(NFAPICRCIndicationList* list) {
    clearList(list);
    pthread_mutex_destroy(&list->lock);
}
