int resizeList(NFAPICRCList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_data) return 0;
    list->data = new_data;
    list->capacity = new_capacity;
    return 1;
}

int addNFAPI_CRC_INDICATION_PDU(NFAPICRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == pdu.rnti) {
            printf("Error: Duplicate RNTI found\n");
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity > 0 ? list->capacity * 2 : 4;
        if (!resizeList(list, new_capacity)) {
            printf("Error: Memory allocation failed\n");
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    memcpy(&list->data[list->size], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

    printf("Added structure. Total count: %zu\n", list->size);

    pthread_mutex_unlock(&list->lock);
    return 1;
}

void freeNFAPICRCList(NFAPICRCList *list) {
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_destroy(&list->lock);
