CRCIndicationList* create_list();
void destroy_list(CRCIndicationList* list);
int add_to_list(CRCIndicationList* list, uint32_t rnti, int start_range, int end_range, uint8_t (*crc_flag_func)(uint32_t));
uint8_t default_crc_flag_logic(uint32_t rnti);

// Create a new list
CRCIndicationList* create_list() {
    CRCIndicationList* list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for list.\n");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the list and free resources
void destroy_list(CRCIndicationList* list) {
    if (list) {
        ListNode* current = list->head;
        while (current) {
            ListNode* next = current->next;
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Add a new entry to the list
int add_to_list(CRCIndicationList* list, uint32_t rnti, int start_range, int end_range, uint8_t (*crc_flag_func)(uint32_t)) {
    if (!list || !crc_flag_func) return -1;

    pthread_mutex_lock(&list->lock);

    if (rnti < start_range || rnti > end_range) {
        fprintf(stderr, "RNTI %u is out of range [%d, %d].\n", rnti, start_range, end_range);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for list node.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data.rnti = rnti;
    new_node->data.crc_flag = crc_flag_func(rnti);
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

