import threading
from concurrent.futures import ThreadPoolExecutor
import signal_framework  # Assume this is an external framework

#define MAX_CAPACITY 10000

typedef struct {
    int rnti;
    int crcflag;
    // other fields as necessary
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    threading.Lock lock;  // For thread safety
    int lower_rnti_bound;
    int upper_rnti_bound;
} CRCList;

void init_crc_list(CRCList *list, int lower_bound, int upper_bound) {
    list->data = malloc(MAX_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = MAX_CAPACITY;
    list->count = 0;
    list->lock = (threading.Lock){};
    list->lower_rnti_bound = lower_bound;
    list->upper_rnti_bound = upper_bound;
}

int is_valid_rnti(int rnti, CRCList *list) {
    return rnti >= list->lower_rnti_bound && rnti <= list->upper_rnti_bound;
}

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Dummy condition for setting CRCFLAG
    pdu->crcflag = (pdu->rnti % 2 == 0);  // Example logic: even RNTI sets crcflag to true
}

NFAPI_CRC_INDICATION_PDU_T* fetch_ue_info(int rnti) {
    // Assume this interacts with the external signaling framework
    return signal_framework.fetch(rnti);
}

void update_crc_list(CRCList *list, int rnti) {
    if (!is_valid_rnti(rnti, list)) {
        fprintf(stderr, "Invalid RNTI: %d\n", rnti);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = fetch_ue_info(rnti);

    // Set CRCFLAG based on UE's state and received signal strength
    set_crcflag(pdu);

    list->lock.acquire();
    if (list->count < list->capacity) {
        list->data[list->count++] = *pdu;
    } else {
        fprintf(stderr, "List capacity reached\n");
    }
    list->lock.release();
}

void clear_crc_list(CRCList *list) {
    list->lock.acquire();
    free(list->data);
    list->capacity = 0;
    list->count = 0;
    list->lock.release();
}

void process_updates_concurrently(CRCList *list, int *rnti_array, size_t num_rntis) {
    ThreadPoolExecutor executor(10); // Adjust the number of threads as needed

    for (size_t i = 0; i < num_rntis; ++i) {
        executor.submit(update_crc_list, list, rnti_array[i]);
    }

    executor.shutdown(wait=True);
}

int main() {
    CRCList crc_list;
    int lower_bound = 1000, upper_bound = 2000;

    init_crc_list(&crc_list, lower_bound, upper_bound);

    // Simulated RNTI values
    int rnti_values[] = {1500, 1600, 1700, 1800, 1901};

    process_updates_concurrently(&crc_list, rnti_values, sizeof(rnti_values) / sizeof(int));

    clear_crc_list(&crc_list);

    return 0;
}
