    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Global variables
Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
int used_rntis[1024] = {0}; // Assuming RNTI values are 10-bit

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_warning(const char* message) {
    fprintf(stdout, "Warning: %s\n", message);
}

int get_random_rnti() {
    int rnti;
    srand((unsigned int)time(NULL));
    for (int i = 0; i < 10; ++i) {
        rnti = rand() & 0x3FF; // Assuming RNTI is 10-bit
        if (!used_rntis[rnti]) {
            return rnti;
        }
    }
    log_warning("No valid RNTI available after 10 iterations, using default.");
    return DEFAULT_RNTI;
}

void update_rnti_availability(int rnti, int add) {
    // Simulate external data source interaction
    if (add) {
        used_rntis[rnti] = 1;
    } else {
        used_rntis[rnti] = 0;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int rnti, int crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_error("Memory allocation failed for CRC indication PDU.");
        return NULL;
    }
    pdu->RNTI = rnti;
    pdu->CRCFLAG = crc_flag;
    pdu->timestamp = time(NULL);
    return pdu;
}

void add_crc_indication_pdu() {
    pthread_mutex_lock(&list_mutex);

    if (head == NULL) {
        head = tail = (Node*)malloc(sizeof(Node));
        if (!head) {
            log_error("Memory allocation failed for list node.");
            pthread_mutex_unlock(&list_mutex);
            return;
        }
    }

    int rnti = get_random_rnti();
    while (tail->data.RNTI == rnti) { // Ensure no consecutive RNTIs are the same
        rnti = get_random_rnti();
    }

    update_rnti_availability(rnti, 1);

    NFAPI_CRC_INDICATION_PDU_T* pdu = create_crc_indication_pdu(rnti, rand() % 2);
    if (!pdu) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        free(pdu);
        log_error("Memory allocation failed for list node.");
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    new_node->data = *pdu;

    if (tail) {
        tail->next = new_node;
    }
    tail = new_node;
    if (!head->next) {
        head = new_node;
    }

    if (tail != NULL && head != NULL) {
        int count = 1;
        Node* current = head->next;
        while (current->next != NULL) {
            count++;
            current = current->next;
        }
        if (count > MAX_STRUCTURES) {
            Node* oldest = head;
            head = head->next;
            free(oldest);
            update_rnti_availability(oldest->data.RNTI, 0);
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

void cleanup_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        update_rnti_availability(current->data.RNTI, 0);
        free(current);
        current = next;
    }
    head = tail = NULL;

    pthread_mutex_unlock(&list_mutex);
}

int main() {
    // Example usage
    for (int i = 0; i < 120; ++i) { // Test with more than MAX_STRUCTURES
        add_crc_indication_pdu();
    }

    cleanup_list();
    return 0;
}
