```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_PDCP_SN 1023
#define RETRY_THRESHOLD 3

typedef struct {
    uint16_t PDCP_SN;
    uint16_t PDCH_RX_SN;
    uint16_t PDCH_TX_SN;
} MAC_CONTEXT;

typedef enum {
    SUCCESS = 0,
    MEMORY_ALLOCATION_FAILURE,
    INVALID_SEQUENCE_NUMBER,
    INITIALIZATION_FAILURE
} ErrorCode;

typedef struct Node {
    MAC_CONTEXT context;
    struct Node* next;
} Node;

Node* head = NULL;

bool isValidSequenceNumber(uint16_t sn) {
    return (sn > 0 && sn <= MAX_PDCP_SN);
}

void logMessage(const char *message) {
    printf("%s\n", message); // Replace with a more robust logging system if needed
}

int createContext(ErrorCode* errorCode, uint16_t PDCP_SN, uint16_t PDCH_RX_SN, uint16_t PDCH_TX_SN) {
    int contextCount = 0;
    int retries;

    for (retries = 0; retries < RETRY_THRESHOLD; ++retries) {
        if (!isValidSequenceNumber(PDCP_SN)) {
            *errorCode = INVALID_SEQUENCE_NUMBER;
            logMessage("Failed: Invalid PDCP_SN");
            return contextCount;
        }

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            *errorCode = MEMORY_ALLOCATION_FAILURE;
            logMessage("Memory allocation failed for MAC_CONTEXT");
            continue; // Retry on memory failure
        }

        newNode->context.PDCP_SN = PDCP_SN;
        newNode->context.PDCH_RX_SN = PDCH_RX_SN;
        newNode->context.PDCH_TX_SN = PDCH_TX_SN;

        if (PDCH_RX_SN == 0 || PDCH_TX_SN == 0) {
            *errorCode = INITIALIZATION_FAILURE;
            free(newNode);
            logMessage("Failed: PDCH_RX_SN or PDCH_TX_SN not initialized");
            continue; // Retry on initialization failure
        }

        newNode->next = head;
        head = newNode;

        contextCount++;
        *errorCode = SUCCESS;
        logMessage("Context created successfully");

        break; // Exit the loop if successful
    }

    if (retries == RETRY_THRESHOLD && *errorCode != SUCCESS) {
        logMessage("Failed: Maximum retry attempts reached");
    }

    return contextCount;
}

void freeContexts() {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
}

int main() {
    ErrorCode errorCode;
    int createdCount;

    createdCount = createContext(&errorCode, 100, 200, 300);
    printf("Created contexts: %d\n", createdCount);

    createdCount = createContext(&errorCode, 1500, 200, 300); // Invalid PDCP_SN
    printf("Created contexts after invalid attempt: %d\n", createdCount);

    freeContexts();

    return 0;
}
```

### Key Points:
- **Memory Management**: The code dynamically allocates memory for each `MAC_CONTEXT` and ensures that memory is freed when no longer needed.
- **Error Handling**: It sets appropriate error codes and retries operations on failure, with a configurable retry threshold.
- **Logging**: Basic logging is implemented to trace context creation attempts and outcomes.
- **Validation**: Validates sequence numbers before using them.
- **Scalability**: Uses a linked list for managing contexts, which is simple but may not be optimal for very high-frequency lookups. Consider switching to a hash table if performance becomes an issue.

This implementation should serve as a solid foundation, and you can further optimize it based on specific application requirements and constraints.']

