    unsigned char iv[AES_IV_SIZE];
} AES_CipherContext;

// Function to initialize AES cipher context using PBKDF2
int init_aes_cipher_context(const char *password, const unsigned char *salt,
                            int salt_len, int iterations, AES_CipherContext *ctx) {
    if (strlen(password) < 8) {
        fprintf(stderr, "Password too short\n");
        return -1;
    }

    if (!ctx || !password || !salt || salt_len != sizeof(ctx->iv)) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len,
                          iterations, EVP_sha256(), AES_KEY_SIZE + AES_IV_SIZE,
                          ctx->key) != 1 || RAND_bytes(ctx->iv, sizeof(ctx->iv)) != 1) {
        fprintf(stderr, "Failed to derive key or generate IV\n");
        return -1;
    }

    return 0; // Success
}

// Cleanup function for releasing resources
void cleanup_aes_cipher_context(AES_CipherContext *ctx) {
    if (ctx) {
        OPENSSL_cleanse(ctx->key, AES_KEY_SIZE);
        OPENSSL_cleanse(ctx->iv, AES_IV_SIZE);
    }
}

