typedef struct {
    int sequence_number;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_size;
    char *payload;
} NetworkPacket;

const char valid_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
const char* ip_ranges[] = {"192.168.", "10.", "172."};
size_t ip_range_count = sizeof(ip_ranges) / sizeof(ip_ranges[0]);

void free_packets(NetworkPacket *packets, size_t packet_count) {
    if (packets == NULL) return;
    for (size_t i = 0; i < packet_count; ++i) {
        free(packets[i].payload);
    }
    free(packets);
}

NetworkPacket* create_network_packets(size_t num_packets, size_t min_payload_size, size_t max_payload_size) {
    if (num_packets == 0 || min_payload_size > max_payload_size) return NULL;

    NetworkPacket *packets = (NetworkPacket*)malloc(num_packets * sizeof(NetworkPacket));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed for packets\n");
        return NULL;
    }

    srand((unsigned int)time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < num_packets; ++i) {
        NetworkPacket *packet = &packets[i];

        packet->sequence_number = (int)(i + 1);

        const char* ip_range = ip_ranges[rand() % ip_range_count];
        snprintf(packet->source_ip, sizeof(packet->source_ip), "%s%d.%d.%d", ip_range,
                 rand() % 256, rand() % 256, rand() % 256);
        snprintf(packet->destination_ip, sizeof(packet->destination_ip), "%s%d.%d.%d", ip_range,
                 rand() % 256, rand() % 256, rand() % 256);

        size_t payload_size = (rand() % (max_payload_size - min_payload_size + 1)) + min_payload_size;
        packet->payload_size = payload_size;

        packet->payload = (char*)malloc(payload_size);
        if (!packet->payload) {
            fprintf(stderr, "Memory allocation failed for packet payload\n");
            free_packets(packets, i);  // Clean up already allocated packets
            return NULL;
        }

        for (size_t j = 0; j < payload_size; ++j) {
            packet->payload[j] = valid_chars[rand() % (sizeof(valid_chars) - 1)];
        }
    }

    return packets;
}

int main() {
    size_t num_packets = 10;
    size_t min_payload_size = 5;
    size_t max_payload_size = 15;

    NetworkPacket *packets = create_network_packets(num_packets, min_payload_size, max_payload_size);
    if (packets == NULL) {
        fprintf(stderr, "Failed to create network packets\n");
        return EXIT_FAILURE;
    }

    // Use the packets...

    free_packets(packets, num_packets);

    return EXIT_SUCCESS;
}
