public class CRCUtility {

    private static final int MAX_STRUCTURES = 10000;
    private ExecutorService executor = Executors.newSingleThreadExecutor();
    private ScheduledExecutorService configUpdater = Executors.newScheduledThreadPool(1);
    private ScheduledExecutorService serviceManager = Executors.newScheduledThreadPool(2);

    // Messaging interface assumed to be implemented elsewhere
    private MessagingService messagingService;

    public CRCUtility(MessagingService messagingService) {
        this.messagingService = messagingService;
    }

