     * Start the service with a random delay.
     */
    public void start() {
        int delay = (int)(Math.random() * 5000); // Random delay between 0-5 seconds
        Runnable startTask = () -> initializeStructures();
        serviceManager.schedule(startTask, delay, TimeUnit.MILLISECONDS);
    }

    /**
     * Stop the service and send a stop message to the messaging system.
     */
    public void stop() {
        serviceManager.shutdownNow();
        messagingService.sendMessage("CRCUtility stopped.");

        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow(); // Force shutdown
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        configUpdater.shutdown();
    }

