            if (size > MAX_STRUCTURES) size = MAX_STRUCTURES;

            NFAPI_CRC_INDICATION_PDU_T[] pdus = new NFAPI_CRC_INDICATION_PDU_T[size];
            for (int i = 0; i < size; i++) {
                try {
                    pdus[i] = new NFAPI_CRC_INDICATION_PDU_T();
                } catch (Exception e) {
                    // Log and handle allocation failure
                    System.err.println("Failed to initialize PDU at index " + i);
                }
            }

            // Further initialization logic, error handling, etc.
        });
    }

    /**
