     */
    private void loadConfigAsync() {
        configUpdater.scheduleAtFixedRate(this::updateConfig, 0, 10, TimeUnit.SECONDS);

        Runnable initialLoad = () -> updateConfig();
        serviceManager.submit(initialLoad);
    }

    /**
     * Update the PDU size based on configuration file.
     */
    private int getMaxPduCountFromConfig() {
        ObjectMapper mapper = new ObjectMapper(new YAMLFactory());
        try {
            Config config = mapper.readValue(new File("config.yaml"), Config.class);
            return config.getPduCount();
        } catch (IOException e) {
