```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 1000

typedef struct {
    char *interface1;
    char *interface2; // Example network interfaces, expand as needed.
} NetworkInterfaces;

typedef struct {
    int settingA;
    float settingB; // Configuration settings can be expanded here.
} ConfigStructure;

typedef struct SessionContext {
    unsigned long sessionID;
    NetworkInterfaces netInterfaces;
    ConfigStructure config;
    struct SessionContext *next;
} SessionContext;

typedef struct {
    SessionContext *sessions;
    pthread_mutex_t lock;
} SessionManager;

SessionManager manager;

void init_manager() {
    manager.sessions = NULL;
    pthread_mutex_init(&manager.lock, NULL);
}

unsigned long generate_unique_id() {
    static unsigned long next_id = 1;
    return __sync_fetch_and_add(&next_id, 1); // Ensure atomic operation.
}

int add_session(NetworkInterfaces *interfaces, ConfigStructure *config) {
    pthread_mutex_lock(&manager.lock);

    SessionContext *newSession = (SessionContext *)malloc(sizeof(SessionContext));
    if (!newSession) {
        fprintf(stderr, "Failed to allocate memory for new session.\n");
        pthread_mutex_unlock(&manager.lock);
        return -1;
    }

    newSession->sessionID = generate_unique_id();
    memcpy(&newSession->netInterfaces, interfaces, sizeof(NetworkInterfaces));
    memcpy(&newSession->config, config, sizeof(ConfigStructure));

    // Add to the linked list
    newSession->next = manager.sessions;
    manager.sessions = newSession;

    pthread_mutex_unlock(&manager.lock);
    log_session_change("ADD", newSession->sessionID); // External logging integration.

    return 0;
}

int remove_session(unsigned long sessionID) {
    pthread_mutex_lock(&manager.lock);

    SessionContext **current = &manager.sessions;
    while (*current) {
        if ((*current)->sessionID == sessionID) {
            SessionContext *to_remove = *current;
            *current = to_remove->next;

            free(to_remove);
            log_session_change("REMOVE", sessionID); // External logging integration.
            pthread_mutex_unlock(&manager.lock);
            return 0;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&manager.lock);
    fprintf(stderr, "Session ID %lu not found.\n", sessionID);
    return -1;
}

int update_session_config(unsigned long sessionID, ConfigStructure *newConfig) {
    pthread_mutex_lock(&manager.lock);

    SessionContext *current = manager.sessions;
    while (current) {
        if (current->sessionID == sessionID) {
            memcpy(&current->config, newConfig, sizeof(ConfigStructure));
            log_session_change("UPDATE", sessionID); // External logging integration.
            pthread_mutex_unlock(&manager.lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager.lock);
    fprintf(stderr, "Session ID %lu not found.\n", sessionID);
    return -1;
}

void log_session_change(const char *action, unsigned long sessionID) {
    // This function should integrate with an external logging service.
    printf("Log: Session %lu %s\n", sessionID, action); // Placeholder for actual logging.
}

void cleanup_manager() {
    pthread_mutex_lock(&manager.lock);

    while (manager.sessions) {
        SessionContext *to_free = manager.sessions;
        manager.sessions = to_free->next;
        free(to_free);
    }

    pthread_mutex_unlock(&manager.lock);
    pthread_mutex_destroy(&manager.lock);
}
```

This code provides a basic implementation for managing session contexts in a high-availability environment. It includes thread safety, dynamic updates to configuration structures, and integration points for logging actions. The design allows scalability and efficient handling of concurrent access while providing robust error management.']

