#define CACHE_SIZE 128
typedef struct {
    int tags[CACHE_SIZE];
    int valid[CACHE_SIZE];  // To track which cache slots are valid
    pthread_mutex_t mutex;  // For thread safety
} TagCache;

// External logging function prototypes (assuming they are defined elsewhere)
void log_creation(const char* type, const void* item);
void log_destruction(const char* type, const void* item);

int create_nfa_pi_crc_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t n, size_t memory_limit,
                           int max_threads, TagCache *tag_cache) {
    pthread_mutex_init(&tag_cache->mutex, NULL);

    size_t total_memory = 0;
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) return -1; // Memory allocation failed

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &(*list)[i];

        pthread_mutex_lock(&tag_cache->mutex);
        int found_in_cache = 0;
        for (int j = 0; j < CACHE_SIZE && !found_in_cache; ++j) {
            if (tag_cache->valid[j]) {
                pdu->RX_UE_INFORMATION_TAG = tag_cache->tags[j];
                found_in_cache = 1;
            }
        }

        if (!found_in_cache) {
            pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Random valid RX_UE_INFORMATION_TAG
            for (int j = 0; j < CACHE_SIZE; ++j) {
                if (!tag_cache->valid[j]) {
                    tag_cache->tags[j] = pdu->RX_UE_INFORMATION_TAG;
                    tag_cache->valid[j] = 1;
                    break;
                }
            }
        }
        pthread_mutex_unlock(&tag_cache->mutex);

        pdu->RNTI = rand() % 1000; // Random valid RNTI
        pdu->crc_indication.CRCFLAG = rand() % 2; // Random CRC flag

        total_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        log_creation("NFAPI_CRC_INDICATION_PDU_T", pdu);

        if (total_memory >= memory_limit) {
            fprintf(stderr, "Memory limit exceeded.\n");
            break;
        }
    }

    // Dynamically add PHY_LAYER_EVENT_TAG structures
    for (size_t i = 0; i < n && total_memory < memory_limit; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &(*list)[i];

        size_t event_mem_usage = sizeof(PHY_LAYER_EVENT_TAG);
        if ((total_memory + event_mem_usage) > memory_limit) break;

        pdu->phy_layer_events = (PHY_LAYER_EVENT_TAG*)malloc(sizeof(PHY_LAYER_EVENT_TAG));
        if (!pdu->phy_layer_events) continue;  // Handle allocation failure gracefully

        pdu->num_phy_events = 1;

        total_memory += event_mem_usage;

        log_creation("PHY_LAYER_EVENT_TAG", pdu->phy_layer_events);
    }

    return (total_memory < memory_limit) ? n : -2; // Return number of populated entries or error
}

void destroy_nfa_pi_crc_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t n) {
    if (!list) return;

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];

        if (pdu->phy_layer_events) {
            log_destruction("PHY_LAYER_EVENT_TAG", pdu->phy_layer_events);
            free(pdu->phy_layer_events);
        }

        log_destruction("NFAPI_CRC_INDICATION_PDU_T", pdu);
    }

    free(list);
}
