#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PDU_COUNT 1000
#define MAX_POOL_SIZE 5000
#define MAX_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for pool management
NFAPI_CRC_INDICATION_PDU_T *pool[MAX_POOL_SIZE];
size_t active_count = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the pool
int initialize_pool(size_t initial_size) {
    pthread_mutex_lock(&pool_mutex);
    if (initial_size > MAX_POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return -1; // Error: Initial size exceeds maximum pool size
    }

    for (size_t i = 0; i < initial_size; ++i) {
        pool[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pool[i]) {
            // Cleanup in case of failure
            while (--i >= 0) free(pool[i]);
            pthread_mutex_unlock(&pool_mutex);
            return -1; // Error: Memory allocation failed
        }
    }

    active_count = initial_size;
    pthread_mutex_unlock(&pool_mutex);
    return 0; // Success
}

// Function to dynamically resize the pool
int resize_pool(size_t new_size) {
    pthread_mutex_lock(&pool_mutex);

    if (new_size > MAX_POOL_SIZE || new_size <= active_count) {
        pthread_mutex_unlock(&pool_mutex);
        return -1; // Error: Invalid size or no need to resize
    }

    for (size_t i = active_count; i < new_size; ++i) {
        pool[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pool[i]) {
            // Cleanup in case of failure
            while (--i >= active_count) free(pool[i]);
            pthread_mutex_unlock(&pool_mutex);
            return -1; // Error: Memory allocation failed
        }
    }

    active_count = new_size;
    pthread_mutex_unlock(&pool_mutex);
    return 0; // Success
}

// Function to populate a structure with random data
void populate_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand(); // Simulating some valid tag
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1
}

// Function to manage the pool of structures
void *manage_pool(void *arg) {
    size_t requested_size = *(size_t *)arg;

    if (initialize_pool(requested_size) != 0) {
        printf("Failed to initialize pool.\n");
        return NULL;
    }

    // Simulate dynamic resizing based on external updates
    while (1) {
        sleep(5); // Simulate waiting for an update

        size_t new_size = rand() % MAX_POOL_SIZE + 1; // Random new size for simulation
        if (resize_pool(new_size) != 0) {
            printf("Failed to resize pool.\n");
            continue;
        }

        pthread_mutex_lock(&pool_mutex);
        for (size_t i = active_count - new_size; i < active_count; ++i) {
            populate_structure(pool[i]);
        }
        pthread_mutex_unlock(&pool_mutex);

        // Monitor usage statistics
        printf("Pool Usage: Active Count = %zu, Total Memory Used = %zu bytes\n",
               active_count,
               active_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return NULL;
}

// Cleanup function to free allocated memory
void cleanup_pool() {
    pthread_mutex_lock(&pool_mutex);
    for (size_t i = 0; i < active_count; ++i) {
        if (pool[i]) free(pool[i]);
    }
    pthread_mutex_unlock(&pool_mutex);
}

int main() {
    size_t initial_size = 100;
    pthread_t threads[MAX_THREADS];

    // Start pool management threads
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, manage_pool, &initial_size)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Join threads (for demonstration purposes, in real use case they might run indefinitely)
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_pool();
    return 0;
}
```

This code provides a basic implementation of managing a pool of `NFAPI_CRC_INDICATION_PDU_T` structures with thread-safe mechanisms, dynamic resizing, and memory management. Adjustments may be needed for specific use cases or performance optimizations.']

