#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG informationTag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t count;
} NFALIST;

// Helper function to initialize list
NFALIST* createList(size_t initialCapacity) {
    NFALIST* list = (NFALIST*)malloc(sizeof(NFALIST));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = initialCapacity;
    list->count = 0;
    return list;
}

// Helper function to add a new element
int addElement(NFALIST* list, unsigned int rnti, unsigned int informationTag) {
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp = realloc(list->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) return -1;

        memset(temp + list->count, 0, (newCapacity - list->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->elements = temp;
        list->capacity = newCapacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[list->count++];
    element->informationTag = informationTag;
    element->rnti = rnti;

    srand((unsigned int)time(NULL) + list->count);
    element->crcIndication.CRCFLAG = rand() % 2;

    return 0;
}

// Helper function to retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T* getElement(NFALIST* list, size_t index) {
    if (index >= list->count) return NULL;
    return &list->elements[index];
}

// Function to free all allocated memory
void freeList(NFALIST* list) {
    if (list) {
        free(list->elements);
        free(list);
    }
}

// Test cases
int main() {
    NFALIST* nfaList = createList(2);

    addElement(nfaList, 1, 100);
    addElement(nfaList, 2, 200);

    NFAPI_CRC_INDICATION_PDU_T* element = getElement(nfaList, 0);
    if (element) {
        printf("RNTI: %u, Information Tag: %u, CRCFLAG: %u\n",
               element->rnti, element->informationTag, element->crcIndication.CRCFLAG);
    }

    // Simulate adding more elements
    for (size_t i = 2; i < 10; ++i) {
        addElement(nfaList, i, i * 100);
    }

    // Check size after additions
    printf("Total Elements: %zu\n", nfaList->count);

    freeList(nfaList);
    return 0;
}
