```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/types.h>
#include <errno.h>

#define MAX_HOSTNAMES 10
#define DNS_TIMEOUT 5

typedef struct {
    uint16_t rnti;
    char rx_ue_information_tag[64];
    uint8_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    struct in_addr ip_address;
    int resolved; // Flag to indicate if the IP address is resolved
    pthread_mutex_t lock;
} HostInfo;

// Global variables for DNS resolution
pthread_mutex_t dns_lock = PTHREAD_MUTEX_INITIALIZER;
HostInfo host_info[MAX_HOSTNAMES];

void* resolve_dns(void *arg) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET_ADDRSTRLEN];
    HostInfo *h = (HostInfo *)arg;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(h->hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        pthread_exit((void *)1);
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (inet_ntop(p->ai_family, &(((struct sockaddr_in*)p->ai_addr)->sin_addr), ipstr, sizeof(ipstr))) {
            pthread_mutex_lock(&h->lock);
            inet_aton(ipstr, &h->ip_address);
            h->resolved = 1;
            pthread_mutex_unlock(&h->lock);
            break;
        }
    }

    freeaddrinfo(res);
    pthread_exit((void *)0);
}

int construct_nfa_crc_pdu_list(size_t ue_count, const char *hostnames[], size_t host_count) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    int i, j, rc;

    if (ue_count == 0 || host_count > MAX_HOSTNAMES) return -1;

    pdu_list = malloc(ue_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) return -2; // Memory allocation failure

    for (i = 0; i < ue_count; ++i) {
        pdu_list[i].rnti = rand() % 65535;
        snprintf(pdu_list[i].rx_ue_information_tag, sizeof(pdu_list[i].rx_ue_information_tag), "RX_TAG_%zu", i);
        pdu_list[i].crc_flag = rand() % 2; // Randomly set CRC flag
    }

    for (j = 0; j < host_count; ++j) {
        strncpy(host_info[j].hostname, hostnames[j], sizeof(host_info[j].hostname));
        host_info[j].resolved = 0;
        pthread_mutex_init(&host_info[j].lock, NULL);

        pthread_t thread_id;
        rc = pthread_create(&thread_id, NULL, resolve_dns, &host_info[j]);
        if (rc) {
            fprintf(stderr, "Error creating thread: %d\n", rc);
            return -3; // Thread creation failure
        }

        void *res;
        rc = pthread_timedjoin_np(thread_id, &res, DNS_TIMEOUT * 1000000); // Timeout in microseconds
        if (rc != 0 && rc != ETIMEDOUT) {
            fprintf(stderr, "Error joining thread: %d\n", rc);
            return -4; // Thread join failure
        }

        if (rc == ETIMEDOUT) {
            pthread_mutex_lock(&host_info[j].lock);
            host_info[j].resolved = 0;
            pthread_mutex_unlock(&host_info[j].lock);
            fprintf(stderr, "DNS resolution timed out for %s\n", hostnames[j]);
        }
    }

    // Clean up
    for (i = 0; i < ue_count; ++i) {
        free(pdu_list[i].rx_ue_information_tag);
    }
    free(pdu_list);

    for (j = 0; j < host_count; ++j) {
        pthread_mutex_destroy(&host_info[j].lock);
    }

    return 0;
}
```

### Key Points:
- **Dynamic Memory Management**: The function dynamically allocates memory for `NFAPI_CRC_INDICATION_PDU_T` structures and ensures proper cleanup.
- **Asynchronous DNS Resolution**: Uses POSIX threads to perform asynchronous DNS lookups with a timeout mechanism.
- **Thread Safety**: Protects shared data using mutexes.
- **Error Handling**: Returns specific error codes for different failure scenarios.
- **Modular Design**: The function is designed to be easily integrated into larger systems.']

