static size_t allocation_errors = 0;

// Mutex for thread safety in logging
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to resolve DNS and return IP address as u_char array.
int resolve_dns(const char* hostname, u_char ip_address[4]) {
    struct hostent *host;
    struct in_addr **addr_list;

    if ((host = gethostbyname(hostname)) == NULL) {
        pthread_mutex_lock(&log_mutex);
        fprintf(stderr, "DNS resolution error for %s\n", hostname);
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    addr_list = (struct in_addr **) host->h_addr_list;

    if (addr_list[0] != NULL) {
        memcpy(ip_address, *addr_list, 4); // Copy the first IP address
        return 0;
    }

    pthread_mutex_lock(&log_mutex);
    fprintf(stderr, "No addresses found for %s\n", hostname);
    pthread_mutex_unlock(&log_mutex);

    return -1;
}

// Function to initialize and populate array with NFAPI_CRC_INDICATION_PDU_T structures.
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t count) {
    if (count == 0) return NULL;

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_lock(&log_mutex);
        fprintf(stderr, "Memory allocation error\n");
        pthread_mutex_unlock(&log_mutex);
        ++allocation_errors;
        return NULL;
    }

    // Populate each entry
    srand(time(NULL));  // Seed for random number generation
    for (size_t i = 0; i < count; ++i) {
        array[i].ueInfoTag = rand() % UINT32_MAX;
        array[i].rnti = rand() % UINT16_MAX;
        array[i].crcIndicationRel8.CRCFLAG = rand() % 2; // Random CRCFLAG
    }

    // Update successful allocations count
    pthread_mutex_lock(&log_mutex);
    successful_allocations += count;
    pthread_mutex_unlock(&log_mutex);

    return array;
}

// Function to free the allocated memory.
void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

// Example usage and testing
int main() {
    size_t num_entries = 10000; // Number of entries required
    NFAPI_CRC_INDICATION_PDU_T *crc_pdu_array = allocate_crc_pdu_array(num_entries);

    if (!crc_pdu_array) {
        fprintf(stderr, "Failed to allocate CRC PDU array\n");
        return EXIT_FAILURE;
    }

    u_char ip_address[4];
