               ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
    } else {
        fprintf(stderr, "Failed to resolve DNS for example.com\n");
    }

    free_crc_pdu_array(crc_pdu_array);

    return EXIT_SUCCESS;
}
