    if (strcmp(dns_cache.entries[index].hostname, hostname) != 0 || 
        time(NULL) - dns_cache.entries[index].last_updated > 3600) { // Cache expiry
        pthread_rwlock_unlock(&dns_cache.lock);
        struct addrinfo hints, *res;
        memset(&hints, 0, sizeof hints);
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;

        if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
            // Fallback to backup DNS server logic here
            return -1;
        }

        addr_list = (struct in_addr **) res->ai_addr;
        dns_cache.entries[index].ip_address = inet_addr(inet_ntoa(*addr_list[0]));
        strncpy(dns_cache.entries[index].hostname, hostname, sizeof(dns_cache.entries[index].hostname) - 1);
        dns_cache.entries[index].last_updated = time(NULL);

        freeaddrinfo(res);
    }

    pthread_rwlock_unlock(&dns_cache.lock);
    return 0;
}

void *dns_resolution_thread(void *arg) {
    char *hostnames[] = {"example.com", "testsite.org"};
    int num_hosts = sizeof(hostnames) / sizeof(hostnames[0]);

    for (int i = 0; i < num_hosts; ++i) {
