    // Allocate more space if needed
    if (ue_manager.active_UEs >= ue_manager.pdus ? sizeof(NFAPI_CRC_INDICATION_PDU_T) : 0) {
        ue_manager.pdus = realloc(ue_manager.pdus, 
                                  (ue_manager.active_UEs + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
