}

void periodic_cleanup() {
    while (1) {
        sleep(60);  // Cleanup interval
        pthread_rwlock_wrlock(&dns_cache.lock);

        time_t now = time(NULL);
        for (int i = 0; i < MAX_HOSTNAMES; ++i) {
            if (dns_cache.entries[i].ip_address && now - dns_cache.entries[i].last_updated > 7200) { // Invalidate old entries
                dns_cache.entries[i].ip_address = 0;
                memset(dns_cache.entries[i].hostname, 0, sizeof(dns_cache.entries[i].hostname));
            }
        }

        pthread_rwlock_unlock(&dns_cache.lock);
    }
}

int main() {
    initialize_dns_cache();

    pthread_t dns_thread, cleanup_thread;

    pthread_create(&dns_thread, NULL, dns_resolution_thread, NULL);
    pthread_create(&cleanup_thread, NULL, periodic_cleanup, NULL);

    // Simulate UE activity
