    pthread_mutex_init(&da->lock, NULL);
}

void freeDynamicArray(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

static void resizeIfNeeded(DynamicArray *da) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_array) {
            da->array = new_array;
            da->capacity = new_capacity;
        } else {
