    da->array[da->size].RNTI = rnti;
    da->array[da->size].crcTag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    da->size++;

    pthread_mutex_unlock(&da->lock);
}

void removeElement(DynamicArray *da, size_t index) {
    if (index >= da->size) return;

    pthread_mutex_lock(&da->lock);

    for (size_t i = index; i < da->size - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }

    da->size--;

    if (da->size > 0 && da->size <= da->capacity / GROWTH_FACTOR) {
        size_t new_capacity = da->capacity / GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_array) {
            da->array = new_array;
            da->capacity = new_capacity;
        }
    }

    pthread_mutex_unlock(&da->lock);
}

void updateElement(DynamicArray *da, size_t index, int rxTag, int rnti) {
    if (index >= da->size) return;

    pthread_mutex_lock(&da->lock);

    da->array[index].RX_UE_INFORMATION_TAG = rxTag;
