LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    // Randomly set the CRCFLAG
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;

    // Insert at the beginning for O(1) insertion
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    return 0; 
}

int delete_from_list(LinkedList* list, int RX_UE_INFORMATION_TAG) {
