    Node *current = list->head, *previous = NULL;

    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        previous = current;
        current = current->next;
    }

    if (!current) return -1; // Not found

    if (!previous) { // Head node
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    list->count--;
    return 0;
}

void print_list(LinkedList* list) {
