#include <forward_list>
#include <mutex>
#include <string>
#include <algorithm>

struct CRC_INDICATION_REL8_TAG {
    bool CRCFLAG;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
};

class NFACRCManager {
private:
    std::forward_list<NFAPI_CRC_INDICATION_PDU_T> crcList;
    mutable std::mutex listMutex;
    size_t activeCRCCount = 0;

public:
    void addElement(const NFAPI_CRC_INDICATION_PDU_T& element) {
        std::lock_guard<std::mutex> lock(listMutex);
        if (element.crcTag.CRCFLAG) {
            ++activeCRCCount;
        }
        crcList.push_front(element);
    }

    void insertAfterString(const std::string& target, const NFAPI_CRC_INDICATION_PDU_T& element) {
        std::lock_guard<std::mutex> lock(listMutex);

        auto it = std::find_if(crcList.begin(), crcList.end(),
                               [&target](const NFAPI_CRC_INDICATION_PDU_T& pdu) {
                                   return pdu.RX_UE_INFORMATION_TAG == target;
                               });

        if (it != crcList.end()) {
            crcList.insert_after(it, element);
            if (element.crcTag.CRCFLAG) {
                ++activeCRCCount;
            }
        }
    }

    void removeElementByIndex(size_t index) {
        std::lock_guard<std::mutex> lock(listMutex);

        auto it = crcList.begin();
        for (size_t i = 0; it != crcList.end() && i < index; ++i, ++it);

        if (it != crcList.end()) {
            if ((*it).crcTag.CRCFLAG) {
                --activeCRCCount;
            }
            crcList.erase_after(it == crcList.begin() ? crcList.before_begin() : std::prev(it));
        }
    }

    void updateElement(size_t index, const NFAPI_CRC_INDICATION_PDU_T& updatedElement) {
        std::lock_guard<std::mutex> lock(listMutex);

        auto it = crcList.begin();
        for (size_t i = 0; it != crcList.end() && i < index; ++i, ++it);

        if (it != crcList.end()) {
            bool wasActive = (*it).crcTag.CRCFLAG;
            *it = updatedElement;

            if (updatedElement.crcTag.CRCFLAG) {
                ++activeCRCCount;
            }
            if (!wasActive && !updatedElement.crcTag.CRCFLAG) {
                --activeCRCCount;
            }
        }
    }

    size_t getActiveCRCCount() const {
        std::lock_guard<std::mutex> lock(listMutex);
        return activeCRCCount;
    }

    // Additional functions for resizing, error handling, and future enhancements
};

int main() {
    NFACRCManager manager;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {"UE1", 1001, {true}};
    manager.addElement(pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {"UE2", 1002, {false}};
    manager.insertAfterString("UE1", pdu2);

    // Example usage
    manager.removeElementByIndex(0);
    manager.updateElement(0, {"UpdatedUE", 2001, {true}});

    return 0;
}
