    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    if (da->array) {
        free(da->array);
        da->array = NULL;
    }
    da->capacity = 0;
    da->size = 0;
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

int add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);

    // Validate the element
    if (element.RX_UE_INFORMATION_TAG < 0 || element.RNTI <= 0) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Invalid data
    }

    // Check for duplicates
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RX_UE_INFORMATION_TAG == element.RX_UE_INFORMATION_TAG &&
            da->array[i].RNTI == element.RNTI) {
            pthread_mutex_unlock(&da->lock);
            return -2; // Duplicate found
        }
    }

    // Resize array if necessary
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -3; // Out of memory
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    // Add the element
    da->array[da->size++] = element;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T *get_element(DynamicArray *da, size_t index) {
    pthread_mutex_lock(&da->lock);

    if (index >= da->size) {
        pthread_mutex_unlock(&da->lock);
        return NULL; // Invalid index
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &da->array[index];
    pthread_mutex_unlock(&da->lock);
    return element;
}

int main() {
    DynamicArray da;
    init_dynamic_array(&da, 10);

    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() % 100000 + 1 };
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0xFF;
        if (add_element(&da, pdu) != 0) {
            fprintf(stderr, "Error adding element\n");
            free_dynamic_array(&da);
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < da.size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = get_element(&da, i);
        if (pdu) {
            printf("Element %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%u\n",
                   i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
    }

    free_dynamic_array(&da);
    return EXIT_SUCCESS;
}
