    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_crc_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, int *count, int N) {
    if (N <= 0 || N > MAX_N) {
        *list = NULL;
        *count = 0;
        return;
    }

    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    int unique_rntis[MAX_N] = {0};
    int unique_count = 0;
    int last_rnti = -1;

    for (int i = 0; i < N; ++i) {
        unsigned int rnti;
        do {
            rnti = rand() % (MAX_RNTI + 1);
        } while (rnti == last_rnti);

        (*list)[i].rx_ue_info.RNTI = rnti;
        (*list)[i].rnti = rnti;

        int found = 0;
        for (int j = 0; j < unique_count; ++j) {
            if (unique_rntis[j] == rnti) {
                found = 1;
                break;
            }
        }

        if (!found) {
            unique_rntis[unique_count++] = rnti;
        }

        (*list)[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;

        last_rnti = rnti;
    }

    *count = unique_count;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int count = 0;
    int N = 100; // Example value

    generate_crc_pdu_list(&list, &count, N);

    printf("Generated %d structures with %d unique RNTIs.\n", N, count);

    free(list);
    return 0;
}
