#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define LOG_FILE "error_log.txt"
#define LOG_ROTATION_SIZE 1024 * 1024 // 1MB

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG; 
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to log errors and handle rotation
void log_error(const char *message) {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) return;
    }

    fseek(log_file, 0, SEEK_END);
    long size = ftell(log_file);
    if (size > LOG_ROTATION_SIZE) {
        fclose(log_file);
        // Rotate log: rename and clear
        char new_log_file[256];
        snprintf(new_log_file, sizeof(new_log_file), "%s.%ld", LOG_FILE, time(NULL));
        rename(LOG_FILE, new_log_file);
        log_file = fopen(LOG_FILE, "w");
    }

    fprintf(log_file, "%s\n", message);
}

// Function to check if RNTI is valid
int is_valid_rnti(uint16_t rnti) {
    FILE *file = fopen("rnti_whitelist.txt", "r");
    if (!file) return 0;

    uint16_t valid_rnti;
    while (fscanf(file, "%hu\n", &valid_rnti) == 1) {
        if (rnti == valid_rnti) {
            fclose(file);
            return 1;
        }
    }

    fclose(file);
    return 0;
}

// Function to allocate and initialize structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(size_t N, uint8_t crc_flag_min, uint8_t crc_flag_max) {
    if (N <= 0 || crc_flag_min > crc_flag_max) {
        log_error("Invalid input parameters for allocation.");
        return NULL;
    }

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * struct_size);
    if (!pdu_list) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Example tag generation
        do {
            pdu_list[i].RNTI = rand() % 65536;
        } while (!is_valid_rnti(pdu_list[i].RNTI));

        pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag_min + (rand() % (crc_flag_max - crc_flag_min + 1));

        // Verify integrity
        if (!(pdu_list[i].RX_UE_INFORMATION_TAG < 65536 &&
              pdu_list[i].RNTI < 65536 &&
              pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG >= crc_flag_min &&
              pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG <= crc_flag_max)) {
            log_error("Memory integrity check failed.");
            free(pdu_list);
            return NULL;
        }
    }

    return pdu_list;
}

// Function to deallocate memory
void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    if (pdu_list) {
        free(pdu_list);
    }
}
