atomic_int pool_index = 0;

void init_memory_pool() {
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        memory_pool[i] = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_from_pool() {
