```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int size;
    int priority;
} PDCP_SDU_T;

typedef struct {
    int eNB_ID;
    PDCP_SDU_T **pdcpsdus;
    int pdcpsdu_count;
    double scheduling_timestamp;
    pthread_mutex_t lock;
} LTE_ENB_TASK_STRUCT;

// Function to initialize an LTE_ENB_TASK_STRUCT
LTE_ENB_TASK_STRUCT* create_enb_task(int eNB_ID) {
    LTE_ENB_TASK_STRUCT *task = (LTE_ENB_TASK_STRUCT*)malloc(sizeof(LTE_ENB_TASK_STRUCT));
    if (!task) return NULL;

    task->eNB_ID = eNB_ID;
    task->pdcpsdus = NULL;
    task->pdcpsdu_count = 0;
    task->scheduling_timestamp = 0.0;

    pthread_mutex_init(&task->lock, NULL);
    return task;
}

// Function to add a PDCP SDU to an LTE_ENB_TASK_STRUCT
void add_pdcpsdu(LTE_ENB_TASK_STRUCT *task, PDCP_SDU_T *pdcpsdu) {
    if (!task || !pdcpsdu) return;

    pthread_mutex_lock(&task->lock);

    // Resize the array of pointers to hold the new SDU
    task->pdcpsdus = (PDCP_SDU_T**)realloc(task->pdcpsdus, (task->pdcpsdu_count + 1) * sizeof(PDCP_SDU_T*));
    if (!task->pdcpsdus) {
        pthread_mutex_unlock(&task->lock);
        return;
    }

    // Insert the new SDU and maintain priority order
    int index = task->pdcpsdu_count;
    for (int i = 0; i < task->pdcpsdu_count; ++i) {
        if (pdcpsdu->priority > task->pdcpsdus[i]->priority) {
            index = i;
            break;
        }
    }

    // Shift elements to the right
    for (int i = task->pdcpsdu_count; i > index; --i) {
        task->pdcpsdus[i] = task->pdcpsdus[i - 1];
    }

    // Insert the new SDU
    task->pdcpsdus[index] = pdcpsdu;
    ++task->pdcpsdu_count;

    // Update scheduling timestamp (simplified for this example)
    task->scheduling_timestamp += 0.01; // Simulate time update

    pthread_mutex_unlock(&task->lock);
}

// Function to free memory allocated for LTE_ENB_TASK_STRUCT
void destroy_enb_task(LTE_ENB_TASK_STRUCT *task) {
    if (!task) return;

    pthread_mutex_lock(&task->lock);

    // Free all PDCP SDUs
    for (int i = 0; i < task->pdcpsdu_count; ++i) {
        free(task->pdcpsdus[i]);
    }
    free(task->pdcpsdus);

    pthread_mutex_unlock(&task->lock);

    pthread_mutex_destroy(&task->lock);
    free(task);
}

// Example of how to handle network status update
void integrate_network_status(LTE_ENB_TASK_STRUCT *task, double network_latency) {
    if (!task) return;

    pthread_mutex_lock(&task->lock);

    // Adjust scheduling timestamp based on latency (simplified example)
    task->scheduling_timestamp += network_latency;

    pthread_mutex_unlock(&task->lock);
}

// Usage example
int main() {
    LTE_ENB_TASK_STRUCT *enb_task = create_enb_task(1);

    PDCP_SDU_T *pdcpsdu1 = (PDCP_SDU_T*)malloc(sizeof(PDCP_SDU_T));
    pdcpsdu1->size = 100;
    pdcpsdu1->priority = 5;

    add_pdcpsdu(enb_task, pdcpsdu1);

    integrate_network_status(enb_task, 0.05);

    destroy_enb_task(enb_task);

    return 0;
}
```

### Key Features:
- **Dynamic Memory Management**: Uses `malloc` and `realloc` to manage memory for PDCP SDUs.
- **Priority Handling**: Inserts PDCP SDUs in order of priority, ensuring efficient retrieval.
- **Concurrency Control**: Utilizes `pthread_mutex_t` for thread-safe operations on shared resources.
- **Real-Time Integration**: Includes a simplified mechanism for adjusting the scheduling timestamp based on network latency.
- **Scalability and Maintenance**: Designed to be easily extended or modified as needed.']

