                       size_t max_total_size, const LTE_RRC_PDU_TAG *new_pdu);
void cleanup_messages(LTE_RRC_CU_MESSAGE **messages, size_t num_messages);

// Function to manage a dynamic array of LTE_RRC_CU_MESSAGE
int add_pdu_to_message(LTE_RRC_CU_MESSAGE **messages, size_t *num_messages, 
                       size_t max_total_size, const LTE_RRC_PDU_TAG *new_pdu) {
    if (!messages || !*messages || !new_pdu) return -1;

    size_t current_size = 0;
    for (size_t i = 0; i < *num_messages; ++i) {
        current_size += sizeof(LTE_RRC_CU_MESSAGE);
        current_size += (*messages)[i].capacity_pdus * sizeof(LTE_RRC_PDU_TAG);
    }

    if ((current_size + sizeof(LTE_RRC_CU_MESSAGE)) > max_total_size) return -1;

    // Find a message to add the PDU or create a new one
    size_t idx = 0;
    for (; idx < *num_messages; ++idx) {
        if ((*messages)[idx].num_pdus < (*messages)[idx].capacity_pdus) break;
    }

    if (idx == *num_messages) { // Need to add a new message
        *messages = realloc(*messages, sizeof(LTE_RRC_CU_MESSAGE) * (*num_messages + 1));
        if (!*messages) return -1;

        LTE_RRC_CU_MESSAGE *new_message = &((*messages)[*num_messages]);
        memset(new_message, 0, sizeof(LTE_RRC_CU_MESSAGE));

        new_message->capacity_pdus = 10; // Initial capacity
        new_message->pdus = malloc(sizeof(LTE_RRC_PDU_TAG) * new_message->capacity_pdus);
        if (!new_message->pdus) return -1;

        (*num_messages)++;
    }

    LTE_RRC_CU_MESSAGE *target_message = &((*messages)[idx]);
    if (target_message->num_pdus == target_message->capacity_pdus) {
        size_t new_capacity = target_message->capacity_pdus * 2;
        target_message->pdus = realloc(target_message->pdus, sizeof(LTE_RRC_PDU_TAG) * new_capacity);
        if (!target_message->pdus) return -1;

        target_message->capacity_pdus = new_capacity;
    }

    memcpy(&target_message->pdus[target_message->num_pdus], new_pdu, sizeof(LTE_RRC_PDU_TAG));
    target_message->num_pdus++;

    printf("Added PDU. Total messages: %zu\n", *num_messages);
    return 0;
}

void cleanup_messages(LTE_RRC_CU_MESSAGE **messages, size_t num_messages) {
    if (!messages || !*messages) return;

    for (size_t i = 0; i < num_messages; ++i) {
        free((*messages)[i].pdus);
    }

    free(*messages);
    *messages = NULL;
}

// Example usage
int main() {
    LTE_RRC_CU_MESSAGE *messages = NULL;
    size_t num_messages = 0;
    size_t max_total_size = 1024; // Example limit

    LTE_RRC_PDU_TAG pdu = { .pdu_id = 1 };
    add_pdu_to_message(&messages, &num_messages, max_total_size, &pdu);

    cleanup_messages(&messages, num_messages);
    return 0;
}
