#include <stdio.h>

#define MIN_PASSWORD_LENGTH 8

typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag[5];
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
int initialize_aes_256_cbc(const char *password, const unsigned char *salt, EVP_CIPHER_CTX **ctx);
void cleanup_cipher(EVP_CIPHER_CTX *ctx);
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(size_t count);

int initialize_aes_256_cbc(const char *password, const unsigned char *salt, EVP_CIPHER_CTX **ctx) {
    if (strlen(password) < MIN_PASSWORD_LENGTH || !ctx) return -1;

    // Derive key and IV
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, EVP_sha256(), 10000, sizeof(key), key);
    RAND_bytes(iv, sizeof(iv));

    *ctx = EVP_CIPHER_CTX_new();
    if (!*ctx) return -1;

    // Initialize cipher context
    if (EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(*ctx);
        return -1;
    }

    return 0;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
