typedef struct MemoryPool {
    size_t element_size;
    void* pool;
    size_t total_elements;
    size_t used_elements;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool* mp, size_t element_size, size_t max_elements) {
    pthread_mutex_init(&mp->lock, NULL);
    mp->element_size = element_size;
    mp->total_elements = max_elements * MAX_LOAD_FACTOR;
    mp->pool = malloc(mp->element_size * mp->total_elements);
    if (!mp->pool) {
        fprintf(stderr, "Memory allocation failed for memory pool\n");
        exit(EXIT_FAILURE);
    }
    memset(mp->pool, 0, mp->element_size * mp->total_elements);
    mp->used_elements = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_elements >= mp->total_elements) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* element = 
        (NFAPI_CRC_INDICATION_PDU_T*)((char*)mp->pool + mp->used_elements * mp->element_size);
    mp->used_elements++;
    pthread_mutex_unlock(&mp->lock);
    return element;
}

void initialize_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t N, MemoryPool* mp, uint16_t seed) {
