#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include "nfa_api_crc_indication_pdu_t.pb-c.h"  // Include generated header from protocol buffer compiler

#define MAX_STRUCTURES 15000

typedef struct {
    uint16_t rnti;
    // other fields as required
} RNTI_POOL;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;  // Mutex for thread-safe access to shared resources
} NFAPI_LIST;

static RNTI_POOL rnti_pool[] = { /* Populate with preloaded pool of identifiers */ };
static size_t rnti_pool_size = sizeof(rnti_pool) / sizeof(RNTI_POOL);

// Utility function to check if an RNTI is unique in the list
int is_unique_rnti(NFAPI_LIST *list, uint16_t rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == rnti) {
            return 0;
        }
    }
    return 1;
}

// Function to allocate and initialize NFAPI_LIST
NFAPI_LIST* create_nfa_list(size_t initial_capacity) {
    NFAPI_LIST *list = malloc(sizeof(NFAPI_LIST));
    if (!list) return NULL;

    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

// Function to add an NFAPI_CRC_INDICATION_PDU_T structure to the list
int add_structure(NFAPI_LIST *list) {
    if (pthread_mutex_lock(&list->mutex)) return -1;

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity < MAX_STRUCTURES ? list->capacity * 2 : MAX_STRUCTURES;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    int assigned_rnti = 0;
    for (size_t i = 0; i < rnti_pool_size && !assigned_rnti; ++i) {
        if (is_unique_rnti(list, rnti_pool[i].rnti)) {
            NFAPI_CRC_INDICATION_PDU_T *new_entry = &list->data[list->size];
            new_entry->rnti = rnti_pool[i].rnti;
            // Initialize other fields as required
            ++list->size;

            assigned_rnti = 1;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return assigned_rnti ? 0 : -1;
}

// Function to serialize the list into a binary format
int serialize_nfa_list(NFAPI_LIST *list, uint8_t **output, size_t *output_size) {
    if (pthread_mutex_lock(&list->mutex)) return -1;

    nfa_api_crc_indication_pdu_t__vector *vec = nfa_api_crc_indication_pdu_t__create();
    for (size_t i = 0; i < list->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &list->data[i];
        nfa_api_crc_indication_pdu_t *item = nfa_api_crc_indication_pdu_t__create();
        item->rnti = entry->rnti;
        // Set other fields as required
        nfa_api_crc_indication_pdu_t__vector_add(vec, item);
    }

    *output_size = nfa_api_crc_indication_pdu_t__get_packed_size(vec);
    *output = malloc(*output_size);
    if (!*output) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    nfa_api_crc_indication_pdu_t__pack(vec, *output);

    // Free vector and mutex
    for (size_t i = 0; i < vec->size; ++i) {
        nfa_api_crc_indication_pdu_t__free_unpacked(vec->data[i], NULL);
    }
    free(vec->data);
    free(vec);
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

