    for (size_t i = 0; i < list->size; ++i) {
        nfa_api_crc_indication_pdu_t__free_unpacked(list->data[i], NULL);
    }
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);

    return 0;
}
