#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

#define MAX_LOAD_FACTOR 10

typedef struct {
    unsigned int TX_POWER_LEVEL;
} RX_UE_INFORMATION_TAG;

typedef unsigned long RNTI;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UnionFindNode {
    int parent;
    int rank;
} UnionFindNode;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned long hashRNTI(RNTI rnti, unsigned long seed) {
    unsigned long hash = 5381;
    while (rnti != 0) {
        hash = ((hash << 5) + hash) + (rnti & 0xFF);
        rnti >>= 8;
    }
    return hash ^ seed;
}

void* unionFindMakeSet(void* arg) {
    UnionFindNode* node = (UnionFindNode*)arg;
    node->parent = *(int*)(node + 1);
    node->rank = 0;
    return NULL;
}

int find(UnionFindNode* nodes, int i) {
    if (nodes[i].parent != i)
        nodes[i].parent = find(nodes, nodes[i].parent);
    return nodes[i].parent;
}

void unionSet(UnionFindNode* nodes, int x, int y) {
    int rootX = find(nodes, x);
    int rootY = find(nodes, y);

    if (rootX != rootY) {
        if (nodes[rootX].rank > nodes[rootY].rank)
            nodes[rootY].parent = rootX;
        else if (nodes[rootX].rank < nodes[rootY].rank)
            nodes[rootX].parent = rootY;
        else {
            nodes[rootY].parent = rootX;
            nodes[rootX].rank++;
        }
    }
}

void checkDisjointPairs(RNTI* rntis, int numRNTIs) {
    UnionFindNode* ufNodes = malloc(sizeof(UnionFindNode) * numRNTIs);
    if (!ufNodes) {
        fprintf(stderr, "Failed to allocate memory for Union-Find nodes\n");
        return;
    }

    pthread_t threads[numRNTIs];
    int indices[numRNTIs];

    for (int i = 0; i < numRNTIs; ++i) {
        ufNodes[i].parent = i;
        ufNodes[i].rank = 0;

        indices[i] = i;
        if (pthread_create(&threads[i], NULL, unionFindMakeSet, &ufNodes[i]) != 0) {
            fprintf(stderr, "Failed to create thread for Union-Find make set\n");
            free(ufNodes);
            return;
        }
    }

    for (int i = 0; i < numRNTIs; ++i)
        pthread_join(threads[i], NULL);

    clock_t start_time = clock();
    for (int i = 0; i < numRNTIs - 1; ++i) {
        for (int j = i + 1; j < numRNTIs; ++j) {
            int rootI = find(ufNodes, rntis[i]);
            int rootJ = find(ufNodes, rntis[j]);

            if (rootI != rootJ)
                unionSet(ufNodes, rootI, rootJ);
        }
    }
    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Time taken to check disjoint pairs: %f seconds\n", time_taken);

    free(ufNodes);
}

int executeBackgroundCommand(const char* command) {
    pid_t pid = fork();

    if (pid < 0) {
        fprintf(stderr, "Fork failed\n");
        return 0;
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(1); // Exit child process if exec fails
    }

    int status;
    waitpid(pid, &status, 0);

    if (WIFEXITED(status)) {
        return WEXITSTATUS(status) == 0 ? 1 : 0;
    } else {
        fprintf(stderr, "Child process terminated abnormally\n");
        return 0;
    }
}

int generateNfarcrcPduList(int expectedLoad, const char* backgroundCommand) {
    int maxEntries = expectedLoad * MAX_LOAD_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * maxEntries);

    if (!pdus) {
        fprintf(stderr, "Memory allocation failed for PDU list\n");
        return 0;
    }

    srand(time(NULL));
    RNTI rntis[maxEntries];
    unsigned long seed = (unsigned long)time(NULL);

    for (int i = 0; i < maxEntries; ++i) {
        pdus[i].rx_ue_information_tag.TX_POWER_LEVEL = rand() % 100;
        rntis[i] = rand();
        pdus[i].rnti = rntis[i];
        pdus[i].crc_indication_rel8_tag.CRCFLAG = hashRNTI(rntis[i], seed);
    }

    checkDisjointPairs(rntis, maxEntries);

    int commandSuccess = executeBackgroundCommand(backgroundCommand);
    if (!commandSuccess) {
        free(pdus);
        return 0;
    }

    free(pdus);
    return 1;
}

int main() {
    const char* command = "sleep 2";
    int success = generateNfarcrcPduList(100, command);

    if (success)
        printf("Operation successful\n");
    else
        printf("Operation failed\n");

    return success ? 1 : 0;
}
