// Define structures as per your requirements.
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe memory pool structure
typedef struct MemoryPool {
    size_t item_size;
    void *pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t item_size, size_t initial_capacity) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->item_size = item_size;
    mp->capacity = initial_capacity;
    mp->used = 0;
    mp->pool = malloc(item_size * initial_capacity);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* pool_allocate(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used >= mp->capacity) {
        size_t new_capacity = mp->capacity * 2;
        void *new_pool = realloc(mp->pool, mp->item_size * new_capacity);
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL; // Handle allocation failure
        }
        mp->pool = new_pool;
        mp->capacity = new_capacity;
    }

    void *item = (char*)mp->pool + (mp->used * mp->item_size);
    mp->used++;
    pthread_mutex_unlock(&mp->lock);

    return item;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (!mp) return;
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Initialize NFAPI_CRC_INDICATION_PDU_T array
int initialize_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t initial_capacity, unsigned int seed) {
    if (!array) return -1;

    MemoryPool *mp = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), initial_capacity);
    if (!mp) return -2;

    srand(seed); // Set random seed for CRCFLAG generation
    size_t total_capacity = initial_capacity * 10; // Prepare for up to 10x load

    for (size_t i = 0; i < total_capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)pool_allocate(mp);
        if (!pdu) break;

        pdu->RX_UE_INFORMATION_TAG = rand() % 100; // Example tag generation
        pdu->RNTI = rand() % 5000; // Example RNTI generation
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? 1 : 0;

        if (i < initial_capacity) {
            ((NFAPI_CRC_INDICATION_PDU_T**)array)[i] = pdu;
        }
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(total_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (size_t i = 0; i < initial_capacity && ((NFAPI_CRC_INDICATION_PDU_T**)array)[i]; ++i) {
        // Populate the array with the allocated items
        ((NFAPI_CRC_INDICATION_PDU_T**)array)[i] = (NFAPI_CRC_INDICATION_PDU_T*)pool_allocate(mp);
    }

    destroy_memory_pool(mp);

    return 0;
}

// Load resource bundle from file
int load_resource_bundle(const char *file_path, void **bundle, size_t *num_items) {
    if (!file_path || !bundle || !num_items) return -1;

    FILE *file = fopen(file_path, "r");
    if (!file) return -2;

    // Example: read number of items
    fscanf(file, "%zu", num_items);

    *bundle = malloc(*num_items * sizeof(void*));
    if (!*bundle) {
        fclose(file);
        return -3;
    }

    for (size_t i = 0; i < *num_items; ++i) {
        // Example: read and store each item
        void *item = malloc(256); // Assume fixed size items for simplicity
        if (!item) break;

        fread(item, sizeof(char), 256, file);
        ((void**)bundle)[i] = item;
    }

    fclose(file);

    return 0;
}
