#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_THREADS 16

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int validate_input(int n) {
    return (n > 0);
}

void initialize_crcflag(uint8_t *crcFlag, int size) {
    for (int i = 0; i < size; ++i) {
        crcFlag[i] = rand() % 256;
    }
}

int hash_function(uint8_t crcFlag, int size) {
    return crcFlag % size;
}

void resolve_collision(uint8_t *crcFlags, int index, int size) {
    do {
        crcFlags[index] = (crcFlags[index] + 1) % 256;
        index = hash_function(crcFlags[index], size);
    } while ((index >= 0 && index < size && crcFlags[index] != 0));
}

int allocate_crcflags(uint8_t *crcFlags, int size) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < size; ++i) {
        uint8_t crcFlag = rand() % 256;
        int index = hash_function(crcFlag, size);
        if (crcFlags[index] == 0 || crcFlags[index] == crcFlag) {
            crcFlags[index] = crcFlag;
            pthread_mutex_unlock(&mutex);
            return index;
        } else {
            resolve_collision(crcFlags, index, size);
        }
    }

    pthread_mutex_unlock(&mutex);
    return -1; // Indicate failure
}

NFAPI_CRC_INDICATION_PDU_T* manage_crc_indications(int n) {
    if (!validate_input(n)) {
        fprintf(stderr, "Invalid input\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    uint8_t crcFlags[n];
    memset(crcFlags, 0, n);

    initialize_crcflag(crcFlags, n);

    for (int i = 0; i < n; ++i) {
        int resultIndex = allocate_crcflags(crcFlags, n);
        if (resultIndex == -1) {
            fprintf(stderr, "Failed to resolve CRCFLAG\n");
            free(array);
            return NULL;
        }

        array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        array[i].RNTI = rand() % 4096; // Example value
        array[i].crcTag.CRCFLAG = crcFlags[resultIndex];
    }

    return array;
}

void clear_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array, int n) {
    if (array != NULL) {
        free(array);
    }
}

