        pthread_mutex_unlock(&list->lock);
        return -2; // Error: Context list full
    }

    // Check consecutive PLMN ID constraint
    if (list->count > 0 && list->contexts[list->count - 1]->serving_plmn_id == serving_plmn_id) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Error: Consecutive PLMN IDs are identical
    }

