    for (size_t i = 0; i < transitions_count; ++i) {
        context->rrc_state_transitions[i] = rrc_state_transitions[i];
    }

    list->contexts[list->count++] = context;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
