            return -1; // Cannot allocate more structures
        }
        NFAPI_CRC_INDICATION_PDU_T *temp = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Memory allocation failure
        }
        list->data = temp;
        list->capacity = new_capacity;
    }

    int rnti_index = rand() % list->pool_size;
    while (rnti_index < list->pool_size && list->available_rntis[rnti_index] == 0) {
        rnti_index++;
    }
    if (rnti_index >= list->pool_size) {
        pthread_mutex_unlock(&list->lock);
        return -3; // No available RNTI
    }

    pdu->rnti = list->available_rntis[rnti_index];
    list->available_rntis[rnti_index] = 0;
    list->used_rntis++;

