        NFAPI_CRC_INDICATION_PDU_T *last_pdu = &list->data[list->count - 1];
        while (pdu->rnti == last_pdu->rnti) {
            rnti_index = rand() % list->pool_size;
            while (rnti_index < list->pool_size && list->available_rntis[rnti_index] == 0) {
                rnti_index++;
            }
