                return -3; // No available RNTI
            }
            pdu->rnti = list->available_rntis[rnti_index];
            list->available_rntis[rnti_index] = 0;
        }
    }

    list->data[list->count++] = *pdu;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
