#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SIZE 1024
#define MAX_ADD_COUNT 512

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
    unsigned char CRCFLAG; // Assuming a single byte for CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    pthread_t flush_thread;
    int running;
} CRCList;

CRCList list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, 0, 1};

void initialize_crc_list() {
    if (pthread_create(&list.flush_thread, NULL, flush_to_disk, &list) != 0) {
        perror("Failed to create flush thread");
    }
}

int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    memcpy(new_node, &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int update_element(CRCList* list, size_t index, NFAPI_CRC_INDICATION_PDU_T element) {
    if (index >= list->size) {
        return -1; // Index out of bounds
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }

    memcpy(&(current->data), &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_element(CRCList* list, size_t index) {
    if (index >= list->size) {
        return -1; // Index out of bounds
    }

    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    for (size_t i = 0; i < index; ++i) {
        current = &((*current)->next);
    }

    Node* temp = *current;
    *current = (*current)->next;

    free(temp);
    list->size--;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void serialize_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&list->lock);

    fwrite(&(list->size), sizeof(size_t), 1, file);
    Node* current = list->head;

    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void deserialize_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&list->lock);

    list->head = NULL;
    list->size = 0;

    while (fread(&(list->head->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory during deserialization");
            break;
        }

        memcpy(&new_node->data, &list->head->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        new_node->next = list->head;
        list->head = new_node;

        list->size++;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void* flush_to_disk(void* arg) {
    CRCList* list = (CRCList*)arg;

    while (list->running) {
        sleep(60); // Flush every 60 seconds
        serialize_list(list, "crc_list_backup.bin");
    }

    return NULL;
}

void stop_flush_thread(CRCList* list) {
    pthread_cancel(list->flush_thread);
    pthread_join(list->flush_thread, NULL);
    list->running = 0;
}

int main() {
    initialize_crc_list();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1,
                                       .RNTI = 2,
                                       .CRC_INDICATION_REL8_TAG = "example_tag",
                                       .CRCFLAG = rand() % 256 };

    add_element(&list, pdu);
    update_element(&list, 0, pdu);
    remove_element(&list, 0);

    serialize_list(&list, "crc_list_backup.bin");
    deserialize_list(&list, "crc_list_backup.bin");

    stop_flush_thread(&list);

    return 0;
}
