typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_POOL;

// Function to dynamically allocate memory for an array of structures
NFAPI_CRC_POOL* create_crc_pool(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    NFAPI_CRC_POOL *pool = (NFAPI_CRC_POOL *)malloc(sizeof(NFAPI_CRC_POOL));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->array) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->array[i].rx_ue_info.valid = 1; // Assuming valid is set to 1
        pool->array[i].rnti = rand() % UINT16_MAX;
        pool->array[i].crc_ind_rel8_tag.CRCFLAG = rand() & 1; // Randomly set CRCFLAG
    }

    return pool;
}

// Function to free the allocated memory for the pool
void destroy_crc_pool(NFAPI_CRC_POOL *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    free(pool->array);
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Function to resize the pool if needed
int expand_crc_pool(NFAPI_CRC_POOL *pool, size_t additional_capacity) {
    if (!pool || additional_capacity == 0) return -1;

    pthread_mutex_lock(&pool->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool->array,
        (pool->capacity + additional_capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    for (size_t i = pool->capacity; i < pool->capacity + additional_capacity; ++i) {
        new_array[i].rx_ue_info.valid = 1;
        new_array[i].rnti = rand() % UINT16_MAX;
        new_array[i].crc_ind_rel8_tag.CRCFLAG = rand() & 1;
    }

    pool->array = new_array;
    pool->capacity += additional_capacity;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}
