#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>

#define MAX_HOSTNAMES 10
#define TIMEOUT 5 // seconds for DNS resolution timeout

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG; // Assume the flag is an 8-bit value
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    struct in_addr ip_address;
} DNSResult;

typedef enum {
    SUCCESS = 0,
    ERROR_MEMORY_ALLOCATION,
    ERROR_DNS_RESOLUTION,
    ERROR_THREAD_CREATION,
} ErrorCode;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
DNSResult dns_results[MAX_HOSTNAMES];

void *dns_resolve(void *arg) {
    char *hostname = (char *)arg;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return (void *)ERROR_DNS_RESOLUTION;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        if (ipv4 && ipv4->sin_family == AF_INET) {
            pthread_mutex_lock(&mutex);
            strncpy(dns_results[p - res].hostname, hostname, sizeof(dns_results[p - res].hostname));
            dns_results[p - res].ip_address = ipv4->sin_addr;
            pthread_mutex_unlock(&mutex);
        }
    }

    freeaddrinfo(res);

    return NULL;
}

ErrorCode construct_nfa_crc_pdu_list(NFAPI_CRC_INDICATION_PDU_T **pdu_list, size_t ue_count, char *hostnames[], int host_count) {
    if (ue_count == 0 || pdu_list == NULL) {
        return ERROR_MEMORY_ALLOCATION;
    }

    // Allocate memory for UE instances
    *pdu_list = malloc(ue_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_list == NULL) {
        return ERROR_MEMORY_ALLOCATION;
    }

    pthread_t threads[MAX_HOSTNAMES];
    int thread_indices[MAX_HOSTNAMES];

    // Initialize UE PDU list
    for (size_t i = 0; i < ue_count; ++i) {
        (*pdu_list)[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Dummy value
        (*pdu_list)[i].RNTI = rand() % 10000;                 // Dummy value
        (*pdu_list)[i].CRC_INDICATION_REL8_TAG = rand() & 1;  // Random CRCFLAG (0 or 1)
    }

    // Resolve DNS asynchronously for given hostnames
    for (int i = 0; i < host_count && i < MAX_HOSTNAMES; ++i) {
        if (pthread_create(&threads[i], NULL, dns_resolve, strdup(hostnames[i])) != 0) {
            return ERROR_THREAD_CREATION;
        }
        thread_indices[i] = i;
    }

    // Join threads and handle results
    for (int i = 0; i < host_count && i < MAX_HOSTNAMES; ++i) {
        void *result;
        pthread_join(threads[i], &result);
        if ((intptr_t)result == ERROR_DNS_RESOLUTION) {
            fprintf(stderr, "DNS resolution failed for hostname %s\n", hostnames[thread_indices[i]]);
            free(*pdu_list);
            return ERROR_DNS_RESOLUTION;
        }
    }

    // Log results (could be removed or adjusted in production)
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_HOSTNAMES; ++i) {
        if (!inet_ntoa(dns_results[i].ip_address)) {
            continue;
        }
        printf("Resolved %s to %s\n", dns_results[i].hostname, inet_ntoa(dns_results[i].ip_address));
    }
    pthread_mutex_unlock(&mutex);

    return SUCCESS;
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    char *hostnames[] = {"example.com", "google.com"};
    int host_count = 2;

    ErrorCode result = construct_nfa_crc_pdu_list(&pdu_list, 5, hostnames, host_count);
    if (result != SUCCESS) {
        fprintf(stderr, "Failed to create NFAPI CRC PDU list with error code: %d\n", result);
        return EXIT_FAILURE;
    }

    // Do something with pdu_list

    free(pdu_list);

    return EXIT_SUCCESS;
}
```

