    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 65535
#define SUCCESS 0
#define FAILURE -1

// Function to check uniqueness of an RNTI in the array
int is_unique_rnti(uint32_t *rnti_list, uint32_t rnti, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (rnti_list[i] == rnti)
            return 0;
    }
    return 1;
}

// Function to generate a valid RX_UE_INFORMATION_TAG
int generate_rx_ue_information_tag(RX_UE_INFORMATION_TAG *tag, int cell_id) {
    if (!tag || cell_id < 0) return FAILURE;

    tag->UE_ID = external_random_lib_generate(); // Use external library for random generation
    tag->CELL_ID = cell_id;
    return SUCCESS;
}

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_indication_pdu_list(size_t n, int *error) {
    if (!n || !error) {
        *error = FAILURE;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        *error = FAILURE;
        return NULL;
    }

    uint32_t rnti_list[MAX_RNTI];
    size_t unique_count = 0;

    for (size_t i = 0; i < n; ++i) {
        int cell_id = external_random_lib_generate() % 1000; // Example cell ID range
        RX_UE_INFORMATION_TAG rx_ue_information_tag;
        if (generate_rx_ue_information_tag(&rx_ue_information_tag, cell_id) == FAILURE) {
            free(list);
            *error = FAILURE;
            return NULL;
        }

        uint32_t rnti;
        do {
            rnti = external_random_lib_generate() & MAX_RNTI; // Generate a random RNTI
        } while (!is_unique_rnti(rnti_list, rnti, unique_count) || !unique_count < n);

        list[i].rx_ue_information_tag = rx_ue_information_tag;
        list[i].RNTI = rnti;
        list[i].crc_indication_rel8_tag.CRCFLAG = external_random_lib_generate() & 0xFFFF;

        rnti_list[unique_count++] = rnti; // Store unique RNTIs
    }

    *error = SUCCESS;
    return list;
}

// Function to serialize the data for storage or transmission
int serialize_nfa_pi_crc_indication_pdu_list(const NFAPI_CRC_INDICATION_PDU_T *list, size_t n, unsigned char **output, size_t *size) {
    if (!list || !n || !output || !size) return FAILURE;

    *size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *output = malloc(*size);
    if (!*output) return FAILURE;

    memcpy(*output, list, *size);

    return SUCCESS;
}

// Function to deserialize the data
int deserialize_nfa_pi_crc_indication_pdu_list(const unsigned char *input, size_t size, NFAPI_CRC_INDICATION_PDU_T **list, size_t *n) {
    if (!input || !size || !list || !n) return FAILURE;

    *n = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *list = malloc(size);
    if (!*list) return FAILURE;

    memcpy(*list, input, size);

    return SUCCESS;
}

// Thread-safe wrapper for creation
NFAPI_CRC_INDICATION_PDU_T* create_thread_safe_nfa_pi_crc_indication_pdu_list(size_t n, int *error) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T *list = create_nfa_pi_crc_indication_pdu_list(n, error);
    pthread_mutex_unlock(&lock);
    return list;
}
