#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <openssl/rand.h>

// Define the structure as per your requirements
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function to find the largest integer in an array
int findLargestInteger(int *array, size_t length) {
    if (length == 0) return -1;
    int max = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Function to process command line options and perform operations on a string
void processCommandLineOption(int option, const char *string) {
    pthread_mutex_lock(&mutex);

    // Example operation: hash the string using OpenSSL
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, (unsigned char *)string, strlen(string));
    SHA256_Final(digest, &sha256);

    printf("Hashed String: ");
    for(int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", digest[i]);
    }
    printf("\n");

    pthread_mutex_unlock(&mutex);
}

// Function to serialize the structure
size_t serializeNFAPI_CRC_INDICATION_PDU_T(const NFAPI_CRC_INDICATION_PDU_T *pdu, unsigned char **buffer) {
    size_t requiredSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = (unsigned char *)malloc(requiredSize);
    if (*buffer == NULL) {
        perror("Failed to allocate memory for serialization");
        return 0;
    }
    memcpy(*buffer, pdu, requiredSize);
    return requiredSize;
}

// Function to deserialize the structure
NFAPI_CRC_INDICATION_PDU_T *deserializeNFAPI_CRC_INDICATION_PDU_T(const unsigned char *buffer) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        perror("Failed to allocate memory for deserialization");
        return NULL;
    }
    memcpy(pdu, buffer, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return pdu;
}

// Main function to process network events
void *processNetworkEvents(void *arg) {
    int fd = *(int *)arg;
    unsigned char *buffer = NULL;
    size_t bufferSize = 0;
    ssize_t bytesRead;

    while (1) {
        // Read data from file descriptor
        bytesRead = read(fd, &bufferSize, sizeof(size_t));
        if (bytesRead <= 0) break; // Handle error or end of stream

        buffer = realloc(buffer, bufferSize);
        if (buffer == NULL) {
            perror("Failed to allocate memory for incoming data");
            continue;
        }

        bytesRead = read(fd, buffer, bufferSize);
        if (bytesRead != bufferSize) {
            perror("Incomplete read");
            free(buffer);
            continue;
        }

        // Deserialize the structure
        NFAPI_CRC_INDICATION_PDU_T *pdu = deserializeNFAPI_CRC_INDICATION_PDU_T(buffer);
        if (!pdu) continue;

        // Process the PDU (dummy processing)
        printf("Processing PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);

        free(pdu);
    }

    if (buffer) {
        free(buffer);
    }
    return NULL;
}

// Main function to handle command line input and simulate network conditions
int main(int argc, char *argv[]) {
    int option = 0;
    const char *string = "example";

    // Parse command line options
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            option = atoi(argv[++i]);
        }
    }

    // Process the command line option and string operation
    processCommandLineOption(option, string);

    // Read integers from standard input
    int numbers[100];
    size_t count = 0;
    while (scanf("%d", &numbers[count]) == 1 && count < sizeof(numbers) / sizeof(numbers[0])) {
        ++count;
    }

    // Find the largest integer
    int largest = findLargestInteger(numbers, count);
    printf("Largest Integer: %d\n", largest);

    // Simulate network conditions (dummy delay)
    sleep(1);

    // Process network events asynchronously
    pthread_t threadId;
    int fd = 0; // Example file descriptor
    if (pthread_create(&threadId, NULL, processNetworkEvents, &fd) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }
    pthread_join(threadId, NULL);

    return EXIT_SUCCESS;
}
```

### Key Points:

- **Thread Safety**: The code uses `pthread_mutex_t` for protecting shared resources.
- **Serialization/Deserialization**: Functions are provided to serialize and deserialize the `NFAPI_CRC_INDICATION_PDU_T` structure.
- **Command Line Option Processing**: Uses OpenSSL to hash a string based on command line options.
- **Memory Management**: Efficiently manages memory with dynamic allocation and deallocation.
- **Network Simulation**: Simulates network conditions with artificial delays.
- **Asynchronous Processing**: Processes network events in a separate thread.

