```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

#define MAX_RX_TAGS 1000
#define MAX_RNTIs 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

bool is_tag_used(int tag, NFAPI_CRC_INDICATION_PDU_T* pdus, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (pdus[i].RX_UE_INFORMATION_TAG == tag) {
            return true;
        }
    }
    return false;
}

bool is_rnti_used(int rnti, NFAPI_CRC_INDICATION_PDU_T* pdus, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (pdus[i].RNTI == rnti) {
            return true;
        }
    }
    return false;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(size_t N, size_t *allocated_count) {
    pthread_mutex_lock(&lock);

    int available_tags[MAX_RX_TAGS];
    int available_rntis[MAX_RNTIs];

    // Initialize available tags and RNTIs
    for (int i = 0; i < MAX_RX_TAGS; ++i)
        available_tags[i] = i + 1;
    for (int i = 0; i < MAX_RNTIs; ++i)
        available_rntis[i] = i + 10001;

    // Shuffle arrays to randomize selection
    srand(time(NULL));
    for (size_t i = 0; i < MAX_RX_TAGS; ++i) {
        int j = rand() % MAX_RX_TAGS;
        int temp = available_tags[i];
        available_tags[i] = available_tags[j];
        available_tags[j] = temp;
    }

    for (size_t i = 0; i < MAX_RNTIs; ++i) {
        int j = rand() % MAX_RNTIs;
        int temp = available_rntis[i];
        available_rntis[i] = available_rntis[j];
        available_rntis[j] = temp;
    }

    // Allocate the array of PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < N && available_tags[i] && available_rntis[i]; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = available_tags[i];
        pdus[i].RNTI = available_rntis[i];
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;
    }

    *allocated_count = i;

    if (*allocated_count < N) {
        fprintf(stderr, "Insufficient unique RX_UE_INFORMATION_TAGS or RNTIs available\n");
