    public ushort RNTI { get; set; }
    public byte[] CRC_INDICATION_REL8_TAG { get; set; } = new byte[10];
    public byte CRCFLAG { get; set; }
}

public class DatabaseHandler
{
    private static readonly object lockObject = new object();

    public void InsertStructures(List<NFAPI_CRC_INDICATION_PDU_T> structures, SqlConnection connection)
    {
        string query = "INSERT INTO CRCIndications (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG) VALUES (@RX_UE_INFORMATION_TAG, @RNTI, @CRC_INDICATION_REL8_TAG, @CRCFLAG)";

        using (SqlCommand command = new SqlCommand(query, connection))
        {
            command.Parameters.Add("@RX_UE_INFORMATION_TAG", SqlDbType.TinyInt);
            command.Parameters.Add("@RNTI", SqlDbType.SmallInt);
            command.Parameters.Add("@CRC_INDICATION_REL8_TAG", SqlDbType.VarBinary, 10);
            command.Parameters.Add("@CRCFLAG", SqlDbType.TinyInt);

            connection.Open();
            SqlTransaction transaction = connection.BeginTransaction("InsertData");

            try
            {
                lock (lockObject)
                {
                    foreach (var structure in structures)
                    {
                        command.Parameters["@RX_UE_INFORMATION_TAG"].Value = structure.RX_UE_INFORMATION_TAG;
                        command.Parameters["@RNTI"].Value = structure.RNTI;

                        byte[] crcBytes = new byte[10];
                        Array.Copy(structure.CRC_INDICATION_REL8_TAG, crcBytes, 10);
                        command.Parameters["@CRC_INDICATION_REL8_TAG"].Value = crcBytes;

                        command.Parameters["@CRCFLAG"].Value = structure.CRCFLAG;
                        command.Transaction = transaction;
                        command.ExecuteNonQuery();
                    }
                }

                transaction.Commit();
            }
            catch (Exception ex)
            {
                try
                {
                    transaction.Rollback();
                }
                catch (Exception rollbackEx)
                {
                    Console.WriteLine("Rollback Exception: " + rollbackEx.Message);
                }

                Console.WriteLine("Insert Error: " + ex.Message);
                // Implement retry logic here if necessary
            }
            finally
            {
                connection.Close();
            }
        }
    }
}
