    if (!collection->pdus) {
        // Log allocation failure using your existing logging framework
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

// Add a new PDU to the collection safely
int add_pdu_to_collection(PduCollection *collection, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pthread_mutex_lock(&collection->lock)) {
        if (collection->count == collection->capacity) {
            size_t new_capacity = collection->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(collection->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_pdus) {
                // Log reallocation failure using your existing logging framework
                fprintf(stderr, "Memory reallocation failed\n");
                pthread_mutex_unlock(&collection->lock);
