typedef struct SessionList {
    Session *sessions;
    size_t count;
    pthread_rwlock_t rwlock; // Read-write lock for the list
} SessionList;

void handleError(const char* message) {
    perror(message);
    exit(EXIT_FAILURE);
}

SessionList* createSessionList(size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of sessions requested\n");
        return NULL;
    }

    SessionList *list = malloc(sizeof(SessionList));
    if (!list) handleError("Failed to allocate memory for session list");

    list->sessions = malloc(N * sizeof(Session));
    if (!list->sessions) handleError("Failed to allocate memory for sessions");

    list->count = N;

    pthread_rwlock_init(&list->rwlock, NULL);
    for (size_t i = 0; i < N; ++i) {
        list->sessions[i].sessionID = i + 1; // Unique session ID
        list->sessions[i].timestamp = time(NULL); // Current timestamp
        list->sessions[i].status = DISCONNECTED;
        list->sessions[i].priority = rand() % MAX_PRIORITY; // Random priority level
        pthread_mutex_init(&list->sessions[i].lock, NULL);
    }

    return list;
}

void updateSessionStatus(SessionList *list) {
    if (!list) return;

    pthread_rwlock_rdlock(&list->rwlock);

    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_lock(&list->sessions[i].lock);

        // Simulate a network event update
        // Example: toggle status or adjust priority based on conditions

        if (rand() % 2 == 0) {
            list->sessions[i].status = (list->sessions[i].status == CONNECTED) ? DISCONNECTED : CONNECTED;
        }

        pthread_mutex_unlock(&list->sessions[i].lock);
    }

    pthread_rwlock_unlock(&list->rwlock);
}

void clearSessionList(SessionList *list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_destroy(&list->sessions[i].lock); // Destroy session lock
    }

    free(list->sessions); // Free memory allocated for sessions
    pthread_rwlock_destroy(&list->rwlock); // Destroy read-write lock
    free(list); // Free memory allocated for the list structure
}

int main() {
    size_t N = 100; // Example: request 100 session slots

    SessionList *sessionList = createSessionList(N);
    if (!sessionList) return EXIT_FAILURE;

    // Simulate an update cycle
    updateSessionStatus(sessionList);

    // Clear the list when done
    clearSessionList(sessionList);

    return EXIT_SUCCESS;
}
```

### Key Considerations:
1. **Thread Safety**: Each session has its own mutex for concurrent access, and a read-write lock is used on the entire list to allow multiple readers or exclusive writer access.
2. **Error Handling**: Checks are in place for invalid input sizes and memory allocation failures, with error messages handled by `handleError()`.
3. **Efficiency & Extensibility**: The structure allows easy addition of new attributes by modifying the `Session` struct without affecting list management functions.
4. **Memory Management**: Memory is managed through careful allocation and deallocation, with locks destroyed in reverse order of creation to prevent deadlocks.

This implementation ensures thread safety, efficiency, and extensibility suitable for high-load server environments.']

