int populateNFAPIList(NFAPI_CRC_INDICATION_PDU_T **list, size_t max_size);

#define LOG_ALLOC(addr) printf("Allocated memory at address: %p\n", (void *)addr)

int populateNFAPIList(NFAPI_CRC_INDICATION_PDU_T **list, size_t max_size) {
    if (!list || max_size == 0) return -1;

    // Allocate initial list with one element
    *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) return -2;

    LOG_ALLOC(*list);

    NFAPI_CRC_INDICATION_PDU_T *current = *list;
    for (size_t i = 1; i < max_size; ++i) {
        // Allocate next element
        NFAPI_CRC_INDICATION_PDU_T *next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (next == NULL) break;

        LOG_ALLOC(next);

        current->crcData.CRCFLAG = rand() % 2;

        // Link to the next node and move the pointer
        current->next = next;
        current = next;
    }

    return 0; // Success
}

// Function to free the allocated list
void freeNFAPIList(NFAPI_CRC_INDICATION_PDU_T *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        LOG_ALLOC(next); // Log freeing of memory
        current = next;
    }
}

int main() {
