            self.RNTI = rnti
            self.CRC_INDICATION_REL8_TAG = {'CRCFLAG': crc_flag}

    nfa_list = []
    for _ in range(n):
        rx_ue_information_tag = random.randint(1, 1000)
        rnti = random.randint(1, 1000)
        crc_flag = random.choice([True, False])
        nfa_list.append(NFAPI_CRC_INDICATION_PDU_T(rx_ue_information_tag, rnti, crc_flag))

    return nfa_list

# Example usage
