    unsigned char RX_UE_INFORMATION_TAG[8];
    unsigned char CRC_INDICATION_REL8_TAG[4];
    unsigned short CRCFLAG; // Example flag, adjust as necessary
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Cache for reused structures
static NFAPI_CRC_INDICATION_PDU_T* structure_cache = NULL;
static int cache_size = 0;

NFAPI_CRC_INDICATION_PDU_T* create_structures(int M) {
    if (M <= 0) return NULL;

    // Attempt to retrieve from cache first
    NFAPI_CRC_INDICATION_PDU_T* structures = NULL;
    int available_from_cache = cache_size > 0 ? cache_size : 0;

    if (available_from_cache >= M) {
        structures = structure_cache;
        structure_cache = realloc(structure_cache, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (cache_size - M));
        cache_size -= M;
    } else {
        structures = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * M);
        if (!structures && available_from_cache > 0) {
            // Fall back to using cache
            structures = structure_cache;
            structure_cache = NULL;
            cache_size = 0;
            M -= available_from_cache;

            // Try allocating the rest
            NFAPI_CRC_INDICATION_PDU_T* additional_structures = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * M);
            if (!additional_structures) {
                free(structures); // Release cache structures in case of failure
                return NULL;
            }

            // Append additional structures to cached ones
            NFAPI_CRC_INDICATION_PDU_T* new_structures = realloc(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (available_from_cache + M));
            memcpy(new_structures + available_from_cache, additional_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * M);
            free(additional_structures);

            structures = new_structures;
        }
    }

    if (!structures && cache_size == 0) {
        // Final attempt to allocate at least one structure
        structures = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (structures) M = 1; // Only have one now
    }

    if (structures) {
        for (int i = 0; i < M; ++i) {
            // Populate RX_UE_INFORMATION_TAG with random data
            for (int j = 0; j < 8; ++j)
                structures[i].RX_UE_INFORMATION_TAG[j] = rand() % 256;

            // Ensure RNTI is within valid range
            do {
                structures[i].RNTI = rand() % (MAX_RNTI + 1);
            } while (structures[i].RNTI > MAX_RNTI);

            // Populate CRC_INDICATION_REL8_TAG with random data
            for (int j = 0; j < 4; ++j)
                structures[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;

            // Randomly set CRCFLAG
            structures[i].CRCFLAG = rand() & 1; // Example: either 0 or 1

            // Set timestamp
            structures[i].timestamp = time(NULL);
        }
    }

    return structures;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T* structures, int M) {
    if (structures && cache_size == 0) { // Cache is empty; no need to free here
        free(structures);
    } else if (structures) {
        // Add back to cache for reuse
        structure_cache = realloc(structure_cache, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (cache_size + M));
        memcpy(structure_cache + cache_size, structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * M);
        cache_size += M;
    }
}
