    return is_valid_rnti(rnti) ? rnti : -1;
}

void retry_fetch_rnti(int *rnti, int retries) {
    for (int i = 0; i < retries; ++i) {
        if (((*rnti = fetch_rnti_from_external_source()) != -1)) return;
    }
    log_error("Failed to fetch RNTI after multiple attempts");
}

void resize_list_if_needed(DynamicList *list) {
    if (list->count >= list->capacity && list->capacity < MAX_RESIZE_ELEMENTS) {
        size_t new_capacity = list->capacity + 500;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_elements != NULL) {
            list->elements = new_elements;
            list->capacity = new_capacity;
        } else {
            log_error("Failed to resize dynamic list");
        }
    }
}

void add_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);
    resize_list_if_needed(list);
    if (list->count < list->capacity) {
        list->elements[list->count++] = element;
    } else {
        log_error("Reached maximum capacity of dynamic list");
    }
    pthread_mutex_unlock(&list->lock);
}

void initialize_dynamic_list(DynamicList *list) {
    list->elements = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->elements == NULL) {
        log_error("Failed to allocate memory for dynamic list");
        exit(EXIT_FAILURE);
    }
    list->capacity = MAX_ELEMENTS;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void free_dynamic_list(DynamicList *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}

void populate_nfa_indication_pdu_list(DynamicList *list) {
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Assign some value
        pdu.CRC_INDICATION_REL8_TAG = rand(); // Assign some value

        int rnti = -1;
        retry_fetch_rnti(&rnti, RETRY_LIMIT);

        if (is_valid_rnti(rnti)) {
            pdu.RNTI = rnti;
            pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            add_element(list, pdu);
        } else {
            log_error("Invalid RNTI encountered");
        }
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicList list;
    initialize_dynamic_list(&list);

    populate_nfa_indication_pdu_list(&list);

    free_dynamic_list(&list);
    return 0;
}
