typedef enum {
    MSG_TYPE_CONFIGURATION_UPDATE,
    // Add other message types as needed
} RRC_MESSAGE_TYPE;

typedef struct {
    RRC_MESSAGE_TYPE type;
    uint32_t checksum;  // Placeholder for a simple checksum field
