#define MAX_STRUCTURES 1024
#define PROBABILITY_PARAM 0.5 // Default probability to set CRCFLAG to 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_INFO_TAG;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
