    printf("%s\n", message);
}

// Function to validate structure integrity (simple mock validation)
int validate_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return pdu->ue_info.RX_UE_INFORMATION_TAG != 0 && pdu->ue_info.RNTI != 0;
}

// Thread function to create and populate structures
void* create_pdu(void* arg) {
    int id = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu_array[MAX_STRUCTURES];
    srand(time(NULL) + id);

    for (int i = 0; i < MAX_STRUCTURES / 4; ++i) { // Each thread handles a part of the work
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed for PDU %d\n", i + id * (MAX_STRUCTURES / 4));
            continue;
        }

        pdu->ue_info.RX_UE_INFORMATION_TAG = rand() % 1000; // Mock data
        pdu->ue_info.RNTI = rand() % 1000;                  // Mock data

        double random_value = (double)rand() / RAND_MAX;
        pdu->crc_tag.CRCFLAG = random_value < PROBABILITY_PARAM ? 1 : 0;

        if (validate_structure(pdu)) {
            pdu_array[i] = pdu;
            log_creation("Created and validated PDU");
        } else {
            free(pdu);
        }
    }

    pthread_exit(NULL);
}

// Function to serialize the structures into a binary format
void serialize_pus(NFAPI_CRC_INDICATION_PDU_T *pus[], size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    fwrite(pus, sizeof(NFAPI_CRC_INDICATION_PDU_T*), count, file);
    fclose(file);
}

// Main function to manage threads and create PDU structures
void create_pdus(int probability_param) {
    pthread_t threads[4];
    int thread_ids[4] = {0, 1, 2, 3};
    NFAPI_CRC_INDICATION_PDU_T *pus[MAX_STRUCTURES];

    PROBABILITY_PARAM = (float)probability_param / 100.0;

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, create_pdu, &thread_ids[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    serialize_pus(pus, MAX_STRUCTURES, "pdus.bin");
}

int main() {
    create_pdus(50); // Set probability to 50%
    return 0;
}
