#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct MeasurementReport {
    int tag;
} MeasurementReport;

typedef struct LTEUEContextRecord {
    char UEID[16];
    int sequenceNumber;
    MeasurementReport reports[10]; // assuming a fixed number of measurement reports per record
    time_t timestamp; // to track when the record was added
} LTEUEContextRecord;

typedef struct Node {
    LTEUEContextRecord* data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int record_count;
} UEList;

// Function prototypes
void initUEList(UEList* list);
void addUEContextRecord(UEList* list, const char* ueid, MeasurementReport reports[], size_t report_count);
void purgeOutdatedRecords(UEList* list, time_t age_threshold);
int getMeasurementTag(); // Simulate getting a valid measurement tag
void freeUEList(UEList* list);

void initUEList(UEList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->record_count = 0;
}

void addUEContextRecord(UEList* list, const char* ueid, MeasurementReport reports[], size_t report_count) {
    pthread_mutex_lock(&list->lock);

    LTEUEContextRecord* new_record = (LTEUEContextRecord*)malloc(sizeof(LTEUEContextRecord));
    if (!new_record) {
        perror("Failed to allocate memory for new UE context record");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    strncpy(new_record->UEID, ueid, sizeof(new_record->UEID) - 1);
    new_record->UEID[sizeof(new_record->UEID) - 1] = '\0';

    new_record->sequenceNumber = rand(); // Random sequence number
    for (size_t i = 0; i < report_count && i < 10; ++i) {
        new_record->reports[i].tag = reports[i].tag ? reports[i].tag : getMeasurementTag();
    }

    time(&new_record->timestamp);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        free(new_record);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = new_record;
    new_node->next = list->head;
    list->head = new_node;
    list->record_count++;

    pthread_mutex_unlock(&list->lock);
}

void purgeOutdatedRecords(UEList* list, time_t age_threshold) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        time_t current_time;
        time(&current_time);

        if ((current_time - current->data->timestamp) > age_threshold) {
            Node* to_delete = current;

            if (prev == NULL) {
                list->head = current->next; // remove head
            } else {
                prev->next = current->next; // remove non-head node
            }

            free(current->data);
            free(to_delete);

            list->record_count--;
            current = current->next;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void freeUEList(UEList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current->data);
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int getMeasurementTag() {
    // Placeholder for a function that would obtain a valid measurement tag
    return rand() % 100; // Simulate random valid tag generation
}
```

### Explanation of Key Choices:

- **Data Structures**: A linked list is chosen to efficiently handle dynamic insertion and deletion, which is critical when purging outdated records.
- **Thread Safety**: `pthread_mutex_t` ensures that concurrent operations on the list are thread-safe. This approach minimizes locking contention since operations like adding or purging typically complete quickly once a lock is acquired.
- **Performance Considerations**: While a linked list can lead to cache inefficiencies due to non-contiguous memory allocation, it provides O(1) complexity for insertions and deletions at the head of the list. This trade-off is acceptable given the requirement for frequent purging operations.
- **Memory Management**: Careful use of dynamic memory ensures scalability without unnecessary consumption of resources.

This implementation supports integration with a database by adding persistence logic in the `addUEContextRecord` function, which would typically involve inserting or updating records in an external system. The code is structured to handle potential data inconsistencies and can be extended for horizontal scaling through distributed systems design principles if needed.']

