#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t max_size;
} ThreadSafeList;

void initialize_list(ThreadSafeList* list, size_t max_size) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->max_size = max_size;
}

int is_full(const ThreadSafeList* list) {
    return list->count >= list->max_size;
}

void generate_random_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag (0 or 1)
}

void insert_pdu(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    while (is_full(list)) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    new_node->data = pdu;
    new_node->timestamp = time(NULL);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    // Notify potentially waiting threads that space is available
    pthread_cond_signal(&list->mutex);

    pthread_mutex_unlock(&list->mutex);
}

void free_list(ThreadSafeList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
}

void process_data(ThreadSafeList* list, size_t max_size) {
    initialize_list(list, max_size);

    // Example usage
    for (int i = 0; i < 10; ++i) {  // Simulate data insertion
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();  // Randomly generated tag
        pdu.RNTI = rand();
        generate_random_crc_flag(&pdu);

        insert_pdu(list, pdu);
    }

    free_list(list);
}

int main() {
    srand(time(NULL));  // Seed random number generator

    ThreadSafeList list;
    process_data(&list, 5);  // Set max size to 5 for this example

    return 0;
}
