typedef struct PDU_List_Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PDU_List_Node* next;
} PDU_List_Node_t;

PDU_List_Node_t* global_pdu_list = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Custom memory pool for efficient allocation
#define POOL_SIZE 1024 * 64 // Adjust size based on expected load

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data[POOL_SIZE];
    int free_index;
} MemoryPool;

MemoryPool* create_memory_pool() {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    memset(pool, 0, sizeof(MemoryPool));
    pool->free_index = 0;
    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* pool) {
    if (pool->free_index >= POOL_SIZE) return NULL;
    return &pool->data[pool->free_index++];
}

void free_memory_pool(MemoryPool** pool_ptr) {
    MemoryPool* pool = *pool_ptr;
    if (!pool) return;
    memset(pool, 0, sizeof(MemoryPool));
    free(pool);
    *pool_ptr = NULL;
}

// Function to create and populate PDU structures
NFAPI_CRC_INDICATION_PDU_T** create_pdus(int N, unsigned int seed, UE_CONFIG_T* ue_config, MemoryPool** pool_ptr) {
    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) return NULL;

    MemoryPool* pool = create_memory_pool();
    if (!pool) {
        free(pdus);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool(pool);
        if (!pdu) {
            // Free partially allocated structures
            while (i > 0) {
                --i;
                PDU_List_Node_t* node = &global_pdu_list[i];
                pthread_mutex_lock(&list_lock);
                global_pdu_list = node->next;
                pthread_mutex_unlock(&list_lock);
            }
            free_memory_pool(&pool);
            free(pdus);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = ue_config->UE_INFO; // Example assignment
        pdu->RNTI = rand(); // Random RNTI for illustration
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag

        pdus[i] = pdu;

        // Add to global list with thread safety
        PDU_List_Node_t* node = (PDU_List_Node_t*)malloc(sizeof(PDU_List_Node_t));
        if (!node) {
            free_memory_pool(&pool);
            free(pdus);
            return NULL;
        }
        memcpy(&(node->pdu), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        pthread_mutex_lock(&list_lock);
        node->next = global_pdu_list;
        global_pdu_list = node;
        pthread_mutex_unlock(&list_lock);

        // Logging
        printf("PDU created at %ld with RNTI: %u\n", time(NULL), pdu->RNTI);
    }

    *pool_ptr = pool; // Return the pool for later deallocation
    return pdus;
}

// Unit test function to verify correctness
void test_create_pdus() {
    UE_CONFIG_T ue_config = { .UE_INFO = 12345 };
    int N = 10;
    unsigned int seed = 42;

    MemoryPool* pool = NULL;
    NFAPI_CRC_INDICATION_PDU_T** pdus = create_pdus(N, seed, &ue_config, &pool);

    if (pdus) {
        printf("Test passed: %d PDUs created.\n", N);
        // Add more checks as needed

        free_memory_pool(&pool);
        for (int i = 0; i < N; ++i) {
            pthread_mutex_lock(&list_lock);
            global_pdu_list = pdus[i]->next;
            pthread_mutex_unlock(&list_lock);
            free(pdus[i]);
        }
        free(pdus);
    } else {
        printf("Test failed: PDUs could not be created.\n");
    }
}

int main() {
    test_create_pdus();
    return 0;
}
