#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set CRC flag (0 or 1)
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array();
int add_pdu(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu);
int remove_pdu(DynamicArray* array, int RX_UE_INFORMATION_TAG);
void iterate_pdus(DynamicArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T));
void free_dynamic_array(DynamicArray* array);

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int add_pdu(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&array->lock);
    new_node->next = array->head;
    array->head = new_node;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

int remove_pdu(DynamicArray* array, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head, *prev = NULL;

    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Not found
    }

    if (prev == NULL) { // Head needs to be removed
        array->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void iterate_pdus(DynamicArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;

    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
}

void free_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void print_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %u\n",
           pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG, pdu.CRCFLAG);
}

// Example usage
int main() {
    DynamicArray* array = create_dynamic_array();
    if (!array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 100, 2000, 0};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 101, 2001, 1};

    add_pdu(array, pdu1);
    add_pdu(array, pdu2);

    iterate_pdus(array, print_pdu);

    remove_pdu(array, 1);

    iterate_pdus(array, print_pdu);

    free_dynamic_array(array);

    return 0;
}
```

