#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IP_LENGTH 16
#define MAX_MAC_LENGTH 18

typedef struct {
    char ip[MAX_IP_LENGTH];
    char subnet_mask[MAX_IP_LENGTH];
    char gateway[MAX_IP_LENGTH];
    char mac_address[MAX_MAC_LENGTH];
} NetworkInterfaceConfig;

typedef struct Node {
    NetworkInterfaceConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} InterfaceList;

void init_list(InterfaceList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int is_unique_ip(const NetworkInterfaceConfig* new_config, const InterfaceList* list) {
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->config.ip, new_config->ip) == 0) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

int validate_config(const NetworkInterfaceConfig* config) {
    // Basic validation logic for IP, subnet mask, gateway and MAC
    if (strlen(config->ip) < 7 || strlen(config->subnet_mask) < 7 ||
        strlen(config->gateway) < 7 || strlen(config->mac_address) < 17)
        return 0;
    return 1;
}

void add_config(InterfaceList* list, NetworkInterfaceConfig new_config) {
    if (!validate_config(&new_config)) {
        printf("Invalid configuration.\n");
        return;
    }

    pthread_mutex_lock(&list->mutex);

    if (!is_unique_ip(&new_config, list)) {
        printf("Duplicate IP address found.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node.");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    memcpy(&new_node->config, &new_config, sizeof(NetworkInterfaceConfig));
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
}

void remove_config(InterfaceList* list, const char* ip) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && strcmp(current->config.ip, ip) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Configuration not found.\n");
    } else {
        if (prev == NULL) {
            list->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
    }

    pthread_mutex_unlock(&list->mutex);
}

NetworkInterfaceConfig* get_config(InterfaceList* list, const char* ip) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL && strcmp(current->config.ip, ip) != 0) {
        current = current->next;
    }

    NetworkInterfaceConfig* config = NULL;
    if (current != NULL) {
        config = &current->config;
    }

    pthread_mutex_unlock(&list->mutex);
    return config;
}

void free_list(InterfaceList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int main() {
    InterfaceList list;
    init_list(&list);

    NetworkInterfaceConfig config1 = {"192.168.0.1", "255.255.255.0", "192.168.0.254", "00:11:22:33:44:55"};
    add_config(&list, config1);

    NetworkInterfaceConfig* retrieved_config = get_config(&list, "192.168.0.1");
    if (retrieved_config) {
        printf("Retrieved IP: %s\n", retrieved_config->ip);
    }

    remove_config(&list, "192.168.0.1");

    free_list(&list);

    return 0;
}
```']

