} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} CRCIndicationList;

CRCIndicationList* create_list(size_t initial_capacity) {
    CRCIndicationList *list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;

    list->items = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(CRCIndicationList *list) {
    if (!list) return;

    free(list->items);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_structure(CRCIndicationList *list, NFAPI_CRC_INDICATION_PDU_T new_struct) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    // Check for RNTI duplicates
    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i].rnti == new_struct.rnti) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate found
        }
    }

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_items = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_items) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }

        list->items = new_items;
        list->capacity = new_capacity;
    }

    list->items[list->count++] = new_struct;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_structure_by_index(CRCIndicationList *list, size_t index) {
    if (!list || index >= list->count) return -1;

    pthread_mutex_lock(&list->lock);

    memmove(&list->items[index], &list->items[index + 1], (list->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count--;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* get_structure_by_rnti(CRCIndicationList *list, RNTI rnti) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i].rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &list->items[i];
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

