#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the UE Context structure
typedef struct {
    unsigned int ue_id;
    unsigned int serving_cell_id;
    float downlink_data_rate; // in Mbps
    float uplink_data_rate;   // in Mbps
} UEContext;

// Define a node for linked list
typedef struct Node {
    UEContext context;
    struct Node* next;
} Node;

// Dynamic List structure
typedef struct {
    Node* head;
    pthread_mutex_t lock;  // Mutex for thread safety
} UEList;

// Initialize the dynamic list
void initializeUEList(UEList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new UE context to the list
void addUEContext(UEList* list, UEContext context) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;  // Check for malloc failure

    newNode->context = context;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

// Update an existing UE context
void updateUEContext(UEList* list, unsigned int ue_id, float downlink_rate, float uplink_rate) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->context.ue_id == ue_id) {
            current->context.downlink_data_rate = downlink_rate;
            current->context.uplink_data_rate = uplink_rate;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);  // Unlock if UE not found
}

// Retrieve a UE context by its ID
UEContext* getUEContext(UEList* list, unsigned int ue_id) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->context.ue_id == ue_id) {
            UEContext* context = &current->context;
            pthread_mutex_unlock(&list->lock);
            return context;  // Caller responsible for thread safety
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;  // Return NULL if not found
}

// Free the entire list and its resources
void freeUEList(UEList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    UEList ueList;
    initializeUEList(&ueList);

    UEContext context1 = {1, 101, 100.0f, 50.0f};
    addUEContext(&ueList, context1);

    updateUEContext(&ueList, 1, 120.0f, 60.0f);

    UEContext* retrievedContext = getUEContext(&ueList, 1);
    if (retrievedContext) {
        printf("UE ID: %u\n", retrievedContext->ue_id);
        printf("Downlink Rate: %.2f Mbps\n", retrievedContext->downlink_data_rate);
        printf("Uplink Rate: %.2f Mbps\n", retrievedContext->uplink_data_rate);
    }

    freeUEList(&ueList);

    return 0;
}
