#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define INITIAL_SIZE 10

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Assume this is an integer for simplicity
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        return NULL;
    }

    list->used = 0;
    list->size = INITIAL_SIZE;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void verify_crc_flags(DynamicList* list) {
    for (size_t i = 0; i < list->used; ++i) {
        // Simple integrity check: CRCFLAG must be either 0 or 1
        if (list->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0 && 
            list->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 1) {
            fprintf(stderr, "Integrity check failed for index %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

int add_pdu(DynamicList* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    if (list->used == list->size) {
        size_t newSize = list->size * 2;
        NFAPI_CRC_INDICATION_PDU_T* newArray = 
            (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!newArray) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->array = newArray;
        list->size = newSize;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->array[list->used++];
