    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_dynamic_list(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    free(list->array);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

