#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

bool isValidRange(uint32_t tag, uint32_t minTag, uint32_t maxTag) {
    return tag >= minTag && tag <= maxTag;
}

void logViolation(const char* message) {
    fprintf(stderr, "Validation Violation: %s\n", message);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data, bool crcFlag) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        logViolation("Memory allocation failed for new node.");
        return NULL;
    }
    newNode->data.RX_UE_INFORMATION_TAG = data.RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = data.RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG.CRCFLAG = crcFlag;
    newNode->next = NULL;
    return newNode;
}

bool addNode(Node** head, NFAPI_CRC_INDICATION_PDU_T data, uint32_t minTag, uint32_t maxTag) {
    if (!isValidRange(data.RX_UE_INFORMATION_TAG, minTag, maxTag)) {
        logViolation("RX_UE_INFORMATION_TAG out of range.");
        return false;
    }

    Node* current = *head;
    bool crcFlag = rand() % 2; // Randomly set CRCFLAG

    while (current) {
        if (crcFlag != current->data.CRC_INDICATION_REL8_TAG.CRCFLAG) {
            logViolation("Inconsistent CRCFLAG in list.");
            return false;
        }
        if (current->next && data.RNTI == current->next->data.RNTI) {
            logViolation("Consecutive elements with the same RNTI detected.");
            return false;
        }
        current = current->next;
    }

    Node* newNode = createNode(data, crcFlag);
    if (!newNode) return false;

    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }

    return true;
}

void freeList(Node** head) {
    Node* current = *head;
    Node* nextNode;

    while (current != NULL) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }

    *head = NULL;
}

size_t serializeList(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return 0;

    size_t count = 0;
    Node* current = head;

    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        count++;
        current = current->next;
    }

    fclose(file);
    return count;
}

Node* deserializeList(const char* filename, uint32_t minTag, uint32_t maxTag) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    Node* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;

    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        if (!addNode(&head, data, minTag, maxTag)) {
            logViolation("Deserialization failed due to validation error.");
            freeList(&head);
            break;
        }
    }

    fclose(file);
    return head;
}

int main() {
    Node* list = NULL;
    uint32_t minTag = 1000, maxTag = 2000;

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T exampleData = {1500, 42, {.CRCFLAG = false}};
    addNode(&list, exampleData, minTag, maxTag);

    serializeList(list, "nfa_list.bin");
    Node* newList = deserializeList("nfa_list.bin", minTag, maxTag);

    freeList(&list);
    freeList(&newList);

    return 0;
}
