#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} SortedLinkedList;

SortedLinkedList* create_list() {
    SortedLinkedList* list = (SortedLinkedList*)malloc(sizeof(SortedLinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(SortedLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_rnti(SortedLinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->data = pdu;
    new_node->next = NULL;
    new_node->prev = NULL;

    Node* current = list->head;
    while (current && current->data.RNTI < pdu.RNTI) {
        if (current->data.RNTI == pdu.RNTI) {
            free(new_node);
            pthread_mutex_unlock(&list->lock);
            fprintf(stderr, "Error: Duplicate RNTI encountered.\n");
            return -1;
        }
        current = current->next;
    }

    if (!list->head || list->head->data.RNTI > pdu.RNTI) {
        new_node->next = list->head;
        if (list->head) list->head->prev = new_node;
        list->head = new_node;
        if (!list->tail) list->tail = new_node;
    } else {
        Node* prev_node = current ? current->prev : list->tail;
        new_node->next = current;
        if (current) current->prev = new_node;
        new_node->prev = prev_node;
        if (prev_node) prev_node->next = new_node;
        if (!new_node->next) list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void iterate_forward(SortedLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_reverse(SortedLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->tail;
    while (current) {
        callback(&(current->data));
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

