           pdu->RNTI, pdu->RX_UE_INFORMATION_TAG, pdu->CRC_INDICATION_REL8_TAG);
}

int main() {
    SortedLinkedList* list = create_list();
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 100, 10};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 200, 20};

    insert_rnti(list, pdu1);
    insert_rnti(list, pdu2);

    printf("Forward iteration:\n");
    iterate_forward(list, print_pdu);

    printf("\nReverse iteration:\n");
    iterate_reverse(list, print_pdu);

    destroy_list(list);
    return 0;
}
