    Node* head;
    pthread_mutex_t lock;
    uint32_t total_allocations;
    uint32_t total_deallocations;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->total_allocations = 0;
    list->total_deallocations = 0;

    return list;
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (pthread_mutex_lock(&list->lock)) return -1;

    // Constraint checks
    if (data.ue_info_tag < MIN_RX_UE_TAG || data.ue_info_tag > MAX_RX_UE_TAG) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Violation: RX_UE_INFORMATION_TAG out of range.\n");
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    list->total_allocations++;

    new_node->data = data;
    new_node->next = NULL;

    if (list->head == NULL || list->head->data.RNTI != data.RNTI) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next && current->next->data.RNTI != data.RNTI) {
            current = current->next;
        }
        if (!current->next || current->next->data.RNTI != data.RNTI) {
            new_node->next = current->next;
            current->next = new_node;
        } else {
            free(new_node);
            list->total_deallocations++;
            pthread_mutex_unlock(&list->lock);
            fprintf(stderr, "Violation: Consecutive RNTIs match.\n");
            return -1;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void delete_list(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        list->total_deallocations++;
        current = next_node;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int serialize_list(LinkedList* list, const char* file_path) {
    if (!list || !file_path) return -1;

    FILE* file = fopen(file_path, "wb");
    if (!file) return -1;

    if (pthread_mutex_lock(&list->lock)) return -1;

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0;
}

int deserialize_list(LinkedList* list, const char* file_path) {
    if (!list || !file_path) return -1;

    FILE* file = fopen(file_path, "rb");
    if (!file) return -1;

    if (pthread_mutex_lock(&list->lock)) return -1;

    while (fread(&(NFAPI_CRC_INDICATION_PDU_T){0}, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_node(list, *(NFAPI_CRC_INDICATION_PDU_T*)file);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0;
}

