#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    union {
        struct {
            unsigned char CRCFLAG;
        } CRC_INDICATION_REL8_TAG;
    };
} NFAPI_CRC_INDICATION_PDU_T;

// Validation function prototype
bool validateCRC(NFAPI_CRC_INDICATION_PDU_T* pdu);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T**)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->count = 0;
    da->capacity = initialCapacity;
    pthread_mutex_init(&da->lock, NULL);

    return da;
}

void destroyDynamicArray(DynamicArray* da) {
    if (da) {
        for (size_t i = 0; i < da->count; ++i) {
            free(da->array[i]);
        }
        free(da->array);
        pthread_mutex_destroy(&da->lock);
        free(da);
    }
}

bool resizeDynamicArray(DynamicArray* da, size_t newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T** newArray = (NFAPI_CRC_INDICATION_PDU_T**)realloc(da->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!newArray) return false;

    for (size_t i = da->count; i < newCapacity; ++i) {
        newArray[i] = NULL;
    }

    da->array = newArray;
    da->capacity = newCapacity;
    return true;
}

int addCRCIndication(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!validateCRC(pdu)) {
        return -1; // Validation failed
    }

    pthread_mutex_lock(&da->lock);

    if (da->count == da->capacity) {
        size_t newCapacity = da->capacity * 2;
        if (!resizeDynamicArray(da, newCapacity)) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failed
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* newPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newPdu) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Memory allocation failed
    }

    *newPdu = *pdu;
    da->array[da->count++] = newPdu;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

bool validateCRC(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return false;

    // Simulate CRC validation logic
    srand(time(NULL));
    bool isValid = (rand() % 2 == 1); // Randomly valid/invalid for demonstration

    // Example of setting the CRCFLAG randomly
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;

    return isValid;
}

// Example usage with threads
void* threadFunction(void* arg) {
    DynamicArray* da = (DynamicArray*)arg;

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() };
    if (addCRCIndication(da, &pdu) != 0) {
        printf("Failed to add CRC Indication\n");
    }

    return NULL;
}

int main() {
    DynamicArray* da = createDynamicArray(10);

    const int numThreads = 5;
    pthread_t threads[numThreads];

    for (int i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], NULL, threadFunction, da) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroyDynamicArray(da);

    return 0;
}
