    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->report = report;
    new_node->pdu = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&array->lock);

    new_node->next = array->head;
    array->head = new_node;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_report(DL_CQI_DynamicArray* array, int ue_id, DL_CQI_Report updated_report) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;
    while (current != NULL) {
        if (current->report.ue_id == ue_id) {
            current->report = updated_report;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Report not found
}

DL_CQI_Report* get_reports(DL_CQI_DynamicArray* array, int band_info) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;
    while (current != NULL && current->report.band_info == band_info) {
        current = current->next;
    }

    // Allocate memory for reports to return
    int count = 0;
    current = array->head;
    while (current != NULL && current->report.band_info == band_info) {
        count++;
        current = current->next;
    }

    DL_CQI_Report* result = malloc(count * sizeof(DL_CQI_Report));
    if (!result) {
        pthread_mutex_unlock(&array->lock);
        return NULL; // Allocation failed
    }

    int index = 0;
    current = array->head;
    while (current != NULL && index < count) {
        if (current->report.band_info == band_info) {
            result[index++] = current->report;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return result; // Caller must free this memory
}

void random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        pdu->crcflag = rand() % 2; // Randomly set to 0 or 1
    }
}

// Example usage
int main() {
    srand(time(NULL));

    DL_CQI_DynamicArray* array = create_array();
    if (!array) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.valid = 1;
    pdu.rx_ue_information_tag = rand(); // Random for demo
    pdu.rnti = rand();

    random_crcflag(&pdu);

    DL_CQI_Report report;
    report.ue_id = 1;
    report.frequency_point = 100;
    report.timestamp = time(NULL);
    report.band_info = 5;

    add_report(array, report, pdu);

    // Example: Get reports for band_info == 5
    DL_CQI_Report* reports = get_reports(array, 5);
    if (reports) {
        for (int i = 0; i < MAX_FREQUENCY_POINTS; i++) {
            printf("Report UE ID: %d\n", reports[i].ue_id);
            free(reports); // Free when done
        }
    }

    destroy_array(array);

    return 0;
}
```

