typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t current_memory_usage;
    pthread_mutex_t lock;
} NFAPIDataList;

// Mock external logging service
void log_event(const char* message) {
    // Thread-safe, non-blocking logging implementation
    printf("%s\n", message); // Placeholder for actual logging logic
}

int is_list_full(NFAPIDataList* list, size_t structure_size) {
    return (list->current_memory_usage + structure_size > MAX_MEMORY_LIMIT);
}

void free_unused_resources(NFAPIDataList* list) {
    Node* current = list->head;
    Node* temp;
    while (current != NULL && is_list_full(list, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        log_event("Freeing unused resources...");
        list->current_memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
        temp = current;
        current = current->next;
        free(temp);
    }
    list->head = current;
}

int add_pdu_to_list(NFAPIDataList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (is_list_full(list, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        free_unused_resources(list);
        if (is_list_full(list, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            pthread_mutex_unlock(&list->lock);
            return -1; // List is still full
        }
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_event("Memory allocation failed!");
        return -2;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->current_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    log_event("PDU added to list.");

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void initialize_list(NFAPIDataList* list) {
    memset(list, 0, sizeof(NFAPIDataList));
    pthread_mutex_init(&list->lock, NULL);
}

int main() {
