                                      .RNTI = 2,
                                      .CRC_INDICATION_REL8_TAG = 3,
                                      .CRCFLAG = rand() % 2 }; // Randomly set

    int result = add_pdu_to_list(&pdu_list, pdu);
    if (result == -1) {
        log_event("Failed to add PDU: List is full.");
    } else if (result == -2) {
        log_event("Failed to add PDU: Memory allocation error.");
    }

    // Cleanup
    Node* current = pdu_list.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&pdu_list.lock);

