    if (!pdu) return NULL;

    pdu->message.type = type;
    pdu->message.seq_number = seq_number;
    pdu->message.data = malloc(data_size);
    if (pdu->message.data) {
        memcpy(pdu->message.data, data, data_size);
        pdu->message.data_size = data_size;
    } else {
        free(pdu);
        return NULL;
    }

    pdu->next = NULL;
    return pdu;
}

