        pthread_mutex_unlock(&list->lock);
        return;
    }

    log_creation(pdu);

    pdu->next = list->head;
    list->head = pdu;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void remove_pdu_from_list(PDU_List* list, NF_NAS_PDU** pdu_out) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    *pdu_out = list->head;
    list->head = (*pdu_out)->next;
    list->count--;

    pthread_mutex_unlock(&list->lock);
}

void free_pdu(NF_NAS_PDU* pdu) {
    if (pdu) {
        free(pdu->message.data);
        free(pdu);
    }
}

void destroy_pdu_list(PDU_List* list) {
    NF_NAS_PDU* current = NULL;
    while ((current = list->head)) {
        list->head = current->next;
        free_pdu(current);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void log_creation(NF_NAS_PDU* pdu) {
