}

void freeIntegerArray(IntegerArray *array) {
    if (array->data) {
        free(array->data);
    }
    pthread_mutex_destroy(&array->mutex);
}

void filterAndStoreIntegers(IntegerArray *array, int (*filterFunc)(int)) {
    int number;
    while (scanf("%d", &number) == 1) {
        pthread_mutex_lock(&array->mutex);
        if (array->count < array->data ? sizeof(array->data) / sizeof(array->data[0]) : 10000 && filterFunc(number)) {
            array->data[array->count++] = number;
        }
        pthread_mutex_unlock(&array->mutex);
    }
}

int findLargestInteger(const IntegerArray *array) {
    if (array->count == 0) return INT_MIN;

    int largest = array->data[0];
    for (size_t i = 1; i < array->count; ++i) {
        if (array->data[i] > largest) {
            largest = array->data[i];
        }
    }
    return largest;
}

void processRxDataAndIntegers(size_t pduSize, int (*filterFunc)(int)) {
    PduList pduList;
    IntegerArray integerArray;

    initializePduList(&pduList, pduSize);
    initializeIntegerArray(&integerArray, 10000);

    // Populate the list with some example data
    for (size_t i = 0; i < pduSize; ++i) {
        pduList.pdus[i].valid_RX_UE_INFORMATION_TAG = rand();
        pduList.pdus[i].RNTI = rand();
        ++pduList.count;
    }

    pthread_t thread1, thread2;

    // Process PDUs in a separate thread to maintain responsiveness
    pthread_create(&thread1, NULL, (void *(*)(void *))processPdus, &pduList);

    // Filter and store integers in the main thread
    filterAndStoreIntegers(&integerArray, filterFunc);

    pthread_join(thread1, NULL);

    int largestInteger = findLargestInteger(&integerArray);
    printf("Largest integer: %d\n", largestInteger);

    freePduList(&pduList);
    freeIntegerArray(&integerArray);
}

int isEven(int number) {
    return number % 2 == 0;
}

// Example usage
int main() {
    processRxDataAndIntegers(10000, isEven);
    return 0;
}
