// Add or update an element in the dynamic array
void addOrUpdateElement(DynamicArray* arr, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (arr->count >= MAX_ELEMENTS) {
        handleError("Maximum number of elements reached.");
    }

    // Check for existing entry
    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->elements[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && 
            arr->elements[i].RNTI == RNTI) {

            free(arr->elements[i].crcTag);
            arr->elements[i].crcTag = NULL;
            break;
        }
    }

    if (arr->count >= arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newElements = realloc(arr->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newElements) {
            handleError("Memory reallocation failed.");
        }
        arr->elements = newElements;
        arr->capacity = newCapacity;
    }

    NFAPI_CRC_INDICATION_PDU_T newElement;
    newElement.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement.RNTI = RNTI;

    // Dynamically allocate CRC tag with random CRCFLAG
    newElement.crcTag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!newElement.crcTag) {
        handleError("Memory allocation for CRC tag failed.");
    }
    newElement.crcTag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    arr->elements[arr->count++] = newElement;
}

// Free all allocated resources in the dynamic array
void freeDynamicArray(DynamicArray* arr) {
    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->elements[i].crcTag) {
            free(arr->elements[i].crcTag);
        }
    }
    free(arr->elements);
    arr->elements = NULL;
    arr->count = 0;
    arr->capacity = 0;
}

// Example usage
