#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define maximum size for error codes list
#define MAX_ERROR_CODES 10

typedef struct {
    int connection_id;
    time_t last_activity;
    int error_codes[MAX_ERROR_CODES];
    size_t error_count;
} ConnectionMetadata;

typedef struct {
    ConnectionMetadata *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicConnectionArray;

DynamicConnectionArray* create_dynamic_array(size_t initial_capacity) {
    DynamicConnectionArray *array = (DynamicConnectionArray*)malloc(sizeof(DynamicConnectionArray));
    if (!array) return NULL;

    array->connections = (ConnectionMetadata*)calloc(initial_capacity, sizeof(ConnectionMetadata));
    if (!array->connections) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicConnectionArray *array) {
    if (array) {
        free(array->connections);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int add_connection(DynamicConnectionArray *array, int connection_id) {
    pthread_mutex_lock(&array->lock);

    // Check if the connection already exists
    for (size_t i = 0; i < array->count; ++i) {
        if (array->connections[i].connection_id == connection_id) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Connection ID already exists
        }
    }

    // Expand the array if necessary
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        ConnectionMetadata *new_connections = realloc(array->connections, new_capacity * sizeof(ConnectionMetadata));
        if (!new_connections) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->connections = new_connections;
        array->capacity = new_capacity;
    }

    // Add the new connection metadata
    ConnectionMetadata *metadata = &array->connections[array->count++];
    metadata->connection_id = connection_id;
    metadata->last_activity = time(NULL);
    metadata->error_count = 0;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int update_last_activity(DynamicConnectionArray *array, int connection_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->connections[i].connection_id == connection_id) {
            array->connections[i].last_activity = time(NULL);
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Connection ID not found
}

int get_most_recent_error(DynamicConnectionArray *array, int connection_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->connections[i].connection_id == connection_id) {
            if (array->connections[i].error_count > 0) {
                int error_code = array->connections[i].error_codes[array->connections[i].error_count - 1];
                pthread_mutex_unlock(&array->lock);
                return error_code; // Return the most recent error code
            }
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Connection ID not found or no errors
}

int add_error_code(DynamicConnectionArray *array, int connection_id, int error_code) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->connections[i].connection_id == connection_id) {
            if (array->connections[i].error_count >= MAX_ERROR_CODES) {
                // Optional: handle overflow, e.g., remove oldest error
                memmove(array->connections[i].error_codes,
                        array->connections[i].error_codes + 1,
                        (MAX_ERROR_CODES - 1) * sizeof(int));
            }
            array->connections[i].error_codes[array->connections[i].error_count++] = error_code;
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Connection ID not found
}
```

This code defines a dynamic array structure for managing TCP connection metadata, ensuring thread safety using mutex locks. It supports adding new connections, updating timestamps, and retrieving error codes efficiently while handling concurrent access. The choice of arrays over linked lists is made to optimize memory usage and insertion performance in this context.']

