// Define constants
#define MAX_STREAMS 10000

// Stream structure
typedef struct {
    int stream_id;
    unsigned long packet_seq_num;
    time_t timestamp;
    int error_status; // 0 = no error, non-zero = error code
} Stream;

// Network interface structure
typedef struct {
    Stream *streams[MAX_STREAMS];
    pthread_mutex_t lock;
    size_t active_stream_count;
} NetworkInterface;

// Initialize the network interface
void init_network_interface(NetworkInterface *ni) {
    memset(ni->streams, 0, sizeof(ni->streams));
    pthread_mutex_init(&ni->lock, NULL);
    ni->active_stream_count = 0;
}

// Add a stream to the network interface
int add_stream(NetworkInterface *ni, int stream_id) {
    pthread_mutex_lock(&ni->lock);

    if (ni->active_stream_count >= MAX_STREAMS) {
        pthread_mutex_unlock(&ni->lock);
        return -1; // No space for more streams
    }

    Stream *stream = malloc(sizeof(Stream));
    if (!stream) {
        pthread_mutex_unlock(&ni->lock);
        return -2; // Memory allocation failed
    }

    stream->stream_id = stream_id;
    stream->packet_seq_num = 0;
    time(&stream->timestamp);
    stream->error_status = 0;

    ni->streams[ni->active_stream_count++] = stream;

    pthread_mutex_unlock(&ni->lock);
    return 0; // Success
}

// Remove a stream from the network interface
int remove_stream(NetworkInterface *ni, int stream_id) {
    pthread_mutex_lock(&ni->lock);

    for (size_t i = 0; i < ni->active_stream_count; ++i) {
        if (ni->streams[i]->stream_id == stream_id) {
            free(ni->streams[i]);
            memmove(&ni->streams[i], &ni->streams[i + 1],
                    (ni->active_stream_count - i - 1) * sizeof(Stream *));
            ni->active_stream_count--;
            pthread_mutex_unlock(&ni->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&ni->lock);
    return -1; // Stream not found
}

// Get stream information by ID
Stream* get_stream_info(NetworkInterface *ni, int stream_id) {
    pthread_mutex_lock(&ni->lock);

    for (size_t i = 0; i < ni->active_stream_count; ++i) {
        if (ni->streams[i]->stream_id == stream_id) {
            pthread_mutex_unlock(&ni->lock);
            return ni->streams[i];
        }
    }

    pthread_mutex_unlock(&ni->lock);
    return NULL; // Stream not found
}

// Example error handling function
void log_error(const char *message, int error_code) {
    fprintf(stderr, "Error %d: %s\n", error_code, message);
}

// Cleanup the network interface
void cleanup_network_interface(NetworkInterface *ni) {
    pthread_mutex_lock(&ni->lock);

    for (size_t i = 0; i < ni->active_stream_count; ++i) {
        free(ni->streams[i]);
    }

    pthread_mutex_unlock(&ni->lock);
    pthread_mutex_destroy(&ni->lock);
}

// Example usage
int main() {
    NetworkInterface ni;
    init_network_interface(&ni);

    if (add_stream(&ni, 1) == 0) {
        printf("Stream added successfully.\n");
    } else {
        log_error("Failed to add stream", -1);
    }

    Stream *stream = get_stream_info(&ni, 1);
    if (stream) {
        printf("Stream ID: %d\n", stream->stream_id);
    } else {
        log_error("Stream not found", -2);
    }

    cleanup_network_interface(&ni);
    return 0;
}
```

This code provides a basic implementation of the network interface with thread-safe operations for managing streams. It includes functions to initialize, add, remove, and query streams, as well as error handling and logging mechanisms. The design focuses on scalability, memory efficiency, concurrency, and performance optimization.']

