DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray *)malloc(sizeof(DynamicArray));
    da->capacity = initial_capacity;
    da->count = 0;
    da->array = (LTE_RRC_CUCCH_SRB2_MESSAGE_T *)calloc(initial_capacity, sizeof(LTE_RRC_CUCCH_SRB2_MESSAGE_T));
    return da;
}

int add_entry(DynamicArray *da, LTE_RRC_CUCCH_SRB2_MESSAGE_T entry) {
    if (da->count == da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        LTE_RRC_CUCCH_SRB2_MESSAGE_T *new_array = 
            (LTE_RRC_CUCCH_SRB2_MESSAGE_T *)realloc(da->array, new_capacity * sizeof(LTE_RRC_CUCCH_SRB2_MESSAGE_T));

        if (!new_array) return -1; // Error handling for realloc failure

        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->count++] = entry;
    return 0;
}

int update_entry(DynamicArray *da, size_t index, LTE_RRC_CUCCH_SRB2_MESSAGE_T entry) {
    if (index >= da->count) return -1; // Error handling for out-of-bounds
    da->array[index] = entry;
    return 0;
