    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].cucch_harq_process_info.dynamic_data != NULL) {
            free(da->array[i].cucch_harq_process_info.dynamic_data);
        }
    }
    free(da->array);
    free(da);
}

int delete_entry(DynamicArray *da, size_t index) {
    if (index >= da->count) return -1; // Error handling for out-of-bounds

    if (da->array[index].cucch_harq_process_info.dynamic_data != NULL) {
        free(da->array[index].cucch_harq_process_info.dynamic_data);
