#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>

#define MAX_CIPHER_MODES 3

typedef enum {
    MODE_CBC,
    MODE_GCM,
    MODE_CTR
} CipherMode;

typedef struct {
    int rx_ue_information_tag;
    unsigned long rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

EVP_CIPHER_CTX* init_cipher_context(const char *cipher_name, const unsigned char *key, 
                                    size_t key_len, const unsigned char *iv, 
                                    CipherMode mode) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const EVP_CIPHER *cipher;
    if (strcmp(cipher_name, "AES") == 0) {
        switch (mode) {
            case MODE_CBC: cipher = EVP_aes_256_cbc(); break;
            case MODE_GCM: cipher = EVP_aes_256_gcm(); break;
            case MODE_CTR: cipher = EVP_aes_256_ctr(); break;
            default: return NULL;
        }
    } else if (strcmp(cipher_name, "ChaCha20") == 0) {
        switch (mode) {
            case MODE_CBC: cipher = EVP_chacha20_poly1305(); break;
            case MODE_GCM: cipher = EVP_chacha20_poly1305(); break; // Using same as no specific GCM
            case MODE_CTR: cipher = EVP_chacha20(); break;
            default: return NULL;
        }
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void generate_crc_indications(NFAPI_CRC_INDICATION_PDU_T *indication_array, size_t count) {
