    RX_UE_INFORMATION_TAG ueInformationTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a unique random RNTI, checking against existing ones
uint32_t generateUniqueRNTI(uint32_t *existingRNTIs, size_t count) {
    uint32_t newRNTI;
    int isUnique;

    do {
        // Random number generation for RNTI; adjust range as necessary
        newRNTI = rand() % 0xFFFFF + 1;

        isUnique = 1;
        for (size_t i = 0; i < count; ++i) {
            if (existingRNTIs[i] == newRNTI) {
                isUnique = 0;
                break;
            }
        }
    } while (!isUnique);

    return newRNTI;
}

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T
NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndicationPduArray(size_t numElements, size_t maxBufferSize) {
    if (numElements > maxBufferSize || numElements == 0) {
        fprintf(stderr, "Invalid number of elements requested.\n");
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *pduArray = malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    uint32_t existingRNTIs[numElements];

    for (size_t i = 0; i < numElements; ++i) {
        pduArray[i].ueInformationTag.rnti = generateUniqueRNTI(existingRNTIs, i);
        existingRNTIs[i] = pduArray[i].rnti;
        pduArray[i].rnti = pduArray[i].ueInformationTag.rnti;

        // Set a random CRC_FLAG
        pduArray[i].crcIndicationRel8Tag.crcFlag = rand() % 2; // Randomly set to 0 or 1

        // Additional logic for processing RX_UE_INFORMATION_TAG could be added here if needed
    }

    return pduArray;
}

// Function to free the allocated memory
void freeNFAPICRCIndicationPduArray(NFAPI_CRC_INDICATION_PDU_T *pduArray) {
    if (pduArray) {
        free(pduArray);
    }
}

int main() {
    size_t numElements = 10;
    size_t maxBufferSize = 100;

    NFAPI_CRC_INDICATION_PDU_T* pduArray = createNFAPICRCIndicationPduArray(numElements, maxBufferSize);

    if (pduArray) {
        // Process the array or perform other operations as needed

        // Free allocated resources
        freeNFAPICRCIndicationPduArray(pduArray);
    }

    return 0;
}
