                                      const PHY_RX_CHANNEL_INFO* channels, int num_channels,
                                      size_t max_channel_info_size, LoggingFramework* log_framework) {

    if (rx_frame_tag < 0 || cell_id < 0 || num_channels <= 0 || 
        !channels || !log_framework || max_channel_info_size == 0) {
        return NULL; // Error handling for invalid inputs
    }

    LTE_PHY_RX_FRAME* frame = (LTE_PHY_RX_FRAME*)malloc(sizeof(LTE_PHY_RX_FRAME));
    if (!frame) {
        log_framework->log("Memory allocation failed for frame.");
        return NULL;
