    for (int i = 0; i < num_channels; ++i) {
        if (channels[i].signal_strength >= SIGNAL_QUALITY_THRESHOLD) {
            valid_channel_count++;
            required_memory += sizeof(PHY_RX_CHANNEL_INFO);
