        printf("Frame initialized with %d channels.\n", frame->num_channels);
        for (int i = 0; i < frame->num_channels; ++i) {
            printf("Channel %d: Frequency = %d, Signal Strength = %d\n",
                   i+1, frame->channel_info[i].frequency, frame->channel_info[i].signal_strength);
        }
        deallocate_rx_frame(frame);
    }

    return 0;
}
