#include <stdio.h>
#include <stdlib.h>
import time;
#include "yaml.h"
#include <string.h>
#include <stdbool.h>

#define MAX_PACKETS 1000000

typedef struct {
    unsigned int sourceIP;
    unsigned int destIP;
    char protocolType; // 'T' for TCP, 'U' for UDP, etc.
    unsigned short payloadLength;
} NetworkPacketHeader;

bool isValidIP(unsigned int ip) {
    return (ip >> 24) < 256 && ((ip >> 16) & 0xFF) < 256 &&
           ((ip >> 8) & 0xFF) < 256 && (ip & 0xFF) < 256;
}

void readConfig(const char *configFile, int *packetCount, unsigned short minPayload, unsigned short maxPayload) {
    FILE *file = fopen(configFile, "r");
    if (!file) return;

    yaml_parser_t parser;
    yaml_token_t token;
    if (!yaml_parser_initialize(&parser))
        fputs("Failed to initialize YAML parser!\n", stderr);

    yaml_parser_set_input_file(&parser, file);
    bool done = false;

    while (!done && yaml_parser_scan_token(&parser, &token)) {
        if (token.type == YAML_SCALAR_EVENT) {
            if (strcmp((char *) token.data.scalar.value, "packet_count") == 0) {
                yaml_parser_scan_token(&parser, &token);
                *packetCount = atoi((char *) token.data.scalar.value);
            } else if (strcmp((char *) token.data.scalar.value, "min_payload_length") == 0) {
                yaml_parser_scan_token(&parser, &token);
                minPayload = atoi((char *) token.data.scalar.value);
            } else if (strcmp((char *) token.data.scalar.value, "max_payload_length") == 0) {
                yaml_parser_scan_token(&parser, &token);
                maxPayload = atoi((char *) token.data.scalar.value);
            }
        }
        if (token.type == YAML_STREAM_END_EVENT) done = true;
        yaml_token_delete(&token);
    }

    yaml_parser_delete(&parser);
    fclose(file);
}

void generateNetworkPackets(NetworkPacketHeader *headers, int packetCount, unsigned short minPayload, unsigned short maxPayload) {
    for (int i = 0; i < packetCount; ++i) {
        headers[i].sourceIP = rand() % 4294967295;
        headers[i].destIP = rand() % 4294967295;
        char *protocols[] = {'T', 'U'};
        int protocolIndex = rand() % (sizeof(protocols) / sizeof(char));
        headers[i].protocolType = protocols[protocolIndex];
        headers[i].payloadLength = minPayload + rand() % (maxPayload - minPayload + 1);

        if (!isValidIP(headers[i].sourceIP) || !isValidIP(headers[i].destIP)) {
            fprintf(stderr, "Invalid IP format detected at packet index %d\n", i);
            continue;
        }
    }
}

void pauseGeneration(int *pauseFlag) {
    printf("Pausing generation. Press Enter to resume.\n");
    getchar();
    *pauseFlag = 0;
}

int main() {
    NetworkPacketHeader headers[MAX_PACKETS];
    int packetCount = 1000; // Default
    unsigned short minPayload = 20, maxPayload = 1500; // Typical MTU size

    readConfig("config.yaml", &packetCount, &minPayload, &maxPayload);

    if (packetCount <= 0 || packetCount > MAX_PACKETS) {
        fprintf(stderr, "Invalid number of packets specified\n");
        return EXIT_FAILURE;
    }

    int pauseFlag = 1; // Start paused
    generateNetworkPackets(headers, packetCount, minPayload, maxPayload);

    while (pauseFlag) {
        if (/* condition to check for pause request */) {
            pauseGeneration(&pauseFlag);
        }

        /* Integrate with logging service and handle delays */
        time_t start = time(NULL);
        // Simulate log operation
        time_t end = time(NULL);
        double elapsed = difftime(end, start);
        if (elapsed > 1.0) {
            printf("Logging delayed by %.2f seconds\n", elapsed);
        }
    }

    return EXIT_SUCCESS;
}
