void add_to_dns_cache(const char* hostname) {
    if (dns_cache_count < CACHE_SIZE) {
        strncpy(dns_cache[dns_cache_count].hostname, hostname, MAX_HOSTNAME_LEN - 1);
        dns_cache[dns_cache_count].hostname[MAX_HOSTNAME_LEN - 1] = '\0';
        dns_cache_count++;
    }
}

const char* resolve_dns(const char *hostname) {
    for (int i = 0; i < dns_cache_count; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            return inet_ntoa(*(struct in_addr *)&dns_cache[i].hostname); // Placeholder
        }
    }

    struct hostent *host;
    char ip[INET_ADDRSTRLEN];

    host = gethostbyname(hostname);
    if (host != NULL) {
        strcpy(ip, inet_ntoa(*((struct in_addr *)host->h_addr)));
        add_to_dns_cache(hostname);
        return ip;
    } else {
        perror("DNS resolution failed");
        return NULL;
    }
}

double calculate_average(const char *line, int field_count) {
    double sum = 0.0;
    int num_fields = 2; // Last two numeric fields

    const char* token = strtok(line, ",");
    for (int i = field_count - num_fields; i < field_count; ++i) {
        if (token != NULL) {
            sum += atof(token);
            token = strtok(NULL, ",");
        }
    }

    return (num_fields > 0) ? (sum / num_fields) : 0.0;
}

void process_log_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for random number generation

    char *line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1) {
        int field_count = 0;

        const char* token = strtok(line, ",");
        while (token != NULL) {
            field_count++;
            token = strtok(NULL, ",");
        }

        double average = calculate_average(line, field_count);

        // Allocate and populate NFAPI_CRC_INDICATION_PDU_T
        NFAPI_CRC_INDICATION_PDU_T pdu;
        memcpy(pdu.RNTI, (uint8_t[]){rand() % 256, rand() % 256}, 2);
        pdu.CRCFLAG = get_random_crcflag();

        // Example: Print the fields for demonstration purposes
        printf("RNTI: %.2x%.2x, CRCFLAG: %u, Average: %.2f\n",
               pdu.RNTI[0], pdu.RNTI[1], pdu.CRCFLAG, average);

        // Optionally resolve a DNS entry from the line (e.g., last field)
        token = strtok(line, ",");
        for (int i = 0; i < field_count - 2 && token != NULL; ++i) {
            token = strtok(NULL, ",");
        }

        if (token != NULL && strlen(token) > 0) {
            const char *ip_address = resolve_dns(token);
            if (ip_address) {
                printf("Resolved IP: %s\n", ip_address);
            }
        }
    }

    free(line);
    fclose(file);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_log_file(argv[1]);

    return EXIT_SUCCESS;
}
