    int numSymbols;
    int otherParameter;
} PDCCH_CONFIG;

typedef struct {
    PHICH_CONFIG phichConfig;
    void *pdcchSymbolsBuffer;  // Dynamically allocated buffer
    int bufferSize;
} LTE_PHY_TX_FRAME_INFO_T;

// Function to initialize and populate array of LTE_PHY_TX_FRAME_INFO_T structures
void initLTEPHYTXFrameInfo(LTE_PHY_TX_FRAME_INFO_T *frameArray, size_t numFrames, PDCCH_CONFIG pdcchConfig) {
    if (!frameArray || !pdcchConfig.numSymbols) {
        return; // Validate inputs to prevent unexpected behavior
    }

    size_t symbolSize = sizeof(int);  // Assuming each symbol is of type int for this example
    pthread_t threads[4]; // Assume 4 threads for parallel allocation, adjust as needed

    void *threadArg[4];
    size_t framesPerThread = numFrames / 4;
    size_t remainingFrames = numFrames % 4;

    auto allocateBufferForFrame = [&](size_t startIdx, size_t endIdx) {
        for (size_t i = startIdx; i < endIdx; ++i) {
            LTE_PHY_TX_FRAME_INFO_T *frame = &frameArray[i];

            // Initialize PHICH_CONFIG
            frame->phichConfig.parameter1 = 0;  // Example initialization
            frame->phichConfig.parameter2 = 1;

            // Allocate buffer for PDCCH_SYMBOLS based on pdcchConfig.numSymbols
            frame->bufferSize = pdcchConfig.numSymbols * symbolSize;
            frame->pdcchSymbolsBuffer = malloc(frame->bufferSize);
            if (!frame->pdcchSymbolsBuffer) {
                // Handle memory allocation failure
                for (size_t j = 0; j < i; ++j) {
                    free(frameArray[j].pdcchSymbolsBuffer);  // Release previously allocated resources
                }
                return;
            }

            memset(frame->pdcchSymbolsBuffer, 0, frame->bufferSize);  // Initialize the buffer
        }
    };

    for (int t = 0; t < 4; ++t) {
        size_t startIdx = t * framesPerThread;
        size_t endIdx = (t + 1) * framesPerThread;

        if (t == 3) { // Handle remaining frames in the last thread
            endIdx += remainingFrames;
        }

        threadArg[t] = malloc(sizeof(size_t) * 2);
        *(size_t *)threadArg[t] = startIdx;
        *((size_t *)threadArg[t] + 1) = endIdx;

        pthread_create(&threads[t], NULL, (void *(*)(void *))allocateBufferForFrame, threadArg[t]);
    }

    for (int t = 0; t < 4; ++t) {
        void *status;
        pthread_join(threads[t], &status);
        free(threadArg[t]);  // Free allocated memory for thread arguments
    }
}

// Usage example:
// PDCCH_CONFIG pdcchConfig = { .numSymbols = 10, ... };
// LTE_PHY_TX_FRAME_INFO_T frameArray[100];
// initLTEPHYTXFrameInfo(frameArray, 100, pdcchConfig);
