}

int validate_no_duplicate_rnti(ThreadSafeList* list) {
    Node* current;
    for (current = list->head; current != NULL; current = current->next) {
        Node* runner;
        for (runner = current->next; runner != NULL; runner = runner->next) {
            if (runner->data.RNTI == current->data.RNTI) {
                return 0; // Duplicate found
            }
        }
    }
    return 1; // No duplicates
}

void add_element(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = element;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->element_count++;

    // Notify subscribers
    Subscriber* subscriber = subscribers_head;
    while (subscriber) {
        pthread_mutex_lock(&subscriber->subscriber_lock);
        if (subscriber->callback) {
            subscriber->callback(&new_node->data);
        }
        pthread_mutex_unlock(&subscriber->subscriber_lock);
        subscriber = subscriber->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void subscribe(NotificationCallback callback) {
    Subscriber* new_subscriber = (Subscriber*)malloc(sizeof(Subscriber));
