    new_subscriber->callback = callback;
    pthread_mutex_init(&new_subscriber->subscriber_lock, NULL);

    pthread_mutex_lock(&nfa_list.lock);
    new_subscriber->next = subscribers_head;
    subscribers_head = new_subscriber;
    pthread_mutex_unlock(&nfa_list.lock);
