            current->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            current->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

            // Notify subscribers
            Subscriber* subscriber = subscribers_head;
            while (subscriber) {
                pthread_mutex_lock(&subscriber->subscriber_lock);
                if (subscriber->callback) {
                    subscriber->callback(&current->data);
                }
                pthread_mutex_unlock(&subscriber->subscriber_lock);
                subscriber = subscriber->next;
            }

            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&nfa_list.lock);
}

void free_list(ThreadSafeList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    list->head = NULL;
    pthread_mutex_destroy(&list->lock);

    // Free subscribers
    Subscriber* subscriber = subscribers_head;
    while (subscriber) {
        Subscriber* next_subscriber = subscriber->next;
        pthread_mutex_unlock(&subscriber->subscriber_lock);
        pthread_mutex_destroy(&subscriber->subscriber_lock);
        free(subscriber);
        subscriber = next_subscriber;
    }
