#include <time.h>

#define RNTI_MIN 1
#define RNTI_MAX 10000

typedef struct {
    int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    uint32_t value;
    struct Node* next;
} Node;

Node* create_node(uint32_t value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->value = value;
    newNode->next = NULL;
    return newNode;
}

bool insert_hash_table(Node** table, uint32_t tag, size_t hash_size) {
    size_t index = tag % hash_size;
    Node* head = table[index];
    while (head != NULL) {
        if (head->value == tag) return false; // Duplicate found
        head = head->next;
    }
    Node* newNode = create_node(tag);
    if (!newNode) return false;
    newNode->next = table[index];
    table[index] = newNode;
    return true;
}

bool check_hash_table(Node** table, uint32_t tag, size_t hash_size) {
    size_t index = tag % hash_size;
    Node* head = table[index];
    while (head != NULL) {
        if (head->value == tag) return true; // Duplicate found
        head = head->next;
    }
    return false;
}

void free_hash_table(Node** table, size_t hash_size) {
    for (size_t i = 0; i < hash_size; ++i) {
        Node* head = table[i];
        while (head != NULL) {
            Node* temp = head;
            head = head->next;
            free(temp);
        }
    }
}

bool generate_unique_rnti(uint16_t* rnti, const uint16_t* existing_rntis, size_t existing_count) {
    bool found = false;
    while (!found) {
        *rnti = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
        found = true;
        for (size_t i = 0; i < existing_count && found; ++i) {
            if (*rnti == existing_rntis[i]) found = false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* manage_nfa_crc_indication_pdu(size_t N, const uint16_t* existing_rntis, size_t existing_count, bool (*get_unique_tag)(uint32_t*)) {
    if (N == 0) return NULL;

    size_t hash_size = N * 2; // Simple heuristic for hash table sizing
    Node** tag_table = (Node**)calloc(hash_size, sizeof(Node*));
    if (!tag_table) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        free(tag_table);
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < N; ++i) {
        uint32_t tag;
        if (!get_unique_tag(&tag)) {
            free(array);
            free_hash_table(tag_table, hash_size);
            return NULL;
        }

        while (!insert_hash_table(tag_table, tag, hash_size));

        array[i].RX_UE_INFORMATION_TAG = tag;

        if (!generate_unique_rnti(&array[i].RNTI, existing_rntis, existing_count)) {
            free(array);
            free_hash_table(tag_table, hash_size);
            return NULL;
        }

        array[i].CRC_INDICATION_REL8_TAG.crcFlag = rand() % 2; // Randomly set crcFlag to 0 or 1
    }

    free(tag_table);

    return array;
}

bool generate_unique_tag(uint32_t* tag) {
    static uint32_t current_tag = 0;
    *tag = ++current_tag;
    return true;
}

void free_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    if (array) free(array);
}
