} NFAPI_CRC_INDICATION_PDU_T;

// Assume valid tags are provided in this array and its size
extern const RX_UE_INFORMATION_TAG* valid_tags[];
extern int num_valid_tags;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned char seed_value;

int validate_tag(RX_UE_INFORMATION_TAG tag) {
    for (int i = 0; i < num_valid_tags; ++i) {
        if (memcmp(&tag, &valid_tags[i], sizeof(tag)) == 0) {
            return 1;
        }
    }
    return 0;
}

unsigned char generate_crc_flag(unsigned int seed) {
    srand(seed);
    return rand() & CRCFLAG_MASK;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_list(size_t num_elements, unsigned int seed, size_t *allocated_size) {
    if (num_elements == 0 || allocated_size == NULL)
        return NULL;

    pthread_mutex_lock(&list_mutex);

    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_size = num_elements * element_size;

    if (total_size > MAX_SIZE_BYTES) {
        fprintf(stderr, "Error: Total list size exceeds maximum allowed bytes\n");
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(total_size);
    if (!list) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    *allocated_size = total_size;

    for (size_t i = 0; i < num_elements; ++i) {
        RX_UE_INFORMATION_TAG tag = { .valid_tag = rand() % 100 }; // Example random generation
        if (!validate_tag(tag)) {
            fprintf(stderr, "Error: Invalid RX_UE_INFORMATION_TAG encountered\n");
            free(list);
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        list[i].rx_ue_information_tag = tag;

        // Generate a random RNTI; assuming it's 16 bits
        list[i].rnti = rand() % (1 << 16);

        time_t now;
        clock_gettime(CLOCK_REALTIME, (struct timespec*)&now);
        list[i].crc_indication_rel8_tag.timestamp = now.tv_sec + (now.tv_nsec / 1000000.0);

        list[i].CRCFLAG = generate_crc_flag(seed_value);
    }

    pthread_mutex_unlock(&list_mutex);
    return list;
}

void free_nfa_pi_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list)
        free(list);
}
