```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_INSTANCES 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
} PoolNode;

typedef struct {
    PoolNode* head;
    int size;
    pthread_mutex_t lock;
    int successful_allocations;
    int failed_attempts;
} CRC_POOL;

CRC_POOL crc_pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, 0, 0};

void initialize_pool(int N) {
    pthread_mutex_lock(&crc_pool.lock);
    if (crc_pool.size == 0) {
        crc_pool.head = (PoolNode*)malloc(N * sizeof(PoolNode));
        for (int i = 0; i < N; ++i) {
            PoolNode* node = &crc_pool.head[i];
            node->data.RX_UE_INFORMATION_TAG = rand() % 256;
            node->data.RNTI = rand() % 4096;
            node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;
            node->next = (i < N - 1) ? &crc_pool.head[i + 1] : NULL;
        }
        crc_pool.size = N;
    }
    pthread_mutex_unlock(&crc_pool.lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&crc_pool.lock);

    if (crc_pool.head != NULL) {
        PoolNode* node = crc_pool.head;
        crc_pool.head = node->next;

        if (--crc_pool.size == 0) {
            free(crc_pool.head);
            crc_pool.head = NULL;
        }

        ++crc_pool.successful_allocations;
        pthread_mutex_unlock(&crc_pool.lock);

        return &node->data;
    } else {
        ++crc_pool.failed_attempts;
        pthread_mutex_unlock(&crc_pool.lock);
        return NULL;
    }
}

void release_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    PoolNode node = {.next = crc_pool.head};
    memcpy(&node.data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&crc_pool.lock);

    node.next = crc_pool.head;
    crc_pool.head = &node;

    if (++crc_pool.size == 1) {
        PoolNode* nodes = (PoolNode*)malloc(crc_pool.size * sizeof(PoolNode));
        memcpy(nodes, &node, sizeof(PoolNode));

        for (int i = 1; i < crc_pool.size; ++i) {
            nodes[i].next = (i == crc_pool.size - 1) ? NULL : &nodes[i + 1];
        }

        free(crc_pool.head);
        crc_pool.head = nodes;
    }

    pthread_mutex_unlock(&crc_pool.lock);
}

void log_metrics() {
    double usage_percentage = ((double)(MAX_UE_INSTANCES - crc_pool.size) / MAX_UE_INSTANCES) * 100.0;

    printf("Successful Allocations: %d\n", crc_pool.successful_allocations);
    printf("Failed Attempts: %d\n", crc_pool.failed_attempts);
    printf("Pool Usage Percentage: %.2f%%\n", usage_percentage);
}

int main() {
    srand(time(NULL));
    initialize_pool(MAX_UE_INSTANCES);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu();
    if (pdu) {
        // Use the pdu...
        release_pdu(pdu);
    }

    log_metrics();

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for synchronization.
- **Pool Management**: Initializes a fixed-size pool and manages allocation/release efficiently.
- **Metrics Monitoring**: Tracks successful allocations, failed attempts, and pool usage percentage.
- **Random Data Initialization**: Sets random values for each structure's fields during initialization.']

