#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_BANDWIDTH 1000 // Example constraint
#define MIN_LATENCY_TOLERANCE 10
#define MAX_QOS_PRIORITY 5

typedef struct {
    int bandwidth;
    int latency_tolerance;
    int qos_priority;
} NetworkConfig;

typedef struct {
    NetworkConfig *configs;
    size_t count;
    pthread_mutex_t lock;
} ConfigArray;

int validate_config(int bandwidth, int latency_tolerance, int qos_priority) {
    return (bandwidth > 0 && bandwidth <= MAX_BANDWIDTH &&
            latency_tolerance >= MIN_LATENCY_TOLERANCE &&
            qos_priority >= 1 && qos_priority <= MAX_QOS_PRIORITY);
}

ConfigArray* init_config_array() {
    ConfigArray *array = malloc(sizeof(ConfigArray));
    if (!array) return NULL;
    array->configs = NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int add_network_config(ConfigArray *array, int bandwidth, int latency_tolerance, int qos_priority) {
    if (!validate_config(bandwidth, latency_tolerance, qos_priority)) return -1;

    pthread_mutex_lock(&array->lock);
    size_t new_count = array->count + 1;
    NetworkConfig *new_configs = realloc(array->configs, new_count * sizeof(NetworkConfig));
    if (!new_configs) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Memory allocation failed
    }

    new_configs[array->count].bandwidth = bandwidth;
    new_configs[array->count].latency_tolerance = latency_tolerance;
    new_configs[array->count].qos_priority = qos_priority;

    array->configs = new_configs;
    array->count = new_count;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
