    NFAPI_CRC_INDICATION_PDU data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t count;
    pthread_mutex_t lock;
    size_t total_memory_used;
} LinkedList;

LinkedList* init_linked_list() {
    LinkedList *list = malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->total_memory_used = 0;
    return list;
}

int add_crc_indication_pdu(LinkedList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (RX_UE_INFORMATION_TAG <= 0 || RNTI <= 0 || CRC_INDICATION_REL8_TAG <= 0) return -1;

    pthread_mutex_lock(&list->lock);
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    srand(time(NULL));
    new_node->data.CRCFLAG = rand() % 2;

    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    list->total_memory_used += sizeof(Node);

    printf("PDU added successfully. Total memory used: %zu bytes\n", list->total_memory_used);
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_linked_list(LinkedList *list) {
    if (list) {
        Node *current = list->head;
        while (current) {
            Node *next = current->next;
            free(current);
            list->total_memory_used -= sizeof(Node);
            current = next;
        }
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}
