#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int user_id;
    char *payload; // Optional payload field, could be NULL if not used.
} Message;

typedef struct {
    Message **messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageArray;

// Initialize the dynamic array
void initMessageArray(MessageArray *array) {
    array->messages = malloc(10 * sizeof(Message*));
    if (!array->messages) exit(EXIT_FAILURE);
    array->count = 0;
    array->capacity = 10;
    pthread_mutex_init(&array->lock, NULL);
}

// Resize the dynamic array
void resizeMessageArray(MessageArray *array) {
    size_t new_capacity = array->capacity * 2;
    Message **new_messages = realloc(array->messages, new_capacity * sizeof(Message*));
    if (!new_messages) exit(EXIT_FAILURE);
    array->messages = new_messages;
    array->capacity = new_capacity;
}

// Add a new message
void addMessage(MessageArray *array, time_t timestamp, int user_id, const char *payload_data) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) resizeMessageArray(array);

    Message *msg = malloc(sizeof(Message));
    if (!msg) exit(EXIT_FAILURE);
    msg->timestamp = timestamp;
    msg->user_id = user_id;
    msg->payload = payload_data ? strdup(payload_data) : NULL;

    array->messages[array->count++] = msg;

    pthread_mutex_unlock(&array->lock);
}

// Update an existing message by user identifier
void updateMessage(MessageArray *array, int user_id, const char *new_payload) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i]->user_id == user_id) {
            free(array->messages[i]->payload);
            array->messages[i]->payload = new_payload ? strdup(new_payload) : NULL;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

// Retrieve messages within a specified time range
MessageArray *retrieveMessages(MessageArray *array, time_t start_time, time_t end_time) {
    MessageArray *result = malloc(sizeof(MessageArray));
    if (!result) exit(EXIT_FAILURE);
    initMessageArray(result);

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i]->timestamp >= start_time && array->messages[i]->timestamp <= end_time) {
            addMessage(result, array->messages[i]->timestamp, array->messages[i]->user_id,
                       array->messages[i]->payload);
        }
    }

    pthread_mutex_unlock(&array->lock);

    return result;
}

// Delete a message by user identifier
void deleteMessage(MessageArray *array, int user_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i]->user_id == user_id) {
            free(array->messages[i]->payload);
            free(array->messages[i]);
            memmove(&array->messages[i], &array->messages[i + 1],
                    (array->count - i - 1) * sizeof(Message*));
            --array->count;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

// Free the dynamic array
void freeMessageArray(MessageArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->messages[i]->payload);
        free(array->messages[i]);
    }
    free(array->messages);

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Logging function
void logOperation(const char *operation) {
    FILE *log_file = fopen("operations.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] %s\n", ctime(&now), operation);
        fclose(log_file);
    }
}

// Example usage
int main() {
    MessageArray array;
    initMessageArray(&array);

    addMessage(&array, time(NULL), 1, "Hello World");
    updateMessage(&array, 1, "Updated Hello World");

    MessageArray *retrieved = retrieveMessages(&array, time(NULL) - 60, time(NULL));
    // Use retrieved messages...
    freeMessageArray(retrieved);

    deleteMessage(&array, 1);
    freeMessageArray(&array);

    return 0;
}
```

