#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define BUFFER_SIZE 1024
#define MAX_STRUCTS_TO_KEEP 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} RingBuffer;

typedef struct {
    double maxWeightedSum;
    int transactionID;
} Metrics;

void initRingBuffer(RingBuffer* buffer) {
    buffer->head = NULL;
    buffer->tail = NULL;
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);
}

bool addStructure(RingBuffer* buffer, NFAPI_CRC_INDICATION_PDU_T structure) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return false;

    newNode->data = structure;
    newNode->timestamp = time(NULL);
    newNode->next = NULL;

    pthread_mutex_lock(&buffer->lock);

    if (buffer->tail) {
        buffer->tail->next = newNode;
    } else {
        buffer->head = newNode;
    }
    buffer->tail = newNode;
    buffer->count++;

    // Evict old structures
    time_t currentTime = time(NULL);
    Node* current = buffer->head;
    while (current && (currentTime - current->timestamp > 3 || buffer->count > MAX_STRUCTS_TO_KEEP)) {
        Node* temp = current;
        current = current->next;
        free(temp);
        if (buffer->head == temp) {
            buffer->head = current;
        }
        buffer->count--;
    }

    pthread_mutex_unlock(&buffer->lock);
    return true;
}

bool processStructures(RingBuffer* buffer, Metrics* metrics) {
    pthread_mutex_lock(&buffer->lock);

    double weightedSum = 0.0;
    int transactionID = -1;

    Node* current = buffer->head;
    while (current) {
        // Example weight calculation: consider CRCFLAG and other fields
        double weight = (current->data.CRCFLAG ? 2.0 : 1.0);
        if (weight > weightedSum) {
            weightedSum = weight;
            transactionID = current->data.RNTI; // Assuming RNTI as transaction ID
        }
        current = current->next;
    }

    metrics->maxWeightedSum = weightedSum;
    metrics->transactionID = transactionID;

    pthread_mutex_unlock(&buffer->lock);
    return true;
}

bool manageNFAPICRCIndications(RingBuffer* buffer, NFAPI_CRC_INDICATION_PDU_T* incomingStructures, size_t numStructures) {
    for (size_t i = 0; i < numStructures; ++i) {
        if (!addStructure(buffer, incomingStructures[i])) {
            return false;
        }
    }

    Metrics metrics = { .maxWeightedSum = 0.0, .transactionID = -1 };
    processStructures(buffer, &metrics);

    printf("Max Weighted Sum: %f\n", metrics.maxWeightedSum);
    printf("Transaction ID: %d\n", metrics.transactionID);

    return true;
}
