#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit: 1MB

typedef struct {
    int crc_value;
    // Add other necessary fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRCArrayManager;

// Error logging mechanism
void log_error(const char* message) {
    // Log errors efficiently, e.g., write to a file or console without blocking
    fprintf(stderr, "Error: %s\n", message);
}

CRCArrayManager* initialize_crc_array_manager(size_t initial_capacity) {
    if (initial_capacity == 0 || (size_t)(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity) > MAX_MEMORY_LIMIT) {
        log_error("Invalid initial capacity");
        return NULL;
    }

    CRCArrayManager* manager = malloc(sizeof(CRCArrayManager));
    if (!manager) {
        log_error("Memory allocation failed for manager");
        return NULL;
    }

    manager->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        log_error("Memory allocation failed for array");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    manager->capacity = initial_capacity;
    manager->count = 0;

    return manager;
}

int add_crc_pdu(CRCArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!manager || manager->count >= manager->capacity) {
        log_error("Failed to add CRC PDU: Manager is NULL or full");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    // Check memory limit before allocation
    size_t required_memory = (manager->count + 2) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory > MAX_MEMORY_LIMIT || required_memory > manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_error("Memory limit exceeded");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Resize array if necessary
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            pthread_mutex_unlock(&manager->lock);
            log_error("Memory reallocation failed");
            return -1;
        }
        manager->array = temp_array;
        manager->capacity = new_capacity;
    }

    manager->array[manager->count] = pdu;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void free_crc_array_manager(CRCArrayManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
