#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

// Define the data structures

typedef struct {
    uint32_t rSRP;
    uint32_t SINR;
    uint64_t throughput;
} MobilityMetrics;

typedef struct {
    uint32_t ue_id;
    uint32_t mme_id;
    MobilityMetrics metrics;
} UE_STATUS_REPORT;

typedef struct Node {
    UE_STATUS_REPORT data;
    _Atomic int priority_score; // Atomic for thread-safe priority score updates
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock; // For ensuring data consistency across threads
} LinkedList;

// Function prototypes

void init_list(LinkedList* list);
void destroy_list(LinkedList* list);
int fetch_data_from_db_and_update_list(LinkedList* list);  // Simulates fetching and updating
void filter_and_prioritize_messages(LinkedList* list, int N, UE_STATUS_REPORT** topN_reports, int* scores);

// Function implementations

void init_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    pthread_mutex_destroy(&list->lock);
}

int fetch_data_from_db_and_update_list(LinkedList* list) {
    // Simulate fetching data and updating the list
    pthread_mutex_lock(&list->lock);

    UE_STATUS_REPORT sample_report = { .ue_id = 1, .mme_id = 101, .metrics = {100, 20, 500}};
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error in allocation
    }

    new_node->data = sample_report;
    atomic_store(&new_node->priority_score, 10); // Set an initial priority score
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void filter_and_prioritize_messages(LinkedList* list, int N, UE_STATUS_REPORT** topN_reports, int* scores) {
    Node* current = list->head;
    while (current != NULL) {
        int priority = atomic_load(&current->priority_score);

        // Implement complex filtering logic here
        if (current->data.metrics.rSRP < 50 || current->data.metrics.SINR < 10) {
            priority += 5; // Increase priority based on criteria
        }
        atomic_store(&current->priority_score, priority);

        current = current->next;
    }

    // Collect top N reports with highest priorities
    pthread_mutex_lock(&list->lock);

    Node** sorted_nodes = (Node**)malloc(N * sizeof(Node*));
    if (!sorted_nodes) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle allocation failure appropriately
    }

    int collected = 0;
    current = list->head;
    while (current != NULL && collected < N) {
        sorted_nodes[collected] = current;
        current = current->next;
        collected++;
    }

    for (int i = 0; i < collected; ++i) {
        for (int j = i + 1; j < collected; ++j) {
            if (atomic_load(&sorted_nodes[i]->priority_score) < atomic_load(&sorted_nodes[j]->priority_score)) {
                Node* temp = sorted_nodes[i];
                sorted_nodes[i] = sorted_nodes[j];
                sorted_nodes[j] = temp;
            }
        }
    }

    for (int i = 0; i < N && i < collected; ++i) {
        topN_reports[i] = &sorted_nodes[i]->data;
        scores[i] = atomic_load(&sorted_nodes[i]->priority_score);
    }

    free(sorted_nodes);
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    LinkedList list;
    init_list(&list);

    int fetch_status = fetch_data_from_db_and_update_list(&list);
    if (fetch_status != 0) {
        fprintf(stderr, "Failed to fetch data\n");
        return EXIT_FAILURE;
    }

    UE_STATUS_REPORT* top_reports[10];
    int priority_scores[10];

    filter_and_prioritize_messages(&list, 10, top_reports, priority_scores);

    for (int i = 0; i < 10 && top_reports[i]; ++i) {
        printf("UE_ID: %u, MME_ID: %u, Priority Score: %d\n", 
               top_reports[i]->ue_id, top_reports[i]->mme_id, priority_scores[i]);
    }

    destroy_list(&list);
    return EXIT_SUCCESS;
}
