    size_t tail;
    size_t count;
    pthread_mutex_t lock;
} RingBuffer;

typedef struct {
    int max_weighted_sum;
    int transaction_id;
} Metrics;

void init_ring_buffer(RingBuffer *rb) {
    rb->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(BUFFER_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    pthread_mutex_init(&rb->lock, NULL);
}

bool enqueue(RingBuffer *rb, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&rb->lock);
    if (rb->count == BUFFER_SIZE) {
        pthread_mutex_unlock(&rb->lock);
        return false; // Buffer overflow
    }
    rb->data[rb->tail] = item;
    rb->tail = (rb->tail + 1) % BUFFER_SIZE;
    rb->count++;
    pthread_mutex_unlock(&rb->lock);
    return true;
}

bool dequeue(RingBuffer *rb, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&rb->lock);
    if (rb->count == 0) {
        pthread_mutex_unlock(&rb->lock);
        return false; // Buffer underflow
    }
    *item = rb->data[rb->head];
    rb->head = (rb->head + 1) % BUFFER_SIZE;
    rb->count--;
    pthread_mutex_unlock(&rb->lock);
    return true;
}

void process_data(RingBuffer *rb, Metrics *metrics) {
    time_t current_time = time(NULL);
    size_t window_start_index = (rb->tail - WINDOW_SIZE * BUFFER_SIZE / 3 + BUFFER_SIZE) % BUFFER_SIZE;

    pthread_mutex_lock(&rb->lock);

    for (size_t i = rb->head; i != window_start_index;) {
        NFAPI_CRC_INDICATION_PDU_T item;
        if (!dequeue(rb, &item)) break;

        int weight = item.RX_UE_INFORMATION_TAG + item.RNTI + (item.CRCFLAG ? 1 : 0);
        if (weight > metrics->max_weighted_sum) {
            metrics->max_weighted_sum = weight;
            metrics->transaction_id = i; // Example transaction ID
        }

        enqueue(rb, item); // Re-enqueue to maintain buffer state

        i = (i + 1) % BUFFER_SIZE;
    }

    pthread_mutex_unlock(&rb->lock);
}

void find_largest_in_array(int *arr, size_t len) {
    int largest = arr[0];
    for (size_t i = 1; i < len; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

bool manage_nfa_data() {
    RingBuffer rb;
    Metrics metrics = {0, -1};
    init_ring_buffer(&rb);

    // Simulate data input and processing
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T new_data;
        if (!enqueue(&rb, new_data)) {
            break; // Handle buffer overflow
        }
        process_data(&rb, &metrics);
    }

    // Read integers from standard input
    int numbers[100];
    size_t count = 0;
    while (scanf("%d", &numbers[count]) == 1 && count < 100) {
        count++;
    }
    find_largest_in_array(numbers, count);

    free(rb.data);
    pthread_mutex_destroy(&rb.lock);

    return true; // Indicate successful completion
}

int main() {
    if (manage_nfa_data()) {
        printf("Data managed successfully.\n");
    } else {
        printf("Failed to manage data.\n");
    }
    return 0;
}
