} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRCArrayManager;

void init_crc_array_manager(CRCArrayManager *manager, size_t initial_capacity) {
    manager->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void free_crc_array_manager(CRCArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->data);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int add_element(CRCArrayManager *manager, uint16_t rx_ue_info_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->data = new_data;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &manager->data[manager->count++];
    element->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG = crc_indication_rel8_tag;

    // Randomly set CRCFLAG
    srand(time(NULL) + rand());  // Seed with time and previous random number
    uint8_t crcflag = rand() % 2;  // Simulate a flag as part of the struct

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int serialize_crc_array(const CRCArrayManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t written = fwrite(manager->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->count, file);
    fclose(file);

    if (written != manager->count) {
        perror("Failed to write all elements");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int deserialize_crc_array(CRCArrayManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t count = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (count > manager->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->data, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory");
            fclose(file);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->data = new_data;
        manager->capacity = count;
    }

    size_t read = fread(manager->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    if (read != count) {
        perror("Failed to read all elements");
        fclose(file);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    manager->count = count;

    fclose(file);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}
