Node* populate_linked_list(size_t max_count, double crc_probability, const UE_Info* external_data[], size_t data_size) {
    if (!external_data || !data_size || crc_probability < 0.0 || crc_probability > 1.0) return NULL;

    Node* head = NULL;
    Node** current = &head;
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < data_size && max_count > 0; ++i) {
        if (!is_valid_ue_info(external_data[i])) continue;

        bool crc_flag = (rand() / (double)RAND_MAX) < crc_probability;
        Node* new_node = create_node(external_data[i], crc_flag);

        if (!new_node) {
            // Clean up on memory allocation failure
            while (head) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        *current = new_node;
        current = &(*current)->next;
        max_count--;
    }

    return head;
}

void free_linked_list(Node* head) {
    while (head) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}
