// Shuffle the array using Fisher-Yates algorithm
void shuffle_dynamic_array(DynamicArray* dyn_array) {
    pthread_mutex_lock(&dyn_array->mutex);
    for (size_t i = dyn_array->count - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        NFAPI_CRC_INDICATION_PDU_T temp = dyn_array->array[i];
        dyn_array->array[i] = dyn_array->array[j];
        dyn_array->array[j] = temp;
    }
    pthread_mutex_unlock(&dyn_array->mutex);
}

