#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <stdio.h>

#define INITIAL_CAPACITY 1000

typedef struct {
    uint32_t rnti;
    // Add other fields as necessary for RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t capacity;
    pthread_mutex_t lock;
    bool initialized;
} RNTIHashTable;

RNTIHashTable* createHashTable(size_t capacity) {
    RNTIHashTable* hashTable = (RNTIHashTable*)malloc(sizeof(RNTIHashTable));
    if (!hashTable) return NULL;

    hashTable->capacity = capacity;
    hashTable->table = (Node**)calloc(capacity, sizeof(Node*));
    pthread_mutex_init(&hashTable->lock, NULL);
    hashTable->initialized = true;

    return hashTable;
}

void freeHashTable(RNTIHashTable* hashTable) {
    if (!hashTable || !hashTable->initialized) return;

    for (size_t i = 0; i < hashTable->capacity; ++i) {
        Node* node = hashTable->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    pthread_mutex_destroy(&hashTable->lock);
    free(hashTable->table);
    free(hashTable);
}

size_t hashFunction(uint32_t rnti, size_t capacity) {
    return rnti % capacity;
}

bool addPDU(RNTIHashTable* hashTable, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!hashTable || !hashTable->initialized) return false;

    pthread_mutex_lock(&hashTable->lock);

    size_t index = hashFunction(pdu.rnti, hashTable->capacity);
    Node* node = hashTable->table[index];

    while (node) {
        if (node->data.rnti == pdu.rnti) {
            printf("Duplicate RNTI detected: %u\n", pdu.rnti);
            pthread_mutex_unlock(&hashTable->lock);
            return false;
        }
        node = node->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&hashTable->lock);
        return false;
    }

    newNode->data = pdu;
    newNode->next = hashTable->table[index];
    hashTable->table[index] = newNode;

    pthread_mutex_unlock(&hashTable->lock);
    return true;
}

void resizeHashTable(RNTIHashTable* hashTable, size_t newCapacity) {
    if (!hashTable || !hashTable->initialized) return;

    Node** oldTable = hashTable->table;
    size_t oldCapacity = hashTable->capacity;

    hashTable->capacity = newCapacity;
    hashTable->table = (Node**)calloc(newCapacity, sizeof(Node*));

    for (size_t i = 0; i < oldCapacity; ++i) {
        Node* node = oldTable[i];
        while (node) {
            Node* nextNode = node->next;

            size_t newIndex = hashFunction(node->data.rnti, newCapacity);
            node->next = hashTable->table[newIndex];
            hashTable->table[newIndex] = node;

            node = nextNode;
        }
    }

    free(oldTable);
}

void manageNFAPIList() {
    RNTIHashTable* hashTable = createHashTable(INITIAL_CAPACITY);

    if (!hashTable) {
        fprintf(stderr, "Failed to initialize hash table\n");
        return;
    }

    // Simulate adding PDUs
    for (int i = 0; i < 2000; ++i) {  // Example loop count, adjust as necessary
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rnti = rand() % 10000;  // Simulated RNTI assignment

        if (!addPDU(hashTable, pdu)) {
            fprintf(stderr, "Failed to add PDU with RNTI: %u\n", pdu.rnti);
            continue;
        }

        if (i > INITIAL_CAPACITY && i % 500 == 0) {  // Example condition for resizing
            resizeHashTable(hashTable, hashTable->capacity * 2);
        }
    }

    freeHashTable(hashTable);
}
