#define MAX_RETRIES 3

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    pthread_mutex_t lock;
} ManagedArray;

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t size, int *retry_count) {
    for (*retry_count = 0; *retry_count < MAX_RETRIES; ++(*retry_count)) {
        NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size);
        if (array) {
            return array;
        }
        log_error("Memory allocation failed, retrying...");
    }
    return NULL;
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t count, unsigned int seed) {
    srand(seed);
    for (size_t i = 0; i < count; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand();
    }
}

ManagedArray* create_managed_array(size_t max_elements, unsigned int seed) {
    ManagedArray *managed_array = (ManagedArray *)malloc(sizeof(ManagedArray));
    if (!managed_array) {
        log_error("Failed to allocate ManagedArray");
        return NULL;
    }

    pthread_mutex_init(&managed_array->lock, NULL);
    managed_array->capacity = 0;

    int retry_count;
    managed_array->array = allocate_memory(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T), &retry_count);

    if (!managed_array->array) {
        log_error("Failed to allocate array after retries");
        free(managed_array);
        return NULL;
    }

    populate_array(managed_array->array, max_elements, seed);
    managed_array->capacity = max_elements;

    return managed_array;
}

void destroy_managed_array(ManagedArray *managed_array) {
    if (managed_array) {
        pthread_mutex_lock(&managed_array->lock);
        free(managed_array->array);
        pthread_mutex_unlock(&managed_array->lock);

        pthread_mutex_destroy(&managed_array->lock);
        free(managed_array);
    }
}

// Usage example
int main() {
    size_t max_elements = 1000;
    unsigned int seed = 42;

    ManagedArray *array = create_managed_array(max_elements, seed);
    if (array) {
        // Use the array...

        destroy_managed_array(array);
    }

    return 0;
}
