    // Example logging function
    fprintf(stderr, "Error: %s\n", error_message);
}

DynamicArray* create_dynamic_array(size_t initial_size) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        log_error("Failed to allocate memory for dynamic array.");
        return NULL;
    }

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        log_error("Failed to allocate memory for data array.");
        return NULL;
    }

    array->size = initial_size;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void resize_dynamic_array(DynamicArray* array, size_t new_size) {
    if (!array) return;

    pthread_mutex_lock(&array->mutex);

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log_error("Failed to reallocate memory for data array.");
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    if (new_size > array->size) {
        // Initialize newly allocated elements
        for (size_t i = array->size; i < new_size; ++i) {
            new_data[i].RX_UE_INFORMATION_TAG = rand() % 1000;
            new_data[i].RNTI = rand() % 5000;
            new_data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }
    }

    array->data = new_data;
    array->size = new_size;

    pthread_mutex_unlock(&array->mutex);
}

void update_crc_flag(DynamicArray* array, size_t index) {
    if (!array || index >= array->size) return;

    pthread_mutex_lock(&array->mutex);

    if (index < array->size) {
        array->data[index].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&array->mutex);
}

void free_dynamic_array(DynamicArray* array) {
    if (!array) return;

    pthread_mutex_lock(&array->mutex);

    free(array->data);
    pthread_mutex_unlock(&array->mutex);

    pthread_mutex_destroy(&array->mutex);
    free(array);
}
