    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a memory pool
#define POOL_SIZE 1024
NFAPI_CRC_INDICATION_PDU_T pool[POOL_SIZE];
size_t free_index = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_struct() {
    pthread_mutex_lock(&pool_mutex);
    if (free_index < POOL_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pool[free_index++];
        pdu->RX_UE_INFORMATION_TAG = rand();  // Random value for demonstration
        pdu->RNTI = rand();
        pdu->crc_tag.CRCFLAG = rand() % 2;    // Randomly set CRCFLAG
        pthread_mutex_unlock(&pool_mutex);
        return pdu;
    }
    pthread_mutex_unlock(&pool_mutex);
    return NULL;
}

void serialize_pdu(const char* filename, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    FILE* file = fopen(filename, "ab");
    if (file == NULL) {
        perror("File opening failed");
        return;
    }

    fwrite(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T deserialize_pdu(const char* filename, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("File opening failed");
        return pdu;
    }

    fseek(file, index * sizeof(NFAPI_CRC_INDICATION_PDU_T), SEEK_SET);
    fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    fclose(file);

    return pdu;
}

void log_event(const char* event) {
    FILE* log_file = fopen("nfa_log.txt", "a");
    if (log_file == NULL) {
        perror("Log file opening failed");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), event);
    fclose(log_file);
}

void verify_integrity(const char* filename, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T pdu = deserialize_pdu(filename, index);
    if (pdu.RX_UE_INFORMATION_TAG == 0 || pdu.RNTI == 0) {
        log_event("Data integrity check failed");
    } else {
        log_event("Data integrity verified");
    }
}

void* process_data(void* arg) {
    const char* filename = (const char*)arg;
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_struct();
        if (pdu != NULL) {
            serialize_pdu(filename, pdu);
            verify_integrity(filename, i);
        }
    }
    return NULL;
}

int main() {
    const char* filename = "nfa_data.bin";

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, process_data, (void*)filename);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
