#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int rssi;
    int cqi;
} MeasurementReport;

typedef struct FrameInfo {
    time_t timestamp;
    unsigned int cell_id;
    MeasurementReport *measurements;
    size_t measurement_count;
    struct FrameInfo *next;
} FrameInfo;

typedef struct {
    FrameInfo *head;
    FrameInfo *tail;
    size_t max_size;
    pthread_mutex_t lock;
} CircularBuffer;

// Function to initialize the circular buffer
CircularBuffer* init_circular_buffer(size_t max_size) {
    CircularBuffer *buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!buffer) return NULL;

    buffer->head = buffer->tail = NULL;
    buffer->max_size = max_size;
    pthread_mutex_init(&buffer->lock, NULL);

    return buffer;
}

// Function to add a new frame to the circular buffer
int add_frame(CircularBuffer *buffer, FrameInfo *frame) {
    if (!frame || !buffer) return -1;

    pthread_mutex_lock(&buffer->lock);

    // Allocate memory for measurements
    frame->measurements = (MeasurementReport*)malloc(frame->measurement_count * sizeof(MeasurementReport));
    if (!frame->measurements) {
        pthread_mutex_unlock(&buffer->lock);
        free(frame);
        return -2;  // Memory allocation failure
    }

    if (buffer->head == NULL) {  // First element
        buffer->head = buffer->tail = frame;
        frame->next = NULL;
    } else {
        if ((buffer->tail->next == buffer->head) || (buffer->max_size == 1)) {  // Buffer is full, overwrite the oldest
            FrameInfo *temp = buffer->head;
            buffer->head = buffer->head->next;
            free(temp->measurements);
            free(temp);

            buffer->tail->next = frame;
        } else {
            buffer->tail->next = frame;
        }
        buffer->tail = frame;
        frame->next = (buffer->max_size == 1) ? buffer->head : NULL;  // Manage circular linking
    }

    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

// Function to retrieve and remove the oldest frame from the buffer
FrameInfo* get_oldest_frame(CircularBuffer *buffer) {
    if (!buffer) return NULL;

    pthread_mutex_lock(&buffer->lock);

    if (buffer->head == NULL) {  // Buffer is empty
        pthread_mutex_unlock(&buffer->lock);
        return NULL;
    }

    FrameInfo *frame = buffer->head;
    buffer->head = frame->next;

    if (buffer->head == NULL) {
        buffer->tail = NULL;  // Only one element was in the buffer
    }

    pthread_mutex_unlock(&buffer->lock);

    return frame;
}

// Function to free a FrameInfo structure
void free_frame(FrameInfo *frame) {
    if (!frame) return;

    free(frame->measurements);
    free(frame);
}

// Cleanup function for circular buffer
void destroy_circular_buffer(CircularBuffer *buffer) {
    if (!buffer) return;

    pthread_mutex_lock(&buffer->lock);

    FrameInfo *current = buffer->head;
    while (current != NULL) {
        FrameInfo *next = current->next;
        free_frame(current);
        current = next;
    }

    pthread_mutex_unlock(&buffer->lock);
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
}

int main() {
    // Example usage
    CircularBuffer *buffer = init_circular_buffer(5);

    if (buffer) {
        FrameInfo *frame1 = (FrameInfo*)malloc(sizeof(FrameInfo));
        frame1->timestamp = time(NULL);
        frame1->cell_id = 123;
        frame1->measurement_count = 3;

        add_frame(buffer, frame1);

        // Retrieve and process oldest frame
        FrameInfo *oldest_frame = get_oldest_frame(buffer);
        if (oldest_frame) {
            printf("Processing oldest frame with cell ID: %u\n", oldest_frame->cell_id);
            free_frame(oldest_frame);
        }

        destroy_circular_buffer(buffer);
    }

    return 0;
}
```

This code provides a thread-safe implementation of a circular buffer for `FrameInfo` structures. It ensures robust memory management, handles allocation failures gracefully, and maintains the most recent N frames efficiently in a high-throughput environment.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct CRC_INDICATION_REL8_TAG {
    uint32_t crc_value;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    uint16_t rnti;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crc_flag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Batch {
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t count;
    pthread_mutex_t lock; // Ensure thread safety
} Batch;

// Function prototypes
Batch* create_batch(size_t size, bool crc_flag);
void delete_batch(Batch** batch_ptr);
NFAPI_CRC_INDICATION_PDU_T* add_to_batch(Batch* batch);

Batch* create_batch(size_t size, bool crc_flag) {
    if (size == 0 || size > MAX_RNTI) return NULL;

    Batch* batch = malloc(sizeof(Batch));
    if (!batch) return NULL;

    pthread_mutex_init(&batch->lock, NULL);
    batch->head = NULL;
    batch->count = 0;

    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    for (size_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) {
            delete_batch(&batch);
            return NULL;
        }
        node->rx_ue_info_tag.rnti = rand() % MAX_RNTI + 1; // Ensure RNTI is non-zero
        node->crc_indication_rel8_tag.crc_value = rand(); // Simulating CRC value
        node->crc_flag = crc_flag;
        node->next = NULL;

        pthread_mutex_lock(&batch->lock);
        if (current) {
            current->next = node;
        } else {
            batch->head = node;
        }
        current = node;
        ++(batch->count);
        pthread_mutex_unlock(&batch->lock);
    }

    return batch;
}

void delete_batch(Batch** batch_ptr) {
    if (!batch_ptr || !*batch_ptr) return;

    Batch* batch = *batch_ptr;
    NFAPI_CRC_INDICATION_PDU_T* current = batch->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&batch->lock);
    free(batch);
    *batch_ptr = NULL;
}

NFAPI_CRC_INDICATION_PDU_T* add_to_batch(Batch* batch) {
    if (!batch || !batch->head) return NULL;

    pthread_mutex_lock(&batch->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = batch->head;
    while (current->next) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&batch->lock);
        return NULL;
    }

    new_node->rx_ue_info_tag.rnti = rand() % MAX_RNTI + 1; // Ensure RNTI is non-zero
    new_node->crc_indication_rel8_tag.crc_value = rand(); // Simulating CRC value
    new_node->crc_flag = batch->head->crc_flag;
    new_node->next = NULL;

    current->next = new_node;
    ++(batch->count);

    pthread_mutex_unlock(&batch->lock);

    return new_node;
}

// Example usage
int main() {
    Batch* batch1 = create_batch(10, true);
    if (batch1) {
        NFAPI_CRC_INDICATION_PDU_T* node = add_to_batch(batch1);
        // Process or iterate over the list as needed
        delete_batch(&batch1);
    }

    Batch* batch2 = create_batch(0, false); // Handle zero size gracefully
    if (batch2) {
        NFAPI_CRC_INDICATION_PDU_T* node = add_to_batch(batch2);
        // Process or iterate over the list as needed
        delete_batch(&batch2);
    }

    return 0;
}
```

