```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_RX_UE_TAG 1000
#define MAX_RNTI 500
#define NUM_STRUCTURES 10

typedef struct {
    int32_t RX_UE_INFORMATION_TAG;
    int16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    int success_count;
    int failure_count;
    double total_time;
} NFAPI_StructureManager;

// Function prototypes
void* initialize_structures(size_t num, unsigned int seed);
int validate_tag(int32_t tag);
int validate_rnti(int16_t rnti);
void free_resources(NFAPI_StructureManager *manager);

void* initialize_structures(size_t num, unsigned int seed) {
    NFAPI_StructureManager manager = {0};
    pthread_mutex_init(&manager.lock, NULL);
    srand(seed);

    // Pre-allocate memory to reduce heap fragmentation
    manager.capacity = num;
    manager.array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(manager.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager.array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    clock_t start_time = clock();
    for (size_t i = 0; i < num; ++i) {
        int32_t tag = rand() % MAX_RX_UE_TAG + 1;
        int16_t rnti = rand() % MAX_RNTI + 1;

        pthread_mutex_lock(&manager.lock);
        if (validate_tag(tag) && validate_rnti(rnti)) {
            manager.array[i].RX_UE_INFORMATION_TAG = tag;
            manager.array[i].RNTI = rnti;
            manager.array[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Example pseudo-random value
            manager.array[i].CRCFLAG = (rand() % 2) ? 1 : 0;
            ++manager.success_count;
        } else {
            fprintf(stderr, "Invalid input detected: Tag=%d, RNTI=%d\n", tag, rnti);
            ++manager.failure_count;
        }
        pthread_mutex_unlock(&manager.lock);
    }

    manager.size = num;
    clock_t end_time = clock();
    manager.total_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    printf("Total Structures: %zu\n", manager.size);
    printf("Success Count: %d\n", manager.success_count);
    printf("Failure Count: %d\n", manager.failure_count);
    printf("Average Time Per Operation: %.6f seconds\n", manager.total_time / num);

    return &manager;
}

int validate_tag(int32_t tag) {
    return (tag >= 1 && tag <= MAX_RX_UE_TAG);
}

int validate_rnti(int16_t rnti) {
    return (rnti >= 1 && rnti <= MAX_RNTI);
}

void free_resources(NFAPI_StructureManager *manager) {
    if (manager->array) {
        free(manager->array);
    }
    pthread_mutex_destroy(&manager->lock);
}
```

