    if (!list || initial_capacity == 0)
        return ERROR_ALLOC_FAIL;

    list->frames = (NFAPI_RX_FRAME_T **)malloc(initial_capacity * sizeof(NFAPI_RX_FRAME_T *));
    if (!list->frames) 
        return ERROR_ALLOC_FAIL;

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return SUCCESS;
}

// Function to free the dynamic frame list
void destroy_dynamic_frame_list(DynamicFrameList *list) {
