    }
    frame->RX_FRAME_TAG = RX_FRAME_TAG;
    frame->num_messages = num_messages;
    frame->messages = (RRC_MESSAGE_T *)malloc(num_messages * sizeof(RRC_MESSAGE_T));
    if (!frame->messages) {
        free(frame);
        pthread_mutex_unlock(&list->lock);
        return ERROR_ALLOC_FAIL;
    }

    // Add the frame to the list
    list->frames[list->count++] = frame;

    pthread_mutex_unlock(&list->lock);

    return SUCCESS;
}

// Function to remove a frame by its tag
int remove_frame_by_tag(DynamicFrameList *list, int RX_FRAME_TAG) {
    if (!list)
        return ERROR_INVALID_TAG;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->frames[i]->RX_FRAME_TAG == RX_FRAME_TAG) {
            free(list->frames[i]->messages);
            free(list->frames[i]);

            // Shift remaining elements
            memmove(&list->frames[i], &list->frames[i + 1],
                    (list->count - i - 1) * sizeof(NFAPI_RX_FRAME_T *));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return ERROR_INVALID_TAG; // Frame not found
}

// Function to get a frame by its tag
NFAPI_RX_FRAME_T *get_frame_by_tag(DynamicFrameList *list, int RX_FRAME_TAG) {
    if (!list)
        return NULL;

    for (size_t i = 0; i < list->count; ++i) {
        if (list->frames[i]->RX_FRAME_TAG == RX_FRAME_TAG) {
            return list->frames[i];
        }
    }

    return NULL;
}
