['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

// Define structures
typedef struct {
    // Assume some fields for PDCP_PDU
    uint8_t data[256];
} PDCP_PDU;

typedef enum {
    INIT,
    IN_PROGRESS,
    COMPLETED
} TransactionState;

typedef struct {
    uint16_t tag;
    TransactionState state;
} MAC_TRANSACTION_TAG;

typedef struct {
    PDCP_PDU pdcp_pdu;
    uint16_t sn;
    MAC_TRANSACTION_TAG transaction_tag;
} MAC_PDU;

// Define the dynamic list structure with thread safety
typedef struct Node {
    MAC_PDU pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} DynamicList;

// Function prototypes
DynamicList* create_dynamic_list();
void free_dynamic_list(DynamicList* list);
int add_pdu_to_list(DynamicList* list, MAC_PDU pdu);
MAC_PDU get_pdu_from_list(DynamicList* list, uint16_t sn);
void serialize_list(const char* filename, DynamicList* list);
int deserialize_list(const char* filename, DynamicList** out_list);
void log_event(const char* message);
void prune_old_data(DynamicList* list, uint16_t sn_threshold);

// Create a dynamic list
DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

// Free the dynamic list
void free_dynamic_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a PDU to the list
int add_pdu_to_list(DynamicList* list, MAC_PDU pdu) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->pdu = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Get a PDU from the list by SN
MAC_PDU get_pdu_from_list(DynamicList* list, uint16_t sn) {
    MAC_PDU pdu = {0};

    if (!list) return pdu;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->pdu.sn == sn) {
            pdu = current->pdu;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return pdu;
}

// Serialize the list to a binary file
void serialize_list(const char* filename, DynamicList* list) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    Node* current = list->head;

    while (current) {
        fwrite(&current->pdu.sn, sizeof(uint16_t), 1, file);
        fwrite(&current->pdu.transaction_tag.tag, sizeof(current->pdu.transaction_tag.tag), 1, file);
        fwrite(&current->pdu.transaction_tag.state, sizeof(current->pdu.transaction_tag.state), 1, file);
        fwrite(&current->pdu.pdcp_pdu.data, sizeof(current->pdu.pdcp_pdu.data), 1, file);

        current = current->next;
    }

    fclose(file);
}

// Deserialize a list from a binary file
int deserialize_list(const char* filename, DynamicList** out_list) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    DynamicList* list = create_dynamic_list();
    if (!list) {
        fclose(file);
        return -1;
    }

    while (!feof(file)) {
        MAC_PDU pdu;
        size_t read_size = fread(&pdu.sn, sizeof(uint16_t), 1, file);
        if (read_size == 0 && feof(file)) break;

        fread(&pdu.transaction_tag.tag, sizeof(pdu.transaction_tag.tag), 1, file);
        fread(&pdu.transaction_tag.state, sizeof(pdu.transaction_tag.state), 1, file);
        fread(&pdu.pdcp_pdu.data, sizeof(pdu.pdcp_pdu.data), 1, file);

        add_pdu_to_list(list, pdu);
    }

    fclose(file);
    *out_list = list;
    return 0;
}

// Log an event
void log_event(const char* message) {
    // Simple logging to console, can be expanded for file or syslog
    printf("Log: %s\n", message);
}

// Prune old data from the list based on SN threshold
void prune_old_data(DynamicList* list, uint16_t sn_threshold) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    Node *prev = NULL;

    while (current) {
        if (current->pdu.sn <= sn_threshold) {
            Node* to_free = current;
            if (prev) prev->next = current->next;
            else list->head = current->next;

            current = current->next;
            free(to_free);
            list->size--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Main function for testing
int main() {
    DynamicList* list = create_dynamic_list();

    MAC_PDU pdu1 = {{0}, 100, {123, IN_PROGRESS}};
    MAC_PDU pdu2 = {{0}, 101, {124, COMPLETED}};

    add_pdu_to_list(list, pdu1);
    add_pdu_to_list(list, pdu2);

    serialize_list("mac_pdus.bin", list);

    DynamicList* deserialized_list;
    deserialize_list("mac_pdus.bin", &deserialized_list);

    MAC_PDU retrieved = get_pdu_from_list(deserialized_list, 101);
    log_event("Retrieved PDU with SN 101");

    prune_old_data(deserialized_list, 100);
    free_dynamic_list(list);
    free_dynamic_list(deserialized_list);

    return 0;
}
