// Initialize the list with a given capacity.
void init_crc_indication_list(CRC_Indication_List *list, size_t initial_capacity) {
    list->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Resize the internal array if needed.
void ensure_capacity(CRC_Indication_List *list) {
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) {
            perror("Failed to resize array");
            exit(EXIT_FAILURE);
        }
        list->array = temp;
        list->capacity = new_capacity;
    }
}

// Function to add a structure to the list.
int add_crc_indication(CRC_Indication_List *list, const NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->array[i].rnti == item->rnti) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Duplicate RNTI found.
        }
    }

    ensure_capacity(list);

    list->array[list->count++] = *item;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Populate the list with random data and unique RNTIs using external API for retrieval.
void populate_crc_indication_list(CRC_Indication_List *list, size_t num_elements, unsigned int seed) {
