        item.rnti = retrieve_rnti_from_network();
        if (item.rnti == 0) { // Assuming 0 as an error condition
            exponential_backoff(&attempt, MAX_ATTEMPTS);
            continue;
        }

        // Randomly set CRCFLAG
        item.crc_indication.CRCFLAG = rand() % 2;

        int result = add_crc_indication(list, &item);
        if (result != 0) {
            fprintf(stderr, "Failed to add RNTI: %u\n", item.rnti);
        }

        attempt = 1; // Reset for next iteration
    }
}

