    fwrite(&list->count, sizeof(size_t), 1, file); // Write number of elements
    fwrite(list->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);

    pthread_mutex_unlock(&list->mutex);

    fclose(file);
}

