    fread(list->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    list->count = count;

    pthread_mutex_unlock(&list->mutex);

    fclose(file);
}

void free_crc_indication_list(CRC_Indication_List *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->array);
}

