typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the list structure with mutex for thread safety
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock; // Mutex for synchronizing access
} DoublyLinkedList;

// Function to initialize the doubly linked list
void init_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to create a new node with given data
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed for node");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

// Function to insert a node at the end of the list
void insert_end(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) return;

    pthread_mutex_lock(&list->lock);

    if (list->tail == NULL) { // List is empty
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to safely iterate over the list and print data
void safe_iterate_and_print(DoublyLinkedList* list) {
    Node* current;

    pthread_mutex_lock(&list->lock);

    for (current = list->head; current != NULL; current = current->next) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %s\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG,
               current->data.CRCFLAG ? "True" : "False");
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to free the list
void free_list(DoublyLinkedList* list) {
    Node* current = list->head;
    Node* next;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Function to process a batch of data
void process_batch(DoublyLinkedList* list, unsigned int max_batch_size) {
    unsigned int i;
    srand((unsigned int)time(NULL)); // Seed for random CRCFLAG

    for (i = 0; i < max_batch_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu_data;
        pdu_data.RX_UE_INFORMATION_TAG = rand(); // Random data
        pdu_data.RNTI = rand();
        pdu_data.CRC_INDICATION_REL8_TAG = rand();
        pdu_data.CRCFLAG = (rand() % 2) ? true : false; // Set CRCFLAG randomly

        insert_end(list, pdu_data);
    }
}

// Main function to demonstrate usage
int main() {
    DoublyLinkedList list;
    init_list(&list);

    unsigned int max_batch_size = 10;

    process_batch(&list, max_batch_size);
    safe_iterate_and_print(&list);
    free_list(&list);

    return 0;
}
