    CRC_INDICATION_REL8_TAG crc_rel8_tag;
    uint64_t timestamp;  // Added to facilitate frame management based on time.
} NFAPI_RX_FRAME_T;

// Define a structure for managing dynamic array
typedef struct {
    NFAPI_RX_FRAME_T **frames;
    size_t capacity;
    size_t count;
} DynamicArray;

// Helper function prototypes
DynamicArray* init_dynamic_array(size_t initial_capacity);
void insert_frame(DynamicArray *array, const NFAPI_RX_FRAME_T *frame);
NFAPI_RX_FRAME_T* find_frame_by_rnti(DynamicArray *array, uint16_t rnti);
void remove_frame_by_rnti(DynamicArray *array, uint16_t rnti);
void update_crc_flags(DynamicArray *array, uint64_t current_time, int criteria);
void flush_old_frames(DynamicArray *array, uint64_t cutoff_timestamp);
void free_dynamic_array(DynamicArray *array);

// Initialize a dynamic array
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;  // Handle allocation failure

    array->frames = (NFAPI_RX_FRAME_T**)calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_T*));
    if (!array->frames) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

// Insert a frame into the dynamic array
void insert_frame(DynamicArray *array, const NFAPI_RX_FRAME_T *frame) {
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_RX_FRAME_T **new_frames = realloc(array->frames, new_capacity * sizeof(NFAPI_RX_FRAME_T*));
        if (!new_frames) return; // Handle allocation failure

        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    NFAPI_RX_FRAME_T *copy = (NFAPI_RX_FRAME_T*)malloc(sizeof(NFAPI_RX_FRAME_T));
    if (!copy) return;  // Handle allocation failure
    memcpy(copy, frame, sizeof(NFAPI_RX_FRAME_T));

    array->frames[array->count++] = copy;
}

// Find a frame by RNTI
NFAPI_RX_FRAME_T* find_frame_by_rnti(DynamicArray *array, uint16_t rnti) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->frames[i]->RNTI == rnti)
            return array->frames[i];
    }
    return NULL;
}

// Remove a frame by RNTI
void remove_frame_by_rnti(DynamicArray *array, uint16_t rnti) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->frames[i]->RNTI == rnti) {
            free(array->frames[i]);
            memmove(&array->frames[i], &array->frames[i + 1], (array->count - i - 1) * sizeof(NFAPI_RX_FRAME_T*));
            array->count--;
            return;
        }
    }
}

// Update CRC flags according to specified criteria
void update_crc_flags(DynamicArray *array, uint64_t current_time, int criteria) {
    for (size_t i = 0; i < array->count; ++i) {
        // Implement your logic here based on the 'criteria' variable.
        if ((int)(current_time - array->frames[i]->timestamp) % criteria == 0) { 
            // Example condition
            array->frames[i]->crc_rel8_tag.CRC = ~array->frames[i]->crc_rel8_tag.CRC; // Invert CRC for demo purposes
        }
    }
}

// Flush frames older than a specified timestamp
void flush_old_frames(DynamicArray *array, uint64_t cutoff_timestamp) {
    size_t write_index = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->frames[i]->timestamp >= cutoff_timestamp) {
            array->frames[write_index++] = array->frames[i];
        } else {
            free(array->frames[i]);
        }
    }
    array->count = write_index;
}

// Free the dynamic array
void free_dynamic_array(DynamicArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        free(array->frames[i]);
    }
    free(array->frames);
    free(array);
}
