#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_EVENTS 10000

typedef struct {
    uint32_t RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    time_t timestamp;
    char protocolType[10];
    CRC_INDICATION_REL8_TAG crcTag;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxInfo;
    uint16_t validRxInfo; // 1 if valid, 0 otherwise
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct EventNode {
    NFAPI_CRC_INDICATION_PDU_T event;
    struct EventNode* next;
} EventNode;

// Memory pool for events
EventNode* memoryPool[MAX_EVENTS];
int poolIndex = 0;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeMemoryPool() {
    pthread_mutex_lock(&poolMutex);
    for (int i = 0; i < MAX_EVENTS; ++i) {
        memoryPool[i] = malloc(sizeof(EventNode));
    }
    pthread_mutex_unlock(&poolMutex);
}

EventNode* allocateEventNode() {
    pthread_mutex_lock(&poolMutex);
    if (poolIndex >= MAX_EVENTS) {
        printf("Memory pool exhausted\n");
        pthread_mutex_unlock(&poolMutex);
        return NULL;
    }
    EventNode* node = memoryPool[poolIndex++];
    pthread_mutex_unlock(&poolMutex);
    return node;
}

void freeEventNode(EventNode* node) {
    if (node == NULL) return;
    // Add back to pool for reuse
    pthread_mutex_lock(&poolMutex);
    node->next = NULL;
    memoryPool[--poolIndex] = node;
    pthread_mutex_unlock(&poolMutex);
}

typedef struct {
    EventNode* head;
    atomic_int processedEventsCount;
} EventQueue;

EventQueue eventQueue = {NULL, 0};

void enqueueEvent(EventQueue* queue, NFAPI_CRC_INDICATION_PDU_T event) {
    EventNode* newNode = allocateEventNode();
    if (newNode == NULL) return;

    newNode->event = event;
    newNode->next = NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    newNode->next = queue->head;
    queue->head = newNode;
    pthread_mutex_unlock(&lock);

    pthread_mutex_destroy(&lock);
}

int dequeueEvent(EventQueue* queue, NFAPI_CRC_INDICATION_PDU_T* event) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    if (queue->head == NULL) {
        pthread_mutex_unlock(&lock);
        return 0;
    }

    EventNode* temp = queue->head;
    *event = temp->event;
    queue->head = queue->head->next;

    freeEventNode(temp);
    atomic_fetch_add(&queue->processedEventsCount, 1);

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return 1;
}

int validateRNTI(uint32_t rnti) {
    // Simple validation: RNTI should be non-zero
    return rnti != 0;
}

void processEvent(NFAPI_CRC_INDICATION_PDU_T event) {
    if (!validateRNTI(event.rxInfo.crcTag.RNTI)) {
        printf("Invalid RNTI detected\n");
        return;
    }

    // Simulate processing
    printf("Processing Event: RNTI=%u, CRCFLAG=%d\n", 
           event.rxInfo.crcTag.RNTI, event.rxInfo.crcTag.CRCFLAG);
}

void* eventProcessor(void* arg) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T event;
        if (dequeueEvent(&eventQueue, &event)) {
            processEvent(event);
        }
        // Simulate real-time processing delay
        usleep(1000);
    }
}

int main() {
    srand(time(NULL));
    initializeMemoryPool();

    pthread_t processorThread;
    pthread_create(&processorThread, NULL, eventProcessor, NULL);

    for (int i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T newEvent;
        newEvent.rxInfo.crcTag.RNTI = rand() % 1024 + 1; // Random RNTI
        newEvent.rxInfo.crcTag.CRCFLAG = rand() % 2;     // Random CRCFLAG
        newEvent.validRxInfo = 1;

        enqueueEvent(&eventQueue, newEvent);
    }

    pthread_join(processorThread, NULL);

    return 0;
}
```

### Key Design Decisions and Assumptions:
- **Memory Pool**: A fixed-size memory pool is used to manage event nodes efficiently. This reduces the overhead of frequent allocations and deallocations.
- **Concurrency**: Mutexes are used for thread safety during enqueue and dequeue operations, ensuring that only one thread can modify the queue at a time.
- **Atomic Operations**: Used to safely increment the count of processed events without requiring additional locking.
- **Validation Logic**: Simple validation is implemented for RNTI values. This can be expanded based on specific requirements.
- **Scalability**: The system uses a fixed-size memory pool, which may need adjustment based on expected load.
- **Performance Monitoring**: Basic processing metrics are printed; more sophisticated monitoring could be added as needed.

### Potential Optimizations:
- Use lock-free data structures for the event queue to reduce contention and improve throughput under high concurrency.
- Implement more advanced validation and error handling mechanisms.
- Consider using a dynamic memory pool that can grow or shrink based on demand, with proper synchronization.

This implementation provides a basic framework that can be expanded and optimized based on specific use cases and performance requirements.']

