#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_ELEMENTS 100000
#define MEMORY_POOL_SIZE (8 * 1024 * 1024) // 8 MB
#define STRUCT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    void* memory_pool;
    size_t pool_size;
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    Node* head;
    pthread_mutex_t list_lock;
    int successful_allocations;
    int failed_allocations;
    int reallocations;
} NFACollection;

// Function to initialize memory pool
int init_memory_pool(MemoryPool* pool) {
    if (!pool) return -1;
    pool->memory_pool = malloc(pool->pool_size);
    if (!pool->memory_pool) return -1;
    pool->offset = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return 0;
}

// Function to allocate memory from the pool
void* memory_pool_alloc(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->offset + size > pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Out of memory
    }
    void* mem = pool->memory_pool + pool->offset;
    pool->offset += size;
    pthread_mutex_unlock(&pool->lock);
    return mem;
}

// Function to initialize NFACollection
int init_nfa_collection(NFACollection* collection, MemoryPool* pool) {
    if (!collection || !pool) return -1;
    collection->head = NULL;
    pthread_mutex_init(&collection->list_lock, NULL);
    collection->successful_allocations = 0;
    collection->failed_allocations = 0;
    collection->reallocations = 0;
    return 0;
}

// Function to create a new NFAPI_CRC_INDICATION_PDU_T node
Node* create_node(MemoryPool* pool) {
    Node* node = (Node*)memory_pool_alloc(pool, STRUCT_SIZE + sizeof(Node*));
    if (!node) {
        return NULL;
    }
    node->next = NULL;
    // Initialize random seed per thread
    static __thread unsigned int seed;
    if (!seed) {
        seed = time(NULL);
    }
    srand(seed);
    node->data.CRCFLAG = rand() % 2; // Random CRCFLAG value (0 or 1)
    return node;
}

// Function to add a new element to the collection
int nfa_collection_add(NFACollection* collection, MemoryPool* pool) {
    pthread_mutex_lock(&collection->list_lock);
    Node* new_node = create_node(pool);
    if (!new_node) {
        pthread_mutex_unlock(&collection->list_lock);
        return -1; // Failed allocation
    }
    new_node->data.RX_UE_INFORMATION_TAG = rand(); // Random value for example
    new_node->data.RNTI = rand() % 65536;
    new_node->data.CRC_INDICATION_REL8_TAG = rand() % 256;

    new_node->next = collection->head;
    collection->head = new_node;
    collection->successful_allocations++;
    pthread_mutex_unlock(&collection->list_lock);
    return 0;
}

// Function to free the memory pool
void free_memory_pool(MemoryPool* pool) {
    if (pool && pool->memory_pool) {
        free(pool->memory_pool);
        pthread_mutex_destroy(&pool->lock);
    }
}

// Function to free the collection
void free_nfa_collection(NFACollection* collection, MemoryPool* pool) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        // No need to free individual nodes as they are part of memory pool
        current = next;
    }
    pthread_mutex_destroy(&collection->list_lock);
}

// Example usage function
void example_usage() {
    MemoryPool pool = { .pool_size = MEMORY_POOL_SIZE };
    NFACollection collection;

    if (init_memory_pool(&pool) != 0 || init_nfa_collection(&collection, &pool) != 0) {
        fprintf(stderr, "Initialization failed\n");
        return;
    }

    // Simulate adding elements to the collection
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        if (nfa_collection_add(&collection, &pool) != 0) {
            printf("Failed allocation attempt at index %d\n", i);
            break;
        }
    }

    // Print statistics
    printf("Successful allocations: %d\n", collection.successful_allocations);
    printf("Failed allocations: %d\n", collection.failed_allocations);

    free_nfa_collection(&collection, &pool);
    free_memory_pool(&pool);
}

int main() {
    example_usage();
    return 0;
}
