#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
import "nfa_api_crc_indication_pdu_t.h"  // Include the definition for NFAPI_CRC_INDICATION_PDU_T

#define MAX_CAPACITY 10000
#define MEMORY_POOL_SIZE (2 * 1024 * 1024) // 2 MB

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    size_t element_size;
    char pool[MEMORY_POOL_SIZE];
    pthread_rwlock_t lock;
} DynamicList;

// Initialize the dynamic list with a custom memory pool
int init_dynamic_list(DynamicList* list, size_t element_size) {
    if (list == NULL || element_size * MAX_CAPACITY > MEMORY_POOL_SIZE) {
        return -1; // Invalid parameters or insufficient memory
    }

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)list->pool;
    list->capacity = 0;
    list->count = 0;
    list->element_size = element_size;

    if (pthread_rwlock_init(&list->lock, NULL) != 0) {
        return -1; // Failed to initialize lock
    }

    return 0;
}

// Add an element to the dynamic list in a thread-safe manner
int add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* item) {
    if (pthread_rwlock_wrlock(&list->lock) != 0) {
        return -1; // Failed to acquire lock
    }

    if (list->count >= MAX_CAPACITY || list->capacity * list->element_size > MEMORY_POOL_SIZE) {
        pthread_rwlock_unlock(&list->lock);
        return -2; // List is full or out of memory
    }

    if (list->capacity == 0) {
        list->capacity = 1;
    } else if (list->count == list->capacity) {
        size_t new_capacity = (list->capacity * 2 > MAX_CAPACITY || 
                               list->capacity * 2 * list->element_size > MEMORY_POOL_SIZE)
                              ? MAX_CAPACITY
                              : list->capacity * 2;
        list->capacity = new_capacity;
    }

    memcpy(&list->data[list->count], item, list->element_size);
    list->count++;

    pthread_rwlock_unlock(&list->lock);

    return 0;
}

// Remove an element from the dynamic list in a thread-safe manner
int remove_from_list(DynamicList* list) {
    if (pthread_rwlock_wrlock(&list->lock) != 0) {
        return -1; // Failed to acquire lock
    }

    if (list->count == 0) {
        pthread_rwlock_unlock(&list->lock);
        return -2; // List is empty
    }

    list->count--;

    pthread_rwlock_unlock(&list->lock);

    return 0;
}

// Get the count of elements in the dynamic list
size_t get_list_count(const DynamicList* list) {
    size_t count;

    if (pthread_rwlock_rdlock(&list->lock) != 0) {
        return -1; // Failed to acquire lock
    }

    count = list->count;

    pthread_rwlock_unlock(&list->lock);

    return count;
}

// Clean up the dynamic list and its resources
void destroy_dynamic_list(DynamicList* list) {
    if (list == NULL) return;

    pthread_rwlock_destroy(&list->lock);
}

// Example of how to integrate with a message-passing framework
void process_message(void* context, NFAPI_CRC_INDICATION_PDU_T* item) {
    // This function would be called by the message-passing framework

    DynamicList* list = (DynamicList*)context;

    if (add_to_list(list, item) != 0) {
        fprintf(stderr, "Failed to add element to list\n");
        // Handle error appropriately
    }
}

// Example of how to use the dynamic list in a multi-threaded environment
void example_usage() {
    DynamicList my_list;
    init_dynamic_list(&my_list, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_t threads[10];

    for (int i = 0; i < 10; ++i) {
        // Spawn threads to simulate concurrent access
        pthread_create(&threads[i], NULL, process_message_wrapper, &my_list);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_dynamic_list(&my_list);
}

void* process_message_wrapper(void* arg) {
    DynamicList* list = (DynamicList*)arg;
    NFAPI_CRC_INDICATION_PDU_T item;

