int populateTrafficFlows(TrafficFlow **flows, size_t numFlows) {
    if (numFlows == 0 || flows == NULL) return -1;

    // Allocate memory for the dynamic array of TrafficFlow structures
    *flows = malloc(numFlows * sizeof(TrafficFlow));
    if (*flows == NULL) return -1; // Memory allocation failed

    for (size_t i = 0; i < numFlows; ++i) {
        // Generate random IP addresses and FlowID
        struct in_addr sourceAddr, destAddr;
        unsigned int flowID;

        // Ensure unique FlowID
        do {
            flowID = rand() % UINT_MAX;
        } while (!isUniqueFlowID(flowID, *flows, i));

        inet_pton(AF_INET, "192.168.1.", &sourceAddr.s_addr);
        sourceAddr.s_addr |= (rand() % 256) << 8;
        inet_ntop(AF_INET, &sourceAddr, (*flows)[i].SourceIPAddress, INET_ADDRSTRLEN);

        inet_pton(AF_INET, "10.0.0.", &destAddr.s_addr);
        destAddr.s_addr |= (rand() % 256) << 8;
        inet_ntop(AF_INET, &destAddr, (*flows)[i].DestinationIPAddress, INET_ADDRSTRLEN);

        (*flows)[i].FlowID = flowID;
    }

    return 0; // Success
}

void freeTrafficFlows(TrafficFlow *flows, size_t numFlows) {
    if (flows != NULL) {
        free(flows);
    }
}

int isUniqueFlowID(unsigned int flowID, TrafficFlow *flows, size_t numFlows) {
    for (size_t i = 0; i < numFlows; ++i) {
        if (flows[i].FlowID == flowID) return 0;
    }
    return 1;
}

void printTrafficFlows(const TrafficFlow *flows, size_t numFlows) {
    if (flows == NULL || numFlows == 0) return;

    for (size_t i = 0; i < numFlows; ++i) {
        printf("Source IP: %s\n", flows[i].SourceIPAddress);
        printf("Destination IP: %s\n", flows[i].DestinationIPAddress);
        printf("Flow ID: %u\n\n", flows[i].FlowID);
    }
}

