#define MAX_BUFFER_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* processInput(void *args) {
    int *buffer = (int *)args;
    pthread_mutex_lock(&mutex);
    // Simulate processing and validation
    printf("Processing input: %d\n", buffer[0]);
    usleep(rand() % 10000); // Random delay to simulate external data source latency
    pthread_mutex_unlock(&mutex);
    free(buffer);
    return NULL;
}

void generateAndProcessPDUList(int n, int processAll) {
    NFAPI_CRC_INDICATION_PDU_T *pduList = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        perror("Memory allocation failed");
        return;
    }

    pthread_t threads[MAX_BUFFER_SIZE];
    int thread_count = 0;

    for (int i = 0; i < n; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pduList[i].RNTI = rand() % 1000;
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    int inputBuffer[MAX_BUFFER_SIZE];
    int bufferSize = 0;

    while (scanf("%d", &inputBuffer[bufferSize]) == 1) {
        if (processAll || (inputBuffer[bufferSize] % 2 == 0)) {
            pthread_mutex_lock(&mutex);
            if (bufferSize < MAX_BUFFER_SIZE) {
                inputBuffer[++bufferSize] = 0; // Placeholder for null termination
            } else {
                fprintf(stderr, "Buffer full. Dropping data.\n");
                break;
            }
            pthread_mutex_unlock(&mutex);

            int *inputCopy = malloc(sizeof(int));
            if (!inputCopy) {
                perror("Memory allocation failed");
                continue;
            }
            *inputCopy = inputBuffer[bufferSize - 1];

            if (thread_count < MAX_BUFFER_SIZE && pthread_create(&threads[thread_count++], NULL, processInput, inputCopy)) {
                perror("Thread creation failed");
                free(inputCopy);
            }

            while (thread_count == MAX_BUFFER_SIZE) {
                usleep(1000); // Wait for threads to finish
                thread_count = 0;
                for (int i = 0; i < MAX_BUFFER_SIZE; ++i) {
                    if (threads[i] != 0 && pthread_tryjoin_np(threads[i], NULL)) {
                        continue;
                    }
                    thread_count++;
                }
            }
        } else {
            // Skip odd numbers if not processing all
            while (getchar() != '\n');
        }
    }

    // Join any remaining threads
    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(pduList);
}

int main(int argc, char *argv[]) {
    if (argc != 2 || (strcmp(argv[1], "all") != 0 && strcmp(argv[1], "even") != 0)) {
        fprintf(stderr, "Usage: %s [all|even]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int n = MAX_BUFFER_SIZE; // Example size
    int processAll = (strcmp(argv[1], "all") == 0);

    srand(time(NULL));
    generateAndProcessPDUList(n, processAll);

    return EXIT_SUCCESS;
}
```

