#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_POOL_SIZE 10

typedef struct {
    int tag;
    // Add other fields as necessary for RX_FRAME_TAG
} RX_FRAME_TAG;

typedef struct {
    int data[256]; // Example structure, adjust size and content as needed
} RRC_MESSAGE_T;

typedef struct NFAPI_RX_FRAME_T {
    RX_FRAME_TAG frame_tag;
    RRC_MESSAGE_T* rrc_messages;
    size_t message_count;
} NFAPI_RX_FRAME_T;

typedef struct {
    RRC_MESSAGE_T* pool[INITIAL_POOL_SIZE];
    size_t used_pool_size;
    pthread_mutex_t lock;
} RRC_MEMORY_POOL;

typedef struct {
    NFAPI_RX_FRAME_T** frames;
    size_t capacity;
    size_t count;
    RRC_MEMORY_POOL rrc_pool;
    pthread_mutex_t list_lock;
    int processed_frames;
    int failed_operations;
    float average_message_size;
} FRAME_LIST_MANAGER;

void initialize_pool(RRC_MEMORY_POOL* pool) {
    pool->used_pool_size = 0;
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        pool->pool[i] = malloc(sizeof(RRC_MESSAGE_T));
        if (!pool->pool[i]) {
            fprintf(stderr, "Failed to allocate memory for RRC message\n");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_init(&pool->lock, NULL);
}

RRC_MESSAGE_T* acquire_message_from_pool(RRC_MEMORY_POOL* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_pool_size == 0) {
        pthread_mutex_unlock(&pool->lock);
        return malloc(sizeof(RRC_MESSAGE_T)); // Fall back to standard allocation
    }
    RRC_MESSAGE_T* message = pool->pool[--pool->used_pool_size];
    pthread_mutex_unlock(&pool->lock);
    return message;
}

void release_message_to_pool(RRC_MEMORY_POOL* pool, RRC_MESSAGE_T* message) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_pool_size < INITIAL_POOL_SIZE) {
        pool->pool[pool->used_pool_size++] = message;
    } else {
        free(message); // Pool is full
    }
    pthread_mutex_unlock(&pool->lock);
}

void initialize_list_manager(FRAME_LIST_MANAGER* manager) {
    manager->frames = malloc(sizeof(NFAPI_RX_FRAME_T*) * 10);
    if (!manager->frames) {
        fprintf(stderr, "Failed to allocate initial frame list\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = 10;
    manager->count = 0;
    initialize_pool(&manager->rrc_pool);
    pthread_mutex_init(&manager->list_lock, NULL);
    manager->processed_frames = 0;
    manager->failed_operations = 0;
    manager->average_message_size = 0.0;
}

void resize_list(FRAME_LIST_MANAGER* manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_RX_FRAME_T** new_frames = realloc(manager->frames, sizeof(NFAPI_RX_FRAME_T*) * new_capacity);
    if (!new_frames) {
        fprintf(stderr, "Failed to resize frame list\n");
        return;
    }
    manager->frames = new_frames;
    manager->capacity = new_capacity;
}

void add_frame(FRAME_LIST_MANAGER* manager, NFAPI_RX_FRAME_T* frame) {
    pthread_mutex_lock(&manager->list_lock);
    if (manager->count == manager->capacity) {
        resize_list(manager);
    }
    manager->frames[manager->count++] = frame;
    manager->processed_frames++;
    pthread_mutex_unlock(&manager->list_lock);
}

void remove_frame(FRAME_LIST_MANAGER* manager, size_t index) {
    pthread_mutex_lock(&manager->list_lock);
    if (index < manager->count) {
        for (size_t i = index; i < manager->count - 1; ++i) {
            manager->frames[i] = manager->frames[i + 1];
        }
        free(manager->frames[--manager->count]->rrc_messages);
        free(manager->frames[manager->count]);
    } else {
        fprintf(stderr, "Attempt to remove frame at invalid index\n");
        manager->failed_operations++;
    }
    pthread_mutex_unlock(&manager->list_lock);
}

void destroy_list(FRAME_LIST_MANAGER* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]->rrc_messages);
        free(manager->frames[i]);
    }
    free(manager->frames);

    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        free(manager->rrc_pool.pool[i]);
    }

    pthread_mutex_destroy(&manager->list_lock);
    pthread_mutex_destroy(&manager->rrc_pool.lock);
}

void process_rf_data(FRAME_LIST_MANAGER* manager, /* RF data acquisition library parameters */) {
    // Simulate acquiring valid frames and messages from the RF module
    for (size_t i = 0; i < 100; ++i) { // Example loop
        NFAPI_RX_FRAME_T* frame = malloc(sizeof(NFAPI_RX_FRAME_T));
        if (!frame) {
            fprintf(stderr, "Failed to allocate memory for frame\n");
            manager->failed_operations++;
            continue;
        }

        frame->frame_tag.tag = i; // Simulate setting a tag
        frame->message_count = rand() % 10 + 1;

        size_t message_size = sizeof(RRC_MESSAGE_T) * frame->message_count;
        frame->rrc_messages = malloc(message_size);
        if (!frame->rrc_messages) {
            fprintf(stderr, "Failed to allocate memory for RRC messages\n");
            free(frame);
            manager->failed_operations++;
            continue;
        }

        for (size_t j = 0; j < frame->message_count; ++j) {
            frame->rrc_messages[j] = *acquire_message_from_pool(&manager->rrc_pool);
            // Simulate filling with data
        }

        add_frame(manager, frame);

        manager->average_message_size = ((manager->average_message_size * (i)) + message_size) / (i + 1);
    }
}

void log_statistics(FRAME_LIST_MANAGER* manager) {
    printf("Processed Frames: %d\n", manager->processed_frames);
    printf("Failed Operations: %d\n", manager->failed_operations);
    printf("Average Message Size: %.2f bytes\n", manager->average_message_size);
}

int main() {
    FRAME_LIST_MANAGER manager;
    initialize_list_manager(&manager);

    // Simulate RF data acquisition
    process_rf_data(&manager, /* parameters */);

    log_statistics(&manager);

    destroy_list(&manager);
    return 0;
}
```

