#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    int packet_id;
    size_t payload_size;
} PacketInfo;

typedef struct {
    int connection_id;
    PacketInfo* packets;
    size_t packet_count;
    time_t last_update;
} ConnectionContext;

typedef struct {
    ConnectionContext* connections[MAX_CONNECTIONS];
    pthread_mutex_t mutex;
} ConnectionManager;

ConnectionManager cm = { .connections = {0}, .mutex = PTHREAD_MUTEX_INITIALIZER };

int allocate_connection(int connection_id) {
    pthread_mutex_lock(&cm.mutex);

    if (connection_id < 0 || connection_id >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&cm.mutex);
        return -1; // Invalid connection ID
    }

    if (cm.connections[connection_id] != NULL) {
        pthread_mutex_unlock(&cm.mutex);
        return -2; // Connection already exists
    }

    cm.connections[connection_id] = malloc(sizeof(ConnectionContext));
    if (!cm.connections[connection_id]) {
        pthread_mutex_unlock(&cm.mutex);
        return -3; // Memory allocation failure
    }

    cm.connections[connection_id]->connection_id = connection_id;
    cm.connections[connection_id]->packets = NULL;
    cm.connections[connection_id]->packet_count = 0;
    cm.connections[connection_id]->last_update = time(NULL);

    pthread_mutex_unlock(&cm.mutex);
    return 0; // Success
}

int deallocate_connection(int connection_id) {
    pthread_mutex_lock(&cm.mutex);

    if (connection_id < 0 || connection_id >= MAX_CONNECTIONS ||
        cm.connections[connection_id] == NULL) {
        pthread_mutex_unlock(&cm.mutex);
        return -1; // Invalid or non-existent connection ID
    }

    ConnectionContext* context = cm.connections[connection_id];
    free(context->packets);
    free(context);

    cm.connections[connection_id] = NULL;

    pthread_mutex_unlock(&cm.mutex);
    return 0; // Success
}

int update_connection(int connection_id, PacketInfo packet) {
    pthread_mutex_lock(&cm.mutex);

    if (connection_id < 0 || connection_id >= MAX_CONNECTIONS ||
        cm.connections[connection_id] == NULL) {
        pthread_mutex_unlock(&cm.mutex);
        return -1; // Invalid or non-existent connection ID
    }

    ConnectionContext* context = cm.connections[connection_id];
    size_t new_count = context->packet_count + 1;
    PacketInfo* new_packets = realloc(context->packets, new_count * sizeof(PacketInfo));

    if (!new_packets) {
        pthread_mutex_unlock(&cm.mutex);
        return -2; // Memory allocation failure
    }

    context->packets = new_packets;
    context->packets[context->packet_count] = packet;
    context->packet_count = new_count;
    context->last_update = time(NULL);

    pthread_mutex_unlock(&cm.mutex);
    return 0; // Success
}

void print_connections() {
    pthread_mutex_lock(&cm.mutex);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (cm.connections[i]) {
            printf("Connection ID: %d, Packets: %zu, Last Update: %ld\n",
                   cm.connections[i]->connection_id,
                   cm.connections[i]->packet_count,
                   cm.connections[i]->last_update);
        }
    }

    pthread_mutex_unlock(&cm.mutex);
}

int main() {
    if (allocate_connection(0) != 0) return 1;
    PacketInfo packet = { .packet_id = 1, .payload_size = 100 };
    if (update_connection(0, packet) != 0) return 1;

    print_connections();

    deallocate_connection(0);
    return 0;
}
```

### Key Points:
