    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node
Node* create_node(unsigned long rx_ue_info_tag, unsigned short rnti) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }

    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.RNTI = rnti;
    srand(time(NULL) + rx_ue_info_tag); // Seed with unique value
    new_node->data.crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
    new_node->next = NULL;

    return new_node;
}

// Function to append a node to the linked list
void append_node(Node** head, unsigned long rx_ue_info_tag, unsigned short rnti) {
    Node* new_node = create_node(rx_ue_info_tag, rnti);
    if (!new_node) return;

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

// Function to validate CRCFLAG consistency
void validate_crcflags(Node* head) {
    if (!head) return;

    Node* current = head;
    int index = 0;

    while (current && current->next) {
        if (current->data.crc_indication_rel8_tag.CRCFLAG != 
            current->next->data.crc_indication_rel8_tag.CRCFLAG) {
            printf("Error: CRCFLAG inconsistency at node index %d\n", index);
        }
        current = current->next;
        index++;
    }
}

// Function to free the linked list
void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    Node* head = NULL;

    // Example usage: create a linked list with 5 nodes
    for (unsigned long i = 1; i <= 5; ++i) {
        append_node(&head, i, i * 10); // Using i and i*10 as example tags
    }

    validate_crcflags(head);

    free_list(head);
    return 0;
}
