```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread-safe operations
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

#define MAX_RETRIES 5

typedef void (*DataRetrievalCallback)(int, const char *);

// Function to simulate data retrieval with exponential backoff
void fetchData(int rnti, DataRetrievalCallback callback) {
    int attempt = 0;
    while (attempt < MAX_RETRIES) {
        if (rand() % 2 == 0) { // Simulating a transient error
            printf("Transient error, retrying...\n");
            sleep((1 << attempt));
            attempt++;
            continue;
        }
        callback(rnti, "Success");
        return;
    }
    printf("Failed to retrieve data for RNTI: %d\n", rnti);
}

// Callback example function
