    }
}

// Function to serialize the list to a binary file
void serializeToFile(NFAPI_CRC_INDICATION_PDU_T *list, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    fclose(file);
}

// Function to deserialize the list from a binary file
NFAPI_CRC_INDICATION_PDU_T *deserializeFromFile(const char *filename, size_t *count) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t elementCount = fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(fileSize);

    if (!list) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), elementCount, file);
    fclose(file);

    *count = elementCount;
    return list;
}

// Function to manage CRC indications
void manageCRCIndications(size_t size, int seed) {
