#include <openssl/kdf.h>
#include <openssl/buffer.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MIN_PASSWORD_LENGTH 16
#define KEY_SIZE 32 // AES-256 key size in bytes
#define IV_SIZE 16  // AES block size for CBC mode

typedef struct {
    unsigned char *key;
    unsigned char *iv;
} AESContext;

void secure_zero(void *ptr, size_t len) {
    volatile unsigned char *volatile p = (volatile unsigned char *volatile) ptr;
    while (len--) *p++ = 0;
}

int initialize_aes_cipher(const char *password, const unsigned char *salt,
                          int iterations, AESContext **aes_context) {

    if (!password || strlen(password) < MIN_PASSWORD_LENGTH) {
        fprintf(stderr, "Error: Password too short.\n");
        return 1;
    }

    if (iterations <= 0) {
        fprintf(stderr, "Error: Invalid number of PBKDF2 iterations.\n");
        return 1;
    }

    // Allocate memory for the derived key and IV
    unsigned char *key = malloc(KEY_SIZE);
    unsigned char *iv = malloc(IV_SIZE);

    if (!key || !iv) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        secure_zero(key, KEY_SIZE);
        secure_zero(iv, IV_SIZE);
        free(key); free(iv);
        return 1;
    }

    // Derive key and IV using PBKDF2
    if (PKCS5_PBKDF2_HMAC(
            password,
            strlen(password),
            salt, EVP_MAX_MD_SIZE,
            iterations,
            EVP_sha256(),
            KEY_SIZE + IV_SIZE,
            key) != 1) {
        fprintf(stderr, "Error: Key derivation failed.\n");
        secure_zero(key, KEY_SIZE);
        secure_zero(iv, IV_SIZE);
        free(key); free(iv);
        return 1;
    }

    // Initialize cipher context
    *aes_context = (AESContext *)malloc(sizeof(AESContext));
    if (!*aes_context) {
        fprintf(stderr, "Error: Memory allocation for AES context failed.\n");
        secure_zero(key, KEY_SIZE);
        secure_zero(iv, IV_SIZE);
        free(key); free(iv);
        return 1;
    }

    (*aes_context)->key = key;
    (*aes_context)->iv = key + KEY_SIZE; // The IV is stored immediately after the key

    printf("AES cipher initialized successfully.\n");

    return 0;
}

void cleanup_aes_cipher(AESContext *aes_context) {
    if (aes_context) {
        secure_zero(aes_context->key, KEY_SIZE);
        secure_zero(aes_context->iv, IV_SIZE);
        free(aes_context->key);
        free(aes_context->iv);
        free(aes_context);
    }
}

int main() {
    const char *password = "secure_password";
    unsigned char salt[16];

    // Generate a random salt
    if (!RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Error: Salt generation failed.\n");
        return 1;
    }

    AESContext *aes_context = NULL;
    int iterations = 10000; // Adjust based on system resources

    if (initialize_aes_cipher(password, salt, iterations, &aes_context) != 0) {
        fprintf(stderr, "Failed to initialize cipher.\n");
        return 1;
    }

    // Cipher is now initialized and ready for use...

    cleanup_aes_cipher(aes_context);

    return 0;
}
```

