int validate_frame(NFAPI_RX_FRAME_T *frame);
void external_module_process(FrameList *list);
void log_duplicate(const char* message);

FrameList* create_list(ErrorCallback error_callback) {
    FrameList *list = (FrameList*)malloc(sizeof(FrameList));
    if (!list) {
        if (error_callback) error_callback("Failed to allocate memory for list.");
        return NULL;
    }
    list->head = NULL;
    list->count = 0;
    return list;
}

void add_frame(FrameList *list, NFAPI_RX_FRAME_T frame, ErrorCallback error_callback) {
    Node **current = &(list->head);
    while (*current != NULL && ((*current)->frame.header.PCI == frame.header.PCI)) {
        log_duplicate("Duplicate PCI detected.");
        return;
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        if (error_callback) error_callback("Failed to allocate memory for new node.");
        return;
    }

    new_node->frame = frame;
    new_node->next = NULL;

    while (*current != NULL && ((*current)->frame.header.PCI < frame.header.PCI)) {
        current = &((*current)->next);
    }

    if (*current == list->head) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node *temp = *current;
        new_node->next = temp->next;
        temp->next = new_node;
    }

    list->count++;
}

void remove_frame(FrameList *list, uint8_t PCI, ErrorCallback error_callback) {
    if (!list || !list->head) return;

    Node **current = &(list->head);
    while (*current && (*current)->frame.header.PCI != PCI) {
        current = &((*current)->next);
    }

    if (*current) {
        Node *temp = *current;
        *current = (*current)->next;
        free(temp);
        list->count--;
    }
}

void destroy_list(FrameList *list, ErrorCallback error_callback) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        if (current->frame.data.data) {
            free(current->frame.data.data);
        }
        free(current);
        current = next;
    }

    free(list);
}

void process_frames(FrameList *list, ErrorCallback error_callback) {
    if (!list || !list->head) return;

    external_module_process(list);

    Node *current = list->head;
    while (current) {
        if (!validate_frame(&current->frame)) {
            log_duplicate("Invalid frame detected.");
        }
        current = current->next;
    }
}

