['Here's a C implementation that manages a dynamic array of NICP packet headers with thread-safe access using mutexes and condition variables for synchronization. It handles memory allocation failures gracefully and supports asynchronous data ingestion.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} PacketHeader;

typedef struct {
    PacketHeader *headers;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NICPManager;

void init_nicp_manager(NICPManager *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);

    manager->headers = (PacketHeader *)malloc(manager->capacity * sizeof(PacketHeader));
    if (!manager->headers) {
        perror("Failed to allocate memory for NICP packet headers");
        exit(EXIT_FAILURE);
    }
}

void free_nicp_manager(NICPManager *manager) {
    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond);

    free(manager->headers);
}

int add_packet_header(NICPManager *manager, int packet_id, size_t payload_size) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        PacketHeader *new_headers = realloc(manager->headers, new_capacity * sizeof(PacketHeader));
        if (!new_headers) {
            perror("Failed to reallocate memory for NICP packet headers");
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->headers = new_headers;
        manager->capacity = new_capacity;
    }

    PacketHeader *header = &manager->headers[manager->count++];
    header->packet_id = packet_id;
    header->timestamp = time(NULL);
    header->payload_size = payload_size;

    pthread_cond_signal(&manager->cond);

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void process_packets(NICPManager *manager) {
    while (1) {
        pthread_mutex_lock(&manager->mutex);

        while (manager->count == 0) {
            pthread_cond_wait(&manager->cond, &manager->mutex);
        }

        // Process the first packet
        PacketHeader header = manager->headers[0];
        printf("Processing packet ID %d with payload size %zu\n", header.packet_id, header.payload_size);

        // Shift remaining packets
        memmove(manager->headers, manager->headers + 1, (manager->count - 1) * sizeof(PacketHeader));
        manager->count--;

        pthread_mutex_unlock(&manager->mutex);
    }
}

// Example usage
int main() {
    NICPManager manager;
    init_nicp_manager(&manager, 10);

    // Start a thread to process packets
    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, (void *(*)(void *))process_packets, &manager);

    // Simulate adding packet headers
    for (int i = 0; i < 20; ++i) {
        add_packet_header(&manager, i, rand() % 1024 + 1);
    }

    pthread_join(processor_thread, NULL);
    free_nicp_manager(&manager);

    return 0;
}
```

This code initializes a dynamic array for NICP packet headers and provides thread-safe functions to add and process packets. It uses mutexes and condition variables to manage concurrency and ensure efficient processing under varying loads.']

