    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_key_t thread_local_storage_key;
} PDU_Manager;

void log_event(const char* event) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), event);
}

PDU_Manager *create_pdu_manager(size_t initial_capacity) {
    PDU_Manager *manager = (PDU_Manager *)malloc(sizeof(PDU_Manager));
    if (!manager) return NULL;

    manager->pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_list) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    pthread_key_create(&manager->thread_local_storage_key, NULL);

    manager->capacity = initial_capacity;
    manager->size = 0;

    log_event("PDU Manager created.");

    return manager;
}

void destroy_pdu_manager(PDU_Manager *manager) {
    if (!manager) return;

    free(manager->pdu_list);
    pthread_mutex_destroy(&manager->lock);
    pthread_key_delete(manager->thread_local_storage_key);

    log_event("PDU Manager destroyed.");
    free(manager);
}

int add_pdu(PDU_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!manager || manager->size >= manager->capacity)
        return -1;

    pthread_mutex_lock(&manager->lock);

    int index = manager->size++;
    if (index == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > 50000) {
            log_event("Capacity limit approached, degrading gracefully.");
            new_capacity = 50000;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(manager->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->pdu_list = new_list;
        manager->capacity = new_capacity;
    }

    manager->pdu_list[index] = pdu;

    log_event("PDU added.");

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void update_crcflag(PDU_Manager *manager, size_t index) {
    if (!manager || index >= manager->size)
        return;

    pthread_mutex_lock(&manager->lock);

    manager->pdu_list[index].CRCFLAG = rand() % 2; // Random CRCFLAG

    log_event("PDU CRCFLAG updated.");

    pthread_mutex_unlock(&manager->lock);
}

void *thread_function(void *arg) {
    PDU_Manager *manager = (PDU_MANAGER *)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand() % 100,
                                      .RNTI = rand() % 1000,
                                      .CRC_INDICATION_REL8_TAG = rand() % 50,
                                      .CRCFLAG = rand() % 2 };
    add_pdu(manager, pdu);
    return NULL;
}

void integrate_external_data_source(PDU_Manager *manager) {
    pthread_t threads[10];

    for (int i = 0; i < 10; ++i)
        pthread_create(&threads[i], NULL, thread_function, manager);

    for (int i = 0; i < 10; ++i)
        pthread_join(threads[i], NULL);
}

int main() {
    srand(time(NULL));

    PDU_Manager *manager = create_pdu_manager(1000);
    if (!manager) return -1;

    integrate_external_data_source(manager);

    destroy_pdu_manager(manager);

    return 0;
}
