SessionManager* create_session_manager() {
    SessionManager *manager = malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->sessions = calloc(INITIAL_CAPACITY, sizeof(UserSession));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_session_manager(SessionManager* manager) {
    if (manager) {
        free(manager->sessions);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_session(SessionManager* manager, int userID, const char* sessionToken, const char* ipAddress) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Max sessions reached
    }

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UserSession* new_sessions = realloc(manager->sessions, new_capacity * sizeof(UserSession));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failed
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    UserSession session;
    session.UserID = userID;
    strncpy(session.SessionToken, sessionToken, sizeof(session.SessionToken));
    session.LastActivityTime = time(NULL);
    strncpy(session.IPAddress, ipAddress, sizeof(session.IPAddress));

    manager->sessions[manager->size++] = session;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void update_last_activity_time(SessionManager* manager, int userID) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i].UserID == userID) {
            manager->sessions[i].LastActivityTime = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void print_sessions(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        printf("UserID: %d, Token: %s, Last Activity: %ld, IP: %s\n",
               manager->sessions[i].UserID,
               manager->sessions[i].SessionToken,
               manager->sessions[i].LastActivityTime,
               manager->sessions[i].IPAddress);

        char* metadata = fetch_user_metadata(manager->sessions[i].UserID);
        printf("User Role: %s\n", metadata);
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    SessionManager *manager = create_session_manager();
    if (!manager) return 1;

    add_session(manager, 1, "token123", "192.168.0.1");
    update_last_activity_time(manager, 1);
    print_sessions(manager);

    destroy_session_manager(manager);
    return 0;
}
