// Represents a timestamp for LastActiveTime
using Timestamp = std::chrono::system_clock::time_point;

class UserSession {
public:
    unsigned int UserID;
    unsigned long SessionID;
    Timestamp LastActiveTime;

    UserSession(unsigned int userID, unsigned long sessionID)
        : UserID(userID), SessionID(sessionID),
          LastActiveTime(std::chrono::system_clock::now()) {}

    // Getters for encapsulated fields
    unsigned int getUserID() const { return UserID; }
    unsigned long getSessionID() const { return SessionID; }
    Timestamp getLastActiveTime() const { return LastActiveTime; }

    void updateLastActiveTime() {
        LastActiveTime = std::chrono::system_clock::now();
    }

    // Function to print session details
    void printDetails() const {
        auto time_t = std::chrono::system_clock::to_time_t(LastActiveTime);
        std::cout << "UserID: " << UserID 
                  << ", SessionID: " << SessionID 
                  << ", Last Active Time: " << std::ctime(&time_t);
    }
};

class UserSessionManager {
private:
    std::unordered_map<unsigned long, UserSession> sessions;
    mutable std::mutex mtx;

public:
    // Add a session if it doesn't already exist
    bool addSession(const UserSession& session) {
        std::lock_guard<std::mutex> lock(mtx);
        auto result = sessions.emplace(session.getSessionID(), session);
        return result.second;  // Returns true if the insertion took place
    }

    // Remove a session by SessionID
    bool removeSession(unsigned long sessionID) {
        std::lock_guard<std::mutex> lock(mtx);
        return sessions.erase(sessionID) > 0;
    }

    // Retrieve a session by SessionID
    UserSession* getSession(unsigned long sessionID) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = sessions.find(sessionID);
        if (it != sessions.end()) {
            return &(it->second);
        }
        return nullptr;
    }

    // Iterate over and print all sessions
    void printAllSessions() const {
        std::lock_guard<std::mutex> lock(const_cast<std::mutex&>(mtx));
        for (const auto& pair : sessions) {
            pair.second.printDetails();
        }
    }

    // Retrieve active sessions within a time window
    std::vector<UserSession> getActiveSessions(Timestamp startTime, Timestamp endTime) const {
        std::lock_guard<std::mutex> lock(const_cast<std::mutex&>(mtx));
        std::vector<UserSession> activeSessions;
        for (const auto& pair : sessions) {
            if (pair.second.getLastActiveTime() >= startTime && 
                pair.second.getLastActiveTime() <= endTime) {
                activeSessions.push_back(pair.second);
            }
        }
        return activeSessions;
    }
};

int main() {
    UserSessionManager manager;

    // Example usage
    UserSession session1(1, 1001);
    UserSession session2(2, 1002);

    manager.addSession(session1);
    manager.addSession(session2);

    manager.printAllSessions();

    auto now = std::chrono::system_clock::now();
    Timestamp startTime = now - std::chrono::hours(1);
    Timestamp endTime = now + std::chrono::hours(1);

    auto activeSessions = manager.getActiveSessions(startTime, endTime);
    for (const auto& session : activeSessions) {
        session.printDetails();
    }

    return 0;
}
```

### Explanation of Trade-offs:
- **Thread Safety**: The use of `std::mutex` ensures that the operations on the sessions map are thread-safe.
- **Efficiency**: An unordered_map is used for O(1) average time complexity for insertion, deletion, and retrieval by SessionID.
- **Maintainability**: The code structure is modular with clear separation between session management and session representation.']

