        log_error("No valid CRC flags found.");
        return NULL;
    }

    fseek(file, 0, SEEK_SET); // Reset file pointer to start

    indication_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indication_array) {
