#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_STRUCTS 1000000

typedef struct {
    uint8_t* buffer;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    // Placeholder for actual fields
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        uint8_t CRCFLAG; // Example field
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    MemoryPool* pool;
    size_t element_size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t resize_lock;
    pthread_cond_t cond_var;
} DynamicNFAPIArray;

MemoryPool create_memory_pool(size_t element_size, size_t initial_capacity) {
    MemoryPool pool;
    pool.size = element_size * initial_capacity;
    pool.buffer = (uint8_t*)malloc(pool.size);
    if (!pool.buffer) {
        perror("Failed to allocate memory for pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool.lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->buffer);
    pthread_mutex_destroy(&pool->lock);
}

DynamicNFAPIArray* create_dynamic_array(size_t element_size, size_t initial_capacity) {
    DynamicNFAPIArray* array = (DynamicNFAPIArray*)malloc(sizeof(DynamicNFAPIArray));
    if (!array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }

    array->element_size = element_size;
    array->capacity = initial_capacity;
    array->pool = &create_memory_pool(element_size, initial_capacity);

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)array->pool->buffer;
    pthread_mutex_init(&array->resize_lock, NULL);
    pthread_cond_init(&array->cond_var, NULL);

    return array;
}

void destroy_dynamic_array(DynamicNFAPIArray* array) {
    if (!array) return;

    destroy_memory_pool(array->pool);
    free(array);
}

void resize_dynamic_array_if_needed(DynamicNFAPIArray* array, size_t new_size) {
    pthread_mutex_lock(&array->resize_lock);

    if (new_size > array->capacity) {
        size_t new_capacity = new_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data,
                                                      new_capacity * array->element_size);
        if (!new_data) {
            perror("Failed to reallocate memory for dynamic array");
            exit(EXIT_FAILURE);
        }

        size_t old_size = array->capacity * array->element_size;
        memmove(new_data + (new_capacity - array->capacity), new_data, old_size);

        pthread_mutex_lock(&array->pool->lock);
        array->pool->buffer += old_size;
        pthread_mutex_unlock(&array->pool->lock);

        array->data = new_data;
        array->capacity = new_capacity;
    }

    pthread_cond_broadcast(&array->cond_var);
    pthread_mutex_unlock(&array->resize_lock);
}

void initialize_and_populate_array(DynamicNFAPIArray* array, size_t num_elements) {
    resize_dynamic_array_if_needed(array, num_elements);

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&array->pool->lock);

        NFAPI_CRC_INDICATION_PDU_T* elem = &array->data[i];
        elem->RX_UE_INFORMATION_TAG = rand(); // Example initialization
        elem->RNTI = rand();
        elem->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        pthread_mutex_unlock(&array->pool->lock);

        // Placeholder for logging and performance monitoring integration
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicNFAPIArray* array = create_dynamic_array(sizeof(NFAPI_CRC_INDICATION_PDU_T), 1024);

    initialize_and_populate_array(array, MAX_STRUCTS);

    destroy_dynamic_array(array);
    return 0;
}
```

