        successful_count++;
        pthread_mutex_unlock(lock);
    }

    external_log("Successfully created structures: ");
    printf("%zu\n", successful_count);

    return list;

cleanup:
    for (size_t j = 0; j <= i; ++j) {
        if (list[j]) free(list[j]);
    }
    free(list);
    pthread_mutex_unlock(lock);
    external_log("Error encountered, cleaned up resources");
    return NULL;
}

