#include <string.h>
#include <pthread.h>

typedef struct {
    // Placeholder for LTE_RRC_CU_MESSAGE fields
} LTE_RRC_CU_MESSAGE;

typedef enum {
    CAUSE_CODE_SUCCESS,
    CAUSE_CODE_ERROR,
    CAUSE_CODE_RESTART
} CAUSE_CODE;

typedef struct {
    LTE_RRC_CU_MESSAGE message;
    CAUSE_CODE cause_code;
} LTE_ENB_RRC_MESSAGE;

typedef struct Node {
    LTE_ENB_RRC_MESSAGE data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} MessageList;

MessageList* create_message_list() {
    MessageList* list = (MessageList*)malloc(sizeof(MessageList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_message_list(MessageList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_message(MessageList* list, LTE_ENB_RRC_MESSAGE message) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = message;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_cause_code(MessageList* list, size_t index, CAUSE_CODE cause_code) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    current->data.cause_code = cause_code;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void process_events(MessageList* list, const char** events, size_t num_events) {
    for (size_t i = 0; i < num_events; i++) {
        CAUSE_CODE new_cause_code = CAUSE_CODE_SUCCESS;

        if (strcmp(events[i], "PING") == 0 || strcmp(events[i], "PONG") == 0) {
            // Example logic: update all cause codes to SUCCESS
            pthread_mutex_lock(&list->lock);
            Node* current = list->head;
            while (current != NULL) {
                current->data.cause_code = CAUSE_CODE_SUCCESS;
                current = current->next;
            }
            pthread_mutex_unlock(&list->lock);
        } else if (strcmp(events[i], "RESTART") == 0) {
            new_cause_code = CAUSE_CODE_RESTART;
        }

        // Update the first message's cause code as an example
        update_cause_code(list, 0, new_cause_code);
    }
}

void iterate_messages(MessageList* list, void (*callback)(LTE_ENB_RRC_MESSAGE*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void print_message(LTE_ENB_RRC_MESSAGE* message) {
    // Placeholder for printing logic
    printf("Message with cause code: %d\n", message->cause_code);
}

int main() {
    MessageList* list = create_message_list();

    LTE_ENB_RRC_MESSAGE msg1 = {{}, CAUSE_CODE_ERROR};
    add_message(list, msg1);

    const char* events[] = {"PING", "RESTART", "PONG"};
    process_events(list, events, 3);

    iterate_messages(list, print_message);

    destroy_message_list(list);
    return 0;
}
```

