int nicp_array_init(NICPArray *array, size_t initial_capacity) {
    if (initial_capacity == 0) return -1;

    array->packets = (NICPPacketHeader *)calloc(initial_capacity, sizeof(NICPPacketHeader));
    if (!array->packets) return -1;

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return 0;
}

int nicp_array_resize(NICPArray *array) {
    size_t new_capacity = array->capacity * 2;
    NICPPacketHeader *new_packets = (NICPPacketHeader *)realloc(array->packets, new_capacity * sizeof(NICPPacketHeader));
    if (!new_packets) return -1;

    array->packets = new_packets;
    array->capacity = new_capacity;
    return 0;
}

int nicp_array_add_packet(NICPArray *array, uint32_t packet_id, size_t payload_size) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        int resize_result = nicp_array_resize(array);
        if (resize_result != 0) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    NICPPacketHeader *packet = &array->packets[array->count++];
    packet->packet_id = packet_id;
    packet->timestamp = time(NULL);
    packet->payload_size = payload_size;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

size_t nicp_array_count(const NICPArray *array) {
    pthread_mutex_lock((pthread_mutex_t *)&array->lock);
    size_t count = array->count;
    pthread_mutex_unlock((pthread_mutex_t *)&array->lock);
    return count;
}

void nicp_array_free(NICPArray *array) {
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}

// Serialization function
size_t serialize_packet(const NICPPacketHeader *packet, uint8_t *buffer, size_t buffer_size) {
    if (!packet || !buffer || buffer_size < sizeof(NICPPacketHeader)) return 0;

    // Serialize the packet data into the buffer
    *((uint32_t *)buffer) = packet->packet_id;
    memcpy(buffer + sizeof(uint32_t), &packet->timestamp, sizeof(time_t));
    memcpy(buffer + sizeof(uint32_t) + sizeof(time_t), &packet->payload_size, sizeof(size_t));

    return sizeof(NICPPacketHeader);
}

// Deserialization function
int deserialize_packet(const uint8_t *buffer, size_t buffer_size, NICPPacketHeader *packet) {
    if (!packet || !buffer || buffer_size < sizeof(NICPPacketHeader)) return -1;

    // Deserialize the packet data from the buffer
    packet->packet_id = *((uint32_t *)buffer);
    memcpy(&packet->timestamp, buffer + sizeof(uint32_t), sizeof(time_t));
    memcpy(&packet->payload_size, buffer + sizeof(uint32_t) + sizeof(time_t), sizeof(size_t));

    return 0;
}
