    if (!manager->headers) {
        perror("Failed to allocate memory for packet headers");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < NUM_NETWORK_INTERFACES; ++i) {
        manager->is_paused[i] = 0;
    }
}

// Free NICP Manager resources.
void free_nicp_manager(NICPManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
    free(manager->headers);
}

// Asynchronously ingest packet into the manager.
int ingest_packet_async(NICPManager *manager, int packet_id, size_t payload_size) {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->max_count || manager->is_paused[0]) { // Assuming interface 0 for simplicity.
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    PacketHeader *header = &manager->headers[manager->count++];
    header->packet_id = packet_id;
    header->timestamp = now;
    header->payload_size = payload_size;

    // Adjust max count if necessary.
    adjust_max_count(manager);

    pthread_cond_signal(&manager->cond_var);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Dynamically adjust the maximum number of packets based on system resources.
void adjust_max_count(NICPManager *manager) {
    // Example heuristic: scale max count up or down based on current utilization.
    double load_factor = (double)manager->count / manager->max_count;

    if (load_factor > 0.8 && manager->max_count < 10000) { // Arbitrary upper limit for scaling.
        size_t new_max = manager->max_count * 2;
        PacketHeader *new_headers = realloc(manager->headers, new_max * sizeof(PacketHeader));
        if (!new_headers) {
            perror("Failed to reallocate memory for packet headers");
            exit(EXIT_FAILURE);
        }
        manager->headers = new_headers;
        manager->max_count = new_max;
    } else if (load_factor < 0.3 && manager->max_count > INITIAL_MAX_COUNT) {
        size_t new_max = manager->max_count / 2;
        PacketHeader *new_headers = realloc(manager->headers, new_max * sizeof(PacketHeader));
        if (!new_headers) {
            perror("Failed to reallocate memory for packet headers");
            exit(EXIT_FAILURE);
        }
        manager->headers = new_headers;
        manager->max_count = new_max;
    }
}

// Process packets based on their timestamps.
void process_packets(NICPManager *manager) {
    while (1) {
        pthread_mutex_lock(&manager->lock);

        while (manager->count == 0 && !pthread_cond_wait(&manager->cond_var, &manager->lock)) {
            // Wait for packets to be available or a signal to wake up.
        }

        if (manager->is_paused[0]) { // Assume processing on interface 0 as example
            pthread_mutex_unlock(&manager->lock);
            continue;
        }

        qsort(manager->headers, manager->count, sizeof(PacketHeader), compare_packets);

        for (size_t i = 0; i < manager->count; ++i) {
            // Process packet headers.
            printf("Processing Packet ID: %d\n", manager->headers[i].packet_id);
        }

        pthread_mutex_unlock(&manager->lock);
    }
}

// Comparison function for sorting packets by timestamp.
int compare_packets(const void *a, const void *b) {
    PacketHeader *headerA = (PacketHeader *)a;
    PacketHeader *headerB = (PacketHeader *)b;
    return headerA->timestamp - headerB->timestamp;
}

// Pause packet processing for a specific network interface.
void pause_processing_for_interface(NICPManager *manager, int interface_idx) {
    pthread_mutex_lock(&manager->lock);
    manager->is_paused[interface_idx] = 1;
    pthread_mutex_unlock(&manager->lock);
}

// Resume packet processing for a specific network interface.
void resume_processing_for_interface(NICPManager *manager, int interface_idx) {
    pthread_mutex_lock(&manager->lock);
    manager->is_paused[interface_idx] = 0;
    pthread_cond_signal(&manager->cond_var); // Signal to process queued packets.
    pthread_mutex_unlock(&manager->lock);
}

// Example main function to demonstrate usage.
int main() {
    NICPManager manager;
    init_nicp_manager(&manager);

    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, (void *)process_packets, &manager);

    // Simulate packet ingestion.
    for (int i = 0; i < 100; ++i) {
        ingest_packet_async(&manager, i, rand() % 1024);
    }

    pause_processing_for_interface(&manager, 0);
    resume_processing_for_interface(&manager, 0);

    pthread_join(processor_thread, NULL);
    free_nicp_manager(&manager);

    return 0;
}
