#define MAX_PDUS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int sequence_number;
    // Placeholder for PDCP_PDU structure
    char *pdcpData;  // Example member
    int SecurityControl;
    NFAPI_CRC_INDICATION_PDU_T *crcIndications;
    size_t crcCount;
} MAC_PDU;

typedef struct {
    MAC_PDU pdus[MAX_PDUS];
    size_t count;
    pthread_mutex_t lock;
} PDUManager;

// Initialize PDU Manager
void initPDUManager(PDUManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Add or update a MAC_PDU based on sequence number
int addOrUpdateMAC_PDU(PDUManager *manager, int seqNum, const char *pdcpData, int securityControl, NFAPI_CRC_INDICATION_PDU_T *crcIndications, size_t crcCount) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pdus[i].sequence_number == seqNum) {
            // Update existing PDU
            free(manager->pdus[i].pdcpData);
            manager->pdus[i].pdcpData = strdup(pdcpData);
            manager->pdus[i].SecurityControl = securityControl;

            free(manager->pdus[i].crcIndications);
            manager->pdus[i].crcCount = crcCount;
            manager->pdus[i].crcIndications = malloc(crcCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(manager->pdus[i].crcIndications, crcIndications, crcCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    if (manager->count < MAX_PDUS) {
        // Add new PDU
        MAC_PDU *newPdu = &manager->pdus[manager->count++];
        newPdu->sequence_number = seqNum;
        newPdu->pdcpData = strdup(pdcpData);
        newPdu->SecurityControl = securityControl;

        newPdu->crcCount = crcCount;
        newPdu->crcIndications = malloc(crcCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(newPdu->crcIndications, crcIndications, crcCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        pthread_mutex_unlock(&manager->lock);
        return 0; // Success
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: PDU Manager is full
}

// Retrieve a MAC_PDU by sequence number
MAC_PDU* getMAC_PDU(PDUManager *manager, int seqNum) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pdus[i].sequence_number == seqNum) {
            MAC_PDU *pdu = &manager->pdus[i];
            pthread_mutex_unlock(&manager->lock);
            return pdu;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Cleanup PDU Manager
void cleanupPDUManager(PDUManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdus[i].pdcpData);
        free(manager->pdus[i].crcIndications);
    }
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    PDUManager manager;
    initPDUManager(&manager);

    NFAPI_CRC_INDICATION_PDU_T crcData[2] = {{1, 1234, {0}}, {2, 5678, {1}}};

    addOrUpdateMAC_PDU(&manager, 101, "Sample PDCP Data", 5, crcData, 2);

    MAC_PDU *retrievedPdu = getMAC_PDU(&manager, 101);
    if (retrievedPdu != NULL) {
        printf("Retrieved PDU: Sequence %d\n", retrievedPdu->sequence_number);
    }

    cleanupPDUManager(&manager);

    return 0;
}
