```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define MEMORY_LIMIT_BYTES (5 * 1024 * 1024) // 5 MB per thread
#define PDU_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG; // Assume this is an enum or bitfield
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t element_size;
    size_t total_elements;
    void* memory_pool;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {0};

void initialize_memory_pool(size_t element_size, size_t total_elements) {
    pthread_mutex_init(&pool.lock, NULL);
    pool.element_size = element_size;
    pool.total_elements = total_elements;

    if (element_size * total_elements > MEMORY_LIMIT_BYTES) {
        fprintf(stderr, "Memory limit exceeded\n");
        exit(1);
    }

    pool.memory_pool = malloc(element_size * total_elements);
    if (!pool.memory_pool) {
        perror("Failed to allocate memory pool");
        exit(1);
    }
}

void destroy_memory_pool() {
    free(pool.memory_pool);
    pthread_mutex_destroy(&pool.lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu_from_pool() {
    pthread_mutex_lock(&pool.lock);

    static size_t index = 0;

    if (index >= pool.total_elements) {
