        return NULL; // No more space
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = 
        (NFAPI_CRC_INDICATION_PDU_T*)((char*)pool.memory_pool + index * pool.element_size);
    index++;

    pthread_mutex_unlock(&pool.lock);
    return pdu;
}

