    size_t num_threads = MAX_THREADS;  // Ideally determined dynamically based on system resources
    size_t chunk_size = data->num_pdus / num_threads;
    start_index = (pthread_self() % num_threads) * chunk_size;
    end_index = ((pthread_self() % num_threads + 1) * chunk_size);
    if ((pthread_self() % num_threads + 1) == num_threads) {
        end_index = data->num_pdus; // Ensure last thread processes remaining elements
    }

    uint16_t existing_rnti = 0;
    for (size_t i = start_index; i < end_index; ++i) {
