        return -1;
    }

    getrusage(RUSAGE_SELF, &usage_before);
    time(&start_time);

    fgets(path, sizeof(path), fp);
    pclose(fp);

    time(&end_time);
    getrusage(RUSAGE_SELF, &usage_after);

    double compile_time = difftime(end_time, start_time);
    printf("Compilation time: %f seconds\n", compile_time);
    printf("Memory usage before: %ld KB\n", usage_before.ru_maxrss / 1024);
    printf("Memory usage after: %ld KB\n", usage_after.ru_maxrss / 1024);

    return WEXITSTATUS(pclose(fp));
}

int main() {
    CRC_INDICATION_REL8_TAG crcTag = {0x12345678};
    unsigned int rnti = 1001;
    unsigned int seed = 42;

    NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(rnti, crcTag, seed);
    if (pdu != NULL) {
        printf("PDU created successfully\n");
        cleanup_structure(pdu);
    } else {
        fprintf(stderr, "Failed to create PDU\n");
    }

    int exit_code = compile_rust_code();
    printf("Rust compilation exit code: %d\n", exit_code);

    return 0;
}
```

