#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging function prototype
void log_pdu_creation(NFAPI_CRC_INDICATION_PDU_T* pdu);

// Memory pool structure
typedef struct {
    size_t element_size;
    unsigned char* memory_pool;
    unsigned char* free_list_head;
    pthread_mutex_t lock;
} MemoryPool;

// Initialize the memory pool
int initialize_memory_pool(MemoryPool* pool, size_t element_size, int num_elements) {
    pool->element_size = element_size;
    pool->memory_pool = (unsigned char*)malloc(element_size * num_elements);
    if (!pool->memory_pool) return -1; // Memory allocation failed

    unsigned char** free_list = (unsigned char**)malloc(num_elements * sizeof(unsigned char*));
    if (!free_list) {
        free(pool->memory_pool);
        return -1;
    }

    for (int i = 0; i < num_elements; ++i) {
        free_list[i] = pool->memory_pool + i * element_size;
        if (i > 0)
            *(unsigned char**)(free_list[i-1]) = free_list[i];
    }
    pool->free_list_head = free_list[0];
    *(unsigned char**)(&free_list[num_elements-1]) = NULL;

    pthread_mutex_init(&pool->lock, NULL);
    free(free_list);

    return 0;
}

// Allocate memory from the pool
void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->free_list_head == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is exhausted
    }

    void* ptr = pool->free_list_head;
    pool->free_list_head = *(unsigned char**)pool->free_list_head;
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

// Free memory back to the pool
void deallocate_to_pool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    *(unsigned char**)ptr = pool->free_list_head;
    pool->free_list_head = (unsigned char*)ptr;
    pthread_mutex_unlock(&pool->lock);
}

// Create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(int n, int max_entries) {
    if (n > max_entries || n <= 0) return NULL;

    MemoryPool pool;
    if (initialize_memory_pool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T), n) != 0)
        return NULL; // Failed to initialize memory pool

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        free(pool.memory_pool);
        pthread_mutex_destroy(&pool.lock);
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool(&pool);
        if (!pdu) break;

        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 1000;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 500;
        pdu->CRCFLAG = rand() % 2; // Random CRCFLAG

        pdu_list[i] = *pdu;

        log_pdu_creation(&pdu_list[i]); // Log creation for auditing
    }

    pthread_mutex_destroy(&pool.lock);
    free(pool.memory_pool);

    return pdu_list;
}

// Example logging function implementation (to be replaced with actual logging mechanism)
void log_pdu_creation(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("Created PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);
}

// Usage example
int main() {
    int n = 100;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_pdu_list(n, MAX_ENTRIES);

    if (pdu_list) {
        printf("Successfully created %d PDUs.\n", n);
        free(pdu_list); // Cleanup after usage
    } else {
        printf("Failed to create PDU list.\n");
    }

    return 0;
}
```

