} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFAPI_List;

// Function to initialize the list
NFAPI_List* create_list() {
    NFAPI_List* list = (NFAPI_List*)malloc(sizeof(NFAPI_List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new PDU structure
int add_pdu(NFAPI_List* list, unsigned long rx_tag, unsigned int rnti) {
    if (!list || rx_tag == 0 || rnti == 0) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    srand(time(NULL) ^ rand()); // Seed with more entropy
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to iterate and update each session's status
void update_sessions(NFAPI_List* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        // Simulate network event updates
        // For example, toggle CRCFLAG for demonstration purposes
        current->data.CRCFLAG ^= 1;

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to clear the list and free memory
void clear_list(NFAPI_List* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to handle potential network disruptions
void handle_network_event(NFAPI_List* list) {
    // Implement retry logic, logging, or other mechanisms here
    // This is a placeholder for handling external data source updates
    update_sessions(list); // Simulate an update from network event
}

int main() {
    int N = 10; // Example input
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N must be positive.\n");
        return -1;
    }

    NFAPI_List* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return -1;
    }

    for (int i = 0; i < N; ++i) {
        add_pdu(list, rand() % 1000000, rand() % 10000);
    }

    update_sessions(list);
    handle_network_event(list);

    clear_list(list);
    return 0;
}
