        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread\n");
            free(pdu_array);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
    }

    // Destroy mutex after use
