    unsigned int RNTI;
    unsigned char RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Constants for valid CRCFLAG range.
#define MIN_VALID_CRCFLAG 0x00
#define MAX_VALID_CRCFLAG 0xFF

// Error codes
typedef enum {
    SUCCESS = 0,
    MEMORY_ALLOCATION_FAILURE,
    INVALID_RRB_COUNT
} ErrorCode;

void log_message(const char *message) {
    printf("%s\n", message);
}

ErrorCode create_nfa_pdu_list(NFAPI_CRC_INDICATION_PDU_T **nfa_pdu_list, size_t num_rrbs, bool enable_logging) {
    if (num_rrbs <= 0) {
        return INVALID_RRB_COUNT;
    }

    *nfa_pdu_list = malloc(num_rrbs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfa_pdu_list == NULL) {
        return MEMORY_ALLOCATION_FAILURE;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_rrbs; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*nfa_pdu_list)[i];

        pdu->RNTI = rand() % 65536; // Random RNTI, assuming it fits in unsigned short
        pdu->RX_UE_INFORMATION_TAG = rand() % 256; // Assuming a byte for RX tag

        do {
            pdu->crc_tag.CRCFLAG = rand() % (MAX_VALID_CRCFLAG - MIN_VALID_CRCFLAG + 1) + MIN_VALID_CRCFLAG;
        } while (pdu->crc_tag.CRCFLAG == 0 && enable_logging); // Ensure valid CRCFLAG

        if (enable_logging) {
            log_message("Generated NFAPI_CRC_INDICATION_PDU_T with RNTI: ");
            printf("%u, RX_UE_INFORMATION_TAG: %d, CRCFLAG: %u\n", pdu->RNTI, pdu->RX_UE_INFORMATION_TAG, pdu->crc_tag.CRCFLAG);
        }

        // Avoid consecutive identical RNTIs
        if (i > 0 && (*nfa_pdu_list)[i].RNTI == (*nfa_pdu_list)[i - 1].RNTI) {
            --i; // Reassign the current index with a new RNTI to avoid collision
        }
    }

    return SUCCESS;
}

// Usage Example (in main or test function)
