#define MAX_ENTRIES 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

unsigned int crcFlagFromRNTI(unsigned int rnti) {
    return (rnti * 2654435761u) & 0xFFFFFFFF; // Example hash function
}

void populatePduList(NFAPI_CRC_INDICATION_PDU_T* pduList, size_t numEntries) {
    srand(time(NULL));
    for (size_t i = 0; i < numEntries; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pduList[i].RNTI = rand() % 10000;
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pduList[i].CRCFLAG = crcFlagFromRNTI(pduList[i].RNTI);
    }
}

typedef struct {
    unsigned int parent;
    unsigned int rank;
} UnionFindNode;

void makeSet(UnionFindNode* uf, size_t numEntries) {
    for (size_t i = 0; i < numEntries; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
}

unsigned int find(UnionFindNode* uf, unsigned int i) {
    if (uf[i].parent != i) {
        uf[i].parent = find(uf, uf[i].parent);
    }
    return uf[i].parent;
}

void unionSets(UnionFindNode* uf, unsigned int xRoot, unsigned int yRoot) {
    if (uf[xRoot].rank < uf[yRoot].rank) {
        uf[xRoot].parent = yRoot;
    } else if (uf[xRoot].rank > uf[yRoot].rank) {
        uf[yRoot].parent = xRoot;
    } else {
        uf[yRoot].parent = xRoot;
        uf[xRoot].rank++;
    }
}

void checkDisjointPairs(NFAPI_CRC_INDICATION_PDU_T* pduList, size_t numEntries) {
    if (numEntries == 0) return;

    UnionFindNode* uf = malloc(numEntries * sizeof(UnionFindNode));
    makeSet(uf, numEntries);

    for (size_t i = 0; i < numEntries - 1; ++i) {
        unsigned int xRoot = find(uf, pduList[i].RNTI);
        for (size_t j = i + 1; j < numEntries; ++j) {
            unsigned int yRoot = find(uf, pduList[j].RNTI);
            if (xRoot != yRoot) {
                unionSets(uf, xRoot, yRoot);
            }
        }
    }

    for (size_t i = 0; i < numEntries - 1; ++i) {
        unsigned int xRoot = find(uf, pduList[i].RNTI);
        for (size_t j = i + 1; j < numEntries; ++j) {
            if (find(uf, pduList[j].RNTI) != xRoot) {
                printf("Disjoint pair: RNTI %u and RNTI %u\n", pduList[i].RNTI, pduList[j].RNTI);
            }
        }
    }

    free(uf);
}

void* backgroundTask(void* arg) {
    while (1) {
        // Simulate checking external data sources
        sleep(rand() % 5 + 1); // Sleep for a random period between 1 and 5 seconds
        printf("Background task checking updates...\n");
        // Logic to update RNTI distribution or handle new data can be added here
    }
}

void generateNfarcrcPduList(size_t numEntries) {
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(numEntries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) return;

    populatePduList(pduList, numEntries);

    pthread_t bgThread;
    pthread_create(&bgThread, NULL, backgroundTask, NULL);
    pthread_detach(bgThread); // Detach the thread to handle its own cleanup

    checkDisjointPairs(pduList, numEntries);

    free(pduList);
}

int main() {
    size_t numEntries = 100; // Example number of entries
    generateNfarcrcPduList(numEntries);
    return 0;
}
```

This code dynamically creates a list of `NFAPI_CRC_INDICATION_PDU_T` structures, populates them with random data, and uses a Union-Find structure to identify disjoint pairs. A background task simulates checking for updates in the RNTI distribution.']

