// Configuration settings
#define CONFIG_MAX_STRUCTURES 1000
#define CONFIG_LOG_FILE "error.log"
#define ENV_DIRECTORY_PATH "STRUCTURE_STORAGE_DIR"

// Global variables for configuration and synchronization
static size_t max_structures = CONFIG_MAX_STRUCTURES;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
