void create_directory(const char *path);
void log_message(int verbosity, const char *message);

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_crc_indication_pdu_list(size_t num_structures) {
    pthread_mutex_lock(&config_lock);

    if (num_structures > max_structures) {
        pthread_mutex_unlock(&config_lock);
        fprintf(stderr, "Error: Requested number of structures exceeds configuration limit.\n");
        return NULL;
    }

    pthread_mutex_unlock(&config_lock);

    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Memory allocation failed");
        return NULL;
    }

