        structures[i].RNTI = rand() % UINT32_MAX;
        structures[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
    }

    return structures;
}

void cleanup_resources(NFAPI_CRC_INDICATION_PDU_T *structures) {
    if (structures) {
        free(structures);
    }
}

