    } else {
        log_message(0, "Structures created successfully.");
    }

    // Cleanup resources
    cleanup_resources(structures);

    return 0;
}

void set_environment_directory(const char *path) {
    pthread_mutex_lock(&log_lock);

    if (setenv(ENV_DIRECTORY_PATH, path, 1) != 0) {
        perror("Failed to set environment variable");
    } else {
        create_directory(path); // Ensure the directory exists
    }

    pthread_mutex_unlock(&log_lock);
}

void create_directory(const char *path) {
    // Implementation of directory creation logic
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        perror("Failed to create directory");
    }
}

void log_message(int verbosity, const char *message) {
    pthread_mutex_lock(&log_lock);

    FILE *log_file = fopen(CONFIG_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        pthread_mutex_unlock(&log_lock);
        return;
    }

    fprintf(log_file, "Verbosity %d: %s\n", verbosity, message);
    fclose(log_file);

    pthread_mutex_unlock(&log_lock);
}
