#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTIS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *rnti_pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned int rnti_failures;
    unsigned int reset_threshold;
    time_t last_reset_time;
} RNTIManager;

static const unsigned int PRIME_RNTI_BASE = 1001; // Start from a prime to help spread hashes
static const size_t INITIAL_CAPACITY = 1024;

// Initialize the RNTI manager
RNTIManager* rnti_manager_init(size_t initial_capacity, unsigned int reset_threshold) {
    RNTIManager *manager = malloc(sizeof(RNTIManager));
    if (!manager) return NULL;

    manager->rnti_pool = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->rnti_pool) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->rnti_failures = 0;
    manager->reset_threshold = reset_threshold;
    manager->last_reset_time = time(NULL);

    return manager;
}

// Resize the RNTI pool if needed
static int resize_rnti_pool(RNTIManager *manager) {
    size_t new_capacity = (manager->capacity < MAX_RNTIS / 2) ? manager->capacity * 2 : MAX_RNTIS;

    NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(manager->rnti_pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pool) {
        return -1; // Failed to resize
    }

    memset(new_pool + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    manager->rnti_pool = new_pool;
    manager->capacity = new_capacity;

    return 0;
}

// Generate a random CRC flag
static unsigned char generate_crc_flag() {
    return rand() & 1; // Randomly set to 0 or 1
}

// Get a unique RNTI from the pool
NFAPI_CRC_INDICATION_PDU_T* get_unique_rnti(RNTIManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity && resize_rnti_pool(manager) < 0) {
        manager->rnti_failures++;
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    unsigned int rnti = PRIME_RNTI_BASE + rand() % MAX_RNTIS;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->rnti_pool[i].RNTI == rnti)
            goto retry;
    }

    // Assign RNTI and CRC flag
    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->rnti_pool[manager->count++];
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_crc_flag();

    pthread_mutex_unlock(&manager->lock);
    return pdu;

retry:
    manager->rnti_failures++;
    pthread_mutex_unlock(&manager->lock);

    // Retry after some delay or additional logic to avoid busy waiting
    return get_unique_rnti(manager); 
}

// Reset the RNTI pool periodically based on time threshold
void rnti_pool_reset(RNTIManager *manager) {
    pthread_mutex_lock(&manager->lock);

    time_t current_time = time(NULL);
    if (difftime(current_time, manager->last_reset_time) >= manager->reset_threshold || manager->rnti_failures > manager->capacity / 10) {
        memset(manager->rnti_pool, 0, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->count = 0;
        manager->last_reset_time = current_time;
        manager->rnti_failures = 0;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Clean up the RNTI manager
void rnti_manager_cleanup(RNTIManager *manager) {
    if (manager) {
        free(manager->rnti_pool);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
