int rtni_is_used(unsigned int* used_rtnis, unsigned int rnti, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (used_rtnis[i] == rnti) {
            return 1;
        }
    }
    return 0;
}

void update_used_rtnis(unsigned int* used_rtnis, unsigned int new_rnti, size_t* count) {
