// Function prototype
int manage_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t n);

// Implementation of the function
int manage_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t n) {
    if (!array || n == 0) return -1; // Invalid input

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) return -2; // Memory allocation failure

    int crc_flag_frequencies[256] = {0};  // Assuming CRCFLAG is a byte value
    RNTI_TYPE used_rntis[n];
    memset(used_rntis, 0, n * sizeof(RNTI_TYPE));

    srand((unsigned)time(NULL));  // Seed for random number generation

    int unique_rnti_count = 0;
    for (size_t i = 0; i < n; ++i) {
        (*array)[i].rx_ue_info_tag.value = rand() % 100;  // Simulate external data source delay

        RNTI_TYPE rnti;
        do {
            rnti = rand();  // Generate a random RNTI
        } while (binary_search(used_rntis, unique_rnti_count, rnti));

        (*array)[i].rnti = rnti;
        used_rntis[unique_rnti_count++] = rnti;

        int crc_flag = rand() % 256; // Random CRCFLAG
        (*array)[i].crc_indication_rel8_tag.CRCFLAG = crc_flag;

        if (crc_flag_frequencies[crc_flag] < INT_MAX) {
            crc_flag_frequencies[crc_flag]++;
        } else {
            printf("CRCFLAG frequency overflow detected for value: %d\n", crc_flag);
        }
    }

    // Optional: Return frequencies or other statistics to caller, perhaps via additional parameters
    return 0; // Success
}

// Helper function to check if an RNTI is already used
int binary_search(RNTI_TYPE *array, size_t count, RNTI_TYPE target) {
    int low = 0;
    int high = (int)count - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (array[mid] == target)
            return 1; // Found
        else if (array[mid] < target)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return 0; // Not found
}
