typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG; // Assuming 1 byte for CRC indication flag
    unsigned char metadata[MD5_DIGEST_LENGTH]; // MD5 hash size
} NAS_PDU;

NAS_PDU* generateNfareWithMetadata(int N, const char *metadataStr) {
    if (N <= 0 || !metadataStr) {
        return NULL;
    }

    // Allocate memory for the NAS PDU structures
    NAS_PDU *nasPdus = malloc(N * sizeof(NAS_PDU));
    if (!nasPdus) {
        return NULL; // Failed to allocate memory
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Compute MD5 hash of metadataStr
    unsigned char md5hash[MD5_DIGEST_LENGTH];
    MD5((const unsigned char*)metadataStr, strlen(metadataStr), md5hash);

    for (int i = 0; i < N; ++i) {
        NAS_PDU *pdu = &nasPdus[i];

        // Initialize the RX_UE_INFORMATION_TAG and RNTI with some logic or random values
        pdu->RX_UE_INFORMATION_TAG = rand() % UINT_MAX;
        pdu->RNTI = rand() % UINT_MAX;

        // Randomly set CRCFLAG
        pdu->CRCFLAG = rand() % 2; // Either 0 or 1

        // Store the computed MD5 hash in metadata
        memcpy(pdu->metadata, md5hash, MD5_DIGEST_LENGTH);
    }

    return nasPdus;
}
