} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with given data
Node* create_node(int rx_ue_tag, int rnti) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }

    newNode->data.RX_UE_INFORMATION_TAG = rx_ue_tag;
    newNode->data.RNTI = rnti;
    // Set CRC_INDICATION_REL8_TAG based on some logic or external source
    newNode->data.CRC_INDICATION_REL8_TAG = rand() % 100; // Example value

    // Randomly set the CRCFLAG
    srand(time(NULL) ^ (unsigned int)newNode);
    newNode->data.CRCFLAG = rand() % 2;

    newNode->next = NULL;
    return newNode;
}

// Function to check if a node with given RX_UE_INFORMATION_TAG and RNTI exists
int node_exists(Node* head, int rx_ue_tag, int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == rx_ue_tag && 
            current->data.RNTI == rnti) {
            return 1; // Node exists
        }
        current = current->next;
    }
    return 0; // Node does not exist
}

// Function to add a node to the linked list if it's unique
int add_node(Node** head, int rx_ue_tag, int rnti) {
    if (node_exists(*head, rx_ue_tag, rnti)) {
        printf("Node with RX_UE_INFORMATION_TAG %d and RNTI %d already exists.\n", 
               rx_ue_tag, rnti);
        return 0; // Node already exists
    }

    Node* newNode = create_node(rx_ue_tag, rnti);
    if (!newNode) {
        return -1; // Memory allocation failed
    }

    newNode->next = *head;
    *head = newNode;
    return 0;
}

// Function to free the linked list
void free_list(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}

// Main function demonstrating usage
int main() {
    Node* head = NULL;

    // Example of adding nodes, in practice this could be driven by external updates
    for (int i = 0; i < 10000; ++i) {
        int rx_ue_tag = rand() % 256; // Simulated data source update
        int rnti = rand() % 4096;

        if (add_node(&head, rx_ue_tag, rnti)) {
            fprintf(stderr, "Error adding node for RX_UE_INFORMATION_TAG: %d, RNTI: %d\n", 
                    rx_ue_tag, rnti);
        }
    }

    // Free the list when done
    free_list(&head);

    return 0;
}
