typedef struct {
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *array;
    pthread_mutex_t lock; // Mutex for thread safety
} DynamicArray;

// Function to dynamically allocate memory and initialize array
DynamicArray* create_dynamic_array(size_t N) {
    if (N == 0) return NULL;

    DynamicArray *dynArr = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!dynArr) {
        perror("Failed to allocate memory for DynamicArray");
        exit(EXIT_FAILURE);
    }

    dynArr->count = N;
    dynArr->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynArr->array) {
        perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T array");
        free(dynArr);
        exit(EXIT_FAILURE);
    }

    // Initialize mutex
    if (pthread_mutex_init(&dynArr->lock, NULL) != 0) {
        perror("Mutex init failed");
        free(dynArr->array);
        free(dynArr);
        exit(EXIT_FAILURE);
    }

    // Populate array with random data
    for (size_t i = 0; i < N; ++i) {
        dynArr->array[i].RX_UE_INFORMATION_TAG = rand();
        dynArr->array[i].RNTI = rand() & 0xFFFF;
        dynArr->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomize CRCFLAG as 0 or 1
    }

    return dynArr;
}

// Serialize the data structure to a binary file
void serialize_to_file(const char *filename, DynamicArray *dynArr) {
    pthread_mutex_lock(&dynArr->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        pthread_mutex_unlock(&dynArr->lock);
        return;
    }

    size_t written = fwrite(dynArr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), dynArr->count, file);
    if (written != dynArr->count) {
        perror("Failed to write data to file");
    }

    fclose(file);
    pthread_mutex_unlock(&dynArr->lock);
}

// Deserialize the data structure from a binary file
DynamicArray* deserialize_from_file(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    fseek(file, 0L, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    // Calculate number of structures
    size_t count = fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (fileSize % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        fprintf(stderr, "File size is not a multiple of NFAPI_CRC_INDICATION_PDU_T\n");
        fclose(file);
        return NULL;
    }

    DynamicArray *dynArr = create_dynamic_array(count);
    if (!dynArr) {
        fclose(file);
        return NULL;
    }

    pthread_mutex_lock(&dynArr->lock);

    size_t read = fread(dynArr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    if (read != count) {
        perror("Failed to read data from file");
    }

    fclose(file);
    pthread_mutex_unlock(&dynArr->lock);

    return dynArr;
}

// Function to free dynamically allocated memory
void destroy_dynamic_array(DynamicArray *dynArr) {
    if (!dynArr) return;

    pthread_mutex_destroy(&dynArr->lock);
    free(dynArr->array);
    free(dynArr);
}
