['Below is a C implementation for managing a dynamic array of `NFAPI_RX_FRAME_PDU_T` structures with thread-safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024

typedef struct {
    int RX_FRAME_TAG;
    int UE_ID;
    char* FRAME_BUFFER;
} NFAPI_RX_FRAME_PDU_T;

typedef struct {
    NFAPI_RX_FRAME_PDU_T** frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} FrameManager;

FrameManager* frame_manager_init() {
    FrameManager* manager = (FrameManager*)malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = (NFAPI_RX_FRAME_PDU_T**)calloc(INITIAL_CAPACITY, sizeof(NFAPI_RX_FRAME_PDU_T*));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

int frame_manager_add(FrameManager* manager, int RX_FRAME_TAG, int UE_ID, const char* data) {
    if (!manager || !data) return -1;

    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_RX_FRAME_PDU_T** new_frames = (NFAPI_RX_FRAME_PDU_T**)realloc(manager->frames, new_capacity * sizeof(NFAPI_RX_FRAME_PDU_T*));
        if (!new_frames) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    NFAPI_RX_FRAME_PDU_T* frame = (NFAPI_RX_FRAME_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!frame) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    frame->RX_FRAME_TAG = RX_FRAME_TAG;
    frame->UE_ID = UE_ID;
    size_t data_len = strlen(data) + 1; // including null terminator
    frame->FRAME_BUFFER = (char*)malloc(data_len);
    if (!frame->FRAME_BUFFER) {
        free(frame);
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    memcpy(frame->FRAME_BUFFER, data, data_len);

    manager->frames[manager->count++] = frame;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int frame_manager_update(FrameManager* manager, int RX_FRAME_TAG, const char* new_data) {
    if (!manager || !new_data) return -1;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        NFAPI_RX_FRAME_PDU_T* frame = manager->frames[i];
        if (frame && frame->RX_FRAME_TAG == RX_FRAME_TAG) {
            size_t data_len = strlen(new_data) + 1;
            char* new_buffer = (char*)realloc(frame->FRAME_BUFFER, data_len);
            if (!new_buffer) {
                pthread_mutex_unlock(&manager->mutex);
                return -1;
            }
            frame->FRAME_BUFFER = new_buffer;
            memcpy(frame->FRAME_BUFFER, new_data, data_len);
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1;
}

void frame_manager_free(FrameManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        NFAPI_RX_FRAME_PDU_T* frame = manager->frames[i];
        if (frame) {
            free(frame->FRAME_BUFFER);
            free(frame);
        }
    }

    free(manager->frames);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe access.
- **Dynamic Array Management**: Automatically resizes the array when capacity is reached.
- **Memory Management**: Handles allocation and deallocation of memory for frames and buffers.
- **Error Handling**: Checks for allocation failures and invalid inputs.']

