// Dynamic memory pool for CRC indications
static pthread_mutex_t crc_pool_lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* crc_pool = NULL;
static size_t crc_pool_size = 0;

void initialize_memory_pool(size_t initial_size) {
    pthread_mutex_lock(&crc_pool_lock);
    if (crc_pool) free(crc_pool);
    crc_pool_size = initial_size;
    crc_pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(crc_pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&crc_pool_lock);
}

void* allocate_crc_pdu() {
    pthread_mutex_lock(&crc_pool_lock);
    if (crc_pool_size == 0) {
        // Double the pool size
        crc_pool_size *= 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pool = realloc(crc_pool, crc_pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&crc_pool_lock);
            return NULL; // Allocation failed
        }
        crc_pool = new_pool;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &crc_pool[--crc_pool_size];
    pthread_mutex_unlock(&crc_pool_lock);
    return pdu;
}

void free_crc_pdu(void* pdu) {
    if (!pdu) return;
    pthread_mutex_lock(&crc_pool_lock);
    crc_pool[crc_pool_size++] = *(NFAPI_CRC_INDICATION_PDU_T*)pdu;
    pthread_mutex_unlock(&crc_pool_lock);
}

