    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} LinkedList;

void init_list(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node() {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for a new node");
        exit(EXIT_FAILURE);
    }
    return node;
}

void set_random_crcflag(CRC_INDICATION_REL8_TAG* tag) {
    // Simulate random CRCFLAG setting
    tag->CRCFLAG = rand() % 2; // Randomly 0 or 1
}

void add_node(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_NODES) {
        Node* oldest = list->head;
        list->head = oldest->next;
        free(oldest);
        --list->count;
    }

    Node* new_node = create_node();
    RX_UE_INFORMATION_TAG rx_tag = {0}; // Populate as needed
    RNTI rnti = {0}; // Populate as needed
    CRC_INDICATION_REL8_TAG crc_tag = {0};
    set_random_crcflag(&crc_tag);

    new_node->data.rx_ue_information_tag = rx_tag;
    new_node->data.rnti = rnti;
    new_node->data.crc_indication_rel8_tag = crc_tag;

    new_node->next = NULL;
    if (list->tail) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }
    ++list->count;

    pthread_mutex_unlock(&list->lock);
}

void clear_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        current->next = NULL; // Disconnect nodes
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(LinkedList* list) {
    clear_list(list);
    pthread_mutex_destroy(&list->lock);
}
```

### Key Points:
- **Thread Safety**: The linked list operations are protected using a `pthread_mutex_t` to ensure thread safety during concurrent access.
- **Memory Management**: Nodes are allocated dynamically, and when the maximum size is reached, the oldest node is freed.
- **Performance Considerations**: Minimizing lock contention by only locking necessary sections of code, especially around critical list modifications. This setup balances performance with simplicity for managing a fixed-size linked list under concurrent access conditions.

