        if (!new_node) exit(EXIT_FAILURE);
        new_node->next = pool.free_list;
        pool.free_list = new_node;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&pool.lock);

    Node* node = pool.free_list;
    if (node == NULL) {
        // Handle memory exhaustion
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &node->data;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pool.free_list = node->next;
    ++pool.allocated_count;

    pthread_mutex_unlock(&pool.lock);

    log_allocation("Allocated");

    return pdu;
}

void deallocate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) exit(EXIT_FAILURE);

    new_node->data = *pdu;
    pthread_mutex_lock(&pool.lock);
    new_node->next = pool.free_list;
    pool.free_list = new_node;
    --pool.allocated_count;
    pthread_mutex_unlock(&pool.lock);

    log_deallocation("Deallocated");
}

void log_allocation(const char* message) {
    time_t now = time(NULL);
    pthread_t current_thread = pthread_self();
    printf("[%s] [Thread ID: %lu] %s\n", ctime(&now), (unsigned long)current_thread, message);
}

void log_deallocation(const char* message) {
    time_t now = time(NULL);
    pthread_t current_thread = pthread_self();
    printf("[%s] [Thread ID: %lu] %s\n", ctime(&now), (unsigned long)current_thread, message);
}

int main() {
    srand(time(NULL));
    initialize_pool(1000); // Initial size of the pool

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu();
    if (pdu) {
        // Use pdu...
        deallocate_pdu(pdu);
    }

    return 0;
}
```

### Key Points:

- **Memory Pool**: A simple linked list is used to manage free nodes, reducing allocation overhead.
- **Thread Safety**: `pthread_mutex_t` ensures thread-safe access to the memory pool.
- **Logging**: Logs allocation and deallocation events with timestamps and thread IDs.
- **Initialization**: Preallocates a fixed number of structures to minimize runtime allocations.

This implementation provides a balance between efficiency and simplicity, suitable for resource-constrained environments. Adjust the initial pool size based on expected load and available resources.']

