    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T* array;
} DynamicArray;

int validate_n(size_t n) {
    if (n < 1 || n > MAX_N) {
        fprintf(stderr, "Error: N must be between 1 and %d\n", MAX_N);
        return -1;
    }
    return 0;
}

unsigned int find_next_available_rnti(unsigned int* existing_rntis, size_t count) {
    unsigned int rnti = 1; // Assuming RNTI starts from 1
    while (1) {
        int found = 0;
        for (size_t i = 0; i < count; ++i) {
            if (existing_rntis[i] == rnti) {
                found = 1;
                break;
            }
        }
        if (!found) return rnti;
        rnti++;
    }
}

DynamicArray* create_dynamic_array() {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (!da) {
        fprintf(stderr, "Error: Failed to allocate memory for DynamicArray\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->mutex, NULL);
    da->capacity = INITIAL_SIZE;
    da->count = 0;
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        fprintf(stderr, "Error: Failed to allocate memory for array\n");
        free(da);
        exit(EXIT_FAILURE);
    }
    return da;
}

void resize_array(DynamicArray* da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Error: Failed to reallocate memory for array\n");
        exit(EXIT_FAILURE);
    }
    da->array = new_array;
    da->capacity = new_capacity;
}

void ensure_unique_rnti(DynamicArray* da) {
    pthread_mutex_lock(&da->mutex);

    unsigned int existing_rntis[da->count];
    memcpy(existing_rntis, da->array, da->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < da->count; ++i) {
        if (existing_rntis[i].RNTI == 0) { // Assuming RNTI of 0 means it's not set
            existing_rntis[i].RNTI = find_next_available_rnti(existing_rntis, da->count);
            existing_rntis[i].CRCFLAG = 1; // Adjust CRCFLAG as needed
        }
    }

    memcpy(da->array, existing_rntis, da->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&da->mutex);
}

int add_to_dynamic_array(DynamicArray* da, size_t n) {
    if (validate_n(n)) return -1;

    pthread_mutex_lock(&da->mutex);

    if (da->count + n > da->capacity) {
        size_t new_capacity = da->capacity;
        while (new_capacity < da->count + n) new_capacity *= 2;
        resize_array(da, new_capacity);
    }

    for (size_t i = 0; i < n; ++i) {
        // Simulating RNTI assignment with a placeholder value
        unsigned int rnti = find_next_available_rnti(da->array, da->count);

        if (rnti == 0) { // Handle potential delay or failure in getting RNTI
            fprintf(stderr, "Error: Unable to assign unique RNTI\n");
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }

        da->array[da->count].RNTI = rnti;
        da->array[da->count].CRCFLAG = 0; // Default value
        da->count++;
    }

    ensure_unique_rnti(da);

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void free_dynamic_array(DynamicArray* da) {
    if (da) {
        pthread_mutex_destroy(&da->mutex);
        free(da->array);
        free(da);
    }
}
