#define MAX_RETRIES 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t dns_lock = PTHREAD_MUTEX_INITIALIZER;
static struct hostent* cached_host_entry = NULL;

int resolve_hostname_to_ip(const char *hostname, u_char *ip_address) {
    int retries = 0;
    struct addrinfo hints, *res, *p;
    int status;

    while (retries < MAX_RETRIES) {
        pthread_mutex_lock(&dns_lock);
        if (cached_host_entry != NULL && strcmp(cached_host_entry->h_name, hostname) == 0) {
            memcpy(ip_address, cached_host_entry->h_addr_list[0], cached_host_entry->h_length);
            pthread_mutex_unlock(&dns_lock);
            return 0;
        }
        pthread_mutex_unlock(&dns_lock);

        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;

        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            perror("getaddrinfo");
            sleep(1); // Backoff before retrying
            retries++;
            continue;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            if (p->ai_family == AF_INET) {
                memcpy(ip_address, p->ai_addr->sa_data + 2, sizeof(u_char) * 4);
                freeaddrinfo(res);

                pthread_mutex_lock(&dns_lock);
                cached_host_entry = gethostbyname(hostname);
                pthread_mutex_unlock(&dns_lock);

                return 0;
            }
        }

        freeaddrinfo(res);
        sleep(1); // Backoff before retrying
        retries++;
    }

    fprintf(stderr, "Failed to resolve hostname after %d attempts\n", MAX_RETRIES);
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_indication_pdu_list(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Failed to allocate memory");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        list[i].RNTI = rand() % 500 + 1;
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0);
    }

    return list;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <hostname> <count>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *hostname = argv[1];
    size_t count = atoi(argv[2]);

    u_char ip_address[4];
    if (resolve_hostname_to_ip(hostname, ip_address) == 0) {
        printf("Resolved IP: %u.%u.%u.%u\n",
               ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_nfa_crc_indication_pdu_list(count);
    if (!pdu_list) {
        return EXIT_FAILURE;
    }

    // Use the pdu_list as needed...

    free(pdu_list);
    return EXIT_SUCCESS;
}
