// Define the LTE_NAS_Message structure
typedef struct {
    int NAS_Message_Type;
    int Message_Id;
    uint8_t *NAS_PDU;
} LTE_NAS_Message;

// Configuration table for message type sizes
#define MAX_MESSAGE_TYPES 10

int message_type_sizes[MAX_MESSAGE_TYPES] = { /* Initialize with appropriate sizes */ };

// Define a structure to manage the array of messages
typedef struct {
    LTE_NAS_Message **messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread safety
} LTE_NAS_Array;

// Function to initialize the LTE_NAS_Array
void init_LTE_NAS_Array(LTE_NAS_Array *array, size_t initial_capacity) {
    array->count = 0;
    array->capacity = initial_capacity;
    array->messages = malloc(array->capacity * sizeof(LTE_NAS_Message *));
    pthread_mutex_init(&array->lock, NULL);
}

// Function to resize the LTE_NAS_Array
void resize_LTE_NAS_Array(LTE_NAS_Array *array) {
    size_t new_capacity = array->capacity * 2;
    LTE_NAS_Message **new_messages = realloc(array->messages, new_capacity * sizeof(LTE_NAS_Message *));
    if (new_messages != NULL) {
        array->messages = new_messages;
        array->capacity = new_capacity;
    } else {
        // Handle reallocation failure
        fprintf(stderr, "Failed to resize message array.\n");
    }
}

// Function to add a new LTE_NAS_Message to the array
void add_LTE_NAS_Message(LTE_NAS_Array *array, int NAS_Message_Type, int Message_Id) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_LTE_NAS_Array(array);
    }

    LTE_NAS_Message *new_message = malloc(sizeof(LTE_NAS_Message));
    new_message->NAS_Message_Type = NAS_Message_Type;
    new_message->Message_Id = Message_Id;

    size_t pdu_size = message_type_sizes[NAS_Message_Type];
    new_message->NAS_PDU = malloc(pdu_size);
    if (new_message->NAS_PDU == NULL) {
        // Handle allocation failure
        fprintf(stderr, "Failed to allocate NAS_PDU.\n");
        free(new_message);
    } else {
        array->messages[array->count++] = new_message;
    }

    pthread_mutex_unlock(&array->lock);
}

// Function to deallocate all resources of the LTE_NAS_Array
void cleanup_LTE_NAS_Array(LTE_NAS_Array *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->messages[i]->NAS_PDU);
        free(array->messages[i]);
    }

    free(array->messages);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Example usage
int main() {
    LTE_NAS_Array array;
    init_LTE_NAS_Array(&array, 10);

    // Add messages (example)
    add_LTE_NAS_Message(&array, 1, 101);
    add_LTE_NAS_Message(&array, 2, 202);

    // Cleanup
    cleanup_LTE_NAS_Array(&array);

    return 0;
}
