void free_context(UeContext *context) {
    if (context->pdu_sessions) {
        free(context->pdu_sessions);
    }
    free(context);
}

void init_ue_context_list(UeContextList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    for (size_t i = 0; i < MAX_CONTEXTS; ++i) {
        list->contexts[i] = NULL;
    }
}

int add_ue_context(UeContextList *list, UeContext *context) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_CONTEXTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    list->contexts[list->count++] = context;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_ue_context(UeContextList *list, unsigned long ue_identity) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->ue_identity == ue_identity) {
            free_context(list->contexts[i]);
            memmove(&list->contexts[i], &list->contexts[i + 1],
                    (list->count - i - 1) * sizeof(UeContext*));
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return 0; // Removed
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void iterate_ue_contexts(UeContextList *list, void (*func)(UeContext*)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        func(list->contexts[i]);
    }
    pthread_mutex_unlock(&list->lock);
