#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define THRESHOLD_MULTIPLIER 2

typedef struct {
    uint32_t RNTI;
    int CRCFLAG; // Example field, assuming a simple integer for flag representation.
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} UE_INFORMATION_ENTRY;

typedef struct {
    uint32_t rnti;
    int crc_flag; // Simplified structure
} RNTI_CRC_INFO;

typedef struct {
    UE_INFORMATION_ENTRY ue_information_entry;
    RNTI_CRC_INFO rnti_crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **array;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Indication_List;

CRC_Indication_List *create_list() {
    CRC_Indication_List *list = (CRC_Indication_List *)malloc(sizeof(CRC_Indication_List));
    list->array = (NFAPI_CRC_INDICATION_PDU_T **)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    memset(list->array, 0, INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(CRC_Indication_List *list) {
    if (list) {
        for (size_t i = 0; i < list->capacity; ++i) {
            free(list->array[i]);
        }
        free(list->array);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void expand_list(CRC_Indication_List *list) {
    size_t new_capacity = list->capacity * THRESHOLD_MULTIPLIER;
    NFAPI_CRC_INDICATION_PDU_T **new_array = (NFAPI_CRC_INDICATION_PDU_T **)realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!new_array) {
        perror("Failed to expand list");
        exit(EXIT_FAILURE);
    }
    memset(new_array + list->capacity, 0, (new_capacity - list->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    list->array = new_array;
    list->capacity = new_capacity;
}

void add_entry(CRC_Indication_List *list, uint64_t rx_ue_info_tag, uint32_t rnti, int crc_flag) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->capacity; ++i) {
        if (!list->array[i]) {
            NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            entry->ue_information_entry.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
            entry->ue_information_entry.crc_indication_rel8_tag.RNTI = rnti;
            entry->ue_information_entry.crc_indication_rel8_tag.CRCFLAG = crc_flag;
            entry->rnti_crc_info.rnti = rnti;
            entry->rnti_crc_info.crc_flag = crc_flag;

            list->array[i] = entry;
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    expand_list(list);
    add_entry(list, rx_ue_info_tag, rnti, crc_flag); // Retry adding after expansion

    pthread_mutex_unlock(&list->lock);
}

void populate_nfaapi_crc_indication_pdu_list(CRC_Indication_List *list, size_t num_entries) {
    for (size_t i = 0; i < num_entries; ++i) {
        uint64_t rx_ue_info_tag = rand(); // Randomly generate a tag
        uint32_t rnti = rand() % 10000; // Example RNTI range
        int crc_flag = rand() % 2; // Random CRC flag

        add_entry(list, rx_ue_info_tag, rnti, crc_flag);
    }
}

void *thread_function(void *arg) {
    CRC_Indication_List *list = (CRC_Indication_List *)arg;
    populate_nfaapi_crc_indication_pdu_list(list, 10); // Example entry count
    return NULL;
}

int main() {
    CRC_Indication_List *list = create_list();

    pthread_t threads[5]; // Example thread count

    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, thread_function, list);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_list(list);

    return 0;
}
```

### Key Points:
- **Memory Management:** The function uses dynamic allocation with `malloc` and `realloc`. Each structure is allocated individually to avoid excessive reallocations.
- **Concurrency:** A mutex (`pthread_mutex_t`) ensures thread-safe access when modifying the list, providing a balance between performance and safety. 
- **Expandable Array Strategy:** When the capacity threshold is reached, the array size doubles, minimizing costly reallocation operations while allowing efficient storage management.

This implementation assumes that the system can manage potential network delays or data inconsistencies outside of this function by using appropriate error handling and retry mechanisms in other parts of the application where data retrieval occurs.']

