        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strncpy((char*)ip_buffer, ipstr, IP_BUFFER_SIZE - 1);
        ip_buffer[IP_BUFFER_SIZE - 1] = '\0';
        freeaddrinfo(res);
        return 0;
    }
    freeaddrinfo(res);
    return -1;
}

u_char* get_cached_ip(const char* hostname) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < sizeof(dns_cache) / sizeof(DNSCacheEntry); ++i) {
        if (dns_cache[i].timestamp != 0 && 
            time(NULL) - dns_cache[i].timestamp < DNS_CACHE_EXPIRY_TIME &&
            strcmp((char*)hostname, (char*)&(dns_cache[i].ip_address[0])) == 0) {

            pthread_mutex_unlock(&cache_lock);
            return (u_char*)&(dns_cache[i].ip_address[0]);
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void cache_ip(const char* hostname, const u_char* ip) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < sizeof(dns_cache) / sizeof(DNSCacheEntry); ++i) {
        if (dns_cache[i].timestamp == 0) { // Find an empty slot
            dns_cache[i].timestamp = time(NULL);
            strncpy((char*)dns_cache[i].ip_address, (const char*)ip, IP_BUFFER_SIZE - 1);
            dns_cache[i].ip_address[IP_BUFFER_SIZE - 1] = '\0';
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }
    pthread_mutex_unlock(&cache_lock);
}

nfaapi_crc_indication_list process_nfaapi_crc_indication(const char* target_host) {
    if (!target_host || strlen(target_host) == 0) {
        fprintf(stderr, "Invalid hostname\n");
        nfaapi_crc_indication_list result = {NULL, 0, NULL};
        return result;
    }

    u_char ip_buffer[IP_BUFFER_SIZE] = {0};
    u_char* cached_ip = get_cached_ip(target_host);
    if (cached_ip) {
        strncpy((char*)ip_buffer, (const char*)cached_ip, IP_BUFFER_SIZE - 1);
    } else {
        if (resolve_dns(target_host, ip_buffer) == -1) {
            fprintf(stderr, "Failed to resolve DNS for host: %s\n", target_host);
            nfaapi_crc_indication_list result = {NULL, 0, NULL};
            return result;
        }
        cache_ip(target_host, ip_buffer);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        nfaapi_crc_indication_list result = {NULL, 0, ip_buffer};
        return result;
    }

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = i + 1;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() & 1; // Randomly set CRCFLAG
    }

    nfaapi_crc_indication_list result = {pdus, MAX_STRUCTURES, ip_buffer};
    return result;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    const char* target_host = "example.com";
    nfaapi_crc_indication_list list = process_nfaapi_crc_indication(target_host);

    if (list.ip_address) {
        printf("Resolved IP: %s\n", (char*)list.ip_address);
    }

    for (size_t i = 0; i < list.count; ++i) {
        printf("Structure %zu - RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
               i, list.pdus[i].RX_UE_INFORMATION_TAG, list.pdus[i].RNTI, list.pdus[i].CRC_INDICATION_REL8_TAG);
    }

    free(list.pdus);
    return 0;
}
