#define MAX_STRUCTURES_PER_FRAME 1000
#define VALID_RX_UE_MIN 1000
#define VALID_RX_UE_MAX 2000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crcTag;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_pdus(int num_frames, int structures_per_frame) {
    int actual_structures = (structures_per_frame > MAX_STRUCTURES_PER_FRAME) ? MAX_STRUCTURES_PER_FRAME : structures_per_frame;

    NFAPI_CRC_INDICATION_PDU_T *frames = malloc(num_frames * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!frames) {
        perror("Memory allocation failed for frames array");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    for (int frame_idx = 0; frame_idx < num_frames; ++frame_idx) {
        int last_rnti = -1;

        // Allocate memory for structures in this frame
        NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(actual_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            perror("Memory allocation failed for pdus");
            while (frame_idx-- > 0) free(frames[frame_idx]);
            free(frames);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        frames[frame_idx] = pdus;

        for (int i = 0; i < actual_structures; ++i) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[i];

            // Generate a valid RX_UE_INFORMATION_TAG
            pdu->crcTag.RX_UE_INFORMATION_TAG = rand() % (VALID_RX_UE_MAX - VALID_RX_UE_MIN + 1) + VALID_RX_UE_MIN;

            // Ensure RNTI is unique within the frame
            uint16_t rnti;
            do {
                rnti = rand();
            } while (rnti == last_rnti);

            pdu->crcTag.RNTI = rnti;
            last_rnti = rnti;

            // Randomly set CRCFLAG
            pdu->CRCFLAG = rand() % 2;
        }
    }

    pthread_mutex_unlock(&lock);
    return frames;
}

void free_crc_pdus(NFAPI_CRC_INDICATION_PDU_T *frames, int num_frames) {
    if (frames == NULL) return;

    for (int i = 0; i < num_frames; ++i) {
        free(frames[i]);
    }
    free(frames);
}
