typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MemoryPool;

void initialize_pool(MemoryPool* pool) {
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_from_pool(MemoryPool* pool) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    pthread_mutex_lock(&pool->lock);

    if (pool->head != NULL) {
        Node* node = pool->head;
        pool->head = node->next;
        pdu = &node->data;
        free(node);
    } else {
        pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&pool->lock);

    if (pdu != NULL) {
        // Populate with random CRCFLAG
        pdu->crc_indication_rel8.CRCFLAG = rand() % 2;
    }
    return pdu;
}

void deallocate_pdu_to_pool(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu == NULL) return;

    Node* node = malloc(sizeof(Node));
    if (!node) return; // Error handling for memory allocation failure

    memcpy(&node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&pool->lock);
    node->next = pool->head;
    pool->head = node;
    pthread_mutex_unlock(&pool->lock);
}

void destroy_pool(MemoryPool* pool) {
    Node* current = pool->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
}

u_char* resolve_hostname(const char* hostname, int retry_count) {
    static u_char ip[4];
    struct addrinfo hints, *res, *rp;
    int err;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_DGRAM; // Datagram socket

    for (int attempt = 0; attempt < retry_count; ++attempt) {
        if ((err = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(err));
            continue;
        }

        for (rp = res; rp != NULL; rp = rp->ai_next) {
            struct sockaddr_in* addr = (struct sockaddr_in*)rp->ai_addr;
            memcpy(ip, &addr->sin_addr, sizeof(struct in_addr));
            freeaddrinfo(res);
            return ip;
        }
        freeaddrinfo(res);
    }

    fprintf(stderr, "Failed to resolve hostname after %d retries.\n", retry_count);
    memset(ip, 0, sizeof(u_char) * 4); // Return empty IP on failure
    return NULL;
}

// Function integrating with network stack and handling JSON response parsing,
// RNTI validation, and other error management would be implemented here.

int main() {
