    initialize_pool(&pool);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu_from_pool(&pool);
    if (pdu) {
        // Use the PDU as needed...
        deallocate_pdu_to_pool(&pool, pdu);
    }

    destroy_pool(&pool);

    // DNS resolution example
    u_char* ip_address = resolve_hostname("example.com", MAX_RETRIES);
    if (ip_address != NULL) {
        printf("Resolved IP: %d.%d.%d.%d\n",
               ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
    }

    return 0;
}
