// Custom memory pool allocator
typedef struct MemoryPool {
    size_t elementSize;
    void** freeList;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool crcIndicationPool = {0};

void initMemoryPool(MemoryPool* pool, size_t elementSize, size_t initialCapacity) {
    pool->elementSize = elementSize;
    pool->capacity = initialCapacity;
    pool->freeList = malloc(initialCapacity * sizeof(void*));
    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < initialCapacity; ++i) {
        void* ptr = malloc(elementSize);
        pool->freeList[i] = ptr;
    }
}

void* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->capacity == 0) {
        size_t newCapacity = pool->capacity > 0 ? pool->capacity * 2 : 16;
        void** newFreeList = realloc(pool->freeList, newCapacity * sizeof(void*));
        if (!newFreeList) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle allocation failure
        }
        pool->freeList = newFreeList;
        for (size_t i = pool->capacity; i < newCapacity; ++i) {
            void* ptr = malloc(pool->elementSize);
            if (!ptr) {
                pthread_mutex_unlock(&pool->lock);
                return NULL; // Handle allocation failure
            }
            pool->freeList[i] = ptr;
        }
        pool->capacity = newCapacity;
    }

    void* allocatedPtr = pool->freeList[--(pool->capacity)];
    pthread_mutex_unlock(&pool->lock);

    return allocatedPtr;
}

void deallocateToPool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    if (pool->capacity < pool->elementSize / sizeof(void*)) {
        size_t newCapacity = pool->capacity + 16;
        void** newFreeList = realloc(pool->freeList, newCapacity * sizeof(void*));
        if (!newFreeList) {
            pthread_mutex_unlock(&pool->lock);
            free(ptr); // Fallback to regular deallocation
            return;
        }
        pool->freeList = newFreeList;
    }

    pool->freeList[pool->capacity++] = ptr;
    pthread_mutex_unlock(&pool->lock);
}

void initLteUeContextSystem() {
    initMemoryPool(&crcIndicationPool, sizeof(NFAPI_CRC_INDICATION_PDU_T), 16);
}

