#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_QUEUE_SIZE 1024
#define MIN_PAYLOAD_LEN 64
#define MAX_PAYLOAD_LEN 1500

typedef struct {
    int sequence_number;
    size_t payload_length;
} MAC_HEADER;

typedef unsigned char* MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
} MAC_RX_BUFFER;

typedef struct Node {
    MAC_RX_BUFFER buffer;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
    int max_queue_size; // Configurable threshold
} DynamicQueue;

DynamicQueue* create_dynamic_queue(int max_queue_size) {
    DynamicQueue* queue = (DynamicQueue*)malloc(sizeof(DynamicQueue));
    if (!queue) return NULL;
    queue->head = queue->tail = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    queue->max_queue_size = max_queue_size > MAX_QUEUE_SIZE ? MAX_QUEUE_SIZE : max_queue_size;
    return queue;
}

int is_valid_sequence(int current_seq, int last_seq) {
    if (current_seq == last_seq) return 0;
    if ((current_seq % 4) != (last_seq % 4)) return 1;
    return 0;
}

void flush_queue(DynamicQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->head) {
        Node* temp = queue->head;
        queue->head = queue->head->next;
        free(temp->buffer.payload);
        free(temp);
    }
    queue->tail = NULL;
    queue->size = 0;
    pthread_mutex_unlock(&queue->lock);
}

int enqueue(DynamicQueue* queue, MAC_RX_BUFFER buffer) {
    if (buffer.header.payload_length < MIN_PAYLOAD_LEN || 
        buffer.header.payload_length > MAX_PAYLOAD_LEN) return -1;

    pthread_mutex_lock(&queue->lock);

    if (queue->size >= queue->max_queue_size) {
        pthread_mutex_unlock(&queue->lock);
        return -2;
    }

    int last_seq = 0;
    Node* current = queue->tail;
    while (current && !is_valid_sequence(buffer.header.sequence_number, last_seq)) {
        last_seq = current->buffer.header.sequence_number;
        current = current->next;
    }

    if (!is_valid_sequence(buffer.header.sequence_number, last_seq)) {
        pthread_mutex_unlock(&queue->lock);
        return -3; // Invalid sequence number
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&queue->lock);
        return -4;
    }
    new_node->buffer = buffer;
    new_node->next = NULL;

    if (!queue->head) {
        queue->head = queue->tail = new_node;
    } else {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }

    queue->size++;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

MAC_RX_BUFFER dequeue(DynamicQueue* queue) {
    pthread_mutex_lock(&queue->lock);

    if (!queue->head) {
        pthread_mutex_unlock(&queue->lock);
        return (MAC_RX_BUFFER){0}; // Return an empty buffer
    }

    Node* temp = queue->head;
    MAC_RX_BUFFER buffer = temp->buffer;
    queue->head = queue->head->next;

    if (!queue->head) {
        queue->tail = NULL;
    }

    free(temp->payload);
    free(temp);

    queue->size--;
    pthread_mutex_unlock(&queue->lock);
    return buffer;
}

void adjust_max_queue_size(DynamicQueue* queue, int new_size) {
    pthread_mutex_lock(&queue->lock);
    if (new_size > MAX_QUEUE_SIZE) new_size = MAX_QUEUE_SIZE;
    while (queue->size > new_size) {
        dequeue(queue); // Ensure the size is reduced
    }
    queue->max_queue_size = new_size;
    pthread_mutex_unlock(&queue->lock);
}

void destroy_dynamic_queue(DynamicQueue* queue) {
    flush_queue(queue);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}
