    rx_ue_information_tag: RX_UE_INFORMATION_TAG,
    rnti: RNTI,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

#[derive(StructOpt, Debug)]
struct Cli {
    /// Number of structures to generate
    count: usize,
}

async fn generate_nfaapi_crc_pdu_t(count: usize) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    let mut pdu_list = Vec::with_capacity(count);

    for _ in 0..count {
        // Simulate fetching or generating RX_UE_INFORMATION_TAG and RNTI
        let ue_id = rand::thread_rng().gen_range(1..=65535); // Random UE ID
        let rnti_value = rand::thread_rng().gen_range(1..=4294967295); // Random RNTI value

        let rx_ue_information_tag = RX_UE_INFORMATION_TAG { ue_id };
