#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_MAC_ADDRESSES 100000

typedef struct {
    unsigned char mac[6];
    uint16_t vlan_tag;
    size_t payload_size;
} NICP_MESSAGE;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    _Atomic int crcflag; // Atomic to ensure thread-safe updates
} NFAPI_CRC_INDICATION_PDU_T;

unsigned char mac_addresses[MAX_MAC_ADDRESSES][6];
atomic_uint next_rnti = 1;
pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;

int generate_unique_mac(unsigned char mac[6]) {
    static int used_macs = 0;
    if (used_macs >= MAX_MAC_ADDRESSES) return -1; // No more unique MACs

    for (;;) {
        unsigned long rand_val = rand();
        memcpy(mac, &rand_val, sizeof(rand_val));
        int mac_index = rand() % MAX_MAC_ADDRESSES;

        if (!memcmp(mac_addresses[mac_index], "\0\0\0\0\0\0", 6)) { // Check uniqueness
            used_macs++;
            memcpy(mac_addresses[mac_index], mac, 6);
            return 0;
        }
    }
}

uint32_t allocate_rnti() {
    uint32_t rnti;
    for (int i = 0; i < 10; ++i) {
        pthread_mutex_lock(&rnti_lock);
        rnti = atomic_fetch_add(&next_rnti, 1);
        if (rnti <= UINT32_MAX - 2) {
            pthread_mutex_unlock(&rnti_lock);
            return rnti;
        }
        pthread_mutex_unlock(&rnti_lock);
    }

    // Fallback: recycle by starting from a lower value or any valid approach
    pthread_mutex_lock(&rnti_lock);
    next_rnti = 1; // Reset to start allocation anew, implement better recycling as needed
    return atomic_fetch_add(&next_rnti, 1);
}

void initialize_and_populate(int N, NICP_MESSAGE **nicp_messages, NFAPI_CRC_INDICATION_PDU_T **nfapi_pdus) {
    *nicp_messages = malloc(N * sizeof(NICP_MESSAGE));
    if (!*nicp_messages) return;

    *nfapi_pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*nfapi_pdus) {
        free(*nicp_messages);
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        (*nicp_messages)[i].vlan_tag = rand() % 4096;
        unsigned char mac[6];
        if (generate_unique_mac(mac) != 0) {
            fprintf(stderr, "Failed to generate unique MAC address.\n");
            break;
        }
        memcpy((*nicp_messages)[i].mac, mac, sizeof(mac));
        (*nicp_messages)[i].payload_size = rand() % 1501; // Random size from 0-1500 bytes

        (*nfapi_pdus)[i].RX_UE_INFORMATION_TAG = rand();
        (*nfapi_pdus)[i].RNTI = allocate_rnti();

        if (i > 0 && (*nfapi_pdus)[i].RNTI == (*nfapi_pdus)[i - 1].RNTI) {
            // Resolve RNTI conflict
            while ((*nfapi_pdus)[i].RNTI == (*nfapi_pdus)[i - 1].RNTI) {
                (*nfapi_pdus)[i].RNTI = allocate_rnti();
            }
        }

        (*nfapi_pdus)[i].CRC_INDICATION_REL8_TAG = rand() & 0xFF;
        atomic_store(&(*nfapi_pdus)[i].crcflag, rand() % 2);
    }
}

void free_resources(NICP_MESSAGE *nicp_messages, NFAPI_CRC_INDICATION_PDU_T *nfapi_pdus) {
    if (nicp_messages) free(nicp_messages);
    if (nfapi_pdus) free(nfapi_pdus);
}
```

