            LTE_RRC_CU_MESSAGE *new_array = realloc(array, sizeof(LTE_RRC_CU_MESSAGE) * (array->capacity + INITIAL_CAPACITY));
            if (new_array) {
                array = new_array;
                for (size_t j = array->capacity - INITIAL_CAPACITY; j < array->capacity; ++j) {
