    PHY_LAYER_FRAME_PDU_T *list = (PHY_LAYER_FRAME_PDU_T *)malloc(*capacity * sizeof(PHY_LAYER_FRAME_PDU_T));
    if (!list) {
        handle_allocation_failure(error_callback);
        return NULL;
    }

