    for (size_t i = 0; i < *capacity; ++i) {
        list[i].header.PHY_LAYER_FRAME_HEADER = rand() % UINT16_MAX + 1;

        // Ensure no two consecutive frames have identical TX_STREAM_ID
        if (i > 0) {
            int new_id;
            do {
                new_id = rand() % 255;  // Assuming a max of 8-bit ID
