        log_error("Failed to allocate memory for records");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->capacity = initial_capacity;

    return manager;
}

int add_record(StatsManager *manager, int timestamp, float signal_strength, float quality) {
    if (!manager || manager->count >= MAX_RECORDS)
        return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_RECORDS)
            goto fail_unlock;

        PHY_STATS_RECORD_T *temp = realloc(manager->records, new_capacity * sizeof(PHY_STATS_RECORD_T));
        if (!temp) {
            log_error("Failed to reallocate memory for records");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->records = temp;
        manager->capacity = new_capacity;
    }

    PHY_STATS_RECORD_T record = {timestamp, signal_strength, quality};
    if (timestamp <= 0 || signal_strength < 0.0f || quality < 0.0f) {
        log_error("Invalid input data");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->records[manager->count++] = record;

fail_unlock:
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_stats_manager(StatsManager *manager) {
    if (!manager)
        return;

    pthread_mutex_lock(&manager->lock);

    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);

    free(manager);
}
```

### Key Features:
- **Memory Management**: The function handles dynamic memory allocation, reallocation, and freeing with error checking.
- **Concurrency**: Uses `pthread_mutex_t` for thread safety to prevent race conditions when accessing shared resources.
- **Error Handling & Logging**: Logs errors when allocations fail or invalid data is provided.
- **Capacity Constraints**: Limits the number of records per batch using a predefined maximum (`MAX_RECORDS`) and dynamically increases capacity if needed, without exceeding this limit.
- **Extensibility**: Designed for easy integration and future extensions, e.g., adding new statistical metrics.
- **Performance Considerations**: Efficient memory use with reallocation only when necessary, minimizing impact on system performance. 

This function is a foundation and can be further enhanced based on specific requirements or integration needs in your codebase.']

