#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int num_allocated_rbs;
    int start_rb_index;
    int scheduling_cycle;
} PDSCH_RAB_ALLOC_T;

typedef struct Node {
    PDSCH_RAB_ALLOC_T data;
    struct Node* next;
} Node;

Node* create_node(PDSCH_RAB_ALLOC_T alloc) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->data = alloc;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int validate_structure(Node* head, int num_rb) {
    Node* current = head;
    int last_end_rb = -2; // Initialize to an invalid index
    while (current != NULL) {
        if (current->data.start_rb_index < 0 || 
            current->data.start_rb_index + current->data.num_allocated_rbs > num_rb ||
            current->data.start_rb_index <= last_end_rb + 1) {
            return 0; // Invalid structure
        }
        last_end_rb = current->data.start_rb_index + current->data.num_allocated_rbs - 1;
        current = current->next;
    }
    return 1;
}

Node* initialize_pdsch_allocations(int num_ues, int total_rb, int scheduling_cycle) {
    Node* head = NULL;
    Node** tail_ptr = &head;

    // Simple allocation strategy: allocate blocks ensuring no two consecutive RBs
    for (int ue = 0; ue < num_ues; ++ue) {
        PDSCH_RAB_ALLOC_T alloc;
        alloc.num_allocated_rbs = 2; // Allocate pairs of RBs to maximize efficiency
        alloc.start_rb_index = (ue * alloc.num_allocated_rbs);
        if (alloc.start_rb_index + alloc.num_allocated_rbs > total_rb) {
            break; // No more room for allocation
        }
        alloc.scheduling_cycle = scheduling_cycle;

        Node* new_node = create_node(alloc);
        *tail_ptr = new_node;
        tail_ptr = &new_node->next;
    }

    if (!validate_structure(head, total_rb)) {
        fprintf(stderr, "Validation failed: Invalid PDSCH allocation structure\n");
        free_list(head);
        return NULL;
    }

    return head;
}

int main() {
    int num_ues = 10; // Example number of UEs
    int total_rb = 100; // Total Resource Blocks available
    int scheduling_cycle = 1;

    Node* allocation_list = initialize_pdsch_allocations(num_ues, total_rb, scheduling_cycle);

    if (allocation_list) {
        Node* current = allocation_list;
        while (current != NULL) {
            printf("RBs: %d, Start Index: %d, Cycle: %d\n",
                   current->data.num_allocated_rbs,
                   current->data.start_rb_index,
                   current->data.scheduling_cycle);
            current = current->next;
        }
        free_list(allocation_list);
    } else {
        printf("Failed to initialize PDSCH allocations.\n");
    }

    return 0;
}
