typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    // Aligning to legacy component's byte requirements
    char padding[4]; // Adjust size as needed for alignment
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_THREADS 4

NFAPI_CRC_INDICATION_PDU_T* generate_nfaapi_crc_indication_pdu(int n) {
    if (n <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    void* thread_func(void* arg) {
        int index = *(int*)arg;
        pthread_mutex_lock(&lock);

        // Ensure unique RX_UE_INFORMATION_TAG and RNTI
        pdu_array[index].RX_UE_INFORMATION_TAG = (uint16_t)index;
        pdu_array[index].RNTI = (uint16_t)(index + 1);

        // Randomly set CRCFLAG
        srand(time(NULL) ^ index);
        pdu_array[index].crc_tag.CRCFLAG = rand() % 2;

        pthread_mutex_unlock(&lock);
        return NULL;
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < n; i += MAX_THREADS) {
        int remaining = (n - i) > MAX_THREADS ? MAX_THREADS : (n - i);

        for (int j = 0; j < remaining; ++j) {
            int* index_ptr = malloc(sizeof(int));
            if (!index_ptr) {
                perror("Memory allocation failed");
                exit(EXIT_FAILURE);
            }
            *index_ptr = i + j;
            pthread_create(&threads[j], NULL, thread_func, index_ptr);
        }

        for (int j = 0; j < remaining; ++j) {
            pthread_join(threads[j], NULL);
            free((void*)threads[j]);
        }
    }

    pthread_mutex_destroy(&lock);

    return pdu_array;
}

void validate_structures(NFAPI_CRC_INDICATION_PDU_T *pdu_array, int n) {
    for (int i = 0; i < n; ++i) {
