typedef struct {
    // Add members of RRC_CONFIG_DCI_T structure here
} RRC_CONFIG_DCI_T;

typedef struct {
    RRC_CONFIG_DCI_T rrc_config_dci;
    int ue_id;  // Assuming UE_ID is an integer for simplicity
} NFAPI_RRC_MESSAGE_T;

// Cache mechanism and logging utilities are placeholders.
typedef struct {
    NFAPI_RRC_MESSAGE_T* messages;
    size_t count;
    pthread_mutex_t lock;
} MessageList;

// Memory pool utility (simplified)
#define POOL_SIZE 1024
NFAPI_RRC_MESSAGE_T message_pool[POOL_SIZE];
size_t pool_index = 0;
pthread_mutex_t pool_lock;

void init_message_list(MessageList* list, size_t initial_size) {
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->messages = (NFAPI_RRC_MESSAGE_T*)malloc(initial_size * sizeof(NFAPI_RRC_MESSAGE_T));
    if (!list->messages) {
        perror("Failed to allocate memory for message list");
        exit(EXIT_FAILURE);
    }
}

void free_message_list(MessageList* list) {
    pthread_mutex_lock(&list->lock);
    free(list->messages);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

NFAPI_RRC_MESSAGE_T* allocate_from_pool() {
    pthread_mutex_lock(&pool_lock);
    if (pool_index < POOL_SIZE) {
        NFAPI_RRC_MESSAGE_T* msg = &message_pool[pool_index++];
        pthread_mutex_unlock(&pool_lock);
        return msg;
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL; // Pool exhausted
}

void deallocate_to_pool(NFAPI_RRC_MESSAGE_T* message) {
    if (message && pool_index > 0) {
        size_t index = ((char*)message - (char*)message_pool) / sizeof(NFAPI_RRC_MESSAGE_T);
        pthread_mutex_lock(&pool_lock);
        pool_index--;
        message_pool[index] = *message; // Reset the structure
        pthread_mutex_unlock(&pool_lock);
    }
}

void resize_message_list(MessageList* list, size_t new_size) {
    pthread_mutex_lock(&list->lock);
    NFAPI_RRC_MESSAGE_T* new_messages = (NFAPI_RRC_MESSAGE_T*)realloc(list->messages, new_size * sizeof(NFAPI_RRC_MESSAGE_T));
    if (!new_messages) {
        perror("Failed to resize message list");
        exit(EXIT_FAILURE);
    }
    list->messages = new_messages;
    list->count = new_size;
    pthread_mutex_unlock(&list->lock);
}

void serialize_message_list(MessageList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    size_t bytes_written = fwrite(list->messages, sizeof(NFAPI_RRC_MESSAGE_T), list->count, file);
    if (bytes_written != list->count) {
        perror("Failed to write complete message list to file");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

void deserialize_message_list(MessageList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }

    // Assuming we know the count beforehand or adjust accordingly
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    size_t message_count = file_size / sizeof(NFAPI_RRC_MESSAGE_T);

    NFAPI_RRC_MESSAGE_T* new_messages = (NFAPI_RRC_MESSAGE_T*)realloc(list->messages, message_count * sizeof(NFAPI_RRC_MESSAGE_T));
    if (!new_messages) {
        perror("Failed to resize message list for deserialization");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    rewind(file);

    size_t bytes_read = fread(new_messages, sizeof(NFAPI_RRC_MESSAGE_T), message_count, file);
    if (bytes_read != message_count) {
        perror("Failed to read complete message list from file");
        free(new_messages);
        fclose(file);
        exit(EXIT_FAILURE);
    }

    list->messages = new_messages;
    list->count = message_count;

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

int main() {
    MessageList list;
    init_message_list(&list, 10); // Initial size of 10

    // Example usage
    NFAPI_RRC_MESSAGE_T* msg = allocate_from_pool();
    if (msg) {
        // Populate msg with data
        pthread_mutex_lock(&list.lock);
        if (list.count < POOL_SIZE) {
            list.messages[list.count++] = *msg;
        }
        pthread_mutex_unlock(&list.lock);

        deallocate_to_pool(msg);
    }

    serialize_message_list(&list, "messages.bin");
    deserialize_message_list(&list, "messages.bin");

    free_message_list(&list);
    return 0;
}
