#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list(size_t capacity) {
    if (capacity == 0) return NULL;

    DoublyLinkedList* list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    list->capacity = capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(DoublyLinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_valid_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Add validation logic as needed
    return 1; // Assuming all PDUs are valid for this example
}

void add_pdu(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || !is_valid_pdu(pdu)) return;

    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = pdu;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void update_pdu(DoublyLinkedList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T updated_pdu) {
    if (!list || !is_valid_pdu(updated_pdu)) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            current->data = updated_pdu;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_pdu(DoublyLinkedList* list, int RNTI) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *to_remove = NULL;
    while (current) {
        if (current->data.RNTI == RNTI) {
            to_remove = current;
            break;
        }
        current = current->next;
    }

    if (to_remove) {
        if (to_remove->prev) {
            to_remove->prev->next = to_remove->next;
        } else {
            list->head = to_remove->next;
        }

        if (to_remove->next) {
            to_remove->next->prev = to_remove->prev;
        } else {
            list->tail = to_remove->prev;
        }

        free(to_remove);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock);
}

void traverse_list(DoublyLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !callback) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage of the callback
void print_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
           pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
}

int main() {
    DoublyLinkedList* list = create_list(10);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .CRC_INDICATION_REL8_TAG = 123 };
    add_pdu(list, pdu1);

    traverse_list(list, print_pdu);
    update_pdu(list, 100, (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = 2, .RNTI = 100, .CRC_INDICATION_REL8_TAG = 456});
    remove_pdu(list, 100);

    destroy_list(list);
    return 0;
}
