        } CRC_INDICATION_REL8_TAG;
    };
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_UE_PER_SYSTEM];
    pthread_mutex_t lock;
} UEContextManager;

UEContextManager contextManager = { .lock = PTHREAD_MUTEX_INITIALIZER };

int allocate_and_populate_pdus(size_t num_pdus) {
    if (num_pdus > MAX_UE_PER_SYSTEM) return -1;

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return -1;

    pthread_mutex_lock(&contextManager.lock);
    for (size_t i = 0; i < num_pdus; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        pdus[i].RNTI = rand() % UINT16_MAX;
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0xFF;

        // Find the first available slot
        for (size_t j = 0; j < MAX_UE_PER_SYSTEM; ++j) {
            if (!contextManager.pdus[j]) {
                contextManager.pdus[j] = &pdus[i];
                break;
            }
        }
    }
    pthread_mutex_unlock(&contextManager.lock);

    return 0;
}

void cleanup_pdus() {
    pthread_mutex_lock(&contextManager.lock);
    for (size_t i = 0; i < MAX_UE_PER_SYSTEM; ++i) {
        if (contextManager.pdus[i]) {
            free(contextManager.pdus[i]);
            contextManager.pdus[i] = NULL;
        }
    }
    pthread_mutex_unlock(&contextManager.lock);
}
