['```c
#include <stdio.h>
#include <stdlib.h>
import <time.h>

#define MAX_PDUS 1024

typedef struct {
    unsigned int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    unsigned int RNTI;
    struct Node* next;
} Node;

Node* cacheHead = NULL;

unsigned int generateUniqueRNTI() {
    static unsigned int lastRNTI = 0;
    do {
        lastRNTI++;
        if (lastRNTI == 0) lastRNTI++; // Avoid RNTI wrap around to zero
    } while (checkRNTICache(lastRNTI));

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->RNTI = lastRNTI;
    newNode->next = cacheHead;
    cacheHead = newNode;

    return lastRNTI;
}

int checkRNTICache(unsigned int rnti) {
    Node *current = cacheHead;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            return 1; // RNTI already in cache
        }
        current = current->next;
    }
    return 0;
}

int getRandomCRCFLAG() {
    srand(time(NULL)); // Seed once, ideally outside for performance
    return rand() % 2; // Randomly returns 0 or 1
}

void freeCache() {
    Node *current = cacheHead;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    cacheHead = NULL;
}

int generatePDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int num_pdus, int* highestCRCIndex) {
    if (num_pdus > MAX_PDUS || num_pdus <= 0) return -1; // Error: Invalid number of PDUs

    *highestCRCIndex = 0;
    int highestCRCValue = pdus[0].crc_ind.CRCFLAG;

    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].ue_info.RNTI = generateUniqueRNTI();
        pdus[i].crc_ind.CRCFLAG = getRandomCRCFLAG();

        if (pdus[i].crc_ind.CRCFLAG > highestCRCValue) {
            highestCRCValue = pdus[i].crc_ind.CRCFLAG;
            *highestCRCIndex = i;
        }
    }

