#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for Network Flow Analysis (NFAPI) entry.
typedef struct {
    int flowID;
    double throughput;  // in Mbps
    double latency;     // in ms
    char *metadata;
    unsigned long checksum;
} NFAPI;

// Function to calculate the checksum of an NFAPI entry.
unsigned long calculate_checksum(NFAPI *entry) {
    unsigned long checksum = 0;
    checksum += entry->flowID;
    checksum += (unsigned long)(entry->throughput * 100); // scale for better precision
    checksum += (unsigned long)(entry->latency * 10);
    if (entry->metadata != NULL) {
        while (*entry->metadata) {
            checksum += (unsigned char)*entry->metadata++;
        }
    }
    return checksum;
}

// Function to sort the array of NFAPI entries.
void sort_nfapi_array(NFAPI **array, int count, int sort_by_throughput) {
    for (int i = 0; i < count - 1; i++) {
        for (int j = 0; j < count - i - 1; j++) {
            if ((sort_by_throughput && array[j]->throughput < array[j + 1]->throughput) ||
                (!sort_by_throughput && array[j]->latency > array[j + 1]->latency)) {
                NFAPI *temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }
}

// Function to initialize and populate the array of NFAPI structures.
NFAPI **initialize_nfapi_array(int expected_size, int *actual_size) {
    NFAPI **array = (NFAPI **)malloc(expected_size * sizeof(NFAPI *));
    if (!array) return NULL;

    for (int i = 0; i < expected_size; i++) {
        array[i] = (NFAPI *)malloc(sizeof(NFAPI));
        if (!array[i]) {
            // Free previously allocated entries on failure
            while (--i >= 0) free(array[i]);
            free(array);
            *actual_size = 0;
            return NULL;
        }

        // Populate with example data; replace with actual data fetching logic.
        array[i]->flowID = rand() % 1000;
        array[i]->throughput = (double)(rand() % 1000) / 10.0;
        array[i]->latency = (double)(rand() % 500) + 1.0;
        array[i]->metadata = strdup("Example metadata");

        // Calculate checksum and validate the entry.
        unsigned long computed_checksum = calculate_checksum(array[i]);
        if (computed_checksum != array[i]->checksum) {
            free(array[i]);
            array[i] = NULL;
            continue; // Skip invalid entries
        }
    }

    *actual_size = expected_size;  // In practice, count valid entries instead.
    return array;
}

// Example usage:
int main() {
    int actual_size = 0;
    NFAPI **nfa_array = initialize_nfapi_array(1000, &actual_size);

    if (nfa_array) {
        sort_nfapi_array(nfa_array, actual_size, 1); // Sort by throughput

        // Free the allocated resources.
        for (int i = 0; i < actual_size; i++) {
            free(nfa_array[i]->metadata);
            free(nfa_array[i]);
        }
        free(nfa_array);
    }

    return 0;
}
```

### Key Features:
