#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_SIZE 1048576 // 1 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp; // For age-based management
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    size_t log_size;
    char log[MAX_LOG_SIZE];
} DynamicList;

// Function prototypes
void init_list(DynamicList* list, int capacity);
int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry);
NFAPI_CRC_INDICATION_PDU_T remove_oldest_entry(DynamicList* list);
void log_event(DynamicList* list, const char* event);
void monitor_memory_usage(DynamicList* list);

// Initialize the dynamic list
void init_list(DynamicList* list, int capacity) {
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_full, NULL);
    pthread_cond_init(&list->not_empty, NULL);
    list->head = list->tail = NULL;
    list->capacity = capacity;
    list->log_size = 0;
}

// Add an entry to the list
int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    while (count_entries(list) >= list->capacity) {
        remove_oldest_entry(list);
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation failed

    new_node->data = entry;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove the oldest entry from the list
NFAPI_CRC_INDICATION_PDU_T remove_oldest_entry(DynamicList* list) {
    if (!list->head) return (NFAPI_CRC_INDICATION_PDU_T){0};

    pthread_mutex_lock(&list->lock);

    Node* temp = list->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;

    list->head = list->head->next;
    if (!list->head) {
        list->tail = NULL;
    }

    free(temp);
    pthread_mutex_unlock(&list->lock);

    return data;
}

// Log an event
void log_event(DynamicList* list, const char* event) {
    pthread_mutex_lock(&list->lock);

    size_t len = strlen(event);
    if (list->log_size + len < MAX_LOG_SIZE) {
        strncat(list->log, event, MAX_LOG_SIZE - list->log_size - 1);
        list->log[list->log_size + len] = '\0';
        list->log_size += len;
    }

    pthread_mutex_unlock(&list->lock);
}

// Monitor memory usage
void monitor_memory_usage(DynamicList* list) {
    // Implementation depends on system specifics and is left as an exercise.
}

// Utility function to count entries in the list
int count_entries(DynamicList* list) {
    int count = 0;
    Node* current = list->head;
    while (current) {
        count++;
        current = current->next;
    }
    return count;
}
