typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    int SEQUENCE_NUMBER;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure to manage array with metadata
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t allocatedSize;
    pthread_mutex_t lock; // Mutex for thread safety
} PduArrayManager;

void log_failure(const char *logFilePath, const char *message) {
    FILE *file = fopen(logFilePath, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

int is_valid_input(int numPDUs, int maxInstances, int crcSize) {
    return numPDUs > 0 && numPDUs <= 1000 && maxInstances > 0 && crcSize > 0;
}

void* initialize_pdu(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *) arg;

    // Initialize structure with random values
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;      // Example tag generation
    pdu->RNTI = rand() % 5000;                       // Random RNTI value
    pdu->CRC_INDICATION_REL8_TAG = rand() % 10;       // Example CRC Tag
    pdu->CRCFLAG = rand() & 1;                        // Randomly set flag to 0 or 1
    static pthread_mutex_t seq_num_lock = PTHREAD_MUTEX_INITIALIZER;
    static int sequence_number = 0;

    pthread_mutex_lock(&seq_num_lock);
    pdu->SEQUENCE_NUMBER = ++sequence_number;
    pthread_mutex_unlock(&seq_num_lock);

    return NULL;
}

PduArrayManager* initialize_pdu_array_manager(int numPDUs, int maxInstances, const char *logFilePath) {
    if (!is_valid_input(numPDUs, maxInstances, 0)) { // crcSize not used directly in validation
        log_failure(logFilePath, "Invalid input parameters.");
        return NULL;
    }

    PduArrayManager* manager = (PduArrayManager *)malloc(sizeof(PduArrayManager));
    if (!manager) {
        log_failure(logFilePath, "Failed to allocate memory for manager.");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->allocatedSize = 0;

    size_t pduSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(pduSize * maxInstances);

    if (!manager->pdus) {
        log_failure(logFilePath, "Failed to allocate memory for PDUs.");
        free(manager);
        pthread_mutex_destroy(&manager->lock);
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    pthread_t threads[numPDUs];

    for (int i = 0; i < numPDUs; ++i) {
        if (manager->allocatedSize >= maxInstances)
            break;

        manager->pdus[manager->allocatedSize] = (NFAPI_CRC_INDICATION_PDU_T){0};

        pthread_create(&threads[i], NULL, initialize_pdu, &manager->pdus[manager->allocatedSize]);
        pthread_join(threads[i], NULL);

        ++manager->allocatedSize;
    }

    return manager;
}

void purge_unused_instances(PduArrayManager* manager) {
    if (manager == NULL)
        return;

    pthread_mutex_lock(&manager->lock);
    // Example simple strategy: Reset the array, reuse from start
    memset(manager->pdus, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * manager->allocatedSize);
    manager->allocatedSize = 0;
    pthread_mutex_unlock(&manager->lock);
}

void free_pdu_array_manager(PduArrayManager* manager) {
    if (manager == NULL)
        return;

    free(manager->pdus);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
