typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
    pthread_mutex_t mutex;
} SharedData;

void init_shared_data(SharedData *data, size_t num_elements) {
    data->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data->array) exit(EXIT_FAILURE);

    pthread_mutex_init(&data->mutex, NULL);
    data->count = num_elements;
}

void destroy_shared_data(SharedData *data) {
    free(data->array);
    pthread_mutex_destroy(&data->mutex);
}

void initialize_structure(NFAPI_CRC_INDICATION_PDU_T* pdu, uint16_t ue_tag, uint16_t rnti, uint8_t crcflag) {
    pdu->RX_UE_INFORMATION_TAG = ue_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
}

void* thread_function(void* arg) {
    SharedData *data = (SharedData*)arg;

    pthread_mutex_lock(&data->mutex);
    for (size_t i = 0; i < data->count; ++i) {
        initialize_structure(&data->array[i], rand() % 65536, rand() % 65536, rand() & 1);
    }
    pthread_mutex_unlock(&data->mutex);

    return NULL;
}

void manage_crc_indications(SharedData *data, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, data)) {
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    size_t num_elements = 1000;
    int num_threads = 4;

    SharedData data;
    init_shared_data(&data, num_elements);

    manage_crc_indications(&data, num_threads);

    destroy_shared_data(&data);
    return 0;
}
