#define INITIAL_ARRAY_SIZE 10

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_array(size_t initial_size, size_t* actual_size) {
    if (initial_size == 0 || !actual_size) return NULL;

    pthread_mutex_lock(&allocation_lock);
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&allocation_lock);

    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand(); // Simulating a valid tag
        array[i].RNTI = rand() % 65536;           // Simulating RNTI
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) != 0;
    }

    *actual_size = initial_size;
    return array;
}

bool resize_crc_array(NFAPI_CRC_INDICATION_PDU_T** old_array, size_t current_size, size_t new_size) {
    if (!old_array || !*old_array || new_size <= current_size) return false;

    pthread_mutex_lock(&allocation_lock);
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*old_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&allocation_lock);

    if (!new_array) {
        perror("Failed to reallocate memory");
        return false;
    }

    for (size_t i = current_size; i < new_size; ++i) {
        new_array[i].RX_UE_INFORMATION_TAG = rand(); // Simulating a valid tag
        new_array[i].RNTI = rand() % 65536;           // Simulating RNTI
        new_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) != 0;
    }

    *old_array = new_array;
    return true;
}

void free_crc_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (!array) return;

    pthread_mutex_lock(&allocation_lock);
    free(array);
    pthread_mutex_unlock(&allocation_lock);
}
