typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} NFAPICRCList;

NFAPICRCList* create_list() {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;

    return list;
}

void destroy_list(NFAPICRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_pdu(NFAPICRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pthread_mutex_lock(&list->lock)) return false;

    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

