        NFAPI_CRC_INDICATION_PDU_T pdu;

        if (generate_random_pdu(&pdu)) {
            add_pdu(list, pdu);
        }

        // Simulate processing delay
        usleep(1000); 
    }
}

void* handle_network_thread(void* arg) {
    NFAPICRCList* list = (NFAPICRCList*)arg;
    process_network_load(list);
    return NULL;
}

int main() {
