time_t get_current_time_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (ts.tv_sec * 1000) + (ts.tv_nsec / 1e6);
}

List* create_list(int seed) {
    List *list = malloc(sizeof(List));
    if (!list) {
        log_error("Failed to allocate memory for list");
        return NULL;
    }

    list->items = malloc(MAX_LIST_SIZE);
    if (!list->items) {
        free(list);
        log_error("Failed to allocate memory for items");
        return NULL;
    }

    list->count = 0;
    list->capacity = MAX_LIST_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_init(&list->lock, NULL);
    list->seed = seed;

    return list;
}

void free_list(List *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->items);
        free(list);
    }
}

int add_item(List *list, const RX_UE_INFORMATION_TAG *tag, uint16_t rnti,
             const RX_UE_INFORMATION_TAG *valid_tags, size_t valid_count) {

    pthread_mutex_lock(&list->lock);

    if (validate_tag(tag, valid_tags, valid_count)) {
        if (list->count >= list->capacity) {
            pthread_mutex_unlock(&list->lock);
            log_error("List capacity exceeded");
            return -1;
        }

        NFAPI_CRC_INDICATION_PDU_T *item = &list->items[list->count++];

        item->tag = *tag;
        item->rnti = rnti;

        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.timestamp = get_current_time_ms();

        for (int i = 0; i < CRCFLAG_LEN; ++i) {
            crc_tag.crc_flag[i] = generate_crc_flag(list->seed + i);
        }

        // Store or use crc_tag as needed

        pthread_mutex_unlock(&list->lock);
        return 0;
    } else {
        pthread_mutex_unlock(&list->lock);
        log_error("Invalid tag");
        return -1;
    }
}
