// Define the TX_EMM_CONTEXT structure
typedef struct {
    int UE_ID;
    int TRACKING_AREA_CODE;
    int TRACKING_AREA_IDENTIFICATION;
} TX_EMM_CONTEXT;

// Node for linked list to store contexts
typedef struct ContextNode {
    TX_EMM_CONTEXT context;
    struct ContextNode* next;
} ContextNode;

// Dynamic array structure with a mutex for thread safety
typedef struct {
    ContextNode* head;
    pthread_mutex_t lock;
    int size;
} ContextArray;

// Function prototypes
ContextArray* create_context_array();
void destroy_context_array(ContextArray* ca);
int add_or_update_context(ContextArray* ca, TX_EMM_CONTEXT new_context);
TX_EMM_CONTEXT* get_context_by_ue_id(ContextArray* ca, int ue_id);
static void validate_tracking_area(int ta_code, int tai_ident);

// Create a new context array
ContextArray* create_context_array() {
    ContextArray* ca = (ContextArray*)malloc(sizeof(ContextArray));
    if (!ca) return NULL;

    ca->head = NULL;
    pthread_mutex_init(&ca->lock, NULL);
    ca->size = 0;

    return ca;
}

// Destroy the context array and free all resources
void destroy_context_array(ContextArray* ca) {
    if (!ca) return;

    ContextNode* current = ca->head;
    while (current) {
        ContextNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&ca->lock);
    free(ca);
}

// Add a new context or update an existing one
int add_or_update_context(ContextArray* ca, TX_EMM_CONTEXT new_context) {
    if (!ca || new_context.UE_ID < 0) return -1;

    pthread_mutex_lock(&ca->lock);

    ContextNode** current = &ca->head;
    while (*current) {
        if ((*current)->context.UE_ID == new_context.UE_ID) {
            // Update existing context
            (*current)->context.TRACKING_AREA_CODE = new_context.TRACKING_AREA_CODE;
            (*current)->context.TRACKING_AREA_IDENTIFICATION = new_context.TRACKING_AREA_IDENTIFICATION;

            pthread_mutex_unlock(&ca->lock);
            return 0;  // Success
        }
        current = &((*current)->next);
    }

    // Add a new context
    ContextNode* new_node = (ContextNode*)malloc(sizeof(ContextNode));
    if (!new_node) {
        pthread_mutex_unlock(&ca->lock);
        return -1;
    }

    new_node->context = new_context;
    new_node->next = NULL;

    *current = new_node;
    ca->size++;

    pthread_mutex_unlock(&ca->lock);
    return 0;  // Success
}

// Retrieve a context by UE_ID
TX_EMM_CONTEXT* get_context_by_ue_id(ContextArray* ca, int ue_id) {
    if (!ca || ue_id < 0) return NULL;

    pthread_mutex_lock(&ca->lock);

    ContextNode* current = ca->head;
    while (current) {
        if (current->context.UE_ID == ue_id) {
            TX_EMM_CONTEXT* context = &current->context;
            pthread_mutex_unlock(&ca->lock);
            return context;  // Found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ca->lock);
    return NULL;  // Not found
}

