#include <stdio.h>
#include <stdlib.h>
import stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct CRC_INDICATION_REL8_TAG {
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    int some_field; // Example field
} RX_UE_INFORMATION_TAG;

typedef struct RNTI {
    int value;
} RNTI;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI_THRESHOLD 100

typedef struct {
    pthread_mutex_t lock;
    int unique_rnti_count;
} RNTIManager;

RNTIManager rnti_manager = {PTHREAD_MUTEX_INITIALIZER, 0};

bool allocate_unique_rnti(RNTI* rnti) {
    pthread_mutex_lock(&rnti_manager.lock);
    if (rnti_manager.unique_rnti_count >= MAX_RNTI_THRESHOLD) {
        pthread_mutex_unlock(&rnti_manager.lock);
        return false;
    }
    rnti->value = rand() % 1000 + 1; // Example allocation logic
    rnti_manager.unique_rnti_count++;
    pthread_mutex_unlock(&rnti_manager.lock);
    return true;
}

void free_rntis() {
    pthread_mutex_lock(&rnti_manager.lock);
    rnti_manager.unique_rnti_count = 0;
    pthread_mutex_unlock(&rnti_manager.lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int n) {
    if (n <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **pp = &head;

    int last_rnti = -1;
    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) {
            // Handle memory allocation failure
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = head;
                head = head->next;
                free(temp);
            }
            free_rntis();
            return NULL;
        }

        node->rx_ue_info_tag.some_field = rand() % 100; // Example data
        RNTI rnti;
        do {
            allocate_unique_rnti(&rnti);
        } while (rnti.value == last_rnti);

        node->rnti = rnti;
        last_rnti = rnti.value;

        node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        node->next = NULL;
        *pp = node;
        pp = &node->next;
    }

    return head;
}

void validate_crc_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    if (!head) {
        printf("List is empty.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = head, *prev = NULL;
    while (current != NULL) {
        // Validate each node
        if (!current->rx_ue_info_tag.some_field || !current->rnti.value || current->next == current) {
            fprintf(stderr, "Invalid node detected.\n");
            break;
        }

        if (prev && prev->rnti.value == current->rnti.value) {
            fprintf(stderr, "Consecutive RNTI values are identical.\n");
            break;
        }

        prev = current;
        current = current->next;
    }
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }
    free_rntis();
}

// Example processing function that runs in a separate thread
void* process_crc_list(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)arg;

    validate_crc_list(list);

    // Simulated processing logic
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL) {
        printf("Processing RNTI: %d, CRCFLAG: %d\n", current->rnti.value, current->crc_indication_rel8_tag.CRCFLAG);
        current = current->next;
    }

    free_crc_list(list);

    return NULL;
}

int main() {
    int n_elements = 10; // Example list size
    NFAPI_CRC_INDICATION_PDU_T *list = create_crc_indication_list(n_elements);
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_crc_list, list)) {
        perror("Could not create processing thread");
        free_crc_list(list);
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    return EXIT_SUCCESS;
}
