    Node* current = head;
    while (current != NULL) {
        // Simulate completing partial data.
        if (!current->data.is_complete) {
            current->data.rx_ue_information_tag.RX_UE_INFORMATION_TAG = rand() % 100;
            for (int j = 0; j < 4; ++j) {
                current->data.crc_indication_rel8_tag.CRCFLAG_REL8[j] = rand() % 2 == 1;
            }
