    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 1000

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_STRUCTURES];
    size_t pool_size;
} MemoryPool;

MemoryPool memory_pool = { .pool_size = 0 };

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    pthread_rwlock_wrlock(&rwlock);

    if (memory_pool.pool_size == 0) {
        pthread_rwlock_unlock(&rwlock);
        return NULL;
    }

    size_t index = --memory_pool.pool_size;
    NFAPI_CRC_INDICATION_PDU_T *structure = memory_pool.pool[index];
    memory_pool.pool[index] = NULL;

    pthread_rwlock_unlock(&rwlock);
    return structure;
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_rwlock_wrlock(&rwlock);

    if (memory_pool.pool_size < MAX_STRUCTURES) {
        memory_pool.pool[memory_pool.pool_size++] = structure;
    }

    pthread_rwlock_unlock(&rwlock);
}

uint8_t generate_crcflag(uint16_t rnti, time_t timestamp) {
    return (uint8_t)((rnti ^ timestamp) & 0xFF); // Simple deterministic function
}

void log_creation(NFAPI_CRC_INDICATION_PDU_T *structure, pthread_t thread_id) {
    FILE *log_file = fopen("creation_log.txt", "a");
    if (log_file) {
