        fprintf(log_file, "Thread %lu created structure at %ld with CRCFLAG: %d\n",
                (unsigned long)thread_id, now, structure->CRCFLAG);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_structure(uint16_t rnti) {
