    time_t timestamp = time(NULL);
    uint8_t crcflag = generate_crcflag(rnti, timestamp);

    structure->RX_UE_INFORMATION_TAG = rand(); // Example tag
    structure->RNTI = rnti;
    structure->CRC_INDICATION_REL8_TAG = 0x01; // Example tag
    structure->CRCFLAG = crcflag;

    log_creation(structure, pthread_self());

    return structure;
}

void initialize_memory_pool(size_t num_structures) {
    for (size_t i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structure) {
            fprintf(stderr, "Error: Out of memory during pool initialization\n");
            return;
        }
        memory_pool.pool[memory_pool.pool_size++] = structure;
    }
}

void destroy_structure_list(NFAPI_CRC_INDICATION_PDU_T **structures, size_t count) {
