            deallocate_structure(structures[i]);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* manage_nfa_list(size_t N, size_t M) {
    pthread_rwlock_rdlock(&rwlock);
    if (memory_pool.pool_size < M) {
        pthread_rwlock_unlock(&rwlock);
        initialize_memory_pool(M - memory_pool.pool_size);
    }
    pthread_rwlock_unlock(&rwlock);

    NFAPI_CRC_INDICATION_PDU_T *structures[N];

    for (size_t i = 0; i < N; ++i) {
