            return NULL;
        }
    }

    return structures[0]; // Return the first structure for demonstration purposes
}

int main() {
    size_t N = 100; // Example number of structures to manage
    size_t M = 200; // Maximum allowed structures

    NFAPI_CRC_INDICATION_PDU_T *structures = manage_nfa_list(N, M);
    if (!structures) {
        fprintf(stderr, "Failed to manage NFA list\n");
        return EXIT_FAILURE;
    }

    printf("NFA list managed successfully\n");

    destroy_structure_list((NFAPI_CRC_INDICATION_PDU_T**)structures, N);

