#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>
#include <openssl/rand.h>

#define MAX_THREADS 4

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[32];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
} SharedQueue;

void init_queue(SharedQueue *queue, size_t initial_capacity) {
    queue->mutex = PTHREAD_MUTEX_INITIALIZER;
    queue->cond = PTHREAD_COND_INITIALIZER;
    queue->size = 0;
    queue->capacity = initial_capacity;
    queue->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void free_queue(SharedQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    free(queue->data);
    pthread_mutex_unlock(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    pthread_mutex_destroy(&queue->mutex);
}

void enqueue(SharedQueue *queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->size == queue->capacity) {
        queue->capacity *= 2;
        queue->data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(queue->data, queue->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    queue->data[queue->size++] = pdu;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

int dequeue(SharedQueue *queue, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->size == 0) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }

    *pdu = queue->data[0];
    memmove(queue->data, queue->data + 1, (--queue->size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&queue->mutex);

    return 1;
}

void* worker_thread(void *arg) {
    SharedQueue *queue = (SharedQueue *)arg;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        if (!dequeue(queue, &pdu)) break;

        // Simulate processing
        printf("Processing PDU with RX_UE_INFORMATION_TAG: %d\n", pdu.RX_UE_INFORMATION_TAG);
    }

    return NULL;
}

void processPDUList(int n, int option) {
    SharedQueue queue;
    init_queue(&queue, 10);

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 1000;

        if (!RAND_bytes(pdu.CRC_INDICATION_REL8_TAG, sizeof(pdu.CRC_INDICATION_REL8_TAG))) {
            fprintf(stderr, "Error generating random bytes\n");
            exit(EXIT_FAILURE);
        }

        enqueue(&queue, pdu);
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, &queue)) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    int input;
    while (scanf("%d", &input) == 1) {
        if ((option == 0 && input % 2 == 0) || option != 0) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = input;
            pdu.RNTI = rand() % 1000;

            if (!RAND_bytes(pdu.CRC_INDICATION_REL8_TAG, sizeof(pdu.CRC_INDICATION_REL8_TAG))) {
                fprintf(stderr, "Error generating random bytes\n");
                exit(EXIT_FAILURE);
            }

            enqueue(&queue, pdu);
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_queue(&queue);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <number_of_pdus> <option>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int n = atoi(argv[1]);
    int option = atoi(argv[2]);

    processPDUList(n, option);

    return EXIT_SUCCESS;
}
```']

