    int sensor_id;
    float value;
} SensorReading;

typedef enum {
    FILTER_ALL,
    FILTER_SENSOR_ID,
    FILTER_TIME_RANGE
} FilterType;

typedef struct {
    int sensor_id_filter;
    time_t start_time;
    time_t end_time;
} FilterCriteria;

// Global variables for shared data structures and synchronization
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;
SensorReading *reading_queue = NULL;
size_t queue_size = 0, queue_capacity = 0;
int shutdown_flag = 0;

void initQueue(size_t initial_capacity) {
    if (initial_capacity == 0) return;
    reading_queue = malloc(initial_capacity * sizeof(SensorReading));
    queue_capacity = initial_capacity;
}

void enqueueSensorReading(const SensorReading *reading) {
    pthread_mutex_lock(&queue_mutex);
    while (queue_size >= queue_capacity && !shutdown_flag) {
        pthread_cond_wait(&cond_var, &queue_mutex);
    }
    if (shutdown_flag) {
        pthread_mutex_unlock(&queue_mutex);
        return;
    }
    reading_queue[queue_size++] = *reading;
    pthread_cond_signal(&cond_var);
    pthread_mutex_unlock(&queue_mutex);
}

int dequeueSensorReading(SensorReading *reading) {
    pthread_mutex_lock(&queue_mutex);
    while (queue_size == 0 && !shutdown_flag) {
        pthread_cond_wait(&cond_var, &queue_mutex);
    }
    if (queue_size > 0) {
        *reading = reading_queue[0];
        memmove(reading_queue, reading_queue + 1, (--queue_size) * sizeof(SensorReading));
        pthread_cond_signal(&cond_var);
        pthread_mutex_unlock(&queue_mutex);
        return 1;
    }
    pthread_mutex_unlock(&queue_mutex);
    return 0;
}

void freeQueue() {
    if (reading_queue != NULL) {
        free(reading_queue);
        reading_queue = NULL;
    }
}

int filterReading(const SensorReading *reading, FilterType filter_type, const FilterCriteria *criteria) {
    switch (filter_type) {
        case FILTER_SENSOR_ID:
            return reading->sensor_id == criteria->sensor_id_filter;
        case FILTER_TIME_RANGE:
            return reading->timestamp >= criteria->start_time && reading->timestamp <= criteria->end_time;
        default:
            return 1; // Filter all
    }
}

void *validationWorker(void *arg) {
    while (!shutdown_flag) {
        SensorReading reading;
        if (dequeueSensorReading(&reading)) {
            // Simulate asynchronous validation with sleep
            usleep(1000);
            printf("Validated: %d at %ld\n", reading.sensor_id, reading.timestamp);
        }
    }
    return NULL;
}

void processAndStoreSensorReadings(FilterType filter_type, const FilterCriteria *criteria) {
    pthread_t worker_threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&worker_threads[i], NULL, validationWorker, NULL) != 0) {
            perror("Failed to create thread");
            exit(1);
        }
    }

    // Simulate reading queue
    initQueue(100);

    for (int i = 0; i < MAX_READINGS_PER_SECOND; ++i) {
        SensorReading new_reading = { .timestamp = time(NULL), .sensor_id = rand() % 10, .value = rand() / (float)RAND_MAX * 100 };

        if (filterReading(&new_reading, filter_type, criteria)) {
            enqueueSensorReading(&new_reading);
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(worker_threads[i], NULL);
    }

    freeQueue();
}

int main(int argc, char *argv[]) {
