#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RNTI 1024
#define CRC_PROBABILITY 0.1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_random_identifier() {
    return rand() % 10000; // Random number between 0 and 9999
}

void set_crcflag(double probability) {
    double random_val = (double)rand() / RAND_MAX;
    if (random_val < probability) {
        return 1; // Set CRCFLAG to 1 indicating packet loss
    }
    return 0; // Set CRCFLAG to 0 indicating no packet loss
}

int is_unique_rnti(unsigned short rnti, NFAPI_CRC_INDICATION_PDU_T *list, int count) {
    for (int i = 0; i < count; ++i) {
        if (list[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void initialize_list(NFAPI_CRC_INDICATION_PDU_T **list, int num_elements) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_elements; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % MAX_RNTI;
        unsigned short rnti = rand() % MAX_RNTI;

        while (!is_unique_rnti(rnti, *list, i)) {
            rnti += generate_random_identifier();
        }

        (*list)[i].RNTI = rnti;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Random byte
        (*list)[i].CRCFLAG = set_crcflag(CRC_PROBABILITY);
    }
}

void cleanup_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list != NULL) {
        free(list);
    }
}

int main() {
    int num_elements = 1000; // Example number of elements
    NFAPI_CRC_INDICATION_PDU_T *indication_pdu_list;

    initialize_list(&indication_pdu_list, num_elements);

    // Simulation of usage
    for (int i = 0; i < num_elements; ++i) {
        printf("Tag: %d, RNTI: %u, CRC Tag: %d, CRCFLAG: %d\n",
               indication_pdu_list[i].RX_UE_INFORMATION_TAG,
               indication_pdu_list[i].RNTI,
               indication_pdu_list[i].CRC_INDICATION_REL8_TAG,
               indication_pdu_list[i].CRCFLAG);
    }

    cleanup_list(indication_pdu_list);

    return 0;
}
```

### Key Points:
