// Message bus simulation using message queue (pthread_mutex for protection)
#define QUEUE_SIZE 100
NFAPI_CRC_INDICATION_PDU_T message_queue[QUEUE_SIZE];
int head = 0, tail = 0;
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    int interface_id;
} InterfaceInfo;

// Function prototypes
