    pthread_mutex_t lock;
} StatsArray;

#define INITIAL_CAPACITY 10

void log_operation(const char *message) {
    printf("%s\n", message);
}

int compare_throughput_desc(const void *a, const void *b) {
    NetworkInterfaceStats *statsA = (NetworkInterfaceStats *)a;
