    return (statsB->throughput > statsA->throughput) - (statsB->throughput < statsA->throughput);
}

void* populate_data(void* arg) {
    StatsArray* array = (StatsArray*)arg;
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkInterfaceStats* new_data = realloc(array->data, new_capacity * sizeof(NetworkInterfaceStats));
        if (!new_data) {
            log_operation("Failed to resize data array.");
            pthread_mutex_unlock(&array->lock);
            return NULL;
        }
        array->data = new_data;
        array->capacity = new_capacity;
