    if (!array->data) {
        log_operation("Failed to allocate initial data array.");
    }
}

void free_stats_array(StatsArray* array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    srand(time(NULL));

    StatsArray statsArray;
    init_stats_array(&statsArray);

    const int num_threads = 20; // Adjust based on expected load
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, populate_data, &statsArray);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    sort_array(&statsArray);

    // Example: Filter interfaces with throughput >= 500 Mbps
    filter_interfaces_by_throughput(&statsArray, 500.0);

    log_operation("Final data array:");
    for (size_t i = 0; i < statsArray.count; ++i) {
        printf("%s: Throughput=%f Mbps, Loss Rate=%f%%, Latency=%f ms\n", 
