import stdlib.h

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG: 1; // Single bit field for CRCFLAG
        unsigned char reserved: 7; // Padding to make it a full byte
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_nfa_pi_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T** pduList, size_t M) {
    *pduList = NULL;
    unsigned int* rnTiSet = (unsigned int*)malloc(M * sizeof(unsigned int));
    if (!rnTiSet) return -1; // Memory allocation failed

    *pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pduList) {
        free(rnTiSet);
        return -2; // Memory allocation failed
    }

    size_t count = 0;
    while (count < M) {
        unsigned int rnTi = rand() % (UINT_MAX / 4); // Generate random RNTI, ensuring uniqueness

        if (!binary_search(rnTiSet, count, rnTi)) { // Check for uniqueness
            (*pduList)[count].RX_UE_INFORMATION_TAG = rand();
            (*pduList)[count].RNTI = rnTi;
            (*pduList)[count].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Set CRCFLAG randomly

            rnTiSet[count] = rnTi; // Store RNTI in set
            count++;
        }
    }

    free(rnTiSet);
    return 0;
}

int binary_search(unsigned int* arr, size_t n, unsigned int target) {
    for (size_t i = 0; i < n; ++i) {
        if (arr[i] == target) {
            return 1;
        }
    }
    return 0;
}
