    size_t pool_size;
    void* memory_pool;
    pthread_mutex_t lock;
} PoolAllocator;

void init_allocator(PoolAllocator* pool, size_t element_size, size_t pool_size) {
    pool->element_size = element_size;
    pool->pool_size = pool_size;
    pool->memory_pool = malloc(element_size * pool_size);
    if (!pool->memory_pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
}

void* allocate(PoolAllocator* pool) {
    pthread_mutex_lock(&pool->lock);
    void* ptr = malloc(pool->element_size);
    if (!ptr) {
        perror("Allocation failed");
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_allocator(PoolAllocator* pool) {
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
}

