typedef struct {
    unsigned int ue_id;
    unsigned int frequency_point;
    time_t timestamp;
    unsigned int band_information;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} LTE_DL_CQI_Report;

typedef struct {
    LTE_DL_CQI_Report *reports;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray *)malloc(sizeof(DynamicArray));
    da->reports = NULL;
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->reports);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

int add_report(DynamicArray *da, LTE_DL_CQI_Report report) {
    pthread_mutex_lock(&da->lock);

    size_t new_count = da->count + 1;
    if (new_count > MAX_REPORTS) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Capacity exceeded
    }

    da->reports = realloc(da->reports, new_count * sizeof(LTE_DL_CQI_Report));
    if (!da->reports) {
        pthread_mutex_unlock(&da->lock);
        return -2; // Memory allocation failure
    }

    da->reports[da->count] = report;
    da->count = new_count;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

int update_report(DynamicArray *da, unsigned int ue_id, LTE_DL_CQI_Report updated_report) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->count; ++i) {
        if (da->reports[i].ue_id == ue_id) {
            da->reports[i] = updated_report;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return -1; // Report not found
}

void filter_and_retrieve(DynamicArray *da, unsigned int band_information, void (*process)(LTE_DL_CQI_Report *)) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->count; ++i) {
        if (da->reports[i].band_information == band_information) {
            process(&da->reports[i]);
        }
    }

    pthread_mutex_unlock(&da->lock);
}

void simulate_external_data_update(DynamicArray *da) {
    // Simulated function to handle external data updates
    // For example, updating band information from an external source
    srand(time(NULL));
    for (size_t i = 0; i < da->count; ++i) {
        pthread_mutex_lock(&da->lock);
        da->reports[i].band_information = rand() % 100 + 1;
        pthread_mutex_unlock(&da->lock);
    }
}

void example_process(LTE_DL_CQI_Report *report) {
    printf("Processing report for UE ID: %u\n", report->ue_id);
}

