    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t capacity;
    pthread_mutex_t lock;
} CRCList;

CRCList* init_list(size_t max_capacity) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    list->capacity = max_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_duplicate(CRCList* list, int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return 1;
        current = current->next;
    }
    return 0;
}

void add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (is_duplicate(list, element.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void update_crc_flag(CRCList* list, int rnti, unsigned char crc_flag) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            current->data.crc_flag = crc_flag;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_element(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node **indirect = &list->head;
    while (*indirect) {
        if ((*indirect)->data.RNTI == rnti) {
            Node* temp = *indirect;
            *indirect = (*indirect)->next;
            free(temp);
            break;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void print_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("RNTI: %d, RX_UE_INFORMATION_TAG: %d, CRC_FLAG: %u\n",
               current->data.RNTI,
               current->data.RX_UE_INFORMATION_TAG,
               current->data.crc_flag);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
