['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants and data structures

#define MAX_DEVICES 1024
#define LOG_BUFFER_SIZE 4096

typedef enum {
    DISCONNECTED,
    CONNECTING,
    CONNECTED,
    ERROR
} ConnectionState;

typedef struct {
    char identifier[256];
    char configuration[512];
    ConnectionState state;
    int health; // Represented as a percentage (0-100)
} NetworkDeviceContext;

typedef struct {
    pthread_mutex_t lock;
    NetworkDeviceContext devices[MAX_DEVICES];
    size_t count;
} DeviceManager;

typedef enum {
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

typedef struct {
    char buffer[LOG_BUFFER_SIZE];
    size_t index;
    LogLevel level;
    pthread_mutex_t log_lock;
} Logger;

// Function prototypes

void init_device_manager(DeviceManager *manager);
int add_device(DeviceManager *manager, const char *identifier, const char *config);
NetworkDeviceContext* find_device(DeviceManager *manager, const char *identifier);
int update_configuration(DeviceManager *manager, const char *identifier, const char *new_config);
int update_connection_state(DeviceManager *manager, const char *identifier, ConnectionState state);
void log_message(Logger *logger, LogLevel level, const char *message);

// Logger functions

static void append_log(Logger *logger, LogLevel level, const char *format, ...) {
    if (level < logger->level) return;

    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&logger->log_lock);
    vsnprintf(logger->buffer + logger->index, LOG_BUFFER_SIZE - logger->index, format, args);
    logger->index = strlen(logger->buffer);

    if (logger->index >= LOG_BUFFER_SIZE) {
        fprintf(stderr, "Log buffer overflow: %s", logger->buffer);
        logger->index = 0; // Reset the log buffer
    }

    pthread_mutex_unlock(&logger->log_lock);

    va_end(args);
}

void init_logger(Logger *logger, LogLevel level) {
    logger->index = 0;
    logger->level = level;
    pthread_mutex_init(&logger->log_lock, NULL);
}

// Device Manager functions

void init_device_manager(DeviceManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
}

int add_device(DeviceManager *manager, const char *identifier, const char *config) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_DEVICES) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No space to add new device
    }

    NetworkDeviceContext *device = &manager->devices[manager->count];
    strncpy(device->identifier, identifier, sizeof(device->identifier));
    strncpy(device->configuration, config, sizeof(device->configuration));
    device->state = DISCONNECTED;
    device->health = 100; // Assume new devices are healthy

    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NetworkDeviceContext* find_device(DeviceManager *manager, const char *identifier) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->devices[i].identifier, identifier) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->devices[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int update_configuration(DeviceManager *manager, const char *identifier, const char *new_config) {
    NetworkDeviceContext *device = find_device(manager, identifier);

    if (device == NULL) {
        return -1; // Device not found
    }

    pthread_mutex_lock(&manager->lock);
    strncpy(device->configuration, new_config, sizeof(device->configuration));
    pthread_mutex_unlock(&manager->lock);

    log_message(NULL, LOG_LEVEL_INFO, "Configuration updated for device %s", identifier);
    return 0;
}

int update_connection_state(DeviceManager *manager, const char *identifier, ConnectionState state) {
    NetworkDeviceContext *device = find_device(manager, identifier);

    if (device == NULL) {
        return -1; // Device not found
    }

    pthread_mutex_lock(&manager->lock);
    device->state = state;
    pthread_mutex_unlock(&manager->lock);

    log_message(NULL, LOG_LEVEL_INFO, "Connection state updated for device %s", identifier);
    return 0;
}

// Logging functions

void log_message(Logger *logger, LogLevel level, const char *format, ...) {
    if (logger == NULL) return;

    va_list args;
    va_start(args, format);

    append_log(logger, level, "[%s] ", get_timestamp());
    vsnprintf(logger->buffer + logger->index, LOG_BUFFER_SIZE - logger->index, format, args);

    va_end(args);

    // Output the log message
    printf("%s\n", logger->buffer);

    // Reset index if buffer is full
    if (logger->index >= LOG_BUFFER_SIZE) {
        logger->index = 0;
    }
}

const char* get_timestamp() {
    static char timestamp[64];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    return timestamp;
}
```

