['```cpp
#include <iostream>
#include <unordered_map>
#include <shared_mutex>
#include <chrono>
#include <string>

class NetworkConnectionRecord {
public:
    using SessionID = std::string;
    using Timestamp = std::chrono::steady_clock::time_point;

private:
    struct Record {
        std::string sessionId;
        Timestamp startTime;
        double bandwidthUsage;
        int errorCount;

        Record(const SessionID& id, const Timestamp& time, double usage, int errors)
            : sessionId(id), startTime(time), bandwidthUsage(usage), errorCount(errors) {}
    };

    std::unordered_map<SessionID, Record> records_;
    mutable std::shared_mutex mutex_;

public:
    NetworkConnectionRecord() = default;

    bool insert(const SessionID& sessionId, double bandwidthUsage, int errorCount) {
        std::unique_lock lock(mutex_);
        if (records_.find(sessionId) != records_.end()) return false;

        auto startTime = std::chrono::steady_clock::now();
        records_[sessionId] = Record(sessionId, startTime, bandwidthUsage, errorCount);
        return true;
    }

    bool update(const SessionID& sessionId, double newBandwidthUsage, int newErrorCount) {
        std::unique_lock lock(mutex_);
        auto it = records_.find(sessionId);
        if (it == records_.end()) return false;

        it->second.bandwidthUsage = newBandwidthUsage;
        it->second.errorCount = newErrorCount;
        return true;
    }

    bool remove(const SessionID& sessionId) {
        std::unique_lock lock(mutex_);
        return records_.erase(sessionId) > 0;
    }

    bool retrieve(const SessionID& sessionId, Record& record) const {
        std::shared_lock lock(mutex_);
        auto it = records_.find(sessionId);
        if (it == records_.end()) return false;

        record = it->second;
        return true;
    }
};

// Example usage
int main() {
    NetworkConnectionRecord networkManager;

    // Insert a new connection record
    networkManager.insert("session123", 100.5, 0);

    // Update an existing connection's bandwidth and error count
    if (networkManager.update("session123", 200.5, 1)) {
        std::cout << "Update successful!" << std::endl;
    }

    NetworkConnectionRecord::Record record;

    // Retrieve a connection record by session ID
    if (networkManager.retrieve("session123", record)) {
        std::cout << "Retrieved: " 
                  << "SessionID: " << record.sessionId
                  << ", Bandwidth Usage: " << record.bandwidthUsage
                  << ", Error Count: " << record.errorCount
                  << std::endl;
    }

    // Remove a connection record by session ID
    if (networkManager.remove("session123")) {
        std::cout << "Remove successful!" << std::endl;
    }

    return 0;
}
```

