    FILE *file = fopen(filename, "wb");
    if (!file) exit(EXIT_FAILURE);

    fwrite(&list->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; ++i) {
        fwrite(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

// Deserialize the list from a file
void deserialize_list(NFAPI_List *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) exit(EXIT_FAILURE);

    size_t expected_size;
    fread(&expected_size, sizeof(size_t), 1, file);

    expand_list(list); // Ensure capacity is sufficient
    list->size = expected_size;

    for (size_t i = 0; i < list->size; ++i) {
        fread(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

