['Here's a thread-safe implementation for managing a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures in C:

```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>
#include <time.h>

#define DEFAULT_MAX_ENTRIES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int max_entries = DEFAULT_MAX_ENTRIES;

void set_max_entries_from_env() {
    char* env_value = getenv("MAX_ENTRIES");
    if (env_value) {
        max_entries = atoi(env_value);
    }
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    int count = 0;

    // Check for list size and remove the oldest entry if necessary
    while (current != NULL && count < max_entries - 1) {
        current = current->next;
        count++;
    }

    // Remove the oldest entry if the list is full
    if (count == max_entries - 1) {
        head = head->next;
        free(current);
    }

    Node* new_node = malloc(sizeof(Node));
    if (new_node != NULL) {
        new_node->data = new_data;
        srand(time(NULL)); // Seed for random number generation
        new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        new_node->next = head;
        head = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void clear_list_if_needed(int condition) {
    pthread_mutex_lock(&list_mutex);

    if (condition) {
        Node* current = head;
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
        head = NULL;
    }

    pthread_mutex_unlock(&list_mutex);
}

void initialize_list_manager() {
    set_max_entries_from_env();
}

void cleanup_list_manager() {
    clear_list_if_needed(1); // Always clear at the end
    pthread_mutex_destroy(&list_mutex);
}
```

### Usage Notes:

- **Initialization**: Call `initialize_list_manager()` before using the list.
- **Adding Entries**: Use `add_entry(NFAPI_CRC_INDICATION_PDU_T new_data)` to add entries.
- **Clearing List**: Use `clear_list_if_needed(int condition)` where `condition` is a boolean-like flag to determine when to clear the list (e.g., based on network configuration changes or time intervals).
- **Cleanup**: Call `cleanup_list_manager()` at the end of your program to free resources.

### Thread Safety:

The implementation uses `pthread_mutex_t` for ensuring thread safety during modifications to the linked list. Make sure to link with `-lpthread` when compiling this code.']

