} FrameArray;

// Helper function to create a new array
FrameArray* init_frame_array(size_t initial_capacity) {
    if (initial_capacity == 0) {
        initial_capacity = 10;
    }

    FrameArray *array = malloc(sizeof(FrameArray));
    array->frames = calloc(initial_capacity, sizeof(LTE_DL_FRAMEINFO));
    array->capacity = initial_capacity;
    array->count = 0;
    atomic_store(&array->version, 0);

    return array;
}

// Resize function to grow the array
void resize_frame_array(FrameArray *array, size_t new_capacity) {
    LTE_DL_FRAMEINFO *new_frames = realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO));
    if (new_frames == NULL) {
        // Handle memory allocation failure
        return;
    }

    array->frames = new_frames;
    array->capacity = new_capacity;
}

// Filter frames based on threshold
void filter_frame_array(FrameArray *array, uint16_t threshold) {
    size_t write_index = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->frames[i].frame_count >= threshold) {
            array->frames[write_index++] = array->frames[i];
        }
    }
    array->count = write_index;
}

// Insert a new frame maintaining the order
void insert_frame(FrameArray *array, LTE_DL_FRAMEINFO frame, size_t index) {
    if (index > array->count || array->capacity == array->count) {
        resize_frame_array(array, array->capacity ? array->capacity * 2 : 10);
    }

    memmove(&array->frames[index + 1], &array->frames[index],
            (array->count - index) * sizeof(LTE_DL_FRAMEINFO));

    array->frames[index] = frame;
    ++array->count;
}

// Concurrent access without locks
LTE_DL_FRAMEINFO read_frame(const FrameArray *array, size_t index) {
    atomic_size_t version_before = atomic_load(&array->version);
    LTE_DL_FRAMEINFO frame = {0};
    if (index < array->count) {
        frame = array->frames[index];
    }
    while (atomic_load(&array->version) != version_before) {
        // Retry reading if the version changed
        return read_frame(array, index);
    }
    return frame;
}

