    size_t index;
} FrameHashEntry;

FrameHashEntry *hash_table = NULL;

size_t hash_function(uint32_t id) {
    return id % HASH_TABLE_SIZE;
}

void init_hash_table() {
    hash_table = calloc(HASH_TABLE_SIZE, sizeof(FrameHashEntry));
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i].index = (size_t)-1; // -1 to denote empty
    }
}

void update_hash_table(uint32_t id, size_t index) {
    size_t hash_index = hash_function(id);

    while (hash_table[hash_index].index != (size_t)-1 && 
           hash_table[hash_index].id != id) {
        hash_index = (hash_index + 1) % HASH_TABLE_SIZE;
    }

    hash_table[hash_index] = (FrameHashEntry){id, index};
}

void free_resources(FrameArray *array) {
    if (array) {
        free(array->frames);
        free(array);
    }
    if (hash_table) {
        free(hash_table);
    }
}
