['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the structure as described.
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define NUM_STRUCTS 100

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random number using Mersenne Twister.
unsigned int mt_random() {
    static unsigned int init = 0;
    static struct {
        unsigned long x[312];
        int p;
    } state;

    if (!init) {
        pthread_mutex_lock(&lock);
        if (!init) {
            // Seed the generator with time.
            srand((unsigned int)time(NULL));
            for (int i = 0; i < 312; ++i)
                state.x[i] = rand();
            state.p = 0;
            init = 1;
        }
        pthread_mutex_unlock(&lock);
    }

    unsigned long y;
    if (++state.p == 312) {
        int j;
        for (j = 0; j < 156; ++j) {
            unsigned long u = (state.x[j] & 0x80000000UL)
                            | (state.x[j + 1] & 0x7fffffffUL);
            state.x[j] = state.x[j + 156]
                        ^ (u >> 1) ^ (0xB5026F5AA96619E9UL & -(u & 1));
        }
        for (; j < 312; ++j) {
            unsigned long u = (state.x[j] & 0x80000000UL)
                            | (state.x[j - 156] & 0x7fffffffUL);
            state.x[j] = state.x[j - 156]
                        ^ (u >> 1) ^ (0xB5026F5AA96619E9UL & -(u & 1));
        }
    }

    y = state.x[state.p];
    y ^= (y >> 29) & 0x5555555555555555UL;
    y ^= (y << 17) & 0x71D67FFFEDA60000UL;
    y ^= (y << 37) & 0xFFF7EEE000000000UL;
    y ^= (y >> 43);

    return (unsigned int)(y ^ (y >> 11));
}

// Function to create and populate a list of structures.
