```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 100
#define RSSI_THRESHOLD 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
    int CRCFLAG;
    int RSSI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} NFALIST;

NFALIST* create_list() {
    NFALIST* list = (NFALIST*)malloc(sizeof(NFALIST));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(Node* node) {
    free(node->data.CRC_INDICATION_REL8_TAG);
    free(node);
}

void free_list(NFALIST* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int compare_RSSI(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pduA = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pduB = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return pduB->RSSI - pduA->RSSI; // Descending order
}

int add_pdu(NFALIST* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        fprintf(stderr, "Max list size reached.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == pdu->RNTI) {
            fprintf(stderr, "Duplicate RNTI found: %d\n", pdu->RNTI);
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate entry
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = *pdu;
    new_node->data.CRCFLAG = pdu->RSSI >= RSSI_THRESHOLD ? 1 : 0;

    // Copy tag with malloc
    char* tag_copy = (char*)malloc(sizeof(pdu->CRC_INDICATION_REL8_TAG));
    if (!tag_copy) {
        fprintf(stderr, "Memory allocation failed for CRC indication tag.\n");
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    strncpy(tag_copy, pdu->CRC_INDICATION_REL8_TAG, sizeof(pdu->CRC_INDICATION_REL8_TAG));
    new_node->data.CRC_INDICATION_REL8_TAG = tag_copy;

    // Insert at the beginning
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    return 1; // Successfully added
}

void sort_list(NFALIST* list) {
    pthread_mutex_lock(&list->lock);

    if (list->size == 0) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    size_t count = 0;

    while (current) { // Count nodes
        count++;
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!array) {
        fprintf(stderr, "Memory allocation failed for sorting.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    current = list->head;
    size_t index = 0;

    while (current) { // Fill array
        array[index++] = current->data;
        current = current->next;
    }

    qsort(array, count, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_RSSI);

    current = list->head; // Update linked list with sorted data

    index = 0;
    while (current) {
        current->data = array[index++];
        current = current->next;
    }

    free(array);
    pthread_mutex_unlock(&list->lock);
}

void synchronize_data(NFALIST* local_list, NFALIST* external_system) {
    // This function would typically interact with an API.
    pthread_mutex_lock(&local_list->lock);

    Node* current_local = local_list->head;
    while (current_local) {
        Node* current_external = external_system->head;
        int found = 0;

        while (current_external) {
            if (current_local->data.RNTI == current_external->data.RNTI) {
                found = 1;
                break;
            }
            current_external = current_external->next;
        }

        if (!found) {
            fprintf(stderr, "Data mismatch detected for RNTI: %d\n", current_local->data.RNTI);
            // Handle synchronization logic here
        }

        current_local = current_local->next;
    }

    pthread_mutex_unlock(&local_list->lock);
}

void log_creation(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("Created PDU: RNTI=%d, RSSI=%d\n", pdu->RNTI, pdu->RSSI);
}
