#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>

typedef struct {
    int32_t DeviceIdentifier;
    uint64_t Timestamp;
    int8_t EventSeverity;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t count;
    pthread_mutex_t mutex;
    double average_severity;
    volatile int updates_in_progress;  // for throttling
} EventManager;

EventManager* initialize_event_manager(size_t initial_capacity) {
    EventManager *em = (EventManager *)malloc(sizeof(EventManager));
    em->events = (NetworkEvent *)calloc(initial_capacity, sizeof(NetworkEvent));
    em->count = 0;
    pthread_mutex_init(&em->mutex, NULL);
    em->average_severity = 0.0;
    em->updates_in_progress = 0;
    return em;
}

void update_event_manager(EventManager *em, const NetworkEvent new_event) {
    static pthread_mutex_t throttle_lock = PTHREAD_MUTEX_INITIALIZER;

    // Throttle updates during high-concurrency
    if (pthread_mutex_trylock(&throttle_lock) == 0) {
        em->updates_in_progress++;
        pthread_mutex_unlock(&throttle_lock);

        pthread_mutex_lock(&em->mutex);

        size_t new_count = em->count + 1;
        int64_t total_severity = ((int64_t)em->average_severity * em->count) + (int64_t)new_event.EventSeverity;

        if (new_count > em->events[0].DeviceIdentifier) { // Assuming DeviceIdentifier is used as a proxy for capacity
            size_t new_capacity = new_count * 2;
            NetworkEvent *new_events = realloc(em->events, new_capacity * sizeof(NetworkEvent));
            if (new_events != NULL) {
                em->events = new_events;
            }
        }

        em->events[em->count] = new_event;
        double new_average_severity = (double)total_severity / new_count;
        em->average_severity = new_average_severity;
        em->count = new_count;

        pthread_mutex_unlock(&em->mutex);

        em->updates_in_progress--;
        pthread_mutex_lock(&throttle_lock);
        pthread_mutex_unlock(&throttle_lock);
    }
}

void free_event_manager(EventManager *em) {
    if (em != NULL) {
        free(em->events);
        pthread_mutex_destroy(&em->mutex);
        free(em);
    }
}
```

