#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define RX_QUALITY_THRESHOLD 50.0

typedef struct {
    int CELL_ID;
    long TIMESTAMP;
    float RX_QUALITY;
    float SINR;
    int MCS_LEVEL;
} PHY_STATS_REPORT_T;

typedef struct Node {
    PHY_STATS_REPORT_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
    float sinr_window[MAX_LIST_SIZE];
    size_t window_size;
    size_t window_index;
    float sum_sinr;
} ReportList;

ReportList* create_report_list(size_t window_size) {
    ReportList* list = (ReportList*)malloc(sizeof(ReportList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->window_size = window_size;
    list->window_index = 0;
    list->sum_sinr = 0.0;

    for (size_t i = 0; i < window_size; ++i) {
        list->sinr_window[i] = 0.0;
    }

    return list;
}

int add_report(ReportList* list, PHY_STATS_REPORT_T report) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        Node* entry = *current;
        if (entry->data.CELL_ID == report.CELL_ID && entry->data.TIMESTAMP == report.TIMESTAMP) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate found
        }
        current = &entry->next;
    }

    if (list->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    if (report.RX_QUALITY > RX_QUALITY_THRESHOLD) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Memory allocation failed
        }

        new_node->data = report;
        new_node->next = *current;

        list->sum_sinr -= list->sinr_window[list->window_index];
        list->sinr_window[list->window_index] = report.SINR;
        list->sum_sinr += report.SINR;

        if (++list->window_index >= list->window_size) {
            list->window_index = 0;
        }

        (*current) = new_node;
        list->size++;
    } else {
        // Log filtering error
    }

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully added
}

void free_report_list(ReportList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

float get_moving_average_sinr(ReportList* list) {
    if (!list || list->size < 1) return 0.0;

    pthread_mutex_lock(&list->lock);
    float average = list->sum_sinr / ((float)list->window_size < (float)list->size ? list->size : list->window_size);
    pthread_mutex_unlock(&list->lock);

    return average;
}

void sort_reports(ReportList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    int sorted = 0;
    while (!sorted) {
        sorted = 1;
        Node* current = list->head;
        while (current && current->next) {
            if (current->data.TIMESTAMP < current->next->data.TIMESTAMP) {
                PHY_STATS_REPORT_T temp = current->data;
                current->data = current->next->data;
                current->next->data = temp;
                sorted = 0;
            }
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void export_to_file(ReportList* list, const char* filename) {
    if (!list || !filename) return;

    FILE* file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fprintf(file, "%d,%ld,%f,%f,%d\n",
                current->data.CELL_ID,
                current->data.TIMESTAMP,
                current->data.RX_QUALITY,
                current->data.SINR,
                current->data.MCS_LEVEL);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

// Usage example
int main() {
    ReportList* list = create_report_list(10);

    PHY_STATS_REPORT_T report1 = {1, 1000, 60.0, 20.0, 5};
    add_report(list, report1);

    float average_sinr = get_moving_average_sinr(list);
    printf("Moving Average SINR: %f\n", average_sinr);

    sort_reports(list);
    export_to_file(list, "reports.csv");

    free_report_list(list);
    return 0;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` for thread-safe access.
- **Memory Management**: Dynamically allocates and frees memory for the list and nodes.
- **Filtering**: Filters reports based on `RX_QUALITY`.
- **Moving Average**: Maintains a moving average of `SINR` values.
- **Sorting**: Sorts reports by `TIMESTAMP`.
- **Export Functionality**: Exports data to a CSV file.
- **Error Handling**: Basic error handling for memory allocation and list full conditions.']

