    // Check for duplicates
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == pdu.RNTI) {
            fprintf(stderr, "Duplicate RNTI detected: %u\n", pdu.RNTI);
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    // Check size limit
    if (list->size >= MAX_LIST_SIZE) {
        fprintf(stderr, "Maximum list size reached.\n");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    // Allocate more space if needed
    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
