    list->data = new_data;

    // Add the new PDU
    list->data[list->size] = pdu;
    ++list->size;

    // Sort by RSSI in descending order
    qsort(list->data, list->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), [](const void* a, const void* b) {
        NFAPI_CRC_INDICATION_PDU_T* p1 = (NFAPI_CRC_INDICATION_PDU_T*)a;
        NFAPI_CRC_INDICATION_PDU_T* p2 = (NFAPI_CRC_INDICATION_PDU_T*)b;
        return (p1->RSSI < p2->RSSI) - (p1->RSSI > p2->RSSI);
    });

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->RSSI >= RSSI_THRESHOLD) {
        pdu->CRCFLAG = 1; // Set based on threshold
    } else {
        pdu->CRCFLAG = 0;
    }
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(uint16_t rnti, float rssi, int rx_tag, int crc_indication_tag) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RNTI = rnti;
    pdu.RSSI = rssi;
    pdu.RX_UE_INFORMATION_TAG = rx_tag;
    pdu.CRC_INDICATION_REL8_TAG = crc_indication_tag;
    set_crcflag(&pdu);
    return pdu;
}

void process_pdus(DynamicList* list, size_t num_pdus) {
    for (size_t i = 0; i < num_pdus; ++i) {
        uint16_t rnti = rand() % 10000; // Example RNTI generation
        float rssi = (rand() % 100) / 10.0f; // Example RSSI value
        int rx_tag = rand(); // Example RX_UE_INFORMATION_TAG
        int crc_indication_tag = rand(); // Example CRC_INDICATION_REL8_TAG

        NFAPI_CRC_INDICATION_PDU_T pdu = create_pdu(rnti, rssi, rx_tag, crc_indication_tag);

        if (add_pdu(list, pdu) == 0) {
            printf("PDU added: RNTI=%u, RSSI=%.1f\n", pdu.RNTI, pdu.RSSI);
        } else {
            fprintf(stderr, "Failed to add PDU for RNTI=%u\n", rnti);
        }
    }
}

int main() {
    DynamicList list;
    init_list(&list);

    // Process a batch of PDUs
    process_pdus(&list, 10);

    cleanup_list(&list);
    return 0;
}
