void add_network_entity(EntityList* list, NetworkEntity* entity);
void remove_expired_events(EventList* list);
Node* find_node_by_timestamp(EventList* list, time_t timestamp);
void add_network_event(EventList* list, EventType type, EntityList entities);
void iterate_active_events(EventList* list);

// Initialize the event list
void init_event_list(EventList* list, uint64_t threshold) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->threshold = threshold;
}

// Free memory for entity list
void free_entity_list(EntityList* list) {
    if (!list || !list->data) return;
    for (size_t i = 0; i < list->length; i++) {
        NetworkEntity* entity = (NetworkEntity*)list->data[i];
        if (entity && entity->id) free(entity->id);
        free(entity);
    }
    free(list->data);
}

// Add network entity to a list
void add_network_entity(EntityList* list, NetworkEntity* entity) {
    if (!list || !entity) return;
    list->length++;
    if (list->capacity < list->length) {
        size_t new_capacity = list->capacity == 0 ? 4 : list->capacity * 2;
        void** new_data = realloc(list->data, new_capacity * sizeof(void*));
        if (new_data) {
            list->data = new_data;
            list->capacity = new_capacity;
        }
    }
    list->data[list->length - 1] = entity;
}

// Remove expired events based on threshold
void remove_expired_events(EventList* list) {
    time_t now = time(NULL);
    Node** current = &list->head;

    while (*current) {
        if (now - (*current)->event->timestamp > list->threshold) {
            Node* to_remove = *current;
            *current = (*current)->next;
            free(to_remove->event->entities.data);
            free(to_remove->event);
            free(to_remove);
        } else {
            current = &(*current)->next;
        }
    }
}

// Find node by timestamp (for internal use)
Node* find_node_by_timestamp(EventList* list, time_t timestamp) {
    Node* current = list->head;
    while (current) {
        if (current->event->timestamp == timestamp) return current;
        current = current->next;
    }
    return NULL;
}

// Add a network event
void add_network_event(EventList* list, EventType type, EntityList entities) {
    pthread_mutex_lock(&list->lock);

    NetworkEvent* new_event = malloc(sizeof(NetworkEvent));
    if (!new_event) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_event->type = type;
    new_event->timestamp = time(NULL);
    new_event->entities = entities;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        free(new_event);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->event = new_event;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Iterate over active events
void iterate_active_events(EventList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        // Process each event, e.g., print or export
        printf("Event Type: %d, Timestamp: %ld\n", current->event->type, current->event->timestamp);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup function for EventList
void cleanup_event_list(EventList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* to_delete = current;
        current = current->next;
        free(to_delete->event->entities.data);
        free(to_delete->event);
        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
