#define MAX_RNTI 0xFFFF

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t count;
    pthread_mutex_t mutex;
} PDU_Manager;

int isValidRNTI(uint16_t rnti) {
    return rnti != 0 && rnti <= MAX_RNTI;
}

PDU_Manager* createPduManager(size_t n) {
    PDU_Manager* manager = (PDU_Manager*)malloc(sizeof(PDU_Manager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->mutex, NULL);
    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    return manager;
}

int addPdu(PDU_Manager* manager, uint16_t rxUeTag, uint16_t rnti, uint8_t crcTag) {
    pthread_mutex_lock(&manager->mutex);

    if (!isValidRNTI(rnti)) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    size_t index = manager->count++;
    if (index >= sizeof(manager->pdus) / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pthread_mutex_unlock(&manager->mutex);
        return -2; // Array full
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &manager->pdus[index];
    pdu->RX_UE_INFORMATION_TAG = rxUeTag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crcTag;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void freePduManager(PDU_Manager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager->pdus);
        free(manager);
    }
}
