#define MAX_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned int seed; // For pseudo-random number generation
} CRCList;

// Function prototypes
void init_crc_list(CRCList *list, unsigned int initial_seed);
void destroy_crc_list(CRCList *list);
int resize_if_needed(CRCList *list);
int add_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu);
void clear_list(CRCList *list);
void debug_print_list(const CRCList *list);

// Initialize the list
void init_crc_list(CRCList *list, unsigned int initial_seed) {
    pthread_mutex_init(&list->lock, NULL);
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = MAX_SIZE;
    list->seed = initial_seed;
}

// Destroy the list and free resources
void destroy_crc_list(CRCList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
}

// Resize if needed (thread-safe)
int resize_if_needed(CRCList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->size < list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return 0; // No resizing needed
    }

    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    list->data = new_data;
    list->capacity *= 2;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Add a PDU to the list (thread-safe)
int add_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (resize_if_needed(list)) {
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    pdu.CRCFLAG = (unsigned char)(pdu.RNTI % 2); // Simple pseudo-random value based on seed
    list->data[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Clear the list and reset CRCFLAG values (thread-safe)
void clear_list(CRCList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        list->data[i].CRCFLAG = 0;
    }
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
}

// Debug print the current state of the list
void debug_print_list(const CRCList *list) {
    pthread_mutex_lock((pthread_mutex_t *)&list->lock);

    printf("Current List State:\n");
    for (size_t i = 0; i < list->size; ++i) {
        printf("Index %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%u\n",
               i,
               list->data[i].RX_UE_INFORMATION_TAG,
               list->data[i].RNTI,
               list->data[i].CRC_INDICATION_REL8_TAG,
               (unsigned int)list->data[i].CRCFLAG);
    }

    pthread_mutex_unlock((pthread_mutex_t *)&list->lock);
}

int main() {
    unsigned int seed = 12345;
    CRCList list;

    init_crc_list(&list, seed);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 10, 100, 0};
    add_pdu(&list, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 20, 200, 0};
    add_pdu(&list, pdu2);

    // Debug print
    debug_print_list(&list);

    // Clear the list
    clear_list(&list);

    destroy_crc_list(&list);
    return 0;
}
