// Assuming the definition of NFAPI_CRC_INDICATION_PDU_T is available elsewhere
typedef struct {
    int crc_id;
    unsigned char data[256]; // Example size, adjust as needed
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ELEMENTS 10000

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* crc_list = NULL;
static int current_size = 0;

// Assumed external logging function
void log_failure(const char *message) {
    // Implementation of the logging library should be provided.
    fprintf(stderr, "%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_crc_list(int n_elements) {
    if (n_elements > MAX_ELEMENTS) {
        log_failure("Requested number of elements exceeds maximum limit.");
        return NULL;
    }

    pthread_mutex_lock(&list_mutex);

    // Allocate or reallocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(crc_list, n_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_list) {
        log_failure("Memory allocation failed.");
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    // Initialize only the newly allocated portion
    if (current_size < n_elements) {
        memset(new_list + current_size, 0, (n_elements - current_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    crc_list = new_list;
    current_size = n_elements;

    pthread_mutex_unlock(&list_mutex);

    return crc_list;
}

// Example usage function for concurrent access
void populate_element(int index, int crc_id, const unsigned char* data) {
    if (index < 0 || index >= MAX_ELEMENTS || !crc_list) {
        log_failure("Invalid index or uninitialized list.");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    // Populate the specific element
    crc_list[index].crc_id = crc_id;
    memcpy(crc_list[index].data, data, sizeof(crc_list[0].data));

    pthread_mutex_unlock(&list_mutex);
}

void cleanup_crc_list() {
    pthread_mutex_lock(&list_mutex);
    free(crc_list);
    crc_list = NULL;
    current_size = 0;
    pthread_mutex_unlock(&list_mutex);
}
