#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[3]; // Assuming 3 bytes for CRC_INDICATION_REL8_TAG
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    int size;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    return list;
}

unsigned int generate_unique_rnti(unsigned int rnti_start, unsigned int* used_rntis, int size) {
    // Generate a unique RNTI
    for (int i = 0; i < 10000; ++i) { // Arbitrary limit to prevent infinite loop
        unsigned int candidate = rnti_start + rand() % 100000;
        int is_unique = 1;
        for (int j = 0; j < size && is_unique; ++j) {
            if (used_rntis[j] == candidate) {
                is_unique = 0;
            }
        }
        if (is_unique) return candidate;
    }
    return 0; // Fallback
}

void add_structure(List* list, unsigned int rnti_start, unsigned int* used_rntis, int used_size) {
    pthread_mutex_lock(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    new_node->data.RX_UE_INFORMATION_TAG = rand(); // Or some meaningful initialization
    new_node->data.RNTI = generate_unique_rnti(rnti_start, used_rntis, used_size);
    memcpy(new_node->data.CRC_INDICATION_REL8_TAG, "\x00\x00\x00", 3); // Placeholder
    new_node->data.CRCFLAG = rand() % 2;

    // Add to list
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    used_rntis[used_size++] = new_node->data.RNTI; // Update RNTI usage

    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_structure_by_rnti(List* list, unsigned int rnti) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL; // Not found
}

void remove_structure_by_index(List* list, int index) {
    if (index < 0 || index >= list->size) return;

    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *prev = NULL;
    for (int i = 0; current != NULL && i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Index out of bounds
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if (prev == NULL) { // Remove head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;

    pthread_mutex_unlock(&list->mutex);
}

void destroy_list(List* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int main() {
    srand(time(NULL));
    List* list = create_list();

    unsigned int used_rntis[1000]; // Assuming a limit for RNTI storage
    memset(used_rntis, 0, sizeof(used_rntis));

    int n = 10; // Number of initial structures
    for (int i = 0; i < n; ++i) {
        add_structure(list, 10000, used_rntis, list->size);
    }

    unsigned int rnti_to_find = 10123;
    NFAPI_CRC_INDICATION_PDU_T* pdu = get_structure_by_rnti(list, rnti_to_find);
    if (pdu) {
        printf("Structure found with RNTI: %u\n", pdu->RNTI);
    } else {
        printf("No structure found with RNTI: %u\n", rnti_to_find);
    }

    remove_structure_by_index(list, 0);

    destroy_list(list);
    return 0;
}
