["Here's a C implementation that addresses your requirements for managing concurrent network sessions:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_SESSIONS 1024
#define SESSION_TIMEOUT 60 // in seconds

typedef enum {
    PROTOCOL_TCP,
    PROTOCOL_UDP
} ProtocolType;

typedef struct {
    int session_id;
    char ip_address[16];
    int port;
    ProtocolType protocol_type;
    time_t last_active; // Timestamp of the last activity
} Session;

typedef struct {
    Session *sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
    size_t count;
} NetworkInterface;

void initialize_network_interface(NetworkInterface *net_if) {
    memset(net_if, 0, sizeof(*net_if));
    pthread_mutex_init(&net_if->lock, NULL);
}

int add_session(NetworkInterface *net_if, const char *ip_address, int port, ProtocolType protocol_type) {
    if (pthread_mutex_lock(&net_if->lock)) return -1;

    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (!net_if->sessions[i]) {
            net_if->sessions[i] = malloc(sizeof(Session));
            if (!net_if->sessions[i]) {
                pthread_mutex_unlock(&net_if->lock);
                return -1;
            }
            net_if->sessions[i]->session_id = i + 1;
            strncpy(net_if->sessions[i]->ip_address, ip_address, sizeof(net_if->sessions[i]->ip_address) - 1);
            net_if->sessions[i]->port = port;
            net_if->sessions[i]->protocol_type = protocol_type;
            net_if->sessions[i]->last_active = time(NULL);
            net_if->count++;
            pthread_mutex_unlock(&net_if->lock);
            return i + 1; // Return session ID
        }
    }

    pthread_mutex_unlock(&net_if->lock);
    return -1; // No available slot
}

void remove_session(NetworkInterface *net_if, int session_id) {
    if (pthread_mutex_lock(&net_if->lock)) return;

    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (net_if->sessions[i] && net_if->sessions[i]->session_id == session_id) {
            free(net_if->sessions[i]);
            net_if->sessions[i] = NULL;
            --net_if->count;
            break;
        }
    }

    pthread_mutex_unlock(&net_if->lock);
}

void check_timeouts(NetworkInterface *net_if) {
    time_t current_time = time(NULL);

    if (pthread_mutex_lock(&net_if->lock)) return;

    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (net_if->sessions[i] && 
            difftime(current_time, net_if->sessions[i]->last_active) > SESSION_TIMEOUT) {
            free(net_if->sessions[i]);
            net_if->sessions[i] = NULL;
            --net_if->count;
        }
    }

    pthread_mutex_unlock(&net_if->lock);
}

void update_session_activity(NetworkInterface *net_if, int session_id) {
    if (pthread_mutex_lock(&net_if->lock)) return;

    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (net_if->sessions[i] && net_if->sessions[i]->session_id == session_id) {
            net_if->sessions[i]->last_active = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&net_if->lock);
}

void cleanup(NetworkInterface *net_if) {
    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (net_if->sessions[i]) {
            free(net_if->sessions[i]);
        }
    }
    pthread_mutex_destroy(&net_if->lock);
}
```

### Key Points:

- **Session Management**: Sessions are stored in an array, with a mutex for thread-safe access.
- **Timeout Handling**: Regularly check sessions for timeouts and remove inactive ones.
- **Resource Cleanup**: Properly free allocated memory when sessions are closed or timed out.
- **Concurrency**: Use mutexes to manage concurrent access to shared resources.
- **Modular Design**: Functions are modular, allowing easy integration of new protocols.

This implementation balances efficiency, usability, maintainability, and scalability by using a simple array-based approach for session management, which is suitable for moderate loads. For higher scalability, consider using more advanced data structures like hash tables or concurrent queues."]

