#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define INITIAL_SIZE 10
#define MAX_RETRIES 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Randomly set to true or false
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned long checksum; // Simple checksum for demonstration purposes.
} CRC_ARRAY;

// Function to log errors and resource usage
void log_with_retry(const char* message) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (/* simulate logging service success */) {
            printf("Log: %s\n", message);
            break;
        }
        retries++;
        // Simulate a backoff
        sleep(1); 
    }
}

// Function to compute checksum incrementally
unsigned long calculate_checksum(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return (unsigned long)pdu->RX_UE_INFORMATION_TAG + pdu->RNTI + pdu->CRC_INDICATION_REL8_TAG;
}

void update_checksum(CRC_ARRAY *arr, NFAPI_CRC_INDICATION_PDU_T* pdu, bool add) {
    unsigned long new_check = calculate_checksum(pdu);
    if (add) {
        arr->checksum += new_check;
    } else {
        arr->checksum -= new_check;
    }
}

void init_array(CRC_ARRAY *arr) {
    arr->size = 0;
    arr->capacity = INITIAL_SIZE;
    arr->array = malloc(arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arr->array == NULL) {
        log_with_retry("Memory allocation failed for initial array.");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&arr->lock, NULL);
    arr->checksum = 0;
}

void free_array(CRC_ARRAY *arr) {
    free(arr->array);
    pthread_mutex_destroy(&arr->lock);
}

bool resize_array_if_needed(CRC_ARRAY *arr) {
    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            log_with_retry("Memory allocation failed during array resize.");
            return false;
        }
        arr->array = new_array;
        arr->capacity = new_capacity;
    }
    return true;
}

bool add_element(CRC_ARRAY *arr, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&arr->lock);
    if (!resize_array_if_needed(arr)) {
        pthread_mutex_unlock(&arr->lock);
        return false;
    }

    arr->array[arr->size] = *element;
    update_checksum(arr, element, true);
    arr->size++;

    log_with_retry("Element added successfully.");
    pthread_mutex_unlock(&arr->lock);
    return true;
}

bool remove_element(CRC_ARRAY *arr, size_t index) {
    if (index >= arr->size) {
        log_with_retry("Attempt to remove element at invalid index.");
        return false;
    }

    pthread_mutex_lock(&arr->lock);
    update_checksum(arr, &arr->array[index], false);

    memmove(&arr->array[index], &arr->array[index + 1], (arr->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->size--;

    pthread_mutex_unlock(&arr->lock);
    log_with_retry("Element removed successfully.");
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(CRC_ARRAY *arr, size_t index) {
    if (index >= arr->size) {
        log_with_retry("Attempt to retrieve element at invalid index.");
        return NULL;
    }

    pthread_mutex_lock(&arr->lock);
    NFAPI_CRC_INDICATION_PDU_T* result = &arr->array[index];
    pthread_mutex_unlock(&arr->lock);

    return result;
}

// This function should be run periodically for validation
void validate_integrity(CRC_ARRAY *arr, const unsigned long reference_checksum) {
    pthread_mutex_lock(&arr->lock);
    if (arr->checksum != reference_checksum) {
        log_with_retry("Data integrity check failed.");
    } else {
        log_with_retry("Data integrity verified successfully.");
    }
    pthread_mutex_unlock(&arr->lock);
}

// Example usage
int main() {
    CRC_ARRAY array;
    init_array(&array);

    NFAPI_CRC_INDICATION_PDU_T element = {1, 2, 3, rand() % 2};
    add_element(&array, &element);

    unsigned long reference_checksum = array.checksum; // Assume this is provided from a reliable source.

    validate_integrity(&array, reference_checksum);

    free_array(&array);
    return 0;
}
