// Define the structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for linked list to handle dynamic array operations efficiently
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the dynamic array structure with thread safety support
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for thread safety
} CRCArray;

// Function to initialize the dynamic array
void initCRCArray(CRCArray* arr) {
    arr->head = NULL;
    pthread_mutex_init(&arr->lock, NULL);
}

// Helper function to create a new node with random CRCFLAG
Node* createNewNode(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG as either 0 or 1
    newNode->next = NULL;

    return newNode;
}

// Function to add a new element to the array
int addElement(CRCArray* arr, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&arr->lock);

    Node* newNode = createNewNode(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (!newNode) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Memory allocation failed
    }

    if (arr->head == NULL || arr->head->data.RNTI > RNTI) {
        newNode->next = arr->head;
        arr->head = newNode;
    } else {
        Node* current = arr->head;
        while (current->next != NULL && current->next->data.RNTI < RNTI) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

// Function to remove an element based on RNTI
int removeElement(CRCArray* arr, int RNTI) {
    pthread_mutex_lock(&arr->lock);

    Node *current = arr->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Element not found
    }

    if (prev == NULL) {
        arr->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

// Function to print all RNTI values in ascending order
void printRNTIs(CRCArray* arr) {
    pthread_mutex_lock(&arr->lock);

    Node* current = arr->head;
    while (current != NULL) {
        printf("RNTI: %d\n", current->data.RNTI);
        current = current->next;
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to free the dynamic array and its elements
void freeCRCArray(CRCArray* arr) {
    pthread_mutex_lock(&arr->lock);

    Node* current = arr->head;
    while (current != NULL) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }

    arr->head = NULL;
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}

// Example usage
int main() {
    CRCArray crcArray;
    initCRCArray(&crcArray);

    addElement(&crcArray, 1, 100, 10);
    addElement(&crcArray, 2, 200, 20);
    addElement(&crcArray, 3, 150, 30);

    printRNTIs(&crcArray);

    removeElement(&crcArray, 200);
    printRNTIs(&crcArray);

    freeCRCArray(&crcArray);
    return 0;
}
