#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import <pthread.h>
#include <time.h>

#define MAX_STRUCTS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

// Custom memory allocator
void* custom_malloc(size_t size) {
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

// Initialize the list
NFAPI_CRC_LIST_T* init_list() {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T *)custom_malloc(sizeof(NFAPI_CRC_LIST_T));
    pthread_mutex_init(&list->lock, NULL);
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)custom_malloc(MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = MAX_STRUCTS;
    return list;
}

// Add a structure to the list
void add_structure(NFAPI_CRC_LIST_T* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);
    if (list->count < list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[list->count++];
        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->RNTI = RNTI;
        pdu->CRCFLAG = rand() % 2; // Random CRC flag
    }
    pthread_mutex_unlock(&list->lock);
}

// Serialize list to binary file
void serialize_list(NFAPI_CRC_LIST_T* list, const char* filename) {
    FILE *file = fopen(filename, "ab");
    if (!file) return;

    pthread_mutex_lock(&list->lock);
    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

// Deserialize list from binary file
void deserialize_list(NFAPI_CRC_LIST_T* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&list->lock);
    list->capacity = count > list->capacity ? count : list->capacity;
    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)custom_malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data != data) {
        memcpy(data, list->data, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        custom_free(list->data);
    }
    fread(data + list->count, sizeof(NFAPI_CRC_INDICATION_PDU_T), count - list->count, file);

    list->data = data;
    list->count += count;
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

// Verify integrity of serialized data
int verify_serialized_data(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return 0;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, sizeof(size_t), SEEK_SET); // Skip the count

    int expectedSize = sizeof(NFAPI_CRC_INDICATION_PDU_T) * count;
    fclose(file);

    return fileSize == (long)(sizeof(size_t) + expectedSize);
}

// Cleanup list
void cleanup_list(NFAPI_CRC_LIST_T* list) {
    pthread_mutex_destroy(&list->lock);
    custom_free(list->data);
    custom_free(list);
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_LIST_T *list = init_list();

    // Example usage
    add_structure(list, 1, 12345);
    add_structure(list, 2, 67890);

    serialize_list(list, "data.bin");
    deserialize_list(list, "data.bin");

    int is_valid = verify_serialized_data("data.bin");
    printf("Data integrity check: %s\n", is_valid ? "Passed" : "Failed");

    cleanup_list(list);

    return 0;
}
