#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_LIST_T;

// Initialize the list
void init_list(NFAPI_LIST_T *list) {
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add an element to the list
void add_element(NFAPI_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);
    if (list->count < MAX_ELEMENTS) {
        list->elements[list->count++] = element;
    }
    pthread_mutex_unlock(&list->lock);
}

// Serialize the list to a binary file
void serialize_list(const NFAPI_LIST_T *list, const char *filename) {
    pthread_mutex_lock(&list->lock);
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (fd == -1) {
        perror("open");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    size_t bytes_written = write(fd, list->elements, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (bytes_written != list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        perror("write");
    }
    close(fd);
    pthread_mutex_unlock(&list->lock);
}

// Deserialize the list from a binary file
void deserialize_list(NFAPI_LIST_T *list, const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return;
    }
    size_t bytes_read = read(fd, list->elements, MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    close(fd);

    pthread_mutex_lock(&list->lock);
    list->count = bytes_read / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&list->lock);
}

// Clean up the list
void cleanup_list(NFAPI_LIST_T *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}

// Example function to generate a random CRCFLAG for an element
uint8_t generate_random_crcflag() {
    return rand() % 2; // Randomly set to 0 or 1
}

int main() {
    NFAPI_LIST_T list;
    init_list(&list);

    // Example usage: Add elements with randomly generated CRCFLAG
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = { .RX_UE_INFORMATION_TAG = i, 
                                               .RNTI = rand() % 65536,
                                               .CRC_INDICATION_REL8_TAG = rand() % 256,
                                               .CRCFLAG = generate_random_crcflag() };
        add_element(&list, element);
    }

    // Serialize and deserialize example
    const char *filename = "nfa_list.bin";
    serialize_list(&list, filename);
    NFAPI_LIST_T new_list;
    init_list(&new_list);
    deserialize_list(&new_list, filename);

    cleanup_list(&list);
    cleanup_list(&new_list);

    return 0;
}
