#define MAX_CONFIGS 10000

typedef struct {
    int phr_info_tag;
    int srs_info_tag;
    int dlsch_info_tag;
} LTE_PHY_TEST_RX_CONFIG_PDU_T;

typedef struct Node {
    LTE_PHY_TEST_RX_CONFIG_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initialize_node(Node* node, int phr, int srs, int dlsch) {
    if (node != NULL) {
        node->data.phr_info_tag = phr;
        node->data.srs_info_tag = srs;
        node->data.dlsch_info_tag = dlsch;
        node->prev = NULL;
        node->next = NULL;
    }
}

DoublyLinkedList* initialize_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (list == NULL) {
        fprintf(stderr, "Memory allocation failed for list\n");
        return NULL;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_init(&list->lock, NULL);

    for (size_t i = 0; i < MAX_CONFIGS; ++i) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (node == NULL) {
            fprintf(stderr, "Memory allocation failed for node\n");
            // Cleanup already allocated nodes
            while (list->head != NULL) {
                Node* temp = list->head;
                list->head = list->head->next;
                free(temp);
            }
            pthread_mutex_destroy(&list->lock);
            free(list);
            return NULL;
        }

        initialize_node(node, 0, 0, 0); // Default values

        if (list->tail != NULL) {
            node->prev = list->tail;
            list->tail->next = node;
        } else {
            list->head = node;
        }
        list->tail = node;
        ++(list->count);
    }

    return list;
}

int validate_list(DoublyLinkedList* list) {
    if (list == NULL || pthread_mutex_lock(&list->lock)) {
        return 0; // Invalid list or lock failure
    }

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.phr_info_tag < 0 || 
            current->data.srs_info_tag < 0 ||
            current->data.dlsch_info_tag < 0) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Invalid data
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 1; // Valid list
}

void cleanup_list(DoublyLinkedList* list) {
    if (list == NULL) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
