#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTS 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Assume 1 for valid, 0 for invalid
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void free_dynamic_array(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
}

int add_crc_pdu(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Buffer overflow
    }

    array->data[array->count++] = pdu;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int probabilistic_crcflag() {
    return rand() % 2; // Simple random 50% chance for demonstration
}

void populate_and_add(DynamicArray *array) {
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu.RNTI = rand() % 10000;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu.CRCFLAG = probabilistic_crcflag();

        if (add_crc_pdu(array, pdu) != 0) {
            fprintf(stderr, "Failed to add PDU at index %zu\n", i);
            break; // Exit on failure
        }
    }
}

void log_array(const DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen("log.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    for (size_t i = 0; i < array->count; ++i) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
                array->data[i].RX_UE_INFORMATION_TAG,
                array->data[i].RNTI,
                array->data[i].CRC_INDICATION_REL8_TAG,
                array->data[i].CRCFLAG);
    }

    fclose(file);
    pthread_mutex_unlock(&array->lock);
}

int main() {
    DynamicArray array;
    init_dynamic_array(&array);

    populate_and_add(&array);
    log_array(&array);

    free_dynamic_array(&array);
    return 0;
}
