        pthread_mutex_lock(&list_mutex);
        nfa_entry_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfa_entry_list[i]) {
            fprintf(stderr, "Memory allocation failed for entry %d\n", i);
            continue;
        }
        pthread_mutex_unlock(&list_mutex);

        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.RX_UE_INFORMATION_TAG = rand();
        crc_tag.RNTI = rnti;

        nfa_entry_list[i]->crc_tag = crc_tag;
        nfa_entry_list[i]->CRCFLAG = is_rnti_registered(rnti) ? (rand() % 2) : 0;
    }
}

// Function to simulate RNTI registration
void register_rnti(int rnti) {
    pthread_mutex_lock(&rnti_table_mutex);
    registered_RNTIs[rnti % MAX_ENTRIES] = 1;
    pthread_mutex_unlock(&rnti_table_mutex);
}

// Unit test function
