#define MAX_RNTIS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t rnti_pool_lock = PTHREAD_MUTEX_INITIALIZER;
static uint16_t allocated_rntis[MAX_RNTIS];
static size_t allocated_count = 0;
static int allocation_failures = 0;
static int crcflag_set_frequency[2] = {0, 0}; // Index 0 for false, 1 for true

void log_message(const char *message) {
    printf("%s\n", message);
}

void* allocate_rnti(void) {
    pthread_mutex_lock(&rnti_pool_lock);

    if (allocated_count >= MAX_RNTIS) {
        allocation_failures++;
        pthread_mutex_unlock(&rnti_pool_lock);
        return NULL;
    }

    uint16_t rnti = rand() % 65536; // Random RNTI
    bool unique_rnti = true;

    for (size_t i = 0; i < allocated_count; ++i) {
        if (allocated_rntis[i] == rnti) {
            unique_rnti = false;
            break;
        }
    }

    if (!unique_rnti) {
        pthread_mutex_unlock(&rnti_pool_lock);
        return allocate_rnti();
    }

    allocated_rntis[allocated_count++] = rnti;
    pthread_mutex_unlock(&rnti_pool_lock);

    return (void*)(uintptr_t)rnti;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = aligned_alloc(16, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_message("Memory allocation failed for PDU");
        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = rand(); // Assign a random value

    void* rnti_ptr = allocate_rnti();
    if (rnti_ptr == NULL) {
        free(pdu);
        return NULL;
    }
    pdu->RNTI = (uint16_t)(uintptr_t)rnti_ptr;

    bool crc_flag = rand() % 2; // Randomly set CRCFLAG
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;
    crcflag_set_frequency[crc_flag]++;

    log_message("PDU created successfully");

    return pdu;
}

void reset_rnti_pool() {
    pthread_mutex_lock(&rnti_pool_lock);
    allocated_count = 0;
    allocation_failures = 0;
    for (int i = 0; i < 2; ++i) crcflag_set_frequency[i] = 0;
    log_message("RNTI pool reset");
    pthread_mutex_unlock(&rnti_pool_lock);
}

void log_statistics() {
    printf("Allocation Failures: %d\n", allocation_failures);
    printf("CRCFLAG set to false: %d times, true: %d times\n",
           crcflag_set_frequency[0], crcflag_set_frequency[1]);
}

int main() {
    srand(time(NULL));

    // Simulate concurrent access
    pthread_t threads[MAX_RNTIS];
    for (size_t i = 0; i < MAX_RNTIS; ++i) {
        if (pthread_create(&threads[i], NULL, (void*(*)(void*))create_pdu, NULL)) {
            log_message("Failed to create thread");
            break;
        }
    }

    for (size_t i = 0; i < MAX_RNTIS; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_statistics();
    reset_rnti_pool();

    return 0;
}
```

