#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint32_t default_RX_UE_INFORMATION_TAG;
    uint16_t default_RNTI;
    uint8_t default_CRC_INDICATION_REL8_TAG;
} Configuration;

pthread_mutex_t rnti_table_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate and populate CRC indication PDUs
int generate_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, int N, Configuration config) {
    if (N <= 0 || pdus == NULL) return -1;

    *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -2;
    }

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&rnti_table_mutex);
        // Simulate checking/updating RNTI registration table
        (*pdus)[i].RX_UE_INFORMATION_TAG = config.default_RX_UE_INFORMATION_TAG + i;
        (*pdus)[i].RNTI = config.default_RNTI + i;
        pthread_mutex_unlock(&rnti_table_mutex);

        (*pdus)[i].CRC_INDICATION_REL8_TAG = config.default_CRC_INDICATION_REL8_TAG;
        (*pdus)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return 0;
}

// Function to free allocated memory for PDUs
void free_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus != NULL) {
        free(pdus);
    }
}

