#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
    pthread_mutex_t lock;
} CRC_INDICATOR_POOL;

void initialize_pool(CRC_INDICATOR_POOL *pool, size_t requested_count) {
    if (requested_count > MAX_ENTRIES) {
        fprintf(stderr, "Warning: Requested entry count exceeds maximum limit. Truncating to %d.\n", MAX_ENTRIES);
        requested_count = MAX_ENTRIES;
    }

    pool->array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(requested_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->array) {
        perror("Failed to allocate memory for CRC indication array");
        exit(EXIT_FAILURE);
    }

    pool->count = requested_count;
    pthread_mutex_init(&pool->lock, NULL);
}

void populate_crc_array(CRC_INDICATOR_POOL *pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        pool->array[i].RX_UE_INFORMATION_TAG = (uint32_t)(rand() % UINT32_MAX);
        pool->array[i].RNTI = (uint16_t)(rand() % UINT16_MAX + 1); // Ensure non-zero RNTI
        pool->array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pool->array[i].CRCFLAG = (pool->array[i].RNTI & 1) ? 0 : 1; // Set based on parity of RNTI
    }

    pthread_mutex_unlock(&pool->lock);
}

void cleanup_pool(CRC_INDICATOR_POOL *pool) {
    free(pool->array);
    pthread_mutex_destroy(&pool->lock);
}

int main() {
    CRC_INDICATOR_POOL pool;
    initialize_pool(&pool, 15000); // Example of handling request beyond limit
    populate_crc_array(&pool);

    // Cleanup resources after use
    cleanup_pool(&pool);

    return 0;
}
```

