        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);
        TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &num_extra_samples);
    } else {
        fprintf(stderr, "Required metadata not found in TIFF file\n");
        TIFFClose(tif);
        free(pdu_array);
        return -1;
    }

    extract_tiff_metadata(tif, &bits_per_sample, &samples_per_pixel, &num_extra_samples);

    // Compute MD5 hash of the given string
    unsigned char md5_hash[16];
    generate_md5_hash(string_to_hash, md5_hash);

    TIFFClose(tif);

    // Output metadata and hash for demonstration purposes (could be stored or processed further)
