import threading

typedef struct {
    unsigned char mac_header[6];
    int vlan_id;
    unsigned short tcp_flags;
    unsigned short checksum;
} MAC_PACKET;

unsigned short generate_checksum(MAC_PACKET *packet, unsigned int seed) {
    // Example checksum algorithm
    unsigned long sum = 0;
    for (int i = 0; i < sizeof(packet->mac_header); ++i) {
        sum += packet->mac_header[i];
    }
    sum += packet->vlan_id + packet->tcp_flags + seed;
    return (unsigned short)(sum & 0xFFFF);
}

MAC_PACKET* initialize_mac_packets(size_t num_structures, unsigned int seed,
                                   size_t max_memory_usage_per_thread) {
    if (num_structures == 0 || max_memory_usage_per_thread == 0) {
        fprintf(stderr, "Invalid configuration parameters.\n");
        return NULL;
    }

    // Calculate the number of structures that fit in the allowed memory
    size_t struct_size = sizeof(MAC_PACKET);
    size_t max_num_structs = max_memory_usage_per_thread / struct_size;

    if (num_structures > max_num_structs) {
        fprintf(stderr, "Requested structure count exceeds maximum allowed memory usage.\n");
        num_structures = max_num_structs;
    }

    MAC_PACKET* packets = (MAC_PACKET*)malloc(num_structures * sizeof(MAC_PACKET));
    if (!packets) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Use a mutex for thread-safe initialization
    threading.Lock init_lock;

    // Function to initialize each packet structure
    auto initialize_packet = [](MAC_PACKET* packet, unsigned int seed) -> void {
        for (int i = 0; i < 6; ++i) {
            packet->mac_header[i] = rand() % 256;
        }
        packet->vlan_id = rand() % 4096;
        packet->tcp_flags = rand() % 65536;
        packet->checksum = generate_checksum(packet, seed);
    };

    // Initialize packets in a thread-safe manner
    init_lock.acquire();
    for (size_t i = 0; i < num_structures; ++i) {
        initialize_packet(&packets[i], seed);
    }
    init_lock.release();

    return packets;
}

