#define MAX_ELEMENTS 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_LIST_T;

void list_init(NFAPI_LIST_T *list) {
    list->elements = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

bool list_add(NFAPI_LIST_T *list, const NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&list->lock);

    if (list->count == MAX_ELEMENTS) {
        printf("Maximum capacity reached.\n");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    size_t new_size = list->count + 1;
    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_elements) {
        printf("Memory reallocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    list->elements = new_elements;
    list->elements[list->count] = *new_element;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool list_get(NFAPI_LIST_T *list, size_t index, NFAPI_CRC_INDICATION_PDU_T *out_element) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->count) {
        printf("Index out of bounds.\n");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    *out_element = list->elements[index];
    pthread_mutex_unlock(&list->lock);
    return true;
}

void list_destroy(NFAPI_LIST_T *list) {
    pthread_mutex_lock(&list->lock);

    free(list->elements);
    list->elements = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

