#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Pre-allocated memory pool
static void* memory_pool[MAX_SIZE];
static pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    // Placeholder for integration with an external logging system
    printf("%s\n", message);
}

int validate_parameters(int N) {
    if (N <= 0 || N > MAX_SIZE) {
        log_message("Invalid parameter: N out of range.");
        return 0;
    }
    return 1;
}

void* allocate_from_pool(size_t size, int index) {
    pthread_mutex_lock(&memory_mutex);
    if (!memory_pool[index]) {
        memory_pool[index] = malloc(size);
        if (!memory_pool[index]) {
            log_message("Memory allocation failed.");
            pthread_mutex_unlock(&memory_mutex);
            return NULL;
        }
    }
    void* ptr = memory_pool[index];
    pthread_mutex_unlock(&memory_mutex);
    return ptr;
}

void reset_crcflags(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    for (int i = 0; i < N; ++i) {
        array[i].CRCFLAG = 0; // Reset to default state
    }
}

int check_integrity(const NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    for (int i = 0; i < N; ++i) {
        if (array[i].RX_UE_INFORMATION_TAG <= 0 || array[i].RNTI <= 0) {
            log_message("Integrity check failed: Invalid RX_UE_INFORMATION_TAG or RNTI.");
            return 0;
        }
    }
    return 1;
}

void* create_crc_indication_array(int N) {
    if (!validate_parameters(N)) {
        return NULL;
    }

    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_from_pool(total_size, 0);

    if (!array) {
        log_message("Failed to allocate memory from pool.");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100 + 1; // Random valid value
        array[i].RNTI = rand() % 500 + 1; // Random valid value
        array[i].CRCFLAG = rand() & 0x01; // Random CRCFLAG, ensuring no overflow

        log_message("Allocated and initialized an NFAPI_CRC_INDICATION_PDU_T structure.");
    }

    if (!check_integrity(array, N)) {
        free(array);
        return NULL;
    }

    reset_crcflags(array, N);

    log_message("CRC flags reset to default state.");

    // Track memory usage statistics
    size_t used_memory = 0;
    for (int i = 0; i < MAX_SIZE; ++i) {
        if (memory_pool[i]) {
            used_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }
    }
    log_message("Memory usage: %zu bytes.", used_memory);

    return array;
}

void free_crc_indication_array(void *array, int N) {
    if (!array) return;

    pthread_mutex_lock(&memory_mutex);
    memory_pool[0] = NULL; // Reset pool index
    pthread_mutex_unlock(&memory_mutex);

    log_message("Memory freed for CRC indication array.");
}
