#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int type;
    unsigned long sequence_number;
} PacketHeader;

typedef struct {
    PacketHeader header;
    size_t payload_length;
    unsigned char *payload;
    unsigned short checksum;
} DataPacket;

unsigned short calculate_checksum(const PacketHeader* header, const unsigned char *payload, size_t length) {
    unsigned long sum = 0;
    for (int i = 0; i < sizeof(PacketHeader); ++i)
        sum += ((const unsigned char*)header)[i];

    for (size_t i = 0; i < length; ++i)
        sum += payload[i];

    return (unsigned short)(sum & 0xFFFF);
}

DataPacket* initialize_data_packets(size_t packet_count, size_t max_payload_length) {
    if (packet_count == 0 || max_payload_length == 0)
        return NULL;

    DataPacket *packets = malloc(packet_count * sizeof(DataPacket));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed for packets\n");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < packet_count; ++i) {
        packets[i].header.type = rand() % 256; // Simulate random packet types
        packets[i].header.sequence_number = rand(); // Random sequence number

        size_t payload_length = rand() % max_payload_length + 1;
        packets[i].payload_length = payload_length;

        packets[i].payload = malloc(payload_length);
        if (!packets[i].payload) {
            fprintf(stderr, "Memory allocation failed for packet payload at index %zu\n", i);

            // Cleanup previously allocated memory
            for (size_t j = 0; j < i; ++j)
                free(packets[j].payload);

            free(packets);
            return NULL;
        }

        // Populate the payload with random data
        for (size_t j = 0; j < payload_length; ++j) {
            packets[i].payload[j] = rand() % 256;
        }

        // Calculate and store checksum
        packets[i].checksum = calculate_checksum(&packets[i].header, packets[i].payload, payload_length);

        // Verify the integrity of the packet by recalculating the checksum
        unsigned short new_checksum = calculate_checksum(&packets[i].header, packets[i].payload, payload_length);
        if (new_checksum != packets[i].checksum) {
            fprintf(stderr, "Checksum verification failed for packet at index %zu\n", i);

            // Cleanup previously allocated memory
            for (size_t j = 0; j <= i; ++j)
                free(packets[j].payload);

            free(packets);
            return NULL;
        }
    }

    return packets;
}

void free_data_packets(DataPacket *packets, size_t packet_count) {
    if (!packets)
        return;

    for (size_t i = 0; i < packet_count; ++i) {
        free(packets[i].payload);
    }

    free(packets);
}
