int create_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t n, const unsigned int max_rnti) {
    if (n == 0 || list == NULL || max_rnti <= 0 || max_rnti > MAX_RNTI) {
        return -1; // Invalid input
    }

    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        return -2; // Memory allocation failure
    }

    srand(time(NULL)); // Seed the random number generator

    unsigned int rnti_values[max_rnti];
    for (unsigned int i = 0; i < max_rnti; ++i) {
        rnti_values[i] = i + 1;
    }

    size_t unique_rnti_count = max_rnti;
    if (unique_rnti_count > n / 2 + 1) {
        unique_rnti_count = n / 2 + 1; // Ensure we have enough unique RNTIs for alternating
    }

    for (size_t i = 0; i < n; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 256;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 256;

        if (i > 0 && unique_rnti_count > 1) { // Avoid consecutive same RNTI
            size_t rnti_index = rand() % (unique_rnti_count - 1);
            while (rnti_index >= unique_rnti_count || 
                   ((*list)[i].RNTI == (*list)[i - 1].RNTI && rnti_index == 0)) {
                rnti_index = rand() % (unique_rnti_count - 1);
            }
            if (rnti_index == unique_rnti_count - 1) { // Wrap around to the start
                (*list)[i].RNTI = rnti_values[0];
            } else {
                (*list)[i].RNTI = rnti_values[rnti_index + 1];
            }
        } else {
            (*list)[i].RNTI = rnti_values[rand() % unique_rnti_count];
        }

        // Ensure RNTI is not the same as the previous if possible
        while (i > 0 && (*list)[i].RNTI == (*list)[i - 1].RNTI && unique_rnti_count > 2) {
            unsigned int new_rnti = rnti_values[rand() % (unique_rnti_count - 1)];
            if (new_rnti != (*list)[i].RNTI) {
                (*list)[i].RNTI = new_rnti;
            }
        }

        (*list)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return 0; // Success
}
