#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_EVENTS 1000000
#define TIMESTAMP_SIZE sizeof(time_t)
#define TYPE_SIZE 32
#define CELL_ID_SIZE 64

typedef struct {
    time_t timestamp;
    char eventType[TYPE_SIZE];
    char cellIdentifier[CELL_ID_SIZE];
} EventLog;

typedef struct Node {
    EventLog event;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LogList;

// Function prototypes
void addEvent(LogList* list, const EventLog* event);
void removeOldEvents(LogList* list, time_t retentionPeriod);
int retrieveFilteredEvents(LogList* list, const char* cellId, EventLog** eventsOut, int* count);

// Helper functions
static Node* createNode(const EventLog* event) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->event.timestamp = event->timestamp;
    strncpy(newNode->event.eventType, event->eventType, TYPE_SIZE);
    strncpy(newNode->event.cellIdentifier, event->cellIdentifier, CELL_ID_SIZE);
    newNode->next = NULL;
    return newNode;
}

static void freeList(Node* head) {
    Node* tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

// Function implementations
void addEvent(LogList* list, const EventLog* event) {
    pthread_mutex_lock(&list->lock);

    // Check for duplicates
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->event.cellIdentifier, event->cellIdentifier) == 0 &&
            strcmp(current->event.eventType, event->eventType) == 0 &&
            current->event.timestamp == event->timestamp) {
            pthread_mutex_unlock(&list->lock);
            return; // Duplicate found, do not add
        }
        current = current->next;
    }

    Node* newNode = createNode(event);
    if (newNode) {
        newNode->next = list->head;
        list->head = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

void removeOldEvents(LogList* list, time_t retentionPeriod) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    time_t currentTime = time(NULL);

    while (current != NULL) {
        if ((currentTime - current->event.timestamp) > retentionPeriod) {
            Node* toDelete = current;
            if (prev == NULL) {
                list->head = current->next; // Remove head
            } else {
                prev->next = current->next; // Remove middle or end node
            }
            current = current->next;
            free(toDelete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int retrieveFilteredEvents(LogList* list, const char* cellId, EventLog** eventsOut, int* count) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    *count = 0;

    // First pass to count the number of matching events
    while (current != NULL) {
        if (strcmp(current->event.cellIdentifier, cellId) == 0) {
            (*count)++;
        }
        current = current->next;
    }

    // Allocate memory for results
    *eventsOut = (EventLog*)malloc(*count * sizeof(EventLog));
    if (!*eventsOut) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    int index = 0;
    current = list->head;

    // Second pass to collect the events
    while (current != NULL) {
        if (strcmp(current->event.cellIdentifier, cellId) == 0) {
            (*eventsOut)[index++] = current->event;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Initialize the log list
void initLogList(LogList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Destroy the log list and free resources
void destroyLogList(LogList* list) {
    freeList(list->head);
    pthread_mutex_destroy(&list->lock);
}
