    size_t count;
    pthread_mutex_t lock;
} LTE_UE_Context_List;

// Function to initialize and configure the LTE UE context list
LTE_UE_Context_List* init_lte_ue_context_list(size_t num_ue) {
    LTE_UE_Context_List *list = malloc(sizeof(LTE_UE_Context_List));
    if (!list) return NULL; // Handle memory allocation failure

    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;

    // Allocate memory for the contexts
    list->contexts = calloc(num_ue, sizeof(LTE_UE_Context));
    if (!list->contexts) {
        free(list); // Free allocated list structure in case of failure
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < num_ue; ++i) {
        // Simulate fetching initial RNTI and DCI format from an external data source
        list->contexts[i].rnti = rand() % 10000 + 1; // Example: Random valid RNTI

        // Fetch or simulate DCI format (this is just random for demonstration)
        list->contexts[i].dci_format = rand() % 10 + 1;

        // Set PDCCH search space, assuming some predefined logic
        list->contexts[i].pdcch_search_space = rand() % 5 + 1;
    }

    list->count = num_ue;

    pthread_mutex_unlock(&list->lock);

    return list;
}

// Function to free the LTE UE context list and handle potential memory leaks
void free_lte_ue_context_list(LTE_UE_Context_List *list) {
    if (list) {
        pthread_mutex_lock(&list->lock);

        if (list->contexts) {
            free(list->contexts); // Free dynamically allocated contexts
        }

        pthread_mutex_unlock(&list->lock);

        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Function to safely access and modify a context in the list
void update_lte_ue_context(LTE_UE_Context_List *list, size_t index, int new_dci_format) {
    if (!list || index >= list->count) return;

    pthread_mutex_lock(&list->lock);

    // Update DCI format for the given index
    list->contexts[index].dci_format = new_dci_format;

    pthread_mutex_unlock(&list->lock);
}

// Example usage and testing of initialization, update, and cleanup
int main() {
    size_t num_ue = 10;
    LTE_UE_Context_List *ue_list = init_lte_ue_context_list(num_ue);

    if (!ue_list) {
        fprintf(stderr, "Failed to initialize UE context list\n");
        return EXIT_FAILURE;
    }

