#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <stdbool.h>

#define INITIAL_CAPACITY 1000
#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Assume this is a boolean type for clarity.
} NFAPI_CRC_INDICATION_PDU_T;

// Statistics structure to track successful and failed operations
typedef struct {
    int success_count;
    int fail_count;
} crc_statistics_t;

// Callback function prototype
typedef void (*statistics_callback)(crc_statistics_t stats);

// Structure holding the dynamic array and its metadata
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    crc_statistics_t statistics;
} CRC_Indication_Manager;

void initialize_manager(CRC_Indication_Manager *manager) {
    manager->size = 0;
    manager->capacity = INITIAL_CAPACITY;
    manager->array = malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        perror("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->mutex, NULL);
    manager->statistics.success_count = 0;
    manager->statistics.fail_count = 0;
}

void clear_manager(CRC_Indication_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);
    memset(manager->array, 0, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = 0;
    pthread_mutex_unlock(&manager->mutex);
}

bool resize_array_if_needed(CRC_Indication_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity && manager->capacity < MAX_ELEMENTS) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&manager->mutex);
            return false; // Indicate failure
        }

        manager->capacity = new_capacity;
        manager->array = new_array;
    }

    pthread_mutex_unlock(&manager->mutex);
    return true; // Indicate success
}

bool add_crc_indication(CRC_Indication_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!resize_array_if_needed(manager)) {
        manager->statistics.fail_count++;
        return false;
    }

    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&manager->mutex);
        manager->statistics.fail_count++;
        return false; // Buffer overflow
    }

    manager->array[manager->size++] = pdu;
    manager->statistics.success_count++;

    pthread_mutex_unlock(&manager->mutex);
    return true;
}

void update_statistics(CRC_Indication_Manager *manager, statistics_callback callback) {
    pthread_mutex_lock(&manager->mutex);

    crc_statistics_t stats = manager->statistics;

    pthread_mutex_unlock(&manager->mutex);

    if (callback) {
        callback(stats);
    }
}

// Example implementation of the callback function
void print_statistics(crc_statistics_t stats) {
    printf("Success: %d, Failures: %d\n", stats.success_count, stats.fail_count);
}

int main() {
    CRC_Indication_Manager manager;
    initialize_manager(&manager);

    // Example usage with dummy data and a randomization for CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, rand() % 2 == 0}; // Random CRCFLAG

    if (add_crc_indication(&manager, pdu)) {
        printf("PDU added successfully.\n");
    } else {
        printf("Failed to add PDU.\n");
    }

    update_statistics(&manager, print_statistics);

    clear_manager(&manager);

    free(manager.array); // Free the memory when done
    pthread_mutex_destroy(&manager.mutex);

    return 0;
}
```

