    // Set timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    pdu->rxUeInformationTag.timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000; // Convert to microseconds

    // Set CRC flag randomly
    pdu->crcIndicationRel8Tag.crcFlag = rand() % 2;

    return pdu;
}

// Function to periodically recalibrate timestamps
void recalibrate_timestamp(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        pdu->rxUeInformationTag.timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000; // Convert to microseconds
    }
}

// Function to dynamically populate the list of PDUs with error handling and retry logic
bool populate_pdu_list(NFAPI_CRC_INDICATION_PDU_T **pduList, int maxRetries) {
    bool success = false;
    int attempts = 0;

    while (attempts < maxRetries && !success) {
        if (MAX_PDU_COUNT > 0) {
            NFAPI_CRC_INDICATION_PDU_T *newPdu = initialize_pdu();
            if (newPdu != NULL) {
                pduList[MAX_PDU_COUNT - 1] = newPdu;
                recalibrate_timestamp(newPdu);
                success = true;
            } else {
                printf("Memory allocation failed, retrying...\n");
                attempts++;
                sleep(1 << attempts); // Exponential backoff
            }
        } else {
            printf("Maximum PDU count reached. Cannot add more PDUs.\n");
            break;
        }
    }

    if (!success) {
        printf("Failed to populate the PDU list after %d retries.\n", maxRetries);
    }

    return success;
}

// Main function for demonstration purposes
int main() {
    srand(time(NULL)); // Seed random number generator

    NFAPI_CRC_INDICATION_PDU_T *pduList[MAX_PDU_COUNT];
    int maxRetries = 5;

    memset(pduList, 0, sizeof(pduList));

    if (populate_pdu_list(pduList, maxRetries)) {
        printf("PDUs populated successfully.\n");
    } else {
        printf("Failed to populate PDUs.\n");
    }

    // Cleanup
    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        if (pduList[i]) {
            free(pduList[i]);
        }
    }

    return 0;
}
