#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int NAS_PDU;
    int UE_Id;
    int TransmissionTimingAdjustment;
} LTE_Uplink_NAS_Transport_PDU;

typedef struct {
    LTE_Uplink_NAS_Transport_PDU *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PDUArray;

#define INITIAL_CAPACITY 100
#define SCALE_FACTOR 2

void revalidate_timing_adjustments(PDUArray *pdu_array, int time_offset);

PDUArray* initialize_pdu_array(int time_offset) {
    PDUArray *pdu_array = (PDUArray *)malloc(sizeof(PDUArray));
    if (!pdu_array) return NULL;

    pthread_mutex_init(&pdu_array->lock, NULL);
    pdu_array->capacity = INITIAL_CAPACITY;
    pdu_array->count = 0;

    pdu_array->array = (LTE_Uplink_NAS_Transport_PDU *)malloc(sizeof(LTE_Uplink_NAS_Transport_PDU) * pdu_array->capacity);
    if (!pdu_array->array) {
        free(pdu_array);
        return NULL;
    }

    pdu_array->time_offset = time_offset;

    return pdu_array;
}

int add_pdu(PDUArray *pdu_array, int nas_pdu, int ue_id) {
    pthread_mutex_lock(&pdu_array->lock);

    if (pdu_array->count == pdu_array->capacity) {
        size_t new_capacity = pdu_array->capacity * SCALE_FACTOR;
        LTE_Uplink_NAS_Transport_PDU *new_array = (LTE_Uplink_NAS_Transport_PDU *)realloc(pdu_array->array, sizeof(LTE_Uplink_NAS_Transport_PDU) * new_capacity);

        if (!new_array) {
            pthread_mutex_unlock(&pdu_array->lock);
            return -1;
        }

        pdu_array->capacity = new_capacity;
        pdu_array->array = new_array;
    }

    LTE_Uplink_NAS_Transport_PDU pdu;
    pdu.NAS_PDU = nas_pdu;
    pdu.UE_Id = ue_id;
    pdu.TransmissionTimingAdjustment = ue_id * SCALE_FACTOR + pdu_array->time_offset;

    pdu_array->array[pdu_array->count++] = pdu;

    pthread_mutex_unlock(&pdu_array->lock);

    return 0;
}

void revalidate_pdu_array(PDUArray *pdu_array) {
    revalidate_timing_adjustments(pdu_array, pdu_array->time_offset);
}

static void revalidate_timing_adjustments(PDUArray *pdu_array, int time_offset) {
    pthread_mutex_lock(&pdu_array->lock);

    for (size_t i = 0; i < pdu_array->count; ++i) {
        pdu_array->array[i].TransmissionTimingAdjustment =
            pdu_array->array[i].UE_Id * SCALE_FACTOR + time_offset;
    }

    pthread_mutex_unlock(&pdu_array->lock);
}

void free_pdu_array(PDUArray *pdu_array) {
    if (!pdu_array) return;

    pthread_mutex_lock(&pdu_array->lock);

    free(pdu_array->array);

    pthread_mutex_unlock(&pdu_array->lock);
    pthread_mutex_destroy(&pdu_array->lock);
    free(pdu_array);
}

// Example Usage
