int add_pdu_to_list(int rx_ue_info_tag, int rnti) {
    pthread_mutex_lock(&list_mutex);

    if (current_size >= max_list_size) {
        log_message("List is full, cannot add more elements.");
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    // Allocate memory for the new element
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
