    new_pdu->ue_info.RNTI = rnti;
    new_pdu->crc_rel8_tag.CRCFLAG = generate_random_crcflag();

    // Add to list
    if (pdu_list == NULL) {
        pdu_list = new_pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* temp = pdu_list;
        while (temp->ue_info.RX_UE_INFORMATION_TAG != 0 && temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_pdu;
        new_pdu->prev = temp; // Maintain a doubly linked list
    }

    current_size++;
    log_message("Added new PDU to the list.");
    pthread_mutex_unlock(&list_mutex);
    return 0;
}

// Function to get the number of elements in the list
size_t get_list_size() {
    pthread_mutex_lock(&list_mutex);
    size_t size = current_size;
    pthread_mutex_unlock(&list_mutex);
    return size;
}

// Cleanup function to free allocated memory
void cleanup_pdu_list() {
    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T* temp;
    while (pdu_list != NULL) {
        temp = pdu_list;
        pdu_list = pdu_list->next;
        free(temp);
    }

    current_size = 0;
    log_message("PDU list cleaned up.");
    pthread_mutex_unlock(&list_mutex);
}

// Initialization function
void initialize() {
    srand(time(NULL)); // Seed the random number generator
    log_message("System initialized.");
}

int main() {
    initialize();

    // Example usage
    add_pdu_to_list(1, 100);
    add_pdu_to_list(2, 200);

    printf("Number of PDUs in list: %zu\n", get_list_size());

    cleanup_pdu_list();
    return 0;
}
