function copyDataFromStream(stream, numBytes) {
    const outputBuffer = Buffer.allocUnsafe(numBytes);
    let totalCopied = 0;

    for (let chunk of stream) {
        if (!chunk || !Buffer.isBuffer(chunk)) continue;

        const bytesToCopy = Math.min(chunk.length, numBytes - totalCopied);
        chunk.copy(outputBuffer, totalCopied, 0, bytesToCopy);
        totalCopied += bytesToCopy;

        if (totalCopied >= numBytes) break;
    }

    return outputBuffer.slice(0, totalCopied); // Return only the filled portion
}

// Example usage:
const stream = [
    Buffer.from([1, 2, 3]),
    Buffer.from([4, 5, 6, 7, 8]),
    Buffer.from([9])
];

const result = copyDataFromStream(stream, 10);
console.log(result); // Output will be a buffer with the first 10 bytes
