#define M 10 // Maximum number of allocated structures

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pool[M];
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t lock;
    unsigned long reuse_count;
} PoolManager;

void initialize_pool(PoolManager *manager) {
    manager->head = 0;
    manager->tail = 0;
    manager->count = 0;
    manager->reuse_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int is_full(PoolManager *manager) {
    return manager->count == M;
}

int is_empty(PoolManager *manager) {
    return manager->count == 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_next_slot(PoolManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (is_full(manager)) {
        // Reuse the oldest slot
        manager->tail = (manager->tail + 1) % M;
        manager->reuse_count++;
    } else {
        manager->count++;
    }

    NFAPI_CRC_INDICATION_PDU_T *slot = &manager->pool[manager->head];
    manager->head = (manager->head + 1) % M;

    pthread_mutex_unlock(&manager->lock);
    return slot;
}

void populate_structure(NFAPI_CRC_INDICATION_PDU_T *structure, size_t index) {
    structure->RX_UE_INFORMATION_TAG = rand() % 1000; // Random valid tag
    structure->RNTI = (uint16_t)(index + 1); // Unique RNTI for demonstration
    structure->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
}

