    CRC_INDICATION_REL8 *CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU;

// Node of the doubly linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU data;
    struct ListNode* prev;
    struct ListNode* next;
} ListNode;

// Doubly linked list structure with synchronization primitives for thread safety
typedef struct LinkedList {
    ListNode *head, *tail;
    int count;
    threading.Lock lock; // Use Python's threading module for locks
} LinkedList;

// Initialize the doubly linked list
void init_list(LinkedList* list) {
    list->head = list->tail = NULL;
    list->count = 0;
    threading.Lock_init(&list->lock);
}

// Insert a node into the linked list
int insert_node(LinkedList *list, NFAPI_CRC_INDICATION_PDU pdu) {
    ListNode *newNode = (ListNode *)custom_malloc(sizeof(ListNode));
    if (!newNode) return -1;

    newNode->data = pdu;
    newNode->prev = NULL;
    newNode->next = NULL;

    threading.Lock_acquire(&list->lock);

    if (list->tail == NULL) { // List is empty
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }

    list->count++;
    threading.Lock_release(&list->lock);

    return 0; // Success
}

// Calculate the average CRCFLAG value
float calculate_average_crcflag(LinkedList *list) {
    int totalCRCFLAGS = 0;

    threading.Lock_acquire(&list->lock);

    ListNode *current = list->head;
    while (current != NULL) {
        totalCRCFLAGS += current->data.CRC_INDICATION_REL8_TAG->CRCFLAG;
        current = current->next;
    }

    float average = (list->count > 0) ? (float)totalCRCFLAGS / list->count : 0.0f;

    threading.Lock_release(&list->lock);

    return average;
}

// Example logging function
void log_message(const char *message) {
    printf("%s\n", message); // Simple console logger
}

// Populate the list with NFAPI_CRC_INDICATION_PDU structures
int populate_list(LinkedList *list, int num_elements) {
    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();

        CRC_INDICATION_REL8* crc_tag = (CRC_INDICATION_REL8*)custom_malloc(sizeof(CRC_INDICATION_REL8));
        if (!crc_tag) return -1;

        crc_tag->CRCFLAG = rand() % 2; // Randomly set to 0 or 1
        pdu.CRC_INDICATION_REL8_TAG = crc_tag;

        if (insert_node(list, pdu) != 0) {
            log_message("Failed to insert node.");
            return -1;
        }
    }

    return 0; // Success
}

int main() {
    LinkedList list;
    init_list(&list);

    int num_elements = 1000;
    if (populate_list(&list, num_elements) == 0) {
        float average_crcflag = calculate_average_crcflag(&list);
        printf("Average CRCFLAG: %.2f\n", average_crcflag);
