    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    RX_UE_INFORMATION_TAG_T ue_info_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;  // For thread safety in high-load conditions
} CRCIndicationList;

int log_callback(const char* message);  // Placeholder for asynchronous logging function

// Initialize the list
void initialize_list(CRCIndicationList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Validate RNTI uniqueness and CRCFLAG within the list
int validate_list(const CRCIndicationList* list, uint16_t rnti_to_check) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.ue_info_tag.RNTI == rnti_to_check)
            return 0; // RNTI already exists
        current = current->next;
    }
    return 1; // RNTI is unique
}

// Add element to the list with validation
int add_element(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!validate_list(list, new_data.ue_info_tag.RNTI))
        return -1;  // RNTI already exists

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node)
        return -2;  // Memory allocation failure

    new_node->data = new_data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Added RNTI %u", new_data.ue_info_tag.RNTI);
    if (log_callback(log_message) != 0)
        fprintf(stderr, "Failed to log message: %s\n", log_message);

    return 0;
}

// Validate the list for integrity
int validate_list_integrity(const CRCIndicationList* list) {
    uint16_t rnti_set[MAX_ELEMENTS] = {0};
    size_t count = 0;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL && count < MAX_ELEMENTS) {
        if (rnti_set[current->data.ue_info_tag.RNTI])
            return -1; // Duplicate RNTI found

        rnti_set[current->data.ue_info_tag.RNTI] = 1;
        current = current->next;
        count++;
    }
    pthread_mutex_unlock(&list->lock);

    if (count != list->size)
        return -2; // Size mismatch

    return 0; // List is valid
}

// Free the list and its resources
void free_list(CRCIndicationList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Example function to fill the list with random elements
void generate_random_list(CRCIndicationList* list, size_t num_elements) {
    srand(time(NULL));  // Seed for randomness

    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T new_data;
        do {
            new_data.ue_info_tag.RNTI = rand() % MAX_ELEMENTS;
            new_data.CRC_INDICATION_REL8_TAG = rand() % 256;
            new_data.CRCFLAG = rand() % 2; // Random CRC flag
        } while (!add_element(list, new_data));
    }
}

int main() {
    CRCIndicationList list;
    initialize_list(&list);

    generate_random_list(&list, MAX_ELEMENTS);

    if (validate_list_integrity(&list) == 0) {
        printf("The list is valid.\n");
    } else {
        fprintf(stderr, "The list integrity check failed!\n");
    }

    free_list(&list);
    return 0;
}
