['Below is a C code implementation that meets the requirements specified in your task description:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_POOL_SIZE 10000

// Memory pool node definition
typedef struct PoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
} PoolNode;

// Memory pool structure
typedef struct {
    PoolNode* free_list;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool() {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    for (int i = 0; i < MAX_POOL_SIZE; ++i) {
        PoolNode* node = (PoolNode*)malloc(sizeof(PoolNode));
        if (!node) break;

        node->next = pool->free_list;
        pool->free_list = node;
    }

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    PoolNode* node = pool->free_list;
    if (!node) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Memory pool exhausted
    }

    pool->free_list = node->next;
    pthread_mutex_unlock(&pool->lock);

    return &node->data;
}

void deallocate_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    PoolNode* node = (PoolNode*)((char*)pdu - offsetof(PoolNode, data));

    pthread_mutex_lock(&pool->lock);
    node->next = pool->free_list;
    pool->free_list = node;
    pthread_mutex_unlock(&pool->lock);
}

void destroy_memory_pool(MemoryPool* pool) {
    PoolNode* current = pool->free_list;
    while (current) {
        PoolNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

