typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *prev, *next;
} ListNode;

typedef struct {
    char **cache;
    size_t size;
    pthread_mutex_t lock;
} DNSCache;

// Memory pool structure
#define POOL_SIZE 1024
char memory_pool[POOL_SIZE];
size_t pool_offset = 0;
pthread_mutex_t pool_lock;

void* custom_malloc(size_t size) {
    void *ptr;
    pthread_mutex_lock(&pool_lock);
    if (pool_offset + size <= POOL_SIZE) {
        ptr = memory_pool + pool_offset;
        pool_offset += size;
    } else {
        ptr = malloc(size);  // Fallback to system allocator
    }
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void custom_free(void *ptr, size_t size) {
    if (ptr != NULL && ptr >= memory_pool && ptr < memory_pool + POOL_SIZE) {
        // Do nothing for pool allocations
    } else {
        free(ptr);  // Free system allocated memory
    }
}

ListNode* create_list_node(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode *node = (ListNode*)custom_malloc(sizeof(ListNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->prev = node->next = NULL;
    return node;
}

void insert_list_node(ListNode **head, ListNode *new_node) {
    pthread_mutex_lock((pthread_mutex_t*)&pool_lock);  // Using the same lock for simplicity
    if (*head == NULL) {
        *head = new_node;
    } else {
        ListNode *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
    }
    pthread_mutex_unlock((pthread_mutex_t*)&pool_lock);
}

void validate_list(ListNode *head) {
    ListNode *current = head;
    while (current) {
        if (!current->data.RX_UE_INFORMATION_TAG || !current->data.RNTI) {
            fprintf(stderr, "Data integrity issue detected\n");
            exit(EXIT_FAILURE);
        }
        current = current->next;
    }
}

int init_dns_cache(DNSCache *cache, size_t cache_size) {
    pthread_mutex_init(&cache->lock, NULL);
    cache->cache = (char **)custom_malloc(cache_size * sizeof(char *));
    if (!cache->cache) {
        fprintf(stderr, "DNS Cache initialization failed\n");
        return -1;
    }
    for (size_t i = 0; i < cache_size; ++i) {
        cache->cache[i] = NULL;
    }
    cache->size = cache_size;
    return 0;
}

char* resolve_hostname(const char *hostname, DNSCache *dns_cache) {
    pthread_mutex_lock(&dns_cache->lock);
    for (size_t i = 0; i < dns_cache->size; ++i) {
        if (dns_cache->cache[i] && strcmp(dns_cache->cache[i], hostname) == 0) {
            char* resolved_ip = strdup("cached_ip"); // Mocked IP resolution
            pthread_mutex_unlock(&dns_cache->lock);
            return resolved_ip;
        }
    }

    struct hostent *host = gethostbyname(hostname);
    if (!host) {
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        pthread_mutex_unlock(&dns_cache->lock);
        return NULL;
    }

    char* ip_address = inet_ntoa(*(struct in_addr *)host->h_addr);
    dns_cache->cache[0] = strdup(hostname);  // Simplified caching
    pthread_mutex_unlock(&dns_cache->lock);
    return ip_address;
}

void log_performance_metrics(const char *message) {
    printf("LOG: %s\n", message);
}

int main() {
    DNSCache cache;
    if (init_dns_cache(&cache, 10) != 0) {
        fprintf(stderr, "Failed to initialize DNS cache\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1234};
    ListNode *head = NULL;

    insert_list_node(&head, create_list_node(pdu));
    validate_list(head);

    char* ip = resolve_hostname("example.com", &cache);
    if (ip) {
        printf("Resolved IP: %s\n", ip);
        free(ip);
    }

    log_performance_metrics("Finished DNS resolution and list management");

    return EXIT_SUCCESS;
}
