        sqlite3_close(db);
        return 1;
    }

    char *sqlQuery = "SELECT name, city, address FROM Employees WHERE supervisor_id = ?";

    sqlite3_stmt *stmt;
    rc = sqlite3_prepare_v2(db, sqlQuery, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return 1;
    }

    sqlite3_bind_text(stmt, 1, supervisorID, -1, SQLITE_STATIC);

    rc = sqlite3_step(stmt);
    while (rc == SQLITE_ROW) {
        printf("Employee Name: %s\n", sqlite3_column_text(stmt, 0));
        printf("City: %s\n", sqlite3_column_text(stmt, 1));
        printf("Address: %s\n", sqlite3_column_text(stmt, 2));
        rc = sqlite3_step(stmt);
    }

    if (rc != SQLITE_DONE) {
        fprintf(stderr, "Failed to step through rows: %s\n", sqlite3_errmsg(db));
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);

    return 0;
}

