        array[i].rnti = -1;
        array[i].complete_msg = NULL;
    }

    pthread_mutex_lock(&lock);
    return array;
}

int populate_ue_context_array(NR_UeContextInfo* array, int ue_id, int rnti) {
    if (!array || ue_id < 0 || rnti < 0) return -1;

    pthread_mutex_lock(&lock);

    for (int i = 0; i < INITIAL_SIZE; ++i) {
