    return -1;
}

void free_ue_context_array(NR_UeContextInfo* array) {
    if (!array) return;

    pthread_mutex_lock(&lock);

    for (int i = 0; i < INITIAL_SIZE; ++i) {
        if (array[i].complete_msg != NULL) {
            free(array[i].complete_msg);
            array[i].ue_id = -1;
            array[i].rnti = -1;
        }
    }

    free(array);

    pthread_mutex_unlock(&lock);

