#include <stdio.h>
#include <stdlib.h>
import threading

// Define the PAGING_REQUEST_T structure
typedef struct {
    int UE_ID;
    char TAI[6];  // Example format for Tracking Area Identity
    int priority_level;
} PAGING_REQUEST_T;

// Define the LTE_EPC_MME_APP_MSG_T structure
typedef struct MmeAppMsgNode {
    int MME_ID;
    PAGING_REQUEST_T *paging_requests;   // Dynamically allocated array
    size_t num_requests;                 // Number of paging requests
    pthread_mutex_t lock;                // Mutex for thread safety

    struct MmeAppMsgNode* next;          // Pointer to the next node in the list
} LTE_EPC_MME_APP_MSG_T;

// Function prototypes
void initialize_mme_app_msg_list(LTE_EPC_MME_APP_MSG_T **head);
void add_paging_request(LTE_EPC_MME_APP_MSG_T *mme, PAGING_REQUEST_T new_request);
void update_priority_level(LTE_EPC_MME_APP_MSG_T *mme, int ue_id, int new_priority);
void free_mme_app_msg_list(LTE_EPC_MME_APP_MSG_T **head);

// Initialize the MME application message list
void initialize_mme_app_msg_list(LTE_EPC_MME_APP_MSG_T **head) {
    *head = NULL;
}

// Function to add a paging request to an existing MME entry
void add_paging_request(LTE_EPC_MME_APP_MSG_T *mme, PAGING_REQUEST_T new_request) {
    pthread_mutex_lock(&mme->lock);

    mme->paging_requests = realloc(mme->paging_requests,
                                   (mme->num_requests + 1) * sizeof(PAGING_REQUEST_T));
    if (!mme->paging_requests) {
        perror("Failed to allocate memory for paging requests");
        exit(EXIT_FAILURE);
    }
    mme->paging_requests[mme->num_requests] = new_request;
    ++mme->num_requests;

    pthread_mutex_unlock(&mme->lock);
}

// Update the priority level of a specific UE
void update_priority_level(LTE_EPC_MME_APP_MSG_T *mme, int ue_id, int new_priority) {
    pthread_mutex_lock(&mme->lock);

    for (size_t i = 0; i < mme->num_requests; ++i) {
        if (mme->paging_requests[i].UE_ID == ue_id) {
            mme->paging_requests[i].priority_level = new_priority;
            break;
        }
    }

    pthread_mutex_unlock(&mme->lock);
}

// Free the dynamically allocated list
void free_mme_app_msg_list(LTE_EPC_MME_APP_MSG_T **head) {
    LTE_EPC_MME_APP_MSG_T *current = *head;
    while (current != NULL) {
        LTE_EPC_MME_APP_MSG_T *next = current->next;

        pthread_mutex_destroy(&current->lock);
        free(current->paging_requests);

        free(current);
        current = next;
    }
    *head = NULL;
}
