                current->prev->next = current->next;
            } else {
                nfa_list.head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                nfa_list.tail = current->prev;
            }
            free(current);
            nfa_list.count--;
            pthread_mutex_unlock(&nfa_list.lock);
            return;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&nfa_list.lock);
}

