#define MAX_ELEMENTS 50000

typedef struct {
    int TX_UE_INFORMATION_TAG;
    char *RRC_connection_state;
    void *payload_buffer;
} NFAPI_L2_PDU_T;

typedef struct UE_Entry {
    int UE_ID;
    NFAPI_L2_PDU_T data;
    struct UE_Entry *next;
} UE_Entry;

typedef struct {
    UE_Entry **table;
    size_t table_size;
    pthread_mutex_t lock;
} UE_List;

// Hash function for unique UE_IDs
unsigned long hash_UE_ID(int UE_ID, size_t table_size) {
    return (unsigned long)(UE_ID % table_size);
}

// Initialize the UE list with a given size
int init_ue_list(UE_List *list, size_t table_size) {
    if (table_size > MAX_ELEMENTS) {
        table_size = MAX_ELEMENTS;
    }
    list->table = calloc(table_size, sizeof(UE_Entry *));
    list->table_size = table_size;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

// Insert a new UE entry
int insert_ue_entry(UE_List *list, int UE_ID, NFAPI_L2_PDU_T data) {
    unsigned long index = hash_UE_ID(UE_ID, list->table_size);

    pthread_mutex_lock(&list->lock);
    UE_Entry *entry = list->table[index];

    while (entry != NULL) {
        if (entry->UE_ID == UE_ID) {
            // UE_ID already exists
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        entry = entry->next;
    }

    UE_Entry *new_entry = malloc(sizeof(UE_Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }

    new_entry->UE_ID = UE_ID;
    new_entry->data = data;
    new_entry->next = list->table[index];
    list->table[index] = new_entry;

    pthread_mutex_unlock(&list->lock);

    // Asynchronous logging (pseudo-code)
    // log_async("Inserted UE_ID: %d", UE_ID);

    return 0;
}

// Validate the integrity of the list
int validate_ue_list(UE_List *list) {
