// Definitions for the structures used in this example

typedef struct {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate pseudo-random numbers based on a seed
uint32_t simple_random(uint32_t *seed) {
    *seed = (*seed * 1103515245 + 12345);
    return (*seed / 65536) % 32768;
}

// CRC calculation using polynomial XOR operation with the last three values
uint32_t calculate_crcflag(CRC_INDICATION_REL8_TAG *last_tags, uint32_t crc_flag) {
    uint32_t crc = crc_flag ^ (last_tags[0].CRCFLAG | last_tags[1].CRCFLAG | last_tags[2].CRCFLAG);
    // Simple polynomial example: x^3 + x + 1
    crc ^= (crc << 3);
    return crc;
}

// Function to dynamically create and populate the array of structures
NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indication_pdus(size_t count, uint32_t seed) {
    if (count > 10000) {
        fprintf(stderr, "Error: Count exceeds maximum limit of 10,000.\n");
        return NULL;
    }

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    CRC_INDICATION_REL8_TAG last_tags[3] = {{0}, {0}, {0}};
    uint32_t current_crc_flag = 0;

    for (size_t i = 0; i < count; ++i) {
        // Generate RX_UE_INFORMATION_TAG and RNTI using a pseudo-random number generator
        pdus[i].RX_UE_INFORMATION_TAG = simple_random(&seed);
        pdus[i].RNTI = simple_random(&seed);

        // Calculate CRCFLAG based on the last three values
        if (i >= 3) {
            current_crc_flag = calculate_crcflag(last_tags, current_crc_flag);
        } else {
            current_crc_flag = simple_random(&seed); // Initial random CRC for first three elements
        }
        pdus[i].crc_tag.CRCFLAG = current_crc_flag;

        // Update the last tags array
        if (i >= 3) {
            last_tags[0] = last_tags[1];
            last_tags[1] = last_tags[2];
        }
        last_tags[i % 3] = pdus[i].crc_tag;
    }

    return pdus;
}

// Function to free the allocated memory
void free_nfaapi_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus != NULL) {
        free(pdus);
    }
}

// Example usage of the function
int main() {
    uint32_t seed = 123456789; // Example seed value
    size_t count = 10000;      // Number of elements to create

    NFAPI_CRC_INDICATION_PDU_T *pdus = create_nfaapi_crc_indication_pdus(count, seed);
    if (pdus == NULL) {
        return EXIT_FAILURE;
    }

    // Use the array as needed...

    free_nfaapi_crc_indication_pdus(pdus);

    return EXIT_SUCCESS;
}
