#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define MAX_CONTEXTS 1024

typedef struct {
    int ue_id;
    unsigned long rnti;
    char *rrc_message; // Placeholder for NR_RrcConnectionReconfigurationComplete
} NR_UeContextInfo;

typedef struct {
    NR_UeContextInfo *contexts;
    size_t size;
    size_t initialized_count;
    pthread_mutex_t mutex;
    int max_concurrent_ops;
    sem_t operation_sem;
} ContextManager;

void log_message(const char *message) {
    // Dummy logging function. Integrate with NMS.
    printf("%s\n", message);
}

int allocate_context(ContextManager *manager, NR_UeContextInfo *context) {
    if (sem_trywait(&manager->operation_sem) < 0) {
        log_message("Resource limit reached for concurrent operations.");
        return -1;
    }

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (!manager->contexts[i].ue_id) { // Assume ue_id == 0 means unallocated
            context->ue_id = rand(); // Simple example. Ensure unique IDs.
            context->rnti = rand();
            context->rrc_message = malloc(128); // Example size allocation
            if (context->rrc_message == NULL) {
                pthread_mutex_unlock(&manager->mutex);
                sem_post(&manager->operation_sem);
                log_message("Memory allocation failed for RRC message.");
                return -1;
            }
            strcpy(context->rrc_message, "RRC Connection Reconfiguration Complete");
            manager->contexts[i] = *context;
            manager->initialized_count++;
            pthread_mutex_unlock(&manager->mutex);
            sem_post(&manager->operation_sem);
            log_message("Context initialized successfully.");
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    sem_post(&manager->operation_sem);
    log_message("No available context slots.");
    return -1;
}

int deallocate_context(ContextManager *manager, int ue_id) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            free(manager->contexts[i].rrc_message);
            memset(&manager->contexts[i], 0, sizeof(NR_UeContextInfo));
            manager->initialized_count--;
            pthread_mutex_unlock(&manager->mutex);
            log_message("Context deallocated successfully.");
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    log_message("Context not found for deallocation.");
    return -1;
}

void initialize_context_manager(ContextManager *manager, size_t max_size, int max_ops) {
    if (max_size > MAX_CONTEXTS) max_size = MAX_CONTEXTS;

    manager->contexts = calloc(max_size, sizeof(NR_UeContextInfo));
    if (!manager->contexts) {
        log_message("Failed to allocate memory for contexts.");
        return;
    }

    manager->size = max_size;
    manager->initialized_count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    sem_init(&manager->operation_sem, 0, max_ops);

    log_message("ContextManager initialized successfully.");
}

void report_status(ContextManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    printf("Initialized contexts: %zu\n", manager->initialized_count);
    printf("Available resources: %zu - %d concurrent ops allowed\n",
           (manager->size - manager->initialized_count), sem_getvalue(&manager->operation_sem, NULL));
    pthread_mutex_unlock(&manager->mutex);
}

void cleanup_context_manager(ContextManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].rrc_message) {
            free(manager->contexts[i].rrc_message);
        }
    }
    free(manager->contexts);
    pthread_mutex_destroy(&manager->mutex);
    sem_destroy(&manager->operation_sem);
}

int main() {
    ContextManager manager;
    initialize_context_manager(&manager, 100, 10);

    NR_UeContextInfo new_context;
    allocate_context(&manager, &new_context);

    report_status(&manager);

    deallocate_context(&manager, new_context.ue_id);
    report_status(&manager);

    cleanup_context_manager(&manager);

    return 0;
}
