```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PEERS 1000

typedef struct {
    char ip_address[16]; // Assuming IPv4 addresses
    uint32_t sequence_number;
    size_t payload_size;
    unsigned char *payload_buffer;
} GTPU_MESSAGE_T;

typedef struct GTPU_MessageNode {
    uint32_t teid; // Tunnel Endpoint Identifier
    GTPU_MESSAGE_T *messages;
    size_t message_count;
    struct GTPU_MessageNode *next;
} GTPU_MessageNode;

typedef struct {
    GTPU_MessageNode *head;
    pthread_mutex_t lock;
} GTPU_List;

// Function to initialize the list
GTPU_List* gtpu_list_init() {
    GTPU_List *list = (GTPU_List *)malloc(sizeof(GTPU_List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to create a new message node
static GTPU_MessageNode* create_message_node(uint32_t teid) {
    GTPU_MessageNode *node = (GTPU_MessageNode *)malloc(sizeof(GTPU_MessageNode));
    if (!node) return NULL;

    node->teid = teid;
    node->messages = NULL;
    node->message_count = 0;
    node->next = NULL;
    return node;
}

// Function to add a new message
void gtpu_add_message(GTPU_List *list, uint32_t teid, const char *ip_address, 
                      uint32_t sequence_number, const unsigned char *payload, size_t payload_size) {
    pthread_mutex_lock(&list->lock);

    GTPU_MessageNode *current = list->head;
    GTPU_MessageNode *prev = NULL;

    // Check for existing node with the same TEID
    while (current != NULL && current->teid != teid) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Create a new node if not found
        current = create_message_node(teid);
        if (prev == NULL) {
            list->head = current; // New head of the list
        } else {
            prev->next = current; // Insert after previous node
        }
    }

    // Allocate memory for a new message
    GTPU_MESSAGE_T *new_message = (GTPU_MESSAGE_T *)malloc(sizeof(GTPU_MESSAGE_T));
    if (!new_message) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    strncpy(new_message->ip_address, ip_address, sizeof(new_message->ip_address) - 1);
    new_message->sequence_number = sequence_number;
    new_message->payload_size = payload_size;

    // Dynamically resize the payload buffer
    new_message->payload_buffer = (unsigned char *)malloc(payload_size);
    if (!new_message->payload_buffer) {
        free(new_message);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memcpy(new_message->payload_buffer, payload, payload_size);

    // Add to the list of messages for this TEID
    new_message->next = current->messages;
    current->messages = new_message;
    current->message_count++;

    pthread_mutex_unlock(&list->lock);
}

// Function to remove a message by sequence number and TEID
void gtpu_remove_message(GTPU_List *list, uint32_t teid, uint32_t sequence_number) {
    pthread_mutex_lock(&list->lock);

    GTPU_MessageNode *current = list->head;
    GTPU_MessageNode *prev = NULL;

    while (current != NULL && current->teid != teid) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    GTPU_MESSAGE_T **ptr = &current->messages;
    while (*ptr != NULL) {
        GTPU_MESSAGE_T *entry = *ptr;
        if (entry->sequence_number == sequence_number) {
            *ptr = entry->next;
            free(entry->payload_buffer);
            free(entry);
            current->message_count--;
            break;
        }
        ptr = &entry->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to merge duplicate messages
void gtpu_merge_duplicates(GTPU_List *list) {
    pthread_mutex_lock(&list->lock);

    GTPU_MessageNode *current = list->head;

    while (current != NULL) {
        GTPU_MESSAGE_T **ptr1 = &current->messages;
        while (*ptr1 != NULL) {
            GTPU_MESSAGE_T *msg1 = *ptr1;
            GTPU_MESSAGE_T **ptr2 = &msg1->next;
            while (*ptr2 != NULL) {
                GTPU_MESSAGE_T *msg2 = *ptr2;

                if (strcmp(msg1->ip_address, msg2->ip_address) == 0 &&
                    msg1->sequence_number == msg2->sequence_number) {

                    // Merge payloads
                    unsigned char *new_payload = realloc(msg1->payload_buffer, 
                                                         msg1->payload_size + msg2->payload_size);
                    if (new_payload) {
                        memcpy(new_payload + msg1->payload_size, msg2->payload_buffer, msg2->payload_size);
                        msg1->payload_size += msg2->payload_size;
                        msg1->payload_buffer = new_payload;

                        // Remove the duplicate message
                        *ptr2 = msg2->next;
                        free(msg2->payload_buffer);
                        free(msg2);

                        current->message_count--;
                    }
                }
                ptr2 = &msg2->next;
            }
            ptr1 = &msg1->next;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to update message payload
void gtpu_update_payload(GTPU_List *list, uint32_t teid, uint32_t sequence_number,
                         const unsigned char *new_payload, size_t new_size) {
    pthread_mutex_lock(&list->lock);

    GTPU_MessageNode *current = list->head;
    while (current != NULL && current->teid != teid) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    GTPU_MESSAGE_T *message = current->messages;
    while (message != NULL) {
        if (message->sequence_number == sequence_number) {
            unsigned char *new_buffer = realloc(message->payload_buffer, new_size);
            if (new_buffer) {
                memcpy(new_buffer, new_payload, new_size);
                message->payload_size = new_size;
                message->payload_buffer = new_buffer;
            }
            break;
        }
        message = message->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to free the list
void gtpu_list_free(GTPU_List *list) {
    pthread_mutex_lock(&list->lock);

    GTPU_MessageNode *current = list->head;
    while (current != NULL) {
        GTPU_MESSAGE_T *message = current->messages;
        while (message != NULL) {
            GTPU_MESSAGE_T *temp = message;
            message = message->next;
            free(temp->payload_buffer);
            free(temp);
        }
        GTPU_MessageNode *temp_node = current;
        current = current->next;
        free(temp_node);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

This code provides a scalable and thread-safe implementation for managing GTP_U-plane messages. It includes functions to initialize the list, add, remove, merge duplicates, update payloads, and free resources. The use of mutexes ensures thread safety during concurrent access.']

