} ConnectionState;

// TCP_CONNECTION structure
typedef struct {
    int session_id;
    char *incoming_buffer;
    size_t incoming_buffer_size;
    char *outgoing_buffer;
    size_t outgoing_buffer_size;
    ConnectionState state;
