// Create a new TCP connection with dynamic buffers
TCP_CONNECTION* create_connection(int session_id, size_t buffer_size) {
    TCP_CONNECTION *conn = (TCP_CONNECTION *)malloc(sizeof(TCP_CONNECTION));
    if (!conn) return NULL;

    conn->session_id = session_id;
    conn->incoming_buffer = (char *)calloc(buffer_size, sizeof(char));
    conn->outgoing_buffer = (char *)calloc(buffer_size, sizeof(char));
    conn->incoming_buffer_size = buffer_size;
    conn->outgoing_buffer_size = buffer_size;
    conn->state = CONNECTED;

    if (pthread_mutex_init(&conn->lock, NULL) != 0) {
        free(conn->incoming_buffer);
        free(conn->outgoing_buffer);
        free(conn);
        return NULL;
    }

    // Integration with external monitoring system can be added here
    printf("Connection %d created with buffer size %zu.\n", session_id, buffer_size);

    return conn;
}

// Destroy a TCP connection and free resources
void destroy_connection(TCP_CONNECTION *connection) {
    if (!connection) return;

    pthread_mutex_lock(&connection->lock);
    free(connection->incoming_buffer);
    free(connection->outgoing_buffer);
    pthread_mutex_unlock(&connection->lock);
    pthread_mutex_destroy(&connection->lock);

    printf("Connection %d destroyed.\n", connection->session_id);
    free(connection);
}

// Set the state of a TCP connection in a thread-safe manner
void set_state(TCP_CONNECTION *connection, ConnectionState new_state) {
    if (!connection) return;

    pthread_mutex_lock(&connection->lock);
    connection->state = new_state;
    pthread_mutex_unlock(&connection->lock);

    // Update external monitoring system with the new state
}

// Get the current state of a TCP connection in a thread-safe manner
ConnectionState get_state(TCP_CONNECTION *connection) {
    ConnectionState state;

    if (!connection) return DISCONNECTED;

    pthread_mutex_lock(&connection->lock);
    state = connection->state;
    pthread_mutex_unlock(&connection->lock);

    return state;
}

// Example usage
int main() {
    size_t buffer_size = 1024; // Adjust based on bandwidth and hardware considerations
    TCP_CONNECTION *conn1 = create_connection(1, buffer_size);
    if (conn1) {
        set_state(conn1, CLOSING);
        destroy_connection(conn1);
    }

    return 0;
}
