#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

LinkedList* init_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        log_error("Failed to allocate memory for linked list.");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_unique_RNTI(LinkedList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (!is_unique_RNTI(list, data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // RNTI already exists
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for a new node.");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void initialize_list_with_random_data(LinkedList* list, int num_elements) {
    srand((unsigned int)time(NULL));
    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand();
        do {
            data.RNTI = rand() % 10000 + 1; // Ensure non-zero RNTI
        } while (!is_unique_RNTI(list, data.RNTI));

        data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
        int result = add_to_list(list, data);
        if (result != 0) {
            log_error("Failed to add element to the list.");
        }
    }
}

// Unit tests
void test_empty_list_creation() {
    LinkedList* list = init_linked_list();
    assert(list != NULL && "List creation failed");
    free_linked_list(list);
}

void test_duplicate_RNTI_handling() {
    LinkedList* list = init_linked_list();
    NFAPI_CRC_INDICATION_PDU_T data1 = {1, 1234, {.CRCFLAG=0}};
    add_to_list(list, data1);

    // Try to add the same RNTI
    int result = add_to_list(list, data1);
    assert(result == -1 && "Duplicate RNTI was not handled correctly");

    free_linked_list(list);
}

void test_large_concurrent_creation(int num_threads, int elements_per_thread) {
    LinkedList* list = init_linked_list();

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))initialize_list_with_random_data, list)) {
            log_error("Failed to create thread");
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_linked_list(list);
}

int main() {
    test_empty_list_creation();
    test_duplicate_RNTI_handling();

    // Test with high concurrency
    test_large_concurrent_creation(10, 100);

    printf("All tests passed.\n");
    return 0;
}
