void *establishConnection(void *arg) {
    // Simulating asynchronous network operation using threads
    int retries = 5;
    while (retries--) {
        printf("Attempting to connect...\n");

        // Simulate connection attempt with random success/failure
        if ((rand() % 3) == 0) { // Randomly decide success or failure
            printf("Connected successfully.\n");
            return NULL; // Exit thread on success
        } else {
            sleep(1); // Backoff strategy: wait before retrying
            printf("Connection attempt failed. Retrying...\n");
        }
    }

    fprintf(stderr, "Failed to establish connection after retries.\n");
    pthread_exit((void *)-1);
}

