    PHY_TASK_SCHED_T *tasks = malloc(N * sizeof(PHY_TASK_SCHED_T));
    if (!tasks) {
        logMessage("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_t taskMutex;
    pthread_mutex_init(&taskMutex, NULL);

