        tasks[i].SCHED_REQUEST_TAG = i; // Example tag assignment

        generateRachConfig(&tasks[i]);

        pthread_mutex_unlock(&taskMutex);
    }

    pthread_mutex_destroy(&taskMutex);

    logMessage("Task list created successfully");
    return tasks;
}

// Helper function to check if a CELL_ID is unique
int isUniqueCellID(int cell_id, int *cell_ids, int count) {
    for (int i = 0; i < count; ++i) {
        if (cell_ids[i] == cell_id)
            return 0;
    }
    return 1;
}

