#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_NODES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    size_t node_count;
} DoublyLinkedList;

// Memory pool for nodes
typedef struct {
    Node* free_list[MAX_NODES];
    pthread_mutex_t pool_lock;
} NodePool;

NodePool* create_node_pool() {
    NodePool* pool = malloc(sizeof(NodePool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->pool_lock, NULL);
    for (size_t i = 0; i < MAX_NODES; ++i) {
        pool->free_list[i] = NULL;
    }

    // Preallocate nodes
    for (size_t i = 0; i < MAX_NODES; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) return NULL;

        pthread_mutex_lock(&pool->pool_lock);
        pool->free_list[i] = node;
        pthread_mutex_unlock(&pool->pool_lock);
    }

    return pool;
}

Node* allocate_node(NodePool* pool) {
    pthread_mutex_lock(&pool->pool_lock);

    for (size_t i = 0; i < MAX_NODES; ++i) {
        if (pool->free_list[i]) {
            Node* node = pool->free_list[i];
            pool->free_list[i] = NULL;
            pthread_mutex_unlock(&pool->pool_lock);
            return node;
        }
    }

    pthread_mutex_unlock(&pool->pool_lock);
    return malloc(sizeof(Node));  // Fallback allocation
}

void free_node(NodePool* pool, Node* node) {
    pthread_mutex_lock(&pool->pool_lock);

    for (size_t i = 0; i < MAX_NODES; ++i) {
        if (!pool->free_list[i]) {
            pool->free_list[i] = node;
            break;
        }
    }

    pthread_mutex_unlock(&pool->pool_lock);
}

DoublyLinkedList* create_doubly_linked_list(NodePool* pool) {
    DoublyLinkedList* list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->node_count = 0;

    return list;
}

int is_unique(DoublyLinkedList* list, unsigned long RNTI, int RX_UE_INFORMATION_TAG) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == RNTI || current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG)
            return 0;
        current = current->next;
    }
    return 1;
}

void append_to_list(DoublyLinkedList* list, NodePool* pool) {
    NFAPI_CRC_INDICATION_PDU_T data;

    // Random generation of values
    srand(time(NULL));
    do {
        data.RX_UE_INFORMATION_TAG = rand() % 10000;
        data.RNTI = rand();
        data.CRCFLAG = rand() % 2;  // Random CRCFLAG: 0 or 1
    } while (!is_unique(list, data.RNTI, data.RX_UE_INFORMATION_TAG));

    Node* new_node = allocate_node(pool);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate node\n");
        return;
    }

    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = list->tail;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->node_count++;

    printf("Appended: RX_UE_INFORMATION_TAG=%d, RNTI=%lu\n", data.RX_UE_INFORMATION_TAG, data.RNTI);

    pthread_mutex_unlock(&list->lock);
}

void destroy_doubly_linked_list(DoublyLinkedList* list, NodePool* pool) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_node(pool, current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
    free(list);
}

void producer(DoublyLinkedList* list, NodePool* pool) {
    for (int i = 0; i < 10; ++i) { // Example: each thread appends 10 nodes
        append_to_list(list, pool);
        pthread_cond_signal(&list->cond_var); // Notify consumers
    }
}

void consumer(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    while (list->node_count == 0) {
        pthread_cond_wait(&list->cond_var, &list->lock);
    }

    Node* current = list->head;
    printf("Consumed: RX_UE_INFORMATION_TAG=%d, RNTI=%lu\n", current->data.RX_UE_INFORMATION_TAG, current->data.RNTI);

    if (current) {
        list->head = current->next;
        if (!list->head) list->tail = NULL;
        free_node(pool, current);
        list->node_count--;
    }

    pthread_mutex_unlock(&list->lock);
}

void* thread_func(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    NodePool* pool = create_node_pool();  // Each thread gets its own pool

    producer(list, pool);

    return NULL;
}

int main() {
    DoublyLinkedList* list = create_doubly_linked_list(NULL);
    const int num_threads = 4;

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_func, (void*)list)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_doubly_linked_list(list, NULL);

    return 0;
}
```

