#define MAX_LOG_LEVEL 5
#define LOG_FILE "event_manager.log"
#define ARCHIVE_THRESHOLD_DAYS 30

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct Event {
    time_t timestamp;
    EventType type;
    size_t data_length;
    char *data;
    struct Event *next;
} Event;

typedef struct {
    Event *head;
    pthread_mutex_t lock;
} EventList;

typedef struct {
    int mode; // 0 for append, 1 for truncate
    FILE *file;
    pthread_mutex_t log_lock;
} LogManager;

LogManager log_manager = { .mode = 0, .file = fopen(LOG_FILE, "a+"), .log_lock = PTHREAD_MUTEX_INITIALIZER };

void initialize_log_manager(int mode) {
    if (mode == 1) {
        // Truncate the log file
        freopen("/dev/null", "w", log_manager.file);
    }
}

void log_message(const char *message, int level) {
    pthread_mutex_lock(&log_manager.log_lock);

    if (level <= MAX_LOG_LEVEL) {
        fprintf(log_manager.file, "[%ld] %s\n", time(NULL), message);
        fflush(log_manager.file);
    }

    pthread_mutex_unlock(&log_manager.log_lock);
}

void cleanup_old_events(EventList *list) {
    time_t now = time(NULL);
    Event **current = &(list->head);

    while (*current) {
        if (difftime(now, (*current)->timestamp) > ARCHIVE_THRESHOLD_DAYS * 24 * 60 * 60) {
            // Archive logic here
            Event *old_event = *current;
            *current = old_event->next;

            free(old_event->data);
            free(old_event);

            log_message("Event archived", 3);
        } else {
            current = &((*current)->next);
        }
    }
}

void append_event(EventList *list, time_t timestamp, EventType type, const char *data) {
    pthread_mutex_lock(&list->lock);

    Event *new_event = malloc(sizeof(Event));
    new_event->timestamp = timestamp;
    new_event->type = type;
    new_event->data_length = strlen(data);
    new_event->data = strdup(data);
    new_event->next = list->head;
    list->head = new_event;

    log_message("Event appended", 2);

    pthread_mutex_unlock(&list->lock);
}

void update_event(EventList *list, time_t timestamp, EventType type, const char *new_data) {
    pthread_mutex_lock(&list->lock);

    Event **current = &(list->head);

    while (*current) {
        if ((*current)->timestamp == timestamp && (*current)->type == type) {
            free((*current)->data);
            (*current)->data = strdup(new_data);
            log_message("Event updated", 2);
            break;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&list->lock);
}

void retrieve_events(EventList *list, EventType type, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&list->lock);

    for (Event *iter = list->head; iter != NULL; iter = iter->next) {
        if (iter->type == type && iter->timestamp >= start_time && iter->timestamp <= end_time) {
            printf("Event: %s\n", iter->data);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    EventList event_list = { .head = NULL };
    pthread_mutex_init(&event_list.lock, NULL);

    initialize_log_manager(0);

    append_event(&event_list, time(NULL), EVENT_TYPE_A, "Test data");
    retrieve_events(&event_list, EVENT_TYPE_A, 0, time(NULL) + 86400);
    update_event(&event_list, time(NULL), EVENT_TYPE_A, "Updated test data");

    cleanup_old_events(&event_list);

    // Free resources
    fclose(log_manager.file);
    pthread_mutex_destroy(&log_manager.log_lock);
    pthread_mutex_destroy(&event_list.lock);

    return 0;
}
