    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    pthread_mutex_t lock;
} NFACache;

void initCache(NFACache *cache) {
    cache->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cache->elements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void freeCache(NFACache *cache) {
    free(cache->elements);
    pthread_mutex_destroy(&cache->lock);
}

int addElement(NFACache *cache, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&cache->lock);

    if (cache->count >= MAX_ELEMENTS) {
        printf("Cache limit reached. Cannot add more elements.\n");
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *newElement = &cache->elements[cache->count++];
    newElement->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement->RNTI = RNTI;
    newElement->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

int removeElement(NFACache *cache, int index) {
    pthread_mutex_lock(&cache->lock);

    if (index < 0 || index >= cache->count) {
        printf("Invalid index. Cannot remove element.\n");
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    memmove(&cache->elements[index], &cache->elements[index + 1],
            (--cache->count - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

void logCacheStatus(const NFACache *cache) {
    printf("Current cache size: %zu\n", cache->count);
}

// Simulate external data source update
void updateFromExternalSource(NFACache *cache, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&cache->lock);

    // Example logic for handling updates (details depend on actual use case)
    if (cache->count < MAX_ELEMENTS) {
        addElement(cache, RX_UE_INFORMATION_TAG, RNTI);
    } else {
        printf("Cache is full. Consider removing an element before adding.\n");
    }

    pthread_mutex_unlock(&cache->lock);
}

// Example usage
int main() {
    NFACache cache;
    initCache(&cache);

    updateFromExternalSource(&cache, 1234, 5678);
    logCacheStatus(&cache);

    removeElement(&cache, 0);
    logCacheStatus(&cache);

    freeCache(&cache);
    return 0;
}
