#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFAPICRCList;

NFAPICRCList* nfapi_crc_list_create() {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void nfapi_crc_list_destroy(NFAPICRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int nfapi_crc_list_add(NFAPICRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    // Check for existing RNTI
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.crcIndicationRel8Tag.RNTI == element.crcIndicationRel8Tag.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -1; // RNTI already exists
        }
        current = current->next;
    }

    // Add new element
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }
    newNode->data = element;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int nfapi_crc_list_update(NFAPICRCList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T updatedElement) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.crcIndicationRel8Tag.RNTI == RNTI) {
            current->data = updatedElement;
            pthread_mutex_unlock(&list->lock);
            return 0; // Updated successfully
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // RNTI not found
}

int nfapi_crc_list_remove(NFAPICRCList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (current->data.crcIndicationRel8Tag.RNTI == RNTI) {
            if (prev == NULL)
                list->head = current->next; // Remove head
            else
                prev->next = current->next;

            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Removed successfully
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // RNTI not found
}

size_t nfapi_crc_list_serialize(NFAPICRCList* list, uint8_t** buffer) {
    pthread_mutex_lock(&list->lock);

    size_t bufferSize = 0;
    Node* current = list->head;

    while (current != NULL) {
        bufferSize += sizeof(current->data.crcIndicationRel8Tag.RX_UE_INFORMATION_TAG);
        bufferSize += sizeof(current->data.crcIndicationRel8Tag.RNTI);
        bufferSize += sizeof(current->data.CRCFLAG);
        current = current->next;
    }

    *buffer = (uint8_t*)malloc(bufferSize);
    if (!*buffer) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Memory allocation failure

    }

    uint8_t* ptr = *buffer;
    current = list->head;

    while (current != NULL) {
        memcpy(ptr, &current->data.crcIndicationRel8Tag.RX_UE_INFORMATION_TAG, sizeof(current->data.crcIndicationRel8Tag.RX_UE_INFORMATION_TAG));
        ptr += sizeof(current->data.crcIndicationRel8Tag.RX_UE_INFORMATION_TAG);

        memcpy(ptr, &current->data.crcIndicationRel8Tag.RNTI, sizeof(current->data.crcIndicationRel8Tag.RNTI));
        ptr += sizeof(current->data.crcIndicationRel8Tag.RNTI);

        memcpy(ptr, &current->data.CRCFLAG, sizeof(current->data.CRCFLAG));
        ptr += sizeof(current->data.CRCFLAG);

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return bufferSize; // Return the size of the serialized data
}

int nfapi_crc_list_deserialize(NFAPICRCList* list, const uint8_t* buffer, size_t bufferSize) {
    if (!buffer || bufferSize == 0) return -1;

    pthread_mutex_lock(&list->lock);

    size_t offset = 0;
    while (offset < bufferSize) {
        NFAPI_CRC_INDICATION_PDU_T element;

        memcpy(&element.crcIndicationRel8Tag.RX_UE_INFORMATION_TAG, buffer + offset, sizeof(element.crcIndicationRel8Tag.RX_UE_INFORMATION_TAG));
        offset += sizeof(element.crcIndicationRel8Tag.RX_UE_INFORMATION_TAG);

        memcpy(&element.crcIndicationRel8Tag.RNTI, buffer + offset, sizeof(element.crcIndicationRel8Tag.RNTI));
        offset += sizeof(element.crcIndicationRel8Tag.RNTI);

        memcpy(&element.CRCFLAG, buffer + offset, sizeof(element.CRCFLAG));
        offset += sizeof(element.CRCFLAG);

        nfapi_crc_list_add(list, element);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}
