    double timestamp;
    double signal_strength;
} NFAPI_RRC_MEASUREMENT_REPORT_T;

typedef struct Node {
    NFAPI_RRC_MEASUREMENT_REPORT_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MeasurementReportList;

MeasurementReportList* create_list() {
    MeasurementReportList* list = malloc(sizeof(MeasurementReportList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(MeasurementReportList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_report(MeasurementReportList* list, NFAPI_RRC_MEASUREMENT_REPORT_T report) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.tag.UE_IDENTIFIER == report.tag.UE_IDENTIFIER) {
            pthread_mutex_unlock(&list->lock);
            return 0; // UE_IDENTIFIER already exists
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->data = report;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully added
}

int update_report(MeasurementReportList* list, int ue_id, NFAPI_RRC_MEASUREMENT_REPORT_T report) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.tag.UE_IDENTIFIER == ue_id) {
            current->data = report;
            pthread_mutex_unlock(&list->lock);
            return 1; // Successfully updated
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // UE_IDENTIFIER not found
}

int remove_report(MeasurementReportList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.tag.UE_IDENTIFIER == ue_id) {
            if (prev) prev->next = current->next;
            else list->head = current->next;
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 1; // Successfully removed
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // UE_IDENTIFIER not found
}

size_t serialize_list(MeasurementReportList* list, unsigned char** buffer) {
    size_t total_size = 0;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        total_size += sizeof(NFAPI_RRC_MEASUREMENT_REPORT_T);
        current = current->next;
    }

    *buffer = malloc(total_size);
    if (!(*buffer)) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Memory allocation failed
    }

    size_t offset = 0;
    current = list->head;
    while (current) {
        memcpy((*buffer) + offset, &current->data, sizeof(NFAPI_RRC_MEASUREMENT_REPORT_T));
        offset += sizeof(NFAPI_RRC_MEASUREMENT_REPORT_T);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return total_size; // Size of serialized data
}

void deserialize_list(MeasurementReportList* list, const unsigned char* buffer, size_t size) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    for (size_t offset = 0; offset < size; offset += sizeof(NFAPI_RRC_MEASUREMENT_REPORT_T)) {
        NFAPI_RRC_MEASUREMENT_REPORT_T report;
        memcpy(&report, buffer + offset, sizeof(NFAPI_RRC_MEASUREMENT_REPORT_T));
        add_report(list, report);
    }

    pthread_mutex_unlock(&list->lock);
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}
