LTE_PHY_RX_FRAME* initialize_receiving_frames(int numFrames) {
    if (numFrames <= 0) {
        fprintf(stderr, "Invalid number of frames.\n");
        return NULL;
    }

    // Allocate memory for the array of LTE_PHY_RX_FRAME
    LTE_PHY_RX_FRAME *frames = (LTE_PHY_RX_FRAME *)malloc(numFrames * sizeof(LTE_PHY_RX_FRAME));
    if (!frames) {
        perror("Memory allocation failed for receiving frames");
        return NULL;
    }

    // Iterate over each frame and allocate memory for PHY_RX_FRAME_STATS
    for (int i = 0; i < numFrames; ++i) {
        frames[i].stats = (PHY_RX_FRAME_STATS *)malloc(sizeof(PHY_RX_FRAME_STATS));
        if (!frames[i].stats) {
            perror("Memory allocation failed for PHY_RX_FRAME_STATS");

            // Free any allocated memory before returning to avoid leaks
            while (--i >= 0) {
                free(frames[i].stats);
            }
            free(frames);
            return NULL;
        }

        // Initialize the fields as required (example initialization)
        frames[i].tti.frameId = i; // Example TTI initialization
        frames[i].stats->sampleData = 0; // Example PHY_RX_FRAME_STATS initialization
    }

    return frames;
}

void cleanup_receiving_frames(LTE_PHY_RX_FRAME *frames, int numFrames) {
    if (frames) {
        for (int i = 0; i < numFrames; ++i) {
            free(frames[i].stats);
        }
        free(frames);
    }
}
