['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    union {
        struct {
            uint8_t CRCFLAG; // Assuming 1 byte for CRCFLAG
        } REL8_TAG;
    };
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Entry* next;
} Entry;

typedef struct {
    Entry* head;
    size_t count;
    size_t capacity; // For tracking max allocated size
    uint16_t rnti_access_count[65536]; // Simplified cache, assuming 16-bit RNTI space
    uint16_t* frequent_rntis; // Dynamic array for frequent access optimization
    size_t freq_capacity; // Size of frequent_rntis array
} NIC_CRC_Manager;

// Function to create a new manager instance
NIC_CRC_Manager* create_crc_manager() {
    NIC_CRC_Manager* manager = (NIC_CRC_Manager*)malloc(sizeof(NIC_CRC_Manager));
    if (!manager) return NULL;
    manager->head = NULL;
    manager->count = 0;
    manager->capacity = 0;
    memset(manager->rnti_access_count, 0, sizeof(manager->rnti_access_count));
    manager->frequent_rntis = NULL;
    manager->freq_capacity = 0;
    return manager;
}

// Function to add a new entry
int add_crc_entry(NIC_CRC_Manager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!manager || !pdu) return -1;

    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) return -2;

    memcpy(&new_entry->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_entry->next = manager->head;
    manager->head = new_entry;
    manager->count++;

    // Update RNTI access count
    manager->rnti_access_count[pdu->RNTI]++;

    // Check if this RNTI needs to be added to the frequent list
    int is_frequent = 0;
    for (size_t i = 0; i < manager->freq_capacity; ++i) {
        if (manager->frequent_rntis[i] == pdu->RNTI) {
            is_frequent = 1;
            break;
        }
    }

    if (!is_frequent) {
        size_t new_freq_capacity = manager->freq_capacity + 1;
        uint16_t* new_frequent_rntis = (uint16_t*)realloc(manager->frequent_rntis, sizeof(uint16_t) * new_freq_capacity);
        if (!new_frequent_rntis) return -3;

        manager->frequent_rntis = new_frequent_rntis;
        manager->frequent_rntis[manager->freq_capacity] = pdu->RNTI;
        manager->freq_capacity = new_freq_capacity;
    }

    // Adjust cache and list for optimization if necessary
    // ...

    return 0; // Success
}

// Function to remove an entry based on RNTI
int remove_crc_entry(NIC_CRC_Manager* manager, uint16_t rnti) {
    if (!manager || !manager->head) return -1;

    Entry *current = manager->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev)
                prev->next = current->next;
            else
                manager->head = current->next;

            free(current);
            manager->count--;

            // Update RNTI access count and cache
            manager->rnti_access_count[rnti]--;
            for (size_t i = 0; i < manager->freq_capacity; ++i) {
                if (manager->frequent_rntis[i] == rnti) {
                    memmove(&manager->frequent_rntis[i], &manager->frequent_rntis[i + 1],
                            sizeof(uint16_t) * (manager->freq_capacity - i - 1));
                    manager->freq_capacity--;
                    break;
                }
            }

            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    return -2; // Entry not found
}

// Function to get the total number of entries
size_t get_total_entries(NIC_CRC_Manager* manager) {
    if (!manager) return (size_t)-1;
    return manager->count;
}

// Function to free all resources used by the manager
void destroy_crc_manager(NIC_CRC_Manager* manager) {
