    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[CRCFLAG_MASK];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    int size;
    threading.Lock lock; // For thread safety
} LinkedList;

// Helper function to generate pseudo-random value for CRCFLAG based on seed
uint8_t generate_crcflag(uint32_t seed) {
    return (seed * 1103515245 + 12345) & CRCFLAG_MASK;
}

// Initialize the linked list
LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    threading.Lock_init(&list->lock);
    return list;
}

// Insert a node into the linked list
int insert_node(LinkedList* list, uint16_t rx_tag, uint16_t rnti, uint32_t seed) {
    if (list->size >= MAX_NODES) {
        fprintf(stderr, "Warning: Maximum capacity reached.\n");
        return -1; // Insufficient capacity
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -2; // Allocation failure
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_tag;
    pdu.RNTI = rnti;
    for (int i = 0; i < CRCFLAG_MASK; ++i) {
        pdu.CRC_INDICATION_REL8_TAG[i] = generate_crcflag(seed + i);
    }

    threading.Lock_acquire(&list->lock);
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    threading.Lock_release(&list->lock);

    return 0; // Success
}

// Delete a node from the linked list by index
int delete_node(LinkedList* list, int index) {
    if (index < 0 || index >= list->size) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        return -1;
    }

    threading.Lock_acquire(&list->lock);
    Node **curr = &list->head;
    for (int i = 0; i < index; ++i) {
        curr = &(*curr)->next;
    }

    Node* to_delete = *curr;
    *curr = to_delete->next;
    free(to_delete);
    list->size--;
    threading.Lock_release(&list->lock);

    return 0; // Success
}

// Retrieve a node's data by index
int get_node_data(LinkedList* list, int index, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (index < 0 || index >= list->size) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        return -1;
    }

    threading.Lock_acquire(&list->lock);
    Node* curr = list->head;
    for (int i = 0; i < index; ++i) {
        curr = curr->next;
    }

    *pdu = curr->data;
    threading.Lock_release(&list->lock);

    return 0; // Success
}

// Serialize the linked list to a binary format
size_t serialize_list(LinkedList* list, uint8_t** buffer) {
    size_t total_size = sizeof(uint32_t); // To store node count at the beginning
    Node* curr = list->head;

    while (curr != NULL) {
        total_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        curr = curr->next;
    }

    *buffer = (uint8_t*)malloc(total_size);
    if (!(*buffer)) return 0; // Allocation failure

    uint8_t* ptr = *buffer;

    // Store the number of nodes
    uint32_t node_count = list->size;
    memcpy(ptr, &node_count, sizeof(uint32_t));
    ptr += sizeof(uint32_t);

    curr = list->head;
    while (curr != NULL) {
        memcpy(ptr, &(curr->data), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        curr = curr->next;
    }

    return total_size;
}

// Deserialize a binary buffer into the linked list
int deserialize_list(LinkedList* list, uint8_t* buffer) {
    if (!buffer) return -1; // Invalid input

    uint32_t node_count;
    memcpy(&node_count, buffer, sizeof(uint32_t));

    if (list->size + node_count > MAX_NODES) {
        fprintf(stderr, "Error: Exceeds maximum capacity.\n");
        return -2; // Insufficient capacity
    }

    threading.Lock_acquire(&list->lock);
    uint8_t* ptr = buffer + sizeof(uint32_t);

    for (uint32_t i = 0; i < node_count; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Error: Memory allocation failed during deserialization.\n");
            threading.Lock_release(&list->lock);
            return -3;
        }

        memcpy(&(new_node->data), ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = list->head;
        list->head = new_node;
        list->size++;

        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    threading.Lock_release(&list->lock);

    return 0; // Success
}

// Free the linked list resources
void free_list(LinkedList* list) {
    if (!list) return;

    Node* curr = list->head;
    while (curr != NULL) {
        Node* temp = curr;
        curr = curr->next;
        free(temp);
    }

    threading.Lock_destroy(&list->lock);
    free(list);
}
