        num_structures = MAX_STRUCTURES;
    }

    NFAPI_CRC_INDICATION_PDU_T **dynamic_list = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!dynamic_list) {
        log_issue("Memory allocation failed for dynamic list.");
        return NULL;
    }

    uint16_t used_rntis[MAX_STRUCTURES] = {0};
    int count = 0;

    srand(time(NULL)); // Seed the random number generator

    while (count < num_structures) {
        NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_structure) {
            log_issue("Memory allocation failed for structure.");
            break;
        }

        do {
            new_structure->rx_ue_information_tag = rand() % 65536; // Random value
            new_structure->rnti = (rand() % MAX_STRUCTURES) + 1; // Ensure non-zero RNTI

            if (used_rntis[new_structure->rnti - 1] != 0) {
                free(new_structure);
                continue;
            }
        } while (!validate_structure(new_structure));

        used_rntis[new_structure->rnti - 1] = new_structure->rnti;

        new_structure->crc_indication_rel8_tag = rand() % 256; // Random byte
        new_structure->crcflag = rand() % 2; // Random boolean

        dynamic_list[count++] = new_structure;
    }

    *actual_count = count;
    return dynamic_list;
}

void free_nfa_pis(NFAPI_CRC_INDICATION_PDU_T **dynamic_list, int actual_count) {
    for (int i = 0; i < actual_count; ++i) {
        if (dynamic_list[i]) {
            free(dynamic_list[i]);
        }
    }
    free(dynamic_list);
}

