#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static unsigned int global_sequence_number = 0;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

bool generate_unique_random_ushort(unsigned short* value, unsigned short used_values[], size_t count) {
    bool found;
    do {
        *value = rand() % 65535 + 1; // RNTI values are between 1 and 65535
        found = false;
        for (size_t i = 0; i < count; ++i) {
            if (used_values[i] == *value) {
                found = true;
                break;
            }
        }
    } while (found);
    return !found;
}

void manage_ue_sessions(size_t N, NFAPI_CRC_INDICATION_PDU_T** sessions) {
    if (N == 0) {
        log_error("Number of elements must be a non-negative integer.");
        *sessions = NULL;
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    *sessions = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*sessions == NULL) {
        log_error("Memory allocation failed.");
        return;
    }

    unsigned short used_rntis[N];
    for (size_t i = 0; i < N; ++i) {
        used_rntis[i] = 0;
    }

    bool previous_crcflag = rand() % 2 == 0;
    for (size_t i = 0; i < N; ++i) {
        (*sessions)[i].RX_UE_INFORMATION_TAG = ++global_sequence_number;

        if (!generate_unique_random_ushort(&(*sessions)[i].RNTI, used_rntis, i)) {
            log_error("Unable to generate unique RNTI values.");
            free(*sessions);
            *sessions = NULL;
            return;
        }
        used_rntis[i] = (*sessions)[i].RNTI;

        (*sessions)[i].CRC_INDICATION_REL8_TAG = !previous_crcflag;
        previous_crcflag = (*sessions)[i].CRC_INDICATION_REL8_TAG;
    }

    printf("UE sessions initialized successfully.\n");
}

void free_ue_sessions(NFAPI_CRC_INDICATION_PDU_T* sessions) {
    if (sessions != NULL) {
        free(sessions);
        sessions = NULL;
    }
}
