#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int timestamp;
    char id[256];
    int status_flag; // Assume 0 or 1 for simplicity
} Message;

typedef struct {
    Message *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageArray;

// Initialize the message array
void initMessageArray(MessageArray *array) {
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->messages = (Message *)malloc(array->capacity * sizeof(Message));
    if (!array->messages) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->lock, NULL);
}

// Resize the message array
void resizeMessageArray(MessageArray *array) {
    size_t new_capacity = array->capacity * 2;
    Message *new_messages = (Message *)realloc(array->messages, new_capacity * sizeof(Message));
    if (!new_messages) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    array->messages = new_messages;
    array->capacity = new_capacity;
}

// Add a new message
void addMessage(MessageArray *array, int timestamp, const char *id, int status_flag) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resizeMessageArray(array);
    }

    Message new_message = {timestamp, "", status_flag};
    strncpy(new_message.id, id, sizeof(new_message.id) - 1);
    array->messages[array->count++] = new_message;

    pthread_mutex_unlock(&array->lock);
}

// Update an existing message by ID
void updateMessage(MessageArray *array, const char *id, int timestamp, int status_flag) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (strncmp(array->messages[i].id, id, sizeof(array->messages[i].id)) == 0) {
            array->messages[i].timestamp = timestamp;
            array->messages[i].status_flag = status_flag;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

// Retrieve messages by timestamp range
void retrieveMessages(MessageArray *array, int start_timestamp, int end_timestamp, Message **results, size_t *result_count) {
    pthread_mutex_lock(&array->lock);

    *result_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].timestamp >= start_timestamp && array->messages[i].timestamp <= end_timestamp) {
            (*results)[*result_count++] = &array->messages[i];
        }
    }

    pthread_mutex_unlock(&array->lock);
}

// Free the message array
void freeMessageArray(MessageArray *array) {
    pthread_mutex_lock(&array->lock);

    free(array->messages);

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}
