#include <pthread.h>

#define MAX_PACKETS 1000
#define MAX_PAYLOAD_SIZE 1500
#define MAX_BANDWIDTH 1000 // in Mbps

typedef struct {
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    int payload_length;
} PacketHeader;

// Global variables for thread safety
pthread_mutex_t lock;
int used_ips[MAX_PACKETS][2]; // 0: source, 1: destination
int ip_count = 0;

// Function prototypes
void initialize_packet_headers(PacketHeader *headers, size_t num_packets);
int generate_random_ip(char *ip_buffer);
int is_valid_ip(const char *ip_address);
void adjust_payload_size(int *payload_length);
void log_traffic_statistics(const PacketHeader *header);

// Initialize packet headers for network traffic simulation
void initialize_packet_headers(PacketHeader *headers, size_t num_packets) {
    pthread_mutex_init(&lock, NULL);

    if (num_packets > MAX_PACKETS) {
        fprintf(stderr, "Exceeded maximum number of packets\n");
        return;
    }

    for (size_t i = 0; i < num_packets; ++i) {
        pthread_mutex_lock(&lock);

        int source_ip_generated = 0, dest_ip_generated = 0;

        while (!source_ip_generated || !dest_ip_generated) {
            if (!source_ip_generated) {
                if (generate_random_ip(headers[i].source_ip)) {
                    source_ip_generated = 1;
                }
            }

            if (!dest_ip_generated) {
                if (generate_random_ip(headers[i].destination_ip)) {
                    dest_ip_generated = 1;
                }
            }

            // Check for unique IPs
            int unique = 1;
            for (int j = 0; j < ip_count && unique; ++j) {
                if ((strcmp(headers[i].source_ip, used_ips[j][0]) == 0 || strcmp(headers[i].destination_ip, used_ips[j][1]) == 0)) {
                    unique = 0;
                    source_ip_generated = dest_ip_generated = 0; // Reset both
                }
            }

            if (unique) {
                strcpy(used_ips[ip_count][0], headers[i].source_ip);
                strcpy(used_ips[ip_count][1], headers[i].destination_ip);
                ip_count++;
            }
        }

        headers[i].protocol_type = rand() % 256; // Assuming protocol type is a byte value

        adjust_payload_size(&headers[i].payload_length);

        log_traffic_statistics(&headers[i]);

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
}

// Generate a random valid IP address
int generate_random_ip(char *ip_buffer) {
    if (inet_ntop(AF_INET, &((struct in_addr){.s_addr = htonl(rand() % 0xFFFFFFFF)}), ip_buffer, sizeof(ip_buffer)) == NULL) {
        return 0;
    }
    return is_valid_ip(ip_buffer);
}

// Validate IP address format
int is_valid_ip(const char *ip_address) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip_address, &(sa.sin_addr)) != 0;
}

// Adjust payload size based on network conditions
void adjust_payload_size(int *payload_length) {
    double bandwidth_factor = (double)(rand() % MAX_BANDWIDTH + 1) / MAX_BANDWIDTH; // Simulated network condition
    *payload_length = (int)(MAX_PAYLOAD_SIZE * bandwidth_factor);
}

// Log traffic statistics for monitoring purposes
void log_traffic_statistics(const PacketHeader *header) {
    printf("Packet - Src: %s, Dest: %s, Protocol: %d, Payload Length: %d\n",
           header->source_ip, header->destination_ip, header->protocol_type, header->payload_length);
}

int main() {
    srand(time(NULL));
    PacketHeader headers[MAX_PACKETS];
    initialize_packet_headers(headers, 10); // Initialize 10 packet headers for demonstration

    return 0;
}
