#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_CAPACITY 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG; // Randomly set true or false
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t mutex;
} PduList;

PduList* create_pdu_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

bool is_rnti_unique(PduList* list, uint16_t rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdus[i].RNTI == rnti) return false;
    }
    return true;
}

int add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->count >= MAX_CAPACITY) return -1;

    pthread_mutex_lock(&list->mutex);

    if (!is_rnti_unique(list, pdu.RNTI)) {
        pthread_mutex_unlock(&list->mutex);
        fprintf(stderr, "Duplicate RNTI detected: %u\n", pdu.RNTI);
        return -2;
    }

    if (pthread_mutex_trylock(&list->mutex) != 0) {
        pthread_mutex_unlock(&list->mutex);
        fprintf(stderr, "Mutex lock failed.\n");
        return -3;
    }

    list->pdus[list->count] = pdu;
    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void serialize_pdu_list(PduList* list, const char* filename) {
    if (!list || !filename) return;

    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", filename);
        return;
    }

    pthread_mutex_lock(&list->mutex);

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);

    fclose(file);
    pthread_mutex_unlock(&list->mutex);
}

PduList* deserialize_pdu_list(const char* filename) {
    if (!filename) return NULL;

    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading: %s\n", filename);
        return NULL;
    }

    PduList* list = create_pdu_list();
    if (!list) goto error;

    pthread_mutex_lock(&list->mutex);

    fread(&list->count, sizeof(size_t), 1, file);
    if (fread(list->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file) != list->count) {
        free_pdu_list(list);
        goto error;
    }

    fclose(file);
    pthread_mutex_unlock(&list->mutex);

    return list;

error:
    fclose(file);
    if (list) free_pdu_list(list);
    return NULL;
}

void free_pdu_list(PduList* list) {
    if (!list) return;

    pthread_mutex_destroy(&list->mutex);
    free(list->pdus);
    free(list);
}
