    pthread_mutex_t mutex;
    unsigned long* rnti_set; // Hash set to track RNTI uniqueness
} NFAPIList;

// Forward declarations
void initialize_list(NFAPIList** list);
int add_element(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T element);
int serialize_list(const char* filename, const NFAPIList* list);
int deserialize_list(NFAPIList** list, const char* filename);
void free_list(NFAPIList* list);
int is_rnti_unique(NFAPIList* list, unsigned long rnti);

// Initialize the list
void initialize_list(NFAPIList** list) {
    *list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (*list == NULL) {
        perror("Failed to allocate memory for list");
        exit(EXIT_FAILURE);
    }

    (*list)->head = NULL;
    (*list)->count = 0;
    pthread_mutex_init(&(*list)->mutex, NULL);
    (*list)->rnti_set = (unsigned long*)calloc(MAX_ELEMENTS, sizeof(unsigned long));
}

// Add an element to the list
int add_element(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->count >= MAX_ELEMENTS || !is_rnti_unique(list, element.RNTI)) {
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    ListElement* new_element = (ListElement*)malloc(sizeof(ListElement));
    if (!new_element) {
        perror("Failed to allocate memory for list element");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    new_element->data = element;
    new_element->next = list->head;
    list->head = new_element;

    // Mark RNTI as used
    unsigned long index = element.RNTI % MAX_ELEMENTS;
    list->rnti_set[index] = element.RNTI;

    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Check if RNTI is unique in the list
int is_rnti_unique(NFAPIList* list, unsigned long rnti) {
    unsigned long index = rnti % MAX_ELEMENTS;
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (list->rnti_set[(index + i) % MAX_ELEMENTS] == rnti) {
            return 0;
        }
    }
    return 1;
}

// Serialize the list to a file
int serialize_list(const char* filename, const NFAPIList* list) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return -1;
    }

    pthread_mutex_lock((pthread_mutex_t*)&list->mutex);

    fwrite(&list->count, sizeof(size_t), 1, file);
    ListElement* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->mutex);

    fclose(file);
    return 0;
}

// Deserialize the list from a file
int deserialize_list(NFAPIList** list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return -1;
    }

    free_list(*list); // Free existing list before loading new data
    initialize_list(list);

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    NFAPI_CRC_INDICATION_PDU_T element;
    while (fread(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        add_element(*list, element);
    }

    fclose(file);
    return 0;
}

// Free the list and associated resources
void free_list(NFAPIList* list) {
    pthread_mutex_lock(&list->mutex);

    ListElement* current = list->head;
    while (current) {
        ListElement* next = current->next;
        free(current);
        current = next;
    }

    free(list->rnti_set);
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Example usage
int main() {
    NFAPIList* list;
    initialize_list(&list);

    for (size_t i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {i, rand(), rand() % 256, rand() % 2};
        if (add_element(list, pdu) != 0) {
            printf("Failed to add element with RNTI: %lu\n", pdu.RNTI);
        }
    }

    serialize_list("list.dat", list);

    NFAPIList* loaded_list;
    deserialize_list(&loaded_list, "list.dat");

    free_list(list);
    free_list(loaded_list);

    return 0;
}
