#define MAX_CAPACITY 10000
#define TIMEOUT_DURATION_MS 5000

typedef struct {
    unsigned int RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    void* data;
    size_t length;
} RX_PDU_T;

typedef struct NFAPI_RX_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    unsigned int RNTI;
    RX_PDU_T rx_pdu;
    struct NFAPI_RX_PDU_T* next;
} NFAPI_RX_PDU_T;

typedef struct {
    NFAPI_RX_PDU_T* head;
    pthread_mutex_t lock;
    unsigned int capacity;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = 0;
    return list;
}

int is_rnti_unique(DynamicList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);
    NFAPI_RX_PDU_T* current = list->head;
    while (current) {
        if (current->RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate RNTI found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 1; // Unique RNTI
}

int add_pdu(DynamicList* list, NFAPI_RX_PDU_T* pdu) {
    if (!is_rnti_unique(list, pdu->RNTI)) {
        fprintf(stderr, "Duplicate RNTI detected\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    if (list->capacity >= MAX_CAPACITY) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "List capacity exceeded\n");
        return -2; // Out of memory
    }

    pdu->next = list->head;
    list->head = pdu;
    list->capacity++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_list(DynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);
    NFAPI_RX_PDU_T* current = list->head;
    while (current) {
        fwrite(&(current->tag), sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&current->RNTI, sizeof(unsigned int), 1, file);
        fwrite(&current->rx_pdu.length, sizeof(size_t), 1, file);
        fwrite(current->rx_pdu.data, current->rx_pdu.length, 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    NFAPI_RX_PDU_T* current = list->head;
    while (current) {
        NFAPI_RX_PDU_T* temp = current;
        current = current->next;
        free(temp->rx_pdu.data);
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    DynamicList* list = create_dynamic_list();
    if (!list) return -1;

    // Example usage
    NFAPI_RX_PDU_T* pdu = malloc(sizeof(NFAPI_RX_PDU_T));
    if (pdu) {
        RX_UE_INFORMATION_TAG tag;
        pdu->tag = tag;
        pdu->RNTI = 12345; // Example RNTI
        pdu->rx_pdu.data = malloc(100); // Example data length
        pdu->rx_pdu.length = 100;

        if (add_pdu(list, pdu) != 0) {
            free(pdu->rx_pdu.data);
            free(pdu);
        }
    }

    serialize_list(list, "nfaapi_data.bin");
    destroy_dynamic_list(list);

    return 0;
}
