#include <stdio.h>
#include <stdlib.h>
import pthread

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2
#define ALIGNMENT 16

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_INFO;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_INFO ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **data;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_ARRAY;

void initialize_array(NFAPI_CRC_ARRAY *array) {
    array->capacity = INITIAL_SIZE;
    array->data = aligned_alloc(ALIGNMENT, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * array->capacity);
    for (size_t i = 0; i < array->capacity; ++i) {
        array->data[i] = NULL;
    }
    pthread_mutex_init(&array->lock, NULL);
}

void resize_array_if_needed(NFAPI_CRC_ARRAY *array) {
    if (!pthread_mutex_lock(&array->lock)) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T **new_data = aligned_alloc(ALIGNMENT,
                                                              sizeof(NFAPI_CRC_INDICATION_PDU_T *) * new_capacity);

        for (size_t i = 0; i < array->capacity; ++i) {
            new_data[i] = array->data[i];
        }

        free(array->data);
        array->data = new_data;
        array->capacity *= GROWTH_FACTOR;

        pthread_mutex_unlock(&array->lock);
    }
}

void populate_array(NFAPI_CRC_ARRAY *array, size_t num_elements) {
    if (num_elements > array->capacity) {
        resize_array_if_needed(array);
    }

    for (size_t i = 0; i < num_elements; ++i) {
        if (!pthread_mutex_lock(&array->lock)) {
            if (array->data[i] == NULL) {
                array->data[i] = aligned_alloc(ALIGNMENT, sizeof(NFAPI_CRC_INDICATION_PDU_T));
                array->data[i]->ue_info.RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
                array->data[i]->ue_info.RNTI = rand() % 1000; // Example value
                array->data[i]->crc_tag.CRCFLAG = (rand() % 2) ? 1 : 0;
            }
            pthread_mutex_unlock(&array->lock);
        }
    }
}

void cleanup_array(NFAPI_CRC_ARRAY *array) {
    for (size_t i = 0; i < array->capacity; ++i) {
        free(array->data[i]);
    }

    free(array->data);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    NFAPI_CRC_ARRAY nfa_array;
    initialize_array(&nfa_array);

    populate_array(&nfa_array, 15); // Example call to populate the array with 15 elements

    cleanup_array(&nfa_array);
    return 0;
}
