#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>
#include <stdint.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define THRESHOLD_MULTIPLIER 2

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} UE_INFO_T;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_INFO_T ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

typedef struct {
    Node** array;
    size_t capacity;
    pthread_mutex_t lock;
} TwoLevelArray;

void init_two_level_array(TwoLevelArray* tla, size_t initial_capacity) {
    tla->array = (Node**)calloc(initial_capacity, sizeof(Node*));
    if (!tla->array) {
        perror("Memory allocation failed for array");
        exit(EXIT_FAILURE);
    }
    tla->capacity = initial_capacity;
    pthread_mutex_init(&tla->lock, NULL);
}

void resize_two_level_array(TwoLevelArray* tla) {
    size_t new_capacity = tla->capacity * THRESHOLD_MULTIPLIER;
    Node** new_array = (Node**)realloc(tla->array, new_capacity * sizeof(Node*));
    if (!new_array) {
        perror("Memory reallocation failed for array");
        exit(EXIT_FAILURE);
    }
    for (size_t i = tla->capacity; i < new_capacity; ++i) {
        new_array[i] = NULL;
    }
    tla->array = new_array;
    tla->capacity = new_capacity;
}

void free_node(Node* node) {
    if (node) {
        free(node->data);
        free(node);
    }
}

void free_two_level_array(TwoLevelArray* tla) {
    for (size_t i = 0; i < tla->capacity; ++i) {
        Node* current = tla->array[i];
        while (current) {
            Node* next = current->next;
            free_node(current);
            current = next;
        }
    }
    free(tla->array);
    pthread_mutex_destroy(&tla->lock);
}

int add_pdu_to_two_level_array(TwoLevelArray* tla, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&tla->lock);

    size_t index = (uintptr_t)pdu % tla->capacity;
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed for node");
        pthread_mutex_unlock(&tla->lock);
        return -1;
    }
    new_node->data = pdu;
    new_node->next = tla->array[index];
    tla->array[index] = new_node;

    // Check if resize is needed
    size_t count = 0;
    for (size_t i = 0; i < tla->capacity; ++i) {
        Node* current = tla->array[i];
        while (current) {
            count++;
            current = current->next;
        }
    }
    if (count > tla->capacity) {
        resize_two_level_array(tla);
    }

    pthread_mutex_unlock(&tla->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(uint32_t ue_info_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Memory allocation failed for PDU");
        exit(EXIT_FAILURE);
    }
    pdu->ue_info.RX_UE_INFORMATION_TAG = ue_info_tag;
    pdu->ue_info.RNTI = rnti;
    srand((unsigned int)time(NULL)); // Seed the random number generator
    pdu->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    return pdu;
}

void populate_nfa_pds(TwoLevelArray* tla, size_t n, uint32_t max_ue_info_tag, uint16_t max_rnti) {
    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(rand() % max_ue_info_tag, rand() % max_rnti);
        if (add_pdu_to_two_level_array(tla, pdu) != 0) {
            free(pdu); // Handle allocation failure
        }
    }
}

int main() {
    TwoLevelArray tla;
    init_two_level_array(&tla, INITIAL_CAPACITY);

    size_t num_pdus = 100; // Example number of PDUs to populate
    uint32_t max_ue_info_tag = 1000; // Example maximum UE information tag value
    uint16_t max_rnti = 65535; // Maximum RNTI value

    populate_nfa_pds(&tla, num_pdus, max_ue_info_tag, max_rnti);

    free_two_level_array(&tla);
    return 0;
}
