    }

    threading.Lock_lock(&list->lock); // Ensure thread safety

    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i].RNTI == entry.RNTI) {
            list->entries[i] = entry;
            threading.Lock_unlock(&list->lock);
            return;
        }
