    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConcurrentQueue;

void initialize_queue(ConcurrentQueue *queue) {
    queue->capacity = INITIAL_CAPACITY;
    queue->size = 0;
    queue->data = malloc(queue->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&queue->lock, NULL);
}

void resize_queue(ConcurrentQueue *queue) {
    size_t new_capacity = queue->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(queue->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to resize memory");
        exit(EXIT_FAILURE);
    }
    queue->data = new_data;
    queue->capacity = new_capacity;
}

int is_valid_structure(const NFAPI_CRC_INDICATION_PDU_T *structure) {
    // Define your validation rules here
    return structure->ue_info.RX_UE_INFORMATION_TAG > 0 && 
           structure->ue_info.RNTI > 0;
}

void log_error(const char *message, const NFAPI_CRC_INDICATION_PDU_T *structure) {
    printf("Error: %s - RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
           message, structure->ue_info.RX_UE_INFORMATION_TAG, 
           structure->ue_info.RNTI, structure->crc_tag.CRCFLAG);
}

void enqueue(ConcurrentQueue *queue, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&queue->lock);

    if (queue->size == queue->capacity) {
        resize_queue(queue);
    }

    if (!is_valid_structure(&item)) {
        log_error("Invalid structure detected", &item);
        pthread_mutex_unlock(&queue->lock);
        return;
    }

    queue->data[queue->size++] = item;

    pthread_mutex_unlock(&queue->lock);
}

void free_queue(ConcurrentQueue *queue) {
    free(queue->data);
    pthread_mutex_destroy(&queue->lock);
}

int main() {
    srand(time(NULL));
    ConcurrentQueue queue;
    initialize_queue(&queue);

    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.ue_info.RX_UE_INFORMATION_TAG = rand() % 100 + 1;
        pdu.ue_info.RNTI = rand() % 1000 + 1;
        pdu.crc_tag.CRCFLAG = rand() % 2;

        enqueue(&queue, pdu);
    }

    free_queue(&queue);

    return 0;
}
