#define MAX_STRUCTS 50000
#define INITIAL_CAPACITY 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp; // For tracking age of the structure
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double age_threshold; // Age in seconds to evict structures
    int (*priority_func)(const NFAPI_CRC_INDICATION_PDU_T*); // Function pointer for prioritization logic
} DynamicCollection;

// Helper function prototypes
static void resize_collection(DynamicCollection *collection, size_t new_capacity);
static void evict_old_structures(DynamicCollection *collection);

void init_collection(DynamicCollection *collection, double age_threshold, int (*priority_func)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    collection->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->age_threshold = age_threshold;
    collection->priority_func = priority_func;
}

void destroy_collection(DynamicCollection *collection) {
    free(collection->data);
    pthread_mutex_destroy(&collection->lock);
}

void add_structure(DynamicCollection *collection, NFAPI_CRC_INDICATION_PDU_T structure) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        resize_collection(collection, collection->capacity * 2);
    }

    // Insert based on priority
    int index = collection->count;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->priority_func(&collection->data[i]) > collection->priority_func(&structure)) {
            index = i;
            break;
        }
    }

    memmove(&collection->data[index + 1], &collection->data[index], (collection->count - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    collection->data[index] = structure;
    collection->data[index].timestamp = time(NULL);
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
}

void evict_expired_structures(DynamicCollection *collection) {
    evict_old_structures(collection);
}

static void resize_collection(DynamicCollection *collection, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(collection->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data != NULL) {
        collection->data = new_data;
        collection->capacity = new_capacity;
    }
}

static void evict_old_structures(DynamicCollection *collection) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < collection->count;) {
        if (difftime(current_time, collection->data[i].timestamp) > collection->age_threshold) {
            memmove(&collection->data[i], &collection->data[i + 1], (collection->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --collection->count;
        } else {
            ++i;
        }
    }

    // Resize down if too much space is unused
    if (collection->capacity > collection->count * 2 && collection->capacity / 2 >= INITIAL_CAPACITY) {
        resize_collection(collection, collection->capacity / 2);
    }
}

// Example priority function based on CRCFLAG (placeholder for real logic)
int example_priority_func(const NFAPI_CRC_INDICATION_PDU_T* structure) {
    return structure->CRCFLAG; // Higher flag value gets higher priority
}

