NFAPI_CRC_INDICATION_PDU_T* initialize_rnti_array(unsigned int start, unsigned int end) {
    if (end <= start || end - start > MAX_RNTI_COUNT) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *rnti_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_RNTI_COUNT);
    if (!rnti_array) return NULL;

    unsigned int count = 0;
    for (unsigned int rnti = start; rnti <= end && count < MAX_RNTI_COUNT; ++rnti) {
        NFAPI_CRC_INDICATION_PDU_T *current = realloc(rnti_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (count + 1));
        if (!current) break;

        rnti_array = current;
