<?php
function manageUserAccount($postData) {
    $response = ['success' => false, 'message' => ''];

    // Validate input data
    if (!isset($postData['name']) || !isset($postData['email']) || !filter_var($postData['email'], FILTER_VALIDATE_EMAIL)) {
        return json_encode(['success' => false, 'message' => 'Invalid name or email']);
    }

    $db = new mysqli('host', 'user', 'password', 'database');
    if ($db->connect_error) {
        return json_encode(['success' => false, 'message' => 'Database connection failed: ' . $db->connect_error]);
    }

    try {
        $db->begin_transaction();

        if (isset($postData['sub_action']) && $postData['sub_action'] === 'delete') {
            $id = isset($postData['id']) ? intval($postData['id']) : null;
            if ($id) {
                $stmt = $db->prepare('DELETE FROM users WHERE id = ?');
                $stmt->bind_param('i', $id);
                $stmt->execute();
                $response['message'] = 'User deleted successfully';
            } else {
                throw new Exception('ID is required for deletion');
            }
        } elseif (isset($postData['id']) && intval($postData['id'])) {
            // Update existing user
            $id = intval($postData['id']);
            $stmt = $db->prepare('UPDATE users SET name=?, email=?, password=? WHERE id=?');
            $hashedPassword = password_hash($postData['password'], PASSWORD_DEFAULT);
            $stmt->bind_param('sssi', $postData['name'], $postData['email'], $hashedPassword, $id);
        } else {
            // Create new user
            $stmt = $db->prepare('INSERT INTO users (name, email, password) VALUES (?, ?, ?)');
            $hashedPassword = password_hash($postData['password'], PASSWORD_DEFAULT);
            $stmt->bind_param('sss', $postData['name'], $postData['email'], $hashedPassword);
        }

        if ($stmt->execute()) {
            $response['success'] = true;
            $response['message'] = isset($postData['sub_action']) && $postData['sub_action'] === 'delete' ? 
                                    'User deleted successfully' : 
                                    (isset($postData['id']) ? 'User updated successfully' : 'User created successfully');
        } else {
            throw new Exception('Database operation failed: ' . $stmt->error);
        }

        $db->commit();
    } catch (Exception $e) {
        $db->rollback();
        $response['message'] = 'Error: ' . $e->getMessage();
    }

    $stmt->close();
    $db->close();

    return json_encode($response);
}
?>
