    uint16_t RNTI;
    struct {
        int CRCFLAG; // Simulating the field
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *array;
    pthread_mutex_t lock;
} RNTI_Manager;

// Helper function to generate a random CRCFLAG value
int getRandomCRCFlag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Thread-safe function to add an entry to the manager
int addRNTI(RNTI_Manager *manager, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? MAX_RNTI : manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RNTI == rnti) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // RNTI already exists
        }
    }

    NFAPI_CRC_INDICATION_PDU_T new_entry = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rnti, .CRC_INDICATION_REL8_TAG = { .CRCFLAG = getRandomCRCFlag() } };

    manager->array[manager->count++] = new_entry;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Function to initialize the RNTI_Manager
RNTI_Manager* initRNTIManager() {
    RNTI_Manager *manager = malloc(sizeof(RNTI_Manager));
    if (!manager) return NULL;

    manager->capacity = MAX_RNTI;
    manager->count = 0;
    manager->array = malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!manager->array) {
        free(manager);
        return NULL; // Memory allocation failed
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Function to clean up the RNTI_Manager
void destroyRNTIManager(RNTI_Manager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
    }
}

int main() {
    // Example usage
    RNTI_Manager* manager = initRNTIManager();
    if (!manager) {
        fprintf(stderr, "Failed to initialize RNTI Manager.\n");
        return EXIT_FAILURE;
    }

    for (uint16_t rnti = 1; rnti <= MAX_RNTI + 100; ++rnti) { // Simulating external input
        int result = addRNTI(manager, rnti);
        if (result != 0) {
            fprintf(stderr, "Failed to add RNTI %u. Result code: %d\n", rnti, result);
        }
    }

    destroyRNTIManager(manager);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety:** The `pthread_mutex_lock` and `pthread_mutex_unlock` functions ensure that the function is thread-safe.
- **Memory Management:** Uses dynamic memory allocation (`malloc`, `realloc`) with checks for failures. The initial capacity doubles each time it needs to grow, minimizing reallocation frequency.
- **Capacity Handling:** Automatically grows when needed, ensuring no duplicates by checking existing entries before adding new ones.
- **Random CRCFLAG:** Simulated using a random number generator to set the `CRCFLAG`.
- **Error Checking:** Provides error handling for memory allocation failures and duplicate RNTI detection.']

