// Structure to manage the list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPIList;

// Function prototypes
NFAPIList* create_list(size_t initial_capacity);
void destroy_list(NFAPIList* list);
int add_to_list(NFAPIList* list, RX_UE_INFORMATION_TAG rxTag, RNTI rnti);
void log_message(const char* message);

// Helper function to initialize the random seed
static void init_random_seed() {
    srand((unsigned int)time(NULL));
}

// Create a new list with initial capacity
NFAPIList* create_list(size_t initial_capacity) {
    NFAPIList* list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->capacity = initial_capacity;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list->elements) {
        free(list);
        return NULL;
    }
    return list;
}

// Destroy the list and free allocated memory
void destroy_list(NFAPIList* list) {
    pthread_mutex_lock(&list->lock);
    free(list->elements);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add an element to the list, ensuring thread safety and uniqueness of RNTI
int add_to_list(NFAPIList* list, RX_UE_INFORMATION_TAG rxTag, RNTI rnti) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > 10000) return -1; // Cap at max capacity

        pthread_mutex_lock(&list->lock);
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->capacity = new_capacity;
        list->elements = new_elements;
        pthread_mutex_unlock(&list->lock);
    }

    // Ensure RNTI uniqueness
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].rnti == rnti) {
            log_message("Error: Duplicate RNTI detected. Operation halted.");
            return -2;
        }
    }

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T new_element = {
        .rxUeInformationTag = rxTag,
        .rnti = rnti,
        .crcIndicationRel8Tag = { .CRCFLAG = rand() % 2 }
    };

    list->elements[list->size++] = new_element;
    pthread_mutex_unlock(&list->lock);

    // Asynchronously log the creation
    log_message("New element added to the list.");

    return 0;
}

// Example logging function (asynchronous implementation not shown for brevity)
void log_message(const char* message) {
    printf("%s\n", message);  // Replace with actual asynchronous logging mechanism
}
