void init_rx_ue_information_tag(RX_UE_INFORMATION_TAG *tag) {
    tag->member1 = rand() % 65535 + 1; // Ensure it's non-zero
    tag->member2 = rand() % 4294967295 + 1;
}

// Function to generate a random CRCFLAG
void init_crc_indication_rel8_tag(CRC_INDICATION_REL8_TAG *tag) {
    tag->member = rand() & 1; // Randomly set CRCFLAG to 0 or 1
}

// Thread-safe function to add structure to list
int add_structure_to_list(NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    pthread_rwlock_wrlock(&rwlock);

    if (nfa_list_size >= MAX_STRUCTURES) {
        fprintf(stderr, "Error: Maximum number of structures reached.\n");
        pthread_rwlock_unlock(&rwlock);
        return -1;
    }

    // Ensure unique RNTI
    for (int i = 0; i < nfa_list_size; ++i) {
        if (nfa_list[i].rnti == new_struct->rnti) {
            pthread_rwlock_unlock(&rwlock);
            fprintf(stderr, "Error: Duplicate RNTI found.\n");
            return -1;
        }
    }

    // Reallocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(nfa_list, (nfa_list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        pthread_rwlock_unlock(&rwlock);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }
    nfa_list = temp;

    // Add new structure to the list
    nfa_list[nfa_list_size] = *new_struct;
    atomic_fetch_add_explicit(&nfa_list_size, 1, memory_order_relaxed);

    pthread_rwlock_unlock(&rwlock);
    return 0;
}

// Function to initialize and manage the list
void manage_nfa_list(void) {
    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T new_struct;

        init_rx_ue_information_tag(&new_struct.rx_ue_info_tag);
        new_struct.rnti = rand() % 65535 + 1; // Ensure non-zero RNTI
        init_crc_indication_rel8_tag(&new_struct.crc_indication_rel8_tag);

        if (add_structure_to_list(&new_struct) != 0) {
            break; // Exit on error
        }
    }
}

// Function to free the list
void free_nfa_list(void) {
    pthread_rwlock_wrlock(&rwlock);
    free(nfa_list);
    nfa_list = NULL;
    atomic_store_explicit(&nfa_list_size, 0, memory_order_relaxed);
    pthread_rwlock_unlock(&rwlock);
}

// Unit test example
void test_manage_nfa_list() {
    manage_nfa_list();
    printf("Test completed. List size: %d\n", nfa_list_size);

    // Add more tests as needed to validate correctness and robustness

    free_nfa_list();
}
