#define MAX_LIST_SIZE 1000

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[64];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} CRCList;

pthread_rwlock_t list_lock = PTHREAD_RWLOCK_INITIALIZER;

void initialize_list(CRCList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_rwlock_wrlock(&list_lock);

    Node* new_node = create_node(data);
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_rwlock_unlock(&list_lock);
        return;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count < MAX_LIST_SIZE) {
        if (list->head == NULL) {
            list->head = new_node;
        } else {
            Node* temp = list->head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_rwlock_unlock(&list_lock);
}

void remove_from_list(CRCList* list, int RNTI) {
    pthread_rwlock_wrlock(&list_lock);

    pthread_mutex_lock(&list->lock);

    Node *temp = list->head, *prev = NULL;
    while (temp != NULL && temp->data.RNTI != RNTI) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) { // Not found
        pthread_mutex_unlock(&list->lock);
        pthread_rwlock_unlock(&list_lock);
        return;
    }

    if (prev == NULL) {
        list->head = temp->next;
    } else {
        prev->next = temp->next;
    }

    free(temp);
    list->count--;

    pthread_mutex_unlock(&list->lock);
    pthread_rwlock_unlock(&list_lock);
}

void log_message(const char* message, int level) {
    const char* levels[] = {"INFO", "WARN", "ERROR"};
    if (level >= 0 && level < 3) {
        printf("[%s] %s\n", levels[level], message);
    }
}

void generate_random_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->RNTI = rand() % 10000;
    snprintf(pdu->RX_UE_INFORMATION_TAG, sizeof(pdu->RX_UE_INFORMATION_TAG), "TAG_%d", rand());
}

