#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_COUNT 10000

typedef struct {
    int id;
    int crc_indicated;
} TransportChannel;

typedef struct {
    int rnti;
    TransportChannel* channels;
    size_t channel_count;
} UEContext;

typedef struct {
    pthread_mutex_t lock;
    UEContext* contexts;
    size_t count;
    size_t capacity;
} LTEUEContextList;

void init_lte_ue_context_list(LTEUEContextList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->contexts = malloc(MAX_UE_COUNT * sizeof(UEContext));
    list->count = 0;
    list->capacity = MAX_UE_COUNT;
}

void add_ue_context(LTEUEContextList* list, int ue_id, int rnti, TransportChannel* channels, size_t channel_count) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        // Resize the array to accommodate more UE contexts
        list->capacity *= 2;
        list->contexts = realloc(list->contexts, list->capacity * sizeof(UEContext));
    }

    UEContext* context = &list->contexts[list->count++];
    context->rnti = rnti;
    context->channels = malloc(channel_count * sizeof(TransportChannel));
    for (size_t i = 0; i < channel_count; ++i) {
        context->channels[i] = channels[i];
    }
    context->channel_count = channel_count;

    pthread_mutex_unlock(&list->lock);
}

void update_ue_context(LTEUEContextList* list, int ue_id, TransportChannel* new_channels, size_t channel_count) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        UEContext* context = &list->contexts[i];
        if (context->rnti == ue_id) { // Assuming RNTI as unique identifier
            free(context->channels);
            context->channels = malloc(channel_count * sizeof(TransportChannel));
            for (size_t j = 0; j < channel_count; ++j) {
                context->channels[j] = new_channels[j];
            }
            context->channel_count = channel_count;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void free_lte_ue_context_list(LTEUEContextList* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->contexts[i].channels);
    }
    free(list->contexts);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    LTEUEContextList ue_context_list;
    init_lte_ue_context_list(&ue_context_list);

    // Example usage
    TransportChannel channels[] = {{1, 0}, {2, 1}};
    add_ue_context(&ue_context_list, 1001, 2001, channels, 2);

    // Simulate an update
    TransportChannel new_channels[] = {{3, 1}, {4, 0}};
    update_ue_context(&ue_context_list, 2001, new_channels, 2);

    free_lte_ue_context_list(&ue_context_list);
    return 0;
}
