#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Assuming these are defined elsewhere in your codebase.
typedef struct {
    // Fields for RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CRC_Indication_List;

#define INITIAL_CAPACITY 10
#define RETRY_LIMIT 3

CRC_Indication_List* create_list() {
    CRC_Indication_List *list = (CRC_Indication_List *)malloc(sizeof(CRC_Indication_List));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(CRC_Indication_List *list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_element(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T element) {
    int retry_count = 0;

    while (retry_count < RETRY_LIMIT) {
        pthread_mutex_lock(&list->lock);

        if (list->size == list->capacity) {
            size_t new_capacity = list->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (!new_data) {
                pthread_mutex_unlock(&list->lock);
                retry_count++;
                continue;
            }

            list->data = new_data;
            list->capacity = new_capacity;
        }

        list->data[list->size++] = element;

        pthread_mutex_unlock(&list->lock);

        return 0; // Success
    }

    return -1; // Failure after retries
}

int remove_element(CRC_Indication_List *list, size_t index) {
    int retry_count = 0;

    while (retry_count < RETRY_LIMIT) {
        pthread_mutex_lock(&list->lock);

        if (index >= list->size) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Invalid index
        }

        memmove(&list->data[index], &list->data[index + 1], (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->size--;

        pthread_mutex_unlock(&list->lock);

        return 0; // Success
    }

    return -1; // Failure after retries
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu && pdu->CRC_INDICATION_REL8_TAG)
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
}
```

### Explanation of the Approach:
- **Thread Safety:** The list is protected by a mutex to ensure thread safety during concurrent access.
- **Dynamic Resizing:** The array doubles in size when full, minimizing reallocations and handling larger datasets efficiently.
- **Retry Mechanism:** Operations are retried up to three times on failure, which helps manage transient errors like failed memory allocations due to temporary resource shortages.
- **Memory Management:** By using `realloc`, the list minimizes frequent memory allocations. This approach reduces fragmentation compared to linked lists, improving cache locality.
- **Scalability and Performance:** The use of a mutex allows for concurrent access while maintaining data integrity. The dynamic resizing strategy ensures performance remains optimal as the dataset grows.

This code provides a robust foundation that can be expanded upon or integrated into larger systems managing network protocol-related tasks. Adjustments might be needed based on specific application constraints and further testing under your actual load conditions.']

