CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->entry_count = 0;
    return list;
}

void destroy_crc_list(CRCList* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_rnti_unique(CRCList* list, unsigned int rnti) {
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

