void add_crc_indication(CRCList* list, unsigned int max_buffer_size) {
    pthread_mutex_lock(&list->lock);

    if (list->entry_count >= max_buffer_size) {
        log_warning("Maximum buffer size exceeded. Retaining only the first N entries.");
        Node* to_remove = list->head;
        list->head = to_remove->next;
        free(to_remove);
        list->entry_count--;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    unsigned int rnti;
    do {
        rnti = rand() % 100000; // Example range for RNTI
    } while (!is_rnti_unique(list, rnti));

    new_node->data.RX_UE_INFORMATION_TAG = rand(); // Example random tag
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag (0 or 1)
    new_node->next = list->head;
    list->head = new_node;
    list->entry_count++;

    pthread_mutex_unlock(&list->lock);
}

void populate_crc_list(CRCList* list, int num_entries, unsigned int max_buffer_size) {
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_entries; ++i) {
        add_crc_indication(list, max_buffer_size);
    }
}

void print_list(const CRCList* list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
