    return (pci % 2 == 0); // Only even PCIs are considered reliable
}

// Generate SNR value within a specified range, with fallback mechanism
double generate_snr(double snr_min, double snr_max) {
    double snr;
    int success = rand() % 10; // Simulate random module success rate

    if (success < 8) { // Assume external module fails occasionally
        snr = ((double)rand() / RAND_MAX) * (snr_max - snr_min) + snr_min;
    } else {
        snr = snr_min + (rand() % 5); // Fallback logic
    }

    return snr;
}
```

