    Node* head;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
} DynamicList;

// Logging function (external integration assumed)
void log_warning(const char* message) {
    // External logging mechanism
    fprintf(stderr, "Warning: %s\n", message);
}

DynamicList* create_dynamic_list(size_t max_size) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (entry.RNTI == 0 || list->count >= list->max_size) {
        log_warning("RNTI is zero or max size exceeded.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == entry.RNTI) break;
        current = current->next;
    }

    if (current) { // RNTI already exists
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_warning("Memory allocation failed.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

size_t get_entry_count(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    size_t count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_index(DynamicList* list, size_t index) {
    if (index >= list->count) return NULL;

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i)
        current = current->next;

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* entry = (current) ? &current->data : NULL;
    pthread_mutex_unlock(&list->lock);

    return entry;
}

void stress_test(DynamicList* list, size_t iterations) {
    for (size_t i = 0; i < iterations; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.RX_UE_INFORMATION_TAG = rand() % 100;
        entry.RNTI = rand() % 65535 + 1; // Random RNTI
        entry.CRC_INDICATION_REL8_TAG = rand() % 10;

        add_entry(list, entry);
    }
}

int main() {
