    Node* node_ptr;
} HashTableEntry;

typedef struct {
    HashTableEntry* table;
    size_t size;
    pthread_mutex_t lock;
} CustomHashTable;

PriorityQueue priority_queue = {NULL, PTHREAD_MUTEX_INITIALIZER};
CustomHashTable hash_table = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

unsigned int hash_function(unsigned int RNTI) {
    return RNTI % hash_table.size;
}

void initialize_hash_table(size_t size) {
    pthread_mutex_lock(&hash_table.lock);
    if (hash_table.table == NULL) {
        hash_table.size = size;
        hash_table.table = calloc(hash_table.size, sizeof(HashTableEntry));
    }
    pthread_mutex_unlock(&hash_table.lock);
}

int insert_to_priority_queue(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&priority_queue.lock);
    Node** current = &priority_queue.head;

    while (*current && ((*current)->data.timestamp < pdu.timestamp)) {
        current = &(*current)->next;
    }

    new_node->next = *current;
    *current = new_node;
    pthread_mutex_unlock(&priority_queue.lock);

    return 0;
}

int insert_to_hash_table(NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned int index = hash_function(pdu.RNTI);
    HashTableEntry* entry;

    pthread_mutex_lock(&hash_table.lock);
    for (entry = &hash_table.table[index]; entry != NULL; entry = entry->node_ptr ? &entry->node_ptr->data : NULL) {
        if (entry->RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&hash_table.lock);
            return -1; // RNTI already exists
        }
    }

    entry = malloc(sizeof(HashTableEntry));
    if (!entry) {
        pthread_mutex_unlock(&hash_table.lock);
        return -1;
    }

    entry->RNTI = pdu.RNTI;
    entry->node_ptr = (Node*)malloc(sizeof(Node));
    if (!entry->node_ptr) {
        free(entry);
        pthread_mutex_unlock(&hash_table.lock);
        return -1;
    }

    entry->node_ptr->data = pdu;
    entry->node_ptr->next = hash_table.table[index];
    hash_table.table[index] = entry;

    pthread_mutex_unlock(&hash_table.lock);
    return 0;
}

void create_and_populate_list(int max_buffer_size) {
    initialize_hash_table(2 * max_buffer_size); // Simple heuristic for load factor

    pthread_t threads[MAX_BUFFER_SIZE];
    int thread_count = 0;

    for (int i = 0; i < MAX_BUFFER_SIZE; ++i) {
        if (thread_count >= MAX_BUFFER_SIZE) break;

        NFAPI_CRC_INDICATION_PDU_T pdu;
        memset(&pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu.ue_info.RNTI = rand() % max_buffer_size + 1; // Unique RNTI
        pdu.crc_tag.CRCFLAG = rand() % 2;
        pdu.timestamp = time(NULL);

        pthread_create(&threads[thread_count], NULL, (void* (*)(void*))insert_to_priority_queue, &pdu);
        if (insert_to_hash_table(pdu) == 0) {
            thread_count++;
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    srand(time(NULL));
    create_and_populate_list(MAX_BUFFER_SIZE);

    // Implement periodic archiving and metrics collection here

    return 0;
}
