['Here's a C implementation that fulfills your specified requirements for managing a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures with the operational constraints you've mentioned:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 100000

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    time_t last_used; // For LRU management
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t current_size;
    pthread_mutex_t lock;
} CRCIndicationList;

void init_list(CRCIndicationList *list) {
    list->head = NULL;
    list->tail = NULL;
    list->current_size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_node() {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    node->next = NULL;
    node->last_used = time(NULL); // Initialize with current timestamp
    return node;
}

void deallocate_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    free(node);
}

void add_crc_indication(CRCIndicationList *list, int rx_ue_info_tag, int rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->current_size >= MAX_LIST_SIZE) {
        // Evict least recently used node
        NFAPI_CRC_INDICATION_PDU_T *temp = list->head;
        NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

        while (temp && temp != list->tail) {
            if ((temp->next == NULL) || (temp->last_used < temp->next->last_used)) {
                prev = (temp->next == NULL) ? list->head : temp;
                temp = (temp->next == NULL) ? list->tail : temp->next;
            } else {
                prev = temp;
                temp = temp->next;
            }
        }

        if (prev == NULL) {
            // Remove head
            NFAPI_CRC_INDICATION_PDU_T *old_head = list->head;
            list->head = old_head->next;
            deallocate_node(old_head);
        } else if (temp == list->tail) {
            // Remove tail
            prev->next = NULL;
            list->tail = prev;
            deallocate_node(temp);
        } else {
            // Remove middle node
            prev->next = temp->next;
            deallocate_node(temp);
        }
        list->current_size--;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = allocate_node();
    new_node->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->RNTI = rnti;
    new_node->crc_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    if (list->tail) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }

    list->current_size++;
    pthread_mutex_unlock(&list->lock);
}

void free_list(CRCIndicationList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        deallocate_node(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->current_size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage and testing
int main() {
    CRCIndicationList list;
    init_list(&list);

    // Add some elements to test
    for (int i = 0; i < MAX_LIST_SIZE + 10; ++i) { // Intentionally exceed the limit
        add_crc_indication(&list, i, rand());
    }

    free_list(&list);
    return 0;
}
