// Error codes
enum ErrorCode {
    SUCCESS = 0,
    INVALID_INPUT = 1,
    INSUFFICIENT_MEMORY = 2,
    MEMORY_POOL_ERROR = 3
};

typedef struct MemoryPool {
    void *pool;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
} MemoryPool;

MemoryPool* initialize_memory_pool(size_t block_size, size_t max_blocks) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->total_blocks = max_blocks;
    mp->used_blocks = 0;

    mp->pool = malloc(block_size * max_blocks);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    memset(mp->pool, 0, block_size * max_blocks);
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    if (mp->used_blocks >= mp->total_blocks) {
        return NULL;
    }

    void *block = (char*)mp->pool + (mp->used_blocks * mp->block_size);
    mp->used_blocks++;
    return block;
}

void* manage_memory_pool(size_t n, int *error_code) {
    static MemoryPool *mp = initialize_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_STRUCTURES);
    if (!mp) {
        *error_code = MEMORY_POOL_ERROR;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_alloc(mp);
    if (!array) {
        *error_code = INSUFFICIENT_MEMORY;
        return NULL;
    }

