    CRC_INDICATION_REL8_TAG crc_tag;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically manage a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* manage_crc_indication_list(
    NFAPI_CRC_INDICATION_PDU_T** last_state, 
    size_t num_states) {

    // Error handling for invalid input
    if (!last_state || *last_state == NULL) {
        fprintf(stderr, "Error: Invalid last state pointer.\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Locking to ensure thread safety
    pthread_mutex_lock(&lock);

    size_t current_size = 0;
    NFAPI_CRC_INDICATION_PDU_T* curr = *last_state;

    while (curr && curr->next) {
        curr = curr->next;
        ++current_size;
    }

    // Check if more states need to be added
    size_t additional_states = num_states - current_size;
    if (additional_states == 0) {
        pthread_mutex_unlock(&lock);
        return *last_state;
    }

    // Allocate memory for the new structures
    NFAPI_CRC_INDICATION_PDU_T* new_head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_head) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Initialize the new list
    NFAPI_CRC_INDICATION_PDU_T* tail = new_head;
    for (size_t i = 0; i < additional_states; ++i) {
        tail->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!tail->next) {
            fprintf(stderr, "Error: Memory allocation failed.\n");

            // Free allocated memory to prevent leaks
            while (new_head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = new_head;
                new_head = new_head->next;
                free(temp);
            }
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Set random CRCFLAG for demonstration purposes
        tail->next->crc_tag.RX_UE_INFORMATION_TAG = rand() % 100; // Example value
        tail->next->crc_tag.RNTI = rand() % 256; // Example value
        tail->next->CRCFLAG = rand() % 2;

        tail->next->next = NULL;
        tail = tail->next;
    }

    // Link the new list to the existing one
    curr->next = new_head;

    pthread_mutex_unlock(&lock);

    return *last_state;
}

// Example usage function to extend state list
void example_usage() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    head = manage_crc_indication_list(&head, 10);

    // Free allocated memory for demonstration purposes
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    example_usage();
    return 0;
}
