['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000
#define CREATION_LIMIT_PER_SECOND 500

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // This could be set to any integer, typically 0 or 1.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures[MAX_STRUCTURES];
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    time_t last_creation_time;
    int creation_count_in_last_second;
    uint32_t seed; // For the pseudo-random number generator
} DynamicArrayManager;

// Initialize the dynamic array manager
void initialize_manager(DynamicArrayManager* manager, uint32_t initial_seed) {
    if (manager == NULL) return;

    manager->count = 0;
    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        manager->structures[i] = NULL;
    }
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->last_creation_time = time(NULL);
    manager->creation_count_in_last_second = 0;

    if (initial_seed == 0) {
        // Use current system time as the seed
        initial_seed = (uint32_t)time(NULL);
    }
    manager->seed = initial_seed;
}

// Pseudo-random number generator using Linear Congruential Generator (LCG)
int pseudo_random(int* seed) {
    const uint64_t a = 6364136223846793005ULL;
    const uint64_t c = 1;
    *seed = (*seed * a + c) & ((1LL << 32) - 1);
    return (*seed >> 16) & 0x7FFF; // Use the higher bits for a reasonable spread
}

// Function to add a new structure, ensuring thread safety and rate limiting
int add_structure(DynamicArrayManager* manager) {
    if (manager == NULL || manager->count >= MAX_STRUCTURES)
        return -1;

    pthread_mutex_lock(&manager->mutex);

    time_t current_time = time(NULL);
    if (current_time != manager->last_creation_time) {
        // Reset the creation counter every second
        manager->creation_count_in_last_second = 0;
        manager->last_creation_time = current_time;
    }

    if (manager->creation_count_in_last_second >= CREATION_LIMIT_PER_SECOND) {
        pthread_mutex_unlock(&manager->mutex);
        return -2; // Rate limit exceeded
    }

    NFAPI_CRC_INDICATION_PDU_T* new_structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_structure == NULL) {
        fprintf(stderr, "Memory allocation failed for a new structure.\n");
        pthread_mutex_unlock(&manager->mutex);
        return -3; // Memory allocation failure
    }

    // Initialize the new structure with pseudo-random values
    uint16_t random_rnti = pseudo_random(&manager->seed) % 65535;
    new_structure->RX_UE_INFORMATION_TAG = pseudo_random(&manager->seed) & 0xFFFFFFFF;
    new_structure->RNTI = (uint16_t)random_rnti;
    new_structure->CRC_INDICATION_REL8_TAG = (uint8_t)(pseudo_random(&manager->seed) % 256);
    new_structure->CRCFLAG = (pseudo_random(&manager->seed) & 1);

    // Add the structure to the array
    manager->structures[manager->count++] = new_structure;

    // Increment and log creation count
    manager->creation_count_in_last_second++;
    printf("Created structure %zu: RX_UE_INFORMATION_TAG=0x%08X, RNTI=%d\n", manager->count - 1, 
           new_structure->RX_UE_INFORMATION_TAG, new_structure->RNTI);

    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

// Function to clean up resources and destroy the manager
void cleanup_manager(DynamicArrayManager* manager) {
    if (manager == NULL) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->structures[i]);
    }

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond);
}

int main() {
    DynamicArrayManager manager;
    initialize_manager(&manager, 0); // Initialize with default seed

    for (int i = 0; i < 10000; ++i) { // Attempt to add more structures than possible
        int result = add_structure(&manager);
        if (result != 0)
            printf("Failed to add structure: %d\n", result);
    }

    cleanup_manager(&manager);
    return 0;
}
```

