static void resize_dynamic_array(DynamicArray* dyn_array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
