    if (dyn_array->count >= dyn_array->capacity) {
        resize_dynamic_array(dyn_array, dyn_array->capacity * 2);
        if (!dyn_array->array) {
            pthread_mutex_unlock(&dyn_array->lock);
            return -1;
        }
    }

    dyn_array->array[dyn_array->count++] = element;

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

// Retrieve an element by index
int get_element(const DynamicArray* dyn_array, size_t index, NFAPI_CRC_INDICATION_PDU_T* out_element) {
