#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum { CRC_OK = 0, CRC_ERROR } CrcStatus;

typedef struct {
    char imsi[16];       // Unique IMSI identifier (15 digits + null terminator)
    int rnti;            // Random Network Temporary Identifier
    CrcStatus crcIndication; // Status indicator for CRC
} UEContext;

typedef struct {
    UEContext *contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} UECtxManager;

// Initialize the manager
void initUECtxManager(UECtxManager *manager) {
    manager->capacity = 10;
    manager->count = 0;
    manager->contexts = malloc(manager->capacity * sizeof(UEContext));
    if (!manager->contexts) {
        perror("Failed to allocate memory for UE contexts");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->lock, NULL);
}

// Resize the storage
static void resizeContexts(UECtxManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    UEContext *new_contexts = realloc(manager->contexts, new_capacity * sizeof(UEContext));
    if (!new_contexts) {
        perror("Failed to reallocate memory for UE contexts");
        exit(EXIT_FAILURE);
    }
    manager->contexts = new_contexts;
    manager->capacity = new_capacity;
}

// Add or update a context
void addOrUpdateUEContext(UECtxManager *manager, const char *imsi, int rnti, CrcStatus crc) {
    pthread_mutex_lock(&manager->lock);

    // Check if the context already exists and update it
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->contexts[i].imsi, imsi) == 0) {
            manager->contexts[i].rnti = rnti;
            manager->contexts[i].crcIndication = crc;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // If not found and capacity is full, resize
    if (manager->count == manager->capacity) {
        resizeContexts(manager);
    }

    // Add new context
    strcpy(manager->contexts[manager->count].imsi, imsi);
    manager->contexts[manager->count].rnti = rnti;
    manager->contexts[manager->count].crcIndication = crc;
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
}

// Retrieve a context by IMSI
UEContext *getUEContextByIMSI(UECtxManager *manager, const char *imsi) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->contexts[i].imsi, imsi) == 0) {
            UEContext *context = &manager->contexts[i];
            pthread_mutex_unlock(&manager->lock);
            return context;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Free resources
void freeUECtxManager(UECtxManager *manager) {
    if (manager) {
        free(manager->contexts);
        pthread_mutex_destroy(&manager->lock);
    }
}

int main() {
    UECtxManager manager;
    initUECtxManager(&manager);

    addOrUpdateUEContext(&manager, "123456789012345", 1001, CRC_OK);
    UEContext *context = getUEContextByIMSI(&manager, "123456789012345");
    if (context) {
        printf("Found IMSI: %s, RNTI: %d, CRC: %d\n", context->imsi, context->rnti, context->crcIndication);
    }

    freeUECtxManager(&manager);
    return 0;
}
```']

