#include <time.h>
#include <pthread.h>

// Assuming these are defined elsewhere in the project:
typedef struct {
    unsigned long timestamp;
    int RX_UE_INFORMATION_TAG;
} RX_UE_INFORMATION;

typedef struct {
    unsigned long RNTI;
} RNTI_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION rx_ue_info;
    RNTI_TAG rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes for logging
void log_message(int level, const char *message);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_crc_list(size_t N, int log_level) {
    if (N == 0) return NULL; // Invalid input handling

    size_t i;
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        log_message(log_level, "Memory allocation failed for list");
        return NULL; // Graceful degradation on memory failure
    }

    srand(time(NULL)); // Seed the random number generator

    pthread_mutex_lock(&mutex); // Ensure thread safety with a mutex lock

    for (i = 0; i < N; ++i) {
        list[i].rx_ue_info.timestamp = time(NULL); // Set unique timestamp
        list[i].rx_ue_info.RX_UE_INFORMATION_TAG = rand() % 1000; // Assign random RX tag
        list[i].rnti.RNTI = rand() % 100000; // Assign random RNTI

        // Randomly set CRCFLAG, e.g., between 0 and 1 for binary flag
        list[i].crc_tag.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&mutex); // Release the mutex lock

    log_message(log_level, "CRC indication PDU list created successfully");

    return list; // Return the pointer to the populated list
}

void log_message(int level, const char *message) {
    if (level > 0) { // Only log if level is positive
        printf("Log [%d]: %s\n", level, message);
    }
}

