typedef struct {
    unsigned int RNTI;
    char RX_UE_INFORMATION_TAG[32];
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 1024

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* buckets[MAX_RNTI];
    pthread_rwlock_t lock;
} CRCArrayManager;

CRCArrayManager* create_crc_array_manager() {
    CRCArrayManager* manager = (CRCArrayManager*)malloc(sizeof(CRCArrayManager));
    for (int i = 0; i < MAX_RNTI; ++i) {
        manager->buckets[i] = NULL;
    }
    pthread_rwlock_init(&manager->lock, NULL);
    return manager;
}

void destroy_crc_array_manager(CRCArrayManager* manager) {
    pthread_rwlock_wrlock(&manager->lock);
    for (int i = 0; i < MAX_RNTI; ++i) {
        Node* node = manager->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
    free(manager);
}

unsigned int hash_rnti(unsigned int rnti) {
    return rnti % MAX_RNTI;
}

void add_entry(CRCArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    unsigned int index = hash_rnti(entry.RNTI);

    pthread_rwlock_wrlock(&manager->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    memcpy(&new_node->data, &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = manager->buckets[index];
    manager->buckets[index] = new_node;
    pthread_rwlock_unlock(&manager->lock);
}

void remove_entry(CRCArrayManager* manager, unsigned int rnti) {
    unsigned int index = hash_rnti(rnti);

    pthread_rwlock_wrlock(&manager->lock);
    Node *prev = NULL, *node = manager->buckets[index];
    while (node && node->data.RNTI != rnti) {
        prev = node;
        node = node->next;
    }
    if (node) {
        if (prev) {
            prev->next = node->next;
        } else {
            manager->buckets[index] = node->next;
        }
        free(node);
    }
    pthread_rwlock_unlock(&manager->lock);
}

int get_total_entries(CRCArrayManager* manager) {
    int total = 0;

    pthread_rwlock_rdlock(&manager->lock);
    for (int i = 0; i < MAX_RNTI; ++i) {
        Node* node = manager->buckets[i];
        while (node) {
            total++;
            node = node->next;
        }
    }
    pthread_rwlock_unlock(&manager->lock);

    return total;
}

// Example usage
int main() {
    CRCArrayManager* manager = create_crc_array_manager();

    NFAPI_CRC_INDICATION_PDU_T entry1 = { .RNTI = 123, .CRC_INDICATION_REL8_TAG = {.CRCFLAG = rand() % 2} };
    add_entry(manager, entry1);

    printf("Total entries: %d\n", get_total_entries(manager));

    remove_entry(manager, 123);
    printf("Total entries after removal: %d\n", get_total_entries(manager));

    destroy_crc_array_manager(manager);
    return 0;
}
