#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16

typedef struct {
    int ue_id;
    int num_bearers;
    int *bearers; // List of active radio bearers
    int num_qos_flows;
    int *qos_flows; // Associated QoS flows
    double latency; // Network performance metric: latency in ms
    double throughput; // Network performance metric: throughput in Mbps
} UEContext;

typedef struct {
    UEContext **contexts;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock; // Read-write lock for concurrency control
} UECtxManager;

// Function to log context changes (stub for integration with existing logging framework)
void log_context_change(const char *message) {
    printf("%s\n", message); // Replace with actual logging mechanism
}

UECtxManager* create_ue_ctx_manager() {
    UECtxManager *manager = (UECtxManager *)malloc(sizeof(UECtxManager));
    manager->contexts = (UEContext **)calloc(INITIAL_CAPACITY, sizeof(UEContext *));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_rwlock_init(&manager->lock, NULL);
    return manager;
}

void resize_context_array(UECtxManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    UEContext **new_array = (UEContext **)realloc(manager->contexts, new_capacity * sizeof(UEContext *));

    if (!new_array) {
        perror("Failed to resize context array");
        exit(EXIT_FAILURE);
    }

    memset(new_array + manager->capacity, 0, manager->capacity * sizeof(UEContext *));
    manager->contexts = new_array;
    manager->capacity = new_capacity;
}

void add_ue_context(UECtxManager *manager, UEContext *context) {
    pthread_rwlock_wrlock(&manager->lock);

    // Check if context already exists
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == context->ue_id) {
            log_context_change("Updating existing UE context");
            free(manager->contexts[i]->bearers);
            free(manager->contexts[i]->qos_flows);

            manager->contexts[i]->num_bearers = context->num_bearers;
            manager->contexts[i]->bearers = (int *)malloc(context->num_bearers * sizeof(int));
            memcpy(manager->contexts[i]->bearers, context->bearers, context->num_bearers * sizeof(int));

            manager->contexts[i]->num_qos_flows = context->num_qos_flows;
            manager->contexts[i]->qos_flows = (int *)malloc(context->num_qos_flows * sizeof(int));
            memcpy(manager->contexts[i]->qos_flows, context->qos_flows, context->num_qos_flows * sizeof(int));

            manager->contexts[i]->latency = context->latency;
            manager->contexts[i]->throughput = context->throughput;

            pthread_rwlock_unlock(&manager->lock);
            return;
        }
    }

    // Add new context
    if (manager->count == manager->capacity) {
        resize_context_array(manager);
    }

    UEContext *new_context = (UEContext *)malloc(sizeof(UEContext));
    memcpy(new_context, context, sizeof(UEContext));

    manager->contexts[manager->count++] = new_context;
    log_context_change("Added new UE context");

    pthread_rwlock_unlock(&manager->lock);
}

void update_ue_context(UECtxManager *manager, int ue_id, double latency, double throughput) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            manager->contexts[i]->latency = latency;
            manager->contexts[i]->throughput = throughput;
            log_context_change("Updated UE context metrics");
            break;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
}

UEContext* get_ue_context(UECtxManager *manager, int ue_id) {
    pthread_rwlock_rdlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            UEContext *context_copy = (UEContext *)malloc(sizeof(UEContext));
            memcpy(context_copy, manager->contexts[i], sizeof(UEContext));
            pthread_rwlock_unlock(&manager->lock);
            return context_copy;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return NULL;
}

void free_ue_ctx_manager(UECtxManager *manager) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]->bearers);
        free(manager->contexts[i]->qos_flows);
        free(manager->contexts[i]);
    }

    free(manager->contexts);
    pthread_rwlock_unlock(&manager->lock);

    pthread_rwlock_destroy(&manager->lock);
    free(manager);
}
```

