FrameManager* create_frame_manager(size_t initial_capacity) {
    FrameManager *manager = (FrameManager*)malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = (NFAPI_RX_FRAME_PDU_T**)calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_PDU_T*));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_frame_manager(FrameManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]->raw_data);
        free(manager->frames[i]);
    }
    free(manager->frames);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_frame(FrameManager *manager, unsigned int ue_id, unsigned int rnti, size_t buffer_size) {
    if (buffer_size > MAX_BUFFER_SIZE || manager == NULL) return -1;

    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_RX_FRAME_PDU_T **new_frames = (NFAPI_RX_FRAME_PDU_T**)realloc(manager->frames, new_capacity * sizeof(NFAPI_RX_FRAME_PDU_T*));
        if (!new_frames) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    NFAPI_RX_FRAME_PDU_T *frame = (NFAPI_RX_FRAME_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!frame) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    frame->UE_ID = ue_id;
    frame->RNTI = rnti;
    frame->buffer_size = buffer_size;
    frame->raw_data = (uint8_t*)malloc(buffer_size);
    if (!frame->raw_data) {
        free(frame);
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    manager->frames[manager->count++] = frame;

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

void process_frame(FrameManager *manager, size_t index, void (*process_fn)(NFAPI_RX_FRAME_PDU_T*)) {
    if (index >= manager->count || manager == NULL) return;

    pthread_mutex_lock(&manager->mutex);

    NFAPI_RX_FRAME_PDU_T *frame = manager->frames[index];
    process_fn(frame);

    pthread_mutex_unlock(&manager->mutex);
}

void remove_frame(FrameManager *manager, size_t index) {
    if (index >= manager->count || manager == NULL) return;

    pthread_mutex_lock(&manager->mutex);

    free(manager->frames[index]->raw_data);
    free(manager->frames[index]);
    memmove(&manager->frames[index], &manager->frames[index + 1], (manager->count - index - 1) * sizeof(NFAPI_RX_FRAME_PDU_T*));
    manager->count--;

    pthread_mutex_unlock(&manager->mutex);
}

