```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_RNTI_VALUE 65535

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    atomic_int size;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    atomic_store(&list->size, 0);
    return list;
}

int generate_unique_rnti(pthread_mutex_t* lock, unsigned short* rntis, int size) {
    static unsigned short used_rntis[MAX_RNTI_VALUE + 1] = {0};
    pthread_mutex_lock(lock);

    for (unsigned short i = 0; i <= MAX_RNTI_VALUE; ++i) {
        if (!used_rntis[i]) {
            used_rntis[i] = 1;
            pthread_mutex_unlock(lock);
            *rntis = i;
            return 0;
        }
    }

    pthread_mutex_unlock(lock);
    return -1; // No available RNTI
}

int complex_crcflag_algorithm(unsigned short rnti, int position) {
    // Implement a non-deterministic algorithm for CRCFLAG
    return (rnti + position * 7) % 2;
}

void populate_list(CRCList* list, int N) {
    pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; ++i) {
        unsigned short rnti;
        if (generate_unique_rnti(&rnti_lock, &rnti, MAX_RNTI_VALUE + 1)) {
            fprintf(stderr, "Error: Unable to generate unique RNTI.\n");
            continue;
        }

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = {0};
        pdu.RX_UE_INFORMATION_TAG = i; // Example tag
        pdu.RNTI = rnti;
        pdu.crc_tag.CRCFLAG = complex_crcflag_algorithm(rnti, i);

        pthread_mutex_lock(&list->lock);
        new_node->data = pdu;
        new_node->next = list->head;
        list->head = new_node;
        atomic_fetch_add(&list->size, 1);
        pthread_mutex_unlock(&list->lock);
    }

    pthread_mutex_destroy(&rnti_lock);
}

void free_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void iterate_list(CRCList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void update_element(CRCList* list, int position, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (int i = 0; current && i < position; ++i) {
        current = current->next;
    }
    if (current) {
        current->data = new_data;
    }
    pthread_mutex_unlock(&list->lock);
}

void check_integrity(CRCList* list, int* error_count) {
    *error_count = 0;

    unsigned short rnti_tracker[MAX_RNTI_VALUE + 1] = {0};
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (rnti_tracker[current->data.RNTI]) {
            (*error_count)++;
        } else {
            rnti_tracker[current->data.RNTI] = 1;
        }

        // Example integrity check for CRCFLAG
        int crcflag = complex_crcflag_algorithm(current->data.RNTI, current->data.RX_UE_INFORMATION_TAG);
        if (current->data.crc_tag.CRCFLAG != crcflag) {
            (*error_count)++;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    if (*error_count > 0) {
        fprintf(stderr, "Integrity check failed with %d errors.\n", *error_count);
        // Implement recovery process
    } else {
        printf("Integrity check passed.\n");
    }
}

// Example callback function for iteration
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RNTI: %u, RX_UE_INFORMATION_TAG: %d, CRCFLAG: %d\n",
           pdu->RNTI, pdu->RX_UE_INFORMATION_TAG, pdu->crc_tag.CRCFLAG);
}

int main() {
    int N = 1000; // Example size
    CRCList* list = create_list();
    if (!list) return -1;

    populate_list(list, N);

    iterate_list(list, print_pdu);

    int error_count;
    check_integrity(list, &error_count);

    free_list(list);
    return 0;
}
