        if (current->message.id == id) {
            current->message.status_flag = status_flag;
            pthread_mutex_unlock(&arr->lock);
            return 0; // Updated
        }
        current = current->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Allocation failure
    }

    newNode->message.timestamp = time(NULL);
    newNode->message.id = id;
    newNode->message.status_flag = status_flag;
    newNode->next = arr->head;
    arr->head = newNode;

    pthread_mutex_unlock(&arr->lock);
    return 1; // Added
}

// Update existing message by ID
int updateMessageById(MessageArray* arr, unsigned int id, char new_status_flag) {
    return addMessage(arr, id, new_status_flag); // Reuse the add function
}

// Retrieve messages within a timestamp range
Node* getMessagesByTimestampRange(MessageArray* arr, time_t start, time_t end) {
    pthread_mutex_lock(&arr->lock);

    Node dummy = {0};
    dummy.next = arr->head;
    Node* current = &dummy;

    while (current != NULL && current->next != NULL) {
        if (current->next->message.timestamp >= start &&
            current->next->message.timestamp <= end) {

            Node* matching = current->next;
            current->next = matching->next;
            matching->next = dummy.next;
            dummy.next = matching;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return dummy.next; // Return the list of matching messages
}

// Create a list of NFAPI_CRC_INDICATION_PDU_T structures with random CRC flags
NFAPI_CRC_INDICATION_PDU_T* createNFAPI_CRC_List(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
