    for (size_t i = 0; i < count; ++i) {
        list[i].rx_ue_information_tag = rand() % 10000;
        list[i].rnti = rand() % 10000;
        list[i].crcflag = rand() & 1; // Random CRC flag
    }

    return list;
}

// Example usage
int main() {
    MessageArray arr;
    initializeMessageArray(&arr);

    addMessage(&arr, 1, '0');
    addMessage(&arr, 2, '1');

    Node* messages = getMessagesByTimestampRange(&arr, time(NULL) - 60, time(NULL));
    while (messages != NULL) {
