    CRCArray* array = (CRCArray*)malloc(sizeof(CRCArray));
    if (!array) return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

