    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void crc_array_destroy(CRCArray* array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->data);
        pthread_mutex_unlock(&array->lock);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int crc_array_add_or_update(CRCArray* array, int ue_id, const unsigned char* rnti) {
    if (!array || !rnti) return -1;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].ue_id == ue_id) {
            memcpy(array->data[i].rnti, rnti, sizeof(array->data[i].rnti));
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
