    array->data[array->size].ue_id = ue_id;
    memcpy(array->data[array->size].rnti, rnti, sizeof(array->data[array->size].rnti));
    ++array->size;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void crc_array_iterate(CRCArray* array, void (*callback)(int ue_id, const unsigned char* rnti)) {
    if (!array || !callback) return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        callback(array->data[i].ue_id, array->data[i].rnti);
    }

    pthread_mutex_unlock(&array->lock);
