typedef struct {
    NFAPI_L1_RX_BUFFER_PDU_T *buffer;
    size_t head;
    size_t tail;
    atomic_size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

CircularBuffer* create_buffer(size_t capacity) {
    if (capacity == 0 || capacity > MAX_BUFFER_SIZE) return NULL;

    CircularBuffer *cb = malloc(sizeof(CircularBuffer));
    cb->buffer = aligned_alloc(16, sizeof(NFAPI_L1_RX_BUFFER_PDU_T) * capacity); // Aligned for SIMD
    cb->head = cb->tail = 0;
    atomic_init(&cb->count, 0);
    pthread_mutex_init(&cb->lock, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);

    return cb;
}

void destroy_buffer(CircularBuffer *cb) {
    if (cb) {
        free(cb->buffer);
        pthread_mutex_destroy(&cb->lock);
        pthread_cond_destroy(&cb->not_full);
        pthread_cond_destroy(&cb->not_empty);
        free(cb);
    }
}

int buffer_write(CircularBuffer *cb, NFAPI_L1_RX_BUFFER_PDU_T data) {
    pthread_mutex_lock(&cb->lock);

    size_t next_head = (cb->head + 1) % MAX_BUFFER_SIZE;
    if (next_head == cb->tail) { // Buffer is full
        printf("Buffer overflow\n");
        pthread_mutex_unlock(&cb->lock);
        return -1;
    }

    cb->buffer[cb->head] = data;
    cb->head = next_head;
    atomic_fetch_add(&cb->count, 1);

    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->lock);

    return 0;
}

int buffer_read(CircularBuffer *cb, NFAPI_L1_RX_BUFFER_PDU_T *data) {
    pthread_mutex_lock(&cb->lock);

    while (cb->head == cb->tail) { // Buffer is empty
        pthread_cond_wait(&cb->not_empty, &cb->lock);
    }

    *data = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % MAX_BUFFER_SIZE;
    atomic_fetch_sub(&cb->count, 1);

    pthread_cond_signal(&cb->not_full);
    pthread_mutex_unlock(&cb->lock);

    return 0;
}

void process_bulk_data(CircularBuffer *cb) {
    size_t count = atomic_load(&cb->count);
    if (count == 0) return;

    // Determine how many elements we can process in a SIMD-friendly way
    size_t simd_chunk_size = count / sizeof(__m128i);
    NFAPI_L1_RX_BUFFER_PDU_T *buffer_ptr = cb->buffer + cb->tail;

    for (size_t i = 0; i < simd_chunk_size; ++i) {
