        buffer_ptr += sizeof(__m128i) / sizeof(NFAPI_L1_RX_BUFFER_PDU_T);
    }

    // Handle remaining elements not processed by SIMD
    size_t remaining = count % sizeof(__m128i);
    for (size_t i = 0; i < remaining; ++i) {
        NFAPI_L1_RX_BUFFER_PDU_T pdu = buffer_ptr[i];
        // Process each element individually
    }
}

// Example unit test function - implement further tests as needed
void test_circular_buffer() {
    CircularBuffer *cb = create_buffer(1024);

    NFAPI_L1_RX_BUFFER_PDU_T data[256];
    for (int i = 0; i < 256; ++i) {
