#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_ELEMENTS 1000000

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned long RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t last_access_time;
    atomic_int access_count;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
    size_t count;
} CRCList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    free(node);
}

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)calloc(1, sizeof(CRCList));
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free_node(temp);
    }
    pthread_rwlock_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.rx_ue_info_tag.RNTI = rand();
    pdu.crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    pdu.last_access_time = time(NULL);
    atomic_init(&pdu.access_count, 1);
    return pdu;
}

void add_element(CRCList* list) {
    pthread_rwlock_wrlock(&list->lock);

    if (list->count >= MAX_ELEMENTS) {
        printf("Max capacity reached. Evicting elements...\n");
        // Implement LRU + LFU eviction strategy here
    }

    Node* new_node = create_node(generate_random_pdu());
    if (!new_node) {
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    printf("Added element. Total count: %zu\n", list->count);

    pthread_rwlock_unlock(&list->lock);
}

void remove_element(CRCList* list) {
    pthread_rwlock_wrlock(&list->lock);

    if (!list->head) {
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    Node* temp = list->head;
    list->head = list->head->next;
    free_node(temp);
    list->count--;

    printf("Removed element. Total count: %zu\n", list->count);

    pthread_rwlock_unlock(&list->lock);
}

void access_element(CRCList* list) {
    pthread_rwlock_rdlock(&list->lock);

    if (!list->head) {
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* data = &current->data;
        time_t now = time(NULL);
        atomic_fetch_add(&data->access_count, 1);
        data->last_access_time = now;

        // Update LRU information
        current->next->last_access_time = now; 

        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

void log_operation(const char* operation) {
    time_t now = time(NULL);
    printf("[%s] Operation: %s, Timestamp: %ld\n", __func__, operation, now);
}

int main() {
    srand(time(NULL));
    CRCList* crc_list = create_crc_list();

    // Simulate operations
    add_element(crc_list);
    access_element(crc_list);
    remove_element(crc_list);

    destroy_crc_list(crc_list);
    return 0;
}
