    int RESULT_CODE;
} LTE_PHY_TEST_MESSAGE_T;

#define TEST_CASE_INDEX_MIN 0
#define TEST_CASE_INDEX_MAX 9999
#define RESULT_CODE_MIN 1
#define RESULT_CODE_MAX 10

// Simulated external test parameter service
int get_random_test_case_index() {
    return rand() % (TEST_CASE_INDEX_MAX - TEST_CASE_INDEX_MIN + 1) + TEST_CASE_INDEX_MIN;
}

int get_random_result_code() {
    return rand() % (RESULT_CODE_MAX - RESULT_CODE_MIN + 1) + RESULT_CODE_MIN;
