// Function to dynamically allocate memory for LTE_PHY_TEST_MESSAGE_T array
LTE_PHY_TEST_MESSAGE_T* allocate_lte_phy_test_messages(int config, int *allocated_count, FILE *log_file) {
    if (config < MIN_CONFIG || config > MAX_CONFIG) {
        config = DEFAULT_CONFIG;
    }

    LTE_PHY_TEST_MESSAGE_T *messages = NULL;
    int *used_ids = NULL;
    int attempts = 0;
    const int max_attempts = 3;

    while (attempts < max_attempts) {
        messages = realloc(messages, config * sizeof(LTE_PHY_TEST_MESSAGE_T));
        if (!messages && !attempts) {
            // Initial allocation attempt failed
            fprintf(log_file, "Initial memory allocation failed.\n");
            free(used_ids);
            return NULL;
        } else if (!messages) {
            // Subsequent attempts failed; log and exit
            fprintf(log_file, "Memory reallocation attempt %d failed. Exiting.\n", attempts + 1);
            break;
        }

        used_ids = realloc(used_ids, config * sizeof(int));
        memset(used_ids, 0, config * sizeof(int));

        int id_set[config];
        for (int i = 0; i < config; ++i) {
            id_set[i] = -1;
        }

        srand((unsigned)time(NULL));

        for (int i = 0; i < config; ++i) {
            LTE_PHY_TEST_MESSAGE_T *msg = &messages[i];

            do {
                msg->PHY_TEST_MESSAGE_ID = rand() % config;
            } while (used_ids[msg->PHY_TEST_MESSAGE_ID]);

            used_ids[msg->PHY_TEST_MESSAGE_ID] = 1;

            msg->TEST_CASE_INDEX = get_random_test_case_index();
            msg->RESULT_CODE = get_random_result_code();

            if (msg->TEST_CASE_INDEX < TEST_CASE_INDEX_MIN || msg->TEST_CASE_INDEX > TEST_CASE_INDEX_MAX ||
                msg->RESULT_CODE < RESULT_CODE_MIN || msg->RESULT_CODE > RESULT_CODE_MAX) {
                fprintf(log_file, "Invalid test parameters at index %d. Retrying...\n", i);
                attempts++;
                break;
            }
        }

        if (attempts == max_attempts - 1 && !id_set[i]) {
            // Last attempt did not complete successfully
            fprintf(log_file, "Final attempt failed.\n");
            free(messages);
            messages = NULL;
            break;
        }

        *allocated_count = config;  // All allocated successfully
        return messages;
    }

    if (messages) {
        free(messages);
    }
    if (used_ids) {
        free(used_ids);
    }
    *allocated_count = 0;
    fprintf(log_file, "Memory allocation failed after %d attempts.\n", max_attempts);

    return NULL;
}

int main() {
    int allocated_count;
    FILE *log_file = fopen("allocation_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    LTE_PHY_TEST_MESSAGE_T *messages = allocate_lte_phy_test_messages(100, &allocated_count, log_file);

    if (messages) {
        printf("Successfully allocated %d structures.\n", allocated_count);
        free(messages);
    } else {
        printf("Allocation failed. Check allocation_log.txt for details.\n");
    }

    fclose(log_file);
    return 0;
}
