#define INITIAL_SIZE 10
#define RNTI_MIN 0x0001
#define RNTI_MAX 0x3FFF

typedef struct {
    int ueId;
    uint16_t rnti;
    bool crcIndication;
} UEContext;

bool isValidRNTI(uint16_t rnti) {
    return rnti >= RNTI_MIN && rnti <= RNTI_MAX;
}

void logMessage(const char *message) {
    printf("%s\n", message);
}

UEContext* createUEContextArray(size_t initialSize, size_t *arraySize) {
    UEContext *ueContextArray = (UEContext *)malloc(initialSize * sizeof(UEContext));
    if (!ueContextArray) {
        logMessage("Memory allocation failed");
        return NULL;
    }
    *arraySize = initialSize;
    return ueContextArray;
}

bool resizeUEContextArray(UEContext **ueContextArray, size_t newSize, size_t *currentSize) {
    UEContext *newArray = (UEContext *)realloc(*ueContextArray, newSize * sizeof(UEContext));
    if (!newArray) {
        logMessage("Memory reallocation failed");
        return false;
    }
    memset(newArray + (*currentSize), 0, (newSize - *currentSize) * sizeof(UEContext));
    *ueContextArray = newArray;
    *currentSize = newSize;
    return true;
}

bool addUEContext(UEContext **ueContextArray, size_t *arraySize, size_t *count, int ueId, uint16_t rnti) {
    if (!isValidRNTI(rnti)) {
        logMessage("Invalid RNTI value");
        return false;
    }

    for (size_t i = 0; i < *count; ++i) {
        if ((*ueContextArray)[i].ueId == ueId) {
            char errorMsg[100];
            snprintf(errorMsg, sizeof(errorMsg), "Collision detected for UE ID: %d", ueId);
            logMessage(errorMsg);
            return false;
        }
    }

    if (*count >= *arraySize) {
        size_t newSize = *arraySize * 2;
        if (!resizeUEContextArray(ueContextArray, newSize, arraySize)) {
            return false;
        }
    }

    UEContext newContext = { ueId, rnti, rand() % 2 == 0 };
    (*ueContextArray)[*count] = newContext;
    (*count)++;
    return true;
}

UEContext* initializeUEContexts(size_t *contextCount) {
    srand(time(NULL));
    size_t arraySize = INITIAL_SIZE;
    UEContext *ueContextArray = createUEContextArray(arraySize, &arraySize);
    if (!ueContextArray) {
        return NULL;
    }

    for (size_t i = 0; i < 100; ++i) { // Example: trying to add 100 contexts
        int ueId = rand() % 10000 + 1;
        uint16_t rnti = RNTI_MIN + rand() % (RNTI_MAX - RNTI_MIN + 1);
        if (!addUEContext(&ueContextArray, &arraySize, contextCount, ueId, rnti)) {
            free(ueContextArray);
            return NULL;
        }
    }

    logMessage("Initialization complete");
    return ueContextArray;
}

void cleanupUEContexts(UEContext *ueContextArray) {
    if (ueContextArray) {
        free(ueContextArray);
    }
}
