#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1024
#define VALID_TAG_MIN 1000
#define VALID_TAG_MAX 9999
#define VALID_RNTI_MIN 1
#define VALID_RNTI_MAX 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t block_size;
    void *memory_start;
    pthread_mutex_t lock;
    size_t current_alloc;
    size_t max_alloc;
} MemoryPool;

MemoryPool memory_pool;

// Logging function
void log_error(const char *message, int error_code) {
    printf("ERROR [%d]: %s\n", error_code, message);
}

// Validate tag and RNTI
int validate_input(int tag, int rnti) {
    if (tag < VALID_TAG_MIN || tag > VALID_TAG_MAX ||
        rnti < VALID_RNTI_MIN || rnti > VALID_RNTI_MAX) {
        log_error("Invalid input parameters", 1001);
        return -1;
    }
    return 0;
}

// Initialize memory pool
int init_memory_pool(size_t block_size, size_t max_alloc) {
    pthread_mutex_init(&memory_pool.lock, NULL);
    memory_pool.block_size = block_size;
    memory_pool.max_alloc = max_alloc;
    memory_pool.current_alloc = 0;

    memory_pool.memory_start = malloc(block_size * max_alloc);
    if (!memory_pool.memory_start) {
        log_error("Failed to allocate memory for pool", 1002);
        return -1;
    }
    return 0;
}

// Allocate structure from the memory pool
NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    pthread_mutex_lock(&memory_pool.lock);

    if (memory_pool.current_alloc >= memory_pool.max_alloc) {
        log_error("Insufficient memory in pool", 1003);
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = 
        (NFAPI_CRC_INDICATION_PDU_T *)((char *)memory_pool.memory_start + 
                                       (memory_pool.current_alloc++ * memory_pool.block_size));

    pthread_mutex_unlock(&memory_pool.lock);

    // Randomly set CRCFLAG
    srand(time(NULL) ^ pthread_self());
    pdu->CRCFLAG = rand() % 256;
    return pdu;
}

// Free all allocated structures (reset the pool)
void free_all_structures() {
    memory_pool.current_alloc = 0;
}

// Batch process CRC indication reports
void batch_process_crc_reports(size_t count) {
    for (size_t i = 0; i < count; ++i) {
        int tag = VALID_TAG_MIN + rand() % (VALID_TAG_MAX - VALID_TAG_MIN + 1);
        int rnti = VALID_RNTI_MIN + rand() % (VALID_RNTI_MAX - VALID_RNTI_MIN + 1);

        if (validate_input(tag, rnti) != 0) continue;

        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_structure();
        if (!pdu) continue;

        pdu->RX_UE_INFORMATION_TAG = tag;
        pdu->RNTI = rnti;
        snprintf(pdu->CRC_INDICATION_REL8_TAG, sizeof(pdu->CRC_INDICATION_REL8_TAG), "Tag-%d", tag);
    }
}

int main() {
    if (init_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_STRUCTURES) != 0) return -1;

    // Example batch processing
    batch_process_crc_reports(100);

    free_all_structures();
    free(memory_pool.memory_start);
    pthread_mutex_destroy(&memory_pool.lock);

    return 0;
}
