#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    pthread_mutex_t lock;
} CrcIndicationList;

CrcIndicationList* create_crc_indication_list(size_t num_elements) {
    if (num_elements > MAX_ELEMENTS) {
        fprintf(stderr, "Requested number of elements exceeds maximum allowed.\n");
        return NULL;
    }

    CrcIndicationList* list = (CrcIndicationList*)malloc(sizeof(CrcIndicationList));
    if (!list) {
        perror("Failed to allocate memory for list structure");
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory for data array");
        free(list);
        pthread_mutex_destroy(&list->lock);
        return NULL;
    }

    list->count = 0;
    return list;
}

void set_crcflag(CrcIndicationList* list, int rx_ue_info_tag, int rnti, int crc_ind_rel8_tag, int crc_flag) {
    if (!list || pthread_mutex_lock(&list->lock)) {
        perror("Failed to lock the mutex");
        return;
    }

    if (list->count >= MAX_ELEMENTS) {
        fprintf(stderr, "List is full.\n");
    } else {
        list->data[list->count].RX_UE_INFORMATION_TAG = rx_ue_info_tag;
        list->data[list->count].RNTI = rnti;
        list->data[list->count].CRC_INDICATION_REL8_TAG = crc_ind_rel8_tag;
        list->data[list->count].CRCFLAG = crc_flag;
        list->count++;
