public class NFACreator {

    private static final Logger logger = Logger.getLogger(NFACreator.class.getName());
    private static final ReentrantLock lock = new ReentrantLock();

    public List<NFAPI_CRC_INDICATION_PDU_T> createNFAPackets(int N, int logLevel) {
        if (N <= 0) {
            logger.log(Level.SEVERE, "Invalid number of elements: N must be greater than zero.");
            return null;
        }

        List<NFAPI_CRC_INDICATION_PDU_T> list = new ArrayList<>();
        Random random = new Random();

        try {
            lock.lock();
            for (int i = 0; i < N; i++) {
                NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();

                // Simulating retrieval of RX_UE_INFORMATION_TAG
                RX_UE_INFORMATION_TAG tag = getRxUeInformationTag(i);
                if (tag == null) {
                    logger.log(Level.WARNING, "Invalid RX_UE_INFORMATION_TAG for index: " + i);
                    continue;
                }
                pdu.rxUeInformationTag = tag;

                // Assign a random RNTI
                pdu.rnti = random.nextInt(10000); // Example range

                // Set CRC flag randomly
                CRC_INDICATION_REL8_TAG crcTag = new CRC_INDICATION_REL8_TAG();
                crcTag.crcFlag = random.nextBoolean();
                pdu.crcIndicationRel8Tag = crcTag;

                // Assign a unique timestamp
                pdu.timestamp = System.currentTimeMillis();

                list.add(pdu);

                // Log debug information if necessary
                if (logLevel >= Level.FINE) {
                    logger.log(Level.FINE, "Created NFAPI_CRC_INDICATION_PDU_T with RNTI: " + pdu.rnti);
                }

                // Evaluate Pokemon type weaknesses
                evaluatePokemonTypeWeakness(tag.type);
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error creating NFAPackets", e);
        } finally {
            lock.unlock();
        }

        return list;
    }

    private RX_UE_INFORMATION_TAG getRxUeInformationTag(int index) {
        // Simulating a library function call
        if (index % 2 == 0) {
            return new RX_UE_INFORMATION_TAG() {{
                name = "Pokemon_" + index;
                type = index % 3 == 0 ? "Fire" : index % 3 == 1 ? "Water" : "Grass";
            }};
        }
        return null;
    }

    private void evaluatePokemonTypeWeakness(String type) {
        switch (type) {
            case "Fire":
                logger.log(Level.INFO, "Weak against: Water");
                break;
            case "Water":
                logger.log(Level.INFO, "Weak against: Electric");
                break;
            case "Grass":
                logger.log(Level.INFO, "Weak against: Fire");
                break;
            default:
                logger.log(Level.WARNING, "Unknown type: " + type);
        }
    }

    public static void main(String[] args) {
        NFACreator creator = new NFACreator();
        List<NFAPI_CRC_INDICATION_PDU_T> packets = creator.createNFAPackets(10, Level.FINE);
        if (packets != null) {
            System.out.println("Created " + packets.size() + " packets.");
        }
    }
}
