['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONFIGURATIONS 100
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct {
    int modulation_scheme;
    int bandwidth;
    unsigned long cell_identity;
    float power_control_settings;
    float reference_signal_power;
} LTE_PHY_Config;

typedef struct Node {
    LTE_PHY_Config config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} ConfigurationManager;

ConfigurationManager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void log_message(int level, const char* message) {
    if (level >= LOG_LEVEL_INFO) {
        printf("%s\n", message);
    }
}

int add_configuration(const LTE_PHY_Config* config) {
    pthread_mutex_lock(&manager.lock);

    Node** current = &manager.head;
    while (*current != NULL) {
        if ((*current)->config.cell_identity == config->cell_identity) {
            log_message(LOG_LEVEL_ERROR, "Duplicate cell identity detected.");
            pthread_mutex_unlock(&manager.lock);
            return -1; // Error: Duplicate entry
        }
        current = &(*current)->next;
    }

    if (manager.count >= MAX_CONFIGURATIONS) {
        log_message(LOG_LEVEL_ERROR, "Maximum configuration limit reached.");
        pthread_mutex_unlock(&manager.lock);
        return -2; // Error: Max configurations reached
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for new node.");
        pthread_mutex_unlock(&manager.lock);
        return -3; // Error: Memory allocation failure
    }

    memcpy(&new_node->config, config, sizeof(LTE_PHY_Config));
    new_node->next = NULL;
    *current = new_node;

    manager.count++;
    log_message(LOG_LEVEL_INFO, "Configuration added successfully.");

    pthread_mutex_unlock(&manager.lock);
    return 0; // Success
}

int update_configuration(unsigned long cell_identity, const LTE_PHY_Config* partial_config) {
    pthread_mutex_lock(&manager.lock);

    Node* current = manager.head;
    while (current != NULL) {
        if (current->config.cell_identity == cell_identity) {
            if (partial_config->modulation_scheme != -1)
                current->config.modulation_scheme = partial_config->modulation_scheme;
            if (partial_config->bandwidth != -1)
                current->config.bandwidth = partial_config->bandwidth;
            if (partial_config->power_control_settings != -1.0f)
                current->config.power_control_settings = partial_config->power_control_settings;
            if (partial_config->reference_signal_power != -1.0f)
                current->config.reference_signal_power = partial_config->reference_signal_power;

            log_message(LOG_LEVEL_INFO, "Configuration updated successfully.");
            pthread_mutex_unlock(&manager.lock);
            return 0; // Success
        }
        current = current->next;
    }

    log_message(LOG_LEVEL_ERROR, "Cell identity not found for update.");
    pthread_mutex_unlock(&manager.lock);
    return -1; // Error: Not found
}

size_t get_total_configurations() {
    pthread_mutex_lock(&manager.lock);
    size_t count = manager.count;
    pthread_mutex_unlock(&manager.lock);
    return count;
}

int serialize_to_file(const char* filename) {
    pthread_mutex_lock(&manager.lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message(LOG_LEVEL_ERROR, "Failed to open file for writing.");
        pthread_mutex_unlock(&manager.lock);
        return -1; // Error: File opening failed
    }

    Node* current = manager.head;
    while (current != NULL) {
        fwrite(&current->config, sizeof(LTE_PHY_Config), 1, file);
        current = current->next;
    }

    if (ferror(file)) {
        log_message(LOG_LEVEL_ERROR, "Error occurred during file write.");
        fclose(file);
        pthread_mutex_unlock(&manager.lock);
        return -2; // Error: Write error
    }

    fclose(file);
    log_message(LOG_LEVEL_INFO, "Configuration serialized successfully.");

    pthread_mutex_unlock(&manager.lock);
    return 0; // Success
}

int deserialize_from_file(const char* filename) {
    pthread_mutex_lock(&manager.lock);

    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_message(LOG_LEVEL_ERROR, "Failed to open file for reading.");
        pthread_mutex_unlock(&manager.lock);
        return -1; // Error: File opening failed
    }

    LTE_PHY_Config config;
    while (fread(&config, sizeof(LTE_PHY_Config), 1, file)) {
        if (add_configuration(&config) != 0) {
            log_message(LOG_LEVEL_ERROR, "Failed to add configuration from deserialization.");
            fclose(file);
            pthread_mutex_unlock(&manager.lock);
            return -2; // Error: Add failed
        }
    }

    if (ferror(file)) {
        log_message(LOG_LEVEL_ERROR, "Error occurred during file read.");
        fclose(file);
        pthread_mutex_unlock(&manager.lock);
        return -3; // Error: Read error
    }

    fclose(file);
    log_message(LOG_LEVEL_INFO, "Configuration deserialized successfully.");

    pthread_mutex_unlock(&manager.lock);
    return 0; // Success
}

void cleanup() {
    pthread_mutex_lock(&manager.lock);

    Node* current = manager.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    manager.count = 0;
    manager.head = NULL;

    log_message(LOG_LEVEL_INFO, "Configuration manager cleaned up.");

    pthread_mutex_unlock(&manager.lock);
}

int main() {
    // Example usage
    LTE_PHY_Config config1 = {1, 20, 12345, 10.5f, 15.0f};
    add_configuration(&config1);

    size_t total_configs = get_total_configurations();
    printf("Total Configurations: %zu\n", total_configs);

    serialize_to_file("config.dat");
    cleanup();

    deserialize_from_file("config.dat");
    cleanup();

    return 0;
}
```

