#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int msgId;
    char senderAddress[256];
    unsigned long sequenceNumber;
} TIDirectionalMessage;

typedef struct Node {
    TIDirectionalMessage message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
    int rangeMin;
    int rangeMax;
    int size;
} MessageList;

int validateMsgId(int msgId) {
    // Simulate external data source validation
    return 1; // Assume always valid for demonstration
}

unsigned long complexSequenceAlgorithm(int msgId, int position) {
    // Example of a non-deterministic sequence number generator
    return (msgId * 2654435761u + position) % 4294967296;
}

int generateUniqueMsgId(MessageList* list, int rangeMin, int rangeMax) {
    int newMsgId;
    do {
        newMsgId = rand() % (rangeMax - rangeMin + 1) + rangeMin;
    } while (!validateMsgId(newMsgId));

    pthread_rwlock_wrlock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->message.msgId == newMsgId) {
            pthread_rwlock_unlock(&list->lock);
            return 0; // Failed to generate a unique msgId
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);

    return newMsgId;
}

int populateMessageList(MessageList* list, int M, int rangeMin, int rangeMax) {
    if (M <= 0 || rangeMin >= rangeMax) {
        return -1; // Invalid parameters
    }

    for (int i = 0; i < M; ++i) {
        pthread_rwlock_wrlock(&list->lock);
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            pthread_rwlock_unlock(&list->lock);
            return -2; // Out of memory
        }

        int msgId = generateUniqueMsgId(list, rangeMin, rangeMax);
        if (msgId == 0) {
            free(newNode);
            pthread_rwlock_unlock(&list->lock);
            return -3; // Failed to generate unique msgId
        }

        newNode->message.msgId = msgId;
        strcpy(newNode->message.senderAddress, "trusted_sender");
        newNode->message.sequenceNumber = complexSequenceAlgorithm(msgId, list->size);

        newNode->next = list->head;
        list->head = newNode;
        list->size++;

        pthread_rwlock_unlock(&list->lock);
    }

    return 0; // Success
}

void freeMessageList(MessageList* list) {
    pthread_rwlock_wrlock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->size = 0;
    pthread_rwlock_unlock(&list->lock);
}

void iterateMessageList(MessageList* list, void (*callback)(TIDirectionalMessage*)) {
    pthread_rwlock_rdlock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        callback(&(current->message));
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);
}

void updateMessageById(MessageList* list, int targetMsgId, const char* newSenderAddress, unsigned long newSequenceNumber) {
    pthread_rwlock_wrlock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->message.msgId == targetMsgId) {
            strcpy(current->message.senderAddress, newSenderAddress);
            current->message.sequenceNumber = newSequenceNumber;
            break;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);
}

void checkListIntegrity(MessageList* list) {
    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->head;
    int seenMsgIds[1000000] = {0}; // Assuming max range is 1,000,000

    while (current != NULL) {
        if (seenMsgIds[current->message.msgId]) {
            fprintf(stderr, "Duplicate msgId detected: %d\n", current->message.msgId);
        }
        seenMsgIds[current->message.msgId] = 1;

        // Add logic to validate sequence number if needed

        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Example usage
void printMessage(TIDirectionalMessage* message) {
    printf("msgId: %d, senderAddress: %s, sequenceNumber: %lu\n", 
           message->msgId, message->senderAddress, message->sequenceNumber);
}

int main() {
    MessageList list = {NULL, PTHREAD_RWLOCK_INITIALIZER, 1, 1000000, 0};
    int M = 10;
    populateMessageList(&list, M, 1, 100);

    iterateMessageList(&list, printMessage);

    freeMessageList(&list);
    return 0;
}
