#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 10

typedef struct {
    uint8_t data[256]; // Example size for MACSDU element
} MACSDU;

typedef struct {
    uint16_t preamble;
    MACSDU* elements;
    size_t count;
    size_t capacity;
} MAC_PDU;

typedef struct {
    MAC_PDU* array;
    size_t size;
    pthread_mutex_t lock;
} MAC_PDU_Manager;

MAC_PDU* create_mac_pdu(uint16_t preamble) {
    MAC_PDU* pdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    if (!pdu) return NULL;

    pdu->preamble = preamble;
    pdu->count = 0;
    pdu->capacity = INITIAL_SIZE;
    pdu->elements = (MACSDU*)calloc(pdu->capacity, sizeof(MACSDU));

    return pdu;
}

void free_mac_pdu(MAC_PDU* pdu) {
    if (!pdu) return;
    free(pdu->elements);
    free(pdu);
}

int add_mac_sdu(MAC_PDU_Manager* manager, size_t index, MACSDU sdu) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->array[index].count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid index
    }

    if (manager->array[index].count == manager->array[index].capacity) {
        size_t new_capacity = manager->array[index].capacity * 2;
        MACSDU* new_elements = (MACSDU*)realloc(manager->array[index].elements, new_capacity * sizeof(MACSDU));
        if (!new_elements) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }
        manager->array[index].capacity = new_capacity;
        manager->array[index].elements = new_elements;
    }

    memmove(&manager->array[index].elements[index + 1], &manager->array[index].elements[index],
            (manager->array[index].count - index) * sizeof(MACSDU));
    manager->array[index].elements[index] = sdu;
    manager->array[index].count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_mac_sdu(MAC_PDU_Manager* manager, size_t index, size_t element_index, MACSDU new_sdu) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->size || element_index >= manager->array[index].count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid index
    }

    manager->array[index].elements[element_index] = new_sdu;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_mac_sdu(MAC_PDU_Manager* manager, size_t index, size_t element_index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->size || element_index >= manager->array[index].count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid index
    }

    memmove(&manager->array[index].elements[element_index], &manager->array[index].elements[element_index + 1],
            (manager->array[index].count - element_index - 1) * sizeof(MACSDU));
    manager->array[index].count--;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

MAC_PDU_Manager* create_manager(size_t initial_size) {
    MAC_PDU_Manager* manager = (MAC_PDU_Manager*)malloc(sizeof(MAC_PDU_Manager));
    if (!manager) return NULL;

    manager->array = (MAC_PDU**)calloc(initial_size, sizeof(MAC_PDU*));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        manager->array[i] = create_mac_pdu(0); // Default preamble
    }
    manager->size = initial_size;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void free_manager(MAC_PDU_Manager* manager) {
    if (!manager) return;
    for (size_t i = 0; i < manager->size; ++i) {
        free_mac_pdu(manager->array[i]);
    }
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int serialize_manager(MAC_PDU_Manager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->size; ++i) {
        fwrite(&manager->array[i]->preamble, sizeof(uint16_t), 1, file);
        uint32_t count = htonl(manager->array[i]->count);
        fwrite(&count, sizeof(uint32_t), 1, file);
        fwrite(manager->array[i]->elements, sizeof(MACSDU), manager->array[i]->count, file);
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
    return 0;
}

int deserialize_manager(MAC_PDU_Manager* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    free_manager(manager);
    *manager = *(create_manager(new_size));

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        fread(&manager->array[i]->preamble, sizeof(uint16_t), 1, file);
        uint32_t count;
        fread(&count, sizeof(uint32_t), 1, file);
        count = ntohl(count);

        if (count > manager->array[i]->capacity) {
            MACSDU* new_elements = (MACSDU*)realloc(manager->array[i]->elements, count * sizeof(MACSDU));
            if (!new_elements) {
                pthread_mutex_unlock(&manager->lock);
                fclose(file);
                return -1;
            }
            manager->array[i]->capacity = count;
            manager->array[i]->elements = new_elements;
        }

        fread(manager->array[i]->elements, sizeof(MACSDU), count, file);
        manager->array[i]->count = count;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
    return 0;
}
