// Define the structures
typedef struct {
    int cell_id;
    // Add other CELL_UPINFO_T fields as necessary
} CELL_UPINFO_T;

typedef struct {
    char ENB_ID[64];
    CELL_UPINFO_T* cells;
    size_t cell_count;
} LTE_ENB_RRC_RECONFIGURATION_REQUEST_T;

// Dynamic list management structure
typedef struct {
    LTE_ENB_RRC_RECONFIGURATION_REQUEST_T** requests;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    size_t max_size;
} DynamicList;

// Function to initialize the dynamic list
void init_dynamic_list(DynamicList* dl, size_t initial_capacity) {
    dl->requests = (LTE_ENB_RRC_RECONFIGURATION_REQUEST_T**)malloc(initial_capacity * sizeof(LTE_ENB_RRC_RECONFIGURATION_REQUEST_T*));
    dl->count = 0;
    dl->capacity = initial_capacity;
    pthread_mutex_init(&dl->lock, NULL);
    dl->max_size = initial_capacity; // Initial max size
}

// Function to update the maximum list size from an external configuration service
void update_max_size(DynamicList* dl, size_t new_max_size) {
    pthread_mutex_lock(&dl->lock);
    dl->max_size = new_max_size;

    if (dl->count > dl->max_size) {
        // Remove excess elements if count exceeds the new max size
        size_t excess_count = dl->count - dl->max_size;
        for (size_t i = 0; i < excess_count; ++i) {
            free(dl->requests[i]->cells);
            free(dl->requests[i]);
        }
        memmove(dl->requests, &dl->requests[excess_count], (dl->count - excess_count) * sizeof(LTE_ENB_RRC_RECONFIGURATION_REQUEST_T*));
        dl->count -= excess_count;
    }

    pthread_mutex_unlock(&dl->lock);
}

// Function to add a new configuration
int add_configuration(DynamicList* dl, LTE_ENB_RRC_RECONFIGURATION_REQUEST_T* request) {
    pthread_mutex_lock(&dl->lock);

    if (dl->count >= dl->max_size) {
        // Resize the list if necessary
        size_t new_capacity = dl->capacity * 2;
        dl->requests = (LTE_ENB_RRC_RECONFIGURATION_REQUEST_T**)realloc(dl->requests, new_capacity * sizeof(LTE_ENB_RRC_RECONFIGURATION_REQUEST_T*));
        dl->capacity = new_capacity;
    }

    if (dl->count < dl->max_size) {
        dl->requests[dl->count++] = request;
        pthread_mutex_unlock(&dl->lock);
        return 0; // Success
    } else {
        pthread_mutex_unlock(&dl->lock);
        return -1; // Failed to add due to size constraints
    }
}

// Function to remove a configuration by ENB_ID
int remove_configuration(DynamicList* dl, const char* enb_id) {
    pthread_mutex_lock(&dl->lock);

    for (size_t i = 0; i < dl->count; ++i) {
        if (strcmp(dl->requests[i]->ENB_ID, enb_id) == 0) {
            free(dl->requests[i]->cells);
            free(dl->requests[i]);

            // Shift the remaining elements
            memmove(&dl->requests[i], &dl->requests[i + 1], (dl->count - i - 1) * sizeof(LTE_ENB_RRC_RECONFIGURATION_REQUEST_T*));
            dl->count--;
            pthread_mutex_unlock(&dl->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&dl->lock);
    return -1; // ENB_ID not found
}

// Function to free the dynamic list resources
void free_dynamic_list(DynamicList* dl) {
    pthread_mutex_lock(&dl->lock);

    for (size_t i = 0; i < dl->count; ++i) {
        free(dl->requests[i]->cells);
        free(dl->requests[i]);
    }
    free(dl->requests);

    pthread_mutex_unlock(&dl->lock);
    pthread_mutex_destroy(&dl->lock);
}

// Example usage
int main() {
    DynamicList dl;
    init_dynamic_list(&dl, 10);

    // Simulate external update to max size
    update_max_size(&dl, 15);

    LTE_ENB_RRC_RECONFIGURATION_REQUEST_T* request = malloc(sizeof(LTE_ENB_RRC_RECONFIGURATION_REQUEST_T));
    strcpy(request->ENB_ID, "ENB_001");
    request->cells = malloc(5 * sizeof(CELL_UPINFO_T)); // Example cell info allocation
    request->cell_count = 5;

    add_configuration(&dl, request);

    remove_configuration(&dl, "ENB_001");

    free_dynamic_list(&dl);
    return 0;
}
