#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST;

NFAPI_CRC_LIST* create_crc_list() {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;

    list->elements = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int allocate_memory_for_list(NFAPI_CRC_LIST* list, size_t new_count) {
    NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) return 0;

    for (size_t i = list->count; i < new_count; ++i) {
        new_elements[i].RX_UE_INFORMATION_TAG = rand(); // Simulate valid data
        new_elements[i].RNTI = rand();
        new_elements[i].CRC_INDICATION_REL8_TAG = rand();

        // Set CRCFLAG based on a probabilistic function
        new_elements[i].CRCFLAG = (rand() % 100) < 30; // Example: 30% chance to set CRCFLAG
    }

    list->elements = new_elements;
    return 1;
}

int add_element(NFAPI_CRC_LIST* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Error: Maximum list size reached.\n");
        return -1;
    }

    if (!allocate_memory_for_list(list, list->count + 1)) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    list->elements[list->count] = element;
    ++list->count;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void clear_list(NFAPI_CRC_LIST* list) {
    pthread_mutex_lock(&list->lock);

    free(list->elements);
    list->elements = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_crc_list(NFAPI_CRC_LIST* list) {
    if (!list) return;

    clear_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
