    size_t capacity;
    pthread_mutex_t lock;
} StructurePool;

StructurePool pool = { .structures = NULL, .capacity = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

// External logging function
void log_error(const char* message) {
    printf("ERROR: %s\n", message);
}

bool initialize_pool(size_t capacity) {
    pthread_mutex_lock(&pool.lock);

    if (capacity > MAX_STRUCTURES || pool.capacity >= capacity) {
        pthread_mutex_unlock(&pool.lock);
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_structures = realloc(pool.structures, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_structures) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&pool.lock);
        return false;
    }

    pool.structures = new_structures;
    pool.capacity = capacity;

    for (size_t i = 0; i < capacity; ++i) {
        pool.structures[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        pool.structures[i].RNTI = -1; // Mark as unused
        pool.structures[i].CRC_INDICATION_REL8_TAG = rand() % 1000 + 1;
    }

    pthread_mutex_unlock(&pool.lock);
    return true;
}

bool populate_structures(size_t N) {
    if (N > MAX_STRUCTURES) {
        log_error("Requested number of structures exceeds system limitations");
        return false;
    }

    if (!initialize_pool(N)) {
        return false;
    }

    bool used_rntis[MAX_STRUCTURES] = { false };
    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&pool.lock);

        int rnti;
        do {
            rnti = rand() % 1024 + 1;
        } while (used_rntis[rnti - 1]);

        used_rntis[rnti - 1] = true;

        pool.structures[i].RNTI = rnti;
        pool.structures[i].CRCFLAG = i % 2 == 0;

        pthread_mutex_unlock(&pool.lock);
    }

    return true;
}

void free_pool() {
    pthread_mutex_lock(&pool.lock);

    if (pool.structures) {
        free(pool.structures);
        pool.structures = NULL;
    }
    pool.capacity = 0;

    pthread_mutex_unlock(&pool.lock);
}

int main() {
    size_t N = 100; // Example input
    if (!populate_structures(N)) {
        log_error("Failed to populate structures");
        return EXIT_FAILURE;
    }

    // Further operations...

    free_pool();
    return EXIT_SUCCESS;
}
