#define MAX_ELEMENTS 5000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t max_size;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_max_size) {
    if (initial_max_size > MAX_ELEMENTS)
        return NULL;

    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list)
        return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->max_size = initial_max_size;

    return list;
}

void free_dynamic_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_sorted_unique(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->count >= list->max_size)
        return -1; // List is full

    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current && (*current)->data.RNTI < element.RNTI) {
        current = &((*current)->next);
    }

    if (*current && (*current)->data.RNTI == element.RNTI) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Duplicate RNTI
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    new_node->data = element;
    new_node->next = *current;

    *current = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void update_list_from_external_source(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* external_data, size_t data_count) {
    for (size_t i = 0; i < data_count; ++i) {
        if (insert_sorted_unique(list, external_data[i]) != 0) {
            // Handle error: log or take appropriate action
        }
    }
}

void adjust_max_size(DynamicList* list, size_t new_max_size) {
    if (new_max_size > MAX_ELEMENTS)
        return;

    pthread_mutex_lock(&list->lock);
    list->max_size = new_max_size;
    pthread_mutex_unlock(&list->lock);
}
