int init_config_manager(ConfigManager *manager) {
    if (!manager) return -1;

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->configs = malloc(manager->capacity * sizeof(PhyConfig));
    if (!manager->configs) return -2;
    pthread_mutex_init(&manager->lock, NULL);

    return 0;
}

int add_or_update_config(ConfigManager *manager, PhyConfig new_config) {
    if (!manager || !new_config.modulation_scheme) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i].cell_identity == new_config.cell_identity) {
            memcpy(&(manager->configs[i]), &new_config, sizeof(PhyConfig));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        PhyConfig *new_configs = realloc(manager->configs, new_capacity * sizeof(PhyConfig));
        if (!new_configs) {
            pthread_mutex_unlock(&manager->lock);
            return -3;
        }
        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }

    memcpy(&(manager->configs[manager->count]), &new_config, sizeof(PhyConfig));
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

size_t get_total_configs(const ConfigManager *manager) {
    if (!manager) return (size_t)-1;

    size_t total = 0;
    pthread_mutex_lock(&(manager->lock));
    total = manager->count;
    pthread_mutex_unlock(&(manager->lock));

    return total;
}

void free_config_manager(ConfigManager *manager) {
