    if (!*event) return -2;

    (*event)->timestamp = strdup(timestamp);
    if (!(*event)->timestamp) {
        free(*event);
        return -3;
    }

    (*event)->event_type = type;
    (*event)->source_id = source_id;
    (*event)->payload_size = payload_size;

    if (payload_size > 0) {
        (*event)->payload = malloc(payload_size);
        if (!(*event)->payload) {
            free((*event)->timestamp);
            free(*event);
            return -4;
