    ea->events = (NetworkEvent**)malloc(initial_capacity * sizeof(NetworkEvent*));
    if (!ea->events) {
        free(ea);
        log_failure("Failed to allocate memory for event array");
        return NULL;
    }
    ea->capacity = initial_capacity;
    ea->count = 0;

    pthread_mutex_init(&ea->lock, NULL);

    return ea;
}

void destroy_event_array(EventArray *ea) {
    if (!ea) return;

    pthread_mutex_lock(&ea->lock);
    for (size_t i = 0; i < ea->count; ++i) {
        free(ea->events[i]->payload);
        free(ea->events[i]);
    }
    free(ea->events);

    pthread_mutex_unlock(&ea->lock);
    pthread_mutex_destroy(&ea->lock);

    free(ea);
    log_success("Event array cleared and destroyed");
}

int add_event(EventArray *ea, NetworkEvent *event) {
    if (!ea || !event) return -1;

    pthread_mutex_lock(&ea->lock);

    // Resize if necessary
    if (ea->count == ea->capacity) {
        size_t new_capacity = ea->capacity * 2;
        NetworkEvent **new_events = realloc(ea->events, new_capacity * sizeof(NetworkEvent*));

        if (!new_events) {
            pthread_mutex_unlock(&ea->lock);
            log_failure("Failed to resize event array");
            return -1;
        }

        ea->events = new_events;
        ea->capacity = new_capacity;
    }

    ea->events[ea->count++] = event;

    pthread_mutex_unlock(&ea->lock);

    log_success("Event added successfully");
    return 0;
}

NetworkEvent* get_event_by_timestamp(EventArray *ea, time_t timestamp) {
    if (!ea) return NULL;

    pthread_mutex_lock(&ea->lock);

    for (size_t i = 0; i < ea->count; ++i) {
        if (ea->events[i]->timestamp == timestamp) {
            NetworkEvent *event_copy = malloc(sizeof(NetworkEvent));
            if (!event_copy) {
                pthread_mutex_unlock(&ea->lock);
                log_failure("Failed to allocate memory for event copy");
                return NULL;
            }

            memcpy(event_copy, ea->events[i], sizeof(NetworkEvent));
            event_copy->payload = strdup(ea->events[i]->payload);

            pthread_mutex_unlock(&ea->lock);

            if (!event_copy->payload) {
                free(event_copy);
                log_failure("Failed to duplicate payload");
                return NULL;
            }

            log_success("Event retrieved by timestamp");
            return event_copy;
        }
    }

    pthread_mutex_unlock(&ea->lock);
    log_failure("Event not found for given timestamp");
    return NULL;
}

// Optional: Implement performance monitoring functions here
