#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    int PORT_NUMBER;
    long SYN_TIMESTAMP;
} TCP_CONNECTION_INFO;

typedef struct {
    TCP_CONNECTION_INFO *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *da) {
    da->size = 0;
    da->capacity = 10; // Initial capacity
    da->array = (TCP_CONNECTION_INFO *)malloc(da->capacity * sizeof(TCP_CONNECTION_INFO));
    pthread_mutex_init(&da->lock, NULL);
}

void freeDynamicArray(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

void resizeIfNeeded(DynamicArray *da) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        TCP_CONNECTION_INFO *new_array = (TCP_CONNECTION_INFO *)realloc(da->array, new_capacity * sizeof(TCP_CONNECTION_INFO));
        if (new_array != NULL) {
            da->array = new_array;
            da->capacity = new_capacity;
        }
    }
}

void addConnection(DynamicArray *da, TCP_CONNECTION_INFO info) {
    pthread_mutex_lock(&da->lock);

    // Simulate external service validation
    // Ensure SOURCE_IP and DESTINATION_IP are valid before adding
    // If temporary failure occurs, skip this addition for now

    resizeIfNeeded(da);
    da->array[da->size] = info;
    da->size++;

    pthread_mutex_unlock(&da->lock);
}

int removeConnectionByIP(DynamicArray *da, const char *source_ip, const char *dest_ip) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (strcmp(da->array[i].SOURCE_IP, source_ip) == 0 &&
            strcmp(da->array[i].DESTINATION_IP, dest_ip) == 0) {

            memmove(&da->array[i], &da->array[i + 1], 
                    (da->size - i - 1) * sizeof(TCP_CONNECTION_INFO));
            da->size--;
            pthread_mutex_unlock(&da->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return 0;
}

int removeConnectionByPort(DynamicArray *da, int port_number) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].PORT_NUMBER == port_number) {

            memmove(&da->array[i], &da->array[i + 1], 
                    (da->size - i - 1) * sizeof(TCP_CONNECTION_INFO));
            da->size--;
            pthread_mutex_unlock(&da->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return 0;
}

void iterateAndOperate(DynamicArray *da, void (*operation)(TCP_CONNECTION_INFO *)) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        operation(&da->array[i]);
    }

    pthread_mutex_unlock(&da->lock);
}

void exampleOperation(TCP_CONNECTION_INFO *info) {
    // Placeholder for specific operations on TCP_CONNECTION_INFO
    printf("Processing connection: %s:%d -> %s\n",
           info->SOURCE_IP, info->PORT_NUMBER,
           info->DESTINATION_IP);
}
