#include <pthread.h>

#define MAX_UES 1000
#define MAX_MAC_ENTITIES_PER_UE 10

typedef struct MACEntity {
    int mac_id;
    // Other MAC specific data...
} MACEntity;

typedef struct RRCState {
    char* state_name; // e.g., "RRC_IDLE", "RRC_CONNECTED"
    // Additional RRC state-specific data...
} RRCState;

typedef struct UEContext {
    int ue_id;
    RRCState* rrc_states[5]; // Support for multiple RRC states
    MACEntity* mac_entities[MAX_MAC_ENTITIES_PER_UE];
    size_t mac_count;
    pthread_mutex_t lock; // For thread-safe access to the UE context
} UEContext;

typedef struct DynamicPool {
    UEContext* ue_contexts[MAX_UES];
    size_t count;
    pthread_mutex_t pool_lock; // Protect the dynamic pool structure
} DynamicPool;

DynamicPool* init_ue_pool() {
    DynamicPool* pool = (DynamicPool*)malloc(sizeof(DynamicPool));
    if (!pool) return NULL;

    pool->count = 0;
    pthread_mutex_init(&pool->pool_lock, NULL);

    for (int i = 0; i < MAX_UES; ++i) {
        pool->ue_contexts[i] = NULL;
    }

    printf("Dynamic UE context pool initialized.\n");
    return pool;
}

void add_ue_context(DynamicPool* pool, int ue_id) {
    pthread_mutex_lock(&pool->pool_lock);

    if (pool->count >= MAX_UES) {
        fprintf(stderr, "Max UE limit reached. Cannot add more UEs.\n");
        pthread_mutex_unlock(&pool->pool_lock);
        return;
    }

    UEContext* context = (UEContext*)malloc(sizeof(UEContext));
    if (!context) {
        fprintf(stderr, "Memory allocation failed for UE Context.\n");
        pthread_mutex_unlock(&pool->pool_lock);
        return;
    }

    context->ue_id = ue_id;
    context->mac_count = 0;

    // Initialize mutex for each UE context
    pthread_mutex_init(&context->lock, NULL);

    for (int i = 0; i < 5; ++i) {
        context->rrc_states[i] = (RRCState*)malloc(sizeof(RRCState));
        context->rrc_states[i]->state_name = "Unknown";
    }

    pool->ue_contexts[pool->count++] = context;
    printf("UE Context %d added to the pool.\n", ue_id);

    pthread_mutex_unlock(&pool->pool_lock);
}

void add_mac_entity(UEContext* context, int mac_id) {
    if (!context) return;

    pthread_mutex_lock(&context->lock);

    if (context->mac_count >= MAX_MAC_ENTITIES_PER_UE) {
        fprintf(stderr, "Max MAC entities limit reached for UE %d.\n", context->ue_id);
        pthread_mutex_unlock(&context->lock);
        return;
    }

    context->mac_entities[context->mac_count] = (MACEntity*)malloc(sizeof(MACEntity));
    if (!context->mac_entities[context->mac_count]) {
        fprintf(stderr, "Memory allocation failed for MAC Entity.\n");
        pthread_mutex_unlock(&context->lock);
        return;
    }

    context->mac_entities[context->mac_count]->mac_id = mac_id;
    context->mac_count++;
    printf("MAC entity with ID %d added to UE %d.\n", mac_id, context->ue_id);

    pthread_mutex_unlock(&context->lock);
}

void cleanup_pool(DynamicPool* pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->count; ++i) {
        UEContext* context = pool->ue_contexts[i];
        if (!context) continue;

        pthread_mutex_lock(&context->lock);

        for (int j = 0; j < 5; ++j) {
            free(context->rrc_states[j]);
        }

        for (size_t k = 0; k < context->mac_count; ++k) {
            free(context->mac_entities[k]);
        }

        pthread_mutex_unlock(&context->lock);
        pthread_mutex_destroy(&context->lock);

        free(context);
    }

    pthread_mutex_destroy(&pool->pool_lock);
    free(pool);
    printf("Dynamic UE context pool cleaned up.\n");
}

// Simulated function to handle unexpected spike in UE connections
void handle_ue_spike(DynamicPool* pool, int additional_ues) {
    for (int i = 0; i < additional_ues; ++i) {
        add_ue_context(pool, pool->count + i); // simplistic way to assign new IDs
    }
}

// Main function demonstrating usage
int main() {
    DynamicPool* pool = init_ue_pool();

    add_ue_context(pool, 1);
    UEContext* ue = pool->ue_contexts[0];
    add_mac_entity(ue, 1001);

    handle_ue_spike(pool, 5); // Example of handling a spike in connections

    cleanup_pool(pool);
    return 0;
}
