// Memory pool structure
typedef struct {
    size_t blockSize;
    void *freeList;
    pthread_mutex_t mutex;
} MemoryPool;

// Function to initialize memory pool
int initMemoryPool(MemoryPool *pool, size_t blockSize, size_t initialBlocks) {
    pool->blockSize = blockSize;
    pool->mutex = (pthread_mutex_t){0};

    char *base = malloc(blockSize * initialBlocks);
    if (!base) return -1;

    for (size_t i = 0; i < initialBlocks; ++i) {
        void *nextBlock = base + i * blockSize;
        ((char **)nextBlock)[0] = (i == initialBlocks - 1) ? NULL : nextBlock + blockSize;
    }

    pool->freeList = base;
    return 0;
}

// Function to allocate from memory pool
void* poolAllocate(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);

    if (!pool->freeList) {
        // Double the pool size if empty
        size_t currentSize = (char *)pool->freeList - (char *)pool;
        char *newBase = realloc(pool, currentSize + 2 * pool->blockSize);
        if (!newBase) {
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        pool = (MemoryPool *)newBase;

        for (size_t i = currentSize / pool->blockSize; i < 2 * (currentSize / pool->blockSize); ++i) {
            void *nextBlock = newBase + i * pool->blockSize;
            ((char **)nextBlock)[0] = (i == 2 * (currentSize / pool->blockSize) - 1) ? NULL : nextBlock + pool->blockSize;
        }

        pool->freeList = newBase + currentSize;
    }

    void *allocatedBlock = pool->freeList;
    pool->freeList = *(void **)allocatedBlock;

    pthread_mutex_unlock(&pool->mutex);
    return allocatedBlock;
}

// Function to deallocate from memory pool (no-op for simplicity)
void poolDeallocate(MemoryPool *pool, void *block) {
    // Typically you would add this block back to the free list
}

// Logging mechanism
