    time_t now = time(NULL);
    printf("Thread %d: Created NFAPI_CRC_INDICATION_PDU_T at index %d on %s", threadId,
           structureIndex, ctime(&now));
}

// Main function to initialize and populate the list
NFAPI_CRC_INDICATION_PDU_T* initializeNFapiCRCIndicationList(size_t N, size_t M, int bufferSize, unsigned int seed) {
    if (N > M) {
        fprintf(stderr, "Requested number of structures exceeds maximum allowed.\n");
        return NULL;
    }

    MemoryPool pool;
    if (initMemoryPool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T), M * 10) != 0) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list.\n");
        return NULL;
