    srand(seed);

    pthread_t currentThread;
    int threadId = (int)pthread_self();

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *structure = poolAllocate(&pool);
        if (!structure) {
            fprintf(stderr, "Memory allocation failed from pool.\n");
            free(list);
            return NULL;
        }

        structure->crcTag.RX_UE_INFORMATION_TAG = rand() % bufferSize;
        structure->crcTag.RNTI = rand() % bufferSize;
        structure->crcTag.CRCFLAG = rand() % 2;

        list[i] = *structure;
        logCreation(threadId, i);
    }

    return list;
}

// Usage
