        if (rnti >= M) { // Ensure RNTI is within bounds
            log_message("Generated RNTI exceeds maximum allowed structures");
            free(nfa_list);
            pthread_rwlock_unlock(&list_lock);
            return NULL;
        }

        rnti_set[rnti] = true;

        // Populate structure
        nfa_list[count].RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        nfa_list[count].RNTI = rnti;
        nfa_list[count].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        log_message("Created structure with RNTI: ");
        printf("%d\n", nfa_list[count].RNTI);

        count++;
    }

    pthread_rwlock_unlock(&list_lock);
    return nfa_list;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T* nfa_list) {
    if (nfa_list) {
        pthread_rwlock_wrlock(&list_lock);

        free(nfa_list);
        log_message("Freed NFA list");

        pthread_rwlock_unlock(&list_lock);
    }
}

// Example logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int main() {
    int N = 10000; // Example number of structures
    int M = 100000; // Maximum allowed structures

    NFAPI_CRC_INDICATION_PDU_T* nfa_list = create_nfa_list(N, M);
    if (nfa_list) {
        free_nfa_list(nfa_list);
    }

    return 0;
}
