// Add a new event
void addEvent(EventArray *ea, time_t timestamp, const char *eventType, const unsigned char *payload, size_t payloadSize) {
    pthread_mutex_lock(&ea->lock);

    if (ea->count == ea->capacity) {
        ea->capacity *= 2;
        ea->events = realloc(ea->events, ea->capacity * sizeof(NetworkEvent *));
        if (!ea->events) exit(EXIT_FAILURE);
    }

    NetworkEvent *event = malloc(sizeof(NetworkEvent));
    if (!event) {
        pthread_mutex_unlock(&ea->lock);
        exit(EXIT_FAILURE);
    }

    event->timestamp = timestamp;
    strncpy(event->eventType, eventType, sizeof(event->eventType));
    event->payloadSize = payloadSize;
    event->payload = malloc(payloadSize);
    if (!event->payload) {
        free(event);
        pthread_mutex_unlock(&ea->lock);
        exit(EXIT_FAILURE);
    }

    memcpy(event->payload, payload, payloadSize);

    ea->events[ea->count++] = event;

    pthread_mutex_unlock(&ea->lock);
}

// Retrieve events by timestamp
NetworkEvent **getEventsByTimestamp(EventArray *ea, time_t timestamp) {
    pthread_mutex_lock(&ea->lock);

    size_t matchingCount = 0;
    for (size_t i = 0; i < ea->count; ++i) {
        if (ea->events[i]->timestamp == timestamp) {
            matchingCount++;
        }
    }

    NetworkEvent **results = malloc(matchingCount * sizeof(NetworkEvent *));
    if (!results) {
        pthread_mutex_unlock(&ea->lock);
        return NULL;
    }

    size_t index = 0;
    for (size_t i = 0; i < ea->count; ++i) {
        if (ea->events[i]->timestamp == timestamp) {
            results[index++] = ea->events[i];
        }
    }

    pthread_mutex_unlock(&ea->lock);
    return results;
}

// Clear the event array
void clearEventArray(EventArray *ea) {
    pthread_mutex_lock(&ea->lock);

    for (size_t i = 0; i < ea->count; ++i) {
        free(ea->events[i]->payload);
        free(ea->events[i]);
    }

    free(ea->events);
    ea->events = NULL;
    ea->capacity = 0;
    ea->count = 0;

    pthread_mutex_unlock(&ea->lock);
}

