int populate_nfa_list(NFAPI_CRC_INDICATION_PDU_T **nfa_list, size_t N, size_t MAX_UNIQUE_RNTI) {
    if (nfa_list == NULL || N <= 0 || MAX_UNIQUE_RNTI <= 0) {
        return -1; // Error: Invalid input
    }

    srand(time(NULL)); // Seed the random number generator

    *nfa_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfa_list == NULL) {
        return -2; // Error: Memory allocation failed
    }

    unsigned int used_rntis[MAX_UNIQUE_RNTI];
    size_t unique_count = 0;
    int last_rnti = -1;

    for (size_t i = 0; i < N; ++i) {
        if (unique_count >= MAX_UNIQUE_RNTI) {
            break; // Reached the maximum number of unique RNTIs
        }

        unsigned int current_rnti;
        do {
            current_rnti = rand() % (MAX_UNIQUE_RNTI * 10); // Example range for RNTI values
        } while (unique_count > 0 && (current_rnti == last_rnti || find_in_array(used_rntis, unique_count, current_rnti)));

        if (unique_count < MAX_UNIQUE_RNTI) {
            used_rntis[unique_count++] = current_rnti;
        }

        (*nfa_list)[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag
        (*nfa_list)[i].RNTI = current_rnti;
        (*nfa_list)[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? CRCFLAG_TRUE : CRCFLAG_FALSE;

        last_rnti = current_rnti;
    }

    return unique_count; // Return the number of unique RNTIs used
}

int find_in_array(const unsigned int *array, size_t length, unsigned int value) {
    for (size_t i = 0; i < length; ++i) {
        if (array[i] == value) {
            return 1;
        }
    }
    return 0;
}
