#include <pthread.h>

// Assumed external random number generation library header
#include "custom_rng.h"

#define MAX_RNTI 1024

typedef struct {
    uint16_t UE_ID;
    uint16_t CELL_ID;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rx_ue_information_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} MemoryPool;

void initialize_pool(MemoryPool *mp, size_t initial_capacity) {
    mp->capacity = initial_capacity;
    mp->count = 0;
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(mp->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&mp->mutex, NULL);
}

void destroy_pool(MemoryPool *mp) {
    free(mp->pool);
    mp->pool = NULL;
    mp->capacity = 0;
    mp->count = 0;
    pthread_mutex_destroy(&mp->mutex);
}

bool allocate_from_pool(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T **pdu) {
    pthread_mutex_lock(&mp->mutex);
    if (mp->count >= mp->capacity) {
        pthread_mutex_unlock(&mp->mutex);
        return false;
    }
    *pdu = &mp->pool[mp->count++];
    pthread_mutex_unlock(&mp->mutex);
    return true;
}

void manage_crc_indications(size_t N, MemoryPool *mp, uint32_t seed) {
    srand(seed);
    custom_rng_init(seed);

    bool rnti_used[MAX_RNTI] = {false};
    size_t generated = 0;

    while (generated < N) {
        if (!allocate_from_pool(mp, &mp->pool[mp->count - 1])) {
            fprintf(stderr, "Failed to allocate PDU from pool\n");
            break;
        }

        uint16_t rnti;
        do {
            rnti = custom_rng_get_uint16() % MAX_RNTI;
        } while (rnti_used[rnti]);

        rnti_used[rnti] = true;

        RX_UE_INFORMATION_TAG_T *rx_info_tag = &mp->pool[mp->count - 1].rx_ue_information_tag;
        rx_info_tag->UE_ID = custom_rng_get_uint16();
        rx_info_tag->CELL_ID = custom_rng_get_uint16();

        mp->pool[mp->count - 1].RNTI = rnti;
        mp->pool[mp->count - 1].crc_indication_rel8_tag.CRCFLAG = custom_rng_get_uint8() % 2;

        generated++;
    }
}

void serialize(const MemoryPool *mp, uint8_t **buffer, size_t *size) {
    *size = mp->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = (uint8_t *)malloc(*size);
    if (!*buffer) {
        perror("Failed to allocate serialization buffer");
        exit(EXIT_FAILURE);
    }
    memcpy(*buffer, mp->pool, *size);
}

bool deserialize(const uint8_t *buffer, size_t size, MemoryPool *mp) {
    if (size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) return false;
    size_t count = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (!allocate_from_pool(mp, NULL)) return false;

    memcpy(mp->pool, buffer, size);
    mp->count = count;

    return true;
}

void test_crc_indications() {
    MemoryPool mp;
    initialize_pool(&mp, 1000);
    manage_crc_indications(500, &mp, 42);

    uint8_t *buffer;
    size_t buffer_size;
    serialize(&mp, &buffer, &buffer_size);

    MemoryPool deserialized_mp;
    initialize_pool(&deserialized_mp, 1000);
    if (!deserialize(buffer, buffer_size, &deserialized_mp)) {
        fprintf(stderr, "Deserialization failed\n");
    }

    free(buffer);
    destroy_pool(&mp);
    destroy_pool(&deserialized_mp);
}

int main() {
    test_crc_indications();
    return 0;
}
