        node = (Node*)malloc(sizeof(Node));
        node->packet = newPacket;
        node->next = list->head;
        list->head = node;
        list->size++;
        snprintf(logMsg, sizeof(logMsg), "Added packet with ID %lu", newPacket.id);
    } else { // Update existing packet
        *node->packet = newPacket;
        snprintf(logMsg, sizeof(logMsg), "Updated packet with ID %lu", newPacket.id);
    }

    logMessage(logMsg);
}

void freePacketList(PacketList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int retrievePacketsByIPRange(PacketList *list, const char *startIP, const char *endIP, Packet **packets, int *count) {
    Node *current = list->head;
    int capacity = 10; // Initial capacity
    *packets = (Packet*)malloc(capacity * sizeof(Packet));
    *count = 0;

    while (current != NULL && *count < capacity) {
        if (strcmp(current->packet.sourceIP, startIP) >= 0 &&
            strcmp(current->packet.destIP, endIP) <= 0) {
            (*packets)[*count++] = current->packet;
        }

        if (*count == capacity) { // Double the size
            capacity *= 2;
            *packets = (Packet*)realloc(*packets, capacity * sizeof(Packet));
        }

        current = current->next;
    }

    return 0; // Success
}

// Example usage:
int main() {
    PacketList *packetList = createPacketList();

    Packet p1 = {1, time(NULL), "192.168.1.1", "192.168.1.2", 1024};
    addOrUpdatePacket(packetList, p1);

    Packet p2 = {2, time(NULL), "192.168.1.3", "192.168.1.4", 2048};
    addOrUpdatePacket(packetList, p2);

    Packet *retrievedPackets;
    int count;
    retrievePacketsByIPRange(packetList, "192.168.1.0", "192.168.1.255", &retrievedPackets, &count);

    for (int i = 0; i < count; ++i) {
        printf("Packet ID: %lu, Source IP: %s, Dest IP: %s\n",
               retrievedPackets[i].id, retrievedPackets[i].sourceIP, retrievedPackets[i].destIP);
    }

    free(retrievedPackets);
    freePacketList(packetList);

    return 0;
}
```

This implementation includes:
- A dynamic linked list to manage packets.
- Functions for adding or updating packets by ID.
- Efficient retrieval of packets based on IP address ranges.
- Integration with an external logging system, with a fallback if the logger is unavailable.
- Memory management to prevent leaks.']

