    struct ListNode* next;
} ListNode;

// List structure with a mutex for thread safety
typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
    int capacity;
    int size;
} CRCList;

// Function to initialize the list
int init_crc_list(CRCList* list, int capacity) {
    if (capacity <= 0) return -1;

    list->head = NULL;
    list->size = 0;
    list->capacity = capacity;

    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        return -1;
    }

    printf("List initialized with capacity %d\n", capacity);
    return 0;
}

// Function to allocate memory for a new node
ListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    newNode->data = data;
    newNode->next = NULL;
    printf("Node allocated\n");
    return newNode;
}

// Function to insert a new node into the list
int insert_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= list->capacity) {
        fprintf(stderr, "List is at full capacity\n");
        return -1;
    }

    ListNode* newNode = create_node(data);
    if (!newNode) return -1;

    pthread_mutex_lock(&list->lock);

    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    printf("Inserted new node\n");
    return 0;
}

// Function to free all nodes in the list
void free_crc_list(CRCList* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        printf("Node deallocated\n");
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    list->head = NULL;
    list->size = 0;

    printf("List deallocated\n");
}

// Function to generate a random CRC flag
int generate_crc_flag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Example usage
void example_usage(int N) {
    CRCList crc_list;
    if (init_crc_list(&crc_list, N) != 0) {
        free_crc_list(&crc_list);
        return;
    }

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data = {i, i * 10, i * 100, generate_crc_flag()};
        if (insert_crc_list(&crc_list, data) != 0) break;
    }

    free_crc_list(&crc_list);
}

int main() {
