    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t count;
    pthread_rwlock_t rwlock;
} PDUManager;

PDUManager* create_pdu_manager(size_t initial_size) {
    if (initial_size > MAX_STRUCTS) initial_size = MAX_STRUCTS;

    PDUManager *manager = malloc(sizeof(PDUManager));
    manager->pdu_list = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->count = 0;
    pthread_rwlock_init(&manager->rwlock, NULL);

    if (!manager || !manager->pdu_list) {
        free(manager);
        perror("Memory allocation failed");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < initial_size; ++i) {
        pthread_rwlock_wrlock(&manager->rwlock);

        manager->pdu_list[i].RX_UE_INFORMATION_TAG = rand() % UINT_MAX + 1;
        do {
            manager->pdu_list[i].RNTI = rand();
        } while (check_duplicate_rnti(manager, i, manager->pdu_list[i].RNTI));

        manager->pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % UINT_MAX + 1;
        manager->pdu_list[i].CRCFLAG = rand() & 0x01;

        pthread_rwlock_unlock(&manager->rwlock);
    }

    manager->count = initial_size;
    return manager;
}

int check_duplicate_rnti(PDUManager *manager, size_t new_index, unsigned int rnti) {
    for (size_t i = 0; i < new_index; ++i) {
        if (manager->pdu_list[i].RNTI == rnti)
            return 1;
    }
    return 0;
}

void free_pdu_manager(PDUManager *manager) {
    pthread_rwlock_wrlock(&manager->rwlock);

    free(manager->pdu_list);
    manager->count = 0;

    pthread_rwlock_unlock(&manager->rwlock);
    pthread_rwlock_destroy(&manager->rwlock);
    free(manager);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Example Unit Test
