#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

int add_or_update_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (element.RNTI <= 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid RNTI
    }

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == element.RNTI) {
            (*current)->data = element;
            pthread_mutex_unlock(&list->lock);
            return 0; // Updated existing
        }
        current = &(*current)->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    new_node->data = element;
    new_node->next = NULL;
    *current = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Added new
}

int remove_element(DynamicList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    if (RNTI <= 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid RNTI
    }

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == RNTI) {
            Node* to_free = *current;
            *current = (*current)->next;
            free(to_free);
            pthread_mutex_unlock(&list->lock);
            return 0; // Removed
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void serialize_list(DynamicList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    while (current) {
        fwrite(&current->data.RNTI, sizeof(int), 1, file); // Serialize other fields as needed
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

int deserialize_list(DynamicList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T element;
    while (fread(&element.RNTI, sizeof(int), 1, file)) { // Deserialize other fields as needed
        add_or_update_element(list, element);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroy_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* to_free = current;
        current = current->next;
        free(to_free);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
