#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_CONNECTIONS 10

typedef struct {
    int id;
    char service_id[50];
    time_t last_active;
    double average_latency;
    pthread_mutex_t lock;
} Connection;

typedef struct {
    Connection *connections[MAX_CONNECTIONS];
    int count;
    pthread_mutex_t mutex;
} ConnectionPool;

// Initialize connection pool
void init_connection_pool(ConnectionPool *pool) {
    pthread_mutex_init(&pool->mutex, NULL);
    pool->count = 0;
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        pool->connections[i] = NULL;
    }
}

// Create a new connection
Connection* create_connection(const char *service_id) {
    Connection *conn = (Connection*)malloc(sizeof(Connection));
    if (!conn) return NULL;

    pthread_mutex_init(&conn->lock, NULL);
    conn->id = rand(); // Unique ID for demonstration purposes.
    snprintf(conn->service_id, sizeof(conn->service_id), "%s", service_id);
    time(&conn->last_active);
    conn->average_latency = 0.0;

    return conn;
}

// Add connection to the pool
int add_connection(ConnectionPool *pool, Connection *connection) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&pool->mutex);
        return -1; // Pool is full
    }

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (!pool->connections[i]) {
            pool->connections[i] = connection;
            pool->count++;
            break;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

// Remove a connection from the pool
int remove_connection(ConnectionPool *pool, Connection *connection) {
    pthread_mutex_lock(&pool->mutex);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (pool->connections[i] == connection) {
            free(pool->connections[i]);
            pool->connections[i] = NULL;
            pool->count--;
            break;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

// Find an idle connection
Connection* find_idle_connection(ConnectionPool *pool, const char *service_id) {
    time_t now;
    time(&now);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (pool->connections[i]) {
            pthread_mutex_lock(&pool->connections[i]->lock);
            double seconds_inactivity = difftime(now, pool->connections[i]->last_active);

            // Check if connection is idle or stale
            if (seconds_inactivity > 30.0 && strcmp(pool->connections[i]->service_id, service_id) == 0) {
                pthread_mutex_unlock(&pool->connections[i]->lock);
                return pool->connections[i];
            }

            pthread_mutex_unlock(&pool->connections[i]->lock);
        }
    }

    return NULL;
}

// Simulate network request
void simulate_network_request(Connection *connection, double latency) {
    pthread_mutex_lock(&connection->lock);

    // Update average latency (simple moving average for demonstration)
    connection->average_latency = (connection->average_latency + latency) / 2.0;

    time(&connection->last_active);
    pthread_mutex_unlock(&connection->lock);
}

// Gracefully re-establish connections
void maintain_connections(ConnectionPool *pool) {
    time_t now;
    double current_time;

    while (1) {
        sleep(5); // Check every 5 seconds

        pthread_mutex_lock(&pool->mutex);

        for (int i = 0; i < MAX_CONNECTIONS; ++i) {
            if (pool->connections[i]) {
                pthread_mutex_lock(&pool->connections[i]->lock);

                time(&now);
                current_time = difftime(now, pool->connections[i]->last_active);

                // Re-establish connection if it has been idle too long
                if (current_time > 60.0) { 
                    remove_connection(pool, pool->connections[i]);
                    Connection *new_conn = create_connection(pool->connections[i]->service_id);
                    add_connection(pool, new_conn);
                }

                pthread_mutex_unlock(&pool->connections[i]->lock);
            }
        }

        pthread_mutex_unlock(&pool->mutex);
    }
}

int main() {
    srand(time(NULL));

    ConnectionPool pool;
    init_connection_pool(&pool);

    // Add initial connections
    for (int i = 0; i < 5; ++i) {
        Connection *conn = create_connection("Service_A");
        add_connection(&pool, conn);
    }

    // Simulate network requests in separate threads
    pthread_t maintenance_thread;
    pthread_create(&maintenance_thread, NULL, (void*)maintain_connections, &pool);

    while (1) {
        sleep(2); // Main thread simulating application workload

        Connection *conn = find_idle_connection(&pool, "Service_A");
        if (!conn) {
            conn = create_connection("Service_A");
            add_connection(&pool, conn);
        }

        simulate_network_request(conn, rand() % 100 / 10.0 + 1.0); // Simulate latency
    }

    pthread_join(maintenance_thread, NULL);

    return 0;
}
```']

