```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CONTEXTS 1024
#define MEASUREMENT_INTERVAL_5G_NR 1000 // in milliseconds
#define MEASUREMENT_INTERVAL_WIFI6 500  // in milliseconds

typedef enum {
    PROTOCOL_5GNR,
    PROTOCOL_WIFI6,
    PROTOCOL_UNKNOWN
} ProtocolType;

typedef struct {
    int ue_id;
    unsigned int rnti;
    char **measurement_results; // dynamic array of measurement results per frequency band
    size_t result_count;
    time_t last_activity_time;
    ProtocolType protocol;
} Context;

typedef struct {
    Context *contexts[MAX_CONTEXTS];
    size_t context_count;
    size_t max_contexts_allowed;
    unsigned int retry_limit;
} NNFSystemState;

// Function prototypes
void initialize_nnf(NNFSystemState *nnf, size_t max_contexts_allowed, unsigned int retry_limit);
Context* create_context(int ue_id, unsigned int rnti, ProtocolType protocol, const char **initial_measurements, size_t measurement_count);
void prune_inactive_contexts(NNFSystemState *nnf, time_t inactivity_threshold);
void dynamic_protocol_switch(Context *context, ProtocolType new_protocol);
int add_measurement_result(Context *context, const char *result);
void log_error(const char *error_message);

// Implementation
void initialize_nnf(NNFSystemState *nnf, size_t max_contexts_allowed, unsigned int retry_limit) {
    nnf->context_count = 0;
    nnf->max_contexts_allowed = max_contexts_allowed;
    nnf->retry_limit = retry_limit;

    for (size_t i = 0; i < MAX_CONTEXTS; i++) {
        nnf->contexts[i] = NULL;
    }
}

Context* create_context(int ue_id, unsigned int rnti, ProtocolType protocol, const char **initial_measurements, size_t measurement_count) {
    if (measurement_count == 0 || initial_measurements == NULL) return NULL;

    Context *new_context = malloc(sizeof(Context));
    if (!new_context) {
        log_error("Memory allocation failed for new context");
        return NULL;
    }

    new_context->ue_id = ue_id;
    new_context->rnti = rnti;
    new_context->protocol = protocol;
    new_context->last_activity_time = time(NULL);

    new_context->measurement_results = malloc(measurement_count * sizeof(char*));
    if (!new_context->measurement_results) {
        free(new_context);
        log_error("Memory allocation failed for measurement results");
        return NULL;
    }

    for (size_t i = 0; i < measurement_count; ++i) {
        new_context->measurement_results[i] = strdup(initial_measurements[i]);
        if (!new_context->measurement_results[i]) {
            for (size_t j = 0; j <= i; ++j) {
                free(new_context->measurement_results[j]);
            }
            free(new_context->measurement_results);
            free(new_context);
            log_error("Memory allocation failed during measurement results duplication");
            return NULL;
        }
    }

    new_context->result_count = measurement_count;
    return new_context;
}

void prune_inactive_contexts(NNFSystemState *nnf, time_t inactivity_threshold) {
    time_t current_time = time(NULL);

    for (size_t i = 0; i < nnf->context_count; ++i) {
        if (difftime(current_time, nnf->contexts[i]->last_activity_time) > inactivity_threshold) {
            Context *inactive_context = nnf->contexts[i];
            nnf->contexts[i] = NULL;

            for (size_t j = i; j < nnf->context_count - 1; ++j) {
                nnf->contexts[j] = nnf->contexts[j + 1];
            }
            nnf->context_count--;

            // Free resources
            for (size_t k = 0; k < inactive_context->result_count; ++k) {
                free(inactive_context->measurement_results[k]);
            }
            free(inactive_context->measurement_results);
            free(inactive_context);

            i--; // Re-evaluate the current index as it now holds a new context
        }
    }
}

void dynamic_protocol_switch(Context *context, ProtocolType new_protocol) {
    if (!context || context->protocol == new_protocol) return;

    // Implement protocol-specific initialization if necessary

    context->protocol = new_protocol;
}

int add_measurement_result(Context *context, const char *result) {
    if (!context || !result) return -1;

    size_t new_count = context->result_count + 1;
    char **new_results = realloc(context->measurement_results, new_count * sizeof(char*));
    if (!new_results) {
        log_error("Memory reallocation failed for adding measurement result");
        return -1;
    }

    context->measurement_results = new_results;
    context->measurement_results[new_count - 1] = strdup(result);

    if (!context->measurement_results[new_count - 1]) {
        free(context->measurement_results[new_count - 1]);
        log_error("Memory allocation failed for new measurement result");
        return -1;
    }

    context->result_count = new_count;
    return 0;
}

void log_error(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}
```

### Key Features:

- **Context Management**: Handles creation and deletion of contexts with unique UE IDs and RNTIs.
- **Dynamic Protocol Switching**: Supports switching between protocols like 5G NR and Wi-Fi 6 based on conditions.
- **Pruning Inactive Contexts**: Periodically removes inactive contexts to optimize memory usage.
- **Error Handling**: Includes logging for error tracking and memory allocation errors.
- **Scalability Considerations**: Limits the number of simultaneous contexts to prevent resource exhaustion.

This code provides a foundational setup that can be expanded upon based on specific network requirements, protocol details, or performance metrics.']

