#include <string.h>

// Define structures for MAC entity context and buffer pool
typedef struct {
    unsigned int mei;               // MAC Entity Identifier
    unsigned int seq_num;           // Sequence number generator
} MacEntityContext;

typedef struct BufferNode {
    char *buffer;
    size_t size;
    struct BufferNode *next;
} BufferNode;

// Define a structure for the buffer pool
typedef struct {
    BufferNode *head;
    BufferNode *tail;
    size_t pool_size;               // Total size of the buffer pool
    size_t used_size;               // Current used size of the buffer pool
} BufferPool;

// Function prototypes
void initializeMacEntityContexts(MacEntityContext **contexts, int num_contexts);
BufferPool* createBufferPool(size_t initial_pool_size);
int allocateBuffer(BufferPool *pool, size_t size, char **buffer);
int freeBuffer(BufferPool *pool, char *buffer);
void updateMei(MacEntityContext *context, unsigned int new_mei);

// Implementations
void initializeMacEntityContexts(MacEntityContext **contexts, int num_contexts) {
    for (int i = 0; i < num_contexts; ++i) {
        contexts[i] = malloc(sizeof(MacEntityContext));
        if (!contexts[i]) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        contexts[i]->mei = rand() % 256; // Assign a random MEI
        contexts[i]->seq_num = 0;
    }
}

BufferPool* createBufferPool(size_t initial_pool_size) {
    BufferPool *pool = malloc(sizeof(BufferPool));
    if (!pool) {
        perror("Failed to allocate memory for buffer pool");
        exit(EXIT_FAILURE);
    }

    pool->head = NULL;
    pool->tail = NULL;
    pool->pool_size = 0;
    pool->used_size = 0;

    BufferNode *node = malloc(sizeof(BufferNode));
    if (!node) {
        perror("Failed to allocate memory for buffer node");
        free(pool);
        exit(EXIT_FAILURE);
    }

    node->buffer = malloc(initial_pool_size);
    if (!node->buffer) {
        perror("Failed to allocate buffer");
        free(node);
        free(pool);
        exit(EXIT_FAILURE);
    }

    node->size = initial_pool_size;
    node->next = NULL;

    pool->head = node;
    pool->tail = node;
    pool->pool_size += initial_pool_size;

    return pool;
}

int allocateBuffer(BufferPool *pool, size_t size, char **buffer) {
    BufferNode *current = pool->head;
    while (current) {
        if (size <= current->size - strlen(current->buffer)) { // Check available space
            *buffer = current->buffer + strlen(current->buffer);
            strcpy(*buffer, "");  // Initialize the buffer content
            current->buffer[strlen(current->buffer) + size] = '\0';  // Null-terminate after allocation
            pool->used_size += size;
            return 1;  // Allocation successful
        }
        current = current->next;
    }

    // If no available space, expand the buffer pool
    BufferNode *new_node = malloc(sizeof(BufferNode));
    if (!new_node) {
        perror("Failed to allocate memory for new buffer node");
        return 0;  // Allocation failed
    }

    new_node->buffer = malloc(size);
    if (!new_node->buffer) {
        perror("Failed to allocate buffer in new node");
        free(new_node);
        return 0;  // Allocation failed
    }

    strcpy(new_node->buffer, "");  // Initialize the buffer content
    new_node->size = size;
    new_node->next = NULL;

    pool->tail->next = new_node;
    pool->tail = new_node;
    pool->pool_size += size;
    pool->used_size += size;

    *buffer = new_node->buffer;
    return 1;  // Allocation successful
}

int freeBuffer(BufferPool *pool, char *buffer) {
    BufferNode *current = pool->head;
    while (current && current->buffer != buffer) {
        current = current->next;
    }

    if (!current) {
        perror("Buffer not found in the pool");
        return 0;  // Deallocation failed
    }

    size_t used_size = strlen(buffer);
    if (used_size > 0) {
        memset(buffer, 0, used_size);  // Clear buffer content
        pool->used_size -= used_size;
    }

    // Optionally remove node if completely unused to prevent memory waste
    if (current == pool->tail && current->buffer[0] == '\0') {
        BufferNode *prev = NULL;
        for (BufferNode *iter = pool->head; iter != current; prev = iter, iter = iter->next);

        if (prev) {
            prev->next = NULL;
        } else {
            pool->head = NULL;
        }

        free(current->buffer);
        free(current);

        pool->tail = prev;
    }

    return 1;  // Deallocation successful
}

void updateMei(MacEntityContext *context, unsigned int new_mei) {
    context->mei = new_mei;
}
