} Identifier;

typedef struct LTE_DL_FRAMEINFO_NODE {
    LTE_DL_FRAMEINFO data;
    struct LTE_DL_FRAMEINFO_NODE *next;
} LTE_DL_FRAMEINFO_NODE;

// Function to check if an RNTI already exists in the list
int rnti_exists(LTE_DL_FRAMEINFO_NODE *head, int rnti) {
    while (head != NULL) {
        if (head->data.mac_inst.rnti == rnti)
            return 1;
        head = head->next;
    }
    return 0;
}

// Function to add an LTE_DL_FRAMEINFO structure
int add_lte_frameinfo(LTE_DL_FRAMEINFO_NODE **head, LTE_DL_FRAMEINFO frame_info) {
    if (rnti_exists(*head, frame_info.mac_inst.rnti)) {
        return -1; // RNTI already exists
    }

    LTE_DL_FRAMEINFO_NODE *new_node = (LTE_DL_FRAMEINFO_NODE *)malloc(sizeof(LTE_DL_FRAMEINFO_NODE));
    if (!new_node) {
        return -2; // Memory allocation failed
    }

    new_node->data = frame_info;
    new_node->next = *head;
    *head = new_node;

    return 0; // Success
}

// Function to serialize the list of LTE_DL_FRAMEINFO structures
size_t serialize_frameinfo_list(LTE_DL_FRAMEINFO_NODE *head, unsigned char **buffer) {
    size_t total_size = 0;
    LTE_DL_FRAMEINFO_NODE *current = head;

    while (current != NULL) {
        total_size += sizeof(current->data); // Simplified size calculation
        current = current->next;
    }

    if (*buffer == NULL) {
        *buffer = (unsigned char *)malloc(total_size);
        if (!*buffer)
            return 0; // Memory allocation failed

        current = head;
        unsigned char *ptr = *buffer;

        while (current != NULL) {
            memcpy(ptr, &current->data, sizeof(current->data));
            ptr += sizeof(current->data);
            current = current->next;
        }
    }

    return total_size; // Return the size of the serialized data
}

// Function to free the list and allocated memory
void free_frameinfo_list(LTE_DL_FRAMEINFO_NODE **head) {
    while (*head != NULL) {
        LTE_DL_FRAMEINFO_NODE *temp = (*head)->next;
        free(*head);
        *head = temp;
    }
}
