#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_FILES 10
#define BUFFER_SIZE 4096

typedef struct {
    long Timestamp;
    int SequenceNumber;
    size_t PayloadLength;
} FrameHeader;

// Logger function
void log_message(const char *message) {
    FILE *log_file = fopen("process_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Error handling utility
void handle_error(const char *operation, const char *file_path) {
    perror(operation);
    log_message((const char[]){"Error ", operation, " file: ", file_path, ": ", strerror(errno), "\n"});
}

// Function to parse data from a file descriptor and populate FrameHeader array
int parse_file(int fd, FrameHeader ***frame_headers, size_t *header_count) {
    FILE *file = fdopen(fd, "rb");
    if (!file) handle_error("fdopen", "N/A");

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    size_t allocated_size = 100; // Initial allocation
    *frame_headers = malloc(allocated_size * sizeof(FrameHeader *));
    if (*frame_headers == NULL) {
        log_message("Failed to allocate memory for FrameHeaders\n");
        fclose(file);
        return -1;
    }

    *header_count = 0;
    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
        // Adaptive parsing logic based on configuration
        for (ssize_t i = 0; i < bytes_read; ++i) {
            FrameHeader *header = malloc(sizeof(FrameHeader));
            if (!header) {
                log_message("Failed to allocate memory for a single FrameHeader\n");
                fclose(file);
                return -1;
            }

            // Example parsing logic (this needs customization)
            header->Timestamp = *(long *)(buffer + i);    // Simplified example
            header->SequenceNumber = *(int *)(buffer + i + sizeof(long));
            header->PayloadLength = *(size_t *)(buffer + i + sizeof(long) + sizeof(int));

            if (*header_count >= allocated_size) {
                allocated_size *= 2;
                *frame_headers = realloc(*frame_headers, allocated_size * sizeof(FrameHeader *));
                if (*frame_headers == NULL) {
                    log_message("Failed to reallocate memory for FrameHeaders\n");
                    free(header);
                    fclose(file);
                    return -1;
                }
            }

            (*frame_headers)[*header_count] = header;
            (*header_count)++;
        }
    }

    if (ferror(file)) handle_error("read", "N/A");

    fclose(file);
    return 0;
}

void *process_file(void *arg) {
    int fd = *((int *)arg);
    FrameHeader **frame_headers = NULL;
    size_t header_count = 0;

    if (parse_file(fd, &frame_headers, &header_count) == -1) {
        log_message("Failed to parse file\n");
        close(fd);
        return NULL;
    }

    // Log successful parsing
    char success_msg[100];
    snprintf(success_msg, sizeof(success_msg), "Parsed %zu headers from file descriptor %d\n", header_count, fd);
    log_message(success_msg);

    // Free allocated memory (just for demonstration)
    for (size_t i = 0; i < header_count; ++i) {
        free(frame_headers[i]);
    }
    free(frame_headers);

    close(fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc <= MAX_FILES + 1) {
        log_message("Insufficient number of files provided\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_FILES];
    int file_descriptors[MAX_FILES];

    for (int i = 0; i < MAX_FILES && i < argc - 1; ++i) {
        file_descriptors[i] = open(argv[i + 1], O_RDONLY);
        if (file_descriptors[i] == -1) {
            log_message((const char[]){"Failed to open ", argv[i + 1], "\n"});
            continue;
        }

        if (pthread_create(&threads[i], NULL, process_file, &file_descriptors[i]) != 0) {
            handle_error("pthread_create", "N/A");
            close(file_descriptors[i]);
            file_descriptors[i] = -1; // Mark as invalid
        }
    }

    for (int i = 0; i < MAX_FILES && file_descriptors[i] != -1; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
