int resize_array_if_needed(DynamicArray *array, size_t new_count);
void free_dynamic_array(DynamicArray *array);
int add_crc_indication_pdu(DynamicArray *array);

// Initialize dynamic array with initial capacity
int initialize_dynamic_array(DynamicArray *array) {
    pthread_rwlock_init(&array->lock, NULL);
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;

    array->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed during initialization.\n");
        return -1;
    }

    return 0;
}

// Resize the array when more capacity is needed
int resize_array_if_needed(DynamicArray *array, size_t new_count) {
    if (new_count > array->capacity) {
        size_t new_capacity = array->capacity * 2;
        while (new_capacity < new_count) {
            new_capacity *= 2;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Memory allocation failed during resize.\n");
            return -1;
        }

        array->data = new_data;
        array->capacity = new_capacity;
    }
    return 0;
}

// Add a CRC indication PDU to the dynamic array
int add_crc_indication_pdu(DynamicArray *array) {
    pthread_rwlock_wrlock(&array->lock);

    if (resize_array_if_needed(array, array->count + 1) != 0) {
        pthread_rwlock_unlock(&array->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG: 0 or 1

    array->data[array->count++] = pdu;

    pthread_rwlock_unlock(&array->lock);
    return 0;
}

// Free dynamic array resources
void free_dynamic_array(DynamicArray *array) {
    if (array->data) {
        free(array->data);
    }
    pthread_rwlock_destroy(&array->lock);
}

int main() {
    srand(time(NULL));

    DynamicArray array;
    if (initialize_dynamic_array(&array) != 0) {
        return -1;
    }

    for (size_t i = 0; i < MAX_N; ++i) {
        if (add_crc_indication_pdu(&array) != 0) {
            fprintf(stderr, "Failed to add CRC indication PDU at index %zu.\n", i);
            free_dynamic_array(&array);
            return -1;
        }
    }

    printf("Added %zu CRC indication PDUs successfully.\n", array.count);

    free_dynamic_array(&array);
    return 0;
}
