NFAPI_CRC_INDICATION_PDU_T* allocate_ue_sessions(int *num_allocated) {
    if (num_allocated == NULL) return NULL;

    const int max_retries = 5;
    const int base_delay_ms = 100;

    NFAPI_CRC_INDICATION_PDU_T *ue_sessions = NULL;
    for (int attempt = 0; attempt <= max_retries; ++attempt) {
        ue_sessions = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_UE_SESSIONS * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (ue_sessions != NULL) {
            for (int i = 0; i < MAX_UE_SESSIONS; ++i) {
                ue_sessions[i].RX_UE_INFORMATION_TAG = i + 1;
                ue_sessions[i].RNTI = i * 2;
                ue_sessions[i].CRC_INDICATION_REL8_TAG = i * 3;
            }
            break;
        } else {
            printf("Memory allocation failed, attempt %d\n", attempt);
            if (attempt < max_retries) {
                int delay_ms = base_delay_ms * (1 << attempt); // Exponential backoff
                time.sleep(delay_ms / 1000.0);
            }
        }
    }

    if (ue_sessions == NULL) {
        printf("Failed to allocate memory after %d attempts\n", max_retries + 1);
        *num_allocated = 0;
        return NULL;
    } else {
        // Log successful allocation for monitoring
        printf("Successfully allocated memory for %d UE sessions\n", MAX_UE_SESSIONS);
        *num_allocated = MAX_UE_SESSIONS;
        return ue_sessions;
