#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    int logging_enabled;
} ArrayManager;

static void log_message(const char *message) {
    if (logging_enabled) {
        printf("%s\n", message);
    }
}

ArrayManager* create_array_manager(int initial_size, int logging_enabled) {
    ArrayManager *manager = malloc(sizeof(ArrayManager));
    if (!manager) {
        log_message("Failed to allocate memory for ArrayManager");
        return NULL;
    }

    manager->capacity = (initial_size > MAX_STRUCTS) ? MAX_STRUCTS : initial_size;
    manager->array = calloc(manager->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        log_message("Failed to allocate memory for array");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->logging_enabled = logging_enabled;

    log_message("ArrayManager created successfully");

    return manager;
}

void fill_random_data(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 100;
    pdu->RNTI = rand() % 1000;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
}

void resize_array(ArrayManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_message("Failed to reallocate memory for array");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->array = new_array;
    manager->capacity = new_capacity;

    log_message("Array resized successfully");

    pthread_mutex_unlock(&manager->lock);
}

void add_pdu(ArrayManager *manager) {
    if (manager->count >= manager->capacity) {
        resize_array(manager, manager->capacity * 2);
    }

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->count];
    fill_random_data(pdu);
    manager->count++;

    log_message("PDU added successfully");

    pthread_mutex_unlock(&manager->lock);
}

void free_array_manager(ArrayManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
        log_message("ArrayManager freed");
    }
}

int main() {
    srand(time(NULL));

    int initial_size = 10;
    ArrayManager *manager = create_array_manager(initial_size, 1);

    if (manager) {
        for (int i = 0; i < 20; ++i) { // Adding more than the initial size to trigger resizing
            add_pdu(manager);
        }
        free_array_manager(manager);
    }

    return 0;
}
