        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(db->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_rwlock_unlock(&db->lock);
            perror("Failed to resize data array");
            return -1;
        }
        db->data = new_data;
        db->capacity = new_capacity;
