unsigned int get_random_crcflag(void) {
    static unsigned int seed = 0;

    pthread_mutex_lock(&rand_mutex);
    if (seed == 0) {
        // Seed the RNG with a real random value from /dev/urandom
        FILE *random_fp = fopen("/dev/urandom", "rb");
        if (random_fp != NULL) {
            fread((char *)&seed, sizeof(seed), 1, random_fp);
            fclose(random_fp);
        } else {
            seed = time(NULL); // Fallback to current time
        }
    }

    seed ^= seed << 13;
    seed ^= seed >> 17;
    seed ^= seed << 5;

    unsigned int crcflag = (seed & 1) ? 0x01 : 0x00; // Assume CRCFLAG can be either 0 or 1

    pthread_mutex_unlock(&rand_mutex);
    return crcflag;
}

