    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    struct in_addr ip_address;
    pthread_mutex_t lock;
} DNS_Entry;

static DNS_Entry dns_cache[MAX_UES];
static int cache_count = 0;
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Logging function
void log_message(const char *message) {
#ifdef DEBUG
    printf("%s\n", message);
#endif
}

int resolve_dns(const char *hostname, struct in_addr *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_message("DNS resolution error");
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;

        addr = &(ipv4->sin_addr);
        memcpy(ip_address, addr, sizeof(struct in_addr));

        freeaddrinfo(res);
        return 0;
    }

    freeaddrinfo(res);
    log_message("DNS resolution failed");
    return -1;
}

int get_cached_dns(const char *hostname, struct in_addr *ip_address) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            memcpy(ip_address, &dns_cache[i].ip_address, sizeof(struct in_addr));
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return -1;
}

int cache_dns(const char *hostname, struct in_addr ip_address) {
    pthread_mutex_lock(&cache_lock);
    if (cache_count < MAX_UES) {
        strncpy(dns_cache[cache_count].hostname, hostname, sizeof(dns_cache[0].hostname));
        memcpy(&dns_cache[cache_count].ip_address, &ip_address, sizeof(struct in_addr));
        pthread_mutex_init(&dns_cache[cache_count].lock, NULL);
        cache_count++;
    }
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_ue_list(int num_ues) {
    if (num_ues <= 0 || num_ues > MAX_UES) {
        log_message("Invalid number of UEs");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *ue_list = malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ue_list) {
        perror("Failed to allocate memory for UE list");
        return NULL;
    }

    for (int i = 0; i < num_ues; ++i) {
        struct in_addr ip_address;

        // Example hostnames array
        const char *hostnames[] = {"example.com", "test.org"};

        if (get_cached_dns(hostnames[i % 2], &ip_address) == -1) {
            if (resolve_dns(hostnames[i % 2], &ip_address) != 0) {
                free(ue_list);
                log_message("Failed to resolve DNS");
                return NULL;
            }
            cache_dns(hostnames[i % 2], ip_address);
        }

        ue_list[i].RX_UE_INFORMATION_TAG = rand();
        ue_list[i].RNTI = rand() & 0xFFFF; // Example RNTI
        ue_list[i].CRC_INDICATION_REL8_TAG = rand() & 0xFF;
        ue_list[i].CRCFLAG = rand() % 2;

        log_message("UE instance configured");
    }

    return ue_list;
}

void free_ue_list(NFAPI_CRC_INDICATION_PDU_T *ue_list) {
    if (ue_list != NULL) {
        free(ue_list);
    }
}
