NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(size_t n, uint32_t seed, int *error_code) {
    if (n == 0) {
        *error_code = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error_code = -2; // Allocation failure
        return NULL;
    }

    initialize_random(seed);

    for (size_t i = 0; i < n; ++i) {
        array[i].rx_ue_information_tag.RNTI = (uint32_t)i + 1; // Unique RNTI values starting from 1
        array[i].rnti = (uint16_t)(array[i].rx_ue_information_tag.RNTI);

        uint8_t crc_flag = rand() % 256;
        if (crc_flag < 0 || crc_flag > 255) {
            free(array);
            *error_code = -3; // Invalid CRCFLAG
            return NULL;
        }
        array[i].crc_indication_rel8_tag.CRCFLAG = crc_flag;
    }

    *error_code = 0;
    return array;
