void serialize_to_binary_file(NFAPI_CRC_INDICATION_PDU_T* array, size_t n, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);
    fclose(file);
}

void deserialize_from_binary_file(NFAPI_CRC_INDICATION_PDU_T** array, size_t* n, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }

    fseek(file, 0, SEEK_END);
    *n = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    rewind(file);

    *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        perror("Memory allocation failed during deserialization");
        exit(EXIT_FAILURE);
    }

    fread(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T), *n, file);
    fclose(file);
}

