#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
    size_t max_size;
    time_t ttl;
} CRCList;

CRCList* create_list(size_t max_size, time_t ttl) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
    list->max_size = max_size;
    list->ttl = ttl;
    return list;
}

void cleanup_list(CRCList* list) {
    time_t current_time = time(NULL);
    Node* prev = NULL;
    Node* curr = list->head;

    pthread_rwlock_wrlock(&list->lock);

    while (curr != NULL) {
        if ((current_time - curr->timestamp) > list->ttl) {
            Node* to_delete = curr;
            curr = curr->next;
            free(to_delete);

            // Adjust max_size accordingly
            list->max_size++;
        } else {
            prev = curr;
            curr = curr->next;
        }
    }

    pthread_rwlock_unlock(&list->lock);
}

int validate_data(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simulate data validation, replace with actual logic
    return (pdu->RX_UE_INFORMATION_TAG > 0 && pdu->RNTI > 0);
}

int add_to_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!validate_data(pdu)) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = *pdu;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    pthread_rwlock_wrlock(&list->lock);

    while (list->head != NULL && list->max_size == 0) {
        Node* to_delete = list->head;
        list->head = list->head->next;
        free(to_delete);
        list->max_size++;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->max_size--;

    pthread_rwlock_unlock(&list->lock);

    return 0;
}

void destroy_list(CRCList* list) {
    Node* curr = list->head;

    while (curr != NULL) {
        Node* to_delete = curr;
        curr = curr->next;
        free(to_delete);
    }

    pthread_rwlock_destroy(&list->lock);
    free(list);
}

// Unit Tests
void test_add_and_cleanup() {
    CRCList* list = create_list(10000, 60); // TTL of 60 seconds

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 100, 200};
    add_to_list(list, &pdu1);

    // Add more entries to test cleanup
    for (int i = 0; i < 5000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {i + 2, i * 10, i * 20};
        add_to_list(list, &pdu);
    }

    // Simulate time passing and cleanup
    sleep(61); // Ensure entries are older than TTL
    cleanup_list(list);

    printf("Test passed: List size after cleanup should be small\n");
    destroy_list(list);
}

int main() {
    test_add_and_cleanup();
    return 0;
}
