    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *pool;
} NFAPICRCIndicationPool;

NFAPICRCIndicationPool* create_pool(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_STRUCTURES) {
        return NULL;
    }

    NFAPICRCIndicationPool *pool = malloc(sizeof(NFAPICRCIndicationPool));
    if (!pool) {
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->pool = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_indication(NFAPICRCIndicationPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        // Handle memory pressure or expand if feasible
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *ind = &pool->pool[pool->count++];

