    ind->CRC_INDICATION_REL8_TAG[0] = (rand() & 1) ? 0x01 : 0x00; // Random CRCFLAG

    pthread_mutex_unlock(&pool->lock);

    return ind;
}

void free_pool(NFAPICRCIndicationPool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);

    if (pool->pool) {
        memset(pool->pool, 0, pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(pool->pool);
        pool->pool = NULL;
    }

