import "nfa_api_message_t.h"  // Assume this header defines NFAPI_MESSAGE_T

#define INITIAL_CAPACITY 16

typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t count;
    size_t capacity;
} DynamicArray;

// Function to initialize the dynamic array
void init_dynamic_array(DynamicArray *array) {
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    array->messages = (NFAPI_MESSAGE_T *)malloc(array->capacity * sizeof(NFAPI_MESSAGE_T));
}

// Function to resize the dynamic array
void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_MESSAGE_T *new_messages = (NFAPI_MESSAGE_T *)realloc(array->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
    if (new_messages) {
        array->messages = new_messages;
        array->capacity = new_capacity;
    } else {
        // Handle reallocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Function to add a new entry
void add_entry(DynamicArray *array, const NFAPI_MESSAGE_T *entry) {
    if (array->count == array->capacity) {
        resize_dynamic_array(array);
    }
    array->messages[array->count++] = *entry;
}

// Function to remove an entry by RNTI
void remove_entry_by_rnti(DynamicArray *array, int rnti) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].RNTI == rnti) {
            for (size_t j = i; j < array->count - 1; ++j) {
                array->messages[j] = array->messages[j + 1];
            }
            --array->count;
            return;
        }
    }
}

// Function to update CRC indication status by RNTI
void update_crc_status(DynamicArray *array, int rnti, uint8_t crc_flag) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].RNTI == rnti) {
            array->messages[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;
            return;
        }
    }
}

// Function to handle external data source updates
void update_ues_from_source(DynamicArray *array, const NFAPI_MESSAGE_T *external_updates[], size_t num_updates) {
    for (size_t i = 0; i < num_updates; ++i) {
        // Check if the RNTI already exists and update CRC status
        for (size_t j = 0; j < array->count; ++j) {
            if (array->messages[j].RNTI == external_updates[i]->RNTI) {
                array->messages[j].CRC_INDICATION_REL8_TAG.CRCFLAG = external_updates[i]->CRC_INDICATION_REL8_TAG.CRCFLAG;
                return;
            }
        }
        // If RNTI doesn't exist, add the new entry
        add_entry(array, external_updates[i]);
    }
}

// Function to free the dynamic array resources
void free_dynamic_array(DynamicArray *array) {
    free(array->messages);
    array->count = 0;
    array->capacity = 0;
}
