#define HASH_TABLE_SIZE 1024

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash_function(int rnti) {
    return rnti % HASH_TABLE_SIZE;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int rxTag, int rnti, int crcFlag) {
    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) return NULL;

    newNode->RX_UE_INFORMATION_TAG = rxTag;
    newNode->RNTI = rnti;
    newNode->crcTag.CRCFLAG = crcFlag;
    newNode->next = NULL;

    return newNode;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) free(pdu);
}

NFAPI_CRC_INDICATION_PDU_T** initialize_list() {
    NFAPI_CRC_INDICATION_PDU_T **hashTable = malloc(HASH_TABLE_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!hashTable) return NULL;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i)
        hashTable[i] = NULL;

    return hashTable;
}

void insert_pdu(NFAPI_CRC_INDICATION_PDU_T **hashTable, int rxTag, int rnti, int crcFlag) {
    pthread_mutex_lock(&lock);

    unsigned int index = hash_function(rnti);
    NFAPI_CRC_INDICATION_PDU_T *newNode = create_pdu(rxTag, rnti, crcFlag);

    if (!newNode) {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Failed to allocate memory for new PDU\n");
        return;
    }

    newNode->next = hashTable[index];
    hashTable[index] = newNode;

    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* find_pdu(NFAPI_CRC_INDICATION_PDU_T **hashTable, int rnti) {
    unsigned int index = hash_function(rnti);

    NFAPI_CRC_INDICATION_PDU_T *current = hashTable[index];
    while (current != NULL) {
        if (current->RNTI == rnti)
            return current;
        current = current->next;
    }

    return NULL;
}

void delete_pdu(NFAPI_CRC_INDICATION_PDU_T **hashTable, int rnti) {
    pthread_mutex_lock(&lock);

    unsigned int index = hash_function(rnti);
    NFAPI_CRC_INDICATION_PDU_T *current = hashTable[index];
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current != NULL) {
        if (current->RNTI == rnti) {
            if (prev)
                prev->next = current->next;
            else
                hashTable[index] = current->next;

            free_pdu(current);
            pthread_mutex_unlock(&lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T **hashTable, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    pthread_mutex_lock(&lock);

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *current = hashTable[i];
        while (current != NULL) {
            fwrite(&current->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
            fwrite(&current->RNTI, sizeof(int), 1, file);
            fwrite(&current->crcTag.CRCFLAG, sizeof(int), 1, file);

            current = current->next;
        }
    }

    pthread_mutex_unlock(&lock);
    fclose(file);
}

void deserialize_list(NFAPI_CRC_INDICATION_PDU_T **hashTable, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *currentNode;
    int rxTag, rnti, crcFlag;

    while (fread(&rxTag, sizeof(int), 1, file) == 1 &&
           fread(&rnti, sizeof(int), 1, file) == 1 &&
           fread(&crcFlag, sizeof(int), 1, file) == 1) {

        delete_pdu(hashTable, rnti); // Ensure no duplicates
        insert_pdu(hashTable, rxTag, rnti, crcFlag);
    }

    pthread_mutex_unlock(&lock);
    fclose(file);
}

void free_list(NFAPI_CRC_INDICATION_PDU_T **hashTable) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *current = hashTable[i];
        while (current != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *toDelete = current;
            current = current->next;
            free_pdu(toDelete);
        }
    }

    free(hashTable);
}

