    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        log_error("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < num_pdus; ++i) {
        int retries = 0;
        int success = 0;

        while (retries <= max_retries && !success) {
            if (time(NULL) - cache->last_update_time > 60 || retries == 0) {
                if (fetch_external_config(cache) == 0) {
                    success = 1;
                } else {
                    log_error("Failed to fetch external configuration");
                    sleep(backoff_interval_ms / 1000);
                    backoff_interval_ms *= 2; // Exponential backoff
                    retries++;
                }
            }

            if (!success) break;

            pdus[i].RX_UE_INFORMATION_TAG = rand() % 256;
            pdus[i].RNTI = rand() % 65536;
            pdus[i].CRC_INDICATION_REL8_TAG = cache->cached_param; // Example usage
            pdus[i].CRCFLAG = rand() % 2;

            // Validate the structure (simple validation example)
            if (pdus[i].RX_UE_INFORMATION_TAG < 0 || pdus[i].RNTI < 0) {
                log_error("Validation failed for generated PDU");
                free(pdus);
                return NULL;
            }
        }

        if (!success) {
            free(pdus);
            return NULL;
        }
    }

    return pdus;
}

int main() {
    srand(time(NULL));

    ConfigCache cache = {0};
    int max_retries = MAX_RETRIES;
    int backoff_interval_ms = INITIAL_BACKOFF_INTERVAL_MS;

    NFAPI_CRC_INDICATION_PDU_T *pdus = generate_nfaapi_crc_indication_pdu(10, max_retries, backoff_interval_ms, &cache);

    if (pdus) {
        // Use the generated pdus...
        free(pdus);
    }

    return 0;
}
