} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the linked list.
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic array structure with thread safety mechanisms.
typedef struct {
    Node* head;
    pthread_mutex_t lock;  // Mutex for thread-safe operations
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->head = NULL;
    if (pthread_mutex_init(&array->lock, NULL) != 0) {
        free(array);
        return NULL; // Handle mutex initialization failure
    }
    return array;
}

bool add_structure(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false;

    new_node->data = new_data;
    new_node->next = NULL;

    pthread_mutex_lock(&array->lock);
    new_node->next = array->head;
    array->head = new_node;
    pthread_mutex_unlock(&array->lock);

    return true; // Successfully added
}

bool remove_structure(DynamicArray* array, unsigned int rnti) {
    Node *current = NULL, *prev = NULL;

    pthread_mutex_lock(&array->lock);
    current = array->head;

    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // RNTI not found
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    if (prev == NULL) {
        array->head = current->next; // Remove head node
    } else {
        prev->next = current->next;  // Bypass the current node
    }

    free(current);
    pthread_mutex_unlock(&array->lock);

    return true; // Successfully removed
}

bool update_crcflag(DynamicArray* array, unsigned int rnti, bool new_flag) {
    Node* current = NULL;

    pthread_mutex_lock(&array->lock);
    current = array->head;

    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }

    if (current == NULL) { // RNTI not found
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    current->data.crc_indication_rel8_tag.CRCFLAG = new_flag;

    pthread_mutex_unlock(&array->lock);

    return true; // Successfully updated
}

void free_dynamic_array(DynamicArray* array) {
    Node *current, *next_node;

    if (array == NULL) return;

    pthread_mutex_lock(&array->lock);
    current = array->head;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);

    free(array);
}

