#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STRUCTURES 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int validate_structure(const NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (structure->RX_UE_INFORMATION_TAG == 0 || structure->RNTI == 0)
        return -1; // Invalid RX_UE_INFORMATION_TAG or RNTI
    if (structure->CRC_INDICATION_REL8_TAG > 3)
        return -2; // Invalid CRC_INDICATION_REL8_TAG
    return 0;
}

void log_error(int error_code) {
    switch (error_code) {
        case -1:
            printf("Error: RX_UE_INFORMATION_TAG or RNTI is invalid.\n");
            break;
        case -2:
            printf("Error: CRC_INDICATION_REL8_TAG is out of range.\n");
            break;
        default:
            printf("Unknown error occurred.\n");
    }
}

void populate_structures(NFAPI_CRC_INDIGATION_PDU_T *structures, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 65535 + 1;
        structures[i].RNTI = rand() % 65535 + 1;
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 4;

        if (validate_structure(&structures[i]) != 0) {
            log_error(validate_structure(&structures[i]));
            exit(EXIT_FAILURE);
        }
    }
}

void write_structures(const NFAPI_CRC_INDIGATION_PDU_T *structures, size_t count,
                      const char *file_path, int binary_format) {

    FILE *file = fopen(file_path, binary_format ? "wb" : "w");
    if (!file) {
        perror("File opening failed");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        if (binary_format) {
            fwrite(&structures[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        } else {
            fprintf(file, "%hu %hu %hhu\n", structures[i].RX_UE_INFORMATION_TAG,
                    structures[i].RNTI, structures[i].CRC_INDICATION_REL8_TAG);
        }
    }

    if (ferror(file)) {
        perror("File writing failed");
    }

    fclose(file);
}

void manage_nfa_structures(const char *file_path, int binary_format) {
    NFAPI_CRC_INDIGATION_PDU_T *structures = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Memory allocation failed");
        return;
    }

    populate_structures(structures, MAX_STRUCTURES);

    write_structures(structures, MAX_STRUCTURES, file_path, binary_format);

    free(structures);
}

int main() {
    manage_nfa_structures("output.txt", 0); // Text format
    manage_nfa_structures("output.bin", 1); // Binary format

    return 0;
}
