#include <string.h>

typedef struct {
    int valid;       // Indicates if the frame is valid
    double SNR;      // Signal-to-Noise Ratio
    double RSSI;     // Received Signal Strength Indicator
} QualityMetrics;

typedef struct {
    int header[10];  // Example frame header structure
    char *demodBuffer;
    size_t demodBufferSize;
    QualityMetrics metrics;
} LTE_PHY_RX_FRAME;

// Simulated external service function for validating quality metrics.
int validate_quality_metrics(QualityMetrics metrics, double benchmarkSNR, double benchmarkRSSI) {
    return (metrics.SNR >= benchmarkSNR && metrics.RSSI >= benchmarkRSSI);
}

typedef struct {
    LTE_PHY_RX_FRAME *frames;
    size_t capacity;
    size_t count;
} FrameManager;

void init_frame(LTE_PHY_RX_FRAME *frame) {
    frame->valid = 0;
    memset(frame->header, 0, sizeof(frame->header));
    frame->demodBuffer = NULL;
    frame->demodBufferSize = 0;
    frame->metrics.SNR = -1.0; // Default invalid value
    frame->metrics.RSSI = -1.0;
}

int allocate_frame(FrameManager *manager, size_t bufferSize) {
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity > 0 ? manager->capacity * 2 : 16; // Start with initial capacity of 16
        LTE_PHY_RX_FRAME *newFrames = realloc(manager->frames, newCapacity * sizeof(LTE_PHY_RX_FRAME));
        if (!newFrames) return -1; // Memory allocation failure

        memset(newFrames + manager->count, 0, (newCapacity - manager->capacity) * sizeof(LTE_PHY_RX_FRAME));
        manager->frames = newFrames;
        manager->capacity = newCapacity;
    }

    LTE_PHY_RX_FRAME *frame = &manager->frames[manager->count++];
    frame->demodBuffer = malloc(bufferSize);
    if (!frame->demodBuffer) {
        // Handle memory allocation failure by cleaning up and returning an error
        manager->count--;
        return -1;
    }

    init_frame(frame);

    return 0; // Success
}

void free_frame_manager(FrameManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i].demodBuffer) {
            free(manager->frames[i].demodBuffer);
        }
    }
    free(manager->frames);
}

int process_frame(FrameManager *manager, size_t index, double benchmarkSNR, double benchmarkRSSI) {
    if (index >= manager->count) return -1; // Index out of bounds

    LTE_PHY_RX_FRAME *frame = &manager->frames[index];

    if (!frame->valid || frame->demodBuffer == NULL) return -2; // Frame not initialized properly

    // Simulate data integrity check
    if (strlen((char *)frame->demodBuffer) != frame->demodBufferSize) {
        return -3; // Data integrity issue detected
    }

    // Integrate with the external service for quality validation
    int valid = validate_quality_metrics(frame->metrics, benchmarkSNR, benchmarkRSSI);

    if (valid) {
        printf("Frame %zu validated successfully.\n", index);
    } else {
        printf("Frame %zu failed validation against benchmarks SNR: %.2f, RSSI: %.2f\n",
               index, benchmarkSNR, benchmarkRSSI);
    }

    return valid ? 0 : -4; // Return appropriate error code
}

int main() {
    FrameManager manager = {NULL, 0, 0};

    double benchmarkSNR = 10.0;
    double benchmarkRSSI = -80.0;

    if (allocate_frame(&manager, 1024) != 0) {
        printf("Failed to allocate frame.\n");
        free_frame_manager(&manager);
        return -1;
    }

    manager.frames[0].valid = 1;
    strcpy((char *)manager.frames[0].demodBuffer, "Valid Data"); // For simplicity
    manager.frames[0].metrics.SNR = 12.5; // Example valid SNR
    manager.frames[0].metrics.RSSI = -75.0; // Example valid RSSI

    if (process_frame(&manager, 0, benchmarkSNR, benchmarkRSSI) != 0) {
        printf("Failed to process frame.\n");
    }

    free_frame_manager(&manager);
    return 0;
}
