#include <string.h>

// Define constants for transform types
typedef enum {
    TRANSFORM_TYPE_A,
    TRANSFORM_TYPE_B
} TransformType;

typedef struct {
    TransformType type;
} PHY_TransformTag;

typedef struct {
    PHY_TransformTag tag;
    void *payloadData;
    size_t payloadSize;
} LTEPHY_TransformPdu;

// Error codes for the function
#define SUCCESS 0
#define ERROR_NULL_POINTER -1
#define ERROR_MEMORY_ALLOCATION -2
#define ERROR_INVALID_TRANSFORM_TYPE -3

int InitializeAndPopulateDynamicArray(
    LTEPHY_TransformPdu ***array,
    size_t *numElements,
    TransformType *transformTypes, // array of transform types for each element
    const void **payloadSources,   // array of payload data sources
    size_t *payloadSizes)          // array of payload sizes
{
    if (array == NULL || numElements == NULL || transformTypes == NULL ||
        payloadSources == NULL || payloadSizes == NULL) {
        return ERROR_NULL_POINTER;
    }

    *array = malloc(*numElements * sizeof(LTEPHY_TransformPdu *));
    if (*array == NULL) {
        return ERROR_MEMORY_ALLOCATION;
    }

    for (size_t i = 0; i < *numElements; ++i) {
        LTEPHY_TransformPdu *pdu = malloc(sizeof(LTEPHY_TransformPdu));
        if (pdu == NULL) {
            // Free already allocated memory in case of failure
            while (i > 0) {
                free((*array)[--i]);
            }
            free(*array);
            return ERROR_MEMORY_ALLOCATION;
        }

        pdu->tag.type = transformTypes[i];

        // Validate the transform type
        if (pdu->tag.type != TRANSFORM_TYPE_A && pdu->tag.type != TRANSFORM_TYPE_B) {
            free(pdu);
            while (--i > 0) {
                free((*array)[i]);
            }
            free(*array);
            return ERROR_INVALID_TRANSFORM_TYPE;
        }

        pdu->payloadData = malloc(payloadSizes[i]);
        if (pdu->payloadData == NULL) {
            free(pdu);
            while (i > 0) {
                free((*array)[--i]);
            }
            free(*array);
            return ERROR_MEMORY_ALLOCATION;
        }

        memcpy(pdu->payloadData, payloadSources[i], payloadSizes[i]);
        pdu->payloadSize = payloadSizes[i];

        (*array)[i] = pdu;
    }

    return SUCCESS;
}

