// Memory pool structure
typedef struct {
    size_t block_size;
    void *pool;
    size_t total_blocks;
    size_t used_blocks;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->used_blocks = 0;

    pool->pool = malloc(block_size * total_blocks);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (pool->used_blocks >= pool->total_blocks) return NULL;

    void* block = (char*)pool->pool + pool->used_blocks * pool->block_size;
    pool->used_blocks++;
    return block;
}

void free_memory_pool(MemoryPool* pool) {
    if (!pool) return;
    free(pool->pool);
    free(pool);
}

// Function to allocate and manage memory for NFAPI_CRC_INDICATION_PDU_T array
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(size_t N, MemoryPool** pool_ptr) {
    size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Initialize or expand the pool if necessary
    MemoryPool* pool;
    if (*pool_ptr == NULL || (*pool_ptr)->total_blocks < N) {
        pool = create_memory_pool(block_size, (N + 1023) / 1024 * 1024); // Allocate in chunks of 1MB
        if (!pool) return NULL;
        if (*pool_ptr != NULL) free_memory_pool(*pool_ptr);
        *pool_ptr = pool;
    } else {
        pool = *pool_ptr;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(pool);

    // Handle memory allocation failure
    if (!array) {
        fprintf(stderr, "Memory allocation failed for %zu structures\n", N);
        return NULL;
    }

    // Initialize the array with random data and monitoring logic
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < N; ++i) {
        ((NFAPI_CRC_INDICATION_PDU_T*)array)[i].ue_info_tag.tag = rand() % 100;
        ((NFAPI_CRC_INDICATION_PDU_T*)array)[i].rnti = rand();
        ((NFAPI_CRC_INDICATION_PDU_T*)array)[i].crc_ind_rel8_tag.CRCFLAG = rand() % 2;

        // Logging for monitoring
        printf("Allocated and initialized structure %zu\n", i);
    }

    return array;
}

// Example usage of the function
int main() {
    MemoryPool* pool = NULL;
    size_t N = 10000; // Example value

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = create_crc_indication_pdu_array(N, &pool);

    if (pdu_array) {
        printf("Successfully created array of %zu elements\n", N);

        // Free resources when done
        free_memory_pool(pool); 
    }

    return 0;
}
