#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
} DynamicArray;

void log_message(const char* message) {
    FILE *log_file = fopen("operation_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        free(array->array);
        free(array);
    }
}

int resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return 0;

    array->array = temp;
    array->capacity = new_capacity;

    return 1;
}

int populate_dynamic_array(DynamicArray* array, size_t n, int rnti_min, int rnti_max) {
    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        if (array->count == array->capacity && !resize_dynamic_array(array, array->capacity * 2)) {
            log_message("Error: Memory allocation failed.");
            return -1;
        }

        int rnti = rand() % (rnti_max + 1) + rnti_min;

        if (rnti < rnti_min || rnti > rnti_max) continue;

        array->array[array->count].RX_UE_INFORMATION_TAG = rand();
        array->array[array->count].RNTI = rnti;
        ++array->count;
    }

    return 0;
}

void filter_dynamic_array(DynamicArray* array, int rnti_min, int rnti_max) {
    size_t new_count = 0;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].RNTI >= rnti_min && array->array[i].RNTI <= rnti_max) {
            if (new_count != i) {
                array->array[new_count] = array->array[i];
            }
            new_count++;
        }
    }

    array->count = new_count;
}

int validate_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].RX_UE_INFORMATION_TAG == 0 || array->array[i].RNTI <= 0) {
            log_message("Validation error: Structure fields not correctly initialized.");
            return -1;
        }
    }

    return 0;
}

int export_to_file(const DynamicArray* array, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->count, file);
    fclose(file);

    log_message("Export completed successfully.");
    return 0;
}

void manage_dynamic_array(size_t n, int rnti_min, int rnti_max) {
    log_message("Operation started.");

    DynamicArray* array = init_dynamic_array(1000);
    if (!array) {
        log_message("Error: Failed to initialize dynamic array.");
        return;
    }

    clock_t start_time = clock();
    if (populate_dynamic_array(array, n, rnti_min, rnti_max) != 0) {
        destroy_dynamic_array(array);
        log_message("Operation failed during population.");
        return;
    }
    filter_dynamic_array(array, rnti_min, rnti_max);

    if (validate_dynamic_array(array) != 0) {
        destroy_dynamic_array(array);
        log_message("Validation failed post-population.");
        return;
    }

    export_to_file(array, "exported_data.bin");

    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    char operation_log[256];
    snprintf(operation_log, sizeof(operation_log), "Operation completed in %.2f seconds.", time_taken);
    log_message(operation_log);

    destroy_dynamic_array(array);
}
