#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <openssl/rand.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

#define BUFFER_SIZE 1024

NFAPI_CRC_INDICATION_PDU_T* generateAndProcessPDUList(int n, int option) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    for (int i = 0; i < n; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i].RNTI = rand() % 50000;
        RAND_bytes(pdus[i].CRC_INDICATION_REL8_TAG, sizeof(pdus[i].CRC_INDICATION_REL8_TAG));
    }

    int *input_numbers = malloc(BUFFER_SIZE * sizeof(int));
    if (!input_numbers) {
        free(pdus);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *filtered_pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!filtered_pdus) {
        free(input_numbers);
        free(pdus);
        return NULL;
    }

    int count = 0;
    pthread_t thread_id;

    void* process_input(void* arg) {
        int num, i = 0;
        while (scanf("%d", &num) == 1 && i < BUFFER_SIZE) {
            if (option == 1 || num % 2 == 0) {
                pthread_mutex_lock(&mutex);
                input_numbers[i++] = num;
                pthread_mutex_unlock(&mutex);
            }
        }
        return NULL;
    }

    pthread_create(&thread_id, NULL, process_input, NULL);
    pthread_join(thread_id, NULL);

    for (int i = 0; i < BUFFER_SIZE && count < n; ++i) {
        if (input_numbers[i] % 2 == 0 || option != 1) {
            filtered_pdus[count].RX_UE_INFORMATION_TAG = input_numbers[i];
            filtered_pdus[count].RNTI = rand() % 50000;
            RAND_bytes(filtered_pdus[count].CRC_INDICATION_REL8_TAG, sizeof(filtered_pdus[count].CRC_INDICATION_REL8_TAG));
            ++count;
        }
    }

    free(input_numbers);
    return filtered_pdus;
}
