// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a pseudo-random number generator with a seed
void init_random_generator(unsigned int seed) {
    srand(seed);
}

// Function to log the creation of each structure safely
void log_creation(int rnti, unsigned char crcflag) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&log_lock);
    printf("Generated NFAPI_CRC_INDICATION_PDU_T - RNTI: %lu, CRCFLAG: %d\n", rnti, crcflag);
    pthread_mutex_unlock(&log_lock);
}

// Function to dynamically create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int create_nfaapi_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T **pdu_list, size_t n, unsigned int seed) {
    // Initialize the random number generator with the provided seed
    init_random_generator(seed);

    // Allocate memory for the list of structures
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_list == NULL) {
        return -1; // Memory allocation failed
    }

    // Populate each structure with valid data
    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&lock); // Ensure thread-safe access to shared resources

        // Generate values and populate the structures
