#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRCFLAG; // Randomly set CRC flag
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} CRCList;

CRCList* init_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int generate_random_crc_flag() {
    srand(time(NULL) ^ (unsigned int)getpid());
    return rand() % 2; // Randomly 0 or 1
}

void add_structure(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL) {
        if ((*current)->data.RNTI == pdu.RNTI) break; // Avoid duplicate RNTI
        current = &(*current)->next;
    }

    if (*current == NULL) { // No duplicate found, add new node
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = pdu;
        newNode->next = NULL;
        *current = newNode;
        list->size++;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_structure(CRCList* list, size_t index) {
    if (index >= list->size) return; // Invalid index

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    for (size_t i = 0; i < index; ++i) {
        current = &(*current)->next;
    }

    Node* toDelete = *current;
    *current = (*current)->next;
    free(toDelete);
    list->size--;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_structure(CRCList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void initialize_list(CRCList* list, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 10000; // Example tag
        pdu.RNTI = rand() % 1000000 + 1; // Ensure non-zero RNTI
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crc_flag();

        add_structure(list, pdu);
    }
}

void free_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* toFree = current;
        current = current->next;
        free(toFree);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    size_t N = 10; // Example number of structures
    CRCList* list = init_list();

    initialize_list(list, N);

    unsigned int rnti_to_find = rand() % 1000000 + 1;
    NFAPI_CRC_INDICATION_PDU_T* pdu = retrieve_structure(list, rnti_to_find);
    if (pdu) {
        printf("Found PDU with RNTI: %u\n", pdu->RNTI);
    } else {
