#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define message structure
typedef struct {
    int id;
    int priority;
    char *data;
} Message;

// Node for the priority queue
typedef struct QueueNode {
    Message msg;
    struct QueueNode *next;
} QueueNode;

// Priority queue structure
typedef struct {
    QueueNode *head;
    pthread_mutex_t lock;
    int overflow_threshold;
    int underflow_threshold;
} PriorityQueue;

// Function prototypes
void initQueue(PriorityQueue *queue, int overflow_thresh, int underflow_thresh);
int enqueue(PriorityQueue *queue, Message msg);
Message dequeue(PriorityQueue *queue);
void processMessages(PriorityQueue *queue);
void monitorQueueHealth(PriorityQueue *queue);

// Initialize the priority queue
void initQueue(PriorityQueue *queue, int overflow_thresh, int underflow_thresh) {
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->overflow_threshold = overflow_thresh;
    queue->underflow_threshold = underflow_thresh;
}

// Enqueue a message based on priority
int enqueue(PriorityQueue *queue, Message msg) {
    pthread_mutex_lock(&queue->lock);

    QueueNode **tracer = &queue->head;
    while (*tracer && (*tracer)->msg.priority >= msg.priority) {
        tracer = &(*tracer)->next;
    }

    QueueNode *new_node = (QueueNode *)malloc(sizeof(QueueNode));
    new_node->msg = msg;
    new_node->next = *tracer;
    *tracer = new_node;

    if (queue->head && queue->head->next == NULL) {
        printf("Warning: Near overflow threshold\n");
    }

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

// Dequeue the highest priority message
Message dequeue(PriorityQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    if (!queue->head) {
        printf("Underflow detected\n");
        Message empty_msg = {-1, -1, NULL};
        pthread_mutex_unlock(&queue->lock);
        return empty_msg;
    }

    QueueNode *temp = queue->head;
    Message msg = temp->msg;
    queue->head = queue->head->next;
    free(temp);

    if (!queue->head) {
        printf("Warning: Near underflow threshold\n");
    }

    pthread_mutex_unlock(&queue->lock);
    return msg;
}

// Process messages in the queue
void processMessages(PriorityQueue *queue) {
    while (1) {
        Message msg = dequeue(queue);
        if (msg.id != -1) {
            printf("Processing message ID: %d\n", msg.id);
            free(msg.data); // Assume data is dynamically allocated
        }
    }
}

// Monitor queue health and performance metrics
void monitorQueueHealth(PriorityQueue *queue) {
    while (1) {
        pthread_mutex_lock(&queue->lock);
        int size = 0;
        QueueNode *current = queue->head;
        while (current) {
            size++;
            current = current->next;
        }
        printf("Current queue size: %d\n", size);

        // Add more monitoring logic as needed
        pthread_mutex_unlock(&queue->lock);
        sleep(1); // Adjust the interval as necessary
    }
}

// Example usage
int main() {
    PriorityQueue queue;
    initQueue(&queue, 10, 2);

    Message msg1 = {1, 5, strdup("Message 1")};
    Message msg2 = {2, 3, strdup("Message 2")};

    enqueue(&queue, msg1);
    enqueue(&queue, msg2);

    pthread_t process_thread, monitor_thread;
    pthread_create(&process_thread, NULL, (void *)processMessages, &queue);
    pthread_create(&monitor_thread, NULL, (void *)monitorQueueHealth, &queue);

    pthread_join(process_thread, NULL);
    pthread_join(monitor_thread, NULL);

    return 0;
}
