#include <stdio.h>
#include <stdlib.h>
import time.h

typedef struct {
    int timestamp;
    int payload_length;
    int unique_id;
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
} PacketList;

void init_packet_list(PacketList* list) {
    list->head = NULL;
    list->size = 0;
}

Node* create_node(DataPacket packet) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->packet = packet;
    new_node->next = NULL;
    return new_node;
}

void add_packet(PacketList* list, DataPacket packet) {
    Node* new_node = create_node(packet);
    if (!new_node) return;

    // Insert at the head for O(1) insertion time
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
}

Node* find_packet_by_id(PacketList* list, int unique_id) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->packet.unique_id == unique_id) {
            return current;
        }
        current = current->next;
    }
    return NULL; // Not found
}

void remove_packet_by_id(PacketList* list, int unique_id) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->packet.unique_id == unique_id) {
            if (prev == NULL) { // Removing head node
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->size--;
            return; // Exit after removing the packet
        }
        prev = current;
        current = current->next;
    }
}

Node* retrieve_packet_by_timestamp(PacketList* list, int timestamp) {
    Node* current = list->head;

    while (current != NULL) {
        if (current->packet.timestamp == timestamp) {
            return current; // Found
        }
        current = current->next;
    }
    return NULL; // Not found
}

// Simulate interaction with external data processing service
int process_packet_with_external_service(DataPacket packet) {
    // Simulating variable response times and potential downtime
    int success = rand() % 2; // Randomly simulate failure or success
    if (success) {
        printf("Packet processed successfully: ID %d\n", packet.unique_id);
    } else {
        printf("Failed to process packet: ID %d\n", packet.unique_id);
    }
    return success;
}

void manage_packet(PacketList* list, DataPacket packet, int action) {
    // Action codes: 1 for add, 2 for remove, 3 for retrieve
    switch (action) {
        case 1:
            add_packet(list, packet);
            break;
        case 2:
            remove_packet_by_id(list, packet.unique_id);
            break;
        case 3:
            Node* result = retrieve_packet_by_timestamp(list, packet.timestamp);
            if (result != NULL) {
                // Process packet with external service
                process_packet_with_external_service(result->packet);
            } else {
                printf("Packet not found for timestamp: %d\n", packet.timestamp);
            }
            break;
        default:
            printf("Invalid action code.\n");
    }
}

void free_packet_list(PacketList* list) {
    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->size = 0;
}

int main() {
    PacketList packet_list;
    init_packet_list(&packet_list);

    // Example operations
    DataPacket new_packet = {time(NULL), 100, 1};
    manage_packet(&packet_list, new_packet, 1); // Add

    new_packet.timestamp = time(NULL) + 10; 
    new_packet.payload_length = 200;
    new_packet.unique_id = 2;
    manage_packet(&packet_list, new_packet, 1); // Add

    DataPacket remove_packet = {0, 0, 1};
    manage_packet(&packet_list, remove_packet, 2); // Remove by ID

    DataPacket retrieve_packet = {new_packet.timestamp, 0, 0};
    manage_packet(&packet_list, retrieve_packet, 3); // Retrieve and process

    free_packet_list(&packet_list);

    return 0;
}
