#include <stdatomic.h>

typedef struct {
    int pusch_dm_rs_config;
    int pucch_resource_indicator;
    int quality_indicator; // Dynamically calculated based on signal strength
} LTEPHYRACHIndication_t;

typedef struct Node {
    LTEPHYRACHIndication_t data;
    atomic_intptr_t next;
} Node;

// Dynamic array-based implementation for better cache locality and memory overhead trade-off
typedef struct {
    Node *array;
    atomic_size_t size;
    atomic_size_t capacity;
    _Atomic int lock; // For managing concurrent access, assuming a simple spinlock or similar mechanism
} LTEPHYRACHDynamicArray_t;

LTEPHYRACHDynamicArray_t* init_array(size_t initial_capacity) {
    LTEPHYRACHDynamicArray_t *arr = (LTEPHYRACHDynamicArray_t*)malloc(sizeof(LTEPHYRACHDynamicArray_t));
    arr->array = (Node*)calloc(initial_capacity, sizeof(Node));
    atomic_store(&arr->size, 0);
    atomic_store(&arr->capacity, initial_capacity);
    atomic_store(&arr->lock, 0); // Assuming 0 is unlocked
    return arr;
}

void resize_array(LTEPHYRACHDynamicArray_t *arr) {
    size_t new_capacity = atomic_load(&arr->capacity) * 2;
    Node *new_array = (Node*)realloc(arr->array, new_capacity * sizeof(Node));
    if (new_array != NULL) {
        arr->array = new_array;
        atomic_store(&arr->capacity, new_capacity);
    }
}

void insert_element(LTEPHYRACHDynamicArray_t *arr, LTEPHYRACHIndication_t element) {
    while (__sync_lock_test_and_set(&arr->lock, 1)) {} // Acquire lock
    if (atomic_load(&arr->size) == atomic_load(&arr->capacity)) {
        resize_array(arr);
    }
    size_t index = atomic_fetch_add(&arr->size, 1);
    arr->array[index].data = element;
    arr->array[index].next = ATOMIC_VAR_INIT((intptr_t)NULL); // Ensure next is set to NULL
    __sync_lock_release(&arr->lock); // Release lock
}

void remove_element(LTEPHYRACHDynamicArray_t *arr, size_t index) {
    while (__sync_lock_test_and_set(&arr->lock, 1)) {} // Acquire lock
    if (index < atomic_load(&arr->size)) {
        for (size_t i = index; i < atomic_load(&arr->size) - 1; ++i) {
            arr->array[i] = arr->array[i + 1];
        }
        atomic_fetch_sub(&arr->size, 1);
    }
    __sync_lock_release(&arr->lock); // Release lock
}

void free_array(LTEPHYRACHDynamicArray_t *arr) {
    while (__sync_lock_test_and_set(&arr->lock, 1)) {} // Acquire lock for safe deallocation
    free(arr->array);
    arr->array = NULL;
    atomic_store(&arr->size, 0);
    atomic_store(&arr->capacity, 0);
    __sync_lock_release(&arr->lock); // Release lock
    free(arr);
}

// Example usage:
// LTEPHYRACHDynamicArray_t* myArray = init_array(10);
// insert_element(myArray, someLTEPHYRACHIndication);
// remove_element(myArray, 0);
// free_array(myArray);

