void destroy_pool(PoolAllocator *allocator) {
    free(allocator->pool);
    pthread_mutex_destroy(&allocator->lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(PoolAllocator *allocator) {
    pthread_mutex_lock(&allocator->lock);

    if (allocator->count >= allocator->capacity) {
        pthread_mutex_unlock(&allocator->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &allocator->pool[allocator->count++];
    pdu->RX_UE_INFORMATION_TAG = rand() % 65536; // Random value for example
    pdu->RNTI = rand() % 4294967296U; // Random value for example
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&allocator->lock);
    return pdu;
}

void release_pdu(PoolAllocator *allocator, NFAPI_CRC_INDICATION_PDU_T *pdu) {
