    if (!allocator || !plugin_func) return;

    pthread_mutex_lock(&allocator->lock);

    for (size_t i = 0; i < allocator->count; ++i) {
        plugin_func(&allocator->pool[i]);
    }

    pthread_mutex_unlock(&allocator->lock);
}

