#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_POOL_SIZE 1024
#define ALIGNMENT 8

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint32_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
} PoolNode;

typedef struct {
    PoolNode* head;
    PoolNode* tail;
    size_t count;
    pthread_mutex_t mutex;
} PooledData;

PooledData pool = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};

int initialize_pool() {
    return 0; // No initialization needed for this simple pool
}

int allocate_pooled_data(PooledData* pool) {
    if (pool->count >= MAX_POOL_SIZE) {
        return -1; // Denial of service prevention
    }

    PoolNode* node = (PoolNode*)malloc(sizeof(PoolNode));
    if (!node) {
        return -2; // Memory allocation failure
    }

    pthread_mutex_lock(&pool->mutex);

    node->next = NULL;
    node->data.RX_UE_INFORMATION_TAG = rand() % 65536;
    node->data.RNTI = rand() % 65536;
    node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set to 0 or 1

    if (pool->head == NULL) {
        pool->head = node;
    } else {
        pool->tail->next = node;
    }
    pool->tail = node;
    pool->count++;

    pthread_mutex_unlock(&pool->mutex);

    return 0;
}

int deallocate_pooled_data(PooledData* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->mutex);

    PoolNode *current = pool->head, *prev = NULL;

    while (current != NULL && memcmp(&(current->data), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Not found
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    if (prev == NULL) { // Head is to be removed
        pool->head = current->next;
    } else {
        prev->next = current->next;
    }

    if (current == pool->tail) {
        pool->tail = prev;
    }

    free(current);
    pool->count--;

    pthread_mutex_unlock(&pool->mutex);

    return 0;
}

void test_pool_management() {
    initialize_pool();

    // Test allocation
    for (int i = 0; i < MAX_POOL_SIZE + 5; ++i) {
        int ret = allocate_pooled_data(&pool);
        if (ret != 0) {
            printf("Allocation failed: %d\n", ret);
        }
    }

    // Test deallocation
    PoolNode* head = pool.head;
    for (int i = 0; i < MAX_POOL_SIZE; ++i) {
        deallocate_pooled_data(&pool, &(head->data));
        if (head) {
            head = head->next;
        }
    }

    // Test underflow
    int ret = deallocate_pooled_data(&pool, &(NFAPI_CRC_INDICATION_PDU_T){0});
    printf("Deallocate non-existing: %d\n", ret);
}

int main() {
    test_pool_management();
    return 0;
}
