#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1000 // Configurable limit

typedef struct {
    char source_ip[16];
    char dest_ip[16];
    unsigned short source_port;
    unsigned short dest_port;
    time_t timestamp;
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T *records;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t lock;
    int (*alert_callback)(int); // Callback for alerts
} ConnectionManager;

ConnectionManager* create_connection_manager(size_t initial_size, int (*alert_callback)(int)) {
    ConnectionManager *manager = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->records = (TCP_CONNECTION_RECORD_T *)calloc(initial_size, sizeof(TCP_CONNECTION_RECORD_T));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->current_size = 0;
    manager->max_size = initial_size;
    pthread_mutex_init(&manager->lock, NULL);
    manager->alert_callback = alert_callback;

    return manager;
}

void destroy_connection_manager(ConnectionManager *manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_connection(ConnectionManager *manager, const TCP_CONNECTION_RECORD_T *record) {
    if (!manager || !record) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->current_size >= manager->max_size) {
        if (manager->alert_callback) manager->alert_callback(1); // Alert for max capacity
        pthread_mutex_unlock(&manager->lock);
        return -2; // Max connections reached
    }

    manager->records[manager->current_size++] = *record;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void adjust_max_connections(ConnectionManager *manager, size_t new_max) {
    if (!manager || new_max < manager->current_size) return;

    pthread_mutex_lock(&manager->lock);

    TCP_CONNECTION_RECORD_T *new_records = (TCP_CONNECTION_RECORD_T *)realloc(manager->records, new_max * sizeof(TCP_CONNECTION_RECORD_T));
    if (new_records) {
        manager->max_size = new_max;
        manager->records = new_records;
    } else if (manager->alert_callback) {
        manager->alert_callback(2); // Alert for allocation failure
    }

    pthread_mutex_unlock(&manager->lock);
}

int alert_example(int code) {
    printf("Alert Code: %d\n", code);
    return 0;
}

void monitor_usage(ConnectionManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    // Example monitoring logic
    printf("Current Connections: %zu, Max Allowed: %zu\n", manager->current_size, manager->max_size);

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    ConnectionManager *manager = create_connection_manager(10, alert_example);
    if (!manager) {
        fprintf(stderr, "Failed to create connection manager.\n");
        return 1;
    }

    TCP_CONNECTION_RECORD_T record = {"192.168.0.1", "192.168.0.2", 12345, 80, time(NULL)};
    add_connection(manager, &record);

    adjust_max_connections(manager, 20);
    monitor_usage(manager);

    destroy_connection_manager(manager);
    return 0;
}
```

This code provides a basic framework for managing TCP connection records with thread safety and dynamic resizing. It includes an alert mechanism for monitoring resource usage and potential bottlenecks. Adjust the `MAX_CONNECTIONS` and other parameters as needed to fit your specific requirements.']

