// Node for the linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *next;
} ListNode;

// Iterator structure
typedef struct {
    ListNode *current;
} ListIterator;

// Function prototypes
ListNode* create_node(uint16_t rx_ue_information_tag, uint16_t rnti);
int insert_node(ListNode **head, ListNode *new_node);
void free_list(ListNode *head);
ListIterator* list_iterator_create(ListNode *head);
ListNode* list_iterator_next(ListIterator *iterator);

// Main function to demonstrate functionality
int main() {
    // Example usage
    ListNode *head = NULL;
    uint16_t rnti_set[100];  // Assume a maximum of 100 unique RNTIs for simplicity

    srand(time(NULL)); // Seed random number generator

    // Populate list with example data
    for (uint16_t i = 0; i < 10; ++i) {
        uint16_t rx_ue_info_tag = rand() % 256;
        uint16_t rnti;

        do {
            rnti = rand() % 65536;
        } while (rnti == ((i > 0) ? head->data.RNTI : 0) || bsearch(&rnti, rnti_set, i, sizeof(uint16_t), cmp_uint16));

        // Insert in set if unique
        memcpy(rnti_set + i, &rnti, sizeof(uint16_t));

        ListNode *new_node = create_node(rx_ue_info_tag, rnti);
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            free_list(head);
            return EXIT_FAILURE;
        }

        if (!insert_node(&head, new_node)) {
            fprintf(stderr, "Failed to insert node due to duplicate RNTI or consecutive same RNTI\n");
            free(new_node); // Free the newly allocated memory
            free_list(head);
            return EXIT_FAILURE;
        }
    }

    // Traverse and print list using iterator
    ListIterator *iterator = list_iterator_create(head);
    while (ListNode *node = list_iterator_next(iterator)) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %u\n",
               node->data.RX_UE_INFORMATION_TAG,
               node->data.RNTI,
               node->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    // Cleanup
    free(iterator);
    free_list(head);

    return EXIT_SUCCESS;
}

ListNode* create_node(uint16_t rx_ue_information_tag, uint16_t rnti) {
    ListNode *node = (ListNode *)malloc(sizeof(ListNode));
    if (!node) return NULL;

    node->data.RX_UE_INFORMATION_TAG = rx_ue_information_tag;
    node->data.RNTI = rnti;
    node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
    node->next = NULL;

    return node;
}

int insert_node(ListNode **head, ListNode *new_node) {
    if (!*head) {
        *head = new_node;
        return 1;
    }

    ListNode *current = *head;
    while (current->next && current->data.RNTI != new_node->data.RNTI) {
        if (current->next->data.RNTI == new_node->data.RNTI || 
            current->data.RNTI == new_node->data.RNTI) {
            return 0; // Duplicate RNTI or consecutive same RNTI
        }
        current = current->next;
    }

    if (current->next && current->next->data.RNTI == new_node->data.RNTI) {
        return 0; // Consecutive node with the same RNTI
    }

    new_node->next = current->next;
    current->next = new_node;

    return 1;
}

void free_list(ListNode *head) {
    ListNode *tmp;
    while (head) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

ListIterator* list_iterator_create(ListNode *head) {
    ListIterator *iterator = (ListIterator *)malloc(sizeof(ListIterator));
    if (!iterator) return NULL;

    iterator->current = head;
    return iterator;
}

ListNode* list_iterator_next(ListIterator *iterator) {
    ListNode *node = iterator->current;
    if (node) {
        iterator->current = node->next;
    }
    return node;
}

int cmp_uint16(const void *a, const void *b) {
    uint16_t arg1 = *(const uint16_t *)a;
    uint16_t arg2 = *(const uint16_t *)b;

    return (arg1 > arg2) - (arg1 < arg2);
}
```

This code implements a linked list with the necessary constraints and includes an iterator for efficient traversal. The memory management ensures no leaks, even on allocation failure, while maintaining uniqueness and non-consecutive RNTI rules.']

