#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 50000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    double SNR_MEASUREMENT;
} NFAPI_RX_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_RX_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int successful_allocations;
    int failed_allocations;
} ListManager;

ListManager list_manager = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0};

int unique_identifier(const NFAPI_RX_INDICATION_PDU_T* pdu) {
    return (pdu->RNTI << 16) | ((int)(pdu->SNR_MEASUREMENT * 1000));
}

Node* create_node(const NFAPI_RX_INDICATION_PDU_T* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        list_manager.failed_allocations++;
        return NULL;
    }
    new_node->data = *pdu;
    new_node->next = NULL;
    list_manager.successful_allocations++;
    return new_node;
}

void add_pdu(const NFAPI_RX_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list_manager.lock);

    Node* current = list_manager.head;
    int identifier = unique_identifier(pdu);

    while (current) {
        if (unique_identifier(&(current->data)) == identifier) {
            pthread_mutex_unlock(&list_manager.lock);
            return; // Identifier already exists
        }
        current = current->next;
    }

    Node* new_node = create_node(pdu);
    if (!new_node) {
        pthread_mutex_unlock(&list_manager.lock);
        return; // Memory allocation failed
    }

    new_node->next = list_manager.head;
    list_manager.head = new_node;

    pthread_mutex_unlock(&list_manager.lock);
}

void get_statistics(int* successful, int* failed) {
    pthread_mutex_lock(&list_manager.lock);

    *successful = list_manager.successful_allocations;
    *failed = list_manager.failed_allocations;

    pthread_mutex_unlock(&list_manager.lock);
}

