FramePool* frame_pool_create(size_t initial_capacity) {
    FramePool *pool = (FramePool*)malloc(sizeof(FramePool));
    if (!pool) return NULL;

    pool->frames = (LTE_PHY_RX_FRAME*)malloc(initial_capacity * sizeof(LTE_PHY_RX_FRAME));
    if (!pool->frames) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void frame_pool_destroy(FramePool *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->frames);
        free(pool);
    }
}

int frame_pool_add(FramePool *pool, int LAYER2_PDU, long timestamp, float SNR) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->frames[i].timestamp == timestamp && pool->frames[i].SNR == SNR)
            goto unlock;
    }

    if (pool->count >= pool->capacity) {
