#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

typedef struct {
    unsigned int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned char CRCFLAG : 1; // Only one bit needed for a flag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    unsigned char metadata[MD5_DIGEST_LENGTH];
} NAS_PDU_STRUCTURE;

void generateNFARewithCRCIndication(int N, const char *metadataStr, int rnti, int seed) {
    if (N <= 0 || metadataStr == NULL) return;

    // Seed the random number generator
    srand(seed);

    // Allocate memory for the array of NAS PDU structures
    NAS_PDU_STRUCTURE *nasPduArray = (NAS_PDU_STRUCTURE *)malloc(N * sizeof(NAS_PDU_STRUCTURE));
    if (!nasPduArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Compute the MD5 hash of the metadata string
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)metadataStr, strlen(metadataStr), md5Hash);

    for (int i = 0; i < N; ++i) {
        nasPduArray[i].rxUeInformationTag.rnti = rnti;
        nasPduArray[i].crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Randomly set CRC flag
        memcpy(nasPduArray[i].metadata, md5Hash, MD5_DIGEST_LENGTH);
    }

    // Example usage or further processing can be done here

    // Free the allocated memory when done
    free(nasPduArray);
}

int main() {
    generateNFARewithCRCIndication(10, "example metadata", 12345, 42);
    return 0;
}
```

