        if (!newNode) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        newNode->transportFormat = indication;
        newNode->next = NULL;

        pthread_mutex_lock(&listMutex);

        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }

        pthread_mutex_unlock(&listMutex);
    }

    return head;
