    pthread_cond_init(&list->cond, NULL);
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->items = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
}

// Free the dynamic list
