    free(list->items);
    pthread_mutex_unlock(&list->lock);
    pthread_cond_destroy(&list->cond);
    pthread_mutex_destroy(&list->lock);
}

// Add a unique RNTI to the list
int addUniqueRNTI(CRCList *list, unsigned int rnti) {
    if (!isValidRNTI(rnti)) return -1;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i].rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Collision detected
        }
    }

    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newItems = realloc(list->items, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
        if (!newItems) {
            pthread_mutex_unlock(&list->lock);
            return -3; // Memory allocation failure
        }
        list->capacity = newCapacity;
        list->items = newItems;
    }

    list->items[list->count++] = (NFAPI_CRC_INDICATION_PDU_T){.rnti = rnti};
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Create an indication with a random CRC flag
