} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T* messages;
    size_t size;
    size_t capacity;
} DynamicArray;

void init_dynamic_array(DynamicArray* array) {
    array->size = 0;
    array->capacity = 10; // Initial capacity
    array->messages = malloc(sizeof(NFAPI_MESSAGE_T) * array->capacity);
}

bool resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    NFAPI_MESSAGE_T* resized_messages = realloc(array->messages, sizeof(NFAPI_MESSAGE_T) * new_capacity);
    if (!resized_messages) return false;
    array->messages = resized_messages;
    array->capacity = new_capacity;
    return true;
}

void add_entry(DynamicArray* array, unsigned int rnti) {
    if (array->size >= array->capacity && !resize_dynamic_array(array, array->capacity * 2)) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    array->messages[array->size].rx_ue_information_tag.RNTI = rnti;
    srand(time(NULL) + (unsigned int)rnti); // Seed with RNTI for variability
    array->messages[array->size].rx_ue_information_tag.crc_indication_rel8_tag.CRCFLAG = rand() % 2 == 0;

    array->size++;
}

bool remove_entry(DynamicArray* array, unsigned int rnti) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i].rx_ue_information_tag.RNTI == rnti) {
            memmove(&array->messages[i], &array->messages[i + 1], 
                    sizeof(NFAPI_MESSAGE_T) * (array->size - i - 1));
            array->size--;
            return true;
        }
    }
    return false;
}

bool update_crc_status(DynamicArray* array, unsigned int rnti, bool new_crc_flag) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i].rx_ue_information_tag.RNTI == rnti) {
            array->messages[i].rx_ue_information_tag.crc_indication_rel8_tag.CRCFLAG = new_crc_flag;
            return true;
        }
    }
    return false;
}

void free_dynamic_array(DynamicArray* array) {
    free(array->messages);
    array->messages = NULL;
    array->size = 0;
    array->capacity = 0;
}
