    size_t capacity;
    int resourceLimit;
} ResourcePool;

// Error codes
#define SUCCESS 0
#define INVALID_CONFIG -1
#define MEMORY_ALLOCATION_FAILED -2
#define RESOURCE_LIMIT_EXCEEDED -3

void init_random_seed(unsigned int seed) {
    srand(seed);
}

int validate_configuration(LTE_RADIORESOURCECONFIGDEDICATED config, LTE_RADIORESOURCECONFIGDEDICATED* allowedConfigs, size_t numAllowed) {
    for (size_t i = 0; i < numAllowed; ++i) {
        if (config.id == allowedConfigs[i].id) {
            return SUCCESS;
        }
    }
    return INVALID_CONFIG;
}

ResourcePool* create_resource_pool(size_t initialCapacity, int resourceLimit) {
    ResourcePool* pool = malloc(sizeof(ResourcePool));
    if (!pool) return NULL;

    pool->configs = calloc(initialCapacity, sizeof(LTE_UERadioResourceConfigDedicated));
    if (!pool->configs) {
        free(pool);
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initialCapacity;
    pool->resourceLimit = resourceLimit;

    return pool;
}

void resize_pool(ResourcePool* pool, size_t newCapacity) {
    LTE_UERadioResourceConfigDedicated* newConfigs = realloc(pool->configs, newCapacity * sizeof(LTE_UERadioResourceConfigDedicated));
    if (!newConfigs) return; // Handle memory allocation failure gracefully

    pool->configs = newConfigs;
    pool->capacity = newCapacity;
}

int add_configuration(ResourcePool* pool, LTE_RADIORESOURCECONFIGDEDICATED* allowedConfigs, size_t numAllowed, unsigned int seed) {
    if (pool->size >= pool->resourceLimit) return RESOURCE_LIMIT_EXCEEDED;

    if (pool->size == pool->capacity) {
        resize_pool(pool, pool->capacity * 2);
        if (!pool->configs) return MEMORY_ALLOCATION_FAILED;
    }

    LTE_UERadioResourceConfigDedicated* config = &pool->configs[pool->size];
    config->RRC_CONFIGURATION_VERSION = pool->size + 1; // Unique version
    config->RRC_RELEASE = rand() % 10; // Example release value

    config->lteRadioResourceConfigList = malloc(sizeof(LTE_UE_RADIORESOURCECONFIGDEDI_LIST));
    if (!config->lteRadioResourceConfigList) return MEMORY_ALLOCATION_FAILED;

    int configId = allowedConfigs[rand() % numAllowed].id;
    config->lteRadioResourceConfigList->config = &allowedConfigs[configId];

    pool->size++;
    return SUCCESS;
}

void free_resource_pool(ResourcePool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->configs[i].lteRadioResourceConfigList);
    }
    free(pool->configs);
    free(pool);
}

int manage_radio_resources(size_t M, int resourceLimit, LTE_RADIORESOURCECONFIGDEDICATED* allowedConfigs, size_t numAllowed, unsigned int seed) {
    init_random_seed(seed);

    ResourcePool* pool = create_resource_pool(10, resourceLimit);
    if (!pool) return MEMORY_ALLOCATION_FAILED;

    for (size_t i = 0; i < M; ++i) {
        int result = add_configuration(pool, allowedConfigs, numAllowed, seed);
        if (result != SUCCESS) {
            free_resource_pool(pool);
            return result;
        }
    }

    // Logging and monitoring placeholder
    printf("Pool size: %zu\n", pool->size);

    free_resource_pool(pool);
    return SUCCESS;
}

int main() {
