['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDUS 10000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

bool is_rnti_unique(uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T *pdus, int count) {
    for (int i = 0; i < count; ++i) {
        if (pdus[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

void log_duplicate_rnti(uint16_t rnti) {
    printf("Duplicate RNTI detected: %u\n", rnti);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdus(int num_pdus, int *result_count) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator
    int count = 0;

    for (int i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        pthread_mutex_lock(&mutex);
        pdu.RX_UE_INFORMATION_TAG = rand() % UINT16_MAX + 1; // Avoid zero
        pdu.RNTI = rand() % UINT16_MAX + 1; // Avoid zero

        if (!is_rnti_unique(pdu.RNTI, pdus, count)) {
            log_duplicate_rnti(pdu.RNTI);
            pthread_mutex_unlock(&mutex);
            continue;
        }

        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG: 0 or 1

        if (count < num_pdus) {
            pdus[count] = pdu;
            ++count;
        }

        pthread_mutex_unlock(&mutex);
    }

    *result_count = count;

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus) {
        free(pdus);
    }
}
```

