    NFAPI_CRC_INDICATION_PDU_T data;
    struct NFAPI_CRC_INDICATION_NODE *next;
} NFAPI_CRC_INDICATION_NODE;

#define HASH_TABLE_SIZE 1024

NFAPI_CRC_INDICATION_NODE* hash_table[HASH_TABLE_SIZE];
pthread_mutex_t table_locks[HASH_TABLE_SIZE];

// Hash function for RNTI
unsigned int hash_rnti(uint32_t rnti) {
    return rnti % HASH_TABLE_SIZE;
}

// Initialize the system and mutexes
void initialize_system() {
    srand(time(NULL));  // Seed for random number generation

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_mutex_init(&table_locks[i], NULL);
    }
}

// Function to add NFAPI_CRC_INDICATION_PDU_T structure to the list
void add_crc_indication_pdu(uint32_t rnti, NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned int index = hash_rnti(rnti);

    pthread_mutex_lock(&table_locks[index]);

    // Check for existing RNTI and handle duplicates by updating
    NFAPI_CRC_INDICATION_NODE *current = hash_table[index];
    while (current != NULL) {
        if (current->rnti == rnti) {
            current->data = pdu;
            pthread_mutex_unlock(&table_locks[index]);
            return;  // RNTI updated, exit
        }
        current = current->next;
    }

    // Create new node if no existing RNTI found
    NFAPI_CRC_INDICATION_NODE *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_NODE));
    if (!new_node) {
        pthread_mutex_unlock(&table_locks[index]);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_node->rnti = rnti;
    new_node->data = pdu;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    pthread_mutex_unlock(&table_locks[index]);
}

// Function to manage the list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indications() {
    for (int i = 0; i < 10000; ++i) { // Example loop, can be adjusted based on load
        uint32_t rnti;
        if (fetch_rnti_from_api(&rnti)) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.ue_info_tag.RNTI = rnti;

            // Set CRCFLAG randomly with consistent seed
            srand(rnti + i);
            pdu.crc_indication_rel8_tag.CRCFLAG = rand() % 2;

            add_crc_indication_pdu(rnti, pdu);
        } else {
            // Implement retry logic with exponential backoff if needed
        }
    }
}

// Function to serialize the data structure to a binary file
void serialize_to_file(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&table_locks[i]);

        NFAPI_CRC_INDICATION_NODE *node = hash_table[i];
        while (node != NULL) {
            fwrite(&(node->rnti), sizeof(uint32_t), 1, file);
            fwrite(&(node->data.ue_info_tag.RNTI), sizeof(node->data.ue_info_tag.RNTI), 1, file);
            fwrite(&(node->data.crc_indication_rel8_tag.CRCFLAG), sizeof(node->data.crc_indication_rel8_tag.CRCFLAG), 1, file);

            node = node->next;
        }

        pthread_mutex_unlock(&table_locks[i]);
    }

    fclose(file);
}

int main() {
    initialize_system();
    manage_crc_indications();
    serialize_to_file("crc_data.bin");

    return 0;
}
