#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

#define MAX_TOTAL_COUNT 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    size_t current_count;
} NFAPI_CRC_LIST;

NFAPI_CRC_LIST* create_crc_list() {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->current_count = 0;
    return list;
}

void free_crc_list(NFAPI_CRC_LIST* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int allocate_pdu(NFAPI_CRC_LIST* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (!list || list->current_count >= MAX_TOTAL_COUNT)
        return -1;

    pthread_mutex_lock(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Simulate a probabilistic algorithm for CRCFLAG
    new_node->data.CRCFLAG = (rand() % 10) < 3 ? 1 : 0; // Example probability

    new_node->next = list->head;
    list->head = new_node;
    list->current_count++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void report_memory_usage(NFAPI_CRC_LIST* list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);

    printf("Current CRC List Count: %zu\n", list->current_count);

    Node* current = list->head;
    while (current) {
        // Example reporting of each node's data
        printf("RNTI: %d, CRCFLAG: %d\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

int main() {
    NFAPI_CRC_LIST* list = create_crc_list();
    if (!list) {
        fprintf(stderr, "Failed to create CRC list\n");
        return -1;
    }

    // Example usage
    for (int i = 0; i < 10; ++i) {
        int result = allocate_pdu(list, i, i * 100, i * 200);
        if (result != 0) {
            fprintf(stderr, "Failed to allocate PDU\n");
            free_crc_list(list);
            return -1;
        }
    }

    report_memory_usage(list);

    free_crc_list(list);
    return 0;
}
