#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdatomic.h>

typedef struct {
    // Placeholder for actual structure definition.
} RX_UE_INFORMATION_TAG;

typedef uint16_t RNTI;

typedef struct {
    _Atomic int CRCFLAG;  // Atomic to ensure thread-safe updates
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t timestamp;  // For age-based cleanup
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
    size_t node_count;
    time_t expiration_threshold; // Time in seconds after which entries are considered expired
} CRC_LIST;

CRC_LIST* initialize_crc_list(time_t expiration_threshold) {
    CRC_LIST* list = malloc(sizeof(CRC_LIST));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for CRC_LIST\n");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->node_count = 0;
    list->expiration_threshold = expiration_threshold;

    // Spawn a thread to handle cleanup
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, cleanup_expired_entries, list) != 0) {
        fprintf(stderr, "Failed to create cleanup thread\n");
        free(list);
        return NULL;
    }
    pthread_detach(cleanup_thread);

    return list;
}

void* cleanup_expired_entries(void *arg) {
    CRC_LIST *list = (CRC_LIST *) arg;
    while (1) {
        time_t current_time = time(NULL);
        pthread_mutex_lock(&list->lock);

        NFAPI_CRC_INDICATION_PDU_T **tracer = &(list->head);
        while (*tracer != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *entry = *tracer;
            if (difftime(current_time, entry->timestamp) > list->expiration_threshold) {
                *tracer = entry->next;  // Remove the node
                free(entry);
                --list->node_count;
            } else {
                tracer = &((*tracer)->next);  // Move to next node
            }
        }

        pthread_mutex_unlock(&list->lock);
        sleep(1);  // Sleep for a short duration before next cleanup cycle
    }
}

void insert_crc_entry(CRC_LIST *list, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return;
    }

    // Populate the new node
    new_node->rx_ue_information_tag = rx_ue_information_tag;
    new_node->rnti = rnti;
    atomic_store(&new_node->crc_indication_rel8_tag.CRCFLAG, rand() % 2); // Randomly set CRCFLAG
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    ++list->node_count;

    pthread_mutex_unlock(&list->lock);
}

void log_metrics(CRC_LIST *list) {
    pthread_mutex_lock(&list->lock);

    printf("Current node count: %zu\n", list->node_count);

    pthread_mutex_unlock(&list->lock);
}

// Cleanup function to free the linked list and resources
void cleanup_crc_list(CRC_LIST *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Usage example
int main() {
    time_t expiration_threshold = 60; // Entries older than 60 seconds will be removed
    CRC_LIST *crc_list = initialize_crc_list(expiration_threshold);

    if (crc_list) {
        RX_UE_INFORMATION_TAG info_tag;
        RNTI rnti = 1234;

        insert_crc_entry(crc_list, info_tag, rnti);
        log_metrics(crc_list);

        sleep(10); // Simulate some processing time

        cleanup_crc_list(crc_list);
    }

    return 0;
}
```

