```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint16_t RNTI;
    // Add other fields as necessary for the structure.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;  // Assuming use of POSIX threads for thread safety
} NFAPI_CRC_INDICATION_ARRAY;

// Function prototypes
int initializeArray(NFAPI_CRC_INDICATION_ARRAY *arr, size_t initial_capacity);
int addElement(NFAPI_CRC_INDICATION_ARRAY *arr, NFAPI_CRC_INDICATION_PDU_T element);
int removeElementByRNTI(NFAPI_CRC_INDICATION_ARRAY *arr, uint16_t RNTI);
void printAllRNtIsAscending(const NFAPI_CRC_INDICATION_ARRAY *arr);

int initializeArray(NFAPI_CRC_INDICATION_ARRAY *arr, size_t initial_capacity) {
    if (pthread_mutex_init(&arr->mutex, NULL) != 0) return -1;

    arr->capacity = initial_capacity;
    arr->count = 0;

    arr->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        pthread_mutex_destroy(&arr->mutex);
        return -1;
    }

    return 0;
}

int addElement(NFAPI_CRC_INDICATION_ARRAY *arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->count == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&arr->mutex);
            return -1; // Allocation failed
        }
        arr->capacity = new_capacity;
        arr->array = new_array;
    }

    arr->array[arr->count++] = element;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int removeElementByRNTI(NFAPI_CRC_INDICATION_ARRAY *arr, uint16_t RNTI) {
    pthread_mutex_lock(&arr->mutex);

    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->array[i].RNTI == RNTI) {
            memmove(&arr->array[i], &arr->array[i + 1], (arr->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            arr->count--;
            break;
        }
    }

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

void printAllRNtIsAscending(const NFAPI_CRC_INDICATION_ARRAY *arr) {
    pthread_mutex_lock((pthread_mutex_t *)&arr->mutex);

    NFAPI_CRC_INDICATION_PDU_T *sorted_array = malloc(arr->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!sorted_array) {
        pthread_mutex_unlock((pthread_mutex_t *)&arr->mutex);
        return;  // Handle allocation failure
    }

    memcpy(sorted_array, arr->array, arr->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < arr->count - 1; ++i) {
        for (size_t j = 0; j < arr->count - i - 1; ++j) {
            if (sorted_array[j].RNTI > sorted_array[j + 1].RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = sorted_array[j];
                sorted_array[j] = sorted_array[j + 1];
                sorted_array[j + 1] = temp;
            }
        }
    }

    for (size_t i = 0; i < arr->count; ++i) {
        printf("RNTI: %u\n", sorted_array[i].RNTI);
    }

    free(sorted_array);

    pthread_mutex_unlock((pthread_mutex_t *)&arr->mutex);
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_ARRAY arr;
    initializeArray(&arr, 4); // Starting with capacity of 4

    addElement(&arr, (NFAPI_CRC_INDICATION_PDU_T){.RNTI = 10});
    addElement(&arr, (NFAPI_CRC_INDICATION_PDU_T){.RNTI = 5});
    addElement(&arr, (NFAPI_CRC_INDICATION_PDU_T){.RNTI = 20});

    printAllRNtIsAscending(&arr);

    removeElementByRNTI(&arr, 10);
    printAllRNtIsAscending(&arr);

    free(arr.array); // Clean up
    pthread_mutex_destroy(&arr.mutex);

    return 0;
}
