} TrafficDirection;

typedef struct {
    int FlowID;
    char QoSClassIdentifier[64];
    TrafficDirection TrafficDirection;
} TrafficFlowConfiguration;

typedef struct Node {
    TrafficFlowConfiguration config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ConfigList;

void initConfigList(ConfigList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

TrafficFlowConfiguration* findConfigByID(ConfigList* list, int FlowID) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->config.FlowID == FlowID) {
            pthread_mutex_unlock(&list->lock);
            return &current->config;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void addOrUpdateConfig(ConfigList* list, TrafficFlowConfiguration config) {
    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current != NULL) {
        if ((*current)->config.FlowID == config.FlowID) {
            (*current)->config = config;
            break;
        }
        current = &((*current)->next);
    }

    if (*current == NULL) { // If not found, add new node
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return; // Memory allocation failed
        }
        newNode->config = config;
        newNode->next = NULL;
        *current = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

void freeConfigList(ConfigList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

