#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define structure for CRC indication tag
typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Define structure for NFAPI CRC indication PDU
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG *CRC_INDICATION_REL8_TAG_PTR;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic list to manage the PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **items;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

// Function prototypes
DynamicList* create_dynamic_list(size_t initial_capacity);
void free_dynamic_list(DynamicList *list);
int add_pdu(DynamicList *list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI);
int update_pdu(DynamicList *list, uint16_t RNTI, int new_CRCFLAG);
void set_random_crcflag(CRC_INDICATION_REL8_TAG *tag);

// Function implementations

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList *)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->items = (NFAPI_CRC_INDICATION_PDU_T **)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!list->items) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void free_dynamic_list(DynamicList *list) {
    if (!list) return;

    for (size_t i = 0; i < list->size; ++i) {
        if (list->items[i]) {
            free(list->items[i]->CRC_INDICATION_REL8_TAG_PTR);
            free(list->items[i]);
        }
    }

    free(list->items);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_pdu(DynamicList *list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_items = (NFAPI_CRC_INDICATION_PDU_T **)realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (!new_items) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->items = new_items;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG_PTR = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!pdu->CRC_INDICATION_REL8_TAG_PTR) {
        free(pdu);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    set_random_crcflag(pdu->CRC_INDICATION_REL8_TAG_PTR);

    list->items[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_pdu(DynamicList *list, uint16_t RNTI, int new_CRCFLAG) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = list->items[i];
        if (pdu && pdu->RNTI == RNTI) {
            pdu->CRC_INDICATION_REL8_TAG_PTR->CRCFLAG = new_CRCFLAG;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

void set_random_crcflag(CRC_INDICATION_REL8_TAG *tag) {
    if (!tag) return;

    srand(time(NULL));
    tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}
