#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_BUFFER_SIZE 256

// Connection structure
typedef struct {
    char *client_id;
    char *server_id;
    char *message_buffer;
    size_t buffer_size;
} Connection;

// Dynamic list of connections
typedef struct {
    Connection **connections;
    size_t count;
    size_t capacity;
} ConnectionList;

// Initialize the connection list
void init_connection_list(ConnectionList *list) {
    list->count = 0;
    list->capacity = 10; // Initial capacity
    list->connections = (Connection **)malloc(sizeof(Connection *) * list->capacity);
}

// Add a new connection or update an existing one
void add_or_update_connection(ConnectionList *list, const char *client_id, const char *server_id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->connections[i]->client_id, client_id) == 0 &&
            strcmp(list->connections[i]->server_id, server_id) == 0) {

            // Update message buffer size dynamically
            list->connections[i]->buffer_size *= 2;
            char *new_buffer = (char *)realloc(list->connections[i]->message_buffer,
                                               sizeof(char) * list->connections[i]->buffer_size);
            if (new_buffer != NULL) {
                list->connections[i]->message_buffer = new_buffer;
            }

            // Log update
            printf("Updated connection for Client ID: %s, Server ID: %s\n", client_id, server_id);
            return;
        }
    }

    // Add new connection if not found
    if (list->count == list->capacity) {
        list->capacity *= 2;
        Connection **new_array = (Connection **)realloc(list->connections,
                                                        sizeof(Connection *) * list->capacity);
        if (new_array != NULL) {
            list->connections = new_array;
        } else {
            perror("Failed to resize connection array");
            exit(EXIT_FAILURE);
        }
    }

    Connection *connection = (Connection *)malloc(sizeof(Connection));
    if (!connection) {
        perror("Failed to allocate memory for connection");
        exit(EXIT_FAILURE);
    }

    connection->client_id = strdup(client_id);
    connection->server_id = strdup(server_id);
    connection->buffer_size = INITIAL_BUFFER_SIZE;
    connection->message_buffer = (char *)malloc(sizeof(char) * connection->buffer_size);

    if (!connection->client_id || !connection->server_id || !connection->message_buffer) {
        free(connection->client_id);
        free(connection->server_id);
        free(connection->message_buffer);
        free(connection);
        perror("Failed to allocate memory for connection components");
        exit(EXIT_FAILURE);
    }

    list->connections[list->count++] = connection;

    // Log addition
    printf("Added new connection: Client ID: %s, Server ID: %s\n", client_id, server_id);
}

// Free the connection list and its resources
void free_connection_list(ConnectionList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->connections[i]->client_id);
        free(list->connections[i]->server_id);
        free(list->connections[i]->message_buffer);
        free(list->connections[i]);
    }
    free(list->connections);
}

// Example usage
int main() {
    ConnectionList list;
    init_connection_list(&list);

    add_or_update_connection(&list, "client1", "serverA");
    add_or_update_connection(&list, "client2", "serverB");

    // Simulating an update by adding with the same identifiers
    add_or_update_connection(&list, "client1", "serverA");

    free_connection_list(&list);
    return 0;
}
```

