pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *manage_packet_list(int N, int filter_threshold, int log_level) {
    pthread_mutex_lock(&lock);

    if (log_level > 0)
        printf("Allocating memory for %d packets.\n", N);

    NFAPI_CRC_INDICATION_PDU_T *packets = NULL;
    size_t packet_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

    packets = malloc(packet_size);
    if (!packets) {
        if (log_level > 0)
            fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (int i = 0; i < N; ++i) {
        packets[i].rx_ue_info_tag.valid = 1;
        packets[i].rnti = rand() % 10000;
        packets[i].crc_indication_rel8_tag.CRCFLAG = generate_crcflag();
        packets[i].timestamp = time(NULL);
        packets[i].sequence_number = i + 1; // Unique sequence number
        packets[i].is_specific_session = (rand() % 2) == 0;

        if (log_level > 1)
            printf("Packet[%d]: RNTI=%u, CRCFLAG=%d\n", i, packets[i].rnti, packets[i].crc_indication_rel8_tag.CRCFLAG);
    }

    if (filter_threshold > 0 && !filter_by_crcconsistency(packets, N, filter_threshold)) {
        free(packets);
        packets = NULL;
    }

    pthread_mutex_unlock(&lock);

    return packets;
}

int generate_crcflag() {
    return rand() % 2; // Randomly set CRCFLAG to true or false
}

bool filter_by_crcconsistency(const NFAPI_CRC_INDICATION_PDU_T *packets, int count, int threshold) {
    int consistent_count = 0;

    for (int i = 1; i < count; ++i) {
        if (packets[i].crc_indication_rel8_tag.CRCFLAG == packets[0].crc_indication_rel8_tag.CRCFLAG)
            ++consistent_count;
    }

    return consistent_count >= threshold;
}
