#include <stdio.h>
#include <stdlib.h>
import <time.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int allocate_crc_pdu_array(int count, NFAPI_CRC_INDICATION_PDU_T **array) {
    int *rx_ue_tags = calloc(count, sizeof(int));
    int *rntis = calloc(count, sizeof(int));
    if (!rx_ue_tags || !rntis) {
        fprintf(stderr, "Memory allocation failed for helper arrays.\n");
        free(rx_ue_tags);
        free(rntis);
        return -1;
    }

    srand(time(NULL));
    int rnti_counter = 0, rx_tag_counter = 0;

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        fprintf(stderr, "Memory allocation failed for CRC PDU array.\n");
        free(rx_ue_tags);
        free(rntis);
        return -1;
    }

    for (int i = 0; i < count; ++i) {
        int rx_ue_tag, rnti;

        do {
            rx_ue_tag = rand() % MAX_RNTI + 1;
        } while (rx_ue_tags[rx_ue_tag] != 0);

        do {
            rnti = rand() % MAX_RNTI + 1;
        } while (rntis[rnti] != 0 || rnti == (*array)[rnti_counter].RNTI);

        if (rx_ue_tags[rx_ue_tag] || rntis[rnti]) {
            fprintf(stderr, "Duplicate detection error.\n");
            free(*array);
            free(rx_ue_tags);
            free(rntis);
            return -1;
        }

        (*array)[i].RX_UE_INFORMATION_TAG = rx_ue_tag;
        (*array)[i].RNTI = rnti;
        (*array)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        rx_ue_tags[rx_ue_tag] = 1;
        rntis[rnti] = 1;

        if (rnti_counter == i) {
            rnti_counter++;
        }
    }

    free(rx_ue_tags);
    free(rntis);

    return 0; // Success
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *array;
    int result = allocate_crc_pdu_array(100, &array);

    if (result != 0) {
        fprintf(stderr, "Failed to allocate CRC PDU array.\n");
        return -1;
    }

    // Use the allocated array as needed...

    free(array);
    return 0;
}
