#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_RETRY 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    pthread_mutex_t mutex;
} List;

void log_error(const char* message) {
    FILE* log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int is_valid_RNTI(int rnti) {
    // Placeholder for actual RNTI validation logic
    return 1;
}

int validate_RX_UE_INFORMATION_TAG(int tag) {
    // Simulate external data source check with random success/failure
    return rand() % 2; 
}

void* allocate_and_populate(void* arg) {
    List* list = (List*)arg;

    for (size_t i = 0; i < list->size; ++i) {
        int rnti, crcflag;
        do {
            rnti = rand() % 10000; // Example range
        } while (!is_valid_RNTI(rnti));

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i + 1; // Unique tag

        int retry_count = 0;
        while (retry_count < MAX_RETRY) {
            if (validate_RX_UE_INFORMATION_TAG(pdu.RX_UE_INFORMATION_TAG)) {
                break;
            }
            retry_count++;
            if (retry_count == MAX_RETRY) {
                char msg[256];
                snprintf(msg, sizeof(msg), "Failed to validate tag %d after %d retries", pdu.RX_UE_INFORMATION_TAG, retry_count);
                log_error(msg);
            }
        }

        crcflag = rand() % 2; // Simulate CRCFLAG as random
        pdu.RNTI = rnti;
        pdu.CRC_INDICATION_REL8_TAG = crcflag;

        pthread_mutex_lock(&list->mutex);
        list->data[i] = pdu;
        pthread_mutex_unlock(&list->mutex);

        usleep(1000);  // Simulate work delay and prevent CPU overuse
    }

    return NULL;
}

List* create_list(size_t size) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        log_error("Failed to allocate memory for list");
        exit(EXIT_FAILURE);
    }
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        log_error("Failed to allocate memory for data array");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&list->mutex, NULL);
    list->size = size;

    return list;
}

void destroy_list(List* list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

List* populate_crc_indication_pdu_list(size_t N) {
    srand(time(NULL));

    List* list = create_list(N);

    const int NUM_THREADS = 4;
    pthread_t threads[NUM_THREADS];
    size_t chunk_size = (N + NUM_THREADS - 1) / NUM_THREADS;

    for (int i = 0; i < NUM_THREADS; ++i) {
        List sub_list = { list->data + i * chunk_size, 
                          (i == NUM_THREADS - 1) ? N - i * chunk_size : chunk_size,
                          list->mutex };

        pthread_create(&threads[i], NULL, allocate_and_populate, &sub_list);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return list;
}

int main() {
    size_t N = 1000; // Example list size
    List* list = populate_crc_indication_pdu_list(N);

    for (size_t i = 0; i < list->size; ++i) {
        printf("Tag: %d, RNTI: %d, CRCFLAG: %d\n",
               list->data[i].RX_UE_INFORMATION_TAG,
               list->data[i].RNTI,
               list->data[i].CRC_INDICATION_REL8_TAG);
    }

    destroy_list(list);

    return 0;
}
