// Define a network session structure
typedef struct {
    char ip_address[16];
    int port_number;
    int connection_status; // 0 for disconnected, 1 for connected
} NetworkSession;

// Define a node for the linked list to manage sessions
typedef struct Node {
    NetworkSession session;
    struct Node* next;
} Node;

// Define the collection of network sessions
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for thread safety
} SessionManager;

// Function prototypes
void add_session(SessionManager* manager, const char* ip_address, int port_number);
void update_session(SessionManager* manager, const char* ip_address, int new_port_number, int new_status);
void remove_session(SessionManager* manager, const char* ip_address);
void log_change(const char* operation, const NetworkSession* session);
int mcs_optimization(int channel_conditions);

// Initialize the SessionManager
SessionManager* init_manager() {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Add a new session to the collection
void add_session(SessionManager* manager, const char* ip_address, int port_number) {
    pthread_mutex_lock(&manager->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    strcpy(new_node->session.ip_address, ip_address);
    new_node->session.port_number = port_number;
    new_node->session.connection_status = 1; // Assume connected when added
    new_node->next = manager->head;
    manager->head = new_node;

    log_change("ADD", &new_node->session);

    pthread_mutex_unlock(&manager->lock);
}

// Update an existing session based on IP address
void update_session(SessionManager* manager, const char* ip_address, int new_port_number, int new_status) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current != NULL) {
        if (strcmp(current->session.ip_address, ip_address) == 0) {
            current->session.port_number = new_port_number;
            current->session.connection_status = new_status;

            log_change("UPDATE", &current->session);

            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Remove a session based on IP address
void remove_session(SessionManager* manager, const char* ip_address) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;
    while (current != NULL) {
        if (strcmp(current->session.ip_address, ip_address) == 0) {
            if (prev == NULL) {
                manager->head = current->next; // Removing head
            } else {
                prev->next = current->next;
            }
            log_change("REMOVE", &current->session);

            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Log changes to an external monitoring service
void log_change(const char* operation, const NetworkSession* session) {
    // Simulate logging to an external service
    printf("Logged %s: IP=%s, Port=%d, Status=%d\n", operation,
           session->ip_address, session->port_number, session->connection_status);
}

// MCS optimization function stub
int mcs_optimization(int channel_conditions) {
    // Simulate dynamic adjustment based on real-time conditions
    return (channel_conditions % 2 == 0) ? 1 : 0; // Simple toggle for demonstration
}

// Free the memory allocated for sessions
void free_sessions(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage
int main() {
    SessionManager* manager = init_manager();

    add_session(manager, "192.168.0.1", 8080);
    update_session(manager, "192.168.0.1", 9090, 0); // Update to disconnected
    remove_session(manager, "192.168.0.1");

    free_sessions(manager);

    return 0;
}
```

