typedef void (*error_callback_t)(const char *message);

// Structure for managing the list with dynamic resizing and thread safety
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    error_callback_t errorCallback;
} CRC_Indication_Manager;

// Forward declaration of internal functions
static void handleMemoryAllocationError(const char *message);
static void resizeArray(CRC_Indication_Manager *manager);

// Function to initialize the manager
int initCRC_IndicationManager(CRC_Indication_Manager *manager, error_callback_t errorCallback) {
    if (!manager || !errorCallback) return -1;

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    manager->array = (NFAPI_CRC_INDICATION_PDU_T **)malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!manager->array) {
        errorCallback("Memory allocation failed for initial capacity.");
        return -1;
    }

    manager->errorCallback = errorCallback;

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    return 0;
}

// Function to add a new structure with randomized CRCFLAG
int addCRCIndication(CRC_Indication_Manager *manager, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (!manager || manager->capacity == 0) return -1;

    pthread_mutex_lock(&manager->lock);

    // Resize array if necessary
    if (manager->size >= manager->capacity && manager->capacity < MAX_STRUCTURES) {
        resizeArray(manager);
    }

    if (manager->size >= manager->capacity) {
        handleMemoryAllocationError("Maximum capacity reached. Cannot add more structures.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *newPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newPdu) {
        handleMemoryAllocationError("Memory allocation failed for new structure.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    newPdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newPdu->RNTI = RNTI;
    newPdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    manager->array[manager->size++] = newPdu;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to resize the array when capacity is exceeded
static void resizeArray(CRC_Indication_Manager *manager) {
    size_t newCapacity = (manager->capacity < MAX_STRUCTURES) ? manager->capacity * 2 : manager->capacity;

    NFAPI_CRC_INDICATION_PDU_T **newArray = realloc(manager->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!newArray) {
        handleMemoryAllocationError("Memory reallocation failed.");
        return;
    }

    memset(newArray + manager->capacity, 0, (newCapacity - manager->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    manager->array = newArray;
    manager->capacity = newCapacity;
}

// Function to handle memory allocation errors
static void handleMemoryAllocationError(const char *message) {
    // Implement logging or any additional error handling here.
    printf("Error: %s\n", message);
}

// Cleanup function to free allocated resources
void cleanupCRC_IndicationManager(CRC_Indication_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->array[i]);
    }
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Main function to demonstrate usage
int main() {
    CRC_Indication_Manager manager;

    initCRC_IndicationManager(&manager, handleMemoryAllocationError);

    // Simulate adding structures
    for (int i = 0; i < 15; ++i) {
        addCRCIndication(&manager, i, i * 10);
    }

    cleanupCRC_IndicationManager(&manager);

    return 0;
}
