// Global lock-free set using a simple bit vector for demonstration purposes.
#define MAX_RNTIS (MAX_ENTRIES)
static atomic_uint_fast64_t rnti_set[MAX_RNTIs / 64 + 1] = {0};

// Function to check and insert RNTI atomically
int is_rnti_unique(uint16_t rnti) {
    size_t index = rnti / 64;
    uint64_t mask = ((uint64_t)1) << (rnti % 64);

    if (!atomic_load(&rnti_set[index]) & mask) {
        atomic_fetch_or(&rnti_set[index], mask);
        return 1; // RNTI is unique
    }
    return 0; // Duplicate RNTI
}

// Function to generate a random CRCFLAG (for example purposes, we toggle between 0 and 1)
