}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_list(size_t *num_entries) {
    if (!num_entries) return NULL;

    size_t entry_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_memory = MAX_ENTRIES * entry_size;

    // Check memory constraints
    if (total_memory > 2 * 1024 * 1024) { // Assume one core for simplicity
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(total_memory);
    if (!list) {
        perror("malloc failed");
        return NULL;
    }

    size_t count = 0;
    while (count < MAX_ENTRIES) {
        NFAPI_CRC_INDICATION_PDU_T entry;

        // Generate random values
        entry.RX_UE_INFORMATION_TAG = rand() % 65536; // Example range for demo purposes
        do {
            entry.RNTI = rand() % 65536;
        } while (!is_rnti_unique(entry.RNTI));

        entry.CRC_INDICATION_REL8_TAG = generate_random_crcflag();

        list[count++] = entry;

        if (count % 1000 == 0) { // Periodically check to avoid infinite loops
            printf("Created %zu entries\n", count);
        }
    }

    *num_entries = count;
    return list;
}

void free_nfa_pi_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}
