    *invalid_tags_count = 0;
    for (size_t i = 0; i < N; ++i) {
        if (!validate_tag(pdu_list[i].RX_UE_INFORMATION_TAG)) {
            (*invalid_tags_count)++;
        }
    }

    printf("Total structures created: %zu\n", N);
    printf("Invalid tags encountered: %d\n", *invalid_tags_count);
}

void create_nfa_pi_crc_indication_pdu(size_t N) {
    if (N > MAX_ALLOWABLE_N) {
        fprintf(stderr, "Error: Requested size exceeds maximum allowable limit.\n");
        return;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int retry_count;
    bool initialized;
    int RX_UE_INFORMATION_TAG, RNTI;

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_destroy(&lock);
        return;
    }

    for (size_t i = 0; i < N; ++i) {
        do {
            retry_count = 0;
            initialized = initialize_RX_UE_INFORMATION_TAG(&RX_UE_INFORMATION_TAG);
        } while (!initialized && ++retry_count <= RETRY_LIMIT);

        if (!initialized) {
            fprintf(stderr, "Failed to initialize RX_UE_INFORMATION_TAG after %d retries.\n", RETRY_LIMIT);
            free(pdu_list);
            pthread_mutex_destroy(&lock);
            return;
        }

        do {
            retry_count = 0;
            initialized = initialize_RNTI(&RNTI);
        } while (!initialized && ++retry_count <= RETRY_LIMIT);

        if (!initialized) {
            fprintf(stderr, "Failed to initialize RNTI after %d retries.\n", RETRY_LIMIT);
            free(pdu_list);
            pthread_mutex_destroy(&lock);
            return;
        }

        pthread_mutex_lock(&lock);
        pdu_list[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu_list[i].RNTI = RNTI;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
        log_event("Created NFAPI_CRC_INDICATION_PDU_T structure.");
        pthread_mutex_unlock(&lock);
    }

    int invalid_tags_count = 0;
    generate_crc_report(pdu_list, N, &invalid_tags_count);

    free(pdu_list);
    pthread_mutex_destroy(&lock);
}

int main() {
    srand(time(NULL)); // Seed random number generator
    size_t N = 10; // Example input
    create_nfa_pi_crc_indication_pdu(N);
    return 0;
}
