#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int CELL_ID;
    time_t MEASUREMENT_TIME;
    float POWER_LEVEL;
} TX_POWER_REPORT;

#define HASH_TABLE_SIZE 1000000

typedef struct HashTableEntry {
    TX_POWER_REPORT report;
    struct HashTableEntry* next;
} HashTableEntry;

typedef struct {
    HashTableEntry** table;
    pthread_mutex_t mutex[HASH_TABLE_SIZE];
} DynamicArrayManager;

unsigned long hashFunction(int cell_id) {
    return (unsigned long)cell_id % HASH_TABLE_SIZE;
}

DynamicArrayManager* createManager() {
    DynamicArrayManager* manager = malloc(sizeof(DynamicArrayManager));
    manager->table = calloc(HASH_TABLE_SIZE, sizeof(HashTableEntry*));
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_init(&manager->mutex[i], NULL);
    }
    return manager;
}

void destroyManager(DynamicArrayManager* manager) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry* entry = manager->table[i];
        while (entry) {
            HashTableEntry* temp = entry;
            entry = entry->next;
            free(temp);
        }
        pthread_mutex_destroy(&manager->mutex[i]);
    }
    free(manager->table);
    free(manager);
}

void addOrUpdateReport(DynamicArrayManager* manager, TX_POWER_REPORT report) {
    unsigned long index = hashFunction(report.CELL_ID);
    pthread_mutex_lock(&manager->mutex[index]);

    HashTableEntry* entry = manager->table[index];
    while (entry) {
        if (entry->report.CELL_ID == report.CELL_ID) {
            entry->report = report;
            break;
        }
        entry = entry->next;
    }

    if (!entry) {
        entry = malloc(sizeof(HashTableEntry));
        entry->report = report;
        entry->next = manager->table[index];
        manager->table[index] = entry;
    }

    pthread_mutex_unlock(&manager->mutex[index]);
}

float getAveragePower(DynamicArrayManager* manager, int cell_id, time_t start_time, time_t end_time) {
    unsigned long index = hashFunction(cell_id);
    pthread_mutex_lock(&manager->mutex[index]);

    float total_power = 0.0;
    int count = 0;

    HashTableEntry* entry = manager->table[index];
    while (entry) {
        if (entry->report.CELL_ID == cell_id &&
            entry->report.MEASUREMENT_TIME >= start_time &&
            entry->report.MEASUREMENT_TIME <= end_time) {
            total_power += entry->report.POWER_LEVEL;
            count++;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&manager->mutex[index]);

    return (count > 0) ? (total_power / count) : -1.0f;
}

// Example usage
int main() {
    DynamicArrayManager* manager = createManager();

    TX_POWER_REPORT report = {12345, time(NULL), 50.5};
    addOrUpdateReport(manager, report);

    float avg_power = getAveragePower(manager, 12345, time(NULL) - 3600, time(NULL));
    printf("Average Power: %f\n", avg_power);

    destroyManager(manager);
    return 0;
}
