    return pdu;
}

void add_pdu_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T* pdu, const char* logfile) {
    if (!list || !pdu) {
        log_message("Failed to add PDU: Invalid parameters", 1, logfile);
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_message("Failed to allocate memory for node", 2, logfile);
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = *pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void free_list(List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

