            return NULL;
        }
    }

    // Notify about changes
    for (size_t i = 0; i < list->size; ++i) {
        update_callback(&list->data[i]);
    }

    return list;
}

// Helper functions

UEInformationList* create_uelist() {
    UEInformationList *list = malloc(sizeof(UEInformationList));
    if (!list) return NULL;

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->data = calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

