    if (list->size == list->capacity) {
        resize_uelist(list);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.sequence_id = rand(); // Generate a unique sequence ID
    pdu.rx_ue_info_tag = rx_ue_info_tag;
    pdu.rnti = rnti;
    pdu.crc_flag = generate_crc_flag();

    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void resize_uelist(UEInformationList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return;

    list->data = new_data;
    list->capacity = new_capacity;
}

void free_uelist(UEInformationList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

