#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1024

typedef struct {
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t block_size;
    void* pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
MemoryPool* create_memory_pool(size_t block_size, size_t capacity);
void destroy_memory_pool(MemoryPool* mp);
void* allocate_from_pool(MemoryPool* mp);
void free_all_blocks(MemoryPool* mp);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures[MAX_STRUCTURES];
    MemoryPool* pool;
    int count;
    pthread_mutex_t list_lock;
} CRCListManager;

CRCListManager* create_crc_list_manager(size_t block_size, size_t capacity) {
    CRCListManager* manager = (CRCListManager*)malloc(sizeof(CRCListManager));
    if (!manager) return NULL;

    manager->pool = create_memory_pool(block_size, capacity);
    manager->count = 0;
    pthread_mutex_init(&manager->list_lock, NULL);

    return manager;
}

void destroy_crc_list_manager(CRCListManager* manager) {
    if (manager) {
        free_all_blocks(manager->pool);
        pthread_mutex_destroy(&manager->list_lock);
        destroy_memory_pool(manager->pool);
        free(manager);
    }
}

int add_structure(CRCListManager* manager, int RNTI, unsigned char CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&manager->list_lock);

    if (manager->count >= MAX_STRUCTURES) {
        fprintf(stderr, "Error: Maximum number of structures reached.\n");
        pthread_mutex_unlock(&manager->list_lock);
        return -1;
    }

    for (int i = 0; i < manager->count; ++i) {
        if (manager->structures[i]->RNTI == RNTI) {
            fprintf(stderr, "Error: Duplicate RNTI found.\n");
            pthread_mutex_unlock(&manager->list_lock);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* new_structure = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(manager->pool);
    if (!new_structure) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&manager->list_lock);
        return -1;
    }

    new_structure->RNTI = RNTI;
    new_structure->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_structure->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    manager->structures[manager->count++] = new_structure;

    fprintf(stdout, "Structure added: RNTI=%d\n", RNTI);

    pthread_mutex_unlock(&manager->list_lock);
    return 0;
}

MemoryPool* create_memory_pool(size_t block_size, size_t capacity) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->capacity = capacity;
    mp->used = 0;
    mp->pool = malloc(block_size * capacity);

    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

void* allocate_from_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->used < mp->capacity) {
        void* block = (char*)mp->pool + mp->block_size * mp->used++;
        pthread_mutex_unlock(&mp->lock);
        return block;
    } else {
        pthread_mutex_unlock(&mp->lock);
        return malloc(mp->block_size); // Fallback to heap allocation
    }
}

void free_all_blocks(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->used > 0) {
        mp->used = 0;
        memset(mp->pool, 0, mp->capacity * mp->block_size);
    }

    pthread_mutex_unlock(&mp->lock);
}

void garbage_collect(CRCListManager* manager) {
    // Implement periodic cleanup logic if needed
}

int main() {
    srand(time(NULL));

    CRCListManager* manager = create_crc_list_manager(sizeof(NFAPI_CRC_INDICATION_PDU_T), 100);

    add_structure(manager, 12345, 1);
    add_structure(manager, 67890, 2);

    destroy_crc_list_manager(manager);

    return 0;
}
```

### Key Points:
- **Memory Pool**: A custom memory pool is used to optimize allocation speed and minimize fragmentation.
- **Thread Safety**: Mutexes are used to ensure thread-safe access to shared resources.
- **Logging**: Basic logging is implemented using `fprintf`.
- **Garbage Collection**: A placeholder function for periodic cleanup is provided, which can be expanded as needed.

This code provides a foundation that balances memory efficiency, performance, and ease of maintenance. Adjustments may be necessary based on specific system requirements or constraints.']

