#include <string.h>

#define DEFAULT_POOL_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t capacity;
    size_t size;
} DynamicArray;

unsigned int hash_function(NFAPI_CRC_INDICATION_PDU_T pdu) {
    return ((pdu.RX_UE_INFORMATION_TAG * 31 + pdu.RNTI) % 10007);
}

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->buckets = (HashNode**)calloc(initial_capacity, sizeof(HashNode*));
    if (!array->buckets) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

int is_duplicate(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned int index = hash_function(pdu) % array->capacity;
    HashNode* node = array->buckets[index];

    while (node) {
        if (node->data.RX_UE_INFORMATION_TAG == pdu.RX_UE_INFORMATION_TAG &&
            node->data.RNTI == pdu.RNTI) {
            return 1;
        }
        node = node->next;
    }

    return 0;
}

int insert_pdu(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (is_duplicate(array, pdu)) return 0;

    unsigned int index = hash_function(pdu) % array->capacity;
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    if (!node) return -1;

    node->data = pdu;
    node->next = array->buckets[index];
    array->buckets[index] = node;
    array->size++;

    return 1;
}

int remove_pdu(DynamicArray* array, int rnti) {
    for (unsigned int i = 0; i < array->capacity; ++i) {
        HashNode *prev = NULL, *curr = array->buckets[i];

        while (curr) {
            if (curr->data.RNTI == rnti) {
                if (prev) {
                    prev->next = curr->next;
                } else {
                    array->buckets[i] = curr->next;
                }

                free(curr);
                array->size--;
                return 1;
            }
            prev = curr;
            curr = curr->next;
        }
    }

    return 0;
}

int update_crcflag(DynamicArray* array, int rx_ue_tag, int rnti, int new_crcflag) {
    for (unsigned int i = 0; i < array->capacity; ++i) {
        HashNode* node = array->buckets[i];

        while (node) {
            if (node->data.RX_UE_INFORMATION_TAG == rx_ue_tag &&
                node->data.RNTI == rnti) {
                node->data.CRCFLAG = new_crcflag;
                return 1;
            }
            node = node->next;
        }
    }

    return 0;
}

int validate_all_pdus(DynamicArray* array) {
    int consistent = 1;

    for (unsigned int i = 0; i < array->capacity && consistent; ++i) {
        HashNode* node = array->buckets[i];

        while (node) {
            // Simulate CRC validation
            int expected_crcflag = (node->data.RX_UE_INFORMATION_TAG + 
                                    node->data.RNTI + 
                                    node->data.CRC_INDICATION_REL8_TAG) % 2;

            if (node->data.CRCFLAG != expected_crcflag) {
                consistent = 0;
                break;
            }

            node = node->next;
        }
    }

    return consistent;
}

void cleanup_dynamic_array(DynamicArray* array) {
    for (unsigned int i = 0; i < array->capacity; ++i) {
        HashNode* node = array->buckets[i];

        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(array->buckets);
    free(array);
}

// Example Usage
int main() {
    DynamicArray* my_array = init_dynamic_array(DEFAULT_POOL_SIZE);

    if (!my_array) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, 
                                       .RNTI = 100, 
                                       .CRC_INDICATION_REL8_TAG = 5,
                                       .CRCFLAG = rand() % 2 };

    insert_pdu(my_array, pdu1);

    update_crcflag(my_array, 1, 100, 1);

    int valid = validate_all_pdus(my_array);
    printf("Array validation: %s\n", valid ? "Passed" : "Failed");

    remove_pdu(my_array, 100);

    cleanup_dynamic_array(my_array);

    return 0;
}
