NFAPI_CRC_INDICATION_PDU_T* allocatePdus(size_t n, float crc_probability_threshold) {
    static PduManager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
    NFAPI_CRC_INDICATION_PDU_T* new_pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_pdus) {
        logWarning("Memory allocation failed for PDUs");
        return NULL;
    }

    pthread_mutex_lock(&manager.lock);

    if (manager.count + n > MAX_STRUCTS) {
        size_t space_left = MAX_STRUCTS - manager.count;
        logWarning("Maximum limit reached, allocating only the remaining space");

        if (space_left > 0) {
            memcpy(new_pdus, manager.pdu_array + manager.count, space_left * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            free(manager.pdu_array);
            manager.pdu_array = new_pdus;
            manager.count += space_left;
        }
        pthread_mutex_unlock(&manager.lock);
        return allocatePdus(n - space_left, crc_probability_threshold); // Retry for remaining PDUs
    } else {
        memcpy(new_pdus + manager.count, manager.pdu_array, manager.count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(manager.pdu_array);

        for (size_t i = manager.count; i < manager.count + n; ++i) {
