```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    char interface_name[64];
    int parameter1;
    int parameter2;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock;
} EventCollection;

// Function prototypes
void init_event_collection(EventCollection *collection);
void free_event_collection(EventCollection *collection);
int add_network_event(EventCollection *collection, const char *name, int param1, int param2);
int validate_configuration(const char *name, int param1, int param2);
void resize_collection_if_needed(EventCollection *collection);

// Initialize the event collection
void init_event_collection(EventCollection *collection) {
    collection->events = (NetworkEvent *)malloc(INITIAL_CAPACITY * sizeof(NetworkEvent));
    if (!collection->events) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    pthread_rwlock_init(&collection->lock, NULL);
}

// Free resources used by the event collection
void free_event_collection(EventCollection *collection) {
    free(collection->events);
    pthread_rwlock_destroy(&collection->lock);
}

// Add a new network event to the collection
int add_network_event(EventCollection *collection, const char *name, int param1, int param2) {
    if (!validate_configuration(name, param1, param2)) {
        return -1;
    }

    pthread_rwlock_wrlock(&collection->lock);

    resize_collection_if_needed(collection);

    NetworkEvent new_event;
    strncpy(new_event.interface_name, name, sizeof(new_event.interface_name));
    new_event.parameter1 = param1;
    new_event.parameter2 = param2;

    collection->events[collection->size++] = new_event;

    pthread_rwlock_unlock(&collection->lock);
    return 0;
}

// Validate the configuration parameters
int validate_configuration(const char *name, int param1, int param2) {
    // Example validation logic (customize as needed)
    if (strlen(name) == 0 || param1 < 0 || param2 < 0) {
        return 0; // Invalid configuration
    }
    return 1; // Valid configuration
}

// Resize the collection if it exceeds capacity
void resize_collection_if_needed(EventCollection *collection) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        NetworkEvent *new_events = (NetworkEvent *)realloc(collection->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            perror("Failed to resize memory");
            exit(EXIT_FAILURE);
        }
        collection->events = new_events;
        collection->capacity = new_capacity;
    }
}

// Example usage
int main() {
    EventCollection collection;
    init_event_collection(&collection);

    add_network_event(&collection, "eth0", 10, 20);
    add_network_event(&collection, "wlan0", 15, 25);

    free_event_collection(&collection);
    return 0;
}
```

