['Below is a C implementation for managing a collection of network event structures with thread-safe operations, dynamic resizing, validation mechanisms, and support for concurrent access:

```c
#include <stdio.h>
#include <stdlib.h>
import pthread.h>
#include <string.h>

typedef struct {
    int interface_id;
    char *name;
    unsigned int config_param; // Example configuration parameter
} NetworkEvent;

typedef struct {
    NetworkEvent **events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventCollection;

// Function to validate network event parameters
int validate_event(const NetworkEvent *event) {
    if (event == NULL || event->name == NULL || strlen(event->name) == 0 || event->config_param == 0)
        return 0; // Invalid configuration
    return 1;
}

// Initialize the collection
void init_collection(EventCollection *collection) {
    collection->count = 0;
    collection->capacity = 4; // Initial capacity
    collection->events = malloc(collection->capacity * sizeof(NetworkEvent *));
    if (!collection->events) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&collection->lock, NULL);
}

// Resize the collection when needed
void resize_collection(EventCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    NetworkEvent **new_events = realloc(collection->events, new_capacity * sizeof(NetworkEvent *));
    if (!new_events) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    collection->events = new_events;
    collection->capacity = new_capacity;
}

// Add a network event
int add_event(EventCollection *collection, NetworkEvent *event) {
    if (!validate_event(event)) return 0;

    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity)
        resize_collection(collection);

    collection->events[collection->count++] = event;

    pthread_mutex_unlock(&collection->lock);
    return 1;
}

// Lookup a network event by interface_id
NetworkEvent *find_event_by_id(EventCollection *collection, int interface_id) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->events[i]->interface_id == interface_id) {
            pthread_mutex_unlock(&collection->lock);
            return collection->events[i];
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

// Cleanup the collection
void cleanup_collection(EventCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i)
        free(collection->events[i]->name);

    free(collection->events);
    pthread_mutex_destroy(&collection->lock);
}

// Example usage
int main() {
    EventCollection collection;
    init_collection(&collection);

    NetworkEvent *event1 = malloc(sizeof(NetworkEvent));
    event1->interface_id = 1;
    event1->name = strdup("eth0");
    event1->config_param = 123;

    if (add_event(&collection, event1)) {
        printf("Added network event with ID: %d\n", event1->interface_id);
    } else {
        fprintf(stderr, "Failed to add network event\n");
    }

    NetworkEvent *found_event = find_event_by_id(&collection, 1);
    if (found_event) {
        printf("Found network event: %s\n", found_event->name);
    }

    cleanup_collection(&collection);
    return 0;
}
```

