#include <stdlib.h>
#include <pthread.h>

// Define the structure for logging configuration parameters.
typedef struct {
    int parameter1;
    double parameter2;
} LoggingConfig;

// Define the structure for a logging facility.
typedef struct {
    char *facilityName;
    LoggingConfig config;
} LoggingEvent;

// Dynamic collection to manage logging events with thread safety.
typedef struct {
    LoggingEvent **events;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock; // Using read-write locks for concurrency.
} LoggingCollection;

// Function prototypes
int validate_config(const LoggingConfig *config);
LoggingCollection* create_logging_collection(size_t initial_capacity);
void destroy_logging_collection(LoggingCollection *collection);
int add_logging_event(LoggingCollection *collection, const char *facilityName, const LoggingConfig *config);
const LoggingEvent* get_logging_event(const LoggingCollection *collection, size_t index);

// Create a new logging collection with the given capacity.
LoggingCollection* create_logging_collection(size_t initial_capacity) {
    LoggingCollection *collection = (LoggingCollection*)malloc(sizeof(LoggingCollection));
    if (!collection) return NULL;

    collection->events = (LoggingEvent**)malloc(initial_capacity * sizeof(LoggingEvent*));
    if (!collection->events) {
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i)
        collection->events[i] = NULL;

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_rwlock_init(&collection->lock, NULL);

    return collection;
}

// Destroy the logging collection and free resources.
void destroy_logging_collection(LoggingCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->events[i]->facilityName);
        free(collection->events[i]);
    }
    free(collection->events);

    pthread_rwlock_destroy(&collection->lock);
    free(collection);
}

// Validate configuration parameters.
int validate_config(const LoggingConfig *config) {
    // Example validation: Ensure parameter1 is positive and parameter2 is non-negative.
    if (config->parameter1 <= 0 || config->parameter2 < 0)
        return 0;
    return 1;
}

// Add a new logging event to the collection.
int add_logging_event(LoggingCollection *collection, const char *facilityName, const LoggingConfig *config) {
    if (!validate_config(config)) return -1;

    pthread_rwlock_wrlock(&collection->lock);

    // Resize collection if needed
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        LoggingEvent **new_events = (LoggingEvent**)realloc(collection->events, new_capacity * sizeof(LoggingEvent*));
        if (!new_events) {
            pthread_rwlock_unlock(&collection->lock);
            return -1;
        }

        for (size_t i = collection->count; i < new_capacity; ++i)
            new_events[i] = NULL;

        collection->events = new_events;
        collection->capacity = new_capacity;
    }

    LoggingEvent *new_event = (LoggingEvent*)malloc(sizeof(LoggingEvent));
    if (!new_event) {
        pthread_rwlock_unlock(&collection->lock);
        return -1;
    }

    new_event->facilityName = strdup(facilityName);
    if (!new_event->facilityName) {
        free(new_event);
        pthread_rwlock_unlock(&collection->lock);
        return -1;
    }

    new_event->config = *config;

    collection->events[collection->count++] = new_event;

    pthread_rwlock_unlock(&collection->lock);

    return 0;
}

// Retrieve a logging event by index.
const LoggingEvent* get_logging_event(const LoggingCollection *collection, size_t index) {
    if (index >= collection->count)
        return NULL;

    pthread_rwlock_rdlock(&collection->lock);
    const LoggingEvent *event = collection->events[index];
    pthread_rwlock_unlock(&collection->lock);

    return event;
}

// Example usage of the logging system
int main() {
    LoggingCollection *collection = create_logging_collection(4);

    if (!collection) {
        printf("Failed to create logging collection.\n");
        return 1;
    }

    LoggingConfig config = {5, 3.14};
    add_logging_event(collection, "facility1", &config);

    const LoggingEvent *event = get_logging_event(collection, 0);
    if (event) {
        printf("Facility: %s, Parameter1: %d, Parameter2: %.2f\n",
               event->facilityName, event->config.parameter1, event->config.parameter2);
    }

    destroy_logging_collection(collection);

    return 0;
}
