NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_crc_pdu(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of elements.\n");
        return NULL;
    }

    // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures.
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        perror("Memory allocation failed");
        return NULL;
