    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = VALID_RX_UE_INFORMATION_TAG;
        array[i].RNTI = VALID_RNTI;
        // Randomly set CRCFLAG.
        int random_crcflag = rand() % 2; // Generates either 0 or 1
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = random_crcflag;
    }

    pthread_mutex_unlock(&lock);

    return array;
}

// Function to update the CRCFLAG atomically based on incoming data.
