    if (!array || index < 0) {
        fprintf(stderr, "Invalid arguments.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    // Bounds checking
    size_t array_size = sizeof(array[0]) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (index >= array_size) {
        fprintf(stderr, "Index out of bounds.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    array[index].CRC_INDICATION_REL8_TAG.CRCFLAG = new_crcflag;

    pthread_mutex_unlock(&lock);
}

// Function to free allocated memory.
void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}

