    int N = 10; // Number of elements, for example
    NFAPI_CRC_INDICATION_PDU_T* pduArray = allocate_and_initialize_crc_pdu(N);

    if (pduArray != NULL) {
        update_crc_flag(pduArray, 5, 1); // Update CRCFLAG for element at index 5
        free_crc_pdu_array(pduArray);
    }

