#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG; // Assuming a typical flag size
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

void log_message(const char *message) {
    printf("%s\n", message);
}

int initialize_list(DynamicList *list, size_t initial_capacity) {
    if (initial_capacity == 0 || list == NULL) return -1;

    list->structures = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->structures) return -1;

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    log_message("List initialized successfully.");
    return 0;
}

void destroy_list(DynamicList *list) {
    if (list) {
        free(list->structures);
        pthread_mutex_destroy(&list->mutex);
        log_message("List destroyed.");
    }
}

int resize_list(DynamicList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_structures = realloc(list->structures, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_structures) return -1;

    list->structures = new_structures;
    list->capacity = new_capacity;

    log_message("List resized.");
    return 0;
}

int add_structure(DynamicList *list, int rx_ue_tag, int rnti, unsigned int crc_flag_min, unsigned int crc_flag_max) {
    if (list == NULL || crc_flag_min > crc_flag_max) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity == 0) { // handle overflow case
            pthread_mutex_unlock(&list->mutex);
            log_message("Failed to resize: capacity overflow.");
            return -1;
        }
        if (resize_list(list, new_capacity) != 0) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* new_structure = &list->structures[list->count];
    new_structure->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_structure->RNTI = rnti;

    srand(time(NULL) ^ pthread_self()); // Seed with time and thread id
    unsigned int crc_flag = (rand() % (crc_flag_max - crc_flag_min + 1)) + crc_flag_min;
    new_structure->CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;

    log_message("New structure added.");

    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void print_list(const DynamicList *list) {
    if (list == NULL || list->structures == NULL) {
        log_message("Empty or invalid list.");
        return;
    }

    for (size_t i = 0; i < list->count; ++i) {
        const NFAPI_CRC_INDICATION_PDU_T* structure = &list->structures[i];
        printf("Structure %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=0x%08X\n", 
               i, structure->RX_UE_INFORMATION_TAG, structure->RNTI, 
               structure->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
}

// Example usage
int main() {
    DynamicList list;
    if (initialize_list(&list, 10) != 0) {
        log_message("Failed to initialize the list.");
        return -1;
    }

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        add_structure(&list, rand() % 100, rand() % 1000, 0x00000000, 0xFFFFFFFF);
    }

    print_list(&list);

    destroy_list(&list);
    return 0;
}
```

This implementation manages a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures with thread-safe operations. It initializes the list with a given capacity, resizes it as necessary, and provides functions to add new structures while ensuring that CRCFLAG values are within specified bounds. The code includes logging for key actions, making debugging easier. Memory is managed carefully using `malloc`, `realloc`, and `free`, and synchronization is achieved via a mutex to handle concurrent access safely.']

