#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function declarations
DynamicArray* create_dynamic_array(size_t initial_size);
void free_dynamic_array(DynamicArray *array);
int populate_and_validate_array(DynamicArray *array, int crcflag_min, int crcflag_max);

// Helper functions for logging
void log_info(const char *format, ...);
void log_error(const char *format, ...);

DynamicArray* create_dynamic_array(size_t initial_size) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) {
        log_error("Failed to allocate memory for array control structure.");
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    array->data = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        log_error("Failed to allocate initial memory for data structures.");
        return NULL;
    }
    array->count = 0;

    log_info("Dynamic array created with size %zu.", initial_size);
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        if (array->data) {
            free(array->data);
        }
        pthread_mutex_unlock(&array->lock);

        pthread_mutex_destroy(&array->lock);
        free(array);

        log_info("Dynamic array freed.");
    }
}

int populate_and_validate_array(DynamicArray *array, int crcflag_min, int crcflag_max) {
    if (!array || array->count >= MAX_STRUCTS) return -1;

    size_t current_size = array->count + 100; // Batch allocation
    NFAPI_CRC_INDICATION_PDU_T *temp_data;

    pthread_mutex_lock(&array->lock);
    temp_data = realloc(array->data, current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_data) {
        log_error("Failed to reallocate memory for data structures.");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->data = temp_data;

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (size_t i = array->count; i < current_size && i < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &array->data[i];

        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 2000;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (unsigned char)(rand() % (crcflag_max - crcflag_min + 1) + crcflag_min);

        log_info("Created PDU: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d",
                 pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    array->count = current_size;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void log_info(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

void log_error(const char *format, ...){
    va_list args;
    va_start(args, format);
    fprintf(stderr, "ERROR: ");
    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");
    va_end(args);
}
