#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define MEMORY_THRESHOLD (1024 * 1024) // Example: 1 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG; // Assuming it's an integer for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

int compareRNTI(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pduA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pduB = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return pduA->RNTI - pduB->RNTI;
}

int checkMemoryUsage(size_t currentUsage) {
    return currentUsage > MEMORY_THRESHOLD;
}

void exportToBinaryFile(NFAPI_CRC_INDICATION_PDU_T *list, size_t size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    fclose(file);
}

void manageList(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size, const char *filename) {
    // Ensure no two consecutive RNTI values are the same
    for (size_t i = 1; i < *size; ++i) {
        if ((*list)[i].RNTI == (*list)[i - 1].RNTI) {
            memmove(&(*list)[i], &(*list)[i + 1], (*size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --*size;
            --i; // Recheck this position
        }
    }

    // Sort the list by RNTI
    qsort(*list, *size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compareRNTI);

    // Handle truncation if size exceeds maximum limit
    if (*size > MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *newList = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*list, MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newList) {
            *list = newList;
            *size = MAX_LIST_SIZE;
        } else {
            perror("Memory allocation failed during truncation");
        }
    }

    // Check memory usage
    size_t currentUsage = *size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (checkMemoryUsage(currentUsage)) {
        fprintf(stderr, "Warning: Memory usage exceeds threshold\n");
    }

    // Export the list to a binary file
    exportToBinaryFile(*list, *size, filename);
}

void populateList(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size) {
    srand(time(NULL));
    for (size_t i = 0; i < MAX_LIST_SIZE; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[i].RNTI = rand() % 65536;
        snprintf((*list)[i].CRC_INDICATION_REL8_TAG, sizeof((*list)[i].CRC_INDICATION_REL8_TAG), "Tag%d", rand() % 10);
        (*list)[i].CRCFLAG = rand() % 2;

        if (checkMemoryUsage((*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            fprintf(stderr, "Warning: Memory allocation exceeds threshold\n");
            break;
        }
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Memory allocation failed for list");
        return EXIT_FAILURE;
    }

    populateList(&list, &MAX_LIST_SIZE);

    manageList(&list, &MAX_LIST_SIZE, "nfa_crc_list.bin");

    free(list);
    return 0;
}
