#include <stdio.h>
#include <stdlib.h>
import threading

// Define the structure with relevant fields
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG:1; // 1-bit field for CRCFLAG
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define constants and globals
#define MAX_SIZE 1000

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL; // Head of the linked list
int size = 0;      // Current number of elements in the list
threading.Lock lock; // Mutex for thread-safe operations

// Function to create a new node with random CRCFLAG
Node* create_node(int ue_info_tag, int rnti) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Populate the structure
    new_node->data.RX_UE_INFORMATION_TAG = ue_info_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    new_node->next = NULL;

    return new_node;
}

// Thread-safe function to add a node to the list
void add_pdu(int ue_info_tag, int rnti) {
    lock.acquire();
    if (size >= MAX_SIZE) {
        printf("Maximum size reached. Cannot add more PDUs.\n");
        lock.release();
        return;
    }

    Node* new_node = create_node(ue_info_tag, rnti);
    if (!new_node) {
        lock.release();
        return;
    }

    // Insert at the head for O(1) insertion
    new_node->next = head;
    head = new_node;

    size++;
    printf("Added PDU: UE Info Tag=%d, RNTI=%d\n", ue_info_tag, rnti);

    lock.release();
}

// Function to free all nodes and reset the list
void clear_list() {
    Node* current = head;
    Node* next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    head = NULL;
    size = 0;
}

// Main function demonstrating the usage
int main() {
    // Initialize random number generator
    srand(time(NULL));

    // Example of adding PDUs (in a real system, these would be dynamic values)
    for (int i = 0; i < 10; ++i) {
        add_pdu(i + 1, i * 2);
    }

    // Clear the list at the end
    clear_list();

    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex (`lock`) is used to ensure that concurrent accesses do not corrupt data.
- **Memory Management**: The linked list dynamically allocates memory for each node, and a function `clear_list` ensures all allocated memory is freed correctly.
- **Logging**: Simple logging using `printf` helps trace operations. In a production environment, consider using more advanced logging mechanisms.
- **Performance Consideration**: Insertions are at the head of the linked list to achieve constant time complexity O(1).
- **Dynamic Scaling**: The list grows dynamically up to a defined maximum size (`MAX_SIZE`) to prevent overflows.']

