        pthread_mutex_unlock(&list->lock);
        return; // Error handling for memory allocation failure
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    if (resize_list_if_needed(list, list->size * 2)) {
        // Handle resizing error or logic here
    }
}

// Validate input parameters for the PDU
uint8_t validate_parameters(uint32_t tag, uint16_t rnti) {
    return (tag != 0 && rnti != 0);
}

// Retrieve an existing PDU from cache or create a new one if not found
NFAPI_CRC_INDICATION_PDU_T get_or_create_pdu(List* list, uint32_t tag, uint16_t rnti) {
