#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 1000

typedef struct {
    int UE_ID;
    int CELL_ID;
    char NAS_MESSAGE_PDU[256]; // Adjust size as needed
} LTE_RRC_UE_CONTEXT_T;

typedef struct {
    LTE_RRC_UE_CONTEXT_T* contexts[MAX_UE_CONTEXTS];
    pthread_rwlock_t lock;
    int count;
} RRC_MANAGER;

RRC_MANAGER* init_rrc_manager() {
    RRC_MANAGER* manager = (RRC_MANAGER*)malloc(sizeof(RRC_MANAGER));
    if (!manager) return NULL;

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i)
        manager->contexts[i] = NULL;

    pthread_rwlock_init(&manager->lock, NULL);
    manager->count = 0;

    return manager;
}

void destroy_rrc_manager(RRC_MANAGER* manager) {
    if (!manager) return;

    pthread_rwlock_wrlock(&manager->lock);
    for (int i = 0; i < MAX_UE_CONTEXTS && manager->contexts[i]; ++i)
        free(manager->contexts[i]);

    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);

    free(manager);
}

int update_rrc_context(RRC_MANAGER* manager, int ue_id, int cell_id, const char* nas_pdu) {
    if (!manager || !nas_pdu) return -1;

    pthread_rwlock_wrlock(&manager->lock);

    // Check existing context
    for (int i = 0; i < MAX_UE_CONTEXTS && manager->contexts[i]; ++i) {
        if (manager->contexts[i]->UE_ID == ue_id) {
            strcpy(manager->contexts[i]->NAS_MESSAGE_PDU, nas_pdu);
            manager->contexts[i]->CELL_ID = cell_id;
            printf("Updated UE ID: %d\n", ue_id); // Log update
            pthread_rwlock_unlock(&manager->lock);
            return 0;
        }
    }

    // Add new context if space is available
    if (manager->count < MAX_UE_CONTEXTS) {
        for (int i = 0; i < MAX_UE_CONTEXTS && manager->contexts[i]; ++i);

        if (i < MAX_UE_CONTEXTS) {
            manager->contexts[i] = (LTE_RRC_UE_CONTEXT_T*)malloc(sizeof(LTE_RRC_UE_CONTEXT_T));
            if (!manager->contexts[i]) {
                pthread_rwlock_unlock(&manager->lock);
                return -1;
            }

            manager->contexts[i]->UE_ID = ue_id;
            manager->contexts[i]->CELL_ID = cell_id;
            strcpy(manager->contexts[i]->NAS_MESSAGE_PDU, nas_pdu);
            ++manager->count;
            printf("Added new UE ID: %d\n", ue_id); // Log addition
        } else {
            pthread_rwlock_unlock(&manager->lock);
            return -1; // No space to add new context
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

void log_rrc_contexts(RRC_MANAGER* manager) {
    if (!manager) return;

    pthread_rwlock_rdlock(&manager->lock);

    for (int i = 0; i < MAX_UE_CONTEXTS && manager->contexts[i]; ++i)
        printf("UE_ID: %d, CELL_ID: %d, NAS_PDU: %s\n", 
               manager->contexts[i]->UE_ID,
               manager->contexts[i]->CELL_ID,
               manager->contexts[i]->NAS_MESSAGE_PDU);

    pthread_rwlock_unlock(&manager->lock);
}

int main() {
