    for (int i = 0; i < list->size; ++i) {
        if (strcmp(list->contexts[i].imei, imei) == 0) {
            strcpy(list->contexts[i].imei, imei);
            list->contexts[i].qos_parameters = qos_parameters;
            list->contexts[i].status_flag = status_flag;
            list->contexts[i].crc_indication_tag = rand() % 2; // Random CRCFLAG
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
