        list->contexts[list->size].qos_parameters = qos_parameters;
        list->contexts[list->size].status_flag = status_flag;
        list->contexts[list->size].crc_indication_tag = rand() % 2; // Random CRCFLAG
        ++list->size;

        pthread_mutex_unlock(&list->lock);
        return 0;
    }

