#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_UE_COUNT 1000

typedef enum {
    UE_IDLE,
    UE_ACTIVE,
    UE_DEGRADED
} UEStatus;

typedef struct {
    char IMEI[15];
    int qos;
    UEStatus status;
    unsigned int CRCFLAG;
    double throughput; // in Mbps
    double latency; // in ms
    double packet_loss; // percentage
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T context;
    struct Node* next;
} Node;

Node* head = NULL;

void addOrUpdateContext(const char* IMEI, int qos) {
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->context.IMEI, IMEI) == 0) {
            current->context.qos = qos;
            current->context.CRCFLAG = rand() % 2; // Random CRC flag
            return;
        }
        current = current->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    strcpy(newNode->context.IMEI, IMEI);
    newNode->context.qos = qos;
    newNode->context.CRCFLAG = rand() % 2; // Random CRC flag
    newNode->context.status = UE_IDLE;
    newNode->context.throughput = 0.0;
    newNode->context.latency = 0.0;
    newNode->context.packet_loss = 0.0;
    newNode->next = head;
    head = newNode;
}

NFAPI_CRC_INDICATION_PDU_T* getContextByIMEI(const char* IMEI) {
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->context.IMEI, IMEI) == 0) {
            return &(current->context);
        }
        current = current->next;
    }
    return NULL;
}

void evaluateContexts() {
    Node* current = head;
    while (current != NULL) {
        // Simulate dynamic network condition evaluation
        if (rand() % 10 < 3) { // Randomly degrade status
            current->context.status = UE_DEGRADED;
        } else if (rand() % 10 > 7) { // Randomly activate
            current->context.status = UE_ACTIVE;
        } else {
            current->context.status = UE_IDLE;
        }

        // Simulate performance metrics update
        current->context.throughput += ((double)(rand() % 100)) / 10.0;
        current->context.latency += (double)(rand() % 20);
        current->context.packet_loss += (double)(rand() % 5) / 10.0;

        // Adjust QoS based on metrics
        if (current->context.throughput < 50.0 || current->context.latency > 100.0 || current->context.packet_loss > 20.0) {
            current->context.qos = current->context.qos - 1;
        } else {
            current->context.qos = current->context.qos + 1;
        }

        current = current->next;
    }
}

void monitorPerformance() {
    // Implement real-time monitoring logic here
    Node* current = head;
    while (current != NULL) {
        printf("IMEI: %s, QoS: %d, Status: %d, Throughput: %.2f Mbps, Latency: %.2f ms, Packet Loss: %.2f%%\n",
               current->context.IMEI,
               current->context.qos,
               current->context.status,
               current->context.throughput,
               current->context.latency,
               current->context.packet_loss);
        current = current->next;
    }
}

void handleNetworkCongestion() {
    // Implement congestion handling logic here
    Node* current = head;
    while (current != NULL) {
        if (current->context.qos > 5 && rand() % 10 < 3) { // Randomly degrade non-critical services
            current->context.qos -= 2;
        }
        current = current->next;
    }
}

void configureGlobalPolicy(int globalQoS) {
    Node* current = head;
    while (current != NULL) {
        current->context.qos = globalQoS;
        current = current->next;
    }
}

int main() {
    srand(time(NULL));

    // Example usage
    addOrUpdateContext("123456789012345", 5);
    addOrUpdateContext("987654321098765", 3);

    evaluateContexts();
    monitorPerformance();
    handleNetworkCongestion();

    NFAPI_CRC_INDICATION_PDU_T* context = getContextByIMEI("123456789012345");
    if (context) {
        printf("Retrieved Context: IMEI=%s, QoS=%d\n", context->IMEI, context->qos);
    }

    configureGlobalPolicy(4);

    return 0;
}
```

This code provides a basic framework for managing NAS contexts in a 5G NR network. It includes functions to add or update contexts, retrieve them by IMEI, evaluate and adjust their states based on simulated network conditions, monitor performance metrics, handle network congestion, and configure global QoS policies. The implementation uses a linked list to store NAS contexts, ensuring scalability with low memory overhead.']

