#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdbool.h>
#include <stdio.h>

#define MAX_STRUCTURES 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

// Initialize the dynamic list
void init_list(DynamicList *list) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Destroy the dynamic list
void destroy_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Check if RNTI is valid
bool is_valid_rnti(unsigned int rnti) {
    // Example validation logic
    return (rnti > 0 && rnti < 65536);
}

// Add a structure to the list
int add_structure(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_valid_rnti(pdu.RNTI)) {
        fprintf(stderr, "Invalid RNTI value\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_STRUCTURES) {
        fprintf(stderr, "Maximum capacity reached\n");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    if (list->capacity < list->size + 1) {
        size_t new_capacity = list->capacity == 0 ? 10 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -3;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0; // Random CRCFLAG
    list->data[list->size] = pdu;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Example usage
int main() {
    DynamicList list;
    init_list(&list);

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100 };
    add_structure(&list, pdu);

    destroy_list(&list);
    return 0;
}
