typedef struct Request {
    pthread_mutex_t lock;
    int priority; // Higher value means higher priority
    TACGIPair pair;
} Request;

#define MAX_NEIGHBORS 10

// Function to dynamically manage the list of TAI and CGI tuples.
void *manage_tai_cgi_list(void *arg) {
    Request **request_queue = (Request **)arg;
    size_t queue_size = 0;

    while (1) { // Simulating continuous handling
        int highest_priority_index = -1;
        int highest_priority_value = -1;

        for (size_t i = 0; i < queue_size; ++i) {
            pthread_mutex_lock(&request_queue[i]->lock);
            if (request_queue[i]->priority > highest_priority_value) {
                highest_priority_value = request_queue[i]->priority;
                highest_priority_index = i;
            }
            pthread_mutex_unlock(&request_queue[i]->lock);
