#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int data;
    // Add more fields as necessary
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    atomic_size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function prototypes
void init_memory_pool();
Node* allocate_node(NFAPI_CRC_INDICATION_PDU_T data);
void deallocate_node(Node* node);
int add_to_pool(NFAPI_CRC_INDICATION_PDU_T data);
int remove_from_pool(int index, NFAPI_CRC_INDICATION_PDU_T *data);
void serialize_list(const char* filename);
int deserialize_list(const char* filename);

// Initialize memory pool
void init_memory_pool() {
    pthread_mutex_lock(&pool.lock);
    pool.head = NULL;
    atomic_store(&pool.size, 0);
    pthread_mutex_unlock(&pool.lock);
}

// Allocate a new node
Node* allocate_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

// Deallocate a node
void deallocate_node(Node* node) {
    free(node);
}

// Add to pool with thread-safety
int add_to_pool(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = allocate_node(data);
    if (!new_node) return -1;

    pthread_mutex_lock(&pool.lock);

    new_node->next = pool.head;
    pool.head = new_node;
    atomic_fetch_add(&pool.size, 1);

    pthread_mutex_unlock(&pool.lock);

    return 0;
}

// Remove from pool with thread-safety
int remove_from_pool(int index, NFAPI_CRC_INDICATION_PDU_T *data) {
    if (index < 0 || atomic_load(&pool.size) <= index) return -1;

    pthread_mutex_lock(&pool.lock);

    Node **indirect = &pool.head;
    for (size_t i = 0; i < index; ++i) {
        indirect = &(*indirect)->next;
    }

    Node *node_to_remove = *indirect;
    if (!node_to_remove) {
        pthread_mutex_unlock(&pool.lock);
        return -1;
    }

    *data = node_to_remove->data;
    *indirect = node_to_remove->next;

    deallocate_node(node_to_remove);
    atomic_fetch_sub(&pool.size, 1);

    pthread_mutex_unlock(&pool.lock);

    return 0;
}

// Serialize list to file
void serialize_list(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    Node* current = pool.head;
    size_t index = 0;

    while (current && index < MAX_STRUCTURES) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
        ++index;
    }

    fclose(file);
}

// Deserialize list from file
int deserialize_list(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_to_pool(data);
    }

    fclose(file);
    return 0;
}

// Main function for testing
int main() {
    init_memory_pool();

    // Populate the pool with some data
    NFAPI_CRC_INDICATION_PDU_T pdu = {123};  // Example data

    clock_t start_time = clock();
    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        add_to_pool(pdu);
    }
    clock_t end_time = clock();

    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Time taken to populate: %f seconds\n", time_taken);

    // Serialize and deserialize
    serialize_list("list.bin");
    remove_from_pool(0, &pdu);  // Clear pool before deserialization for demonstration

    if (deserialize_list("list.bin") == 0) {
        printf("Deserialized successfully.\n");
    }

    return 0;
}
