    if (!is_valid_rnti(data.RNTI)) {
        log_message("WARNING", "Invalid RNTI value");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        log_message("ERROR", "List size limit reached");
        return -1;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    log_message("INFO", "Added new element to the list");
    pthread_mutex_unlock(&list->lock);

    return 0;
}

