} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_POOL_SIZE 1024

// Hash table for RNTI validation
typedef struct hash_node {
    uint16_t rnti;
    struct hash_node *next;
} hash_node_t;

typedef struct {
    hash_node_t **buckets;
    size_t bucket_count;
    pthread_mutex_t lock;
} rnti_hash_table_t;

// Memory pool structure
typedef struct memory_pool {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} memory_pool_t;

// Function prototypes
rnti_hash_table_t* create_rnti_hash_table(size_t bucket_count);
void destroy_rnti_hash_table(rnti_hash_table_t *table);
int rnti_exists(rnti_hash_table_t *table, uint16_t rnti);
void insert_rnti(rnti_hash_table_t *table, uint16_t rnti);
memory_pool_t* create_memory_pool(size_t initial_capacity);
void destroy_memory_pool(memory_pool_t *pool);
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(memory_pool_t *pool);
void resize_memory_pool(memory_pool_t *pool, size_t new_capacity);
int create_nfapi_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t max_pdu_count, int enable_logging);

// Implementation
rnti_hash_table_t* create_rnti_hash_table(size_t bucket_count) {
    rnti_hash_table_t *table = malloc(sizeof(rnti_hash_table_t));
    table->buckets = calloc(bucket_count, sizeof(hash_node_t *));
    table->bucket_count = bucket_count;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_rnti_hash_table(rti_hash_table_t *table) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        hash_node_t *node = table->buckets[i];
        while (node) {
            hash_node_t *next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int rnti_exists(rti_hash_table_t *table, uint16_t rnti) {
    size_t index = rnti % table->bucket_count;
    pthread_mutex_lock(&table->lock);

    hash_node_t *node = table->buckets[index];
    while (node) {
        if (node->rnti == rnti) {
            pthread_mutex_unlock(&table->lock);
            return 1;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return 0;
}

void insert_rnti(rti_hash_table_t *table, uint16_t rnti) {
    size_t index = rnti % table->bucket_count;
    pthread_mutex_lock(&table->lock);

    hash_node_t *node = malloc(sizeof(hash_node_t));
    node->rnti = rnti;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    pthread_mutex_unlock(&table->lock);
}

memory_pool_t* create_memory_pool(size_t initial_capacity) {
    memory_pool_t *pool = malloc(sizeof(memory_pool_t));
    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->pool = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool_t *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used >= pool->capacity) {
        resize_memory_pool(pool, pool->capacity * 2);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->pool[pool->used++];
    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void resize_memory_pool(memory_pool_t *pool, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pool) {
        pool->pool = new_pool;
        pool->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize memory pool\n");
        exit(EXIT_FAILURE);
    }
}

int create_nfapi_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t max_pdu_count, int enable_logging) {
    rti_hash_table_t *rnti_table = create_rnti_hash_table(1024);
    memory_pool_t *pool = create_memory_pool(INITIAL_POOL_SIZE);

    size_t created_count = 0;
    for (size_t i = 0; i < max_pdu_count && created_count < max_pdu_count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu(pool);

        pdu->RX_UE_INFORMATION_TAG = rand(); // Example value
        pdu->RNTI = (uint16_t)(rand() % 65536); // Example RNTI
        pdu->CRC_INDICATION_REL8_TAG = (i & 1) ? 0xAA : 0x55; // Example CRC flag based on parity of index

        if (!rnti_exists(rnti_table, pdu->RNTI)) {
            insert_rnti(rnti_table, pdu->RNTI);
            pdus[created_count++] = pdu;

            if (enable_logging) {
                time_t now;
                time(&now);
                printf("Created PDU at %s: RX_UE_INFORMATION_TAG=%u, RNTI=%u\n", 
                       ctime(&now), pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
            }
        } else {
            free(pdu); // Free unused allocation
        }
    }

    destroy_rnti_hash_table(rnti_table);
    destroy_memory_pool(pool);

    return created_count;
}
