typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    atomic_size_t success_count;
} Queue;

Queue queue = {.head = NULL, .tail = NULL, .count = 0,
               .mutex = PTHREAD_MUTEX_INITIALIZER,
               .cond = PTHREAD_COND_INITIALIZER,
               .success_count = ATOMIC_VAR_INIT(0)};

void log_event(const char* level, const char* message) {
    if (strcmp(level, "DEBUG") == 0) return; // Disable logging when not needed
    printf("[%s] %s\n", level, message);
}

int create_structure(NFAPI_CRC_INDICATION_PDU_T pdu, int enable_logging) {
    pthread_mutex_lock(&queue.mutex);

    while (queue.count >= MAX_PDU_COUNT) {
        log_event("INFO", "Queue is full, waiting...");
        pthread_cond_wait(&queue.cond, &queue.mutex);
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&queue.mutex);
        return -1;
    }

    *new_node = (Node){.data = pdu, .next = NULL};
    if (queue.tail) {
        queue.tail->next = new_node;
    } else {
        queue.head = new_node;
    }
    queue.tail = new_node;
    queue.count++;

    atomic_fetch_add(&queue.success_count, 1);

    if (enable_logging) {
        char log_message[128];
        snprintf(log_message, sizeof(log_message),
                 "Added PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=0x%02X",
                 pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
        log_event("INFO", log_message);
    }

    pthread_cond_signal(&queue.cond);
    pthread_mutex_unlock(&queue.mutex);

    return 0;
}

size_t get_success_count() {
    return atomic_load(&queue.success_count);
}

void reset_success_count() {
    atomic_store(&queue.success_count, 0);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3};
    create_structure(pdu, 1); // Enable logging
    printf("Success count: %zu\n", get_success_count());
    reset_success_count();
    return 0;
}
