                log_debug("API call failed, retrying...");
                sleep(1 << (attempt - 1)); // Exponential backoff
                retry = true;
                continue;
            }

            if (rnti_set[rnti % 256]) {
                log_debug("Duplicate RNTI detected, retrying...");
                retry = true;
                continue;
            }

            rnti_set[rnti % 256] = 1;

            unsigned int checksum = calculate_checksum(tag);
            bool crcflag = rand() & 1; // Randomly set CRCFLAG

            if (checksum != crcflag) {
                log_debug("Checksum mismatch, skipping PDU...");
                retry = true;
                continue;
            }

            if (pdu_list->count == pdu_list->allocated_count) {
                size_t new_alloc_size = pdu_list->allocated_count * 2;
                NFAPI_CRC_INDICATION_PDU_T* temp_pdus =
                    realloc(pdu_list->pdus, new_alloc_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!temp_pdus) handle_error("Memory reallocation failed for PDUs");
                pdu_list->allocated_count = new_alloc_size;
                pdu_list->pdus = temp_pdus;
            }

            strcpy(pdu_list->pdus[pdu_list->count].RX_UE_INFORMATION_TAG, tag);
            pdu_list->pdus[pdu_list->count].RNTI = rnti;
            pdu_list->pdus[pdu_list->count].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

            log_debug("PDU generated: RX_UE_INFORMATION_TAG=%s, RNTI=%u, CRCFLAG=%d", tag, rnti, crcflag);
            pdu_list->count++;

            if (!retry) break;
        }
    }

    log_info("Finished generating PDUs. Total count: %zu", pdu_list->count);

    return pdu_list;
}

void free_pdus(PDU_List *pdu_list) {
