#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Example structure definitions
typedef struct {
    int valid; // Just for demonstration, assuming it's a flag or similar
} RX_UE_INFORMATION_TAG;

typedef unsigned int RNTI;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t timestamp; // For tracking age
} NFAPI_CRC_INDICATION_PDU;

// Node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

// Hash table bucket
typedef struct Bucket {
    Node* head;
} Bucket;

// Global hash table and lock
#define TABLE_SIZE 256 // Example size, can be adjusted
Bucket* hash_table[TABLE_SIZE];
pthread_mutex_t locks[TABLE_SIZE];

unsigned int hash_function(RNTI rnti) {
    return rnti % TABLE_SIZE;
}

void initialize_system() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        hash_table[i] = malloc(sizeof(Bucket));
        hash_table[i]->head = NULL;
        pthread_mutex_init(&locks[i], NULL);
    }
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

// Add a new entry or update an existing one
void add_or_update_entry(RX_UE_INFORMATION_TAG rx_ue_info_tag, RNTI rnti,
                         CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    unsigned int index = hash_function(rnti);
    pthread_mutex_lock(&locks[index]);

    Node* current = hash_table[index]->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            // Update
            current->data.rx_ue_info_tag = rx_ue_info_tag;
            current->data.crc_indication_rel8_tag = crc_indication_rel8_tag;
            current->data.timestamp = time(NULL);
            pthread_mutex_unlock(&locks[index]);
            return;
        }
        prev = current;
        current = current->next;
    }

    // Add new entry
    Node* newNode = malloc(sizeof(Node));
    newNode->data.rx_ue_info_tag = rx_ue_info_tag;
    newNode->data.rnti = rnti;
    newNode->data.crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    newNode->data.timestamp = time(NULL);
    newNode->next = hash_table[index]->head;
    hash_table[index]->head = newNode;

    pthread_mutex_unlock(&locks[index]);
}

// Remove an entry by RNTI
void remove_entry(RNTI rnti) {
    unsigned int index = hash_function(rnti);
    pthread_mutex_lock(&locks[index]);

    Node* current = hash_table[index]->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (prev == NULL) {
                // Remove head
                hash_table[index]->head = current->next;
            } else {
                // Remove middle or end
                prev->next = current->next;
            }
            free_node(current);
            pthread_mutex_unlock(&locks[index]);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&locks[index]);
}

// Periodically clear entries older than a threshold (milliseconds)
void clear_old_entries(time_t threshold_ms) {
    time_t current_time = time(NULL);
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&locks[i]);

        Node* current = hash_table[i]->head;
        Node* prev = NULL;

        while (current != NULL) {
            if (difftime(current_time, current->data.timestamp) > threshold_ms / 1000.0) {
                if (prev == NULL) {
                    // Remove head
                    hash_table[i]->head = current->next;
                } else {
                    // Remove middle or end
                    prev->next = current->next;
                }
                Node* temp = current;
                current = current->next;
                free_node(temp);
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&locks[i]);
    }
}

void shutdown_system() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Node* current = hash_table[i]->head;
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free_node(temp);
        }
        pthread_mutex_destroy(&locks[i]);
        free(hash_table[i]);
    }
}

int main() {
    initialize_system();
    // Example usage
    RX_UE_INFORMATION_TAG rx_ue_info_tag = {1};
    RNTI rnti = 1234;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag = {0};

    add_or_update_entry(rx_ue_info_tag, rnti, crc_indication_rel8_tag);

    clear_old_entries(5000); // Clear entries older than 5 seconds

    remove_entry(rnti);

    shutdown_system();
    return 0;
}
```

