typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRCList;

void initialize_list(CRCList *list, size_t initial_capacity) {
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void resize_list_if_needed(CRCList *list) {
    if (list->count >= list->capacity && list->capacity < MAX_LIST_SIZE) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_LIST_SIZE) {
            new_capacity = MAX_LIST_SIZE;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_data) {
            list->data = new_data;
            list->capacity = new_capacity;
        } else {
            log_message(LOG_LEVEL_ERROR, "Failed to resize CRCList");
        }
    }
}

void update_crc_flags(CRCList *list, int (*poll_external_source)(int), int default_crc_flag) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (default_crc_flag != -1) { // -1 means no default initialization
            list->data[i].CRCFLAG = default_crc_flag;
        }
        int rnti = list->data[i].RNTI;
        list->data[i].CRCFLAG = poll_external_source(rnti);
    }

    pthread_mutex_unlock(&list->lock);
}

int serialize_list(const CRCList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message(LOG_LEVEL_ERROR, "Failed to open file for serialization.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    size_t written = fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);

