    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message(LOG_LEVEL_ERROR, "Failed to open file for deserialization.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    list->count = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    resize_list_if_needed(list);

    fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);

    pthread_mutex_unlock(&list->lock);

    fclose(file);

    if (ferror(file)) {
        log_message(LOG_LEVEL_ERROR, "Error occurred during deserialization.");
        return -1;
    }

    return 0;
}

void free_list(CRCList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
}

int poll_external_source(int rnti) { // Dummy function for polling CRC flag
    // Replace with actual implementation to get CRCFLAG from external source
    return (rnti % 2 == 0) ? 1 : 0; // Example logic
}

int main() {
