    initialize_list(&crc_list, 10);

    // Update CRC flags with default initialization to a specific value (-1 means no default)
    update_crc_flags(&crc_list, poll_external_source, -1);

    if (serialize_list(&crc_list, "crl_data.bin") == 0) {
        log_message(LOG_LEVEL_INFO, "List serialized successfully.");
    }

    CRCList new_crc_list;
    initialize_list(&new_crc_list, 10);

    if (deserialize_list(&new_crc_list, "crl_data.bin") == 0) {
        log_message(LOG_LEVEL_INFO, "List deserialized successfully.");
    }

    free_list(&crc_list);
    free_list(&new_crc_list);

    return 0;
}
